/* CALR · intl 分卷 th-p01（由 _work/merge/build-packs.js 从 prototype/data/laws/ 自动生成，请勿手工编辑） */
(function (root) {
  'use strict';
  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["TH-H001"] = {"id":"TH-H001","coverage":"full","language":"en","sourceName":"泰国官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":31,"structureMode":"ARTICLE","title":{"zh":"ACT OF ARBITRATION CENTER，B.E. 2550 (2007)","en":"ACT OF ARBITRATION CENTER, B.E. 2550 (2007)","orig":null},"level":"law","status":"active","issuingBody":"泰国官方发布渠道","promulgatedDate":"2007","completenessNote":"自 2026-10-06 全库备份回流（_work/_backup_20261006/data/TH-H001.json）；条文逐字取自该备份，未改写、未补全；原始来源见 source 字段。","country":"TH","countryName":"泰国","layer":"intl","articles":[{"id":"TH-H001-A1","no":1,"noLabel":{"en":"Article 1"},"text":{"en":"This Act shall be called the “The Act of Arbitration Center,  \nB.E. 2550”."}},{"id":"TH-H001-A2","no":2,"noLabel":{"en":"Article 2"},"heading":{"en":"This Act shall come into force as from the day following its"},"text":{"en":"publication in the Government Gazette."}},{"id":"TH-H001-A3","no":3,"noLabel":{"en":"Article 3"},"heading":{"en":"In this Act:"},"text":{"en":"“Center” means the Arbitration Center; \n“Committee” means the Arbitration Center Committee; \n“Committee member” means a member of the Arbitration Center Committee;  \n“Director” means the director of the Arbitration Center; \n“Advisor” means an advisor to the Arbitration Center; “Staff” means a \nmember of staff of the Arbitration Center; “Employee” means an employee of the \nArbitration Center; “Minister” means the Minister in charge of this Act."}},{"id":"TH-H001-A4","no":4,"noLabel":{"en":"Article 4"},"heading":{"en":"The Minister of Justice shall be in charge of this Act"},"text":{"en":"* \nRemark: This Translation is provided by Thailand Arbitration Center as the competent authority for \ninformation purposes only. Whilst Thailand Arbitration Center has made efforts to ensure the accuracy and \ncorrectness of the translation, the original Thai text as formally adopted and published shall in all events \nremain the sole authoritative text having the force of Law. \n \n2 \nChapter 1 \nEstablishment, Objectives, and Authority \n____________"}},{"id":"TH-H001-A5","no":5,"noLabel":{"en":"Article 5"},"text":{"en":"A Center called “The Arbitration Center” shall be established as  \na juristic person."}},{"id":"TH-H001-A6","no":6,"noLabel":{"en":"Article 6"},"heading":{"en":"The headquarters of the Center shall be situated either in"},"text":{"en":"Bangkok or a nearby province."}},{"id":"TH-H001-A7","no":7,"noLabel":{"en":"Article 7"},"heading":{"en":"The Center shall have the following objectives:"},"text":{"en":"(1) to promote and develop procedures on conciliation and arbitration; \n(2) to deal with affairs relating to disputes through conciliation and arbitration; \nand \n( 3 )  to promote and disseminate knowledge concerning conciliation and \narbitration, as well as relevant laws."}},{"id":"TH-H001-A8","no":8,"noLabel":{"en":"Article 8"},"text":{"en":"In order to fulfill the objectives stated in section 7, the Center \nshall have the authority to act as follows: \n(1) to exercise rights to ownership, rights to possession, and real rights; \n(2) to establish rights or to create juristic acts concerning assets located within \nand outside the country; \n(3) to employ or authorize persons to deal with affairs within the scope of the \nCenter’s duties and authority; \n( 4 )  to make loans in order to proceed in the interest of fulfilling the \nobjectives; \n(5 ) to collect fees, dues, remuneration and service charges for the Center’s \nwork; \n(6) to carry out any other duties specified by this Act, or as entrusted by the \nCommittee. \n“Loans” in accordance with (4) shall be in compliance with criteria prescribed by \nthe Cabinet. \n \nChapter 2 \nCapital, Income, and Assets \n____________"}},{"id":"TH-H001-A9","no":9,"noLabel":{"en":"Article 9"},"heading":{"en":"Capital and assets used for the Center’s activities shall be"},"text":{"en":"comprised of: \n \n3 \n(1) monies received from the Government as starting fund; \n(2) general subsidies provided by the Government as appropriate and necessary; \n(3) monies or other assets donated by others; \n(4) fees, dues, remuneration and service charges levied from parties in dispute \nor the Center’s clients; \n( 5 )  income derived from training programs and seminars and from the \ndissemination of knowledge concerning conciliation and arbitration procedures and relevant \nlaws; \n( 6 )  the interests and other benefits derived from the Center’s income, \nincluding that derived from intellectual property."}},{"id":"TH-H001-A10","no":10,"noLabel":{"en":"Article 10"},"text":{"en":"The Center’s income shall not be a remittance to be sent to the  \nMinistry of Finance under the Treasury Reserve Law and the Budgetary Law."}},{"id":"TH-H001-A11","no":11,"noLabel":{"en":"Article 11"},"heading":{"en":"The Center’s property shall not be subject to any civil case"},"text":{"en":"enforcement. \n \nChapter 3 \nManagement and Administration \n____________"}},{"id":"TH-H001-A12","no":12,"noLabel":{"en":"Article 12"},"heading":{"en":"There shall be a Committee called “the Arbitration Center"},"text":{"en":"Committee” comprised of  the Permanent Secretary for Justice, as the chairperson; the \nAttorney General; the Secretary-General of the Office of the Judiciary; the President of the \nThai Chamber of Commerce; the President of the Federation of Thai Industries; the President \nof the Thai Bankers’ Association; the President of the Lawyers’ Council of Thailand; the \nPresident of Council of Engineer; the President of Architect Council of Thailand and five \nqualified members. \nThe Director shall be both a committee member and Secretary-General. \nQualified members, according to paragraph one, shall be appointed from \namong those with knowledge, expertise or experience in the spheres of economics, \ncommerce, industry, law or arbitration, at least three of whom shall be representatives from \nthe private sector."}},{"id":"TH-H001-A13","no":13,"noLabel":{"en":"Article 13"},"heading":{"en":"Each qualified member shall conform to the following"},"text":{"en":"specifications and prohibitions: \n(1) be of Thai nationality; \n \n4 \n(2) be not less than thirty-five years of age and not more than seventy years \nof age; \n(3) not be a bankrupt, an incompetent or quasi-incompetent person; \n(4) never have been sentenced to imprisonment by a final judgment, except \nfor an offence committed through negligence or a petty case; and \n(5 ) not be a holder of a political office; a member of a local assembly or  \na local administrator; a committee member or holder of other managerial position in  \na political party; an advisor or officer of a political party."}},{"id":"TH-H001-A14","no":14,"noLabel":{"en":"Article 14"},"text":{"en":"A qualified member shall hold a position for a four-year term. \nUpon vacating a position, the committee member may be re-appointed. \nPrior to the appointment of a new qualified member, the outgoing \ncommittee member shall remain in office until the appointment has been made."}},{"id":"TH-H001-A15","no":15,"noLabel":{"en":"Article 15"},"heading":{"en":"Other than retirement on the expiration of the term as under"},"text":{"en":"section 14, a qualified member shall be discharged from their position upon: \n(1) death; \n(2) resignation; \n(3) being dismissed by the Cabinet due to failure or inability to perform their \nduties or behaving in an unseemly manner; and \n(4) being unqualified or falling under any of the prohibitions as prescribed in \nsection 13"}},{"id":"TH-H001-A16","no":16,"noLabel":{"en":"Article 16"},"text":{"en":"On the dismissal of a qualified member prior to the expiration of \ntheir term, the Cabinet shall appoint another person to fill the position and such qualified \nmember thus appointed to fill a vacant position shall remain in office for the remaining term \nof the dismissed member."}},{"id":"TH-H001-A17","no":17,"noLabel":{"en":"Article 17"},"heading":{"en":"To be a quorum, a meeting of the Committee shall consist of"},"text":{"en":"no less than one-half of the total number of committee members. \nAt a meeting of the Committee, if the chairperson does not attend or is \nunable to perform duties, the committee members present shall select one among them to \nact as the chairperson of the meeting. \nDecisions shall be made by majority votes, with each committee member \nhaving one vote. In the case of an equal number of votes, the chairperson shall have an \nadditional casting vote. \n \n \n5"}},{"id":"TH-H001-A18","no":18,"noLabel":{"en":"Article 18"},"heading":{"en":"The Committee shall oversee the performance of the Center"},"text":{"en":"and have, in particular, the following authority and duties: \n(1) to determine the administrative policy of the Center; \n( 2 )  to issue measures, principles and conditions concerning income and \nexpenditure; \n(3) to approve the Center’s financial plan and annual budget; \n(4) to determine the size of the workforce, the period of employment, salary \nscales, wages and remuneration of staff and employees; \n(5) to issue rules for conciliation and arbitration procedures; \n(6) to issue rules for the morals, ethics and conduct of arbitrators in order to \nestablish their neutrality and independence; \n(7) to issue rules or regulations for the supervision of working practices and \ngeneral administration of the Center as follows: \n(a) general administration of the Center, the organization of divisions and \nthe scope of their authority; \n(b) staff recruitment and human resource management of the Center; \n(c) the recruitment, election, appointment, and dismissal of the Director, \nthe Director’s working practices, and the authorization of a person to act in their stead; \n(d) to provide welfare and other benefits for staff and employees; \n(e) to fix the fees, dues, remunerations, service charges and income of the \nCenter in accordance with section 9 (4) and (5); and \n(f) to administer and manage the finances, procurement and assets of the \nCenter, including accounting and the writing off of assets from the accounts, such writing off \nof asset shall be complied with principles fixed by the Cabinet. \n(8) to perform any act as necessary or that in continuation with the previous \nact, in order to achieve the objectives. \nRules and regulations in accordance with (5) (6) and (7) shall come into \nforced following their publication in the Government Gazette."}},{"id":"TH-H001-A19","no":19,"noLabel":{"en":"Article 19"},"heading":{"en":"The Committee shall have the authority to appoint"},"text":{"en":"knowledgeable persons with expertise  as advisors, and to appoint sub-committees to \nconsider or implement affairs as entrusted by the Committee. \nThe provisions of section 17 shall be applied mutatis mutandis to the \nconvening of a sub-committee."}},{"id":"TH-H001-A20","no":20,"noLabel":{"en":"Article 20"},"heading":{"en":"The chairperson of the Committee, committee members,"},"text":{"en":"advisors, and sub-committee members shall be paid a meeting allowance and remuneration \nas prescribed by the Cabinet. \n \n6"}},{"id":"TH-H001-A21","no":21,"noLabel":{"en":"Article 21"},"text":{"en":"The Center shall have a Director to administrate the Center’s  \nundertakings under the supervision of the Committee. \nThe Committee shall appoint a suitable person to be Director, who is able to \nwork for the Center full-time and with knowledge and expertise beneficial to the Center."}},{"id":"TH-H001-A22","no":22,"noLabel":{"en":"Article 22"},"text":{"en":"The Director shall conform to the following qualifications and \nprohibitions: \n(1) be of Thai nationality; \n(2) be not less than thirty-five years of age, and not more than sixty-five \nyears of age; \n(3) have knowledge, expertise or experience appropriate for the work of the \nCenter; \n(4) not fall under any of the prohibitions as prescribed in section 13 (3) (4) or (5)."}},{"id":"TH-H001-A23","no":23,"noLabel":{"en":"Article 23"},"text":{"en":"The Director shall hold the position for a four-year term and, \nupon vacating the position, may be re-appointed for a maximum of two consecutive terms."}},{"id":"TH-H001-A24","no":24,"noLabel":{"en":"Article 24"},"heading":{"en":"Other than retirement on the expiration of the term, the"},"text":{"en":"Director shall be dismissed from the position upon: \n(1) death; \n(2) resignation; \n(3) being dismissed by the Cabinet due to failure or inability to perform their \nduties or behaving in an unseemly manner; and \n(4) being unqualified or falling under any of the prohibitions as prescribed in \nsection 22. \nThe Committee’s decision to dismiss the Director in accordance with (3) shall \nbe made by the votes of at least two-thirds of the committee members present, excluding \nthe Director’s."}},{"id":"TH-H001-A25","no":25,"noLabel":{"en":"Article 25"},"heading":{"en":"The Director shall have the following duties and authority:"},"text":{"en":"(1) to manage the Center in accordance with legislation, rules, regulations and \nthe Committee’s decisions; \n(2) to supervise the Center’s staff and employees; \n(3) to recruit, appoint, promote, demote, reduce salary or wages, discipline, \nand dismiss staff and employees of the Center in compliance with rules determined by the \nCommittee; and \n \n7 \n(4) to issue regulations concerning the Center’s administration which are not \nin conflict with or obstructive to the rules, regulations and the Committee’s decisions."}},{"id":"TH-H001-A26","no":26,"noLabel":{"en":"Article 26"},"text":{"en":"In matters relating to the third person, the Director shall be the \nrepresentative of the Center, and in such matters, the Director could authorize a person to \nany perform specific procedure which is in compliance with the rules determined by the \nCommittee."}},{"id":"TH-H001-A27","no":27,"noLabel":{"en":"Article 27"},"heading":{"en":"The Committee shall determine the salary scale and other"},"text":{"en":"benefits for the Director as prescribed by the Cabinet. \n \nChapter 4 \nAccounting and Auditing \n____________"}},{"id":"TH-H001-A28","no":28,"noLabel":{"en":"Article 28"},"heading":{"en":"The Center shall prepare the accounts in accordance with"},"text":{"en":"international accounting  standards and the criteria set out by the Committee, and, in \naddition, hold internal financial, accounting and procurement audits and report to the \nCommittee at least annually."}},{"id":"TH-H001-A29","no":29,"noLabel":{"en":"Article 29"},"text":{"en":"The Center shall prepare balance sheets, financial statements, \nand operational accounts to be submitted to the auditor within 90 days of every the end of \naccounting period and submit a copy of financial statements to the Comptroller General’s \nDepartment for use in the preparation of National Monetary Budget. \nThe Office of the Auditor General of Thailand, or an outsider appointed by \nthe Committee with the approval of the Office of the Auditor General of Thailand, shall act \nas the auditor and submit the auditing reports to the Committee annually. \nIn order to carry out such matter, the auditor shall have the right to examine \nall books and accounts and any other Center documents; investigate the Director, the \ninternal audit, staff, employees or other individuals; and request the submission of \nadditional books and accounts and other Center documents as necessary. \n \nChapter 5 \nSupervision \n____________"}},{"id":"TH-H001-A30","no":30,"noLabel":{"en":"Article 30"},"text":{"en":"The Director shall propose draft rules or regulations as stated in \nsection 18 (5) (6)  and (7) to the Minister without delay. The Minister may veto such draft \nrules or regulations, clearly stating the reason for so doing. If the veto has not been made \n \n8 \nwithin a period of thirty days since the date of receiving the draft from the Director, such \ndraft could be proceeded and published in the Government Gazette."}},{"id":"TH-H001-A31","no":31,"noLabel":{"en":"Article 31"},"heading":{"en":"Where the Minister vetoes a draft rule or regulation, the"},"text":{"en":"Committee shall reconsider  such draft along with the reason provided by the Minister. If at \nleast two-thirds of the committee members present at the meeting vote to confirm the \ndraft, it could be proceeded and published in the Government Gazette. \n \n \nCountersigned by \nGeneral Surayud Chulanont \nPrime Minister \n \n9 \nNote:- The rationale for the promulgation of the Act of Arbitration Center is to promote \ndispute resolution  through arbitration for parties in dispute to resolve their civil and \ncommercial disputes as a resort to court proceeding: this will also assist reduce the case \nload in the courts. There should be an independent agency with a highly flexible \nadministrative system together with knowledgeable personnel equipped with expertise in \nconducting dispute resolution through the use of arbitral methods. Such personnel shall \nhave the duty of promoting and developing dispute resolution and arbitration as well as \nimplementing dispute resolution through arbitration. It is, therefore, deemed necessary to \npromulgate this Act."}}],"pack":"th-p01"};
  FT["TH-H003"] = {"id":"TH-H003","coverage":"full","language":"en","sourceName":"泰国官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":83,"structureMode":"ARTICLE","title":{"zh":"CYBER SECURITY MAINTENANCE ACT，B.E. 2562 (2019)","en":"CYBER SECURITY MAINTENANCE ACT, B.E. 2562 (2019)","orig":null},"level":"law","status":"active","issuingBody":"泰国官方发布渠道","promulgatedDate":"2019","completenessNote":"自 2026-10-06 全库备份回流（_work/_backup_20261006/data/TH-H003.json）；条文逐字取自该备份，未改写、未补全；原始来源见 source 字段。","country":"TH","countryName":"泰国","layer":"intl","articles":[{"id":"TH-H003-A1","no":1,"noLabel":{"en":"Article 1"},"text":{"en":"This Act is called the “Cyber Security Maintenance Act, B.E. 2562 \n(2019)”."}},{"id":"TH-H003-A2","no":2,"noLabel":{"en":"Article 2"},"text":{"en":"1  This Act shall come into force as from the day following the date of \nits publication in the Government Gazette."}},{"id":"TH-H003-A3","no":3,"noLabel":{"en":"Article 3"},"heading":{"en":"In this Act:"},"text":{"en":"“cyber security maintenance” means measures or operations established for \npreventing, handling and reducing risks of internal and external cyber threats affecting national \nsecurity, economic security, military security and internal peace and order; \n  “cyber threat” means any unlawful act or operation which is performed by the \nuse of a computer or a computer system or an undesirable programme with an intent to cause \nan act of violence against a computer system, computer data or other relevant data and which \nis an imminent danger causing damage to or affecting the functionality of a computer, a \ncomputer system or other relevant data; \n  “cyber” includes data and communications resulting from the provision of \nservices, or the application of, a computer network, an internet system or a telecommunication \nnetwork and also the regular provision of satellite services and similar networks of general \nconnectivity; \n  “State agency” means central administration, provincial administration, local \nadministration, a State enterprise, a legislative organ, a judicial organ, an independent organ, a \npublic organisation and any other agency of the State; \n  “code of practice” means rules or directions prescribed by the Cyber Security \nSupervisory Committee; \n  “cyber security incident” means an incident resulting from any unlawful action \nor operation which is performed via a computer or a computer system and is likely to cause \ndamage to or affect the cyber security maintenance or the cyber security of a computer, \ncomputer data, a computer system or other data relating to a computer system; \n                                                        \n 1 Published in Government Gazette, Vol. 136, Part 69a, dated 27 th  May 2019. \n3 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  “resolution measures for the cyber security maintenance” means the resolution \nof cyber security problems by the deployment of personnel, procedures and technology via a \ncomputer, a computer system, a computer programme or a service relating to any computer \nwith a view to creating confidence in and strengthening the cyber security of a computer, \ncomputer data, a computer system or other data relating to a computer system; \n  “critical information infrastructure” means a computer or computer system \nwhich is used by a State agency or a private agency in its affairs in connection with the \nmaintenance of national security, public safety, national economic security or infrastructure of \npublic interests; \n  “critical information infrastructure agency” means a State agency or private \nagency  which assumes missions or provides services in relation to  critical information \ninfrastructure ; \n  “regulatory or supervisory agency” means a State agency, private agency or \nperson that is designated by law to have duties and powers to regulate or supervise the \noperation of affairs of State agencies or critical information infrastructure agencies; \n  “Committee” means the National Cyber Security Committee; \n  “competent official” means the person appointed by the Minister for performing \nactivities under this Act; \n  Secretary-General” means the Secretary-General of the National Cyber Security \nCommittee; \n  “Office” means the Office of the National Cyber Security Committee; \n  “Minister” means the Minister having charge and control of the execution of this Act."}},{"id":"TH-H003-A4","no":4,"noLabel":{"en":"Article 4"},"text":{"en":"The Prime Minister shall have charge and control of the execution of \nthis Act and shall have the powers to issue Notifications and appoint competent officials in the \nexecution of this Act. \n  Such Notifications shall come into force upon their publication in the \nGovernment Gazette. \n \n4 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nCHAPTER I \nCOMMITTEES \n______________ \nPART I \nNATIONAL CYBER SECURITY COMMITTEE \n______________"}},{"id":"TH-H003-A5","no":5,"noLabel":{"en":"Article 5"},"text":{"en":"There shall be a committee called the “National Cyber Security \nCommittee” called “NCSC” in brief and called in the English language as the “National Cyber \nSecurity Committee” as abbreviated as “NCSC”, consisting of: \n  (1) the Prime Minister as Chairperson; \n  (2) ex officio  members, viz, the Minister of Defence, Minister of Digital Economy \nand Society, Permanent Secretary for Finance, Permanent Secretary for Justice, Commissioner-\nGeneral of the Royal Thai Police and Secretary-General of the National Security Council;  \n  (3) not more than seven qualified members appointed by the Council of \nMinisters from persons possessing apparent knowledge, expertise and experience in the cyber \nsecurity maintenance, information and communication technology, personal data protection, \nscience, engineering, law, finance or other areas relevant and beneficial to the cyber security \nmaintenance. \n  The Secretary-General shall be a member and secretary and the Secretary-\nGeneral shall appoint not more than two officials of the Office as assistant secretaries. \n  The rules and procedures for the selection of persons to be nominated to the \nCouncil of Ministers for being appointed as qualified members and the selection of qualified \nmembers to replace those who vacate office before the expiration of the term under section 7 \nparagraph two shall be in accordance with the Rule prescribed by the Council of Ministers upon \nrecommendation by the Committee."}},{"id":"TH-H003-A6","no":6,"noLabel":{"en":"Article 6"},"text":{"en":"A qualified member of the Committee shall be of Thai nationality \nand shall not be under the prohibitions as follows: \n  (1) being a bankrupt or having previously been a dishonest bankrupt; \n5 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (2) being an incompetent person or a quasi -incompetent person; \n  (3) having been sentenced to imprisonment by a final judgment of the Court, \nwhether having been actually imprisoned or not, except for an offence committed through \nnegligence or a petty offence; \n  (4) having previously been expelled or dismissed from or ordered to leave the \nGovernment service or an agency of his service by reason of any corruption in office or grave \nmisconduct; \n  (5) having previously been removed from office established by law; \n  (6) being a holder of a political position, a member of a local assembly or a local \nadministrator, an executive member or holder of a position responsible for the administration of \na political party, an adviser to a political party or an official of a political party."}},{"id":"TH-H003-A7","no":7,"noLabel":{"en":"Article 7"},"text":{"en":"A qualified member of the Committee shall hold office for a term of \nfour years and may be re-appointed but may not serve for more than two consecutive terms. \n  In the case of an appointment of a qualified member as an additional one or as \nthe one in replacement of a qualified member who vacates office before the expiration of the \nterm, the person so appointed as an additional or replacing qualified member shall hold office \nfor the remaining tern of the qualified members already appointed, except that in the case \nwhere there remain less than ninety days in the term of office the appointment of a replacing \nqualified member may be omitted. \n  At the expiration of the term under paragraph one, if new qualified members \nhave not yet been appointed, the qualified members who vacate office at the expiration of \nsuch term shall remain in office for continuance of performance until new qualified members \nare appointed."}},{"id":"TH-H003-A8","no":8,"noLabel":{"en":"Article 8"},"text":{"en":"In addition to the vacation of office upon the expiration of the term \nunder section 7, a qualified member vacates office upon: \n  (1) death; \n  (2) resignation; \n  (3) being removed by the Council of Ministers; \n6 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (4) being disqualified or being under any prohibition under section 6."}},{"id":"TH-H003-A9","no":9,"noLabel":{"en":"Article 9"},"heading":{"en":"The Committee has the duties and powers as follows:"},"text":{"en":"(1) to submit to the Council of Ministers, for approval, the policy and plan on the \ncyber security maintenance as well as the promotion and support of operations for the cyber \nsecurity maintenance under section 42 and section 43, along the line of the directions laid \ndown under section 42;  \n  (2) to lay down the policy on the management in connection with the cyber \nsecurity maintenance for State agencies and critical information infrastructure agencies; \n  (3) to prepare, for submission to the Council of Ministers, an action plan on the \ncyber security maintenance which shall serve as a master plan on the cyber security \nmaintenance in a normal situation and in a situation where a cyber threat might occur or has \noccurred, provided that such plan shall be in line with national policies, strategies and plans as \nwell as the framework policies and masterplans in connection with the security maintenance \nprepared by the National Security Council; \n  (4) to prescribe standards and directions for promoting and developing systems \nfor the provision of services in connection with the cyber security maintenance, establish \nstandards in connection with the cyber security maintenance and prescribe minimum standards \nrelating to computers, computer systems and computer programmes and also promote \naccreditation of cyber security maintenance standards for critical information infrastructure \nagencies, State agencies, regulatory or supervisory agencies and private agencies; \n  (5) to prescribe measures and directions for elevating skills, knowledge and \nexpertise, in the cyber security maintenance, of competent officials or officials of critical \ninformation infrastructure agencies, State agencies, regulatory or supervisory agencies and \nprivate agencies which are involved in the cyber security maintenance; \n  (6) to set a framework for co-ordinating co-operation with other domestic and \nforeign agencies which are involved in the cyber security maintenance; \n  (7) to appoint and remove the Secretary-General; \n  (8) to entrust the regulation and supervision to regulatory or supervisory \nagencies, State agencies or critical information infrastructure agencies and also lay down for \n7 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nthem requirements, objects, duties and powers and a framework for the operations in the cyber \nsecurity maintenance; \n  (9) to monitor and assess the implementation of the policy and plan on the \ncyber security maintenance, action plan on the cyber security maintenance and operations for \nthe cyber security maintenance as provided in this Act; \n  (10) to make recommendations and give advice, to the National Commission on \nDigitality for Economy and Society or the Council of Ministers, on matters in connection with the \ncyber security maintenance; \n  (11) to recommend to the Council of Ministers the enactment or revision of laws \nrelating to the cyber security maintenance; \n  (12) to prepare a report providing a summary of operations involving the cyber \nsecurity maintenance producing significant impacts or directions for developing cyber security \nmaintenance standards, for submission to the Council of Ministers for information; \n  (13) to perform any other activities as provided in this Act or as entrusted by the \nCouncil of Ministers."}},{"id":"TH-H003-A10","no":10,"noLabel":{"en":"Article 10"},"text":{"en":"Meetings of the Committee shall be in accordance with the Rule \nprescribed by the Committee. In this regard, meetings may be held by an electronic means or \nany other means."}},{"id":"TH-H003-A11","no":11,"noLabel":{"en":"Article 11"},"heading":{"en":"The Chairperson and members of the Committee shall receive"},"text":{"en":"meeting allowances or other remuneration in accordance with the rules prescribed by the \nCouncil of Ministers. \nPART II \nCYBER SECURITY SUPERVISORY COMMITTEE \n______________"}},{"id":"TH-H003-A12","no":12,"noLabel":{"en":"Article 12"},"heading":{"en":"In the execution of duties and powers of the Committee under"},"text":{"en":"section 9, there shall be the Cyber Security Supervisory Committee called “CSSC” in brief, \nconsisting of: \n  (1) the Minister of Digital Economy and Society as Chairperson; \n8 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (2) ex officio  members, viz, the Permanent Secretary for Foreign Affairs, \nPermanent Secretary for Transport, Permanent Secretary for Digital Economy and Society, \nPermanent Secretary for Energy, Permanent Secretary for Interior, Permanent Secretary for \nPublic Health, Commissioner-General of the Royal Thai Police, Supreme Commander-in-Chief, \nSecretary-General of the National Security Council, Director of the National Intelligence Agency, \nGovernor of the Bank of Thailand, Secretary-General of the Office of the Securities and Exchange \nCommission and Secretary-General of the National Broadcasting and Telecommunications \nCommission; \n  (3) not more than four qualified members appointed by the Committee from \npersons possessing apparent knowledge, expertise and experience beneficial to the cyber \nsecurity maintenance. \n  The Secretary-General shall be a member and secretary and the Secretary-\nGeneral shall appoint not more than two officials of the Office as assistant secretaries. \n  The rules and procedures for the selection of persons deemed appropriate for \nbeing appointed as qualified members shall be in accordance with the Rule prescribed by the \nCommittee."}},{"id":"TH-H003-A13","no":13,"noLabel":{"en":"Article 13"},"heading":{"en":"The CSSC has the duties and powers as follows:"},"text":{"en":"(1) to monitor operations in the implementation of the policy and plan under \nsection 9 (1) and section 42; \n  (2) to oversee and take action for handling critical cyber threats under section 61, \nsection 62, section 63, section 64, section 65 and section 66; \n  (3) to supervise the operation of the National Centre for Co-ordination of the \nComputer System Security Maintenance and the incident action as well as computer forensic \nscience; \n  (4) to prescribe a code of practice and a framework standard for the cyber \nsecurity maintenance, thereby constituting minimum requirements for cyber security \nmaintenance operations to be observed by State agencies and critical information infrastructure \nagencies and also lay down measures for assessing risks and reacting to as well as handling \ncyber threats upon their occurrence or upon incidents affecting or possibly affecting or causing \n9 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nsignificant or serious  damage to information systems of the country, with a view to facilitating \nfast, efficient and uniform operations in conducting the cyber security maintenance; \n  (5) to determine duties of critical information infrastructure agencies and duties \nof regulator or supervisory agencies, provided that regulator or supervisory agencies shall at \nleast be required to have the duty to set appropriate standards for handling cyber threats of \neach critical information infrastructure agency and State agency; \n  (6) to determine levels of cyber threats as well as details of measures for \npreventing, handling, assessing, suppressing and terminating cyber threats of each level, for \nsubmission to the Committee; \n  (7) to analyse situations and assess impacts of cyber threats for submission to the \nCommittee for consideration and giving directions when a cyber threat of a more severe level \noccurs or is expected to occur. \n  In prescribing the framework standard under paragraph one (4), regard shall be \nhad to risk management principles, as to which the following methods and measures shall at \nleast be an integral part thereof: \n  (1) the indication of possible risks to computers, computer data, computer \nsystems, other data relating to computer systems and property, lives and physical conditions of \npersons; \n  (2) measures for preventing possible risks; \n  (3) measures for inspection and surveillance of cyber threats; \n  (4) incident action measures upon discovery of cyber threats; \n  (5) measures for remedying, and carrying out rehabilitation from, damage \nresulting from cyber threats."}},{"id":"TH-H003-A14","no":14,"noLabel":{"en":"Article 14"},"text":{"en":"In carrying out activities under section 13 paragraph one (2) in the \ninterest of the timely handling of cyber threats, the CSSC may delegate its power to the Minister \nof Digital Economy and Society, Supreme Commander-in-Chief and other members designated \nby the CSSC for carrying out operations in such matters jointly and may also require regulatory \nor supervisory agencies and critical information infrastructure agencies that are under attack to \njoin operations, co-ordination and support. \n10 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  The performance under paragraph one shall be in accordance with the Rule \nprescribed by the CSSC."}},{"id":"TH-H003-A15","no":15,"noLabel":{"en":"Article 15"},"text":{"en":"The provisions of section 6, section 7 and section 8 shall apply to \nqualified members of the CSSC mutatis mutandis ."}},{"id":"TH-H003-A16","no":16,"noLabel":{"en":"Article 16"},"heading":{"en":"The CSSC shall have the power to appoint sub-committees for"},"text":{"en":"performing any particular activities as entrusted by the CSSC."}},{"id":"TH-H003-A17","no":17,"noLabel":{"en":"Article 17"},"text":{"en":"Meetings of the CSSC and sub-committees shall be in accordance \nwith the Rule prescribed by the CSSC. In this regard, meetings may be held by an electronic \nmeans or any other means."}},{"id":"TH-H003-A18","no":18,"noLabel":{"en":"Article 18"},"text":{"en":"The Chairperson and members, the chairperson of a sub-committee \nand members of a sub-committee appointed by the CSSC shall receive meeting allowances or \nother remuneration in accordance with the rules prescribed by the Council of Ministers."}},{"id":"TH-H003-A19","no":19,"noLabel":{"en":"Article 19"},"text":{"en":"In the performance of duties under this Act, competent officials \nshall show identification cards to persons concerned. \n  In appointing competent officials, the Minister shall appoint persons possessing \nknowledge and expertise in the cyber security maintenance as competent officials for \nperforming any particular activities under this Act. In this regard, levels of knowledge and \nexpertise in the cyber security maintenance of competent officials shall be as prescribed in the \nNotification of the Committee. \n  Identification cards of competent officials shall be in accordance with the form \nprescribed in the Notification of the CSSC. \nCHAPTER II \nOFFICE OF THE NATIONAL CYBER SECURITY COMMITTEE \n______________"}},{"id":"TH-H003-A20","no":20,"noLabel":{"en":"Article 20"},"text":{"en":"There shall be the Office of the National Cyber Security Committee \nas a State agency which is ascribed the status of a juristic person and is neither a Government \n11 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nagency under the law on the administrative organisation of State affairs nor a State enterprise \nunder the law on budgetary procedures or other laws."}},{"id":"TH-H003-A21","no":21,"noLabel":{"en":"Article 21"},"text":{"en":"Affairs of the Office is not subject to the law on labour protection, \nthe law on labour relations, the law on social security and the law on compensation but \nofficials and employees of the Office shall receive not lower remunerative benefits than those \nprovided in the law on labour protection, the law on social security and the law on \ncompensation."}},{"id":"TH-H003-A22","no":22,"noLabel":{"en":"Article 22"},"text":{"en":"The Office shall be responsible for clerical work, technical work, \nmeeting work and secretarial work of the Committee and the CSSC and shall also have the \nduties and powers as follows: \n  (1) to make recommendations and lend support to the Committee in relation to \nthe preparation of the policy and plan on the cyber security maintenance and the action plan \non the cyber security maintenance under section 9; \n  (2) to prepare the code of conduct and framework standard for the cyber \nsecurity maintenance under section 13 paragraph one (4) for submission to the CSSC for \napproval; \n  (3) to co-ordinate operations on the cyber security maintenance  of critical \ninformation infrastructure agencies under section 53 and section 54; \n  (4) to undertake co-ordination and provide co-operation in regard to the \nestablishment of centres for co-ordination of the computer system security maintenance \ndomestically and overseas in relation cyber security incidents and lay down resolution \nmeasures for the cyber security maintenance; \n  (5) to take action and co-ordinate with State and private agencies in reacting to \nand handling cyber threats as entrusted by the Committee; \n  (6) to conduct surveillance of cyber threat risks, follow, analyse and process data \non cyber threats and also give warnings of cyber threats; \n  (7) to work and co-ordinate with, and lend support as well as provide assistance \nto, agencies concerned in connection with the implementation of the policy and plan on the \ncyber security maintenance, the action plan on the cyber security maintenance and measures \n12 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nfor preventing, handling and reducing cyber threat risks or in accordance with orders of the \nCommittee; \n  (8) to take action and provide co-operation or assistance in regard to the \nprevention, handling and reduction of cyber threat risks, in particular, cyber threats affecting or \noccurring to critical information infrastructure; \n  (9) to strengthen knowledge and understanding in relation to the cyber security \nmaintenance and create common awareness of cyber threat situations, with a view to putting \nforth integrated and up-to-date operational actions; \n  (10) to serve as a focal point for gathering and analysing information on the cyber \nsecurity maintenance of the country and also disseminate information relating to risks and \nincidents involving the cyber security maintenance to State agencies and private agencies; \n  (11) to serve as a focal point for co-ordinating co-operation amongst agencies \nwhich are concerned in the cyber security maintenance of domestic and foreign State agencies \nand private agencies; \n  (12) to enter into agreements and co-operation with domestic and foreign \norganisations or agencies in affairs concerning operations in pursuit of duties and powers of the \nOffice upon approval by the Committee; \n  (13) to study and research into information necessary for the cyber security \nmaintenance with a view to making recommendations on cyber security maintenance measures \nand provide regular training and practice on cyber threat handling to agencies concerned;  \n  (14) to promote, support and take action in the dissemination of knowledge on \nthe cyber security maintenance and also provide training for elevating skills and expertise in the \nperformance of duties in connection with the cyber security maintenance; \n  (15) to report progress and situations in connection with the execution of this Act \nand also problems and obstacles to the Committee for consideration and action, in accordance \nwith periods of time as specified by the Committee; \n  (16) to perform any other activities in connection with the cyber security \nmaintenance of the country, as entrusted by the Committee or the Council of Ministers. \n13 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  For the purpose of taking action in pursuit of the duties and powers under (6), \nthe Office shall establish the National Centre for Co-ordination of the Computer System Security \nMaintenance as its internal body, with the duties and powers as prescribed by the Committee."}},{"id":"TH-H003-A23","no":23,"noLabel":{"en":"Article 23"},"text":{"en":"In carrying out activities of the Office, the Office shall also have \ngeneral duties and powers as follows in addition to the duties and powers as provided under \nsection 22: \n  (1) to hold ownership, possessory rights and real rights; \n  (2) to establish rights or enter into juristic acts of all types with proprietary \nbinding effects and also enter into any other juristic act for the purpose of the operation of \naffairs of the Office; \n  (3) to provide and grant funding for supporting the operation of affairs of the \nOffice; \n  (4) to collect fees, contribution fees, remuneration or service charges for the \noperation of affairs, in accordance with the rules and rates prescribed by the Office with the \napproval of the EBO; \n  (5) to perform any other activities provided by law to be the duties and powers \nof the Office or as entrusted by the Committee or the EBO."}},{"id":"TH-H003-A24","no":24,"noLabel":{"en":"Article 24"},"text":{"en":"The fund and property for the operation of affairs of the Office consist of: \n  (1) the inaugural fund allocated by the Government under section 81 paragraph \none and the money as well as property transferred under section 82; \n  (2) the general subsidy annually allocated by the Government as appropriate; \n  (3) contributions from domestic and foreign State agencies or intergovernmental \norganisations; \n  (4) fees, contribution fees, remuneration, service charges or incomes resulting \nfrom the operation of affairs in pursuit of the duties and powers of the Office; \n  (5) fruits of the money or incomes from property of the Office. \n  The money and property of the Office under paragraph one shall be remitted as \nState revenues. \n14 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A25","no":25,"noLabel":{"en":"Article 25"},"text":{"en":"There shall be, for the purpose of supervising general administration \nof the Office, the Executive Board of the Office of the National Cyber Security Committee called \n“EBO” in brief consisting of the Minister of Digital Economy and Society as Chairperson, \nPermanent Secretary for Digital Economy and Society, Comptroller-General, Secretary-General of \nthe Civil Service Commission, Secretary-General of the Office of the Public Sector Development \nCommission and not more than six qualified members, as members. \n  The Secretary-General shall be a member and secretary and the Secretary-\nGeneral shall appoint not more than two officials of the Office as assistant secretaries. \n  Qualified members under paragraph one shall be appointed by the Minister from \npersons possessing apparent knowledge, expertise and ability in the areas of cyber security \nmaintenance, information and communication technology, economics, social sciences, law, \nbusiness administration or other areas relevant and beneficial to the operation of work of the \nEBO, in accordance with the rules and procedures prescribed by the Committee. \n  The provisions of section 6 and section 8 shall apply to qualified members \nmutatis mutandis ."}},{"id":"TH-H003-A26","no":26,"noLabel":{"en":"Article 26"},"text":{"en":"A qualified member of the EBO shall hold office for a term of four \nyears. \n  In the case of an appointment of a qualified member as an additional one or as \nthe one in replacement of a qualified member who vacates office before the expiration of the \nterm, the Minister may appoint an additional or replacing qualified member and the person so \nappointed as an additional or replacing qualified member shall hold office for the remaining \ntern of the qualified members already appointed. \n  At the expiration of the term under paragraph one, if new qualified members \nhave not yet been appointed, the qualified members who vacate office at the expiration of \nsuch term shall remain in office for continuance of performance until new qualified members \nare appointed."}},{"id":"TH-H003-A27","no":27,"noLabel":{"en":"Article 27"},"heading":{"en":"The EBO shall have the duties and powers as follows:"},"text":{"en":"(1) to set the administration policy and approve action plans of the Office; \n15 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (2) to make regulations on institutional organisation, finance, personnel \nadministration, general administration, procurement, internal auditing and also aids and welfare \nof the Office; \n  (3) to approve the expenditure plan and annual appropriation of the Office; \n  (4) to supervise the administration and operation of affairs of the Office and the \nSecretary-General to ensure conformity with this Act and other relevant laws; \n  (5) to decide administrative orders of the Secretary-General insofar as they are \nconcerned with the administration of affairs of the Office; \n  (6) to assess the operation of affairs of the Office and the performance of the \nSecretary-General; \n  (7) to perform other duties as provided by this Act or other laws to be the duties \nand powers of the EBO or as entrusted by the Committee or the Council of Ministers. \n  In the performance of affairs under paragraph one, the EBO may appoint a sub-\ncommittee for considering, recommending or taking any particular act as entrusted by the EBO. \nIn this regard, the performance of work and meetings shall be in accordance with the rules and \nprocedures prescribed by the EBO. \n  The EBO may appoint qualified persons who possess expertise in areas beneficial \nto the operation of work of the Office as advisers to the EBO, in accordance with the rules and \nprocedures prescribed by the Committee."}},{"id":"TH-H003-A28","no":28,"noLabel":{"en":"Article 28"},"text":{"en":"The chairperson and members and the chairperson and members of \na sub-committee appointed by the EBO shall receive meeting allowances and other \nremuneration in accordance with the rules prescribed by the Committee."}},{"id":"TH-H003-A29","no":29,"noLabel":{"en":"Article 29"},"text":{"en":"The Office shall have a Secretary-General, who shall be responsible \nfor the performance of work of the Office and become the superior of officials and employees \nof the Office."}},{"id":"TH-H003-A30","no":30,"noLabel":{"en":"Article 30"},"text":{"en":"The Secretary-General shall have the qualifications as follows: \n  (1) being of Thai nationality; \n  (2) being not lower than thirty-five years of age but not over sixty years of age; \n16 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (3) being a person possessing knowledge, ability and experience in the area \nrelating to missions of the Office and the administration."}},{"id":"TH-H003-A31","no":31,"noLabel":{"en":"Article 31"},"text":{"en":"A person of any of the following descriptions shall be prohibited \nfrom being the Secretary-General: \n  (1) being a bankrupt or having previously been a dishonest bankrupt; \n  (2) being an incompetent person or a quasi -incompetent person; \n  (3) having been sentenced to imprisonment by a final judgment, whether having \nbeen actually imprisoned or not, except for an offence committed through negligence or a \npetty offence \n  (4) being a Government official, official or employee of a Government agency or \na State enterprise or any other agency of the State or of a local administration; \n  (5) being or having previously been a political official, a holder of a political \nposition, a member of a local assembly or a local administrator, except where not less than \none year has elapsed since the vacation of office; \n  (6) being or having previously been an executive member of, or holder of any \nother position in, a political party or an official of a political party, except where not less than \none year has elapsed since the vacation of office; \n  (7) having previously been expelled or dismissed from or ordered to leave the \nGovernment service or an agency of his service by reason of corruption in office or grave \nmisconduct or having previously been removed from office; \n  (8) having previously been removed by reason of failing the performance \nassessment under section 35 (5)."}},{"id":"TH-H003-A32","no":32,"noLabel":{"en":"Article 32"},"text":{"en":"The Committee shall determine the rate of a monthly salary and \nother remuneration of the Secretary-General in accordance with the rules prescribed by the \nCouncil of Ministers."}},{"id":"TH-H003-A33","no":33,"noLabel":{"en":"Article 33"},"text":{"en":"The Secretary-General shall hold office for a term of four years. \n  The Secretary-General who vacates office at the expiration of the term may be \nre-appointed but may not serve for more than two terms. \n17 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A34","no":34,"noLabel":{"en":"Article 34"},"text":{"en":"In each year, the performance of the Secretary-General shall be \nassessed, in accordance with periods of time and procedures prescribed by the Committee."}},{"id":"TH-H003-A35","no":35,"noLabel":{"en":"Article 35"},"text":{"en":"In addition to the vacation of office upon the expiration of the \nterm, the Secretary-General vacates office upon: \n  (1) death; \n  (2) resignation; \n  (3) being disqualified under section 30 or being under any prohibition under section \n31; \n  (4) being removed upon a resolution by the Committee by reason of neglect or \ncorruption in office or misbehaviour or incompetence; \n  (5) being removed by the Committee by reason of failing the performance \nassessment; \n  (6) the occurrence of the case specified in the contract of employment or the \nagreement between the Committee and the Secretary-General."}},{"id":"TH-H003-A36","no":36,"noLabel":{"en":"Article 36"},"heading":{"en":"The Secretary-General shall, under the supervision of the"},"text":{"en":"Committee, the CSSC and the EBO, carry out activities in pursuit of orders of the Committee, \nthe CSSC and the EBO, within the duties and powers as follows: \n  (1) to administer affairs of the Office with a view to the achievement of missions \nof the Office and in accordance with the policy and plan on the cyber security maintenance, \nthe action plan on the cyber security maintenance, policies of the Council of Ministers and the \nCommittee and Regulations, policies, resolutions and Notifications of the EBO;  \n  (2) to lay down Rules under policies of the Committee and the CSSC in a manner \nnot contrary to or inconsistent with the law, resolutions of the Council of Ministers and \nRegulations, policies, resolutions and Notifications issued by the Committee and the CSSC; \n  (3) to be the superior of officials and employees of the Office and assess \nperformance of officials and employees of the Office in accordance with the Regulations of the \nEBO and the Rules of the Office; \n18 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (4) to appoint Deputy Secretary-Generals or assistant Secretary-Generals with the \napproval of the Committee for assisting the performance of work of the Secretary-General as \nentrusted by the Secretary-General; \n  (5) to recruit and appoint officials and employees of the Office, increase, reduce \nor cut their salaries or wages, inflict disciplinary penalty upon them and also remove them from \noffice, in accordance with the Regulations of the EBO and the Rules of the Office; \n  (6) to perform any other activities in accordance with the Regulations, policies, \nresolutions or Notifications issued by the EBO or the CSSC. \n  In affairs of the Office which concern third persons, the Secretary-General shall \nrepresent the Office within the scope of the appointment by the Committee. \n  The Secretary-General may delegate powers to any person attached to the Office \nfor performing any particular act on the Secretary-General’s behalf, in accordance with the \nRegulations issued by the EBO. \n  In the case where there is no Secretary-General or the Secretary-General is \nunable to perform duties, the Deputy Secretary-General of respective seniority shall act as the \nSecretary-General. If there is no Deputy Secretary-General or Deputy Secretary-Generals are \nunable to perform duties, the Committee shall appoint an appropriate person to act as the \nSecretary-General."}},{"id":"TH-H003-A37","no":37,"noLabel":{"en":"Article 37"},"text":{"en":"Accounting of the Office shall be carried out in accordance with the \nform and rules prescribed by the EBO, having regard to international principles and accounting \nstandards."}},{"id":"TH-H003-A38","no":38,"noLabel":{"en":"Article 38"},"text":{"en":"The Office shall prepare financial statements and accounts and \nsubmit the same to the auditor within ninety days as from the end of the accounting year. \n  The State Audit Office or a chartered auditor approved by the State Audit Office \nshall be the auditor of the Office and assess the expenditure of money as well as the disposal \nof property of the Office every year and prepare an audit report for submission to the EBO for \nadoption. \n19 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A39","no":39,"noLabel":{"en":"Article 39"},"text":{"en":"The Office shall prepare an annual report on its operations for \nsubmission to the Committee and the Minister within one hundred eighty days as from the end \nof the accounting year and disseminate the report to the public. \n  The annual report on operations under paragraph one shall indicate details of \nfinancial statements as commented on by the auditor and the works of the Office as well as \nthe reporting of the assessment of the operations of the Office in the past year. \n  The assessment of the operations of the Office under paragraph two shall be \ncarried out by a third person approved by the EBO."}},{"id":"TH-H003-A40","no":40,"noLabel":{"en":"Article 40"},"heading":{"en":"The Minister shall have the power to exercise general"},"text":{"en":"superintendence of affairs of the Office to ensure conformity with the duties and powers of the \nOffice, laws, national strategies, policies and plans of the Government and resolutions of the \nCouncil of Ministers concerned. For this purpose, the Minister shall have the power to order the \nSecretary-General to provide explanations, give opinions or prepare a report for submission to \nthe Minister and shall have the power to suspend acts of the Office which are contrary to the \nduties and powers of the Office, laws, national strategies, policies and plans of the Government \nor resolutions of the Council of Ministers concerned and order an investigation of facts relating \nto the operation of the Office. \nCHAPTER III \nCYBER SECURITY MAINTENANCE \n______________ \nPART I \nPOLICY AND PLANS \n______________"}},{"id":"TH-H003-A41","no":41,"noLabel":{"en":"Article 41"},"heading":{"en":"The cyber security maintenance shall be conducted by having"},"text":{"en":"regard to the uniformity and integration of operations of State agencies and private agencies \nand shall be in line with the national policy and plan on the development of digitality for \neconomy and society under the law on digital development for economy and society and the \npolicy and masterplan relating to the maintenance of security prepared by the National Security \nCouncil. \n20 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  Operations in relation to the cyber security maintenance shall be aimed at \ncreating potential for the prevention, handling and reduction of cyber threat risks, in particular, \nthe protection of critical information infrastructure of the country."}},{"id":"TH-H003-A42","no":42,"noLabel":{"en":"Article 42"},"text":{"en":"The policy and plan on the cyber security maintenance shall at \nleast contain goals and directions as follows: \n  (1) the integration of the management in relation to the cyber security \nmaintenance of the country; \n  (2) the creation of measures and mechanisms for developing potential for the \nprevention, handling and reduction of cyber threat risks; \n  (3) the creation of measures for the protection of critical information \ninfrastructure of the country; \n  (4) the co-ordination of co-operation between the public and private sectors and \nthe co-ordination of international co-operation for the purpose of the cyber security \nmaintenance; \n  (5) the research and development of technology and bodies of knowledge \nrelating to the cyber security maintenance; \n  (6) the development of personnel and experts in the area of the cyber security \nmaintenance in both public and private sectors; \n  (7) the creation of awareness and knowledge of the cyber security maintenance; \n  (8) the development of rules and laws for the purpose of the cyber security \nmaintenance."}},{"id":"TH-H003-A43","no":43,"noLabel":{"en":"Article 43"},"heading":{"en":"The Committee shall prepare the policy and plan on the cyber"},"text":{"en":"security maintenance in accordance with the directions under section 42 for submission to the \nCouncil of Ministers for approval and for publication in the Government Gazette. Upon its \npublication, State agencies, regulatory or supervisory agencies and critical information \ninfrastructure agencies as specified in the policy and plan on the cyber security maintenance \nshall take action in the implementation of such policy and plan. \n21 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  In the preparation of the policy and plan under paragraph one, the Office shall \nhold the hearing of opinions or meetings jointly with State agencies, regulatory or supervisory \nagencies and critical information infrastructure agencies."}},{"id":"TH-H003-A44","no":44,"noLabel":{"en":"Article 44"},"text":{"en":"State agencies, regulatory or supervisory agencies and critical \ninformation infrastructure agencies shall expeditiously prepare a code of practice and a \nframework standard for the cyber security maintenance of each agency in line with the policy \nand plan on the cyber security maintenance. \n  The code of practice for the cyber security maintenance under paragraph one \nshall at least consist of the following matters: \n  (1) the plan on the inspection and assessment of risks involving the cyber \nsecurity maintenance by an assessor, an internal auditor or a third-person independent auditor \nat least once a year;  \n  (2) the plan on the handling of cyber threats. \n  For the purpose of the preparation of the code of practice for the cyber security \nmaintenance under paragraph one, the Office shall, with the approval of the Committee, \nprepare a code of practice and a framework standard in order to be relied on by State agencies, \nregulatory or supervisory agencies or critical information infrastructure agencies as guidance for \npreparing their own code of practice or to be adopted as their own code of practice, and in the \ncase where such agencies have not yet had a code of practice or have a code of practice which \nis incomplete or inconsistent with the code of practice and framework standard, such code of \npractice and framework standard shall govern. \nPART II \nMANAGEMENT \n______________"}},{"id":"TH-H003-A45","no":45,"noLabel":{"en":"Article 45"},"text":{"en":"State agencies, regulatory or supervisory agencies and critical \ninformation infrastructure agencies have the duty to prevent, handle and reduce cyber threat \nrisks in accordance with the code of practice and framework standard for the cyber security \nmaintenance of each agency and shall also proceed in the implementation of the code of \n22 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \npractice and framework standard for the cyber security maintenance under section 13 paragraph \none (4). \n  In the case where State agencies, regulatory or supervisory agencies or critical \ninformation infrastructure agencies are unable to take action or perform in accordance with \nparagraph one, the Office may render assistance with respect to personnel or technological \nmatters to such agencies at their request."}},{"id":"TH-H003-A46","no":46,"noLabel":{"en":"Article 46"},"heading":{"en":"For the purpose of the cyber security maintenance, the State"},"text":{"en":"agencies, regulatory or supervisory agencies and critical information infrastructure agencies shall \ngive the Office the notification of names of officials of executive levels and operational levels in \nthe interest of the co-ordination in relation to the cyber security maintenance. \n  In the case of any change of officials under paragraph one, the State agencies, \nregulatory or supervisory agencies and critical information infrastructure agencies shall \nexpeditiously notify it to the Office."}},{"id":"TH-H003-A47","no":47,"noLabel":{"en":"Article 47"},"text":{"en":"In the case where the performance of duties under this Act requires \nknowledge and expertise, the Committee or the CSSC may entrust the Secretary-General to \nemploy experts as may be appropriate to particular work. \n  Experts under paragraph one shall possess such appropriate qualifications or \nexperience as prescribed in the Notification of the Committee.  \n  The Secretary-General shall issue expert identification cards to persons appointed \nand such persons shall, in the performance of duties, show identification cards as experts and \nshall, upon termination of duties, expeditiously return the identification cards to the Office. \nPART III \nCRITICAL INFORMATION INFRASTRUCTURE \n______________"}},{"id":"TH-H003-A48","no":48,"noLabel":{"en":"Article 48"},"text":{"en":"Critical information infrastructure denotes activities central to \nnational security, military security, economic security and internal peace and order and it is the \nduty of the Office to support and assist the prevention, handling and reduction of cyber threat \nrisks, in particular, cyber threats affecting or occurring to critical information infrastructure. \n23 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A49","no":49,"noLabel":{"en":"Article 49"},"heading":{"en":"The Committee shall have the power to issue a Notification"},"text":{"en":"prescribing agencies which assume missions or provide services in the following areas as critical \ninformation infrastructure agencies: \n  (1) national security; \n  (2) essential public services; \n  (3) finance and banking; \n  (4) information technology and telecommunication; \n  (5) transport and logistics; \n  (6) energy and public utilities; \n  (7) public health; \n  (8) other areas as additionally prescribed in the Notification of the Committee. \n  The consideration and prescription, in the Notification, of missions or services \nunder paragraph one shall be in accordance with the rules prescribed by the Committee and \npublished in the Government Gazette. In this regard, the Committee shall, from time to time, \nconsider and review the prescription, in the Notification, of such missions or services as may be \nappropriate."}},{"id":"TH-H003-A50","no":50,"noLabel":{"en":"Article 50"},"heading":{"en":"The Committee shall have the power to issue a Notification"},"text":{"en":"prescribing the nature, duties and responsibilities of centres for co-ordination of the computer \nsystem security maintenance for critical information infrastructure agencies under section 49 for \ncarrying out co-ordination on, exercising surveillance of, handling and resolving cyber threats. In \nthis regard, the Committee may require State agencies which have readiness or regulatory or \nsupervisory agencies for such critical information infrastructure agencies to perform such duties \nfor the critical information infrastructure agencies under section 49 in whole or in part. \n  The consideration and prescription, in the Notification, of missions or services of \nthe agencies under paragraph one shall be in accordance with the rules prescribed by the \nCommittee and published in the Government Gazette. In this regard, the Committee shall, from \ntime to time, consider and review the prescription, in the Notification, of such missions or \nservices as may be appropriate. \n24 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A51","no":51,"noLabel":{"en":"Article 51"},"heading":{"en":"In the case of doubt or a challenge as regards the nature of"},"text":{"en":"agencies assuming missions or providing services in the areas prescribed in the Notification \nunder section 49 or section 50, the Committee shall give a final decision thereon."}},{"id":"TH-H003-A52","no":52,"noLabel":{"en":"Article 52"},"text":{"en":"For the purposes of contacts and co-ordination, critical information \ninfrastructure agencies shall notify names and contact information of owners and possessors of \ncomputers and computer system administrators to the Office, their regulatory or supervisory \nagencies and the agencies under section 50 within thirty days as from the date of the \nNotification of the Committee under section 49 paragraph two and section 50 paragraph two or \nas from the date of the decision of the Committee under section 51, as the case may be. In this \nregard, owners and possessors of computers and computer system administrators must at least \nbe persons responsible for the administration of such critical information infrastructure agencies. \n  In the case of any change of owners and possessors of computers and computer \nsystem administrators under paragraph one, notification thereof shall be given to the agencies \nconcerned under paragraph one not less than seven days prior to the change except that, in \nthe case of inevitable necessity, the notification shall be given expeditiously."}},{"id":"TH-H003-A53","no":53,"noLabel":{"en":"Article 53"},"text":{"en":"In carrying out the cyber security maintenance of critical information \ninfrastructure agencies, regulatory or supervisory agencies shall inspect minimum standards as \nregards cyber security of critical information infrastructure agencies within their supervision. If it \nis found that any critical information infrastructure agency fails to meet the standard, such \nregulatory or supervisory agencies shall, without delay, notify the critical information \ninfrastructure agency which fails to meet the standard to carry out rectification in order to meet \nthe standard expeditiously. If such critical information infrastructure agency fails to take action \nor fails to accomplish the action within the period of time specified by the  regulatory or \nsupervisory agency, the regulatory or supervisory agency shall refer the matter to the CSSC for \nconsideration without delay. \n  Upon receipt of a complaint under paragraph one, if the CSSC is of the opinion, \nafter its consideration, that such incident occurs and may cause a cyber threat, the CSSC shall \ntake action as follows: \n  (1) in the case of a State agency, notifying the matter to its chief executive officer \nfor the purpose of exercising the administrative power in instructing such State agency or critical \n25 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \ninformation infrastructure agency to carry out the rectification towards the satisfaction of the \nstandard expeditiously; \n  (2) in the case of a private agency, notifying the matter to its chief executive \nofficer, possessors of computers and administrators of computer systems of such critical \ninformation infrastructure agency for the purpose of carrying out the rectification towards the \nsatisfaction of the standard expeditiously. \n  The Secretary-General shall also carry out follow-ups to ensure the compliance \nwith the provisions of paragraph two."}},{"id":"TH-H003-A54","no":54,"noLabel":{"en":"Article 54"},"text":{"en":"A critical information infrastructure agency shall cause risks involving \nthe cyber security maintenance to be assessed by an assessor and shall also put in place the \nauditing of cyber security by both internal and third-party independent auditors of information \nsecurity at least once a year. \n  A critical information infrastructure agency shall furnish a summary of a report on \nthe operations to the Office within thirty days as from the date of completion."}},{"id":"TH-H003-A55","no":55,"noLabel":{"en":"Article 55"},"text":{"en":"In the case where the CSSC is of the opinion that the assessment of \nrisks involving the cyber security maintenance or the auditing of cyber security under section 54 \nfails to meet the standard, as revealed by a report prepared by a regulatory or supervisory \nagency, the CSSC shall order such critical information infrastructure agency to carry out a risk \nassessment anew to ensure the satisfaction of the standard or carry out the auditing in other \naspects which may affect critical information infrastructure. \n  In the case where such critical information infrastructure agency has already put \nin place the assessment of risks involving the cyber security maintenance or the auditing of \ncyber security under paragraph one but the CSSC is of the opinion that it remains unable to \nmeet the standard, the CSSC shall take action as follows: \n  (1) in the case of a State agency, notifying the matter to its chief executive officer \nfor the purpose of exercising the administrative power in instructing such State agency or critical \ninformation infrastructure agency to carry out the rectification towards the satisfaction of the \nstandard expeditiously; \n  (2) in the case of a private agency, notifying the matter to its chief executive \nofficer, possessors of computers and administrators of computer systems of such critical \n26 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \ninformation infrastructure agency for the purpose of carrying out the rectification towards the \nsatisfaction of the standard expeditiously. \n  The Secretary-General shall also carry out follow-ups to ensure the compliance \nwith the provisions of paragraph two."}},{"id":"TH-H003-A56","no":56,"noLabel":{"en":"Article 56"},"text":{"en":"A critical information infrastructure agency shall put in place \nmechanisms or procedures for surveillance of cyber threats or cyber security incidents which \nare concerned with its critical information infrastructure in accordance with the standard \nprescribed by the regulatory or supervisory agency and in accordance with the code of practice \nas well as resolution measures for the cyber security maintenance as prescribed by the \nCommittee or the CSSC and shall participate in a test of cyber threat handling readiness \norganised by the Office."}},{"id":"TH-H003-A57","no":57,"noLabel":{"en":"Article 57"},"text":{"en":"Upon occurrence of a cyber threat which significantly affects a \nsystem of a critical information infrastructure agency, the critical information infrastructure \nagency shall report it to the Office and the regulatory or supervisory agency and carry out the \nhandling of the cyber threat as provided in Part IV. In this regard, the CSSC may also prescribe \nrules and procedures for the reporting. \nPART IV \nCYBER THREAT HANDLING \n______________"}},{"id":"TH-H003-A58","no":58,"noLabel":{"en":"Article 58"},"text":{"en":"In the case where a cyber threat occurs or is expected to occur to \nan information system within the oversight and responsibility of any State agency or critical \ninformation infrastructure agency, such agency shall take action in inspecting its relevant data, \ncomputer data and computer systems and also surrounding circumstances for the purpose of \nassessing whether the cyber threat has actually occurred. If the inspection reveals that the \ncyber threat has occurred or is expected to occur, it shall take action for preventing, handling \nand reducing cyber threat risks in accordance with the code of practice and framework standard \nfor the cyber security maintenance of such agency and notify the matter to the Office and its \nregulatory or supervisory agency expeditiously. \n27 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  In the case where any agency or person encounters obstacles to or problems in \nthe prevention, handling and reduction of its or his cyber threat risks, such agency or person \nmay address a request to the Office for assistance."}},{"id":"TH-H003-A59","no":59,"noLabel":{"en":"Article 59"},"text":{"en":"When it appears to a regulatory or supervisory agency or when a \nregulatory or supervisory agency has been notified of the incident under section 58, the \nregulatory or supervisory agency shall collaborate with agencies under section 50 in gathering \ndata, examining and analysing situations and assess impacts in connection with cyber threats \nand take action as follows: \n  (1) lending support and rendering assistance to State agencies or critical \ninformation infrastructure agencies within its control or supervision and carrying out co-\noperation and co-ordination with the Office in the prevention, handling and reduction of cyber \nthreat risks; \n  (2) expeditiously giving warnings to State agencies and critical information \ninfrastructure agencies within its control or supervision as well as regulatory or supervisory \nagencies of other State agencies or critical information infrastructure agencies concerned."}},{"id":"TH-H003-A60","no":60,"noLabel":{"en":"Article 60"},"text":{"en":"In its consideration for the purpose of exercising powers in the \nprevention of cyber threats, the Committee may prescribe the nature of cyber threats and \nclassify them into three levels as follows: \n  (1) a non-serious cyber threat, which means a cyber threat posing a significant risk \nto the extent causing a computer system of a critical infrastructure agency of the country or the \nprovision of public services to become less efficient;  \n  (2) a serious cyber threat, which means a threat significantly increasing attacks \nagainst a computer system, computers or computer data with a view to attacking critical \ninfrastructure of the country and thereby causing a computer system or critical information \ninfrastructure pertinent to the provision of critical infrastructure services of the country, national \nsecurity, international relations, national defence, economy, public health, public safety or \npublic peace and order to be so injurious as to be incapable of functionality or out of service;  \n  (3) a critical cyber threat, which means a critical cyber threat of the following \ndescriptions:  \n28 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n   (a) being a cyber threat resulting from an attack against a computer \nsystem, computers or computer data at a higher level than that of a serious cyber threat, in \nthat it generates severe effects on critical information infrastructure of the country so \ncomprehensively as to put the operation of State agencies or the provision of critical \ninfrastructure services of the country to the public into total failure such that the State is \nunable to control central functionality of computer systems of the State or the employment of \nregular remedial measures for resolving the threat becomes unworkable, with the possibility \nthat the threat spreads to other critical infrastructure of the country and thereby gives rise to \nfatality of a large number of people or destruction of a large number or amount of computer \nsystems, computers or computer data to a comprehensive and nationwide extent; \n   (b) being a cyber threat which affects or possibly affects public peace and \norder or causes harm to national security or possibly causes the country or any part of the \ncountry to be in a state of emergency or face the commission of offences relating to terrorism \nunder the Penal Code, a battle or a war such that urgent measures are needed for upholding \nthe democratic regime of government with the King as Head of the State under the Constitution \nof the Kingdom of Thailand, the independence and territorial integrity, national benefits, the \nobservance of laws, public safety, peaceful living of the people, the protection of rights and \nliberties, public peace and order or interests or the prevention or cure of damage from public \ndisasters of an urgent and severe nature. \n  Details of the nature of cyber threats and measures for preventing, handling, \nassessing, suppressing and terminating cyber threats of each level shall be prescribed in the \nNotification of the Committee."}},{"id":"TH-H003-A61","no":61,"noLabel":{"en":"Article 61"},"text":{"en":"When it appears to the CSSC that a serious cyber threat occurs or is \nexpected to occur, the CSSC shall order the Office to take action as follows: \n  (1) gathering information and documentary evidence, witnesses or physical \nevidence concerned for the purposes of analysing situations and assessing impacts of the cyber \nthreat; \n  (2) supporting, assisting and participating in the prevention, handling and \nreduction of emerging cyber threat risks; \n29 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (3) preventing cyber security incidents resulting from the cyber threat, \nrecommending or ordering the use of resolution mechanisms for the cyber security \nmaintenance and also finding directions for countering or resolving cyber security problems; \n  (4) encouraging the Office and agencies concerned, in public and private sectors, \nto assist and participate in the prevention, handling and reduction of emerging cyber threat \nrisks; \n  (5) giving warnings of the cyber threat for information as is necessary and \nappropriate, having regard to the situation and the gravity as well as impacts of such cyber \nthreat;  \n  (6) facilitating the co-ordination amongst State agencies concerned as well as \nprivate agencies for managing risks and cyber security incidents."}},{"id":"TH-H003-A62","no":62,"noLabel":{"en":"Article 62"},"heading":{"en":"In the execution of section 61 for the purposes of analysing"},"text":{"en":"situations and assessing impacts of cyber threats, the Secretary-General shall order competent \nofficials to take action as follows:  \n  (1) making written requests for co-operation from persons concerned for the \npurpose of providing information within an appropriate period of time and at a specified place \nor providing, in writing, information on cyber threats;   \n  (2) making written requests for information, documents or copies of information \nor documents which are in possession of other persons and beneficial to the conduct of \noperations;  \n  (3) addressing questions to persons possessing knowledge and understanding of \nfacts and situations connected with cyber threats; \n  (4) entering immovable property or places of business connected with or \nexpectedly connected with cyber threats of persons or agencies concerned upon consent of \nthe possessor of such place. \n  A person who provides information under paragraph one in good faith shall be \nafforded protection and shall not be deemed to commit a wrongful act or a breach of contract."}},{"id":"TH-H003-A63","no":63,"noLabel":{"en":"Article 63"},"text":{"en":"In the case where it is necessary for the prevention, handling and \nreduction of cyber threat risks, the CSSC shall order State agencies to provide information and \n30 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nlend support through the provision of their personnel or the use of electronic devices which are \nin their possession and related to the cyber security maintenance.  \n  The CSSC shall exercise supervision to prevent the use of information acquired \nunder paragraph one in a possibly injurious manner and the CSSC shall be responsible for \nremuneration of personnel and costs or damage from the use of such electronic devices.  \n  The provisions of paragraph one and paragraph two shall also apply to requests \nto be addressed to private individuals with their consent."}},{"id":"TH-H003-A64","no":64,"noLabel":{"en":"Article 64"},"text":{"en":"In the case where a serious cyber threat occurs or is expected to \noccur, the CSSC shall take action in preventing, handling and reducing cyber threat risks and \npursue necessary measures. \n  In the execution of paragraph one, the CSSC shall instruct, in writing, State \nagencies concerned with the cyber security maintenance to perform or cease any action for the \npurposes of preventing, handling and reducing cyber threat risks in an appropriate and efficient \nmanger in accordance with the directions determined by the CSSC and also undertake \nintegrated collaboration in promptly controlling, terminating or mitigating consequences of such \ncyber threat.  \n  The Secretary-General shall continually report the operations under this section \nto the CSSC and shall, when such cyber threat ceases to exist, expeditiously report results of \nthe operations to the CSSC."}},{"id":"TH-H003-A65","no":65,"noLabel":{"en":"Article 65"},"text":{"en":"In handing and mitigating damage from a serious cyber threat, the \nCSSC has the power to order, only to the extent necessary for preventing the cyber threat, \nowners, possessors or users of computers or computer systems or administrators of computer \nsystems who are reasonably believed to be connected with the cyber threat or affected by the \ncyber threat to take action as follows: \n  (1) exercising surveillance of computers or computer systems in a particular \nperiod of time; \n  (2) inspecting computers or computer systems for finding defects which affect \nthe cyber security maintenance, analysing situations and assessing impacts of the cyber threat; \n31 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (3) taking measures for resolving the cyber threat in order to cope with defects or \neliminate undesirable instruction sets or terminate or mitigate the cyber threat in operation;  \n  (4) retaining the status of computer data or computer systems by any means for \nthe purpose of conducting operations in computer forensic science; \n  (5) gaining access to computer data or computer systems or other data relating \nto computer systems concerned only to the extent necessary for preventing the cyber threat.  \n  In the case where there exists a need for gaining access to the data under (5), the \nCSSC shall entrust the Secretary-General to file a motion with the competent Court for ordering \nowners, possessors or users of computers or computer systems or administrators of computer \nsystems under paragraph one to take action required by the motion. In this regard, a motion \nfiled with the Court shall indicate a reasonable cause to believe that any particular person is \ncommitting or will be committing a particular act which gives rise to a serious cyber threat. In \nthe consideration of a motion, a request shall be made for the conduct of an urgent inquiry \ninto the motion and the Court shall expeditiously conduct the inquiry."}},{"id":"TH-H003-A66","no":66,"noLabel":{"en":"Article 66"},"text":{"en":"In preventing, handling and reducing risks of serious cyber threats, \nthe CSSC has the power to carry out or order competent officials to carry out operations, only \nto the extent necessary for preventing cyber threats, in the following matters: \n  (1) entering a place for inspection upon written notification of a reasonable cause \nto the owner or possessor of such place if there is a reasonable cause to believe that there are \ncomputers or computer systems which are connected to cyber threats or affected by cyber \nthreats; \n  (2) gaining access to computer data, computer systems or other data relating to \ncomputer systems or making copies of or screening data or information or computer \nprogrammes reasonably believed to be connected with or affected by cyber threats; \n  (3) testing functionality of computers or computer systems reasonably believed \nto be connected with or affected by cyber threats or used for searching any data stored therein \nor utilised therefrom;   \n  (4) seizing or attaching, only to the extent necessary, computers, computer \nsystems or any equipment reasonably believed to be connected with cyber threats for \ninspection or analysis for a period not exceeding thirty days and, at the expiration of such \n32 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nperiod, returning computers or any equipment to owners or possessors immediately after \ncompletion of the inspection or analysis. \n  In carrying out activities under (2), (3) and (4), the CSSC shall file a motion with \nthe competent Court for ordering competent officials to take action indicated in the motion. In \nthis regard, a motion shall indicate a reasonable cause to believe that any particular person is \ncommitting or will be committing a particular act which gives rise to a serious cyber threat. In \nthe consideration of a motion, a request shall be made for the conduct of an urgent inquiry \ninto the motion and the Court shall expeditiously conduct the inquiry."}},{"id":"TH-H003-A67","no":67,"noLabel":{"en":"Article 67"},"text":{"en":"In the case where there occurs a critical cyber threat, it shall be the \nduty and power of the National Security Council to carry out the cyber security maintenance \nunder the law on the National Security Council and other relevant laws."}},{"id":"TH-H003-A68","no":68,"noLabel":{"en":"Article 68"},"text":{"en":"In the case where the incident is a matter of emergency and the \ntreat in question is a critical cyber threat, the Committee may entrust the Secretary-General to \ntake immediate action to the extent necessary for preventing and remedying damage in \nadvance without filing a motion with the Court, provided that after having taken such action \ndetails thereof shall expeditiously be given to the competent Court. \n  In the case of an incident of serious or critical nature, for the purposes of \npreventing, assessing, handling, suppressing, terminating and reducing cyber threat risks, the \nSecretary-General shall, with the approval of the Committee or the CSSC, have the power to \nrequest up-to-date and consistent information from persons connected with cyber threats. In \nthis instance, such persons shall expeditiously give the Committee or the CSSC co-operation \nand assistance."}},{"id":"TH-H003-A69","no":69,"noLabel":{"en":"Article 69"},"text":{"en":"A person to whom an order in connection with the handling of a cyber \nthreat is given may appeal against the order only if the cyber threat in question is a non-serious \none.  \nCHAPTER IV \nPENALTIES \n______________ \n33 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A70","no":70,"noLabel":{"en":"Article 70"},"text":{"en":"A competent official under this Act shall not disclose or furnish \ncomputer data, log files, other data relating to computer systems or data of providers which are \nacquired under this Act to any person. Any person who violates this prohibition shall be liable \nto imprisonment for a term not exceeding three years or to a fine not exceeding sixty thousand \nBaht or to both. \n  The provisions of paragraph one shall not apply to action performed for the \npurpose of taking legal proceedings against offenders under this Act or offenders under other \nlaws or for the purpose of taking legal proceedings against competent officials in connection \nwith the unlawful exercise of powers and duties."}},{"id":"TH-H003-A71","no":71,"noLabel":{"en":"Article 71"},"text":{"en":"Any competent official under this Act who negligently causes any \nother person to gain the knowledge of computer data, log files, data of providers or other data \nrelating to computer systems which have been acquired under this Act shall be liable to \nimprisonment for a term not exceeding one year or to a fine not exceeding twenty thousand \nBaht or to both."}},{"id":"TH-H003-A72","no":72,"noLabel":{"en":"Article 72"},"text":{"en":"Any person who, having gained the knowledge of computer data, \nlog files, data of providers or other data relating to computer systems acquired by a competent \nofficial under this Act, unlawfully discloses such data to any person shall be liable to \nimprisonment for a term not exceeding two years or to a fine not exceeding forty thousand \nBaht or to both."}},{"id":"TH-H003-A73","no":73,"noLabel":{"en":"Article 73"},"text":{"en":"Any critical information infrastructure agency which fails to report \ncyber threats under section 57 without any reasonable cause shall be liable to a fine not \nexceeding two hundred thousand Baht."}},{"id":"TH-H003-A74","no":74,"noLabel":{"en":"Article 74"},"text":{"en":"Any person who fails to comply with a written request made by a \ncompetent official or fails to furnish information to a competent official under section 62 (1) or \n(2) without any reasonable cause, as the case may be, shall be liable to a fine not exceeding \none hundred thousand Baht."}},{"id":"TH-H003-A75","no":75,"noLabel":{"en":"Article 75"},"text":{"en":"Any person who violates or fails to comply with an order of the \nCSSC under section 65 (1) and (2) without any reasonable cause shall be liable to a fine not \nexceeding three hundred thousand Baht and an additional fine not exceeding ten thousand \n34 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nBaht a day as from the expiration of the period of time specified by the order issued by the \nCSSC until correct action is performed. \n  Any person who violates or fails to comply with an order of the CSSC under \nsection 65 (3) and (4) or fails to comply with an order of the Court under section 65 (5) shall be \nliable to imprisonment for a term not exceeding one year or to a fine not exceeding twenty \nthousand Baht or to both."}},{"id":"TH-H003-A76","no":76,"noLabel":{"en":"Article 76"},"text":{"en":"Any person who obstructs or fails to comply with an order of the \nCSSC or a competent official who takes action in pursuit of an order of the CSSC under section \n66 (1) or fails to comply with an order of the Court under section 66 (2), (3) or (4) without any \nreasonable cause shall be liable to imprisonment for a term not exceeding three years or to a \nfine not exceeding sixty thousand Baht or to both."}},{"id":"TH-H003-A77","no":77,"noLabel":{"en":"Article 77"},"text":{"en":"In the case where the offender under this Act is a juristic person, if \nthe commission of the offence by such juristic person has resulted from the instruction or an \naction of a director or a manager or any person responsible for the operation of such juristic \nperson or in the case where such person has the duty to give instructions or take action and \nrefrains from giving instructions or taking action, thereby leading to the commission of the \noffence by such juristic person, such person shall also be liable to the penalty as provided for \nsuch offence. \nTRANSITORY PROVISIONS \n_______________"}},{"id":"TH-H003-A78","no":78,"noLabel":{"en":"Article 78"},"text":{"en":"In the initial period, the Committee shall consist of the Chairperson \nand members under section 5 (1) and (2) and the Secretary-General of the National Cyber \nSecurity Committee shall be a member and secretary for performing duties to the extent \nnecessary for the time being, and action shall be taken for completing the appointment of \nqualified members of the Committee under section 5 (3) within ninety days as from the date on \nwhich this Act comes into force. \n  In appointing qualified members under paragraph one, the Minister of Digital \nEconomy and Society may also nominate persons to the Council of Ministers for considering \nand appointing as such qualified members. \n35 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H003-A79","no":79,"noLabel":{"en":"Article 79"},"text":{"en":"Action shall be taken in order to have the CSSC and the EBO within \nninety days as from the date of the appointment of qualified members of the Committee under \nsection 78. \n  Action shall be taken for completing the appointment of the Secretary-General \nof the National Cyber Security Committee under this Act within ninety days as from the date of \nthe completion of the establishment of the Office under section 80."}},{"id":"TH-H003-A80","no":80,"noLabel":{"en":"Article 80"},"text":{"en":"Action shall be taken for completing the establishment of the Office \nfor performing operations under this Act within one year as from the date on which this Act \ncomes into force. \n  Pending the completion of the establishment of the Office, the Office of the \nPermanent Secretary for Digital Economy and Society shall serve as the Office under this Act \nand the Permanent Secretary for Digital Economy and Society shall serve as Secretary-General \nuntil the appointment of the Secretary-General is made under section 79 paragraph two."}},{"id":"TH-H003-A81","no":81,"noLabel":{"en":"Article 81"},"text":{"en":"In the initial period, the Council of Ministers shall allocate an \ninaugural fund to the Office as is necessary. \n  The Minister shall propose to the Council of Ministers for instructing Government \nofficials, employees, officials or any other workers in State agencies to perform duties at the \nOffice for the time being within a period of time specified by the Council of Ministers.  \n  It shall be deemed that Government officials, employees, officials or any other \nworkers in State agencies who perform duties at the Office for the time being under paragraph \ntwo retain their original status and remain entitled to salaries or wages, as the case may be, \nfrom their original agencies. In this regard, the Committee may also determine special \nremuneration for Government officials, employees, officials or any other workers in State \nagencies under paragraph two during their performance of duties at the Office. \n  Within one hundred eighty days as from the completion of the establishment of \nthe Office, the Office shall take action in selecting Government officials, employees, officials or \nany other workers in State agencies under paragraph two for the purpose of recruiting them as \nemployees of the Office.  \n36 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  Any Government official, employee, official or other worker in a State agency who is \nselected and recruited under paragraph four shall be entitled to count a period of previous service \nat the original agency into a period of service at the Office under this Act on a continual basis."}},{"id":"TH-H003-A82","no":82,"noLabel":{"en":"Article 82"},"text":{"en":"When this Act comes into force, the Minister shall propose to the \nCouncil of Ministers for approving a transfer of all powers, duties, undertakings, property, rights, \nliabilities and budgets of all missions relating to the cyber security maintenance of the Office of \nthe Permanent Secretary of the Ministry of Digital Economy and Society and the Electronic \nTransactions Development Agency as in existence on the day prior to the date on which this \nAct comes into force to the Office under this Act."}},{"id":"TH-H003-A83","no":83,"noLabel":{"en":"Article 83"},"text":{"en":"The issuance of Ministerial Regulations, Rules and Notifications under \nthis Act shall be completed within one year as from the date on which this Act comes into force. If \ntheir completion cannot be achieved, the Minister shall report the reasons therefor to the Council \nof Ministers for information. \n \n  Countersigned by: \n    General Prayut Chan-o-cha   \n       Prime Minister"}}],"pack":"th-p01"};
  FT["TH-H004"] = {"id":"TH-H004","coverage":"full","language":"th","sourceName":"泰国国务委员会办公室（Office of the Council of State, สำนักงานคณะกรรมการกฤษฎีกา）法律检索系统","sourceUrl":"https://searchlaw.ocs.go.th/council-of-state/#/public/doc/Qko1NGNVa1FhMG9hTTNGcU9sTGxydz09","fetchedAt":"2026-10-06","articleCount":1849,"structureMode":"ARTICLE","title":{"zh":"民商法典","en":"Civil and Commercial Code","orig":"ประมวลกฎหมายแพ่งและพาณิชย์"},"level":"code","status":"active","topics":["civil","commercial"],"docNumber":"ป0003-1D-0002","issuingBody":"泰国国务委员会办公室（OCS）","promulgatedDate":"1925-11-11","officialCode":"ป0003-1D-0002","completenessNote":"全文，共 1849 条；逐字取自 泰国国务委员会办公室（Office of the Council of State, สำนักงานคณะกรรมการกฤษฎีกา）法律检索系统官方详情页（https://searchlaw.ocs.go.th/council-of-state/#/public/doc/Qko1NGNVa1FhMG9hTTNGcU9sTGxydz09），未改写、未摘译、未节选；原文语言：泰语（th）。 条文抬头依官方原件为「มาตรา N」（第 N 条）体例，本库照录官方写法；编/章/节/款标题依原件「บรรพ …」「ลักษณะ …」「หมวด …」「ส่วน …」层级还原。 其中 2 条在官方原件中已被废止（抬头带「(ยกเลิก)」），本库照录其编号与正文，「status」字段标注为 repealed，未删除、未改写。 源文条号不连续（自第 1 条起，止于第 1755 条，缺 1275、1276、1277、1278、1279、1280、1281、1282、1283、1284、1285、1286、1287、1288、1289、1290、1291、1292、1293、1294）：经逐条比对官方页面，该处原文没有对应的「มาตรา N」抬头行，系官方编号跳跃或条文已被整条废止未留残文，非抽取遗漏，故未擅自补号。","country":"TH","countryName":"泰国","layer":"intl","articles":[{"id":"TH-H004-A1","no":1,"noLabel":{"th":"มาตรา 1"},"text":{"th":"มาตรา ๑ กฎหมายนี้ให้เรียกว่า ประมวลกฎหมายแพ่งและพาณิชย์"}},{"id":"TH-H004-A2","no":2,"noLabel":{"th":"มาตรา 2"},"text":{"th":"มาตรา ๒ พระราชบัญญัตินี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศในราชกิจจานุเบกษาเป็นต้นไปมาตรา ๖๒ ในกรณีที่มีการให้ของหมั้นกันไว้ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ ให้ของหมั้นดังกล่าวตกเป็นสิทธิแก่หญิงเมื่อได้ทำการสมรสแล้ว"}},{"id":"TH-H004-A3","no":3,"noLabel":{"th":"มาตรา 3"},"text":{"th":"มาตรา ๓ ให้ยกเลิกมาตรา ๖ แห่งพระราชบัญญัติให้ใช้บทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ พุทธศักราช ๒๔๗๗ แต่ไม่ให้กระทบกระเทือนถึงการสมรสของบุคคลซึ่งนับถือศาสนาอิสลาม ซึ่งได้มีอยู่ก่อนวันใช้พระราชกำหนดนี้ และทั้งสัมพันธ์ในครอบครัวอันเกิดแต่การสมรสนั้น ๆ"}},{"id":"TH-H004-A4","no":4,"noLabel":{"th":"มาตรา 4"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๔ กฎหมายนั้น ต้องใช้ในบรรดากรณีซึ่งต้องด้วยบทบัญญัติใด ๆ แห่งกฎหมายตามตัวอักษร หรือตามความมุ่งหมายของบทบัญญัตินั้น ๆ เมื่อไม่มีบทกฎหมายที่จะยกมาปรับคดีได้ ให้วินิจฉัยคดีนั้นตามจารีตประเพณีแห่งท้องถิ่น ถ้าไม่มีจารีตประเพณีเช่นว่านั้น ให้วินิจฉัยคดีอาศัยเทียบบทกฎหมายที่ใกล้เคียงอย่างยิ่ง และถ้าบทกฎหมายเช่นนั้นก็ไม่มีด้วย ให้วินิจฉัยตามหลักกฎหมายทั่วไป"}},{"id":"TH-H004-A5","no":5,"noLabel":{"th":"มาตรา 5"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๕ บทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ ท้ายพระราชบัญญัตินี้ ไม่กระทบกระเทือนถึงความสมบูรณ์ของการหมั้น การสมรส สัญญาก่อนสมรส การเป็นบิดามารดากับบุตร การเป็นผู้ปกครอง การเป็นผู้อนุบาลหรือผู้พิทักษ์และการรับบุตรบุญธรรมที่ได้มีอยู่แล้วในวันใช้บังคับบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ ท้ายพระราชบัญญัตินี้"}},{"id":"TH-H004-A6","no":6,"noLabel":{"th":"มาตรา 6"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๖ การเปลี่ยนแปลงเพิกถอนสัญญาก่อนสมรส ซึ่งสัญญาก่อนสมรสนั้นได้ทำขึ้นไว้ก่อนวันใช้บังคับบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ให้กระทำได้โดยคู่สมรสนำหนังสือสัญญาก่อนสมรสพร้อมด้วยข้อตกลงการเปลี่ยนแปลงเพิกถอนไปยื่นต่อนายทะเบียนสมรส ณ ท้องที่ที่ตนทำการสมรส และให้นายทะเบียนสมรสจดการเปลี่ยนแปลงเพิกถอนสัญญาก่อนสมรสไว้ในทะเบียนสมรส และแนบหนังสือสัญญาก่อนสมรส พร้อมด้วยข้อตกลงเปลี่ยนแปลงเพิกถอนไว้ท้ายทะเบียนสมรสด้วย การเปลี่ยนแปลงเพิกถอนสัญญาก่อนสมรสจะกระทำได้ต่อเมื่อได้รับอนุญาตจากศาลตามเงื่อนไขและกรณีที่ระบุไว้ในมาตรา ๑๔๖๗ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้"}},{"id":"TH-H004-A7","no":7,"noLabel":{"th":"มาตรา 7"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๗ บทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ไม่กระทบกระเทือนถึงอำนาจการจัดการสินบริคณห์ที่คู่สมรสฝ่ายใดฝ่ายหนึ่งได้มีอยู่แล้วในวันใช้บังคับบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ที่ได้ตรวจชำระใหม่ ท้ายพระราชบัญญัตินี้ แต่ให้ถือว่าสินเดิมตามบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์เดิมของฝ่ายใดเป็นสินส่วนตัวตามบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ ท้ายพระราชบัญญัตินี้ของฝ่ายนั้น เพื่อประโยชน์แห่งมาตรานี้ ถ้าคู่สมรสฝ่ายใดเป็นผู้จัดการสินบริคณห์แต่ฝ่ายเดียว ให้ถือว่าคู่สมรสอีกฝ่ายหนึ่งได้ยินยอมให้คู่สมรสฝ่ายนั้นจัดการสินสมรสและสินส่วนตัวตามวรรคหนึ่งของตนด้วย ในกรณีที่คู่สมรสฝ่ายใดประสงค์จะใช้อำนาจจัดการสินส่วนตัวตามวรรคหนึ่งที่เป็นส่วนของตน ถ้าคู่สมรสนั้นมิได้เป็นผู้จัดการสินบริคณห์ให้แจ้งให้คู่สมรสอีกฝ่ายหนึ่งทราบ และให้คู่สมรสทั้งสองฝ่ายร่วมกันจัดการแบ่งสินส่วนตัวดังกล่าวที่อยู่ในสภาพที่แบ่งได้ให้แก่ฝ่ายที่ประสงค์จะจัดการ แต่ถ้าสินส่วนตัวนั้นไม่อยู่ในสภาพที่แบ่งได้ให้ทั้งสองฝ่ายจัดการร่วมกัน"}},{"id":"TH-H004-A8","no":8,"noLabel":{"th":"มาตรา 8"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๘ ให้บรรดาสมาคมที่ได้จดทะเบียนตามประมวลกฎหมายแพ่งและพาณิชย์ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ เป็นสมาคมตามบทบัญญัติแห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ สมาคมใดที่ได้จดทะเบียนตามประมวลกฎหมายแพ่งและพาณิชย์ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ มิได้ใช้ชื่อซึ่งมีคำว่า “สมาคม” ประกอบกับชื่อของสมาคมให้ยื่นคำขอแก้ไขข้อบังคับของสมาคมให้ถูกต้องตามมาตรา ๘๐ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ภายในสองปีนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ"}},{"id":"TH-H004-A9","no":9,"noLabel":{"th":"มาตรา 9"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๙ ในกรณีที่เจ้าหนี้กระทำการใด ๆ ระหว่างวันที่พระราชบัญญัติแก้ไขเพิ่มเติมประมวลกฎหมายแพ่งและพาณิชย์ (ฉบับที่ ๒๐) พ.ศ. ๒๕๕๗ มีผลใช้บังคับจนถึงวันก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ อันมีผลเป็นการลดจำนวนหนี้ที่มีการค้ำประกัน รวมทั้งดอกเบี้ย ค่าสินไหมทดแทน หรือค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้น ให้เจ้าหนี้มีหนังสือแจ้งให้ผู้ค้ำประกันทราบถึงการลดหนี้ดังกล่าวภายในหกสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ และให้ผู้ค้ำประกันเป็นอันหลุดพ้นจากการค้ำประกันตามเงื่อนไขที่บัญญัติไว้ในมาตรา ๖๙๑ วรรคหนึ่ง แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัติ"}},{"id":"TH-H004-A10","no":10,"noLabel":{"th":"มาตรา 10"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๐ สมาคมตามมาตรา ๘ วรรคหนึ่ง สมาคมใด มีสมาชิกไม่ถึงสิบคน หากสมาคมนั้นไม่ได้จัดให้มีจำนวนสมาชิกตามมาตรา ๘๑ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ภายในสองปีนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ ให้นายทะเบียนถอนชื่อสมาคมนั้นออกจากทะเบียนตามมาตรา ๑๐๒ (๕) แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้"}},{"id":"TH-H004-A11","no":11,"noLabel":{"th":"มาตรา 11"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๑ ให้บรรดามูลนิธิที่ได้จดทะเบียนตามประมวลกฎหมายแพ่งและพาณิชย์ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ เป็นมูลนิธิตามบทบัญญัติแห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ และให้ถือว่าตราสารก่อตั้งมูลนิธิดังกล่าวเป็นข้อบังคับของมูลนิธิตามประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ มูลนิธิใดที่ได้จดทะเบียนตามประมวลกฎหมายแพ่งและพาณิชย์ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ มิได้ใช้ชื่อซึ่งมีคำว่า “มูลนิธิ” ประกอบกับชื่อของมูลนิธิ ให้ยื่นคำขอแก้ไขข้อบังคับของมูลนิธิให้ถูกต้องตามมาตรา ๑๑๓ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ภายในสองปีนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ"}},{"id":"TH-H004-A12","no":12,"noLabel":{"th":"มาตรา 12"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๒ บรรดามูลนิธิที่มีอยู่ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับและมิได้เป็นนิติบุคคล ถ้าประสงค์จะจัดตั้งเป็นนิติบุคคลและใช้คำว่า “มูลนิธิ” ประกอบชื่อของตนต่อไป ต้องยื่นคำขอจดทะเบียนตามมาตรา ๑๑๔ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ ภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ"}},{"id":"TH-H004-A13","no":13,"noLabel":{"th":"มาตรา 13"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓ มูลนิธิตามมาตรา ๑๑ วรรคหนึ่ง มูลนิธิใด มีข้อบังคับที่กำหนดให้มีผู้จัดการของมูลนิธิไม่ถึงสามคนในวันที่พระราชบัญญัตินี้ใช้บังคับ ถ้ามูลนิธินั้นไม่ดำเนินการยื่นคำขอแก้ไขข้อบังคับของมูลนิธิเพื่อให้มีคณะกรรมการซึ่งประกอบด้วยบุคคลไม่น้อยกว่าสามคนเป็นผู้ดำเนินกิจการของมูลนิธิภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ ให้นายทะเบียนดำเนินการตามมาตรา ๑๒๘ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ เพื่อสั่งการให้แก้ไขข้อบังคับของมูลนิธิให้ถูกต้องตามกฎหมายต่อไป ถ้าปรากฏว่ามูลนิธิใดไม่สามารถดำเนินกิจการต่อไปได้ ก็ให้นายทะเบียนร้องขอต่อศาลให้มีคำสั่งให้เลิกมูลนิธิตามมาตรา ๑๓๑ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้"}},{"id":"TH-H004-A14","no":14,"noLabel":{"th":"มาตรา 14"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๔ บรรดาระยะเวลาที่บัญญัติไว้ในบรรพ ๑ แห่งประมวลกฎหมายแพ่งและพาณิชย์และที่บัญญัติไว้ในลักษณะ ๒๓ สมาคม ของบรรพ ๓ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ซึ่งใช้บังคับอยู่ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ หากระยะเวลาดังกล่าวยังไม่สิ้นสุดลงในวันที่พระราชบัญญัตินี้ใช้บังคับ และระยะเวลาที่กำหนดขึ้นตามบทบัญญัติแห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้ แตกต่างกับระยะเวลาที่กำหนดไว้เดิม ให้นำระยะเวลาที่ยาวกว่ามาใช้บังคับ"}},{"id":"TH-H004-A15","no":15,"noLabel":{"th":"มาตรา 15"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๕ สภาพบุคคลย่อมเริ่มแต่เมื่อคลอดแล้วอยู่รอดเป็นทารกและสิ้นสุดลงเมื่อตาย ทารกในครรภ์มารดาก็สามารถมีสิทธิต่าง ๆ ได้ หากว่าภายหลังคลอดแล้วอยู่รอดเป็นทารก"}},{"id":"TH-H004-A16","no":16,"noLabel":{"th":"มาตรา 16"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๖ บทบัญญัติแห่งกฎหมายอื่นที่อ้างถึงบทบัญญัติในบรรพ ๑ หรือลักษณะ ๒๓ ในบรรพ ๓ แห่งประมวลกฎหมายแพ่งและพาณิชย์ ให้ถือว่าบทบัญญัติแห่งกฎหมายนั้นอ้างถึงบทบัญญัติที่มีนัยเช่นเดียวกันในบรรพ ๑ แห่งประมวลกฎหมายแพ่งและพาณิชย์ที่ได้ตรวจชำระใหม่ท้ายพระราชบัญญัตินี้"}},{"id":"TH-H004-A17","no":17,"noLabel":{"th":"ข้อ 17"},"chapter":{"th":"ส่วน 1"},"text":{"th":"ข้อ ๑๗ ในกรณีที่กฎหมาย กฎ หรือระเบียบใดกำหนดให้ผู้ขอรับอนุมัติ อนุญาต หรือใบอนุญาต หรือผู้ยื่นขอจดทะเบียนหรือจดแจ้ง หรือผู้แจ้ง ต้องใช้เอกสารที่ทางราชการออกให้แก่ผู้นั้นเพื่อประกอบการพิจารณาหรือดำเนินการ ให้เป็นหน้าที่ของผู้มีอำนาจอนุมัติ อนุญาต ออกใบอนุญาต รับจดทะเบียน รับจดแจ้ง หรือรับแจ้งนั้น ที่จะต้องดำเนินการให้หน่วยงานที่ออกเอกสารราชการเช่นว่านั้นส่งข้อมูลหรือสำเนาเอกสารดังกล่าวมาเพื่อประกอบการพิจารณาหรือดำเนินการ ในกรณีที่ผู้มีอำนาจดังกล่าวประสงค์ได้สำเนาเอกสารนั้นจากผู้ขอรับอนุมัติ อนุญาต หรือใบอนุญาต หรือผู้ยื่นขอจดทะเบียนหรือจดแจ้ง หรือผู้แจ้ง ให้ผู้มีอำนาจนั้นเป็นผู้จัดทำสำเนาเอกสารดังกล่าวเอง เพื่อประโยชน์แห่งการนี้ ห้ามมิให้เรียกเก็บค่าใช้จ่ายที่เกิดจากการทำสำเนาดังกล่าวจากผู้ขอรับอนุมัติ อนุญาต หรือใบอนุญาตหรือผู้ยื่นขอจดทะเบียนหรือจดแจ้ง หรือผู้แจ้ง"}},{"id":"TH-H004-A18","no":18,"noLabel":{"th":"มาตรา 18"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๘ สิทธิของบุคคลในการที่จะใช้นามอันชอบที่จะใช้ได้นั้น ถ้ามีบุคคลอื่นโต้แย้งก็ดี หรือบุคคลผู้เป็นเจ้าของนามนั้นต้องเสื่อมเสียประโยชน์เพราะการที่มีผู้อื่นมาใช้นามเดียวกันโดยมิได้รับอำนาจให้ใช้ได้ก็ดี บุคคลผู้เป็นเจ้าของนามจะเรียกให้บุคคลนั้นระงับความเสียหายก็ได้ ถ้าและเป็นที่พึงวิตกว่าจะต้องเสียหายอยู่สืบไป จะร้องขอต่อศาลให้สั่งห้ามก็ได้"}},{"id":"TH-H004-A19","no":19,"noLabel":{"th":"มาตรา 19"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๙ ในกรณีที่มีการจดทะเบียนหนังสือบริคณห์สนธิไว้ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ แต่ยังมิได้จดทะเบียนบริษัท ให้สามารถดำเนินการจดทะเบียนบริษัทได้ภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ และมิให้นำมาตรา ๑๐๙๙ วรรคสอง แห่งประมวลกฎหมายแพ่งและพาณิชย์ ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้มาใช้บังคับกับการจดทะเบียนบริษัทภายในหนึ่งร้อยแปดสิบวันดังกล่าว"}},{"id":"TH-H004-A20","no":20,"noLabel":{"th":"มาตรา 20"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๐ ในกรณีที่เจ้าหนี้กระทำการใด ๆ นับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ อันมีผลเป็นการลดจำนวนหนี้ที่มีการค้ำประกัน รวมทั้งดอกเบี้ย ค่าสินไหมทดแทน หรือค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้น ให้ผู้ค้ำประกันเป็นอันหลุดพ้นจากการค้ำประกันตามเงื่อนไขที่บัญญัติไว้ในมาตรา ๖๙๑ วรรคหนึ่ง แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้"}},{"id":"TH-H004-A21","no":21,"noLabel":{"th":"มาตรา 21"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๑ บทบัญญัติตามมาตรา ๗๒๗ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ ให้ใช้กับสัญญาจำนองที่ยังมีผลบังคับอยู่ในวันที่พระราชบัญญัตินี้ใช้บังคับด้วย"}},{"id":"TH-H004-A22","no":22,"noLabel":{"th":"มาตรา 22"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๒ บทบัญญัติตามมาตรา ๗๒๘ และมาตรา ๗๓๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ ให้ใช้บังคับกับการบังคับจำนองที่ทำขึ้นนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับด้วย"}},{"id":"TH-H004-A23","no":23,"noLabel":{"th":"มาตรา 23"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๓ บทบัญญัติตามมาตรา ๗๓๗ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ ให้ใช้บังคับกับกรณีที่ผู้รับโอนต้องการไถ่ถอนจำนองเมื่อมีการบอกกล่าวบังคับจำนองตามมาตรา ๗๓๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้"}},{"id":"TH-H004-A24","no":24,"noLabel":{"th":"มาตรา 24"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๔ ผู้เยาว์อาจทำการใด ๆ ได้ทั้งสิ้น ซึ่งเป็นการสมแก่ฐานานุรูปแห่งตน และเป็นการอันจำเป็นในการดำรงชีพตามสมควร"}},{"id":"TH-H004-A25","no":25,"noLabel":{"th":"มาตรา 25"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๕ ผู้เยาว์อาจทำพินัยกรรมได้เมื่อมีอายุสิบห้าปีบริบูรณ์"}},{"id":"TH-H004-A26","no":26,"noLabel":{"th":"มาตรา 26"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๖ ถ้าผู้แทนโดยชอบธรรมอนุญาตให้ผู้เยาว์จำหน่ายทรัพย์สินเพื่อการอันใดอันหนึ่งอันได้ระบุไว้ ผู้เยาว์จะจำหน่ายทรัพย์สินนั้นเป็นประการใดภายในขอบของการที่ระบุไว้นั้นก็ทำได้ตามใจสมัคร อนึ่ง ถ้าได้รับอนุญาตให้จำหน่ายทรัพย์สินโดยมิได้ระบุว่าเพื่อการอันใด ผู้เยาว์ก็จำหน่ายได้ตามใจสมัคร"}},{"id":"TH-H004-A27","no":27,"noLabel":{"th":"มาตรา 27"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๗ ผู้แทนโดยชอบธรรมอาจให้ความยินยอมแก่ผู้เยาว์ในการประกอบธุรกิจทางการค้าหรือธุรกิจอื่น หรือในการทำสัญญาเป็นลูกจ้างในสัญญาจ้างแรงงานได้ ในกรณีที่ผู้แทนโดยชอบธรรมไม่ให้ความยินยอมโดยไม่มีเหตุอันสมควร ผู้เยาว์อาจร้องขอต่อศาลให้สั่งอนุญาตได้ ในความเกี่ยวพันกับการประกอบธุรกิจหรือการจ้างแรงงานตามวรรคหนึ่งให้ผู้เยาว์มีฐานะเสมือนดังบุคคลซึ่งบรรลุนิติภาวะแล้ว ถ้าการประกอบธุรกิจหรือการทำงานที่ได้รับความยินยอมหรือที่ได้รับอนุญาตตามวรรคหนึ่ง ก่อให้เกิดความเสียหายถึงขนาดหรือเสื่อมเสียแก่ผู้เยาว์ ผู้แทนโดยชอบธรรมอาจบอกเลิกความยินยอมที่ได้ให้แก่ผู้เยาว์เสียได้ หรือในกรณีที่ศาลอนุญาต ผู้แทนโดยชอบธรรมอาจร้องขอต่อศาลให้เพิกถอนการอนุญาตที่ได้ให้แก่ผู้เยาว์นั้นเสียได้ ในกรณีที่ผู้แทนโดยชอบธรรมบอกเลิกความยินยอมโดยไม่มีเหตุอันสมควร ผู้เยาว์อาจร้องขอต่อศาลให้เพิกถอนการบอกเลิกความยินยอมของผู้แทนโดยชอบธรรมได้ การบอกเลิกความยินยอมโดยผู้แทนโดยชอบธรรมหรือการเพิกถอนการอนุญาตโดยศาล ย่อมทำให้ฐานะเสมือนดังบุคคลซึ่งบรรลุนิติภาวะแล้วของผู้เยาว์สิ้นสุดลง แต่ไม่กระทบกระเทือนการใด ๆ ที่ผู้เยาว์ได้กระทำไปแล้วก่อนมีการบอกเลิกความยินยอมหรือเพิกถอนการอนุญาต"}},{"id":"TH-H004-A28","no":28,"noLabel":{"th":"มาตรา 28"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๘ บุคคลวิกลจริตผู้ใด ถ้าคู่สมรสก็ดี ผู้บุพการีกล่าวคือ บิดา มารดา ปู่ย่า ตายาย ทวดก็ดี ผู้สืบสันดานกล่าวคือ ลูก หลาน เหลน ลื่อก็ดี ผู้ปกครองหรือผู้พิทักษ์ก็ดี ผู้ซึ่งปกครองดูแลบุคคลนั้นอยู่ก็ดี หรือพนักงานอัยการก็ดี ร้องขอต่อศาลให้สั่งให้บุคคลวิกลจริตผู้นั้นเป็นคนไร้ความสามารถ ศาลจะสั่งให้บุคคลวิกลจริตผู้นั้นเป็นคนไร้ความสามารถก็ได้ บุคคลซึ่งศาลได้สั่งให้เป็นคนไร้ความสามารถตามวรรคหนึ่ง ต้องจัดให้อยู่ในความอนุบาล การแต่งตั้งผู้อนุบาล อำนาจหน้าที่ของผู้อนุบาล และการสิ้นสุดของความเป็นผู้อนุบาล ให้เป็นไปตามบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายนี้ คำสั่งของศาลตามมาตรานี้ ให้ประกาศในราชกิจจานุเบกษา"}},{"id":"TH-H004-A29","no":29,"noLabel":{"th":"มาตรา 29"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๙ การใด ๆ อันบุคคลซึ่งศาลสั่งให้เป็นคนไร้ความสามารถได้กระทำลง การนั้นเป็นโมฆียะ"}},{"id":"TH-H004-A30","no":30,"noLabel":{"th":"มาตรา 30"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๐ การใด ๆ อันบุคคลวิกลจริตซึ่งศาลยังมิได้สั่งให้เป็นคนไร้ความสามารถได้กระทำลง การนั้นจะเป็นโมฆียะต่อเมื่อได้กระทำในขณะที่บุคคลนั้นจริตวิกลอยู่ และคู่กรณีอีกฝ่ายหนึ่งได้รู้แล้วด้วยว่าผู้กระทำเป็นคนวิกลจริต"}},{"id":"TH-H004-A31","no":31,"noLabel":{"th":"มาตรา 31"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๑ ถ้าเหตุที่ทำให้เป็นคนไร้ความสามารถได้สิ้นสุดไปแล้ว และเมื่อบุคคลผู้นั้นเองหรือบุคคลใด ๆ ดังกล่าวมาในมาตรา ๒๘ ร้องขอต่อศาลก็ให้ศาลสั่งเพิกถอนคำสั่งที่ให้เป็นคนไร้ความสามารถนั้น คำสั่งของศาลตามมาตรานี้ ให้ประกาศในราชกิจจานุเบกษา"}},{"id":"TH-H004-A32","no":32,"noLabel":{"th":"มาตรา 32"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๒ บุคคลใดมีกายพิการหรือมีจิตฟั่นเฟือนไม่สมประกอบ หรือประพฤติสุรุ่ยสุร่าย เสเพลเป็นอาจิณ หรือติดสุรายาเมา หรือมีเหตุอื่นใดทำนองเดียวกันนั้น จนไม่สามารถจะจัดทำการงานโดยตนเองได้ หรือจัดกิจการไปในทางที่อาจจะเสื่อมเสียแก่ทรัพย์สินของตนเองหรือครอบครัว เมื่อบุคคลตามที่ระบุไว้ในมาตรา ๒๘ ร้องขอต่อศาล ศาลจะสั่งให้บุคคลนั้นเป็นคนเสมือนไร้ความสามารถก็ได้ บุคคลซึ่งศาลได้สั่งให้เป็นคนเสมือนไร้ความสามารถตามวรรคหนึ่ง ต้องจัดให้อยู่ในความพิทักษ์ การแต่งตั้งผู้พิทักษ์ ให้เป็นไปตามบทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายนี้ ให้นำบทบัญญัติว่าด้วยการสิ้นสุดของความเป็นผู้ปกครองในบรรพ ๕ แห่งประมวลกฎหมายนี้มาใช้บังคับแก่การสิ้นสุดของการเป็นผู้พิทักษ์โดยอนุโลม คำสั่งของศาลตามมาตรานี้ ให้ประกาศในราชกิจจานุเบกษา"}},{"id":"TH-H004-A33","no":33,"noLabel":{"th":"มาตรา 33"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๓ ในคดีที่มีการร้องขอให้ศาลสั่งให้บุคคลใดเป็นคนไร้ความสามารถเพราะวิกลจริต ถ้าทางพิจารณาได้ความว่าบุคคลนั้นไม่วิกลจริต แต่มีจิตฟั่นเฟือนไม่สมประกอบ เมื่อศาลเห็นสมควรหรือเมื่อมีคำขอของคู่ความหรือของบุคคลตามที่ระบุไว้ในมาตรา ๒๘ ศาลอาจสั่งให้บุคคลนั้นเป็นคนเสมือนไร้ความสามารถก็ได้ หรือในคดีที่มีการร้องขอให้ศาลสั่งให้บุคคลใดเป็นคนเสมือนไร้ความสามารถเพราะมีจิตฟั่นเฟือนไม่สมประกอบ ถ้าทางพิจารณาได้ความว่าบุคคลนั้นวิกลจริต เมื่อมีคำขอของคู่ความหรือของบุคคลตามที่ระบุไว้ในมาตรา ๒๘ ศาลอาจสั่งให้บุคคลนั้นเป็นคนไร้ความสามารถก็ได้"}},{"id":"TH-H004-A34","no":34,"noLabel":{"th":"มาตรา 34"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๔ คนเสมือนไร้ความสามารถนั้น ต้องได้รับความยินยอมของผู้พิทักษ์ก่อนแล้วจึงจะทำการอย่างหนึ่งอย่างใดดังต่อไปนี้ได้ (๑) นำทรัพย์สินไปลงทุน (๒) รับคืนทรัพย์สินที่ไปลงทุน ต้นเงินหรือทุนอย่างอื่น (๓) กู้ยืมหรือให้กู้ยืมเงิน ยืมหรือให้ยืมสังหาริมทรัพย์อันมีค่า (๔) รับประกันโดยประการใด ๆ อันมีผลให้ตนต้องถูกบังคับชำระหนี้ (๕) เช่าหรือให้เช่าสังหาริมทรัพย์มีกำหนดระยะเวลาเกินกว่าหกเดือน หรืออสังหาริมทรัพย์มีกำหนดระยะเวลาเกินกว่าสามปี (๖) ให้โดยเสน่หา เว้นแต่การให้ที่พอควรแก่ฐานานุรูป เพื่อการกุศล การสังคมหรือตามหน้าที่ธรรมจรรยา (๗) รับการให้โดยเสน่หาที่มีเงื่อนไขหรือค่าภาระติดพัน หรือไม่รับการให้โดยเสน่หา (๘) ทำการอย่างหนึ่งอย่างใดเพื่อจะได้มาหรือปล่อยไปซึ่งสิทธิในอสังหาริมทรัพย์ หรือในสังหาริมทรัพย์อันมีค่า (๙) ก่อสร้างหรือดัดแปลงโรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น หรือซ่อมแซมอย่างใหญ่ (๑๐) เสนอคดีต่อศาลหรือดำเนินกระบวนพิจารณาใด ๆ เว้นแต่การร้องขอตามมาตรา ๓๕ หรือการร้องขอถอนผู้พิทักษ์ (๑๑) ประนีประนอมยอมความหรือมอบข้อพิพาทให้อนุญาโตตุลาการวินิจฉัย ถ้ามีกรณีอื่นใดนอกจากที่กล่าวในวรรคหนึ่ง ซึ่งคนเสมือนไร้ความสามารถอาจจัดการไปในทางเสื่อมเสียแก่ทรัพย์สินของตนเองหรือครอบครัว ในการสั่งให้บุคคลใดเป็นคนเสมือนไร้ความสามารถ หรือเมื่อผู้พิทักษ์ร้องขอในภายหลัง ศาลมีอำนาจสั่งให้คนเสมือนไร้ความสามารถนั้นต้องได้รับความยินยอมของผู้พิทักษ์ก่อนจึงจะทำการนั้นได้ ในกรณีที่คนเสมือนไร้ความสามารถไม่สามารถจะทำการอย่างหนึ่งอย่างใดที่กล่าวมาในวรรคหนึ่งหรือวรรคสองได้ด้วยตนเอง เพราะเหตุมีกายพิการหรือมีจิตฟั่นเฟือนไม่สมประกอบ ศาลจะสั่งให้ผู้พิทักษ์เป็นผู้มีอำนาจกระทำการนั้นแทนคนเสมือนไร้ความสามารถก็ได้ ในกรณีเช่นนี้ ให้นำบทบัญญัติที่เกี่ยวกับผู้อนุบาลมาใช้บังคับแก่ผู้พิทักษ์โดยอนุโลม คำสั่งของศาลตามมาตรานี้ ให้ประกาศในราชกิจจานุเบกษา การใดกระทำลงโดยฝ่าฝืนบทบัญญัติมาตรานี้ การนั้นเป็นโมฆียะ"}},{"id":"TH-H004-A35","no":35,"noLabel":{"th":"มาตรา 35"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๕ ในกรณีที่ผู้พิทักษ์ไม่ยินยอมให้คนเสมือนไร้ความสามารถกระทำการอย่างหนึ่งอย่างใดตามมาตรา ๓๔ โดยปราศจากเหตุผลอันสมควร เมื่อคนเสมือนไร้ความสามารถร้องขอ ศาลจะมีคำสั่งอนุญาตให้กระทำการนั้นโดยไม่ต้องรับความยินยอมจากผู้พิทักษ์ก็ได้ ถ้าการนั้นจะเป็นคุณประโยชน์แก่คนเสมือนไร้ความสามารถ"}},{"id":"TH-H004-A36","no":36,"noLabel":{"th":"มาตรา 36"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๖ ถ้าเหตุที่ศาลได้สั่งให้เป็นคนเสมือนไร้ความสามารถได้สิ้นสุดไปแล้ว ให้นำบทบัญญัติมาตรา ๓๑ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A37","no":37,"noLabel":{"th":"มาตรา 37"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๗ ภูมิลำเนาของบุคคลธรรมดา ได้แก่ถิ่นอันบุคคลนั้นมีสถานที่อยู่เป็นแหล่งสำคัญ"}},{"id":"TH-H004-A38","no":38,"noLabel":{"th":"มาตรา 38"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๘ ถ้าบุคคลธรรมดามีถิ่นที่อยู่หลายแห่งซึ่งอยู่สับเปลี่ยนกันไปหรือมีหลักแหล่งที่ทำการงานเป็นปกติหลายแห่ง ให้ถือเอาแห่งใดแห่งหนึ่งเป็นภูมิลำเนาของบุคคลนั้น"}},{"id":"TH-H004-A39","no":39,"noLabel":{"th":"มาตรา 39"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๙ ถ้าภูมิลำเนาไม่ปรากฏ ให้ถือว่าถิ่นที่อยู่เป็นภูมิลำเนา"}},{"id":"TH-H004-A40","no":40,"noLabel":{"th":"มาตรา 40"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๐ บุคคลธรรมดาซึ่งเป็นผู้ไม่มีที่อยู่ปกติเป็นหลักแหล่ง หรือเป็นผู้ครองชีพในการเดินทางไปมาปราศจากหลักแหล่งที่ทำการงาน พบตัวในถิ่นไหนให้ถือว่าถิ่นนั้นเป็นภูมิลำเนาของบุคคลนั้น"}},{"id":"TH-H004-A41","no":41,"noLabel":{"th":"มาตรา 41"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๑ ภูมิลำเนาย่อมเปลี่ยนไปด้วยการย้ายถิ่นที่อยู่ พร้อมด้วยเจตนาปรากฏชัดแจ้งว่าจะเปลี่ยนภูมิลำเนา"}},{"id":"TH-H004-A42","no":42,"noLabel":{"th":"มาตรา 42"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๒ ถ้าบุคคลใดได้เลือกเอาถิ่นใด โดยมีเจตนาปรากฏชัดแจ้งว่าจะให้เป็นภูมิลำเนาเฉพาะการเพื่อทำการใด ให้ถือว่าถิ่นนั้นเป็นภูมิลำเนาเฉพาะการสำหรับการนั้น"}},{"id":"TH-H004-A43","no":43,"noLabel":{"th":"มาตรา 43"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๓ ภูมิลำเนาของคู่สมรส ได้แก่ถิ่นที่อยู่ที่คู่สมรสอยู่กินด้วยกันฉันคู่สมรส เว้นแต่คู่สมรสฝ่ายใดได้แสดงเจตนาให้ปรากฏว่ามีภูมิลำเนาแยกต่างหากจากกัน"}},{"id":"TH-H004-A44","no":44,"noLabel":{"th":"มาตรา 44"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๔ ภูมิลำเนาของผู้เยาว์ ได้แก่ภูมิลำเนาของผู้แทนโดยชอบธรรมซึ่งเป็นผู้ใช้อำนาจปกครองหรือผู้ปกครอง ในกรณีที่ผู้เยาว์อยู่ใต้อำนาจปกครองของบิดามารดา ถ้าบิดาและมารดามีภูมิลำเนาแยกต่างหากจากกัน ภูมิลำเนาของผู้เยาว์ได้แก่ภูมิลำเนาของบิดาหรือมารดาซึ่งตนอยู่ด้วย"}},{"id":"TH-H004-A45","no":45,"noLabel":{"th":"มาตรา 45"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๕ ภูมิลำเนาของคนไร้ความสามารถ ได้แก่ภูมิลำเนาของผู้อนุบาล"}},{"id":"TH-H004-A46","no":46,"noLabel":{"th":"มาตรา 46"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๖ ภูมิลำเนาของข้าราชการ ได้แก่ถิ่นอันเป็นที่ทำการตามตำแหน่งหน้าที่ หากมิใช่เป็นตำแหน่งหน้าที่ชั่วคราวชั่วระยะเวลาหรือเป็นเพียงแต่งตั้งไปเฉพาะการครั้งเดียวคราวเดียว"}},{"id":"TH-H004-A47","no":47,"noLabel":{"th":"มาตรา 47"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗ ภูมิลำเนาของผู้ที่ถูกจำคุกตามคำพิพากษาถึงที่สุดของศาลหรือตามคำสั่งโดยชอบด้วยกฎหมาย ได้แก่เรือนจำหรือทัณฑสถานที่ถูกจำคุกอยู่ จนกว่าจะได้รับการปล่อยตัว"}},{"id":"TH-H004-A48","no":48,"noLabel":{"th":"มาตรา 48"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๔๘ ถ้าบุคคลใดไปเสียจากภูมิลำเนาหรือถิ่นที่อยู่โดยมิได้ตั้งตัวแทนผู้รับมอบอำนาจทั่วไปไว้ และไม่มีใครรู้แน่ว่าบุคคลนั้นยังมีชีวิตอยู่หรือไม่ เมื่อผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอ ศาลจะสั่งให้ทำการอย่างหนึ่งอย่างใดไปพลางก่อนตามที่จำเป็นเพื่อจัดการทรัพย์สินของบุคคลผู้ไม่อยู่นั้นก็ได้ เมื่อเวลาได้ล่วงเลยไปหนึ่งปีนับแต่วันที่ผู้ไม่อยู่นั้นไปเสียจากภูมิลำเนาหรือถิ่นที่อยู่ และไม่มีผู้ใดได้รับข่าวเกี่ยวกับบุคคลนั้นประการใดเลยก็ดี หรือหนึ่งปีนับแต่วันมีผู้ได้พบเห็นหรือได้ทราบข่าวมาเป็นครั้งหลังสุดก็ดี เมื่อบุคคลตามวรรคหนึ่งร้องขอ ศาลจะตั้งผู้จัดการทรัพย์สินของผู้ไม่อยู่ขึ้นก็ได้"}},{"id":"TH-H004-A49","no":49,"noLabel":{"th":"มาตรา 49"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๔๙ ในกรณีที่ผู้ไม่อยู่ได้ตั้งตัวแทนผู้รับมอบอำนาจทั่วไปไว้ และสัญญาตัวแทนระงับสิ้นไป หรือปรากฏว่าตัวแทนผู้รับมอบอำนาจทั่วไปได้จัดการทรัพย์สินนั้นในลักษณะที่อาจเสียหายแก่บุคคลดังกล่าว ให้นำมาตรา ๔๘ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A50","no":50,"noLabel":{"th":"มาตรา 50"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๐ เมื่อผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอ ศาลจะสั่งให้ตัวแทนผู้รับมอบอำนาจทั่วไปจัดทำบัญชีทรัพย์สินของผู้ไม่อยู่ขึ้นตามที่ศาลจะมีคำสั่งก็ได้"}},{"id":"TH-H004-A51","no":51,"noLabel":{"th":"มาตรา 51"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๑ ภายใต้บังคับมาตรา ๘๐๒ ถ้าตัวแทนผู้รับมอบอำนาจทั่วไปเห็นเป็นการจำเป็นจะต้องทำการอันใดอันหนึ่งเกินขอบอำนาจที่ได้รับไว้ ต้องขออนุญาตต่อศาล และเมื่อศาลสั่งอนุญาตแล้วจึงจะกระทำการนั้นได้"}},{"id":"TH-H004-A52","no":52,"noLabel":{"th":"มาตรา 52"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๒ ผู้จัดการทรัพย์สินที่ศาลได้ตั้งขึ้น ต้องทำบัญชีทรัพย์สินของผู้ไม่อยู่ให้เสร็จภายในสามเดือนนับแต่วันทราบคำสั่งตั้งของศาล แต่ผู้จัดการทรัพย์สินจะร้องขอต่อศาลให้ขยายเวลาก็ได้"}},{"id":"TH-H004-A53","no":53,"noLabel":{"th":"มาตรา 53"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๓ บัญชีทรัพย์สินตามมาตรา ๕๐ และมาตรา ๕๒ ต้องมีพยานลงลายมือชื่อรับรองความถูกต้องอย่างน้อยสองคน พยานสองคนนั้นต้องเป็นคู่สมรสหรือญาติของผู้ไม่อยู่ซึ่งบรรลุนิติภาวะแล้ว แต่ถ้าไม่มีคู่สมรสหรือหาญาติไม่ได้ หรือคู่สมรสและญาติไม่ยอมเป็นพยาน จะให้ผู้อื่นซึ่งบรรลุนิติภาวะแล้วเป็นพยานก็ได้"}},{"id":"TH-H004-A54","no":54,"noLabel":{"th":"มาตรา 54"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๔ ผู้จัดการทรัพย์สินมีอำนาจหน้าที่อย่างเดียวกับตัวแทนผู้รับมอบอำนาจทั่วไปตามมาตรา ๘๐๑ และมาตรา ๘๐๒ ถ้าผู้จัดการทรัพย์สินเห็นเป็นการจำเป็นจะต้องทำการอันใดอันหนึ่งเกินขอบอำนาจ ต้องขออนุญาตต่อศาล และเมื่อศาลสั่งอนุญาตแล้วจึงจะกระทำการนั้นได้"}},{"id":"TH-H004-A55","no":55,"noLabel":{"th":"มาตรา 55"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๕ ถ้าผู้ไม่อยู่ได้ตั้งตัวแทนผู้รับมอบอำนาจเฉพาะการอันใดไว้ ผู้จัดการทรัพย์สินจะเข้าไปเกี่ยวข้องกับการอันเป็นอำนาจเฉพาะการนั้นไม่ได้ แต่ถ้าปรากฏว่าการที่ตัวแทนจัดทำอยู่นั้นอาจจะเสียหายแก่ผู้ไม่อยู่ ผู้จัดการทรัพย์สินจะร้องขอให้ศาลถอดถอนตัวแทนนั้นเสียก็ได้"}},{"id":"TH-H004-A56","no":56,"noLabel":{"th":"มาตรา 56"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๖ เมื่อผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอ หรือเมื่อศาลเห็นสมควร ศาลอาจสั่งอย่างหนึ่งอย่างใดดังต่อไปนี้ (๑) ให้ผู้จัดการทรัพย์สินหาประกันอันสมควรในการจัดการทรัพย์สินของผู้ไม่อยู่ตลอดจนการมอบคืนทรัพย์สินนั้น (๒) ให้ผู้จัดการทรัพย์สินแถลงถึงความเป็นอยู่แห่งทรัพย์สินของผู้ไม่อยู่ (๓) ถอดถอนผู้จัดการทรัพย์สิน และตั้งผู้อื่นให้เป็นผู้จัดการทรัพย์สินแทนต่อไป"}},{"id":"TH-H004-A57","no":57,"noLabel":{"th":"มาตรา 57"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๗ ในคำสั่งตั้งผู้จัดการทรัพย์สิน ศาลจะกำหนดบำเหน็จให้แก่ผู้จัดการทรัพย์สินโดยจ่ายจากทรัพย์สินของผู้ไม่อยู่นั้นก็ได้ ถ้าศาลมิได้กำหนด ผู้จัดการทรัพย์สินจะร้องขอต่อศาลให้กำหนดบำเหน็จในภายหลังก็ได้ ถ้าผู้จัดการทรัพย์สิน หรือผู้มีส่วนได้เสีย หรือพนักงานอัยการร้องขอ หรือเมื่อมีกรณีปรากฏแก่ศาลว่า พฤติการณ์เกี่ยวกับการจัดการทรัพย์สินได้เปลี่ยนแปลงไป ศาลจะสั่งกำหนด บำเหน็จ งด ลด เพิ่ม หรือกลับให้บำเหน็จแก่ผู้จัดการทรัพย์สินอีกก็ได้"}},{"id":"TH-H004-A58","no":58,"noLabel":{"th":"มาตรา 58"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๘ ความเป็นผู้จัดการทรัพย์สินย่อมสิ้นสุดลงในกรณีดังต่อไปนี้ (๑) ผู้ไม่อยู่นั้นกลับมา (๒) ผู้ไม่อยู่นั้นมิได้กลับมาแต่ได้จัดการทรัพย์สินหรือตั้งตัวแทนเพื่อจัดการทรัพย์สินของตนแล้ว (๓) ผู้ไม่อยู่ถึงแก่ความตายหรือศาลมีคำสั่งให้เป็นคนสาบสูญ (๔) ผู้จัดการทรัพย์สินลาออกหรือถึงแก่ความตาย (๕) ผู้จัดการทรัพย์สินเป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ (๖) ผู้จัดการทรัพย์สินเป็นบุคคลล้มละลาย (๗) ศาลถอดถอนผู้จัดการทรัพย์สิน"}},{"id":"TH-H004-A59","no":59,"noLabel":{"th":"มาตรา 59"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๕๙ ในกรณีที่ความเป็นผู้จัดการทรัพย์สินสิ้นสุดลงเพราะเหตุตามมาตรา ๕๘ (๔) (๕) หรือ (๖) ผู้จัดการทรัพย์สินหรือทายาทของผู้จัดการทรัพย์สิน ผู้จัดการมรดก ผู้อนุบาล ผู้พิทักษ์ เจ้าพนักงานพิทักษ์ทรัพย์ หรือผู้มีหน้าที่ดูแลทรัพย์สินของผู้จัดการทรัพย์สิน แล้วแต่กรณี จะต้องแถลงให้ศาลทราบถึงความสิ้นสุดนั้นโดยไม่ชักช้าเพื่อศาลจะได้มีคำสั่งเกี่ยวกับผู้จัดการทรัพย์สินต่อไปตามที่เห็นสมควร ในระหว่างเวลาดังกล่าวนั้น บุคคลดังกล่าวจะต้องจัดการตามควรแก่พฤติการณ์เพื่อรักษาประโยชน์ของผู้ไม่อยู่ จนกว่าจะได้ส่งมอบทรัพย์สินของผู้ไม่อยู่ให้แก่บุคคลหนึ่งบุคคลใดตามที่ศาลจะได้มีคำสั่ง"}},{"id":"TH-H004-A60","no":60,"noLabel":{"th":"มาตรา 60"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๖๐ ให้นำบทบัญญัติว่าด้วยตัวแทนแห่งประมวลกฎหมายนี้ มาใช้บังคับแก่การจัดการทรัพย์สินของผู้ไม่อยู่โดยอนุโลม"}},{"id":"TH-H004-A61","no":61,"noLabel":{"th":"มาตรา 61"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๖๑ ถ้าบุคคลใดได้ไปจากภูมิลำเนาหรือถิ่นที่อยู่ และไม่มีใครรู้แน่ว่าบุคคลนั้นยังมีชีวิตอยู่หรือไม่ตลอดระยะเวลาห้าปี เมื่อผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอ ศาลจะสั่งให้บุคคลนั้นเป็นคนสาบสูญก็ได้ ระยะเวลาตามวรรคหนึ่งให้ลดเหลือสองปี (๑) นับแต่วันที่การรบหรือสงครามสิ้นสุดลง ถ้าบุคคลนั้นอยู่ในการรบหรือสงคราม และหายไปในการรบหรือสงครามดังกล่าว (๒) นับแต่วันที่ยานพาหนะที่บุคคลนั้นเดินทาง อับปาง ถูกทำลาย หรือสูญหายไป (๓) นับแต่วันที่เหตุอันตรายแก่ชีวิตนอกจากที่ระบุไว้ใน (๑) หรือ (๒) ได้ผ่านพ้นไป ถ้าบุคคลนั้นตกอยู่ในอันตรายเช่นว่านั้น"}},{"id":"TH-H004-A62","no":62,"noLabel":{"th":"มาตรา 62"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๖๒ บุคคลซึ่งศาลได้มีคำสั่งให้เป็นคนสาบสูญ ให้ถือว่าถึงแก่ความตายเมื่อครบกำหนดระยะเวลาดังที่ระบุไว้ในมาตรา ๖๑"}},{"id":"TH-H004-A63","no":63,"noLabel":{"th":"มาตรา 63"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๖๓ เมื่อบุคคลผู้ถูกศาลสั่งให้เป็นคนสาบสูญนั้นเองหรือผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอต่อศาล และพิสูจน์ได้ว่าบุคคลผู้ถูกศาลสั่งให้เป็นคนสาบสูญนั้นยังคงมีชีวิตอยู่ก็ดี หรือว่าตายในเวลาอื่นผิดไปจากเวลาดังระบุไว้ในมาตรา ๖๒ ก็ดี ให้ศาลสั่งถอนคำสั่งให้เป็นคนสาบสูญนั้นแต่การถอนคำสั่งนี้ย่อมไม่กระทบกระเทือนถึงความสมบูรณ์แห่งการทั้งหลายอันได้ทำไปโดยสุจริตในระหว่างเวลาตั้งแต่ศาลมีคำสั่งให้เป็นคนสาบสูญจนถึงเวลาถอนคำสั่งนั้น บุคคลผู้ได้ทรัพย์สินมาเนื่องแต่การที่ศาลสั่งให้บุคคลใดเป็นคนสาบสูญ แต่ต้องเสียสิทธิของตนไปเพราะศาลสั่งถอนคำสั่งให้บุคคลนั้นเป็นคนสาบสูญ ให้นำบทบัญญัติว่าด้วยลาภมิควรได้แห่งประมวลกฎหมายนี้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A64","no":64,"noLabel":{"th":"มาตรา 64"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๖๔ ถ้ามีคดีฟ้องขอให้ศาลแสดงว่าการสมรสเป็นโมฆะ เพราะเหตุสมรสฝ่าฝืนบทบัญญัติมาตรา ๑๔๕๒ แห่งประมวลกฎหมายแพ่งและพาณิชย์ค้างพิจารณาอยู่ในศาลใดในวันที่พระราชบัญญัตินี้ใช้บังคับ ให้ศาลนั้นพิจารณาพิพากษาคดีต่อไปได้จนกว่าคดีจะถึงที่สุด"}},{"id":"TH-H004-A65","no":65,"noLabel":{"th":"มาตรา 65"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๖๕ ในกรณีที่มีการสมรสฝ่าฝืนมาตรา ๑๔๕๒ แห่งประมวลกฎหมายแพ่งและพาณิชย์ สิทธิเรียกค่าเลี้ยงชีพหรือสิทธิในมรดกของคู่สมรสที่ตายซึ่งคู่สมรสอีกฝ่ายหนึ่งที่สมรสโดยสุจริตมีอยู่แล้วก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ ให้เป็นไปตามมาตรา ๑๔๙๙ แห่งประมวลกฎหมายแพ่งและพาณิชย์ก่อนการแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้"}},{"id":"TH-H004-A66","no":66,"noLabel":{"th":"มาตรา 66"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๖๖ ในการจดทะเบียนเด็กเป็นบุตรชอบด้วยกฎหมายถ้าเจ้าหน้าที่ได้ส่งแจ้งความการขอจดทะเบียนไปยังเด็กหรือมารดาเด็กแล้ว แต่ยังไม่มีการจดทะเบียนก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ การจดทะเบียนเด็กเป็นบุตรชอบด้วยกฎหมายให้บังคับตามบทบัญญัติแห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้"}},{"id":"TH-H004-A67","no":67,"noLabel":{"th":"มาตรา 67"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๖๗ บรรดาบทบัญญัติแห่งกฎหมาย กฎ ระเบียบ ข้อบังคับ ข้อกำหนด ข้อบัญญัติ ประกาศ คำสั่ง หรือมติคณะรัฐมนตรีใดที่อ้างถึงสามี ภริยา หรือสามีภริยา ให้ถือว่าอ้างถึงคู่สมรสที่จดทะเบียนสมรสตามประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ด้วย ความในวรรคหนึ่งมิให้นำมาใช้บังคับแก่กรณีที่บทบัญญัติแห่งกฎหมาย กฎ ระเบียบ ข้อบังคับ ข้อกำหนด ข้อบัญญัติ ประกาศ คำสั่ง หรือมติคณะรัฐมนตรีกำหนดสิทธิ หน้าที่ สถานะทางกฎหมาย หรือเรื่องอื่นใดที่เกี่ยวข้องกับสามี ภริยา หรือสามีภริยาไว้แตกต่างกัน"}},{"id":"TH-H004-A68","no":68,"noLabel":{"th":"มาตรา 68"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๖๘ ให้หน่วยงานของรัฐที่รับผิดชอบการประเมินผลสัมฤทธิ์ตามกฎหมายว่าด้วยหลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย ดำเนินการทบทวนกฎหมายในความรับผิดชอบที่กำหนดสิทธิ หน้าที่ สถานะทางกฎหมาย หรือเรื่องอื่นใดที่เกี่ยวข้องกับสามี ภริยา สามีภริยา หรือคู่สมรส เพื่อรองรับสิทธิ หน้าที่ สถานะทางกฎหมาย หรือเรื่องอื่นใดที่เกี่ยวข้องให้แก่คู่สมรสตามประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้โดยต้องพิจารณาให้เหมาะสมกับเพศสภาพของคู่สมรสด้วย ให้หน่วยงานของรัฐที่ดำเนินการทบทวนตามวรรคหนึ่ง เสนอผลการทบทวนพร้อมทั้งร่างกฎหมายในกรณีที่ต้องมีการแก้ไขเพิ่มเติมกฎหมาย ต่อคณะรัฐมนตรีภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ หากไม่สามารถดำเนินการได้ให้รายงานเหตุผลที่ไม่อาจดำเนินการได้ต่อคณะรัฐมนตรีเพื่อทราบ"}},{"id":"TH-H004-A69","no":69,"noLabel":{"th":"มาตรา 69"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๖๙ บทบัญญัติมาตรา ๑๕๙๘/๒๒ และมาตรา ๑๕๙๘/๒๓ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ไม่กระทบกระเทือนถึงความสมบูรณ์ของการให้ความยินยอมในการรับเด็กเป็นบุตรบุญธรรมที่ได้กระทำไปแล้วก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ"}},{"id":"TH-H004-A70","no":70,"noLabel":{"th":"มาตรา 70"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๐ บทบัญญัติบรรพ ๕ แห่งประมวลกฎหมายแพ่งและพาณิชย์ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้ไม่กระทบกระเทือนถึงความสมบูรณ์ของการหมั้น การสมรส สัญญาก่อนสมรส การเป็นบิดามารดากับบุตร การเป็นผู้ปกครอง และการรับบุตรบุญธรรมที่ได้มีอยู่แล้วในวันที่พระราชบัญญัตินี้ใช้บังคับ เว้นแต่ในกรณีที่พระราชบัญญัตินี้บัญญัติไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A71","no":71,"noLabel":{"th":"มาตรา 71"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๑ บรรดาอายุความหรือระยะเวลาที่บทบัญญัติในประมวลกฎหมายแพ่งและพาณิชย์ได้กำหนดไว้ก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ หากยังไม่สิ้นสุดลงในวันที่พระราชบัญญัตินี้ใช้บังคับ และอายุความหรือระยะเวลาที่กำหนดขึ้นใหม่นั้นแตกต่างกับอายุความหรือระยะเวลาที่กำหนดไว้เดิม ก็ให้นำอายุความหรือระยะเวลาที่ยาวกว่ามาบังคับ"}},{"id":"TH-H004-A72","no":72,"noLabel":{"th":"มาตรา 72"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๒ การเปลี่ยนตัวผู้แทนของนิติบุคคล หรือการจำกัดหรือแก้ไข เปลี่ยนแปลงอำนาจของผู้แทนของนิติบุคคล ให้มีผลต่อเมื่อได้ปฏิบัติตามกฎหมาย ข้อบังคับหรือตราสารจัดตั้งแล้ว แต่จะยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริตมิได้"}},{"id":"TH-H004-A73","no":73,"noLabel":{"th":"มาตรา 73"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๓ ถ้ามีตำแหน่งว่างลงในจำนวนผู้แทนของนิติบุคคล และมีเหตุอันควรเชื่อว่าการปล่อยตำแหน่งว่างไว้น่าจะเกิดความเสียหายขึ้นได้ เมื่อผู้มีส่วนได้เสียหรือพนักงานอัยการร้องขอศาลจะแต่งตั้งผู้แทนชั่วคราวขึ้นก็ได้"}},{"id":"TH-H004-A74","no":74,"noLabel":{"th":"มาตรา 74"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๔ ถ้าประโยชน์ได้เสียของนิติบุคคลขัดกับประโยชน์ได้เสียของผู้แทนของนิติบุคคลในการอันใด ผู้แทนของนิติบุคคลนั้นจะเป็นผู้แทนในการอันนั้นไม่ได้"}},{"id":"TH-H004-A75","no":75,"noLabel":{"th":"มาตรา 75"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๕ ถ้ากรณีตามมาตรา ๗๔ เป็นเหตุให้ไม่มีผู้แทนของนิติบุคคลเหลืออยู่ หรือผู้แทนของนิติบุคคลที่เหลืออยู่มีจำนวนไม่พอจะเป็นองค์ประชุม หรือไม่พอจะกระทำการอันนั้นได้ หากกฎหมาย ข้อบังคับ หรือตราสารจัดตั้งของนิติบุคคลนั้น มิได้มีข้อกำหนดในเรื่องนี้ไว้เป็นอย่างอื่น ให้นำความในมาตรา ๗๓ มาใช้บังคับเพื่อตั้งผู้แทนเฉพาะการโดยอนุโลม"}},{"id":"TH-H004-A76","no":76,"noLabel":{"th":"มาตรา 76"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๖ ถ้าการกระทำตามหน้าที่ของผู้แทนของนิติบุคคลหรือผู้มีอำนาจทำการแทนนิติบุคคล เป็นเหตุให้เกิดความเสียหายแก่บุคคลอื่น นิติบุคคลนั้นต้องรับผิดชดใช้ค่าสินไหมทดแทนเพื่อความเสียหายนั้น แต่ไม่สูญเสียสิทธิที่จะไล่เบี้ยเอาแก่ผู้ก่อความเสียหาย ถ้าความเสียหายแก่บุคคลอื่นเกิดจากการกระทำที่ไม่อยู่ในขอบวัตถุประสงค์หรืออำนาจหน้าที่ของนิติบุคคล บรรดาบุคคลดังกล่าวตามวรรคหนึ่งที่ได้เห็นชอบให้กระทำการนั้นหรือได้เป็นผู้กระทำการดังกล่าว ต้องร่วมกันรับผิดชดใช้ค่าสินไหมทดแทนแก่ผู้ที่ได้รับความเสียหายนั้น"}},{"id":"TH-H004-A77","no":77,"noLabel":{"th":"มาตรา 77"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๗๗ ให้นำบทบัญญัติว่าด้วยตัวแทนแห่งประมวลกฎหมายนี้ มาใช้บังคับแก่ความเกี่ยวพันระหว่างนิติบุคคลกับผู้แทนของนิติบุคคล และระหว่างนิติบุคคล หรือผู้แทนของนิติบุคคลกับบุคคลภายนอก โดยอนุโลม"}},{"id":"TH-H004-A78","no":78,"noLabel":{"th":"มาตรา 78"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๗๘ การก่อตั้งสมาคมเพื่อกระทำการใด ๆ อันมีลักษณะต่อเนื่องร่วมกันและมิใช่เป็นการหาผลกำไรหรือรายได้มาแบ่งปันกัน ต้องมีข้อบังคับและจดทะเบียนตามบทบัญญัติแห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A79","no":79,"noLabel":{"th":"มาตรา 79"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๗๙ ข้อบังคับของสมาคมอย่างน้อยต้องมีรายการดังต่อไปนี้ (๑) ชื่อสมาคม (๒) วัตถุประสงค์ของสมาคม (๓) ที่ตั้งสำนักงานใหญ่ และที่ตั้งสำนักงานสาขาทั้งปวง (๔) วิธีรับสมาชิก และการขาดจากสมาชิกภาพ (๕) อัตราค่าบำรุง (๖) ข้อกำหนดเกี่ยวกับคณะกรรมการของสมาคม ได้แก่ จำนวนกรรมการ การตั้งกรรมการ วาระการดำรงตำแหน่งของกรรมการ การพ้นจากตำแหน่งของกรรมการ และการประชุมของคณะกรรมการ (๗) ข้อกำหนดเกี่ยวกับการจัดการสมาคม การบัญชี และทรัพย์สินของสมาคม (๘) ข้อกำหนดเกี่ยวกับการประชุมใหญ่"}},{"id":"TH-H004-A80","no":80,"noLabel":{"th":"มาตรา 80"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๐ สมาคมต้องใช้ชื่อซึ่งมีคำว่า “สมาคม” ประกอบกับชื่อของสมาคม"}},{"id":"TH-H004-A81","no":81,"noLabel":{"th":"มาตรา 81"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๑ การขอจดทะเบียนสมาคมนั้น ให้ผู้จะเป็นสมาชิกของสมาคมจำนวนไม่น้อยกว่าสามคน ร่วมกันยื่นคำขอเป็นหนังสือต่อนายทะเบียนแห่งท้องที่ที่สำนักงานใหญ่ของสมาคมจะตั้งขึ้น พร้อมกับแนบข้อบังคับของสมาคม รายชื่อ ที่อยู่ และอาชีพของผู้จะเป็นสมาชิกไม่น้อยกว่าสิบคน และรายชื่อ ที่อยู่ และอาชีพของผู้จะเป็นกรรมการของสมาคมมากับคำขอด้วย"}},{"id":"TH-H004-A82","no":82,"noLabel":{"th":"มาตรา 82"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๒ เมื่อนายทะเบียนได้รับคำขอจดทะเบียนพร้อมทั้งข้อบังคับแล้วเห็นว่าคำขอนั้นถูกต้องตามมาตรา ๘๑ และข้อบังคับถูกต้องตามมาตรา ๗๙ และวัตถุประสงค์ของสมาคมไม่ขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรือไม่เป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ และรายการซึ่งจดแจ้งในคำขอหรือข้อบังคับสอดคล้องกับวัตถุประสงค์ของสมาคมและผู้จะเป็นกรรมการของสมาคมนั้นมีฐานะและความประพฤติเหมาะสมในการดำเนินการตามวัตถุประสงค์ของสมาคม ให้นายทะเบียนรับจดทะเบียนและออกใบสำคัญแสดงการจดทะเบียนให้แก่สมาคมนั้น และประกาศการจัดตั้งสมาคมในราชกิจจานุเบกษา ถ้านายทะเบียนเห็นว่าคำขอหรือข้อบังคับไม่ถูกต้องตามมาตรา ๘๑ หรือมาตรา ๗๙ หรือรายการซึ่งจดแจ้งในคำขอหรือข้อบังคับไม่สอดคล้องกับวัตถุประสงค์ของสมาคม หรือผู้จะเป็นกรรมการของสมาคมมีฐานะหรือความประพฤติไม่เหมาะสมในการดำเนินการตามวัตถุประสงค์ของสมาคม ให้มีคำสั่งให้ผู้ยื่นคำขอจดทะเบียนแก้ไขหรือเปลี่ยนแปลงให้ถูกต้อง เมื่อแก้ไขหรือเปลี่ยนแปลงถูกต้องแล้ว ให้รับจดทะเบียนและออกใบสำคัญแสดงการจดทะเบียนให้และสมาคมนั้น ถ้านายทะเบียนเห็นว่าไม่อาจรับจดทะเบียนได้เนื่องจากวัตถุประสงค์ของสมาคมขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรืออาจเป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ หรือผู้ยื่นคำขอจดทะเบียนไม่แก้ไขหรือเปลี่ยนแปลงให้ถูกต้องภายในสามสิบวันนับแต่วันที่ทราบคำสั่งของนายทะเบียน ให้นายทะเบียนมีคำสั่งไม่รับจดทะเบียนและแจ้งคำสั่งพร้อมด้วยเหตุผลที่ไม่รับจดทะเบียนไปยังผู้ยื่นคำขอจดทะเบียนโดยมิชักช้า ผู้ยื่นคำขอจดทะเบียนมีสิทธิอุทธรณ์คำสั่งไม่รับจดทะเบียนนั้นต่อรัฐมนตรีว่าการกระทรวงมหาดไทย โดยทำเป็นหนังสือยื่นต่อนายทะเบียนภายในสามสิบวันนับแต่วันที่ได้รับแจ้งคำสั่งไม่รับจดทะเบียน ให้รัฐมนตรีว่าการกระทรวงมหาดไทยวินิจฉัยอุทธรณ์ และแจ้งคำวินิจฉัยให้ผู้อุทธรณ์ทราบภายในเก้าสิบวันนับแต่วันที่นายทะเบียนได้รับหนังสืออุทธรณ์ คำวินิจฉัยของรัฐมนตรีว่าการกระทรวงมหาดไทยให้เป็นที่สุด"}},{"id":"TH-H004-A83","no":83,"noLabel":{"th":"มาตรา 83"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๓ สมาคมที่ได้จดทะเบียนแล้วเป็นนิติบุคคล"}},{"id":"TH-H004-A84","no":84,"noLabel":{"th":"มาตรา 84"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๔ การแก้ไขเพิ่มเติมข้อบังคับของสมาคมจะกระทำได้ก็แต่โดยมติของที่ประชุมใหญ่ และสมาคมต้องนำข้อบังคับที่ได้แก้ไขเพิ่มเติมไปจดทะเบียนต่อนายทะเบียนแห่งท้องที่ที่สำนักงานใหญ่ของสมาคมตั้งอยู่ภายในสิบสี่วันนับแต่วันที่ได้ลงมติและให้นำความในมาตรา ๘๒ มาใช้บังคับโดยอนุโลม เมื่อนายทะเบียนได้จดทะเบียนแล้วให้มีผลใช้บังคับได้"}},{"id":"TH-H004-A85","no":85,"noLabel":{"th":"มาตรา 85"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๕ การแต่งตั้งกรรมการของสมาคมขึ้นใหม่ทั้งชุดหรือการเปลี่ยนแปลงกรรมการของสมาคม ให้กระทำตามข้อบังคับของสมาคม และสมาคมต้องนำไปจดทะเบียนต่อนายทะเบียนแห่งท้องที่ที่สำนักงานใหญ่ของสมาคมตั้งอยู่ภายในสามสิบวันนับแต่วันที่มีการแต่งตั้งหรือเปลี่ยนแปลงกรรมการของสมาคม ถ้านายทะเบียนเห็นว่ากรรมการของสมาคมตามวรรคหนึ่งผู้ใด มีฐานะหรือความประพฤติไม่เหมาะสมในการดำเนินการตามวัตถุประสงค์ของสมาคม นายทะเบียนจะไม่รับจดทะเบียนกรรมการของสมาคมผู้นั้นก็ได้ ในกรณีที่นายทะเบียนไม่รับจดทะเบียนกรรมการของสมาคม นายทะเบียนต้องแจ้งเหตุผลที่ไม่รับจดทะเบียนให้สมาคมทราบภายในหกสิบวันนับแต่วันที่ยื่นคำขอจดทะเบียน และให้นำความในมาตรา ๘๒ วรรคสี่และวรรคห้า มาใช้บังคับโดยอนุโลม ในระหว่างที่ยังไม่มีการจดทะเบียนกรรมการของสมาคมชุดใหม่ ถ้าข้อบังคับของสมาคมมิได้กำหนดไว้เป็นอย่างอื่น ให้กรรมการของสมาคมชุดเดิมปฏิบัติหน้าที่กรรมการของสมาคมต่อไปจนกว่าจะได้มีการจดทะเบียนกรรมการของสมาคมชุดใหม่"}},{"id":"TH-H004-A86","no":86,"noLabel":{"th":"มาตรา 86"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๖ คณะกรรมการของสมาคมเป็นผู้ดำเนินกิจการของสมาคมตามกฎหมายและข้อบังคับ ภายใต้การควบคุมดูแลของที่ประชุมใหญ่"}},{"id":"TH-H004-A87","no":87,"noLabel":{"th":"มาตรา 87"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๗ คณะกรรมการของสมาคมเป็นผู้แทนของสมาคมในกิจการอันเกี่ยวกับบุคคลภายนอก"}},{"id":"TH-H004-A88","no":88,"noLabel":{"th":"มาตรา 88"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๘ บรรดากิจการที่คณะกรรมการของสมาคมได้กระทำไป แม้จะปรากฏในภายหลังว่ามีข้อบกพร่องเกี่ยวกับการตั้งหรือคุณสมบัติของกรรมการของสมาคม กิจการนั้นย่อมมีผลสมบูรณ์"}},{"id":"TH-H004-A89","no":89,"noLabel":{"th":"มาตรา 89"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๙ สมาชิกของสมาคมมีสิทธิที่จะตรวจตรากิจการและทรัพย์สินของสมาคมในระหว่างเวลาทำการของสมาคมได้"}},{"id":"TH-H004-A90","no":90,"noLabel":{"th":"มาตรา 90"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๐ สมาชิกของสมาคมต้องชำระค่าบำรุงเต็มจำนวนในวันที่สมัครเข้าเป็นสมาชิกหรือในวันเริ่มต้นของระยะเวลาชำระค่าบำรุง แล้วแต่กรณี เว้นแต่ข้อบังคับของสมาคมจะกำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A91","no":91,"noLabel":{"th":"มาตรา 91"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๑ สมาชิกของสมาคมจะลาออกจากสมาคมเมื่อใดก็ได้ เว้นแต่ข้อบังคับของสมาคมจะกำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A92","no":92,"noLabel":{"th":"มาตรา 92"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๒ สมาชิกแต่ละคนมีความรับผิดในหนี้ของสมาคมไม่เกินจำนวนค่าบำรุงที่สมาชิกนั้นค้างชำระอยู่"}},{"id":"TH-H004-A93","no":93,"noLabel":{"th":"มาตรา 93"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓ คณะกรรมการของสมาคมต้องจัดให้มีการประชุมใหญ่สามัญอย่างน้อยปีละครั้ง"}},{"id":"TH-H004-A94","no":94,"noLabel":{"th":"มาตรา 94"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๔ คณะกรรมการของสมาคมจะเรียกประชุมใหญ่วิสามัญเมื่อใดก็สุดแต่จะเห็นสมควร สมาชิกจำนวนไม่น้อยกว่าหนึ่งในห้าของจำนวนสมาชิกทั้งหมดหรือสมาชิกจำนวนไม่น้อยกว่าหนึ่งร้อยคนหรือสมาชิกจำนวนไม่น้อยกว่าที่กำหนดไว้ในข้อบังคับจะทำหนังสือร้องขอต่อคณะกรรมการของสมาคมให้เรียกประชุมใหญ่วิสามัญก็ได้ในหนังสือร้องขอนั้น ต้องระบุว่าประสงค์ให้เรียกประชุมเพื่อการใด เมื่อคณะกรรมการของสมาคมได้รับหนังสือร้องขอให้เรียกประชุมใหญ่วิสามัญตามวรรคสอง ให้คณะกรรมการของสมาคมเรียกประชุมใหญ่วิสามัญโดยจัดให้มีการประชุมขึ้นภายในสามสิบวันนับแต่วันที่ได้รับคำร้องขอ ถ้าคณะกรรมการของสมาคมไม่เรียกประชุมภายในระยะเวลาตามวรรคสาม สมาชิกที่เป็นผู้ร้องขอให้เรียกประชุมหรือสมาชิกอื่นรวมกันมีจำนวนไม่น้อยกว่าจำนวนสมาชิกที่กำหนดตามวรรคสองจะเรียกประชุมเองก็ได้"}},{"id":"TH-H004-A95","no":95,"noLabel":{"th":"มาตรา 95"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๕ ในการเรียกประชุมใหญ่ คณะกรรมการของสมาคมต้องส่งหนังสือนัดประชุมไปยังสมาชิกทุกคนซึ่งมีชื่อในทะเบียนของสมาคมก่อนวันนัดประชุมไม่น้อยกว่าเจ็ดวันหรือลงพิมพ์โฆษณาอย่างน้อยสองคราวในหนังสือพิมพ์ที่แพร่หลายในท้องที่ฉบับหนึ่งก่อนวันนัดประชุมไม่น้อยกว่าเจ็ดวันก็ได้ การเรียกประชุมใหญ่ต้องระบุสถานที่ วัน เวลา และระเบียบวาระการประชุมและจัดส่งรายละเอียดและเอกสารที่เกี่ยวข้องตามควรไปพร้อมกันด้วย สำหรับการเรียกประชุมใหญ่โดยการพิมพ์โฆษณา รายละเอียดและเอกสารดังกล่าวต้องจัดไว้และพร้อมที่จะมอบให้แก่สมาชิกที่ร้องขอ ณ สถานที่ที่ผู้เรียกประชุมกำหนด"}},{"id":"TH-H004-A96","no":96,"noLabel":{"th":"มาตรา 96"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๖ การประชุมใหญ่ของสมาคมต้องมีสมาชิกมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนสมาชิกทั้งหมดจึงจะเป็นองค์ประชุม เว้นแต่ข้อบังคับของสมาคมจะกำหนดองค์ประชุมไว้เป็นอย่างอื่น ในการประชุมใหญ่ครั้งใด ถ้าไม่ได้องค์ประชุมตามที่กำหนดไว้และการประชุมใหญ่นั้นได้เรียกตามคำร้องขอของสมาชิก ก็ให้งดการประชุม แต่ถ้าเป็นการประชุมใหญ่ที่สมาชิกมิได้เป็นผู้ร้องขอ ให้คณะกรรมการของสมาคมเรียกประชุมใหญ่อีกครั้งหนึ่งโดยจัดให้มีการประชุมขึ้นภายในสิบสี่วันนับแต่วันที่นัดประชุมครั้งแรก การประชุมครั้งหลังนี้ไม่บังคับว่าจำต้องครบองค์ประชุม"}},{"id":"TH-H004-A97","no":97,"noLabel":{"th":"มาตรา 97"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๗ มติของที่ประชุม ให้ถือเอาเสียงข้างมากเป็นประมาณ เว้นแต่กรณีที่ข้อบังคับของสมาคมกำหนดเสียงข้างมากไว้เป็นพิเศษโดยเฉพาะ สมาชิกคนหนึ่งมีเสียงหนึ่งในการลงคะแนน ถ้าคะแนนเสียงเท่ากันให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นได้อีกเสียงหนึ่งเป็นเสียงชี้ขาด"}},{"id":"TH-H004-A98","no":98,"noLabel":{"th":"มาตรา 98"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๘ สมาชิกจะมอบอำนาจให้สมาชิกผู้ใดมาเข้าประชุมและออกเสียงลงคะแนนแทนตนก็ได้ เว้นแต่ข้อบังคับของสมาคมจะกำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A99","no":99,"noLabel":{"th":"มาตรา 99"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๙ ในกรณีที่จะมีมติในเรื่องใด ถ้าส่วนได้เสียของกรรมการหรือสมาชิกของสมาคมผู้ใดขัดกับประโยชน์ได้เสียของสมาคม กรรมการหรือสมาชิกของสมาคมผู้นั้นจะออกเสียงลงคะแนนในเรื่องนั้นไม่ได้"}},{"id":"TH-H004-A100","no":100,"noLabel":{"th":"มาตรา 100"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๐ ในการประชุมใหญ่ครั้งใด ถ้าได้มีการนัดประชุมหรือการลงมติโดยไม่ปฏิบัติตามหรือฝ่าฝืนข้อบังคับของสมาคมหรือบทบัญญัติในส่วนนี้ สมาชิก หรือพนักงานอัยการอาจร้องขอให้ศาลสั่งเพิกถอนมติในการประชุมใหญ่ครั้งนั้นได้ แต่ต้องร้องขอต่อศาลภายในหนึ่งเดือนนับแต่วันที่ที่ประชุมใหญ่ลงมติ"}},{"id":"TH-H004-A101","no":101,"noLabel":{"th":"มาตรา 101"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๑ สมาคมย่อมเลิกด้วยเหตุหนึ่งเหตุใดดังต่อไปนี้ (๑) เมื่อมีเหตุตามที่กำหนดในข้อบังคับ (๒) ถ้าสมาคมตั้งขึ้นไว้เฉพาะระยะเวลาใด เมื่อสิ้นระยะเวลานั้น (๓) ถ้าสมาคมตั้งขึ้นเพื่อกระทำกิจการใด เมื่อกิจการนั้นสำเร็จแล้ว (๔) เมื่อที่ประชุมใหญ่มีมติให้เลิก (๕) เมื่อสมาคมล้มละลาย (๖) เมื่อนายทะเบียนถอนชื่อสมาคมออกจากทะเบียนตามมาตรา ๑๐๒ (๗) เมื่อศาลสั่งให้เลิกตามมาตรา ๑๐๔"}},{"id":"TH-H004-A102","no":102,"noLabel":{"th":"มาตรา 102"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๒ ให้นายทะเบียนมีอำนาจสั่งถอนชื่อสมาคมออกจากทะเบียนได้ในกรณีดังต่อไปนี้ (๑) เมื่อปรากฏในภายหลังการจดทะเบียนว่า วัตถุประสงค์ของสมาคมขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรืออาจเป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ และนายทะเบียนได้สั่งให้แก้ไขแล้วแต่สมาคมไม่ปฏิบัติตามภายในระยะเวลาที่นายทะเบียนกำหนด (๒) เมื่อปรากฏว่าการดำเนินกิจการของสมาคมขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรืออาจเป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ (๓) เมื่อสมาคมหยุดดำเนินกิจการติดต่อกันตั้งแต่สองปีขึ้นไป (๔) เมื่อปรากฏว่าสมาคมให้หรือปล่อยให้บุคคลอื่นซึ่งมิใช่กรรมการของสมาคมเป็นผู้ดำเนินกิจการของสมาคม (๕) เมื่อสมาคมมีสมาชิกเหลือน้อยกว่าสิบคนมาเป็นเวลาติดต่อกันกว่าสองปี"}},{"id":"TH-H004-A103","no":103,"noLabel":{"th":"มาตรา 103"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓ เมื่อนายทะเบียนมีคำสั่งให้ถอนชื่อสมาคมใดออกจากทะเบียนตามมาตรา ๑๐๒ แล้ว ให้นายทะเบียนแจ้งคำสั่งพร้อมด้วยเหตุผลไปยังสมาคมนั้นโดยมิชักช้า และประกาศการเลิกสมาคมในราชกิจจานุเบกษา กรรมการคนหนึ่งคนใดหรือสมาชิกของสมาคมจำนวนไม่น้อยกว่าสามคน มีสิทธิอุทธรณ์คำสั่งของนายทะเบียนตามวรรคหนึ่งต่อรัฐมนตรีว่าการกระทรวงมหาดไทยได้ โดยทำเป็นหนังสือยื่นต่อนายทะเบียนภายในสามสิบวันนับแต่วันที่ได้รับแจ้งคำสั่ง และให้นำความในมาตรา ๘๒ วรรคห้า มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A104","no":104,"noLabel":{"th":"มาตรา 104"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔ เมื่อมีกรณีตามมาตรา ๑๐๒ ผู้มีส่วนได้เสียอาจร้องขอให้นายทะเบียนถอนชื่อสมาคมออกจากทะเบียนได้ ถ้านายทะเบียนไม่ปฏิบัติตามคำร้องขอโดยไม่แจ้งเหตุผลให้ผู้ร้องขอทราบภายในเวลาอันสมควร หรือนายทะเบียนได้แจ้งเหตุผลให้ทราบแล้วแต่ผู้ร้องขอไม่พอใจในเหตุผลดังกล่าวผู้ร้องขอนั้นจะร้องขอต่อศาลให้สั่งเลิกสมาคมนั้นเสียก็ได้"}},{"id":"TH-H004-A105","no":105,"noLabel":{"th":"มาตรา 105"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๕ เมื่อสมาคมมีเหตุต้องเลิกตามมาตรา ๑๐๑ (๑) (๒) (๓) หรือ (๔) ให้คณะกรรมการของสมาคมที่อยู่ในตำแหน่งขณะมีการเลิกสมาคมแจ้งการเลิกสมาคมต่อนายทะเบียนภายในสิบสี่วันนับแต่วันที่มีการเลิกสมาคม ในกรณีที่ศาลมีคำพิพากษาหรือคำสั่งถึงที่สุดให้สมาคมล้มละลายตามมาตรา ๑๐๑ (๕) หรือมีคำสั่งถึงที่สุดให้เลิกสมาคมตามมาตรา ๑๐๔ ให้ศาลแจ้งคำพิพากษาหรือคำสั่งดังกล่าวให้นายทะเบียนทราบด้วย ให้นายทะเบียนประกาศการเลิกสมาคมในราชกิจจานุเบกษา"}},{"id":"TH-H004-A106","no":106,"noLabel":{"th":"มาตรา 106"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๖ ในกรณีที่มีการเลิกสมาคม ให้มีการชำระบัญชีสมาคมและให้นำบทบัญญัติในบรรพ ๓ ลักษณะ ๒๒ ว่าด้วยการชำระบัญชีห้างหุ้นส่วนจดทะเบียน ห้างหุ้นส่วนจำกัด และบริษัทจำกัด มาใช้บังคับแก่การชำระบัญชีสมาคมโดยอนุโลม"}},{"id":"TH-H004-A107","no":107,"noLabel":{"th":"มาตรา 107"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๗ เมื่อได้ชำระบัญชีแล้ว ถ้ามีทรัพย์สินเหลืออยู่เท่าใด จะแบ่งให้แก่สมาชิกของสมาคมนั้นไม่ได้ ทรัพย์สินที่เหลือนั้นจะต้องโอนให้แก่สมาคมหรือมูลนิธิ หรือนิติบุคคลที่มีวัตถุประสงค์เกี่ยวกับการสาธารณกุศล ตามที่ได้ระบุชื่อไว้ในข้อบังคับของสมาคม หรือถ้าข้อบังคับไม่ได้ระบุชื่อไว้ก็ให้เป็นไปตามมติของที่ประชุมใหญ่ แต่ถ้าข้อบังคับของสมาคมหรือที่ประชุมใหญ่มิได้ระบุผู้รับโอนทรัพย์สินดังกล่าวไว้ หรือระบุไว้แต่ไม่สามารถปฏิบัติได้ ให้ทรัพย์สินที่เหลืออยู่นั้นตกเป็นของแผ่นดิน"}},{"id":"TH-H004-A108","no":108,"noLabel":{"th":"มาตรา 108"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๘ ผู้ใดประสงค์จะขอตรวจเอกสารเกี่ยวกับสมาคมที่นายทะเบียนเก็บรักษาไว้หรือจะขอให้นายทะเบียนคัดสำเนาเอกสารดังกล่าว พร้อมด้วยคำรับรองว่าถูกต้อง ให้ยื่นคำขอต่อนายทะเบียน และเมื่อได้เสียค่าธรรมเนียมตามที่กำหนดในกฎกระทรวงแล้วให้นายทะเบียนปฏิบัติตามคำขอนั้น"}},{"id":"TH-H004-A109","no":109,"noLabel":{"th":"มาตรา 109"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๙ ให้รัฐมนตรีว่าการกระทรวงมหาดไทยรักษาการตามบทบัญญัติในส่วนนี้ และให้มีอำนาจแต่งตั้งนายทะเบียนกับออกกฎกระทรวงเกี่ยวกับ (๑) การยื่นคำขอจดทะเบียนและการรับจดทะเบียน (๒) ค่าธรรมเนียมการจดทะเบียน การขอตรวจเอกสาร การคัดสำเนาเอกสารและค่าธรรมเนียมการขอให้นายทะเบียนดำเนินการใด ๆ เกี่ยวกับสมาคม รวมทั้งการยกเว้นค่าธรรมเนียมดังกล่าว (๓) การดำเนินกิจการของสมาคมและการทะเบียนสมาคม (๔) การอื่นใดเพื่อปฏิบัติให้เป็นไปตามบทบัญญัติในส่วนนี้ กฎกระทรวงนั้น เมื่อประกาศในราชกิจจานุเบกษาแล้วให้ใช้บังคับได้"}},{"id":"TH-H004-A110","no":110,"noLabel":{"th":"มาตรา 110"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๐ มูลนิธิได้แก่ทรัพย์สินที่จัดสรรไว้โดยเฉพาะสำหรับวัตถุประสงค์เพื่อการกุศล สาธารณะ การศาสนา ศิลปะ วิทยาศาสตร์ วรรณคดี การศึกษา หรือเพื่อสาธารณประโยชน์อย่างอื่น โดยมิได้มุ่งหาผลประโยชน์มาแบ่งปันกัน และได้จดทะเบียนตามบทบัญญัติแห่งประมวลกฎหมายนี้ การจัดการทรัพย์สินของมูลนิธิ ต้องมิใช่เป็นการหาผลประโยชน์เพื่อบุคคลใดนอกจากเพื่อดำเนินการตามวัตถุประสงค์ของมูลนิธินั้นเอง"}},{"id":"TH-H004-A111","no":111,"noLabel":{"th":"มาตรา 111"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๑ มูลนิธิต้องมีข้อบังคับ และต้องมีคณะกรรมการของมูลนิธิประกอบด้วยบุคคลอย่างน้อยสามคน เป็นผู้ดำเนินกิจการของมูลนิธิตามกฎหมายและข้อบังคับของมูลนิธิ"}},{"id":"TH-H004-A112","no":112,"noLabel":{"th":"มาตรา 112"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๒ ข้อบังคับของมูลนิธิอย่างน้อยต้องมีรายการดังต่อไปนี้ (๑) ชื่อมูลนิธิ (๒) วัตถุประสงค์ของมูลนิธิ (๓) ที่ตั้งสำนักงานใหญ่และที่ตั้งสำนักงานสาขาทั้งปวง (๔) ทรัพย์สินของมูลนิธิขณะจัดตั้ง (๕) ข้อกำหนดเกี่ยวกับคณะกรรมการของมูลนิธิ ได้แก่ จำนวนกรรมการ การตั้งกรรมการ วาระการดำรงตำแหน่งของกรรมการ การพ้นจากตำแหน่งของกรรมการ และการประชุมของคณะกรรมการ (๖) ข้อกำหนดเกี่ยวกับการจัดการมูลนิธิ การจัดการทรัพย์สินและบัญชีของมูลนิธิ"}},{"id":"TH-H004-A113","no":113,"noLabel":{"th":"มาตรา 113"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๓ มูลนิธิต้องใช้ชื่อซึ่งมีคำว่า “มูลนิธิ” ประกอบกับชื่อของมูลนิธิ"}},{"id":"TH-H004-A114","no":114,"noLabel":{"th":"มาตรา 114"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔ การขอจดทะเบียนมูลนิธินั้น ให้ผู้ขอจัดตั้งมูลนิธิยื่นคำขอเป็นหนังสือต่อนายทะเบียนแห่งท้องที่ที่สำนักงานใหญ่ของมูลนิธิจะตั้งขึ้น ในคำขออย่างน้อยต้องระบุเจ้าของทรัพย์สินและรายการทรัพย์สินที่จะจัดสรรสำหรับมูลนิธิ รายชื่อ ที่อยู่และอาชีพของผู้จะเป็นกรรมการของมูลนิธิทุกคน พร้อมกับแนบข้อบังคับของมูลนิธิมากับคำขอด้วย"}},{"id":"TH-H004-A115","no":115,"noLabel":{"th":"มาตรา 115"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕ เมื่อนายทะเบียนได้รับคำขอแล้วเห็นว่า คำขอนั้นถูกต้องตามมาตรา ๑๑๔ และข้อบังคับถูกต้องตามมาตรา ๑๑๒ และวัตถุประสงค์เป็นไปตามมาตรา ๑๑๐ และไม่ขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรือไม่เป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ และรายการซึ่งจดแจ้งในคำขอหรือข้อบังคับสอดคล้องกับวัตถุประสงค์ของมูลนิธิ และผู้จะเป็นกรรมการของมูลนิธินั้นมีฐานะและความประพฤติเหมาะสมในการดำเนินการตามวัตถุประสงค์ของมูลนิธิ ให้นายทะเบียนรับจดทะเบียนและออกใบสำคัญแสดงการจดทะเบียนให้แก่มูลนิธินั้นและประกาศการจัดตั้งมูลนิธิในราชกิจจานุเบกษา ถ้านายทะเบียนเห็นว่าคำขอหรือข้อบังคับไม่ถูกต้องตามมาตรา ๑๑๔ หรือมาตรา ๑๑๒ หรือรายการซึ่งจดแจ้งในคำขอหรือข้อบังคับไม่สอดคล้องกับวัตถุประสงค์ของมูลนิธิ หรือผู้จะเป็นกรรมการของมูลนิธิมีฐานะหรือความประพฤติไม่เหมาะสมในการดำเนินการตามวัตถุประสงค์ของมูลนิธิ ให้มีคำสั่งให้ผู้ขอจดทะเบียนแก้ไขหรือเปลี่ยนแปลงให้ถูกต้อง เมื่อแก้ไขหรือเปลี่ยนแปลงถูกต้องแล้ว ให้รับจดทะเบียนและออกใบสำคัญแสดงการจดทะเบียนให้แก่มูลนิธินั้น ถ้านายทะเบียนเห็นว่าไม่อาจรับจดทะเบียนได้เนื่องจากวัตถุประสงค์ของมูลนิธิไม่เป็นไปตามมาตรา ๑๑๐ หรือขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชนหรืออาจเป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ หรือผู้ขอจดทะเบียนไม่แก้ไขหรือเปลี่ยนแปลงให้ถูกต้องภายในสามสิบวันนับแต่วันที่ทราบคำสั่งของนายทะเบียน ให้นายทะเบียนมีคำสั่งไม่รับจดทะเบียนและแจ้งคำสั่งพร้อมด้วยเหตุผลที่ไม่รับจดทะเบียนให้ผู้ขอจดทะเบียนทราบโดยมิชักช้า ผู้ขอจดทะเบียนมีสิทธิอุทธรณ์คำสั่งไม่รับจดทะเบียนนั้นต่อรัฐมนตรีว่าการกระทรวงมหาดไทย โดยทำเป็นหนังสือยื่นต่อนายทะเบียนภายในสามสิบวันนับแต่วันที่ได้รับแจ้งคำสั่งไม่รับจดทะเบียน ให้รัฐมนตรีว่าการกระทรวงมหาดไทยวินิจฉัยอุทธรณ์และแจ้งคำวินิจฉัยให้ผู้อุทธรณ์ทราบภายในเก้าสิบวันนับแต่วันที่นายทะเบียนได้รับหนังสืออุทธรณ์ คำวินิจฉัยของรัฐมนตรีว่าการกระทรวงมหาดไทยให้เป็นที่สุด"}},{"id":"TH-H004-A116","no":116,"noLabel":{"th":"มาตรา 116"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖ ก่อนที่นายทะเบียนรับจดทะเบียนมูลนิธิ ผู้ขอจัดตั้งมูลนิธิมีสิทธิขอถอนการจัดตั้งมูลนิธิได้โดยทำเป็นหนังสือยื่นต่อนายทะเบียน สิทธิที่จะขอถอนการจัดตั้งมูลนิธินี้ไม่ตกทอดไปยังทายาท ในกรณีที่มีผู้ขอจัดตั้งมูลนิธิหลายคน ถ้าผู้ขอจัดตั้งมูลนิธิคนหนึ่งคนใดใช้สิทธิถอนการจัดตั้ง มูลนิธิ ให้คำขอจัดตั้งมูลนิธินั้นเป็นอันระงับไป"}},{"id":"TH-H004-A117","no":117,"noLabel":{"th":"มาตรา 117"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗ ในกรณีที่ผู้ขอจัดตั้งมูลนิธิถึงแก่ความตายก่อนนายทะเบียนรับจดทะเบียนมูลนิธิ ถ้าผู้ตายมิได้ทำพินัยกรรมยกเลิกการจัดตั้งมูลนิธิที่ขอจัดตั้งไว้ให้คำขอจัดตั้งมูลนิธิที่ผู้ตายได้ยื่นไว้ต่อนายทะเบียนยังคงใช้ได้ต่อไป และให้ทายาทหรือผู้จัดการมรดกหรือผู้ซึ่งผู้ตายมอบหมาย ดำเนินการในฐานะเป็นผู้ขอจัดตั้งมูลนิธิต่อไป ถ้าบุคคลดังกล่าวไม่ดำเนินการภายในหนึ่งร้อยยี่สิบวันนับแต่วันที่ผู้ขอจัดตั้งมูลนิธิถึงแก่ความตาย บุคคลผู้มีส่วนได้เสียหรือพนักงานอัยการจะดำเนินการในฐานะเป็นผู้ขอจัดตั้งมูลนิธินั้นต่อไปก็ได้ ในกรณีที่ไม่สามารถจัดตั้งมูลนิธิขึ้นได้ตามวัตถุประสงค์ที่ผู้ตายกำหนดไว้ ถ้าหากไม่มีพินัยกรรมของผู้ตายสั่งการในเรื่องนี้ไว้เป็นอย่างอื่น ให้นำความในมาตรา ๑๖๗๙ วรรคสอง มาใช้บังคับโดยอนุโลม ถ้าไม่สามารถดำเนินการตามมาตรา ๑๖๗๙ วรรคสอง หรือมูลนิธิจัดตั้งขึ้นไม่ได้ตามมาตรา ๑๑๕ ให้ทรัพย์สินที่จัดสรรไว้ตกเป็นมรดกของผู้ตาย"}},{"id":"TH-H004-A118","no":118,"noLabel":{"th":"มาตรา 118"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘ ในกรณีที่มีข้อกำหนดพินัยกรรมให้ก่อตั้งมูลนิธิตามมาตรา ๑๖๗๖ ให้บุคคลซึ่งมีหน้าที่ที่จะต้องจัดตั้งมูลนิธิตามมาตรา ๑๖๗๗ วรรคหนึ่ง ดำเนินการตามมาตรา ๑๑๔ และตามบทบัญญัติแห่งมาตรานี้ ถ้าบุคคลซึ่งมีหน้าที่ที่จะต้องจัดตั้งมูลนิธิตามวรรคหนึ่ง มิได้ขอจดทะเบียนก่อตั้งมูลนิธิภายในหนึ่งร้อยยี่สิบวันนับแต่วันที่บุคคลดังกล่าวได้รู้หรือควรรู้ข้อกำหนดพินัยกรรมให้ก่อตั้งมูลนิธิ บุคคลผู้มีส่วนได้เสียคนหนึ่งคนใดหรือพนักงานอัยการจะเป็นผู้ขอจดทะเบียนมูลนิธิก็ได้ ถ้าผู้ยื่นคำขอจดทะเบียนมูลนิธิไม่ดำเนินการแก้ไขหรือเปลี่ยนแปลงให้ถูกต้องตามคำสั่งของนายทะเบียนตามมาตรา ๑๑๕ จนเป็นเหตุให้นายทะเบียนไม่รับจดทะเบียนมูลนิธิเพราะเหตุดังกล่าว บุคคลผู้มีส่วนได้เสียคนหนึ่งคนใดหรือพนักงานอัยการจะเป็นผู้ขอจดทะเบียนมูลนิธินั้นอีกก็ได้ ผู้ยื่นคำขอจดทะเบียนก่อตั้งมูลนิธิตามมาตรานี้ จะขอถอนการก่อตั้งมูลนิธิตามมาตรา ๑๑๖ ไม่ได้ ในกรณีที่มีผู้คัดค้านต่อนายทะเบียนว่าพินัยกรรมนั้นมิได้กำหนดให้ก่อตั้งเป็นมูลนิธิ ให้นายทะเบียนแจ้งให้ผู้คัดค้านไปร้องต่อศาลภายในหกสิบวันนับแต่วันที่ได้รับแจ้งจากนายทะเบียน และให้นายทะเบียนรอการพิจารณาการจดทะเบียนไว้ก่อน เพื่อดำเนินการตามคำพิพากษาหรือคำสั่งของศาล ถ้าผู้คัดค้านไม่ยื่นคำร้องต่อศาลภายในเวลาที่กำหนด ให้นายทะเบียนพิจารณาการจดทะเบียนมูลนิธินั้นต่อไป"}},{"id":"TH-H004-A119","no":119,"noLabel":{"th":"มาตรา 119"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙ ในกรณีที่มีข้อกำหนดพินัยกรรมให้จัดตั้งมูลนิธิ ถ้าพินัยกรรมที่ทำไว้มิได้มีข้อกำหนดเกี่ยวกับรายการตามมาตรา ๑๑๒ (๑) (๓) (๕) หรือ (๖) ให้ผู้ยื่นคำขอตามมาตรา ๑๑๘ กำหนดรายการดังกล่าวได้ ถ้าผู้มีส่วนได้เสียคนหนึ่งคนใดคัดค้าน ให้นายทะเบียนมีคำสั่งตามที่เห็นสมควร แล้วแจ้งให้ผู้ยื่นคำขอและผู้คัดค้านทราบพร้อมทั้งแจ้งด้วยว่า หากผู้ยื่นคำขอหรือผู้คัดค้านไม่พอใจในคำสั่งดังกล่าว ก็ให้ไปร้องคัดค้านต่อศาลภายในหกสิบวันนับแต่วันที่ได้รับแจ้งจากนายทะเบียน และให้นายทะเบียนรอการพิจารณาจดทะเบียนไว้ก่อนเพื่อดำเนินการตามคำพิพากษาหรือคำสั่งของศาล แต่ถ้าไม่มีการร้องคัดค้านต่อศาลภายในเวลาที่กำหนด ให้นายทะเบียนพิจารณาจดทะเบียนมูลนิธิตามที่ได้มีคำสั่งไว้นั้นต่อไป"}},{"id":"TH-H004-A120","no":120,"noLabel":{"th":"มาตรา 120"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐ ในกรณีที่มีบุคคลหลายรายยื่นคำขอจดทะเบียนมูลนิธิตามพินัยกรรมของเจ้ามรดกรายเดียวกัน ถ้าคำขอนั้นมีข้อขัดแย้งกัน ให้นายทะเบียนเรียกผู้ยื่นคำขอมาตกลงกัน และถ้าผู้ยื่นคำขอไม่มาตกลงกัน หรือตกลงกันไม่ได้ภายในระยะเวลาที่นายทะเบียนกำหนด ให้นายทะเบียนมีคำสั่งตามที่เห็นสมควร และให้นำความในมาตรา ๑๑๙ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A121","no":121,"noLabel":{"th":"มาตรา 121"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๑ เมื่อได้จดทะเบียนมูลนิธิแล้ว ถ้าผู้ขอจัดตั้งมูลนิธิมีชีวิตอยู่ ให้ทรัพย์สินที่จัดสรรไว้เพื่อการนั้นตกเป็นของมูลนิธิตั้งแต่วันที่นายทะเบียนรับจดทะเบียนมูลนิธิเป็นต้นไป ในกรณีที่ผู้ขอจัดตั้งมูลนิธิถึงแก่ความตายก่อนนายทะเบียนรับจดทะเบียนมูลนิธิ เมื่อได้จดทะเบียนมูลนิธิแล้ว ให้ทรัพย์สินที่จัดสรรไว้เพื่อการนั้นตกเป็นของมูลนิธิตั้งแต่เวลาที่ผู้ขอจัดตั้งมูลนิธินั้นถึงแก่ความตาย"}},{"id":"TH-H004-A122","no":122,"noLabel":{"th":"มาตรา 122"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๒ มูลนิธิที่ได้จดทะเบียนแล้วเป็นนิติบุคคล"}},{"id":"TH-H004-A123","no":123,"noLabel":{"th":"มาตรา 123"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๓ คณะกรรมการของมูลนิธิเป็นผู้แทนของมูลนิธิในกิจการอันเกี่ยวกับบุคคลภายนอก"}},{"id":"TH-H004-A124","no":124,"noLabel":{"th":"มาตรา 124"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๔ บรรดากิจการที่คณะกรรมการของมูลนิธิได้กระทำไป แม้จะปรากฏในภายหลังว่ามีข้อบกพร่องเกี่ยวกับการแต่งตั้งหรือคุณสมบัติของกรรมการของมูลนิธิ กิจการนั้นย่อมมีผลสมบูรณ์"}},{"id":"TH-H004-A125","no":125,"noLabel":{"th":"มาตรา 125"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๕ การแต่งตั้งกรรมการของมูลนิธิขึ้นใหม่ทั้งชุดหรือการเปลี่ยนแปลงกรรมการของมูลนิธิ ให้กระทำตามข้อบังคับของมูลนิธิ และมูลนิธิต้องนำไปจดทะเบียนภายในสามสิบวันนับแต่วันที่มีการแต่งตั้งหรือเปลี่ยนแปลงกรรมการของมูลนิธิ ถ้านายทะเบียนเห็นว่ากรรมการของมูลนิธิตามวรรคหนึ่งผู้ใด มีฐานะหรือความประพฤติไม่เหมาะสมในการดำเนินการตามวัตถุประสงค์ของมูลนิธิ นายทะเบียนจะไม่รับจดทะเบียนกรรมการของมูลนิธิผู้นั้นก็ได้ ในกรณีที่นายทะเบียนไม่รับจดทะเบียนกรรมการของมูลนิธิ นายทะเบียนต้องแจ้งเหตุผลที่ไม่รับจดทะเบียนให้มูลนิธิทราบภายในหกสิบวันนับแต่วันที่ยื่นคำขอจดทะเบียน และให้นำความในมาตรา ๑๑๕ วรรคสี่และวรรคห้ามาใช้บังคับโดยอนุโลม ในกรณีที่กรรมการของมูลนิธิพ้นจากตำแหน่งและไม่มีกรรมการของมูลนิธิเหลืออยู่ หรือกรรมการของมูลนิธิที่เหลืออยู่ไม่สามารถดำเนินการตามหน้าที่ได้ ถ้าข้อบังคับของมูลนิธิมิได้กำหนดการปฏิบัติหน้าที่ไว้เป็นอย่างอื่น ให้กรรมการของมูลนิธิที่พ้นจากตำแหน่งปฏิบัติหน้าที่กรรมการของมูลนิธิต่อไปจนกว่านายทะเบียนจะได้แจ้งการรับจดทะเบียนกรรมการของมูลนิธิที่ตั้งใหม่ กรรมการของมูลนิธิที่พ้นจากตำแหน่งเพราะถูกถอดถอนโดยคำสั่งศาลตามมาตรา ๑๒๙ จะปฏิบัติหน้าที่ตามวรรคสามไม่ได้"}},{"id":"TH-H004-A126","no":126,"noLabel":{"th":"มาตรา 126"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๖ ภายใต้บังคับมาตรา ๑๒๗ ให้คณะกรรมการของมูลนิธิเป็นผู้มีอำนาจแก้ไขเพิ่มเติมข้อบังคับของมูลนิธิ แต่ถ้าข้อบังคับของมูลนิธิได้กำหนดหลักเกณฑ์และวิธีการแก้ไขเพิ่มเติมไว้ การแก้ไขเพิ่มเติมต้องเป็นไปตามที่ข้อบังคับกำหนด และให้มูลนิธินำข้อบังคับที่แก้ไขเพิ่มเติมนั้นไปจดทะเบียนต่อนายทะเบียนภายในสามสิบวันนับแต่วันที่คณะกรรมการของมูลนิธิได้แก้ไขเพิ่มเติมข้อบังคับของมูลนิธิและให้นำความในมาตรา ๑๑๕ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A127","no":127,"noLabel":{"th":"มาตรา 127"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๗ การแก้ไขเพิ่มเติมรายการในข้อบังคับของมูลนิธิตามมาตรา ๑๑๒ (๒) จะกระทำได้แต่เฉพาะในกรณีดังต่อไปนี้ (๑) เพื่อให้สามารถดำเนินการตามวัตถุประสงค์ของมูลนิธิ หรือ (๒) พฤติการณ์เปลี่ยนแปลงไปเป็นเหตุให้วัตถุประสงค์ของมูลนิธินั้นมีประโยชน์น้อย หรือไม่อาจดำเนินการให้สมประโยชน์ตามวัตถุประสงค์ของมูลนิธินั้นได้ และวัตถุประสงค์ของมูลนิธิที่แก้ไขเพิ่มเติมนั้นใกล้ชิดกับวัตถุประสงค์เดิมของมูลนิธิ"}},{"id":"TH-H004-A128","no":128,"noLabel":{"th":"มาตรา 128"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๘ ให้นายทะเบียนมีอำนาจตรวจตราและควบคุมดูแลการดำเนินกิจการของมูลนิธิให้เป็นไปตามกฎหมายและข้อบังคับของมูลนิธิ เพื่อการนี้ให้นายทะเบียนหรือพนักงานเจ้าหน้าที่ซึ่งนายทะเบียนมอบหมายเป็นหนังสือ มีอำนาจ (๑) มีคำสั่งเป็นหนังสือให้กรรมการ พนักงาน ลูกจ้างหรือตัวแทนของมูลนิธิชี้แจงแสดงข้อเท็จจริงเกี่ยวกับกิจการของมูลนิธิ หรือเรียกบุคคลดังกล่าวมาสอบถาม หรือให้ส่งหรือแสดงสมุดบัญชีและเอกสารต่าง ๆ ของมูลนิธิเพื่อตรวจสอบ (๒) เข้าไปในสำนักงานของมูลนิธิในเวลาระหว่างพระอาทิตย์ขึ้น และพระอาทิตย์ตกเพื่อตรวจสอบกิจการของมูลนิธิ ในการปฏิบัติการตามวรรคหนึ่ง ถ้าเป็นนายทะเบียนให้แสดงบัตรประจำตัวและถ้าเป็นพนักงานเจ้าหน้าที่ซึ่งได้รับมอบหมาย ให้แสดงบัตรประจำตัวและหนังสือมอบหมายของนายทะเบียนต่อผู้ที่เกี่ยวข้อง"}},{"id":"TH-H004-A129","no":129,"noLabel":{"th":"มาตรา 129"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๙ ในกรณีที่กรรมการของมูลนิธิผู้ใดดำเนินกิจการของมูลนิธิผิดพลาดเสื่อมเสียต่อมูลนิธิ หรือดำเนินกิจการฝ่าฝืนกฎหมายหรือข้อบังคับของมูลนิธิ หรือกลายเป็นผู้มีฐานะหรือความประพฤติไม่เหมาะสมในการดำเนินการตามวัตถุประสงค์ของมูลนิธิ นายทะเบียน พนักงานอัยการ หรือผู้มีส่วนได้เสียคนหนึ่งคนใดอาจร้องขอต่อศาลให้มีคำสั่งถอดถอนกรรมการของมูลนิธิผู้นั้นได้ ในกรณีที่การกระทำตามวรรคหนึ่งเป็นการกระทำของคณะกรรมการของมูลนิธิ หรือปรากฏว่าคณะกรรมการของมูลนิธิไม่ดำเนินการตามวัตถุประสงค์ของมูลนิธิโดยไม่มีเหตุอันสมควร นายทะเบียน พนักงานอัยการ หรือผู้มีส่วนได้เสียคนหนึ่งคนใดอาจร้องขอต่อศาลให้มีคำสั่งถอดถอนกรรมการของมูลนิธิทั้งคณะได้ ในกรณีที่ศาลมีคำสั่งถอดถอนกรรมการของมูลนิธิหรือคณะกรรมการของมูลนิธิตามวรรคหนึ่งหรือวรรคสอง ศาลจะแต่งตั้งบุคคลอื่นเป็นกรรมการของมูลนิธิ หรือคณะกรรมการของมูลนิธิแทนกรรมการของมูลนิธิ หรือคณะกรรมการของมูลนิธิที่ศาลถอดถอนก็ได้ เมื่อศาลมีคำสั่งแต่งตั้งบุคคลใดเป็นกรรมการของมูลนิธิแล้ว ให้นายทะเบียนดำเนินการจดทะเบียนไปตามนั้น"}},{"id":"TH-H004-A130","no":130,"noLabel":{"th":"มาตรา 130"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๐ มูลนิธิย่อมเลิกด้วยเหตุหนึ่งเหตุใด ดังต่อไปนี้ (๑) เมื่อมีเหตุตามที่กำหนดในข้อบังคับ (๒) ถ้ามูลนิธิตั้งขึ้นไว้เฉพาะระยะเวลาใด เมื่อสิ้นระยะเวลานั้น (๓) ถ้ามูลนิธิตั้งขึ้นเพื่อวัตถุประสงค์อย่างใด และได้ดำเนินการตามวัตถุประสงค์สำเร็จบริบูรณ์แล้ว หรือวัตถุประสงค์นั้นกลายเป็นพ้นวิสัย (๔) เมื่อมูลนิธินั้นล้มละลาย (๕) เมื่อศาลมีคำสั่งให้เลิกมูลนิธิตามมาตรา ๑๓๑"}},{"id":"TH-H004-A131","no":131,"noLabel":{"th":"มาตรา 131"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๑ นายทะเบียน พนักงานอัยการ หรือผู้มีส่วนได้เสียคนหนึ่งคนใดอาจร้องขอต่อศาลให้มีคำสั่งให้เลิกมูลนิธิได้ในกรณีหนึ่งกรณีใด ดังต่อไปนี้ (๑) เมื่อปรากฏว่าวัตถุประสงค์ของมูลนิธิขัดต่อกฎหมาย (๒) เมื่อปรากฏว่ามูลนิธิกระทำการขัดต่อกฎหมายหรือศีลธรรมอันดีของประชาชน หรืออาจเป็นภยันตรายต่อความสงบสุขของประชาชนหรือความมั่นคงของรัฐ (๓) เมื่อปรากฏว่ามูลนิธิไม่สามารถดำเนินกิจการต่อไปได้ไม่ว่าเพราะเหตุใด ๆ หรือหยุดดำเนินกิจการตั้งแต่สองปีขึ้นไป"}},{"id":"TH-H004-A132","no":132,"noLabel":{"th":"มาตรา 132"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๒ เมื่อมูลนิธิมีเหตุต้องเลิกตามมาตรา ๑๓๐ (๑) (๒) หรือ (๓) แล้ว ให้คณะกรรมการของมูลนิธิที่อยู่ในตำแหน่งขณะมีการเลิกมูลนิธิแจ้งการเลิกมูลนิธิต่อนายทะเบียนภายในสิบสี่วันนับแต่วันที่มีการเลิกมูลนิธิ ในกรณีที่ศาลมีคำพิพากษาหรือคำสั่งถึงที่สุดให้มูลนิธิล้มละลายตามมาตรา ๑๓๐ (๔) หรือมีคำสั่งถึงที่สุดให้เลิกมูลนิธิตามมาตรา ๑๓๑ ให้ศาลแจ้งคำพิพากษาหรือคำสั่งดังกล่าวให้นายทะเบียนทราบด้วย ให้นายทะเบียนประกาศการเลิกมูลนิธิในราชกิจจานุเบกษา"}},{"id":"TH-H004-A133","no":133,"noLabel":{"th":"มาตรา 133"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๓ ในกรณีที่มีการเลิกมูลนิธิ ให้มีการชำระบัญชีมูลนิธิและให้นำบทบัญญัติในบรรพ ๓ ลักษณะ ๒๒ ว่าด้วยการชำระบัญชีห้างหุ้นส่วนจดทะเบียน ห้างหุ้นส่วนจำกัด และบริษัทจำกัด มาใช้บังคับแก่การชำระบัญชีมูลนิธิโดยอนุโลม ทั้งนี้ ให้ผู้ชำระบัญชีเสนอรายงานการชำระบัญชีต่อนายทะเบียน และให้นายทะเบียนเป็นผู้อนุมัติรายงานนั้น"}},{"id":"TH-H004-A134","no":134,"noLabel":{"th":"มาตรา 134"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๔ เมื่อได้ชำระบัญชีแล้ว ให้โอนทรัพย์สินของมูลนิธิให้แก่มูลนิธิหรือนิติบุคคลที่มีวัตถุประสงค์ตามมาตรา ๑๑๐ ซึ่งได้ระบุชื่อไว้ในข้อบังคับของมูลนิธิ ถ้าข้อบังคับของมูลนิธิมิได้ระบุชื่อมูลนิธิหรือนิติบุคคลดังกล่าวไว้ พนักงานอัยการ ผู้ชำระบัญชี หรือผู้มีส่วนได้เสียคนหนึ่งคนใด อาจร้องขอต่อศาลให้จัดสรรทรัพย์สินนั้นแก่มูลนิธิหรือนิติบุคคลอื่นที่ปรากฏว่ามีวัตถุประสงค์ใกล้ชิดที่สุดกับวัตถุประสงค์ของมูลนิธินั้นได้ ถ้ามูลนิธินั้นถูกศาลสั่งให้เลิกตามมาตรา ๑๓๑ (๑) หรือ (๒) หรือการจัดสรรทรัพย์สินตามวรรคหนึ่งไม่อาจกระทำได้ ให้ทรัพย์สินของมูลนิธิตกเป็นของแผ่นดิน"}},{"id":"TH-H004-A135","no":135,"noLabel":{"th":"มาตรา 135"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๕ ผู้ใดประสงค์จะขอตรวจเอกสารเกี่ยวกับมูลนิธิที่นายทะเบียนเก็บรักษาไว้ หรือจะขอให้นายทะเบียนคัดสำเนาเอกสารดังกล่าวพร้อมด้วยคำรับรองว่าถูกต้อง ให้ยื่นคำขอต่อนายทะเบียน และเมื่อได้เสียค่าธรรมเนียมตามที่กำหนดในกฎกระทรวงแล้ว ให้นายทะเบียนปฏิบัติตามคำขอนั้น"}},{"id":"TH-H004-A136","no":136,"noLabel":{"th":"มาตรา 136"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๓๖ ให้รัฐมนตรีว่าการกระทรวงมหาดไทยรักษาการตามบทบัญญัติในส่วนนี้ และให้มีอำนาจแต่งตั้งนายทะเบียนกับออกกฎกระทรวงเกี่ยวกับ (๑) การยื่นคำขอจดทะเบียนและการรับจดทะเบียน (๒) ค่าธรรมเนียมการจดทะเบียน การขอตรวจเอกสาร การคัดสำเนาเอกสารและค่าธรรมเนียมการขอให้นายทะเบียนดำเนินการใด ๆ เกี่ยวกับมูลนิธิรวมทั้งการยกเว้นค่าธรรมเนียมดังกล่าว (๓) แบบบัตรประจำตัวของนายทะเบียนและพนักงานเจ้าหน้าที่ (๔) การดำเนินกิจการของมูลนิธิและการทะเบียนมูลนิธิ (๕) การอื่นใดเพื่อปฏิบัติให้เป็นไปตามบทบัญญัติในส่วนนี้ กฎกระทรวงนั้น เมื่อประกาศในราชกิจจานุเบกษาแล้วให้ใช้บังคับได้"}},{"id":"TH-H004-A137","no":137,"noLabel":{"th":"มาตรา 137"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗ ทรัพย์ หมายความว่า วัตถุมีรูปร่าง"}},{"id":"TH-H004-A138","no":138,"noLabel":{"th":"มาตรา 138"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘ ทรัพย์สิน หมายความรวมทั้งทรัพย์และวัตถุไม่มีรูปร่าง ซึ่งอาจมีราคาและอาจถือเอาได้"}},{"id":"TH-H004-A139","no":139,"noLabel":{"th":"มาตรา 139"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๙ อสังหาริมทรัพย์ หมายความว่า ที่ดินและทรัพย์อันติดอยู่กับที่ดินมีลักษณะเป็นการถาวรหรือประกอบเป็นอันเดียวกับที่ดินนั้น และหมายความรวมถึงทรัพยสิทธิอันเกี่ยวกับที่ดินหรือทรัพย์อันติดอยู่กับที่ดินหรือประกอบเป็นอันเดียวกับที่ดินนั้นด้วย"}},{"id":"TH-H004-A140","no":140,"noLabel":{"th":"มาตรา 140"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๐ สังหาริมทรัพย์ หมายความว่า ทรัพย์สินอื่นนอกจากอสังหาริมทรัพย์ และหมายความรวมถึงสิทธิอันเกี่ยวกับทรัพย์สินนั้นด้วย"}},{"id":"TH-H004-A141","no":141,"noLabel":{"th":"มาตรา 141"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๑ ทรัพย์แบ่งได้ หมายความว่า ทรัพย์อันอาจแยกออกจากกันเป็นส่วน ๆ ได้จริง ถนัดชัดแจ้ง แต่ละส่วนได้รูปบริบูรณ์ลำพังตัว"}},{"id":"TH-H004-A142","no":142,"noLabel":{"th":"มาตรา 142"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๒ ทรัพย์แบ่งไม่ได้ หมายความว่า ทรัพย์อันจะแยกออกจากกันไม่ได้นอกจากเปลี่ยนแปลงภาวะของทรัพย์ และหมายความรวมถึงทรัพย์ที่มีกฎหมายบัญญัติว่าแบ่งไม่ได้ด้วย"}},{"id":"TH-H004-A143","no":143,"noLabel":{"th":"มาตรา 143"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๓ ทรัพย์นอกพาณิชย์ หมายความว่า ทรัพย์ที่ไม่สามารถถือเอาได้และทรัพย์ที่โอนแก่กันมิได้โดยชอบด้วยกฎหมาย"}},{"id":"TH-H004-A144","no":144,"noLabel":{"th":"มาตรา 144"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๔ ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรือโดยจารีตประเพณีแห่งท้องถิ่นเป็นสาระสำคัญในความเป็นอยู่ของทรัพย์นั้น และไม่อาจแยกจากกันได้นอกจากจะทำลาย ทำให้บุบสลาย หรือทำให้ทรัพย์นั้นเปลี่ยนแปลงรูปทรงหรือสภาพไป เจ้าของทรัพย์ย่อมมีกรรมสิทธิ์ในส่วนควบของทรัพย์นั้น"}},{"id":"TH-H004-A145","no":145,"noLabel":{"th":"มาตรา 145"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๕ ไม้ยืนต้นเป็นส่วนควบกับที่ดินที่ไม้นั้นขึ้นอยู่ ไม้ล้มลุกหรือธัญชาติอันจะเก็บเกี่ยวรวงผลได้คราวหนึ่งหรือหลายคราวต่อปีไม่เป็นส่วนควบกับที่ดิน"}},{"id":"TH-H004-A146","no":146,"noLabel":{"th":"มาตรา 146"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๖ ทรัพย์ซึ่งติดกับที่ดินหรือติดกับโรงเรือนเพียงชั่วคราวไม่ถือว่าเป็นส่วนควบกับที่ดินหรือโรงเรือนนั้น ความข้อนี้ให้ใช้บังคับแก่โรงเรือนหรือสิ่งปลูกสร้างอย่างอื่น ซึ่งผู้มีสิทธิในที่ดินของผู้อื่นใช้สิทธินั้นปลูกสร้างไว้ในที่ดินนั้นด้วย"}},{"id":"TH-H004-A147","no":147,"noLabel":{"th":"มาตรา 147"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๗ อุปกรณ์ หมายความว่า สังหาริมทรัพย์ซึ่งโดยปกตินิยมเฉพาะถิ่นหรือโดยเจตนาชัดแจ้งของเจ้าของทรัพย์ที่เป็นประธาน เป็นของใช้ประจำอยู่กับทรัพย์ที่เป็นประธานเป็นอาจิณเพื่อประโยชน์แก่การจัดดูแล ใช้สอย หรือรักษาทรัพย์ที่เป็นประธาน และเจ้าของทรัพย์ได้นำมาสู่ทรัพย์ที่เป็นประธานโดยการนำมาติดต่อหรือปรับเข้าไว้ หรือทำโดยประการอื่นใดในฐานะเป็นของใช้ประกอบกับทรัพย์ที่เป็นประธานนั้น อุปกรณ์ที่แยกออกจากทรัพย์ที่เป็นประธานเป็นการชั่วคราวก็ยังไม่ขาดจากการเป็นอุปกรณ์ของทรัพย์ที่เป็นประธานนั้น อุปกรณ์ย่อมตกติดไปกับทรัพย์ที่เป็นประธาน เว้นแต่จะมีการกำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A148","no":148,"noLabel":{"th":"มาตรา 148"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๔๘ ดอกผลของทรัพย์ ได้แก่ ดอกผลธรรมดาและดอกผลนิตินัย ดอกผลธรรมดา หมายความว่า สิ่งที่เกิดขึ้นตามธรรมชาติของทรัพย์ ซึ่งได้มาจากตัวทรัพย์ โดยการมีหรือใช้ทรัพย์นั้นตามปกตินิยม และสามารถถือเอาได้เมื่อขาดจากทรัพย์นั้น ดอกผลนิตินัย หมายความว่า ทรัพย์หรือประโยชน์อย่างอื่นที่ได้มาเป็นครั้งคราวแก่เจ้าของทรัพย์จากผู้อื่นเพื่อการที่ได้ใช้ทรัพย์นั้น และสามารถคำนวณและถือเอาได้เป็นรายวันหรือตามระยะเวลาที่กำหนดไว้"}},{"id":"TH-H004-A149","no":149,"noLabel":{"th":"มาตรา 149"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๙ นิติกรรม หมายความว่า การใด ๆ อันทำลงโดยชอบด้วยกฎหมายและด้วยใจสมัคร มุ่งโดยตรงต่อการผูกนิติสัมพันธ์ขึ้นระหว่างบุคคล เพื่อจะก่อ เปลี่ยนแปลง โอน สงวน หรือ ระงับซึ่งสิทธิ"}},{"id":"TH-H004-A150","no":150,"noLabel":{"th":"มาตรา 150"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๐ การใดมีวัตถุประสงค์เป็นการต้องห้ามชัดแจ้งโดยกฎหมายเป็นการพ้นวิสัยหรือเป็นการขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน การนั้นเป็นโมฆะ"}},{"id":"TH-H004-A151","no":151,"noLabel":{"th":"มาตรา 151"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๑ การใดเป็นการแตกต่างกับบทบัญญัติของกฎหมาย ถ้ามิใช่กฎหมายอันเกี่ยวกับความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน การนั้นไม่เป็นโมฆะ"}},{"id":"TH-H004-A152","no":152,"noLabel":{"th":"มาตรา 152"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๒ การใดมิได้ทำให้ถูกต้องตามแบบที่กฎหมายบังคับไว้ การนั้นเป็นโมฆะ"}},{"id":"TH-H004-A153","no":153,"noLabel":{"th":"มาตรา 153"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๓ การใดมิได้เป็นไปตามบทบัญญัติของกฎหมายว่าด้วยความสามารถของบุคคล การนั้นเป็นโมฆียะ"}},{"id":"TH-H004-A154","no":154,"noLabel":{"th":"มาตรา 154"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๔ การแสดงเจตนาใดแม้ในใจจริงผู้แสดงจะมิได้เจตนาให้ตนต้องผูกพันตามที่ได้แสดงออกมาก็ตาม หาเป็นมูลเหตุให้การแสดงเจตนานั้นเป็นโมฆะไม่ เว้นแต่คู่กรณีอีกฝ่ายหนึ่งจะได้รู้ถึงเจตนาอันซ่อนอยู่ในใจของผู้แสดงนั้น"}},{"id":"TH-H004-A155","no":155,"noLabel":{"th":"มาตรา 155"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๕ การแสดงเจตนาลวงโดยสมรู้กับคู่กรณีอีกฝ่ายหนึ่งเป็นโมฆะ แต่จะยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริต และต้องเสียหายจากการแสดงเจตนาลวงนั้นมิได้ ถ้าการแสดงเจตนาลวงตามวรรคหนึ่งทำขึ้นเพื่ออำพรางนิติกรรมอื่น ให้นำบทบัญญัติของกฎหมายอันเกี่ยวกับนิติกรรมที่ถูกอำพรางมาใช้บังคับ"}},{"id":"TH-H004-A156","no":156,"noLabel":{"th":"มาตรา 156"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖ การแสดงเจตนาโดยสำคัญผิดในสิ่งซึ่งเป็นสาระสำคัญแห่งนิติกรรมเป็นโมฆะ ความสำคัญผิดในสิ่งซึ่งเป็นสาระสำคัญแห่งนิติกรรมตามวรรคหนึ่ง ได้แก่ ความสำคัญผิดในลักษณะของนิติกรรม ความสำคัญผิดในตัวบุคคลซึ่งเป็นคู่กรณีแห่งนิติกรรมและความสำคัญผิดในทรัพย์สินซึ่งเป็นวัตถุแห่งนิติกรรม เป็นต้น"}},{"id":"TH-H004-A157","no":157,"noLabel":{"th":"มาตรา 157"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗ การแสดงเจตนาโดยสำคัญผิดในคุณสมบัติของบุคคลหรือทรัพย์สินเป็นโมฆียะ ความสำคัญผิดตามวรรคหนึ่ง ต้องเป็นความสำคัญผิดในคุณสมบัติซึ่งตามปกติถือว่าเป็นสาระสำคัญ ซึ่งหากมิได้มีความสำคัญผิดดังกล่าวการอันเป็นโมฆียะนั้นคงจะมิได้กระทำขึ้น"}},{"id":"TH-H004-A158","no":158,"noLabel":{"th":"มาตรา 158"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘ ความสำคัญผิดตามมาตรา ๑๕๖ หรือมาตรา ๑๕๗ ซึ่งเกิดขึ้นโดยความประมาทเลินเล่ออย่างร้ายแรงของบุคคลผู้แสดงเจตนา บุคคลนั้นจะถือเอาความสำคัญผิดนั้นมาใช้เป็นประโยชน์แก่ตนไม่ได้"}},{"id":"TH-H004-A159","no":159,"noLabel":{"th":"มาตรา 159"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๙ การแสดงเจตนาเพราะถูกกลฉ้อฉลเป็นโมฆียะ การถูกกลฉ้อฉลที่จะเป็นโมฆียะตามวรรคหนึ่ง จะต้องถึงขนาดซึ่งถ้ามิได้มีกลฉ้อฉลดังกล่าว การอันเป็นโมฆียะนั้นคงจะมิได้กระทำขึ้น ถ้าคู่กรณีฝ่ายหนึ่งแสดงเจตนาเพราะถูกกลฉ้อฉลโดยบุคคลภายนอก การแสดงเจตนานั้นจะเป็นโมฆียะต่อเมื่อคู่กรณีอีกฝ่ายหนึ่งได้รู้หรือควรจะได้รู้ถึงกลฉ้อฉลนั้น"}},{"id":"TH-H004-A160","no":160,"noLabel":{"th":"มาตรา 160"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๐ การบอกล้างโมฆียะกรรมเพราะถูกกลฉ้อฉลตามมาตรา ๑๕๙ ห้ามมิให้ยกเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริต"}},{"id":"TH-H004-A161","no":161,"noLabel":{"th":"มาตรา 161"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๑ ถ้ากลฉ้อฉลเป็นแต่เพียงเหตุจูงใจให้คู่กรณีฝ่ายหนึ่งยอมรับข้อกำหนดอันหนักยิ่งกว่าที่คู่กรณีฝ่ายนั้นจะยอมรับโดยปกติ คู่กรณีฝ่ายนั้นจะบอกล้างการนั้นหาได้ไม่ แต่ชอบที่จะเรียกเอาค่าสินไหมทดแทนเพื่อความเสียหายอันเกิดจากกลฉ้อฉลนั้นได้"}},{"id":"TH-H004-A162","no":162,"noLabel":{"th":"มาตรา 162"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๒ ในนิติกรรมสองฝ่าย การที่คู่กรณีฝ่ายหนึ่งจงใจนิ่งเสียไม่แจ้งข้อความจริงหรือคุณสมบัติอันคู่กรณีอีกฝ่ายหนึ่งมิได้รู้ การนั้นจะเป็นกลฉ้อฉล หากพิสูจน์ได้ว่าถ้ามิได้นิ่งเสียเช่นนั้น นิติกรรมนั้นก็คงจะมิได้กระทำขึ้น"}},{"id":"TH-H004-A163","no":163,"noLabel":{"th":"มาตรา 163"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๓ ถ้าคู่กรณีต่างได้กระทำการโดยกลฉ้อฉลด้วยกันทั้งสองฝ่าย ฝ่ายหนึ่งฝ่ายใดจะกล่าวอ้างกลฉ้อฉลของอีกฝ่ายหนึ่ง เพื่อบอกล้างการนั้นหรือเรียกค่าสินไหมทดแทนมิได้"}},{"id":"TH-H004-A164","no":164,"noLabel":{"th":"มาตรา 164"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๔ การแสดงเจตนาเพราะถูกข่มขู่เป็นโมฆียะ การข่มขู่ที่จะทำให้การใดตกเป็นโมฆียะนั้น จะต้องเป็นการข่มขู่ที่จะให้เกิดภัยอันใกล้จะถึงและร้ายแรงถึงขนาดที่จะจูงใจให้ผู้ถูกข่มขู่มีมูลต้องกลัว ซึ่งถ้ามิได้มีการข่มขู่เช่นนั้น การนั้นก็คงจะมิได้กระทำขึ้น"}},{"id":"TH-H004-A165","no":165,"noLabel":{"th":"มาตรา 165"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕ การขู่ว่าจะใช้สิทธิตามปกตินิยม ไม่ถือว่าเป็นการข่มขู่ การใดที่กระทำไปเพราะนับถือยำเกรง ไม่ถือว่าการนั้นได้กระทำเพราะถูกข่มขู่"}},{"id":"TH-H004-A166","no":166,"noLabel":{"th":"มาตรา 166"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖ การข่มขู่ย่อมทำให้การแสดงเจตนาเป็นโมฆียะแม้บุคคลภายนอกจะเป็นผู้ข่มขู่"}},{"id":"TH-H004-A167","no":167,"noLabel":{"th":"มาตรา 167"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๗ ในการวินิจฉัยกรณีความสำคัญผิด กลฉ้อฉล หรือการข่มขู่ให้พิเคราะห์ถึง เพศ อายุ ฐานะ สุขภาพอนามัย และภาวะแห่งจิตของผู้แสดงเจตนาตลอดจนพฤติการณ์และสภาพแวดล้อมอื่น ๆ อันเกี่ยวกับการนั้นด้วย"}},{"id":"TH-H004-A168","no":168,"noLabel":{"th":"มาตรา 168"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๘ การแสดงเจตนาที่กระทำต่อบุคคลซึ่งอยู่เฉพาะหน้าให้ถือว่ามีผลนับแต่ผู้รับการแสดงเจตนาได้ทราบการแสดงเจตนานั้น ความข้อนี้ให้ใช้ตลอดถึงการที่บุคคลหนึ่งแสดงเจตนาไปยังบุคคลอีกคนหนึ่งโดยทางโทรศัพท์ หรือโดยเครื่องมือสื่อสารอย่างอื่น หรือโดยวิธีอื่นซึ่งสามารถติดต่อถึงกันได้ทำนองเดียวกัน"}},{"id":"TH-H004-A169","no":169,"noLabel":{"th":"มาตรา 169"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๙ การแสดงเจตนาที่กระทำต่อบุคคลซึ่งมิได้อยู่เฉพาะหน้าให้ถือว่ามีผลนับแต่เวลาที่การแสดงเจตนานั้นไปถึงผู้รับการแสดงเจตนา แต่ถ้าได้บอกถอนไปถึงผู้รับการแสดงเจตนานั้นก่อนหรือพร้อมกันกับที่การแสดงเจตนานั้นไปถึงผู้รับการแสดงเจตนา การแสดงเจตนานั้นตกเป็นอันไร้ผล การแสดงเจตนาที่ได้ส่งออกไปแล้วย่อมไม่เสื่อมเสียไป แม้ภายหลังการแสดงเจตนานั้นผู้แสดงเจตนาจะถึงแก่ความตาย หรือถูกศาลสั่งให้เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ"}},{"id":"TH-H004-A170","no":170,"noLabel":{"th":"มาตรา 170"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๐ การแสดงเจตนาซึ่งกระทำต่อผู้เยาว์หรือผู้ที่ศาลสั่งให้เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ จะยกขึ้นเป็นข้อต่อสู้ผู้รับการแสดงเจตนาไม่ได้ เว้นแต่ผู้แทนโดยชอบธรรม ผู้อนุบาล หรือผู้พิทักษ์ แล้วแต่กรณี ของผู้รับการแสดงเจตนานั้นได้รู้ด้วย หรือได้ให้ความยินยอมไว้ก่อนแล้ว ความในวรรคหนึ่งมิให้ใช้บังคับ ถ้าการแสดงเจตนานั้นเกี่ยวกับการที่กฎหมายบัญญัติให้ผู้เยาว์หรือคนเสมือนไร้ความสามารถกระทำได้เองโดยลำพัง"}},{"id":"TH-H004-A171","no":171,"noLabel":{"th":"มาตรา 171"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๑ ในการตีความการแสดงเจตนานั้น ให้เพ่งเล็งถึงเจตนาอันแท้จริงยิ่งกว่าถ้อยคำสำนวนหรือตัวอักษร"}},{"id":"TH-H004-A172","no":172,"noLabel":{"th":"มาตรา 172"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๒ โมฆะกรรมนั้นไม่อาจให้สัตยาบันแก่กันได้ และผู้มีส่วนได้เสียคนหนึ่งคนใดจะยกความเสียเปล่าแห่งโมฆะกรรมขึ้นกล่าวอ้างก็ได้ ถ้าจะต้องคืนทรัพย์สินอันเกิดจากโมฆะกรรม ให้นำบทบัญญัติว่าด้วยลาภมิควรได้แห่งประมวลกฎหมายนี้มาใช้บังคับ"}},{"id":"TH-H004-A173","no":173,"noLabel":{"th":"มาตรา 173"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๓ ถ้าส่วนหนึ่งส่วนใดของนิติกรรมเป็นโมฆะ นิติกรรมนั้นย่อมตกเป็นโมฆะทั้งสิ้น เว้นแต่จะพึงสันนิษฐานได้โดยพฤติการณ์แห่งกรณีว่า คู่กรณีเจตนาจะให้ส่วนที่ไม่เป็นโมฆะนั้นแยกออกจากส่วนที่เป็นโมฆะได้"}},{"id":"TH-H004-A174","no":174,"noLabel":{"th":"มาตรา 174"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔ การใดเป็นโมฆะแต่เข้าลักษณะเป็นนิติกรรมอย่างอื่นซึ่งไม่เป็นโมฆะ ให้ถือตามนิติกรรมซึ่งไม่เป็นโมฆะ ถ้าสันนิษฐานได้โดยพฤติการณ์แห่งกรณีว่า หากคู่กรณีได้รู้ว่าการนั้นเป็นโมฆะแล้ว ก็คงจะได้ตั้งใจมาตั้งแต่แรกที่จะทำนิติกรรมอย่างอื่นซึ่งไม่เป็นโมฆะนั้น"}},{"id":"TH-H004-A175","no":175,"noLabel":{"th":"มาตรา 175"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๕ โมฆียะกรรมนั้น บุคคลต่อไปนี้จะบอกล้างเสียก็ได้ (๑) ผู้แทนโดยชอบธรรมหรือผู้เยาว์ซึ่งบรรลุนิติภาวะแล้ว แต่ผู้เยาว์จะบอกล้างก่อนที่ตนบรรลุนิติภาวะก็ได้ถ้าได้รับความยินยอมของผู้แทนโดยชอบธรรม (๒) บุคคลซึ่งศาลสั่งให้เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถเมื่อบุคคลนั้นพ้นจากการเป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถแล้ว หรือผู้อนุบาล หรือผู้พิทักษ์ แล้วแต่กรณี แต่คนเสมือนไร้ความสามารถจะบอกล้างก่อนที่ตนจะพ้นจากการเป็นคนเสมือนไร้ความสามารถก็ได้ถ้าได้รับความยินยอมของผู้พิทักษ์ (๓) บุคคลผู้แสดงเจตนาเพราะสำคัญผิด หรือถูกกลฉ้อฉล หรือถูกข่มขู่ (๔) บุคคลวิกลจริตผู้กระทำนิติกรรมอันเป็นโมฆียะตามมาตรา ๓๐ ในขณะที่จริตของบุคคลนั้นไม่วิกลแล้ว ถ้าบุคคลผู้ทำนิติกรรมอันเป็นโมฆียะถึงแก่ความตายก่อนมีการบอกล้างโมฆียะกรรม ทายาทของบุคคลดังกล่าวอาจบอกล้างโมฆียะกรรมนั้นได้"}},{"id":"TH-H004-A176","no":176,"noLabel":{"th":"มาตรา 176"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๖ โมฆียะกรรมเมื่อบอกล้างแล้ว ให้ถือว่าเป็นโมฆะมาแต่เริ่มแรก และให้ผู้เป็นคู่กรณีกลับคืนสู่ฐานะเดิม ถ้าเป็นการพ้นวิสัยจะให้กลับคืนเช่นนั้นได้ ก็ให้ได้รับค่าเสียหายชดใช้ให้แทน ถ้าบุคคลใดได้รู้หรือควรจะได้รู้ว่าการใดเป็นโมฆียะ เมื่อบอกล้างแล้ว ให้ถือว่าบุคคลนั้นได้รู้ว่าการนั้นเป็นโมฆะ นับแต่วันที่ได้รู้หรือควรจะได้รู้ว่าเป็นโมฆียะ ห้ามมิให้ใช้สิทธิเรียกร้องอันเกิดแต่การกลับคืนสู่ฐานะเดิมตามวรรคหนึ่ง เมื่อพ้นหนึ่งปีนับแต่วันบอกล้างโมฆียะกรรม"}},{"id":"TH-H004-A177","no":177,"noLabel":{"th":"มาตรา 177"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๗ ถ้าบุคคลผู้มีสิทธิบอกล้างโมฆียะกรรมตามมาตรา ๑๗๕ ผู้หนึ่งผู้ใด ได้ให้สัตยาบันแก่โมฆียะกรรม ให้ถือว่าการนั้นเป็นอันสมบูรณ์มาแต่เริ่มแรก แต่ทั้งนี้ย่อมไม่กระทบกระเทือนถึงสิทธิของบุคคลภายนอก"}},{"id":"TH-H004-A178","no":178,"noLabel":{"th":"มาตรา 178"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๘ การบอกล้างหรือให้สัตยาบันแก่โมฆียะกรรม ย่อมกระทำได้โดยการแสดงเจตนาแก่คู่กรณีอีกฝ่ายหนึ่งซึ่งเป็นบุคคลที่มีตัวกำหนดได้แน่นอน"}},{"id":"TH-H004-A179","no":179,"noLabel":{"th":"มาตรา 179"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๙ การให้สัตยาบันแก่โมฆียะกรรมนั้น จะสมบูรณ์ต่อเมื่อได้กระทำภายหลังเวลาที่มูลเหตุให้เป็นโมฆียะกรรมนั้นหมดสิ้นไปแล้ว บุคคลซึ่งศาลได้สั่งให้เป็นคนไร้ความสามารถ คนเสมือนไร้ความสามารถหรือบุคคลวิกลจริต ผู้กระทำนิติกรรมอันเป็นโมฆียะตามมาตรา ๓๐ จะให้สัตยาบันแก่โมฆียะกรรมได้ต่อเมื่อได้รู้เห็นซึ่งโมฆียะกรรมนั้นภายหลังที่บุคคลนั้นพ้นจากการเป็นคนไร้ความสามารถ คนเสมือนไร้ความสามารถหรือในขณะที่จริตของบุคคลนั้นไม่วิกล แล้วแต่กรณี ทายาทของบุคคลผู้ทำนิติกรรมอันเป็นโมฆียะ จะให้สัตยาบันแก่โมฆียะกรรมได้นับแต่เวลาที่ผู้ทำนิติกรรมนั้นถึงแก่ความตาย เว้นแต่สิทธิที่จะบอกล้างโมฆียะกรรมของผู้ตายนั้นได้สิ้นสุดลงแล้ว บทบัญญัติวรรคหนึ่งและวรรคสองมิให้ใช้บังคับ ถ้าการให้สัตยาบันแก่โมฆียะกรรมกระทำโดยผู้แทนโดยชอบธรรม ผู้อนุบาลหรือผู้พิทักษ์"}},{"id":"TH-H004-A180","no":180,"noLabel":{"th":"มาตรา 180"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๘๐ ภายหลังเวลาอันพึงให้สัตยาบันได้ตามมาตรา ๑๗๙ ถ้ามีพฤติการณ์อย่างหนึ่งอย่างใดดังต่อไปนี้เกิดขึ้นเกี่ยวด้วยโมฆียะกรรมโดยการกระทำของบุคคลซึ่งมีสิทธิบอกล้างโมฆียะกรรมตามมาตรา ๑๗๕ ถ้ามิได้สงวนสิทธิไว้แจ้งชัดประการใดให้ถือว่าเป็นการให้สัตยาบัน (๑) ได้ปฏิบัติการชำระหนี้แล้วทั้งหมดหรือแต่บางส่วน (๒) ได้มีการเรียกให้ชำระหนี้นั้นแล้ว (๓) ได้มีการแปลงหนี้ใหม่ (๔) ได้มีการให้ประกันเพื่อหนี้นั้น (๕) ได้มีการโอนสิทธิหรือความรับผิดทั้งหมดหรือแต่บางส่วน (๖) ได้มีการกระทำอย่างอื่นอันแสดงได้ว่าเป็นการให้สัตยาบัน"}},{"id":"TH-H004-A181","no":181,"noLabel":{"th":"มาตรา 181"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๘๑ โมฆียะกรรมนั้นจะบอกล้างมิได้เมื่อพ้นเวลาหนึ่งปีนับแต่เวลาที่อาจให้สัตยาบันได้ หรือเมื่อพ้นเวลาสิบปีนับแต่ได้ทำนิติกรรมอันเป็นโมฆียะนั้น"}},{"id":"TH-H004-A182","no":182,"noLabel":{"th":"มาตรา 182"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๒ ข้อความใดอันบังคับไว้ให้นิติกรรมเป็นผลหรือสิ้นผลต่อเมื่อมีเหตุการณ์อันไม่แน่นอนว่าจะเกิดขึ้นหรือไม่ในอนาคต ข้อความนั้นเรียกว่าเงื่อนไข"}},{"id":"TH-H004-A183","no":183,"noLabel":{"th":"มาตรา 183"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๓ นิติกรรมใดมีเงื่อนไขบังคับก่อน นิติกรรมนั้นย่อมเป็นผลต่อเมื่อเงื่อนไขนั้นสำเร็จแล้ว นิติกรรมใดมีเงื่อนไขบังคับหลัง นิติกรรมนั้นย่อมสิ้นผลในเมื่อเงื่อนไขนั้นสำเร็จแล้ว ถ้าคู่กรณีแห่งนิติกรรมได้แสดงเจตนาไว้ด้วยกันว่า ความสำเร็จแห่งเงื่อนไขนั้นให้มีผลย้อนหลังไปถึงเวลาใดเวลาหนึ่งก่อนสำเร็จ ก็ให้เป็นไปตามเจตนาเช่นนั้น"}},{"id":"TH-H004-A184","no":184,"noLabel":{"th":"มาตรา 184"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๔ ในระหว่างที่เงื่อนไขยังไม่สำเร็จ คู่กรณีฝ่ายหนึ่งฝ่ายใดแห่งนิติกรรมอันอยู่ในบังคับเงื่อนไขจะต้องงดเว้นไม่กระทำการอย่างหนึ่งอย่างใดให้เป็นที่เสื่อมเสียประโยชน์แก่คู่กรณีอีกฝ่ายหนึ่ง ซึ่งจะพึงได้จากความสำเร็จแห่งเงื่อนไขนั้น"}},{"id":"TH-H004-A185","no":185,"noLabel":{"th":"มาตรา 185"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๕ ในระหว่างที่เงื่อนไขยังมิได้สำเร็จนั้น สิทธิและหน้าที่ต่าง ๆ ของคู่กรณีมีอย่างไร จะจำหน่าย จะรับมรดก จะจัดการป้องกันรักษา หรือจะทำประกันไว้ประการใดตามกฎหมายก็ย่อมทำได้"}},{"id":"TH-H004-A186","no":186,"noLabel":{"th":"มาตรา 186"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๖ ถ้าความสำเร็จแห่งเงื่อนไขจะเป็นทางให้คู่กรณีฝ่ายใดเสียเปรียบ และคู่กรณีฝ่ายนั้นกระทำการโดยไม่สุจริตจนเป็นเหตุให้เงื่อนไขนั้นไม่สำเร็จให้ถือว่าเงื่อนไขนั้นสำเร็จแล้ว ถ้าความสำเร็จแห่งเงื่อนไขจะเป็นทางให้คู่กรณีฝ่ายใดได้เปรียบ และคู่กรณีฝ่ายนั้นกระทำการโดยไม่สุจริตจนเป็นเหตุให้เงื่อนไขนั้นสำเร็จ ให้ถือว่าเงื่อนไขนั้นมิได้สำเร็จเลย"}},{"id":"TH-H004-A187","no":187,"noLabel":{"th":"มาตรา 187"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๗ ถ้าเงื่อนไขสำเร็จแล้วในเวลาทำนิติกรรม หากเป็นเงื่อนไขบังคับก่อนให้ถือว่านิติกรรมนั้นไม่มีเงื่อนไข หากเป็นเงื่อนไขบังคับหลังให้ถือว่านิติกรรมนั้นเป็นโมฆะ ถ้าเป็นอันแน่นอนในเวลาทำนิติกรรมว่าเงื่อนไขไม่อาจสำเร็จได้ หากเป็นเงื่อนไขบังคับก่อน ให้ถือว่านิติกรรมนั้นเป็นโมฆะ หากเป็นเงื่อนไขบังคับหลังให้ถือว่านิติกรรมนั้นไม่มีเงื่อนไข ตราบใดที่คู่กรณียังไม่รู้ว่าเงื่อนไขได้สำเร็จแล้วตามวรรคหนึ่ง หรือไม่อาจสำเร็จได้ตามวรรคสอง ตราบนั้นคู่กรณียังมีสิทธิและหน้าที่ตามมาตรา ๑๘๔ และมาตรา ๑๘๕"}},{"id":"TH-H004-A188","no":188,"noLabel":{"th":"มาตรา 188"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๘ นิติกรรมใดมีเงื่อนไขอันไม่ชอบด้วยกฎหมาย หรือขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน นิติกรรมนั้นเป็นโมฆะ"}},{"id":"TH-H004-A189","no":189,"noLabel":{"th":"มาตรา 189"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๘๙ นิติกรรมใดมีเงื่อนไขบังคับก่อนและเงื่อนไขนั้นเป็นการพ้นวิสัย นิติกรรมนั้นเป็นโมฆะ นิติกรรมใดมีเงื่อนไขบังคับหลังและเงื่อนไขนั้นเป็นการพ้นวิสัย ให้ถือว่านิติกรรมนั้นไม่มีเงื่อนไข"}},{"id":"TH-H004-A190","no":190,"noLabel":{"th":"มาตรา 190"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๙๐ นิติกรรมใดมีเงื่อนไขบังคับก่อนและเป็นเงื่อนไขอันจะสำเร็จได้หรือไม่ สุดแล้วแต่ใจของฝ่ายลูกหนี้ นิติกรรมนั้นเป็นโมฆะ"}},{"id":"TH-H004-A191","no":191,"noLabel":{"th":"มาตรา 191"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๙๑ นิติกรรมใดมีเงื่อนเวลาเริ่มต้นกำหนดไว้ ห้ามมิให้ทวงถามให้ปฏิบัติการตามนิติกรรมนั้นก่อนถึงเวลาที่กำหนด นิติกรรมใดมีเงื่อนเวลาสิ้นสุดกำหนดไว้ นิติกรรมนั้นย่อมสิ้นผลเมื่อถึงเวลาที่กำหนด"}},{"id":"TH-H004-A192","no":192,"noLabel":{"th":"มาตรา 192"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๙๒ เงื่อนเวลาเริ่มต้นหรือเงื่อนเวลาสิ้นสุดนั้น ให้สันนิษฐานไว้ก่อนว่ากำหนดไว้เพื่อประโยชน์แก่ฝ่ายลูกหนี้ เว้นแต่จะปรากฏโดยเนื้อความแห่งตราสารหรือโดยพฤติการณ์แห่งกรณีว่าได้ตั้งใจจะให้เป็นประโยชน์แก่ฝ่ายเจ้าหนี้หรือแก่คู่กรณีทั้งสองฝ่ายด้วยกัน ถ้าเงื่อนเวลาเป็นประโยชน์แก่ฝ่ายใด ฝ่ายนั้นจะสละประโยชน์นั้นเสียก็ได้ หากไม่กระทบกระเทือนถึงประโยชน์อันคู่กรณีอีกฝ่ายหนึ่งจะพึงได้รับจากเงื่อนเวลานั้น"}},{"id":"TH-H004-A193","no":193,"noLabel":{"th":"มาตรา 193"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๙๓ ในกรณีดังต่อไปนี้ ฝ่ายลูกหนี้จะถือเอาประโยชน์แห่งเงื่อนเวลาเริ่มต้นหรือเงื่อนเวลาสิ้นสุดมิได้ (๑) ลูกหนี้ถูกศาลสั่งพิทักษ์ทรัพย์เด็ดขาดตามกฎหมายว่าด้วยล้มละลาย (๒) ลูกหนี้ไม่ให้ประกันในเมื่อจำต้องให้ (๓) ลูกหนี้ได้ทำลาย หรือทำให้ลดน้อยถอยลงซึ่งประกันอันได้ให้ไว้ (๔) ลูกหนี้นำทรัพย์สินของบุคคลอื่นมาให้เป็นประกันโดยเจ้าของทรัพย์สินนั้นมิได้ยินยอมด้วย"}},{"id":"TH-H004-A193.001","no":193.001,"noLabel":{"th":"มาตรา 193/1"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๑ การนับระยะเวลาทั้งปวง ให้บังคับตามบทบัญญัติแห่งลักษณะนี้ เว้นแต่จะมีกฎหมาย คำสั่งศาล ระเบียบข้อบังคับ หรือนิติกรรมกำหนดเป็นอย่างอื่น"}},{"id":"TH-H004-A193.002","no":193.002,"noLabel":{"th":"มาตรา 193/2"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๒ การคำนวณระยะเวลา ให้คำนวณเป็นวัน แต่ถ้ากำหนดเป็นหน่วยเวลาที่สั้นกว่าวัน ก็ให้คำนวณตามหน่วยเวลาที่กำหนดนั้น"}},{"id":"TH-H004-A193.003","no":193.003,"noLabel":{"th":"มาตรา 193/3"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๓ ถ้ากำหนดระยะเวลาเป็นหน่วยเวลาที่สั้นกว่าวันให้เริ่มต้นนับในขณะที่เริ่มการนั้น ถ้ากำหนดระยะเวลาเป็นวัน สัปดาห์ เดือนหรือปี มิให้นับวันแรกแห่งระยะเวลานั้นรวมเข้าด้วยกัน เว้นแต่จะเริ่มการในวันนั้นเองตั้งแต่เวลาที่ถือได้ว่าเป็นเวลาเริ่มต้นทำการงานกันตามประเพณี"}},{"id":"TH-H004-A193.004","no":193.004,"noLabel":{"th":"มาตรา 193/4"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๔ ในทางคดีความ ในทางราชการ หรือทางธุรกิจการค้าและอุตสาหกรรม วัน หมายความว่า เวลาทำการตามที่ได้กำหนดขึ้นโดยกฎหมาย คำสั่งศาล หรือระเบียบข้อบังคับ หรือเวลาทำการตามปกติของกิจการนั้น แล้วแต่กรณี"}},{"id":"TH-H004-A193.005","no":193.005,"noLabel":{"th":"มาตรา 193/5"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๕ ถ้ากำหนดระยะเวลาเป็นสัปดาห์ เดือนหรือปี ให้คำนวณตามปีปฏิทิน ถ้าระยะเวลามิได้กำหนดนับแต่วันต้นแห่งสัปดาห์ วันต้นแห่งเดือนหรือปี ระยะเวลาย่อมสิ้นสุดลงในวันก่อนหน้าจะถึงวันแห่งสัปดาห์ เดือนหรือปีสุดท้ายอันเป็นวันตรงกับวันเริ่มระยะเวลานั้น ถ้าในระยะเวลานับเป็นเดือนหรือปีนั้นไม่มีวันตรงกันในเดือนสุดท้าย ให้ถือเอาวันสุดท้ายแห่งเดือนนั้นเป็นวันสิ้นสุดระยะเวลา"}},{"id":"TH-H004-A193.006","no":193.006,"noLabel":{"th":"มาตรา 193/6"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๖ ถ้าระยะเวลากำหนดเป็นเดือนและวัน หรือกำหนดเป็นเดือนและส่วนของเดือน ให้นับจำนวนเดือนเต็มก่อน แล้วจึงนับจำนวนวันหรือส่วนของเดือนเป็นวัน ถ้าระยะเวลากำหนดเป็นส่วนของปี ให้คำนวณส่วนของปีเป็นเดือนก่อนหากมีส่วนของเดือน ให้นับส่วนของเดือนเป็นวัน การคำนวณส่วนของเดือนตามวรรคหนึ่งและวรรคสอง ให้ถือว่าเดือนหนึ่งมีสามสิบวัน"}},{"id":"TH-H004-A193.007","no":193.007,"noLabel":{"th":"มาตรา 193/7"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๗ ถ้ามีการขยายระยะเวลาออกไปโดยมิได้มีกำหนดวันเริ่มต้นแห่งระยะเวลาที่ขยายออกไป ให้นับวันที่ต่อจากวันสุดท้ายของระยะเวลาเดิมเป็นวันเริ่มต้น"}},{"id":"TH-H004-A193.008","no":193.008,"noLabel":{"th":"มาตรา 193/8"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๙๓/๘ ถ้าวันสุดท้ายของระยะเวลาเป็นวันหยุดทำการตามประกาศเป็นทางการ หรือตามประเพณี ให้นับวันที่เริ่มทำการใหม่ต่อจากวันที่หยุดทำการนั้นเป็นวันสุดท้ายของระยะเวลา"}},{"id":"TH-H004-A193.009","no":193.009,"noLabel":{"th":"มาตรา 193/9"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๙ สิทธิเรียกร้องใด ๆ ถ้ามิได้ใช้บังคับภายในระยะเวลาที่กฎหมายกำหนด สิทธิเรียกร้องนั้นเป็นอันขาดอายุความ"}},{"id":"TH-H004-A193.01","no":193.01,"noLabel":{"th":"มาตรา 193/10"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๐ สิทธิเรียกร้องที่ขาดอายุความ ลูกหนี้มีสิทธิที่จะปฏิเสธการชำระหนี้ตามสิทธิเรียกร้องนั้นได้"}},{"id":"TH-H004-A193.011","no":193.011,"noLabel":{"th":"มาตรา 193/11"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๑ อายุความที่กฎหมายกำหนดไว้นั้น คู่กรณีจะตกลงกันให้งดใช้หรือขยายออกหรือย่นเข้าไม่ได้"}},{"id":"TH-H004-A193.012","no":193.012,"noLabel":{"th":"มาตรา 193/12"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๒ อายุความให้เริ่มนับแต่ขณะที่อาจบังคับสิทธิเรียกร้องได้เป็นต้นไป ถ้าเป็นสิทธิเรียกร้องให้งดเว้นกระทำการอย่างใด ให้เริ่มนับแต่เวลาแรกที่ฝ่าฝืนกระทำการนั้น"}},{"id":"TH-H004-A193.013","no":193.013,"noLabel":{"th":"มาตรา 193/13"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๓ สิทธิเรียกร้องที่เจ้าหนี้ยังไม่อาจบังคับได้จนกว่าจะได้ทวงถามให้ลูกหนี้ชำระหนี้ก่อน ให้เริ่มนับอายุความตั้งแต่เวลาแรกที่อาจทวงถามได้เป็นต้นไป แต่ถ้าลูกหนี้ยังไม่ต้องชำระหนี้จนกว่าระยะเวลาหนึ่งจะได้ล่วงพ้นไปแล้วนับแต่เวลาที่ได้ทวงถามนั้น ให้เริ่มนับอายุความตั้งแต่ระยะเวลานั้นได้สิ้นสุดไปแล้ว"}},{"id":"TH-H004-A193.014","no":193.014,"noLabel":{"th":"มาตรา 193/14"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๔ อายุความย่อมสะดุดหยุดลงในกรณีดังต่อไปนี้ (๑) ลูกหนี้รับสภาพหนี้ต่อเจ้าหนี้ตามสิทธิเรียกร้องโดยทำเป็นหนังสือรับสภาพหนี้ให้ ชำระหนี้ให้บางส่วน ชำระดอกเบี้ย ให้ประกัน หรือกระทำการใด ๆ อันปราศจากข้อสงสัยแสดงให้เห็นเป็นปริยายว่ายอมรับสภาพหนี้ตามสิทธิเรียกร้อง (๒) เจ้าหนี้ได้ฟ้องคดีเพื่อตั้งหลักฐานสิทธิเรียกร้องหรือเพื่อให้ชำระหนี้ (๓) เจ้าหนี้ได้ยื่นคำขอรับชำระหนี้ในคดีล้มละลาย (๔) เจ้าหนี้ได้มอบข้อพิพาทให้อนุญาโตตุลาการพิจารณา (๕) เจ้าหนี้ได้กระทำการอื่นใดอันมีผลเป็นอย่างเดียวกันกับการฟ้องคดี"}},{"id":"TH-H004-A193.015","no":193.015,"noLabel":{"th":"มาตรา 193/15"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๕ เมื่ออายุความสะดุดหยุดลงแล้ว ระยะเวลาที่ล่วงไปก่อนนั้นไม่นับเข้าในอายุความ เมื่อเหตุที่ทำให้อายุความสะดุดหยุดลงสิ้นสุดเวลาใด ให้เริ่มนับอายุความใหม่ตั้งแต่เวลานั้น"}},{"id":"TH-H004-A193.016","no":193.016,"noLabel":{"th":"มาตรา 193/16"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๖ หนี้ใดซึ่งตามมูลแห่งหนี้นั้น เจ้าหนี้จะได้รับชำระหนี้เป็นคราว ๆ เจ้าหนี้มีสิทธิเรียกให้ลูกหนี้ทำหนังสือรับสภาพหนี้ให้ในเวลาใดเวลาหนึ่งก่อนอายุความครบบริบูรณ์ เพื่อเป็นหลักฐานว่าอายุความสะดุดหยุดลง"}},{"id":"TH-H004-A193.017","no":193.017,"noLabel":{"th":"มาตรา 193/17"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๗ ในกรณีที่อายุความสะดุดหยุดลงเพราะเหตุตามมาตรา ๑๙๓/๑๔ (๒) หากคดีนั้นได้มีคำพิพากษาถึงที่สุดให้ยกคำฟ้อง หรือคดีเสร็จไปโดยการจำหน่ายคดีเพราะเหตุถอนฟ้อง หรือทิ้งฟ้อง ให้ถือว่าอายุความไม่เคยสะดุดหยุดลง ในกรณีที่คดีนั้นศาลไม่รับหรือคืนหรือให้ยกคำฟ้องเพราะเหตุคดีไม่อยู่ในอำนาจศาล หรือศาลให้ยกคำฟ้องโดยไม่ตัดสิทธิโจทก์ที่จะฟ้องใหม่ และปรากฏว่าอายุความครบกำหนดไปแล้วในระหว่างการพิจารณา หรือจะครบกำหนดภายในหกสิบวันนับแต่วันที่คำพิพากษาหรือคำสั่งนั้นถึงที่สุด ให้เจ้าหนี้มีสิทธิฟ้องคดีเพื่อตั้งหลักฐานสิทธิเรียกร้องหรือเพื่อให้ชำระหนี้ภายในหกสิบวันนับแต่วันที่คำพิพากษาหรือคำสั่งนั้นถึงที่สุด"}},{"id":"TH-H004-A193.018","no":193.018,"noLabel":{"th":"มาตรา 193/18"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๘ ให้นำมาตรา ๑๙๓/๑๗ มาใช้บังคับแก่กรณีที่อายุความสะดุดหยุดลงเพราะเหตุตามมาตรา ๑๙๓/๑๔ (๓) (๔) และ (๕) โดยอนุโลม"}},{"id":"TH-H004-A193.019","no":193.019,"noLabel":{"th":"มาตรา 193/19"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๑๙ ในขณะที่อายุความจะครบกำหนดนั้น ถ้ามีเหตุสุดวิสัยมาขัดขวางมิให้เจ้าหนี้กระทำการตามมาตรา ๑๙๓/๑๔ ให้อายุความนั้นยังไม่ครบกำหนดจนกว่าจะพ้นสามสิบวันนับแต่วันที่เหตุสุดวิสัยนั้นได้สิ้นสุดลง"}},{"id":"TH-H004-A193.02","no":193.02,"noLabel":{"th":"มาตรา 193/20"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๐ อายุความสิทธิเรียกร้องของผู้เยาว์หรือของบุคคลวิกลจริตอันศาลจะสั่งให้เป็นคนไร้ความสามารถหรือไม่ก็ตาม ถ้าจะครบกำหนดลงในขณะที่บุคคลดังกล่าวยังไม่ลุถึงความสามารถเต็มภูมิ หรือในระหว่างหนึ่งปีนับแต่วันที่บุคคลดังกล่าวไม่มีผู้แทนโดยชอบธรรมหรือผู้อนุบาล อายุความนั้นยังไม่ครบกำหนดจนกว่าจะครบหนึ่งปีนับแต่วันที่บุคคลนั้นได้ลุถึงความสามารถเต็มภูมิหรือได้มีผู้แทนโดยชอบธรรมหรือผู้อนุบาล แล้วแต่กรณี แต่ถ้าอายุความสิทธิเรียกร้องนั้นมีระยะเวลาน้อยกว่าหนึ่งปีก็ให้นำกำหนดระยะเวลาที่สั้นกว่านั้นมาใช้แทนกำหนดระยะเวลาหนึ่งปีดังกล่าว"}},{"id":"TH-H004-A193.021","no":193.021,"noLabel":{"th":"มาตรา 193/21"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๑ อายุความสิทธิเรียกร้องของผู้เยาว์หรือของคนไร้ความสามารถหรือของคนเสมือนไร้ความสามารถ ที่จะฟ้องร้องผู้แทนโดยชอบธรรมหรือผู้อนุบาลหรือผู้พิทักษ์ของตนนั้น ถ้าจะครบกำหนดลงในขณะที่บุคคลดังกล่าวยังไม่ลุถึงความสามารถเต็มภูมิ หรือในระหว่างหนึ่งปีนับแต่วันที่บุคคลดังกล่าวไม่มีผู้แทนโดยชอบธรรมหรือผู้อนุบาลหรือผู้พิทักษ์ อายุความนั้นยังไม่ครบกำหนดจนกว่าจะครบหนึ่งปีนับแต่วันที่บุคคลนั้นได้ลุถึงความสามารถเต็มภูมิหรือได้มีผู้แทนโดยชอบธรรมหรือผู้อนุบาลหรือผู้พิทักษ์ แล้วแต่กรณี แต่ถ้าอายุความสิทธิเรียกร้องนั้นมีระยะเวลาน้อยกว่าหนึ่งปี ก็ให้นำกำหนดระยะเวลาที่สั้นกว่านั้นมาใช้แทนกำหนดระยะเวลาหนึ่งปีดังกล่าว"}},{"id":"TH-H004-A193.022","no":193.022,"noLabel":{"th":"มาตรา 193/22"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๒ อายุความสิทธิเรียกร้องระหว่างคู่สมรส ถ้าจะครบกำหนดก่อนหรือภายในหนึ่งปีนับแต่วันที่การสมรสสิ้นสุดลง อายุความนั้นยังไม่ครบกำหนดจนกว่าจะครบหนึ่งปีนับแต่วันที่การสมรสสิ้นสุดลง"}},{"id":"TH-H004-A193.023","no":193.023,"noLabel":{"th":"มาตรา 193/23"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๓ อายุความสิทธิเรียกร้องอันเป็นคุณหรือเป็นโทษแก่ผู้ตาย ถ้าจะครบกำหนดภายในหนึ่งปีนับแต่วันตาย อายุความนั้นยังไม่ครบกำหนดจนกว่าจะครบหนึ่งปีนับแต่วันตาย"}},{"id":"TH-H004-A193.024","no":193.024,"noLabel":{"th":"มาตรา 193/24"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๔ เมื่ออายุความครบกำหนดแล้ว ลูกหนี้จะสละประโยชน์แห่งอายุความนั้นเสียก็ได้ แต่การสละประโยชน์เช่นว่านี้ไม่มีผลกระทบกระเทือนสิทธิของบุคคลภายนอกหรือผู้ค้ำประกัน"}},{"id":"TH-H004-A193.025","no":193.025,"noLabel":{"th":"มาตรา 193/25"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๕ เมื่ออายุความครบกำหนดแล้ว ให้มีผลย้อนหลังขึ้นไปถึงวันที่เริ่มนับอายุความ"}},{"id":"TH-H004-A193.026","no":193.026,"noLabel":{"th":"มาตรา 193/26"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๖ เมื่อสิทธิเรียกร้องส่วนที่เป็นประธานขาดอายุความให้สิทธิเรียกร้องส่วนที่เป็นอุปกรณ์นั้นขาดอายุความด้วย แม้ว่าอายุความของสิทธิเรียกร้องส่วนที่เป็นอุปกรณ์นั้นจะยังไม่ครบกำหนดก็ตาม"}},{"id":"TH-H004-A193.027","no":193.027,"noLabel":{"th":"มาตรา 193/27"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๗ ผู้รับจำนอง ผู้รับจำนำ ผู้ทรงสิทธิยึดหน่วง หรือผู้ทรงบุริมสิทธิเหนือทรัพย์สินของลูกหนี้อันตนได้ยึดถือไว้ ยังคงมีสิทธิบังคับชำระหนี้จากทรัพย์สินที่จำนอง จำนำ หรือที่ได้ยึดถือไว้ แม้ว่าสิทธิเรียกร้องส่วนที่เป็นประธานจะขาดอายุความแล้วก็ตาม แต่จะใช้สิทธินั้นบังคับให้ชำระดอกเบี้ยที่ค้างย้อนหลังเกินห้าปีขึ้นไปไม่ได้"}},{"id":"TH-H004-A193.028","no":193.028,"noLabel":{"th":"มาตรา 193/28"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๘ การชำระหนี้ตามสิทธิเรียกร้องซึ่งขาดอายุความแล้วนั้นไม่ว่ามากน้อยเพียงใดจะเรียกคืนไม่ได้ แม้ว่าผู้ชำระหนี้จะไม่รู้ว่าสิทธิเรียกร้องขาดอายุความแล้วก็ตาม บทบัญญัติในวรรคหนึ่ง ให้ใช้บังคับแก่การที่ลูกหนี้รับสภาพความรับผิดโดยมีหลักฐานเป็นหนังสือ หรือโดยการให้ประกันด้วย แต่จะอ้างความข้อนี้ขึ้นเป็นโทษแก่ผู้ค้ำประกันเดิมไม่ได้"}},{"id":"TH-H004-A193.029","no":193.029,"noLabel":{"th":"มาตรา 193/29"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๓/๒๙ เมื่อไม่ได้ยกอายุความขึ้นเป็นข้อต่อสู้ ศาลจะอ้างเอาอายุความมาเป็นเหตุยกฟ้องไม่ได้"}},{"id":"TH-H004-A193.03","no":193.03,"noLabel":{"th":"มาตรา 193/30"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๐ อายุความนั้น ถ้าประมวลกฎหมายนี้หรือกฎหมายอื่นมิได้บัญญัติไว้โดยเฉพาะให้มีกำหนดสิบปี"}},{"id":"TH-H004-A193.031","no":193.031,"noLabel":{"th":"มาตรา 193/31"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๑ สิทธิเรียกร้องของรัฐที่จะเรียกเอาค่าภาษีอากรให้มีกำหนดอายุความสิบปี ส่วนสิทธิเรียกร้องของรัฐที่จะเรียกเอาหนี้อย่างอื่นให้บังคับตามบทบัญญัติในลักษณะนี้"}},{"id":"TH-H004-A193.032","no":193.032,"noLabel":{"th":"มาตรา 193/32"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๒ สิทธิเรียกร้องที่เกิดขึ้นโดยคำพิพากษาของศาลที่ถึงที่สุด หรือโดยสัญญาประนีประนอมยอมความ ให้มีกำหนดอายุความสิบปี ทั้งนี้ ไม่ว่าสิทธิเรียกร้องเดิมจะมีกำหนดอายุความเท่าใด"}},{"id":"TH-H004-A193.033","no":193.033,"noLabel":{"th":"มาตรา 193/33"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๓ สิทธิเรียกร้องดังต่อไปนี้ให้มีกำหนดอายุความห้าปี (๑) ดอกเบี้ยค้างชำระ (๒) เงินที่ต้องชำระเพื่อผ่อนทุนคืนเป็นงวด ๆ (๓) ค่าเช่าทรัพย์สินค้างชำระ เว้นแต่ค่าเช่าสังหาริมทรัพย์ตามมาตรา ๑๙๓/๓๔ (๖) (๔) เงินค้างจ่าย คือ เงินเดือน เงินปี เงินบำนาญ ค่าอุปการะเลี้ยงดูและเงินอื่น ๆ ในลักษณะทำนองเดียวกับที่มีการกำหนดจ่ายเป็นระยะเวลา (๕) สิทธิเรียกร้องตามมาตรา ๑๙๓/๓๔ (๑) (๒) และ (๕) ที่ไม่อยู่ในบังคับอายุความสองปี"}},{"id":"TH-H004-A193.034","no":193.034,"noLabel":{"th":"มาตรา 193/34"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๔ สิทธิเรียกร้องดังต่อไปนี้ ให้มีกำหนดอายุความสองปี (๑) ผู้ประกอบการค้าหรืออุตสาหกรรม ผู้ประกอบหัตถกรรม ผู้ประกอบศิลปอุตสาหกรรมหรือช่างฝีมือ เรียกเอาค่าของที่ได้ส่งมอบ ค่าการงานที่ได้ทำ หรือค่าดูแลกิจการของผู้อื่น รวมทั้งเงินที่ได้ออกทดรองไป เว้นแต่เป็นการที่ได้ทำเพื่อกิจการของฝ่ายลูกหนี้นั้นเอง (๒) ผู้ประกอบเกษตรกรรมหรือการป่าไม้ เรียกเอาค่าของที่ได้ส่งมอบอันเป็นผลิตผลทางเกษตรหรือป่าไม้ เฉพาะที่ใช้สอยในบ้านเรือนของฝ่ายลูกหนี้นั้นเอง (๓) ผู้ขนส่งคนโดยสารหรือสิ่งของหรือผู้รับส่งข่าวสาร เรียกเอาค่าโดยสาร ค่าระวาง ค่าเช่า ค่าธรรมเนียม รวมทั้งเงินที่ได้ออกทดรองไป (๔) ผู้ประกอบธุรกิจโรงแรมหรือหอพัก ผู้ประกอบธุรกิจในการจำหน่ายอาหารและเครื่องดื่ม หรือผู้ประกอบธุรกิจสถานบริการตามกฎหมายว่าด้วยสถานบริการเรียกเอาค่าที่พัก อาหารหรือเครื่องดื่ม ค่าบริการหรือค่าการงานที่ได้ทำให้แก่ผู้มาพักหรือใช้บริการ รวมทั้งเงินที่ได้ออกทดรองไป (๕) ผู้ขายสลากกินแบ่ง สลากกินรวบ หรือสลากที่คล้ายคลึงกัน เรียกเอาค่าขายสลาก เว้นแต่เป็นการขายเพื่อการขายต่อ (๖) ผู้ประกอบธุรกิจในการให้เช่าสังหาริมทรัพย์ เรียกเอาค่าเช่า (๗) บุคคลซึ่งมิได้เข้าอยู่ในประเภทที่ระบุไว้ใน (๑) แต่เป็นผู้ประกอบธุรกิจในการดูแลกิจการของผู้อื่นหรือรับทำการงานต่าง ๆ เรียกเอาสินจ้างอันจะพึงได้รับในการนั้น รวมทั้งเงินที่ได้ออกทดรองไป (๘) ลูกจ้างซึ่งรับใช้การงานส่วนบุคคล เรียกเอาค่าจ้างหรือสินจ้างอย่างอื่น เพื่อการงานที่ทำ รวมทั้งเงินที่ได้ออกทดรองไป หรือนายจ้างเรียกเอาคืนซึ่งเงินเช่นว่านั้นที่ตนได้จ่ายล่วงหน้าไป (๙) ลูกจ้างไม่ว่าจะเป็นลูกจ้างประจำ ลูกจ้างชั่วคราว หรือลูกจ้างรายวัน รวมทั้งผู้ฝึกหัดงาน เรียกเอาค่าจ้างหรือสินจ้างอย่างอื่น รวมทั้งเงินที่ได้ออกทดรองไป หรือนายจ้างเรียกเอาคืนซึ่งเงินเช่นว่านั้นที่ตนได้จ่ายล่วงหน้าไป (๑๐) ครูสอนผู้ฝึกหัดงาน เรียกเอาค่าฝึกสอนและค่าใช้จ่ายอย่างอื่นตามที่ได้ตกลงกันไว้ รวมทั้งเงินที่ได้ออกทดรองไป (๑๑) เจ้าของสถานศึกษาหรือสถานพยาบาล เรียกเอาค่าธรรมเนียมการเรียนและค่าธรรมเนียมอื่น ๆ หรือค่ารักษาพยาบาลและค่าใช้จ่ายอย่างอื่น รวมทั้งเงินที่ได้ออกทดรองไป (๑๒) ผู้รับคนไว้เพื่อการบำรุงเลี้ยงดูหรือฝึกสอน เรียกเอาค่าการงานที่ทำให้ รวมทั้งเงินที่ได้ออกทดรองไป (๑๓) ผู้รับเลี้ยงหรือฝึกสอนสัตว์ เรียกเอาค่าการงานที่ทำให้ รวมทั้งเงินที่ได้ออกทดรองไป (๑๔) ครูหรืออาจารย์ เรียกเอาค่าสอน (๑๕) ผู้ประกอบวิชาชีพเวชกรรม ทันตกรรม การพยาบาล การผดุงครรภ์ ผู้ประกอบการบำบัดโรคสัตว์ หรือผู้ประกอบโรคศิลปะสาขาอื่น เรียกเอาค่าการงานที่ทำให้รวมทั้งเงินที่ได้ออกทดรองไป (๑๖) ทนายความหรือผู้ประกอบวิชาชีพทางกฎหมาย รวมทั้งพยานผู้เชี่ยวชาญเรียกเอาค่าการงานที่ทำให้ รวมทั้งเงินที่ได้ออกทดรองไป หรือคู่ความเรียกเอาคืนซึ่งเงินเช่นว่านั้นที่ตนได้จ่ายล่วงหน้าไป (๑๗) ผู้ประกอบวิชาชีพวิศวกรรม สถาปัตยกรรม ผู้สอบบัญชี หรือผู้ประกอบวิชาชีพอิสระอื่น เรียกเอาค่าการงานที่ทำให้ รวมทั้งเงินที่ได้ออกทดรองไป หรือผู้ว่าจ้างให้ประกอบการงานดังกล่าวเรียกเอาคืนซึ่งเงินเช่นว่านั้นที่ตนได้จ่ายล่วงหน้าไป"}},{"id":"TH-H004-A193.035","no":193.035,"noLabel":{"th":"มาตรา 193/35"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๙๓/๓๕ ภายใต้บังคับมาตรา ๑๙๓/๒๗ สิทธิเรียกร้องที่เกิดขึ้นจากการที่ลูกหนี้รับสภาพความรับผิดโดยมีหลักฐานเป็นหนังสือหรือโดยการให้ประกันตามมาตรา ๑๙๓/๒๘ วรรคสอง ให้มีกำหนดอายุความสองปีนับแต่วันที่ได้รับสภาพความรับผิดหรือให้ประกัน"}},{"id":"TH-H004-A194","no":194,"noLabel":{"th":"มาตรา 194"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๔ ด้วยอำนาจแห่งมูลหนี้ เจ้าหนี้ย่อมมีสิทธิจะเรียกให้ลูกหนี้ชำระหนี้ได้ อนึ่ง การชำระหนี้ด้วยงดเว้นการอันใดอันหนึ่งก็ย่อมมีได้"}},{"id":"TH-H004-A195","no":195,"noLabel":{"th":"มาตรา 195"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๕ เมื่อทรัพย์ซึ่งเป็นวัตถุแห่งหนี้นั้นได้ระบุไว้แต่เพียงเป็นประเภท และถ้าตามสภาพแห่งนิติกรรม หรือตามเจตนาของคู่กรณีไม่อาจจะกำหนดได้ว่าทรัพย์นั้นจะพึงเป็นชนิดอย่างไรไซร้ ท่านว่าลูกหนี้จะต้องส่งมอบทรัพย์ชนิดปานกลาง ถ้าลูกหนี้ได้กระทำการอันตนจะพึงต้องทำเพื่อส่งมอบทรัพย์สิ่งนั้นทุกประการแล้วก็ดี หรือถ้าลูกหนี้ได้เลือกกำหนดทรัพย์ที่จะส่งมอบแล้วด้วยความยินยอมของเจ้าหนี้ก็ดี ท่านว่าทรัพย์นั้นจึงเป็นวัตถุแห่งหนี้จำเดิมแต่เวลานั้นไป"}},{"id":"TH-H004-A196","no":196,"noLabel":{"th":"มาตรา 196"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๖ ถ้าหนี้เงินได้แสดงไว้เป็นเงินต่างประเทศ ท่านว่าจะส่งใช้เป็นเงินไทยก็ได้ การเปลี่ยนเงินนี้ ให้คิดตามอัตราแลกเปลี่ยนเงิน ณ สถานที่และในเวลาที่ใช้เงิน"}},{"id":"TH-H004-A197","no":197,"noLabel":{"th":"มาตรา 197"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๗ ถ้าหนี้เงินจะพึงส่งใช้ด้วยเงินตราชนิดหนึ่งชนิดใดโดยเฉพาะ อันเป็นชนิดที่ยกเลิกไม่ใช้กันแล้วในเวลาที่จะต้องส่งเงินใช้หนี้นั้นไซร้ การส่งใช้เงินท่านให้ถือเสมือนหนึ่งว่ามิได้ระบุไว้ให้ใช้เป็นเงินตราชนิดนั้น"}},{"id":"TH-H004-A198","no":198,"noLabel":{"th":"มาตรา 198"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๘ ถ้าการอันมีกำหนดพึงกระทำเพื่อชำระหนี้นั้นมีหลายอย่าง แต่จะต้องกระทำเพียงการใดการหนึ่งแต่อย่างเดียวไซร้ ท่านว่าสิทธิที่จะเลือกทำการอย่างใดนั้นตกอยู่แก่ฝ่ายลูกหนี้ เว้นแต่จะได้ตกลงกันกำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A199","no":199,"noLabel":{"th":"มาตรา 199"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๙๙ การเลือกนั้นท่านให้ทำด้วยแสดงเจตนาแก่คู่กรณีอีกฝ่ายหนึ่ง การชำระหนี้ได้เลือกทำเป็นอย่างใดแล้ว ท่านให้ถือว่าอย่างนั้นอย่างเดียวเป็นการชำระหนี้อันกำหนดให้กระทำแต่ต้นมา"}},{"id":"TH-H004-A200","no":200,"noLabel":{"th":"มาตรา 200"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๒๐๐ ถ้าจะต้องเลือกภายในระยะเวลาอันมีกำหนด และฝ่ายที่มีสิทธิจะเลือก มิได้เลือกภายในระยะเวลานั้นไซร้ ท่านว่าสิทธิที่จะเลือกนั้นย่อมตกไปอยู่แก่อีกฝ่ายหนึ่ง ถ้ามิได้กำหนดระยะเวลาให้เลือกไซร้ เมื่อหนี้ถึงกำหนดชำระ ฝ่ายที่ไม่มีสิทธิจะเลือกอาจกำหนดเวลาพอสมควรแก่เหตุ แล้วบอกกล่าวให้ฝ่ายโน้นใช้สิทธิเลือกภายในเวลาอันนั้น"}},{"id":"TH-H004-A201","no":201,"noLabel":{"th":"มาตรา 201"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๒๐๑ ถ้าบุคคลภายนอกจะพึงเป็นผู้เลือก ท่านให้กระทำด้วยแสดงเจตนาแก่ลูกหนี้ และลูกหนี้จะต้องแจ้งความนั้นแก่เจ้าหนี้ ถ้าบุคคลภายนอกนั้นไม่อาจจะเลือกได้ก็ดี หรือไม่เต็มใจจะเลือกก็ดี ท่านว่าสิทธิที่จะเลือกตกไปอยู่แก่ฝ่ายลูกหนี้"}},{"id":"TH-H004-A202","no":202,"noLabel":{"th":"มาตรา 202"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๒๐๒ ถ้าการอันจะพึงต้องทำเพื่อชำระหนี้นั้นมีหลายอย่าง และอย่างใดอย่างหนึ่งตกเป็นอันพ้นวิสัยจะทำได้มาแต่ต้นก็ดี หรือกลายเป็นพ้นวิสัยในภายหลังก็ดี ท่านให้จำกัดหนี้นั้นไว้เพียงการชำระหนี้อย่างอื่นที่ไม่พ้นวิสัย อนึ่ง การจำกัดอันนี้ย่อมไม่เกิดมีขึ้น หากว่าการชำระหนี้กลายเป็นพ้นวิสัยเพราะพฤติการณ์อันใดอันหนึ่งซึ่งฝ่ายที่ไม่มีสิทธิจะเลือกนั้นต้องรับผิดชอบ"}},{"id":"TH-H004-A203","no":203,"noLabel":{"th":"มาตรา 203"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๓ ถ้าเวลาอันจะพึงชำระหนี้นั้นมิได้กำหนดลงไว้ หรือจะอนุมานจากพฤติการณ์ทั้งปวงก็ไม่ได้ไซร้ ท่านว่าเจ้าหนี้ย่อมจะเรียกให้ชำระหนี้ได้โดยพลัน และฝ่ายลูกหนี้ก็ย่อมจะชำระหนี้ของตนได้โดยพลันดุจกัน ถ้าได้กำหนดเวลาไว้ แต่หากกรณีเป็นที่สงสัย ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าหนี้จะเรียกให้ชำระหนี้ก่อนถึงเวลานั้นหาได้ไม่ แต่ฝ่ายลูกหนี้จะชำระหนี้ก่อนกำหนดนั้นก็ได้"}},{"id":"TH-H004-A204","no":204,"noLabel":{"th":"มาตรา 204"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๔ ถ้าหนี้ถึงกำหนดชำระแล้ว และภายหลังแต่นั้นเจ้าหนี้ได้ให้คำเตือนลูกหนี้แล้ว ลูกหนี้ยังไม่ชำระหนี้ไซร้ ลูกหนี้ได้ชื่อว่าผิดนัดเพราะเขาเตือนแล้ว ถ้าได้กำหนดเวลาชำระหนี้ไว้ตามวันแห่งปฏิทิน และลูกหนี้มิได้ชำระหนี้ตามกำหนดไซร้ ท่านว่าลูกหนี้ตกเป็นผู้ผิดนัดโดยมิพักต้องเตือนเลย วิธีเดียวกันนี้ท่านให้ใช้บังคับแก่กรณีที่ต้องบอกกล่าวล่วงหน้าก่อนการชำระหนี้ ซึ่งได้กำหนดเวลาลงไว้อาจคำนวณนับได้โดยปฏิทินนับแต่วันที่ได้บอกกล่าว"}},{"id":"TH-H004-A205","no":205,"noLabel":{"th":"มาตรา 205"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๕ ตราบใดการชำระหนี้นั้นยังมิได้กระทำลงเพราะพฤติการณ์อันใดอันหนึ่งซึ่งลูกหนี้ไม่ต้องรับผิดชอบ ตราบนั้นลูกหนี้ยังหาได้ชื่อว่าผิดนัดไม่"}},{"id":"TH-H004-A206","no":206,"noLabel":{"th":"มาตรา 206"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๖ ในกรณีหนี้อันเกิดแต่มูลละเมิด ลูกหนี้ได้ชื่อว่าผิดนัดมาแต่เวลาที่ทำละเมิด"}},{"id":"TH-H004-A207","no":207,"noLabel":{"th":"มาตรา 207"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๗ ถ้าลูกหนี้ขอปฏิบัติการชำระหนี้ และเจ้าหนี้ไม่รับชำระหนี้นั้นโดยปราศจากมูลเหตุอันจะอ้างกฎหมายได้ไซร้ ท่านว่าเจ้าหนี้ตกเป็นผู้ผิดนัด"}},{"id":"TH-H004-A208","no":208,"noLabel":{"th":"มาตรา 208"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๘ การชำระหนี้จะให้สำเร็จผลเป็นอย่างใด ลูกหนี้จะต้องขอปฏิบัติการชำระหนี้ต่อเจ้าหนี้เป็นอย่างนั้นโดยตรง แต่ถ้าเจ้าหนี้ได้แสดงแก่ลูกหนี้ว่า จะไม่รับชำระหนี้ก็ดี หรือเพื่อที่จะชำระหนี้จำเป็นที่เจ้าหนี้จะต้องกระทำการอย่างใดอย่างหนึ่งก่อนก็ดี ลูกหนี้จะบอกกล่าวแก่เจ้าหนี้ว่า ได้เตรียมการที่จะชำระหนี้ไว้พร้อมเสร็จแล้ว ให้เจ้าหนี้รับชำระหนี้นั้นเท่านี้ก็นับว่าเป็นการเพียงพอแล้ว ในกรณีเช่นนี้ท่านว่าคำบอกกล่าวของลูกหนี้นั้นก็เสมอกับคำขอปฏิบัติการชำระหนี้"}},{"id":"TH-H004-A209","no":209,"noLabel":{"th":"มาตรา 209"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๐๙ ถ้าได้กำหนดเวลาไว้เป็นแน่นอนเพื่อให้เจ้าหนี้กระทำการอันใด ท่านว่าที่จะขอปฏิบัติการชำระหนี้นั้น จะต้องทำก็แต่เมื่อเจ้าหนี้ทำการอันนั้นภายในเวลากำหนด"}},{"id":"TH-H004-A210","no":210,"noLabel":{"th":"มาตรา 210"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๐ ถ้าลูกหนี้จำต้องชำระหนี้ส่วนของตนต่อเมื่อเจ้าหนี้ชำระหนี้ตอบแทนด้วยไซร้ แม้ถึงว่าเจ้าหนี้จะได้เตรียมพร้อมที่จะรับชำระหนี้ตามที่ลูกหนี้ขอปฏิบัตินั้นแล้วก็ดี หากไม่เสนอที่จะทำการชำระหนี้ตอบแทนตามที่จะพึงต้องทำ เจ้าหนี้ก็เป็นอันได้ชื่อว่าผิดนัด"}},{"id":"TH-H004-A211","no":211,"noLabel":{"th":"มาตรา 211"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๑ ในเวลาที่ลูกหนี้ขอปฏิบัติการชำระหนี้นั้นก็ดี หรือในเวลาที่กำหนดไว้ให้เจ้าหนี้ทำการอย่างใดอย่างหนึ่ง โดยกรณีที่บัญญัติไว้ในมาตรา ๒๐๙ นั้นก็ดี ถ้าลูกหนี้มิได้อยู่ในฐานะที่จะสามารถชำระหนี้ได้ไซร้ ท่านว่าเจ้าหนี้ยังหาผิดนัดไม่"}},{"id":"TH-H004-A212","no":212,"noLabel":{"th":"มาตรา 212"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๒ ถ้ามิได้กำหนดเวลาชำระหนี้ไว้ก็ดี หรือถ้าลูกหนี้มีสิทธิที่จะชำระหนี้ได้ก่อนเวลากำหนดก็ดี การที่เจ้าหนี้มีเหตุขัดข้องชั่วคราวไม่อาจรับชำระหนี้ที่เขาขอปฏิบัติแก่ตนได้นั้น หาทำให้เจ้าหนี้ตกเป็นผู้ผิดนัดไม่ เว้นแต่ลูกหนี้จะได้บอกกล่าวการชำระหนี้ไว้ล่วงหน้าโดยเวลาอันสมควร"}},{"id":"TH-H004-A213","no":213,"noLabel":{"th":"มาตรา 213"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๓ ถ้าลูกหนี้ละเลยเสียไม่ชำระหนี้ของตน เจ้าหนี้จะร้องขอต่อศาลให้สั่งบังคับชำระหนี้ก็ได้ เว้นแต่สภาพแห่งหนี้จะไม่เปิดช่องให้ทำเช่นนั้นได้ เมื่อสภาพแห่งหนี้ไม่เปิดช่องให้บังคับชำระหนี้ได้ ถ้าวัตถุแห่งหนี้เป็นอันให้กระทำการอันหนึ่งอันใด เจ้าหนี้จะร้องขอต่อศาลให้สั่งบังคับให้บุคคลภายนอกกระทำการอันนั้นโดยให้ลูกหนี้เสียค่าใช้จ่ายให้ก็ได้ แต่ถ้าวัตถุแห่งหนี้เป็นอันให้กระทำนิติกรรมอย่างใดอย่างหนึ่งไซร้ ศาลจะสั่งให้ถือเอาตามคำพิพากษาแทนการแสดงเจตนาของลูกหนี้ก็ได้ ส่วนหนี้ซึ่งมีวัตถุเป็นอันจะให้งดเว้นการอันใด เจ้าหนี้จะเรียกร้องให้รื้อถอนการที่ได้กระทำลงแล้วนั้นโดยให้ลูกหนี้เสียค่าใช้จ่าย และให้จัดการอันควรเพื่อกาลภายหน้าด้วยก็ได้ อนึ่ง บทบัญญัติในวรรคทั้งหลายที่กล่าวมาก่อนนี้ หากระทบกระทั่งถึงสิทธิที่จะเรียกเอาค่าเสียหายไม่"}},{"id":"TH-H004-A214","no":214,"noLabel":{"th":"มาตรา 214"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๔ ภายใต้บังคับบทบัญญัติแห่งมาตรา ๗๓๓ เจ้าหนี้มีสิทธิที่จะให้ชำระหนี้ของตนจากทรัพย์สินของลูกหนี้จนสิ้นเชิง รวมทั้งเงินและทรัพย์สินอื่น ๆ ซึ่งบุคคลภายนอกค้างชำระแก่ลูกหนี้ด้วย"}},{"id":"TH-H004-A215","no":215,"noLabel":{"th":"มาตรา 215"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๕ เมื่อลูกหนี้ไม่ชำระหนี้ให้ต้องตามความประสงค์อันแท้จริงแห่งมูลหนี้ไซร้ เจ้าหนี้จะเรียกเอาค่าสินไหมทดแทนเพื่อความเสียหายอันเกิดแต่การนั้นก็ได้"}},{"id":"TH-H004-A216","no":216,"noLabel":{"th":"มาตรา 216"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๖ ถ้าโดยเหตุผิดนัด การชำระหนี้กลายเป็นอันไร้ประโยชน์แก่เจ้าหนี้ เจ้าหนี้จะบอกปัดไม่รับชำระหนี้ และจะเรียกเอาค่าสินไหมทดแทนเพื่อการไม่ชำระหนี้ก็ได้"}},{"id":"TH-H004-A217","no":217,"noLabel":{"th":"มาตรา 217"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๗ ลูกหนี้จะต้องรับผิดชอบในความเสียหายบรรดาที่เกิดแต่ความประมาทเลินเล่อในระหว่างเวลาที่ตนผิดนัด ทั้งจะต้องรับผิดชอบในการที่การชำระหนี้กลายเป็นพ้นวิสัยเพราะอุบัติเหตุอันเกิดขึ้นในระหว่างเวลาที่ผิดนัดนั้นด้วย เว้นแต่ความเสียหายนั้น ถึงแม้ว่าตนจะได้ชำระหนี้ทันเวลากำหนดก็คงจะต้องเกิดมีอยู่นั่นเอง"}},{"id":"TH-H004-A218","no":218,"noLabel":{"th":"มาตรา 218"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๘ ถ้าการชำระหนี้กลายเป็นพ้นวิสัยจะทำได้ เพราะพฤติการณ์อันใดอันหนึ่งซึ่งลูกหนี้ต้องรับผิดชอบไซร้ ท่านว่าลูกหนี้จะต้องใช้ค่าสินไหมทดแทนให้แก่เจ้าหนี้เพื่อค่าเสียหายอย่างใด ๆ อันเกิดแต่การไม่ชำระหนี้นั้น ในกรณีที่การชำระหนี้กลายเป็นพ้นวิสัยแต่เพียงบางส่วน ถ้าหากว่าส่วนที่ยังเป็นวิสัยจะทำได้นั้นจะเป็นอันไร้ประโยชน์แก่เจ้าหนี้แล้ว เจ้าหนี้จะไม่ยอมรับชำระหนี้ส่วนที่ยังเป็นวิสัยจะทำได้นั้นแล้ว และเรียกค่าสินไหมทดแทนเพื่อการไม่ชำระหนี้เสียทั้งหมดทีเดียวก็ได้"}},{"id":"TH-H004-A219","no":219,"noLabel":{"th":"มาตรา 219"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๑๙ ถ้าการชำระหนี้กลายเป็นพ้นวิสัยเพราะพฤติการณ์อันใดอันหนึ่งซึ่งเกิดขึ้นภายหลังที่ได้ก่อหนี้ และซึ่งลูกหนี้ไม่ต้องรับผิดชอบนั้นไซร้ ท่านว่าลูกหนี้เป็นอันหลุดพ้นจากการชำระหนี้นั้น ถ้าภายหลังที่ได้ก่อหนี้ขึ้นแล้วนั้น ลูกหนี้กลายเป็นคนไม่สามารถจะชำระหนี้ได้ไซร้ ท่านให้ถือเสมือนว่าเป็นพฤติการณ์ที่ทำให้การชำระหนี้ตกเป็นอันพ้นวิสัยฉะนั้น"}},{"id":"TH-H004-A220","no":220,"noLabel":{"th":"มาตรา 220"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๐ ลูกหนี้ต้องรับผิดชอบในความผิดของตัวแทนแห่งตนกับทั้งของบุคคลที่ตนใช้ในการชำระหนี้นั้นโดยขนาดเสมอกับว่าเป็นความผิดของตนเองฉะนั้น แต่บทบัญญัติแห่งมาตรา ๓๗๓ หาใช้บังคับแก่กรณีเช่นนี้ด้วยไม่"}},{"id":"TH-H004-A221","no":221,"noLabel":{"th":"มาตรา 221"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๑ หนี้เงินอันต้องเสียดอกเบี้ยนั้น ท่านว่าจะคิดดอกเบี้ยในระหว่างที่เจ้าหนี้ผิดนัดหาได้ไม่"}},{"id":"TH-H004-A222","no":222,"noLabel":{"th":"มาตรา 222"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๒ การเรียกเอาค่าเสียหายนั้น ได้แก่เรียกค่าสินไหมทดแทนเพื่อความเสียหายเช่นที่ตามปกติย่อมเกิดขึ้นแต่การไม่ชำระหนี้นั้น เจ้าหนี้จะเรียกค่าสินไหมทดแทนได้ แม้กระทั่งเพื่อความเสียหายอันเกิดแต่พฤติการณ์พิเศษ หากว่าคู่กรณีที่เกี่ยวข้องได้คาดเห็นหรือควรจะได้คาดเห็นพฤติการณ์เช่นนั้นล่วงหน้าก่อนแล้ว"}},{"id":"TH-H004-A223","no":223,"noLabel":{"th":"มาตรา 223"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๓ ถ้าฝ่ายผู้เสียหายได้มีส่วนทำความผิดอย่างใดอย่างหนึ่งก่อให้เกิดความเสียหายด้วยไซร้ ท่านว่าหนี้อันจะต้องใช้ค่าสินไหมทดแทนแก่ฝ่ายผู้เสียหายมากน้อยเพียงใดนั้น ต้องอาศัยพฤติการณ์เป็นประมาณ ข้อสำคัญก็คือว่าความเสียหายนั้นได้เกิดขึ้นเพราะฝ่ายไหนเป็นผู้ก่อยิ่งหย่อนกว่ากันเพียงไร วิธีเดียวกันนี้ท่านให้ใช้แม้ทั้งที่ความผิดของฝ่ายผู้ที่เสียหายจะมีแต่เพียงละเลยไม่เตือนลูกหนี้ให้รู้สึกถึงอันตรายแห่งการเสียหายอันเป็นอย่างร้ายแรงผิดปกติ ซึ่งลูกหนี้ไม่รู้หรือไม่อาจจะรู้ได้ หรือเพียงแต่ละเลยไม่บำบัดปัดป้อง หรือบรรเทาความเสียหายนั้นด้วย อนึ่ง บทบัญญัติแห่งมาตรา ๒๒๐ นั้นท่านให้นำมาใช้บังคับด้วยโดยอนุโลม"}},{"id":"TH-H004-A224","no":224,"noLabel":{"th":"มาตรา 224"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๔ หนี้เงินนั้น ให้คิดดอกเบี้ยในระหว่างเวลาผิดนัดในอัตราที่กำหนดตามมาตรา ๗ บวกด้วยอัตราเพิ่มร้อยละสองต่อปี ถ้าเจ้าหนี้อาจจะเรียกดอกเบี้ยได้สูงกว่านั้นโดยอาศัยเหตุอย่างอื่นอันชอบด้วยกฎหมาย ก็ให้คงส่งดอกเบี้ยต่อไปตามนั้น ห้ามมิให้คิดดอกเบี้ยซ้อนดอกเบี้ยในระหว่างผิดนัด การพิสูจน์ค่าเสียหายอย่างอื่นนอกจากนั้น ให้พิสูจน์ได้"}},{"id":"TH-H004-A224.001","no":224.001,"noLabel":{"th":"มาตรา 224/1"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๔/๑ ถ้าลูกหนี้มีหน้าที่ผ่อนชำระหนี้เงินเป็นงวด และลูกหนี้ผิดนัดไม่ชำระหนี้ในงวดใด เจ้าหนี้อาจเรียกดอกเบี้ยในระหว่างเวลาผิดนัดได้เฉพาะจากต้นเงินของงวดที่ลูกหนี้ผิดนัดนั้น ข้อตกลงใดขัดกับความในวรรคหนึ่ง ข้อตกลงนั้นเป็นโมฆะ"}},{"id":"TH-H004-A225","no":225,"noLabel":{"th":"มาตรา 225"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๒๒๕ ถ้าลูกหนี้จำต้องใช้ค่าสินไหมทดแทนเพื่อราคาวัตถุอันได้เสื่อมเสียไประหว่างผิดนัดก็ดี หรือวัตถุอันไม่อาจส่งมอบได้เพราะเหตุอย่างใดอย่างหนึ่งอันเกิดขึ้นระหว่างผิดนัดก็ดี ท่านว่าเจ้าหนี้จะเรียกดอกเบี้ยในจำนวนที่จะต้องใช้เป็นค่าสินไหมทดแทนคิดตั้งแต่เวลาอันเป็นฐานที่ตั้งแห่งการกะประมาณราคานั้นก็ได้ วิธีเดียวกันนี้ท่านให้ใช้ตลอดถึงการที่ลูกหนี้จำต้องใช้ค่าสินไหมทดแทนเพื่อการที่ราคาวัตถุตกต่ำ เพราะวัตถุนั้นเสื่อมเสียลงในระหว่างเวลาที่ผิดนัดนั้นด้วย"}},{"id":"TH-H004-A226","no":226,"noLabel":{"th":"มาตรา 226"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๒๖ บุคคลผู้รับช่วงสิทธิของเจ้าหนี้ ชอบที่จะใช้สิทธิทั้งหลายบรรดาที่เจ้าหนี้มีอยู่โดยมูลหนี้ รวมทั้งประกันแห่งหนี้นั้นได้ในนามของตนเอง ช่วงทรัพย์ ได้แก่เอาทรัพย์สินอันหนึ่งเข้าแทนที่ทรัพย์สินอีกอันหนึ่ง ในฐานะนิตินัยอย่างเดียวกันกับทรัพย์สินอันก่อน"}},{"id":"TH-H004-A227","no":227,"noLabel":{"th":"มาตรา 227"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๒๗ เมื่อเจ้าหนี้ได้รับค่าสินไหมทดแทนความเสียหายเต็มตามราคาทรัพย์หรือสิทธิซึ่งเป็นวัตถุแห่งหนี้นั้นแล้ว ท่านว่าลูกหนี้ย่อมเข้าสู่ฐานะเป็นผู้รับช่วงสิทธิของเจ้าหนี้อันเกี่ยวกับทรัพย์หรือสิทธินั้น ๆ ด้วยอำนาจกฎหมาย"}},{"id":"TH-H004-A228","no":228,"noLabel":{"th":"มาตรา 228"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๒๘ ถ้าพฤติการณ์ซึ่งทำให้การชำระหนี้เป็นอันพ้นวิสัยนั้น เป็นผลให้ลูกหนี้ได้มาซึ่งของแทนก็ดี หรือได้สิทธิเรียกร้องค่าสินไหมทดแทนเพื่อทรัพย์อันจะพึงได้แก่ตนนั้นก็ดี ท่านว่าเจ้าหนี้จะเรียกให้ส่งมอบของแทนที่ได้รับไว้ หรือจะเข้าเรียกเอาค่าสินไหมทดแทนเสียเองก็ได้ ถ้าเจ้าหนี้มีสิทธิเรียกร้องค่าสินไหมทดแทนเพราะการไม่ชำระหนี้ และถ้าใช้สิทธินั้นดังได้ระบุไว้ในวรรคต้นไซร้ ค่าสินไหมทดแทนอันจะพึงใช้แก่เจ้าหนี้นั้นย่อมลดจำนวนลงเพียงเสมอราคาแห่งของแทนซึ่งลูกหนี้ได้รับไว้ หรือเสมอจำนวนค่าสินไหมทดแทนที่ลูกหนี้จะเรียกร้องได้นั้น"}},{"id":"TH-H004-A229","no":229,"noLabel":{"th":"มาตรา 229"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๒๙ การรับช่วงสิทธิย่อมมีขึ้นด้วยอำนาจกฎหมายและย่อมสำเร็จเป็นประโยชน์แก่บุคคลดังจะกล่าวต่อไปนี้ คือ (๑) บุคคลซึ่งเป็นเจ้าหนี้อยู่เอง และมาใช้หนี้ให้แก่เจ้าหนี้อีกคนหนึ่งผู้มีสิทธิจะได้รับใช้หนี้ก่อนตน เพราะเขามีบุริมสิทธิ หรือมีสิทธิจำนำจำนอง (๒) บุคคลผู้ได้ไปซึ่งอสังหาริมทรัพย์ใด และเอาเงินราคาค่าซื้อใช้ให้แก่ผู้รับจำนองทรัพย์นั้นเสร็จไป (๓) บุคคลผู้มีความผูกพันร่วมกับผู้อื่น หรือเพื่อผู้อื่นในอันจะต้องใช้หนี้ มีส่วนได้เสียด้วยในการใช้หนี้นั้น และเข้าใช้หนี้นั้น"}},{"id":"TH-H004-A230","no":230,"noLabel":{"th":"มาตรา 230"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๓๐ ถ้าในการที่เจ้าหนี้นำบังคับยึดทรัพย์อันหนึ่งอันใดของลูกหนี้นั้น บุคคลผู้ใดจะต้องเสี่ยงภัยเสียสิทธิในทรัพย์อันนั้นเพราะการบังคับยึดทรัพย์ไซร้ ท่านว่าบุคคลผู้นั้นมีสิทธิจะเข้าใช้หนี้เสียแทนได้ อนึ่ง ผู้ครองทรัพย์อันหนึ่งอันใด ถ้าจะต้องเสี่ยงภัยเสียสิทธิครองทรัพย์นั้นไปเพราะการบังคับยึดทรัพย์ ก็ย่อมมีสิทธิจะทำได้เช่นเดียวกับที่ว่ามานั้น ถ้าบุคคลภายนอกผู้ใดมาใช้หนี้แทนจนเป็นที่พอใจของเจ้าหนี้แล้ว บุคคลผู้นั้นย่อมเข้ารับช่วงสิทธิเรียกร้องของเจ้าหนี้ แต่สิทธิเรียกร้องอันนี้จะบังคับให้เป็นที่เสื่อมเสียแก่เจ้าหนี้หาได้ไม่"}},{"id":"TH-H004-A231","no":231,"noLabel":{"th":"มาตรา 231"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๓๑ ถ้าทรัพย์สินที่จำนอง จำนำ หรืออยู่ในบังคับบุริมสิทธิประการอื่นนั้น เป็นทรัพย์อันได้เอาประกันภัยไว้ไซร้ ท่านว่าสิทธิจำนอง จำนำ หรือบุริมสิทธิอย่างอื่นนั้นย่อมครอบไปถึงสิทธิที่จะเรียกร้องเอาแก่ผู้รับประกันภัยด้วย ในกรณีที่เป็นอสังหาริมทรัพย์ ถ้าผู้รับประกันภัยได้รู้ หรือควรจะได้รู้ว่ามีจำนอง หรือบุริมสิทธิอย่างอื่นไซร้ ท่านยังมิให้ผู้รับประกันภัยใช้เงินให้แก่ผู้เอาประกันภัย จนกว่าจะได้บอกกล่าวเจตนาเช่นนั้นไปยังผู้รับจำนอง หรือเจ้าหนี้มีบุริมสิทธิคนอื่นแล้ว และมิได้รับคำคัดค้านการที่จะใช้เงินนั้นมาภายในเดือนหนึ่งนับแต่วันบอกกล่าว แต่สิทธิอย่างใด ๆ ที่ได้ไปจดทะเบียน ณ หอทะเบียนที่ดินนั้น ท่านให้ถือว่าเป็นอันรู้ถึงผู้รับประกันภัย วิธีเดียวกันนี้ท่านให้ใช้ตลอดถึงการจำนองสังหาริมทรัพย์ที่กฎหมายอนุญาตให้ทำได้นั้นด้วย ในกรณีที่เป็นสังหาริมทรัพย์ ผู้รับประกันภัยจะใช้เงินให้แก่ผู้เอาประกันภัยโดยตรงก็ได้ เว้นแต่ตนจะได้รู้หรือควรจะได้รู้ว่าทรัพย์นั้นตกอยู่ในบังคับจำนำ หรือบุริมสิทธิอย่างอื่น ผู้รับประกันภัยไม่ต้องรับผิดต่อเจ้าหนี้ ถ้าทรัพย์สินอันได้เอาประกันภัยไว้นั้นได้คืนมา หรือได้จัดของแทนให้ วิธีเดียวกันนี้ท่านให้อนุโลมใช้บังคับแก่กรณีบังคับซื้อกับทั้งกรณีที่ต้องใช้ค่าเสียหายอันควรจะได้แก่เจ้าของทรัพย์สิน เพราะเหตุทรัพย์สินทำลายหรือบุบสลายนั้นด้วย"}},{"id":"TH-H004-A232","no":232,"noLabel":{"th":"มาตรา 232"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๒๓๒ ถ้าตามความในมาตราก่อนนี้เป็นอันว่าจะเอาเงินจำนวนหนึ่งให้แทนทรัพย์สินที่ทำลายหรือบุบสลายไซร้ เงินจำนวนนี้ท่านยังมิให้ส่งมอบแก่ผู้รับจำนอง ผู้รับจำนำ หรือเจ้าหนี้มีบุริมสิทธิคนอื่น ก่อนที่หนี้ซึ่งได้เอาทรัพย์นี้เป็นประกันไว้นั้นจะถึงกำหนด และถ้าคู่กรณีไม่สามารถจะตกลงกับลูกหนี้ได้ไซร้ ท่านว่าต่างฝ่ายต่างมีสิทธิที่จะเรียกร้องให้นำเงินจำนวนนั้นไปวางไว้ ณ สำนักงานวางทรัพย์เพื่อประโยชน์อันร่วมกัน เว้นแต่ลูกหนี้จะหาประกันให้ไว้ตามสมควร"}},{"id":"TH-H004-A233","no":233,"noLabel":{"th":"มาตรา 233"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๒๓๓ ถ้าลูกหนี้ขัดขืนไม่ยอมใช้สิทธิเรียกร้องหรือเพิกเฉยเสียไม่ใช้สิทธิเรียกร้อง เป็นเหตุให้เจ้าหนี้ต้องเสียประโยชน์ไซร้ ท่านว่าเจ้าหนี้จะใช้สิทธิเรียกร้องนั้นในนามของตนเองแทนลูกหนี้เพื่อป้องกันสิทธิของตนในมูลหนี้นั้นก็ได้ เว้นแต่ในข้อที่เป็นการของลูกหนี้ส่วนตัวโดยแท้"}},{"id":"TH-H004-A234","no":234,"noLabel":{"th":"มาตรา 234"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๒๓๔ เจ้าหนี้ผู้ใช้สิทธิเรียกร้องของลูกหนี้นั้นจะต้องขอหมายเรียกลูกหนี้มาในคดีนั้นด้วย"}},{"id":"TH-H004-A235","no":235,"noLabel":{"th":"มาตรา 235"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๒๓๕ เจ้าหนี้จะใช้สิทธิเรียกร้องของลูกหนี้เรียกเงินเต็มจำนวนที่ยังค้างชำระแก่ลูกหนี้ โดยไม่ต้องคำนึงถึงจำนวนที่ค้างชำระแก่ตนก็ได้ ถ้าจำเลยยอมใช้เงินเพียงเท่าจำนวนที่ลูกหนี้เดิมค้างชำระแก่เจ้าหนี้นั้น คดีก็เป็นเสร็จกันไป แต่ถ้าลูกหนี้เดิมได้เข้าชื่อเป็นโจทก์ด้วย ลูกหนี้เดิมจะขอให้ศาลพิจารณาพิพากษาต่อไปในส่วนจำนวนเงินที่ยังเหลือติดค้างอยู่ก็ได้ แต่อย่างไรก็ดี ท่านมิให้เจ้าหนี้ได้รับมากไปกว่าจำนวนที่ค้างชำระแก่ตนนั้นเลย"}},{"id":"TH-H004-A236","no":236,"noLabel":{"th":"มาตรา 236"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๒๓๖ จำเลยมีข้อต่อสู้ลูกหนี้เดิมอยู่อย่างใด ๆ ท่านว่าจะยกขึ้นต่อสู้เจ้าหนี้ได้ทั้งนั้น เว้นแต่ข้อต่อสู้ซึ่งเกิดขึ้นเมื่อยื่นฟ้องแล้ว"}},{"id":"TH-H004-A237","no":237,"noLabel":{"th":"มาตรา 237"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๒๓๗ เจ้าหนี้ชอบที่จะร้องขอให้ศาลเพิกถอนเสียได้ซึ่งนิติกรรมใด ๆ อันลูกหนี้ได้กระทำลงทั้งรู้อยู่ว่าจะเป็นทางให้เจ้าหนี้เสียเปรียบ แต่ความข้อนี้ท่านมิให้ใช้บังคับ ถ้าปรากฏว่าในขณะที่ทำนิติกรรมนั้น บุคคลซึ่งเป็นผู้ได้ลาภงอกแต่การนั้นมิได้รู้เท่าถึงข้อความจริงอันเป็นทางให้เจ้าหนี้ต้องเสียเปรียบนั้นด้วย แต่หากกรณีเป็นการทำให้โดยเสน่หา ท่านว่าเพียงแต่ลูกหนี้เป็นผู้รู้ฝ่ายเดียวเท่านั้นก็พอแล้วที่จะขอเพิกถอนได้ บทบัญญัติดังกล่าวมาในวรรคก่อนนี้ ท่านมิให้ใช้บังคับแก่นิติกรรมใดอันมิได้มีวัตถุเป็นสิทธิในทรัพย์สิน"}},{"id":"TH-H004-A238","no":238,"noLabel":{"th":"มาตรา 238"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๒๓๘ การเพิกถอนดังกล่าวมาในบทมาตราก่อนนั้นไม่อาจกระทบกระทั่งถึงสิทธิของบุคคลภายนอกอันได้มาโดยสุจริตก่อนเริ่มฟ้องคดีขอเพิกถอน อนึ่ง ความที่กล่าวมาในวรรคก่อนนี้ ท่านมิให้ใช้บังคับ ถ้าสิทธินั้นได้มาโดยเสน่หา"}},{"id":"TH-H004-A239","no":239,"noLabel":{"th":"มาตรา 239"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๒๓๙ การเพิกถอนนั้นย่อมได้เป็นประโยชน์แก่เจ้าหนี้หมดทุกคน"}},{"id":"TH-H004-A240","no":240,"noLabel":{"th":"มาตรา 240"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๒๔๐ การเรียกร้องขอเพิกถอนนั้น ท่านห้ามมิให้ฟ้องร้องเมื่อพ้นปีหนึ่งนับแต่เวลาที่เจ้าหนี้ได้รู้ต้นเหตุอันเป็นมูลให้เพิกถอน หรือพ้นสิบปีนับแต่ได้ทำนิติกรรมนั้น"}},{"id":"TH-H004-A241","no":241,"noLabel":{"th":"มาตรา 241"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๑ ผู้ใดเป็นผู้ครองทรัพย์สินของผู้อื่น และมีหนี้อันเป็นคุณประโยชน์แก่ตนเกี่ยวด้วยทรัพย์สินซึ่งครองนั้นไซร้ ท่านว่าผู้นั้นจะยึดหน่วงทรัพย์สินนั้นไว้จนกว่าจะได้ชำระหนี้ก็ได้ แต่ความที่กล่าวนี้ท่านมิให้ใช้บังคับ เมื่อหนี้นั้นยังไม่ถึงกำหนด อนึ่ง บทบัญญัติในวรรคก่อนนี้ ท่านมิให้ใช้บังคับ ถ้าการที่เข้าครอบครองนั้นเริ่มมาแต่ทำการอันใดอันหนึ่งซึ่งไม่ชอบด้วยกฎหมาย"}},{"id":"TH-H004-A242","no":242,"noLabel":{"th":"มาตรา 242"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๒ สิทธิยึดหน่วงอันใด ถ้าไม่สมกับลักษณะที่เจ้าหนี้รับภาระในมูลหนี้ก็ดี ไม่สมกับคำสั่งอันลูกหนี้ได้ให้ไว้ก่อนหรือให้ในเวลาที่ส่งมอบทรัพย์สินนั้นก็ดี หรือเป็นการขัดกับความสงบเรียบร้อยของประชาชนก็ดี สิทธิยึดหน่วงเช่นนั้นท่านให้ถือว่าหามีไม่เลย"}},{"id":"TH-H004-A243","no":243,"noLabel":{"th":"มาตรา 243"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๓ ในกรณีที่ลูกหนี้เป็นคนสินล้นพ้นตัวไม่สามารถใช้หนี้ เจ้าหนี้มีสิทธิจะยึดหน่วงทรัพย์สินไว้ได้ แม้ทั้งที่ยังไม่ถึงกำหนดเรียกร้อง ถ้าการที่ลูกหนี้ไม่สามารถใช้หนี้นั้นได้เกิดเป็นขึ้นหรือรู้ถึงเจ้าหนี้ต่อภายหลังเวลาที่ได้ส่งมอบทรัพย์สินไซร้ ถึงแม้ว่าจะไม่สมกับลักษณะที่เจ้าหนี้รับภาระในมูลหนี้ไว้เดิม หรือไม่สมกับคำสั่งอันลูกหนี้ได้ให้ไว้ก็ดี เจ้าหนี้ก็อาจจะใช้สิทธิยึดหน่วงได้"}},{"id":"TH-H004-A244","no":244,"noLabel":{"th":"มาตรา 244"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๔ ผู้ทรงสิทธิยึดหน่วงจะใช้สิทธิของตนแก่ทรัพย์สินทั้งหมดที่ยึดหน่วงไว้นั้นจนกว่าจะชำระหนี้สิ้นเชิงก็ได้"}},{"id":"TH-H004-A245","no":245,"noLabel":{"th":"มาตรา 245"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๕ ผู้ทรงสิทธิยึดหน่วงจะเก็บดอกผลแห่งทรัพย์สินที่ยึดหน่วงไว้ และจัดสรรเอาไว้เพื่อการชำระหนี้แก่ตนก่อนเจ้าหนี้คนอื่นก็ได้ ดอกผลเช่นว่านี้จะต้องจัดสรรเอาชำระดอกเบี้ยแห่งหนี้นั้นก่อน ถ้ายังมีเหลือจึงให้จัดสรรใช้ต้นเงิน"}},{"id":"TH-H004-A246","no":246,"noLabel":{"th":"มาตรา 246"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๖ ผู้ทรงสิทธิยึดหน่วงจำต้องจัดการดูแลรักษาทรัพย์สินที่ยึดหน่วงไว้นั้นตามสมควร เช่นจะพึงคาดหมายได้จากบุคคลในฐานะเช่นนั้น อนึ่ง ทรัพย์สินซึ่งยึดหน่วงไว้นั้น ถ้ามิได้รับความยินยอมของลูกหนี้ ท่านว่าผู้ทรงสิทธิยึดหน่วงหาอาจจะใช้สอยหรือให้เช่า หรือเอาไปทำเป็นหลักประกันได้ไม่ แต่ความที่กล่าวนี้ท่านมิให้ใช้บังคับไปถึงการใช้สอยเช่นที่จำเป็นเพื่อจะรักษาทรัพย์สินนั้นเอง ถ้าผู้ทรงสิทธิยึดหน่วงกระทำการฝ่าฝืนบทบัญญัติใดที่กล่าวมานี้ ท่านว่าลูกหนี้จะเรียกร้องให้ระงับสิทธินั้นเสียก็ได้"}},{"id":"TH-H004-A247","no":247,"noLabel":{"th":"มาตรา 247"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๗ ถ้าผู้ทรงสิทธิยึดหน่วงต้องเสียค่าใช้จ่ายไปตามที่จำเป็นเกี่ยวด้วยทรัพย์สินอันตนยึดหน่วงไว้นั้นเพียงใด จะเรียกให้เจ้าทรัพย์ชดใช้ให้ก็ได้"}},{"id":"TH-H004-A248","no":248,"noLabel":{"th":"มาตรา 248"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๘ ภายในบังคับแห่งบทบัญญัติมาตรา ๑๙๓/๒๗ การใช้สิทธิยึดหน่วงหาทำให้อายุความแห่งหนี้สะดุดหยุดลงไม่"}},{"id":"TH-H004-A249","no":249,"noLabel":{"th":"มาตรา 249"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๔๙ ลูกหนี้จะเรียกร้องให้ระงับสิทธิยึดหน่วงด้วยหาประกันให้ไว้ตามสมควรก็ได้"}},{"id":"TH-H004-A250","no":250,"noLabel":{"th":"มาตรา 250"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๒๕๐ การครองทรัพย์สินสูญสิ้นไป สิทธิยึดหน่วงก็เป็นอันระงับสิ้นไปด้วย แต่ความที่กล่าวนี้ท่านมิให้ใช้บังคับแก่กรณีที่ทรัพย์สินอันยึดหน่วงไว้นั้นได้ให้เช่าไปหรือจำนำไว้ด้วยความยินยอมของลูกหนี้"}},{"id":"TH-H004-A251","no":251,"noLabel":{"th":"มาตรา 251"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๑ ผู้ทรงบุริมสิทธิย่อมทรงไว้ซึ่งสิทธิเหนือทรัพย์สินของลูกหนี้ในการที่จะได้รับชำระหนี้อันค้างชำระแก่ตนจากทรัพย์สินนั้นก่อนเจ้าหนี้อื่น ๆ โดยนัยดังบัญญัติไว้ในประมวลกฎหมายนี้ หรือบทกฎหมายอื่น"}},{"id":"TH-H004-A252","no":252,"noLabel":{"th":"มาตรา 252"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๒ บทบัญญัติแห่งมาตรา ๒๔๔ นั้นท่านให้ใช้บังคับตลอดถึงบุริมสิทธิด้วยตามแต่กรณี"}},{"id":"TH-H004-A253","no":253,"noLabel":{"th":"มาตรา 253"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๓ ถ้าหนี้มีอยู่เป็นคุณแก่บุคคลผู้ใดในมูลอย่างหนึ่งอย่างใดดังจะกล่าวต่อไปนี้ บุคคลผู้นั้นย่อมมีบุริมสิทธิเหนือทรัพย์สินทั้งหมดของลูกหนี้ คือ (๑) ค่าใช้จ่ายเพื่อประโยชน์อันร่วมกัน (๒) ค่าปลงศพ (๓) ค่าภาษีอากร และเงินที่ลูกจ้างมีสิทธิได้รับเพื่อการงานที่ได้ทำให้แก่ลูกหนี้ซึ่งเป็นนายจ้าง (๔) ค่าเครื่องอุปโภคบริโภคอันจำเป็นประจำวัน"}},{"id":"TH-H004-A254","no":254,"noLabel":{"th":"มาตรา 254"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๔ บุริมสิทธิในมูลค่าใช้จ่ายเพื่อประโยชน์อันร่วมกันนั้น ใช้สำหรับเอาค่าใช้จ่ายอันได้เสียไปเพื่อประโยชน์ของเจ้าหนี้หมดทุกคนร่วมกัน เกี่ยวด้วยการรักษา การชำระบัญชี หรือการเฉลี่ยทรัพย์สินของลูกหนี้ ถ้าค่าใช้จ่ายนั้นมิได้เสียไปเพื่อประโยชน์ของเจ้าหนี้หมดทุกคนไซร้ บุริมสิทธิย่อมจะใช้ได้แต่เฉพาะต่อเจ้าหนี้ผู้ที่ได้รับประโยชน์จากการนั้น"}},{"id":"TH-H004-A255","no":255,"noLabel":{"th":"มาตรา 255"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๕ บุริมสิทธิในมูลค่าปลงศพนั้น ใช้สำหรับเอาค่าใช้จ่ายในการปลงศพตามควรแก่ฐานานุรูปของลูกหนี้"}},{"id":"TH-H004-A256","no":256,"noLabel":{"th":"มาตรา 256"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๖ บุริมสิทธิในมูลค่าภาษีอากรนั้น ใช้สำหรับเอาบรรดาค่าภาษีอากรในที่ดิน ทรัพย์สิน หรือค่าภาษีอากรอย่างอื่นที่ลูกหนี้ยังค้างชำระอยู่ในปีปัจจุบันและก่อนนั้นขึ้นไปอีกปีหนึ่ง"}},{"id":"TH-H004-A257","no":257,"noLabel":{"th":"มาตรา 257"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๗ บุริมสิทธิในเงินที่ลูกจ้างมีสิทธิได้รับเพื่อการงานที่ได้ทำให้แก่ลูกหนี้ซึ่งเป็นนายจ้างนั้น ให้ใช้สำหรับค่าจ้าง ค่าล่วงเวลา ค่าทำงานในวันหยุด ค่าล่วงเวลาในวันหยุด ค่าชดเชย ค่าชดเชยพิเศษ และเงินอื่นใดที่ลูกจ้างมีสิทธิได้รับเพื่อการงานที่ได้ทำให้ นับถอยหลังขึ้นไปสี่เดือนแต่รวมกันแล้วต้องไม่เกินหนึ่งแสนบาทต่อลูกจ้างคนหนึ่ง"}},{"id":"TH-H004-A258","no":258,"noLabel":{"th":"มาตรา 258"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๘ บุริมสิทธิในมูลค่าเครื่องอุปโภคบริโภคอันจำเป็นประจำวันนั้น ใช้สำหรับเอาค่าเครื่องอุปโภคบริโภค ซึ่งยังค้างชำระอยู่นับถอยหลังขึ้นไปหกเดือน เช่น ค่าอาหาร เครื่องดื่ม โคมไฟ ฟืน ถ่าน อันจำเป็นเพื่อการทรงชีพของลูกหนี้ และบุคคลในสกุลซึ่งอยู่กับลูกหนี้และซึ่งลูกหนี้จำต้องอุปการะ กับทั้งคนใช้ของลูกหนี้ด้วย"}},{"id":"TH-H004-A259","no":259,"noLabel":{"th":"มาตรา 259"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๕๙ ถ้าหนี้มีอยู่เป็นคุณแก่บุคคลผู้ใดในมูลอย่างหนึ่งอย่างใดดังจะกล่าวต่อไปนี้ บุคคลผู้นั้นย่อมมีบุริมสิทธิเหนือสังหาริมทรัพย์เฉพาะอย่างของลูกหนี้ คือ (๑) เช่าอสังหาริมทรัพย์ (๒) พักอาศัยในโรงแรม (๓) รับขนคนโดยสาร หรือของ (๔) รักษาสังหาริมทรัพย์ (๕) ซื้อขายสังหาริมทรัพย์ (๖) ค่าเมล็ดพันธุ์ ไม้พันธุ์ หรือปุ๋ย (๗) ค่าแรงงานกสิกรรม หรืออุตสาหกรรม"}},{"id":"TH-H004-A260","no":260,"noLabel":{"th":"มาตรา 260"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๐ บุริมสิทธิในมูลเช่าอสังหาริมทรัพย์นั้น ใช้สำหรับเอาค่าเช่าอสังหาริมทรัพย์และหนี้อย่างอื่นของผู้เช่าอันเกิดจากความเกี่ยวพันในเรื่องเช่า และมีอยู่เหนือสังหาริมทรัพย์ของผู้เช่าซึ่งอยู่ในหรือบนอสังหาริมทรัพย์นั้น"}},{"id":"TH-H004-A261","no":261,"noLabel":{"th":"มาตรา 261"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๑ บุริมสิทธิของผู้ให้เช่าที่ดินนั้นมีอยู่เหนือสังหาริมทรัพย์ทั้งหลายอันผู้เช่าได้นำเข้ามาไว้บนที่ดินที่ให้เช่า หรือนำเข้ามาไว้ในเรือนโรงอันใช้ประกอบกับที่ดินนั้น และมีอยู่เหนือสังหาริมทรัพย์เช่นสำหรับที่ใช้ในที่ดินนั้น กับทั้งเหนือดอกผลอันเกิดจากที่ดินซึ่งอยู่ในครอบครองของผู้เช่านั้นด้วย บุริมสิทธิของผู้ให้เช่าเรือนโรงย่อมมีอยู่เหนือสังหาริมทรัพย์ ซึ่งผู้เช่านำเข้ามาไว้ในเรือนโรงนั้นด้วย"}},{"id":"TH-H004-A262","no":262,"noLabel":{"th":"มาตรา 262"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๒ ถ้าการเช่าอสังหาริมทรัพย์ได้โอนไปก็ดี หรือได้ให้เช่าช่วงก็ดี บุริมสิทธิของผู้ให้เช่าเดิมย่อมครอบไปถึงสังหาริมทรัพย์ซึ่งผู้รับโอน หรือผู้เช่าช่วงได้นำเข้ามาไว้ในทรัพย์สินนั้นด้วย ความที่กล่าวนี้ท่านให้ใช้ได้ตลอดถึงเงินอันผู้โอน หรือผู้ให้เช่าช่วงจะพึงได้รับจากผู้รับโอนหรือผู้เช่าช่วงนั้นด้วย"}},{"id":"TH-H004-A263","no":263,"noLabel":{"th":"มาตรา 263"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๓ ในกรณีที่ผู้เช่าต้องชำระบัญชีเฉลี่ยทรัพย์สินทั่วไปนั้น บุริมสิทธิของผู้ให้เช่าย่อมมีอยู่แต่เฉพาะสำหรับเอาใช้ค่าเช่าและหนี้อย่างอื่นเท่าที่มีในระยะกำหนดส่งค่าเช่าเพียงสามระยะ คือปัจจุบันระยะหนึ่ง ก่อนนั้นขึ้นไประยะหนึ่ง และต่อไปภายหน้าอีกระยะหนึ่งเท่านั้น และใช้สำหรับเอาค่าเสียหายซึ่งเกิดขึ้นในระยะกำหนดส่งค่าเช่าปัจจุบันและก่อนนั้นขึ้นไปอีกระยะหนึ่งด้วย"}},{"id":"TH-H004-A264","no":264,"noLabel":{"th":"มาตรา 264"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๔ ในการเรียกร้องของผู้ให้เช่า ถ้าผู้ให้เช่าได้รับเงินประกันไว้ ผู้ให้เช่าย่อมมีบุริมสิทธิแต่เพียงในส่วนที่ไม่มีเงินประกัน"}},{"id":"TH-H004-A265","no":265,"noLabel":{"th":"มาตรา 265"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๕ บุริมสิทธิในมูลพักอาศัยในโรงแรมนั้น ใช้สำหรับเอาเงินบรรดาที่ค้างชำระแก่เจ้าสำนักเพื่อการพักอาศัยและการอื่น ๆ อันได้จัดให้สำเร็จความปรารถนาแก่คนเดินทาง หรือแขกอาศัย รวมทั้งการชดใช้เงินทั้งหลายที่ได้ออกแทนไปและมีอยู่เหนือเครื่องเดินทาง หรือทรัพย์สินอย่างอื่นของคนเดินทาง หรือแขกอาศัยอันเอาไว้ในโรงแรม โฮเต็ล หรือสถานที่เช่นนั้น"}},{"id":"TH-H004-A266","no":266,"noLabel":{"th":"มาตรา 266"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๖ ผู้ให้เช่าอสังหาริมทรัพย์ หรือเจ้าสำนักโรงแรม โฮเต็ล หรือสถานที่เช่นนั้น จะใช้บุริมสิทธิของตนบังคับทำนองเดียวกับผู้รับจำนำก็ได้ บทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้ว่าด้วยการบังคับจำนำนั้น ท่านให้นำมาใช้บังคับด้วยโดยอนุโลม"}},{"id":"TH-H004-A267","no":267,"noLabel":{"th":"มาตรา 267"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๗ บุริมสิทธิในมูลรับขนนั้น ใช้สำหรับเอาค่าระวางพาหนะในการรับขนคนโดยสารหรือของ กับทั้งค่าใช้จ่ายอันเป็นอุปกรณ์ และเป็นบุริมสิทธิมีอยู่เหนือของและเครื่องเดินทางทั้งหมดอันอยู่ในมือของผู้ขนส่ง"}},{"id":"TH-H004-A268","no":268,"noLabel":{"th":"มาตรา 268"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๘ ในกรณีดังได้ปรารภไว้ในความแปดมาตราก่อนนี้นั้น ผู้ให้เช่าอสังหาริมทรัพย์ก็ดี เจ้าสำนักโรงแรมก็ดี หรือผู้ขนส่งก็ดี จะใช้บุริมสิทธิของตนเหนือสังหาริมทรัพย์อันเป็นของบุคคลภายนอกก็ได้ เว้นแต่ตนจะได้รู้ในเวลาอันควรรู้ได้ว่าทรัพย์สินเหล่านั้นเป็นของบุคคลภายนอก ถ้าอสังหาริมทรัพย์นั้นถูกลักหรือสูญหาย ท่านให้บังคับตามบทกฎหมายว่าด้วยการแสวงคืนครองทรัพย์"}},{"id":"TH-H004-A269","no":269,"noLabel":{"th":"มาตรา 269"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๖๙ บุริมสิทธิในมูลรักษาสังหาริมทรัพย์นั้น ใช้สำหรับเอาค่าใช้จ่ายเพื่อรักษาสังหาริมทรัพย์ และมีอยู่เหนือสังหาริมทรัพย์อันนั้น อนึ่ง บุริมสิทธินี้ยังใช้สำหรับเอาค่าใช้จ่ายที่จำเป็นอันได้เสียไปเพื่อที่จะสงวนสิทธิ หรือรับสภาพสิทธิ หรือบังคับสิทธิ อันเกี่ยวด้วยสังหาริมทรัพย์นั้นอีกด้วย"}},{"id":"TH-H004-A270","no":270,"noLabel":{"th":"มาตรา 270"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๐ บุริมสิทธิในมูลซื้อขายสังหาริมทรัพย์นั้น ใช้สำหรับเอาราคาซื้อขายและดอกเบี้ยในราคานั้น และมีอยู่เหนือสังหาริมทรัพย์อันนั้น"}},{"id":"TH-H004-A271","no":271,"noLabel":{"th":"มาตรา 271"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๑ บุริมสิทธิในมูลค่าเมล็ดพันธุ์ ไม้พันธุ์ หรือปุ๋ยนั้น ใช้สำหรับเอาราคาค่าเมล็ดพันธุ์ ไม้พันธุ์ หรือปุ๋ย และดอกเบี้ยในราคานั้น และมีอยู่เหนือดอกผลอันเกิดงอกในที่ดินเพราะใช้สิ่งเหล่านั้นภายในปีหนึ่งนับแต่เวลาที่ใช้"}},{"id":"TH-H004-A272","no":272,"noLabel":{"th":"มาตรา 272"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๒ บุริมสิทธิในมูลค่าแรงงานเพื่อกสิกรรมและอุตสาหกรรมนั้น ในส่วนบุคคลที่ได้ทำการงานกสิกรรม ใช้สำหรับเอาค่าจ้างนับถอยหลังขึ้นไปปีหนึ่ง และในส่วนบุคคลที่ได้ทำการงานอุตสาหกรรม ใช้สำหรับเอาค่าจ้างนับถอยหลังขึ้นไปสามเดือน และเป็นบุริมสิทธิมีอยู่เหนือดอกผลหรือสิ่งของที่ประดิษฐ์ขึ้นอันเกิดแต่แรงงานของบุคคลนั้น ๆ"}},{"id":"TH-H004-A273","no":273,"noLabel":{"th":"มาตรา 273"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๓ ถ้าหนี้มีอยู่เป็นคุณแก่บุคคลผู้ใดในมูลอย่างหนึ่งอย่างใดดังจะกล่าวต่อไปนี้ บุคคลผู้นั้นย่อมมีบุริมสิทธิเหนืออสังหาริมทรัพย์เฉพาะอย่างของลูกหนี้ คือ (๑) รักษาอสังหาริมทรัพย์ (๒) จ้างทำของเป็นการงานทำขึ้นบนอสังหาริมทรัพย์ (๓) ซื้อขายอสังหาริมทรัพย์"}},{"id":"TH-H004-A274","no":274,"noLabel":{"th":"มาตรา 274"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๔ บุริมสิทธิในมูลรักษาอสังหาริมทรัพย์นั้น ใช้สำหรับเอาค่าใช้จ่ายเพื่อรักษาอสังหาริมทรัพย์ และมีอยู่เหนืออสังหาริมทรัพย์อันนั้น อนึ่ง บทบัญญัติแห่งมาตรา ๒๖๙ วรรคสองนั้น ท่านให้นำมาใช้บังคับแก่กรณีที่กล่าวมาในวรรคก่อนนี้ด้วย"}},{"id":"TH-H004-A275","no":275,"noLabel":{"th":"มาตรา 275"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๕ บุริมสิทธิในมูลจ้างทำของเป็นการงานทำขึ้นบนอสังหาริมทรัพย์นั้น ใช้สำหรับเอาสินจ้าง ค่าทำของเป็นการงานอันผู้ก่อสร้าง สถาปนิก หรือผู้รับจ้างได้ทำลงบนอสังหาริมทรัพย์ของลูกหนี้ และมีอยู่เหนืออสังหาริมทรัพย์อันนั้น อนึ่ง บุริมสิทธินี้ย่อมเกิดมีขึ้นต่อเมื่ออสังหาริมทรัพย์นั้นมีราคาเพิ่มขึ้นในปัจจุบันเพราะการที่ได้ทำขึ้นนั้น และมีอยู่เพียงเหนือราคาที่เพิ่มขึ้นเท่านั้น"}},{"id":"TH-H004-A276","no":276,"noLabel":{"th":"มาตรา 276"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๖ บุริมสิทธิในมูลซื้อขายอสังหาริมทรัพย์นั้น ใช้สำหรับเอาราคาอสังหาริมทรัพย์และดอกเบี้ยในราคานั้นและมีอยู่เหนืออสังหาริมทรัพย์อันนั้น"}},{"id":"TH-H004-A277","no":277,"noLabel":{"th":"มาตรา 277"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๗ เมื่อมีบุริมสิทธิสามัญหลายรายแย้งกัน ท่านให้ถือว่าบุริมสิทธิทั้งหลายนั้นมีลำดับที่จะให้ผลก่อนหลังดังที่ได้เรียงลำดับไว้ในมาตรา ๒๕๓ เมื่อมีบุริมสิทธิสามัญแย้งกับบุริมสิทธิพิเศษ ท่านว่าบุริมสิทธิพิเศษย่อมอยู่ในลำดับก่อน แต่บุริมสิทธิในมูลค่าใช้จ่ายเพื่อประโยชน์ร่วมกันนั้นย่อมอยู่ในลำดับก่อนในฐานที่จะใช้สิทธินั้นต่อเจ้าหนี้ผู้ได้รับประโยชน์จากการนั้นหมดทุกคนด้วยกัน"}},{"id":"TH-H004-A278","no":278,"noLabel":{"th":"มาตรา 278"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๘ เมื่อมีบุริมสิทธิแย้งกันหลายรายเหนือสังหาริมทรัพย์อันหนึ่งอันเดียวกัน ท่านให้ถือลำดับก่อนหลังดังที่เรียงไว้ต่อไปนี้ คือ (๑) บุริมสิทธิในมูลเช่าอสังหาริมทรัพย์ พักอาศัยในโรงแรมและรับขน (๒) บุริมสิทธิในมูลรักษาสังหาริมทรัพย์ แต่ถ้ามีบุคคลหลายคนเป็นผู้รักษา ท่านว่าผู้ที่รักษาภายหลังอยู่ในลำดับก่อนผู้ที่ได้รักษามาก่อน (๓) บุริมสิทธิในมูลซื้อขายสังหาริมทรัพย์ ค่าเมล็ดพันธุ์ ไม้พันธุ์ หรือปุ๋ย และค่าแรงงานกสิกรรมและอุตสาหกรรม ถ้าบุคคลผู้ใดมีบุริมสิทธิอยู่ในลำดับเป็นที่หนึ่ง และรู้อยู่ในขณะที่ตนได้ประโยชน์แห่งหนี้มานั้น ว่ายังมีบุคคลอื่นซึ่งมีบุริมสิทธิอยู่ในลำดับที่สองหรือที่สามไซร้ ท่านห้ามมิให้บุคคลผู้นั้นใช้สิทธิในการที่ตนอยู่ในลำดับก่อนนั้นต่อบุคคลอื่นเช่นว่ามา และท่านห้ามมิให้ใช้สิทธินี้ต่อผู้ที่ได้รักษาทรัพย์ไว้เพื่อประโยชน์แก่บุคคลผู้มีบุริมสิทธิในลำดับที่หนึ่งนั้นเองด้วย ในส่วนดอกผล ท่านให้บุคคลผู้ได้ทำการงานกสิกรรมอยู่ในลำดับที่หนึ่ง ผู้ส่งเมล็ดพันธุ์ ไม้พันธุ์ หรือปุ๋ย อยู่ในลำดับที่สอง และให้ผู้เช่าที่ดิน อยู่ในลำดับที่สาม"}},{"id":"TH-H004-A279","no":279,"noLabel":{"th":"มาตรา 279"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๗๙ เมื่อมีบุริมสิทธิพิเศษแย้งกันหลายรายเหนืออสังหาริมทรัพย์อันหนึ่งอันเดียวกัน ท่านให้ถือลำดับก่อนหลังดังที่ได้เรียงลำดับไว้ในมาตรา ๒๗๓ ถ้าได้ซื้อขายอสังหาริมทรัพย์นั้นสืบต่อกันไปอีกไซร้ ลำดับก่อนหลังในระหว่างผู้ขายด้วยกันนั้น ท่านให้เป็นไปตามลำดับที่ได้ซื้อขายก่อนและหลัง"}},{"id":"TH-H004-A280","no":280,"noLabel":{"th":"มาตรา 280"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๐ เมื่อบุคคลหลายคนมีบุริมสิทธิในลำดับเสมอกันเหนือทรัพย์อันหนึ่งอันเดียวกัน ท่านให้ต่างคนต่างได้รับชำระหนี้เฉลี่ยตามส่วนมากน้อยแห่งจำนวนที่ตนเป็นเจ้าหนี้"}},{"id":"TH-H004-A281","no":281,"noLabel":{"th":"มาตรา 281"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๑ บุริมสิทธิอันมีอยู่เหนือสังหาริมทรัพย์นั้น ท่านห้ามมิให้ใช้ เมื่อบุคคลภายนอกได้ทรัพย์นั้นจากลูกหนี้และได้ส่งมอบทรัพย์ให้กันไปเสร็จแล้ว"}},{"id":"TH-H004-A282","no":282,"noLabel":{"th":"มาตรา 282"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๒ เมื่อมีบุริมสิทธิแย้งกับสิทธิจำนำสังหาริมทรัพย์ ท่านว่าผู้รับจำนำย่อมมีสิทธิเป็นอย่างเดียวกันกับผู้ทรงบุริมสิทธิในลำดับที่หนึ่งดังที่เรียงไว้ในมาตรา ๒๗๘ นั้น"}},{"id":"TH-H004-A283","no":283,"noLabel":{"th":"มาตรา 283"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๓ บุคคลผู้มีบุริมสิทธิสามัญต้องรับชำระหนี้เอาจากสังหาริมทรัพย์ของลูกหนี้ก่อน ต่อเมื่อยังไม่พอจึงให้เอาชำระหนี้จากอสังหาริมทรัพย์ได้ ในส่วนอสังหาริมทรัพย์นั้น ก็ต้องรับชำระหนี้เอาจากอสังหาริมทรัพย์ อันมิได้ตกอยู่ในฐานเป็นหลักประกันพิเศษเสียก่อน ถ้าบุคคลใดมีบุริมสิทธิสามัญและละเลยด้วยความประมาทเลินเล่อไม่สอดเข้าแย้งขัดในการแบ่งเฉลี่ยทรัพย์ตามความที่กล่าวมาในวรรคทั้งสองข้างบนนี้ไซร้ อันบุคคลนั้นจะใช้บุริมสิทธิของตนต่อบุคคลภายนอกผู้ได้จดทะเบียนสิทธิไว้แล้ว เพื่อจะเอาใช้จนถึงขนาดเช่นที่ตนจะหากได้รับเพราะได้สอดเข้าแย้งขัดนั้น ท่านว่าหาอาจจะใช้ได้ไม่ อนึ่ง บทบัญญัติที่กล่าวมาในวรรคทั้งสามข้างต้นนี้ท่านมิให้ใช้บังคับ หากว่าเงินที่ขายอสังหาริมทรัพย์ได้นั้นจะพึงต้องเอามาแบ่งเฉลี่ยก่อนเงินที่ขายทรัพย์สินอย่างอื่นก็ดี หรือหากว่าเงินที่ขายอสังหาริมทรัพย์อันตกอยู่ในฐานเป็นหลักประกันพิเศษนั้นจะพึงต้องเอามาแบ่งเฉลี่ยก่อนเงินที่ขายอสังหาริมทรัพย์อย่างอื่นก็ดุจกัน"}},{"id":"TH-H004-A284","no":284,"noLabel":{"th":"มาตรา 284"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๔ บุริมสิทธิสามัญนั้น ถึงแม้จะมิได้ไปลงทะเบียนเกี่ยวด้วยอสังหาริมทรัพย์ก็ดี ย่อมจะยกขึ้นเป็นข้อต่อสู้เจ้าหนี้ใด ๆ ที่ไม่มีหลักประกันพิเศษนั้นได้ แต่ความที่กล่าวนี้ท่านมิให้ใช้ไปถึงการต่อสู้บุคคลภายนอกผู้ได้ไปลงทะเบียนสิทธิไว้"}},{"id":"TH-H004-A285","no":285,"noLabel":{"th":"มาตรา 285"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๕ บุริมสิทธิในมูลรักษาอสังหาริมทรัพย์นั้น ถ้าหากว่าเมื่อทำการเพื่อบำรุงรักษานั้นสำเร็จแล้ว ไปบอกลงทะเบียนไว้โดยพลันไซร้ บุริมสิทธิก็คงให้ผลต่อไป"}},{"id":"TH-H004-A286","no":286,"noLabel":{"th":"มาตรา 286"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๖ บุริมสิทธิในมูลจ้างทำของเป็นการงานทำขึ้นบนอสังหาริมทรัพย์นั้น หากทำรายการประมาณราคาชั่วคราวไปบอกลงทะเบียนไว้ก่อนเริ่มลงมือทำการไซร้ บุริมสิทธิก็คงให้ผลต่อไป แต่ถ้าราคาที่ทำจริงนั้นล้ำราคาที่ได้ประมาณไว้ชั่วคราว ท่านว่าบุริมสิทธิในส่วนจำนวนที่ล้ำอยู่นั้นหามีไม่ ส่วนการที่จะวินิจฉัยว่าอสังหาริมทรัพย์นั้นมีราคาเพิ่มขึ้นเพราะการอันได้ทำขึ้นบนอสังหาริมทรัพย์มากน้อยเพียงใดนั้น ท่านให้ศาลตั้งแต่งผู้เชี่ยวชาญขึ้นเป็นผู้กะประมาณ ในเวลาที่มีแย้งขัดในการแบ่งเฉลี่ย"}},{"id":"TH-H004-A287","no":287,"noLabel":{"th":"มาตรา 287"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๗ บุริมสิทธิใดได้ไปจดลงทะเบียนแล้วตามบทบัญญัติแห่งมาตราทั้งสองข้างบนนี้ บุริมสิทธินั้นท่านว่าอาจจะใช้ได้ก่อนสิทธิจำนอง"}},{"id":"TH-H004-A288","no":288,"noLabel":{"th":"มาตรา 288"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๘ บุริมสิทธิในมูลซื้อขายอสังหาริมทรัพย์นั้น หากว่าเมื่อไปลงทะเบียนสัญญาซื้อขายนั้น บอกลงทะเบียนไว้ด้วยว่าราคาหรือดอกเบี้ยในราคานั้นยังมิได้ชำระไซร้ บุริมสิทธินั้นก็คงให้ผลต่อไป"}},{"id":"TH-H004-A289","no":289,"noLabel":{"th":"มาตรา 289"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๒๘๙ ว่าถึงผลแห่งบุริมสิทธิ นอกจากที่ได้บัญญัติไว้ในมาตรา ๒๘๑ ถึงมาตรา ๒๘๘ นี้แล้ว ท่านให้นำบทบัญญัติทั้งหลายแห่งลักษณะจำนองมาใช้บังคับด้วยตามแต่กรณี"}},{"id":"TH-H004-A290","no":290,"noLabel":{"th":"มาตรา 290"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๐ ถ้าการชำระหนี้เป็นการอันจะแบ่งกันชำระได้ และมีบุคคลหลายคนเป็นลูกหนี้ก็ดี มีบุคคลหลายคนเป็นเจ้าหนี้ก็ดี เมื่อกรณีเป็นที่สงสัย ท่านว่าลูกหนี้แต่ละคนจะต้องรับผิดเพียงเป็นส่วนเท่า ๆ กัน และเจ้าหนี้แต่ละคนก็ชอบที่จะได้รับแต่เพียงเป็นส่วนเท่า ๆ กัน"}},{"id":"TH-H004-A291","no":291,"noLabel":{"th":"มาตรา 291"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๑ ถ้าบุคคลหลายคนจะต้องทำการชำระหนี้โดยทำนองซึ่งแต่ละคนจำต้องชำระหนี้สิ้นเชิงไซร้ แม้ถึงว่าเจ้าหนี้ชอบที่จะได้รับชำระหนี้สิ้นเชิงได้แต่เพียงครั้งเดียว (กล่าวคือลูกหนี้ร่วมกัน) ก็ดี เจ้าหนี้จะเรียกชำระหนี้จากลูกหนี้แต่คนใดคนหนึ่งสิ้นเชิงหรือแต่โดยส่วนก็ได้ตามแต่จะเลือก แต่ลูกหนี้ทั้งปวงก็ยังคงต้องผูกพันอยู่ทั่วทุกคนจนกว่าหนี้นั้นจะได้ชำระเสร็จสิ้นเชิง"}},{"id":"TH-H004-A292","no":292,"noLabel":{"th":"มาตรา 292"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๒ การที่ลูกหนี้ร่วมกันคนหนึ่งชำระหนี้นั้น ย่อมได้เป็นประโยชน์แก่ลูกหนี้คนอื่น ๆ ด้วย วิธีเดียวกันนี้ท่านให้ใช้บังคับแก่การใด ๆ อันพึงกระทำแทนชำระหนี้ วางทรัพย์สินแทนชำระหนี้ และหักกลบลบหนี้ด้วย ลูกหนี้ร่วมกันคนหนึ่งมีสิทธิเรียกร้องอย่างไร ลูกหนี้คนอื่น ๆ จะเอาสิทธิอันนั้นไปใช้หักกลบลบหนี้หาได้ไม่"}},{"id":"TH-H004-A293","no":293,"noLabel":{"th":"มาตรา 293"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๓ การปลดหนี้ให้แก่ลูกหนี้ร่วมกันคนหนึ่งนั้น ย่อมเป็นไปเพื่อประโยชน์แก่ลูกหนี้คนอื่น ๆ เพียงเท่าส่วนของลูกหนี้ที่ได้ปลดให้ เว้นแต่จะได้ตกลงกันเป็นอย่างอื่น"}},{"id":"TH-H004-A294","no":294,"noLabel":{"th":"มาตรา 294"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๔ การที่เจ้าหนี้ผิดนัดต่อลูกหนี้ร่วมกันคนหนึ่งนั้น ย่อมได้เป็นคุณประโยชน์แก่ลูกหนี้คนอื่น ๆ ด้วย"}},{"id":"TH-H004-A295","no":295,"noLabel":{"th":"มาตรา 295"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๕ ข้อความจริงอื่นใด นอกจากที่ระบุไว้ในมาตรา ๒๙๒ ถึงมาตรา ๒๙๔ นั้น เมื่อเป็นเรื่องเท้าถึงตัวลูกหนี้ร่วมกันคนใดก็ย่อมเป็นไปเพื่อคุณและโทษแต่เฉพาะแก่ลูกหนี้คนนั้น เว้นแต่จะปรากฏว่าขัดกับสภาพแห่งหนี้นั้นเอง ความที่ว่ามานี้ เมื่อจะกล่าวโดยเฉพาะก็คือว่าให้ใช้แก่การให้คำบอกกล่าว การผิดนัด การที่หยิบยกอ้างความผิด การชำระหนี้อันเป็นพ้นวิสัยแก่ฝ่ายลูกหนี้ร่วมกันคนหนึ่ง กำหนดอายุความหรือการที่อายุความสะดุดหยุดลง และการที่สิทธิเรียกร้องเกลื่อนกลืนกันไปกับหนี้สิน"}},{"id":"TH-H004-A296","no":296,"noLabel":{"th":"มาตรา 296"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๖ ในระหว่างลูกหนี้ร่วมกันทั้งหลายนั้น ท่านว่าต่างคนต่างต้องรับผิดเป็นส่วนเท่า ๆ กัน เว้นแต่จะได้กำหนดไว้เป็นอย่างอื่น ถ้าส่วนที่ลูกหนี้ร่วมกันคนใดคนหนึ่งจะพึงชำระนั้น เป็นอันจะเรียกเอาจากคนนั้นไม่ได้ไซร้ ยังขาดจำนวนอยู่เท่าไรลูกหนี้คนอื่น ๆ ซึ่งจำต้องออกส่วนด้วยนั้นก็ต้องรับใช้ แต่ถ้าลูกหนี้ร่วมกันคนใดเจ้าหนี้ได้ปลดให้หลุดพ้นจากหนี้อันร่วมกันนั้นแล้ว ส่วนที่ลูกหนี้คนนั้นจะพึงต้องชำระหนี้ก็ตกเป็นพับแก่เจ้าหนี้ไป"}},{"id":"TH-H004-A297","no":297,"noLabel":{"th":"มาตรา 297"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๗ ถ้าในสัญญาอันหนึ่งอันใดมีบุคคลหลายคนร่วมกันผูกพันตนในอันจะทำการชำระหนี้ไซร้ หากกรณีเป็นที่สงสัย ท่านว่าบุคคลเหล่านั้นจะต้องรับผิดเช่นอย่างเป็นลูกหนี้ร่วมกัน แม้ถึงว่าเป็นการอันจะแบ่งกันชำระหนี้ได้"}},{"id":"TH-H004-A298","no":298,"noLabel":{"th":"มาตรา 298"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๘ ถ้าบุคคลหลายคนมีสิทธิเรียกร้องการชำระหนี้โดยทำนองซึ่งแต่ละคนอาจจะเรียกให้ชำระหนี้สิ้นเชิงได้ไซร้ แม้ถึงว่าลูกหนี้จำต้องชำระหนี้สิ้นเชิงแต่เพียงครั้งเดียว (กล่าวคือเจ้าหนี้ร่วมกัน) ก็ดี ท่านว่าลูกหนี้จะชำระหนี้ให้แก่เจ้าหนี้แต่คนใดคนหนึ่งก็ได้ตามแต่จะเลือก ความข้อนี้ให้ใช้บังคับได้ แม้ทั้งที่เจ้าหนี้คนหนึ่งจะได้ยื่นฟ้องเรียกชำระหนี้ไว้แล้ว"}},{"id":"TH-H004-A299","no":299,"noLabel":{"th":"มาตรา 299"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๒๙๙ การที่เจ้าหนี้ร่วมกันคนหนึ่งผิดนัดนั้น ย่อมเป็นโทษแก่เจ้าหนี้คนอื่น ๆ ด้วย ถ้าสิทธิเรียกร้องและหนี้สินนั้นเป็นอันเกลื่อนกลืนกันไปในเจ้าหนี้ร่วมกันคนหนึ่ง สิทธิของเจ้าหนี้คนอื่น ๆ อันมีต่อลูกหนี้ก็ย่อมเป็นอันระงับสิ้นไป นอกจากนี้ ท่านให้นำบทบัญญัติแห่งมาตรา ๒๙๒ มาตรา ๒๙๓ และมาตรา ๒๙๕ มาใช้บังคับด้วยโดยอนุโลม กล่าวโดยเฉพาะก็คือ แม้เจ้าหนี้ร่วมกันคนหนึ่งจะโอนสิทธิเรียกร้องให้แก่บุคคลอื่นไปก็หากระทบกระทั่งถึงสิทธิของเจ้าหนี้คนอื่น ๆ ด้วยไม่"}},{"id":"TH-H004-A300","no":300,"noLabel":{"th":"มาตรา 300"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๐๐ ในระหว่างเจ้าหนี้ร่วมกันนั้น ท่านว่าต่างคนชอบที่จะได้รับชำระหนี้เป็นส่วนเท่า ๆ กัน เว้นแต่จะได้กำหนดไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A301","no":301,"noLabel":{"th":"มาตรา 301"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๐๑ ถ้าบุคคลหลายคนเป็นหนี้อันจะแบ่งกันชำระมิได้ ท่านว่าบุคคลเหล่านั้นต้องรับผิดเช่นอย่างลูกหนี้ร่วมกัน"}},{"id":"TH-H004-A302","no":302,"noLabel":{"th":"มาตรา 302"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๐๒ ถ้าการชำระหนี้เป็นการอันจะแบ่งกันชำระมิได้ และมีบุคคลหลายคนเป็นเจ้าหนี้ ถ้าบุคคลเหล่านั้นมิได้เป็นเจ้าหนี้ร่วมกันไซร้ ท่านว่าลูกหนี้ได้แต่จะชำระหนี้ให้ได้ประโยชน์แก่บุคคลเหล่านั้นทั้งหมดด้วยกัน และเจ้าหนี้แต่ละคนจะเรียกชำระหนี้ได้ก็แต่เพื่อได้ประโยชน์ด้วยกันหมดทุกคนเท่านั้น อนึ่ง เจ้าหนี้แต่ละคนจะเรียกให้ลูกหนี้วางทรัพย์ที่เป็นหนี้นั้นไว้เพื่อประโยชน์แห่งเจ้าหนี้หมดทุกคนด้วยกันก็ได้ หรือถ้าทรัพย์นั้นไม่ควรแก่การจะวางไว้ ก็ให้ส่งแก่ผู้พิทักษ์ทรัพย์ซึ่งศาลจะได้ตั้งแต่งขึ้น นอกจากนี้ ข้อความจริงใดที่เท้าถึงเจ้าหนี้คนหนึ่งเท่านั้น หาเป็นไปเพื่อคุณหรือโทษแก่เจ้าหนี้คนอื่น ๆ ด้วยไม่"}},{"id":"TH-H004-A303","no":303,"noLabel":{"th":"มาตรา 303"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๓ สิทธิเรียกร้องนั้นท่านว่าจะพึงโอนกันได้ เว้นไว้แต่สภาพแห่งสิทธินั้นเองจะไม่เปิดช่องให้โอนกันได้ ความที่กล่าวมานี้ย่อมไม่ใช้บังคับ หากคู่กรณีได้แสดงเจตนาเป็นอย่างอื่น การแสดงเจตนาเช่นว่านี้ ท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริต"}},{"id":"TH-H004-A304","no":304,"noLabel":{"th":"มาตรา 304"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๔ สิทธิเรียกร้องเช่นใด ตามกฎหมายศาลจะสั่งยึดไม่ได้ สิทธิเรียกร้องเช่นนั้น ท่านว่าจะโอนกันหาได้ไม่"}},{"id":"TH-H004-A305","no":305,"noLabel":{"th":"มาตรา 305"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๕ เมื่อโอนสิทธิเรียกร้องไป สิทธิจำนอง จำนำ หรือหลักประกันทางธุรกิจที่มีอยู่เกี่ยวพันกับสิทธิเรียกร้องนั้นก็ดี สิทธิอันเกิดขึ้นแต่การค้ำประกันที่ให้ไว้เพื่อสิทธิเรียกร้องนั้นก็ดี ย่อมตกไปได้แก่ผู้รับโอนด้วย อนึ่ง ผู้รับโอนจะใช้บุริมสิทธิใด ๆ ที่ตนมีอยู่เกี่ยวด้วยสิทธิเรียกร้องในกรณีบังคับยึดทรัพย์หรือล้มละลายนั้นก็ได้"}},{"id":"TH-H004-A306","no":306,"noLabel":{"th":"มาตรา 306"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๖ การโอนหนี้อันจะพึงต้องชำระแก่เจ้าหนี้คนหนึ่งโดยเฉพาะเจาะจงนั้น ถ้าไม่ทำเป็นหนังสือ ท่านว่าไม่สมบูรณ์ อนึ่ง การโอนหนี้นั้นท่านว่าจะยกขึ้นเป็นข้อต่อสู้ลูกหนี้หรือบุคคลภายนอกได้แต่เมื่อได้บอกกล่าวการโอนไปยังลูกหนี้ หรือลูกหนี้จะได้ยินยอมด้วยในการโอนนั้น คำบอกกล่าวหรือความยินยอมเช่นว่านี้ท่านว่าต้องทำเป็นหนังสือ ถ้าลูกหนี้ทำให้พอแก่ใจผู้โอนด้วยการใช้เงิน หรือด้วยประการอื่นเสียแต่ก่อนได้รับบอกกล่าว หรือก่อนได้ตกลงให้โอนไซร้ ลูกหนี้นั้นก็เป็นอันหลุดพ้นจากหนี้"}},{"id":"TH-H004-A307","no":307,"noLabel":{"th":"มาตรา 307"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๗ ถ้าพิพาทอ้างสิทธิในการโอนต่างราย โอนรายใดได้บอกกล่าวหรือตกลงกันก่อน โอนรายนั้นมีสิทธิดีกว่าโอนรายอื่น ๆ"}},{"id":"TH-H004-A308","no":308,"noLabel":{"th":"มาตรา 308"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๘ ถ้าลูกหนี้ได้ให้ความยินยอมดังกล่าวมาในมาตรา ๓๐๖ โดยมิได้อิดเอื้อน ท่านว่าจะยกข้อต่อสู้ที่มีต่อผู้โอนขึ้นต่อสู้ผู้รับโอนนั้นหาได้ไม่ แต่ถ้าเพื่อจะระงับหนี้นั้น ลูกหนี้ได้ใช้เงินให้แก่ผู้โอนไปไซร้ ลูกหนี้จะเรียกคืนเงินนั้นก็ได้ หรือถ้าเพื่อการเช่นกล่าวมานั้นลูกหนี้รับภาระเป็นหนี้อย่างใดอย่างหนึ่งขึ้นใหม่ต่อผู้โอน จะถือเสมือนหนึ่งว่าหนี้นั้นมิได้ก่อขึ้นเลยก็ได้ ถ้าลูกหนี้เป็นแต่ได้รับคำบอกกล่าวการโอน ท่านว่าลูกหนี้มีข้อต่อสู้ผู้โอนก่อนเวลาที่ได้รับคำบอกกล่าวนั้นฉันใด ก็จะยกขึ้นเป็นข้อต่อสู้แก่ผู้รับโอนได้ฉันนั้น ถ้าลูกหนี้มีสิทธิเรียกร้องจากผู้โอน แต่สิทธินั้นยังไม่ถึงกำหนดในเวลาบอกกล่าวไซร้ ท่านว่าจะเอาสิทธิเรียกร้องนั้นมาหักกลบลบกันก็ได้ หากว่าสิทธินั้นจะได้ถึงกำหนดไม่ช้ากว่าเวลาถึงกำหนดแห่งสิทธิเรียกร้องอันได้โอนไปนั้น"}},{"id":"TH-H004-A309","no":309,"noLabel":{"th":"มาตรา 309"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๐๙ การโอนหนี้อันพึงต้องชำระตามเขาสั่งนั้น ท่านว่าจะยกขึ้นเป็นข้อต่อสู้ลูกหนี้หรือบุคคลภายนอกคนอื่นได้ แต่เฉพาะเมื่อการโอนนั้นได้สลักหลังไว้ในตราสาร และตัวตราสารนั้นได้ส่งมอบให้แก่ผู้รับโอนไปด้วย"}},{"id":"TH-H004-A310","no":310,"noLabel":{"th":"มาตรา 310"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๑๐ ในมูลหนี้อันพึงต้องชำระตามเขาสั่งนั้น ลูกหนี้มีสิทธิที่จะสอบสวนถึงตัวผู้ทรงตราสาร หรือสอบสวนความถูกต้องแท้จริงแห่งลายมือชื่อหรือดวงตราของผู้ทรงได้ แต่ก็หามีความผูกพันที่จะต้องทำถึงเพียงนั้นไม่ แต่ถ้าลูกหนี้ทำการโดยทุจริตหรือประมาทเลินเล่ออย่างร้ายแรงไซร้ การชำระหนี้นั้นก็ไม่เป็นอันสมบูรณ์"}},{"id":"TH-H004-A311","no":311,"noLabel":{"th":"มาตรา 311"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๑๑ บทบัญญัติแห่งมาตราก่อนนี้ ท่านให้ใช้บังคับตลอดถึงกรณีที่มีกำหนดตัวเจ้าหนี้ระบุไว้ในตราสารซึ่งมีข้อความจดไว้ด้วยว่า ให้ชำระหนี้แก่ผู้ทรงตราสาร"}},{"id":"TH-H004-A312","no":312,"noLabel":{"th":"มาตรา 312"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๑๒ ในมูลหนี้อันพึงต้องชำระตามเขาสั่งนั้น ลูกหนี้จะยกข้อต่อสู้ซึ่งมีต่อเจ้าหนี้เดิมขึ้นเป็นข้อต่อสู้ผู้รับโอนโดยสุจริตนั้นหาได้ไม่ เว้นแต่ที่ปรากฏในตัวตราสารนั้นเอง หรือที่มีขึ้นเป็นธรรมดาสืบจากลักษณะแห่งตราสารนั้น"}},{"id":"TH-H004-A313","no":313,"noLabel":{"th":"มาตรา 313"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๑๓ บทบัญญัติแห่งมาตราก่อนนี้ ท่านให้ใช้บังคับตลอดถึงหนี้อันพึงต้องชำระแก่ผู้ถือนั้นด้วย แล้วแต่กรณี"}},{"id":"TH-H004-A314","no":314,"noLabel":{"th":"มาตรา 314"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๔ อันการชำระหนี้นั้น ท่านว่าบุคคลภายนอกจะเป็นผู้ชำระก็ได้ เว้นแต่สภาพแห่งหนี้จะไม่เปิดช่องให้บุคคลภายนอกชำระ หรือจะขัดกับเจตนาอันคู่กรณีได้แสดงไว้ บุคคลผู้ไม่มีส่วนได้เสียด้วยในการชำระหนี้นั้น จะเข้าชำระหนี้โดยขืนใจลูกหนี้หาได้ไม่"}},{"id":"TH-H004-A315","no":315,"noLabel":{"th":"มาตรา 315"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๕ อันการชำระหนี้นั้นต้องทำให้แก่ตัวเจ้าหนี้หรือแก่บุคคลผู้มีอำนาจรับชำระหนี้แทนเจ้าหนี้ การชำระหนี้ทำให้แก่บุคคลผู้ไม่มีอำนาจรับชำระหนี้นั้น ถ้าเจ้าหนี้ให้สัตยาบันก็นับว่าสมบูรณ์"}},{"id":"TH-H004-A316","no":316,"noLabel":{"th":"มาตรา 316"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๖ ถ้าการชำระหนี้นั้นได้ทำให้แก่ผู้ครองตามปรากฏแห่งสิทธิในมูลหนี้ ท่านว่าการชำระหนี้นั้นจะสมบูรณ์ก็แต่เมื่อบุคคลผู้ชำระหนี้ได้กระทำการโดยสุจริต"}},{"id":"TH-H004-A317","no":317,"noLabel":{"th":"มาตรา 317"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๗ นอกจากกรณีที่กล่าวไว้ในมาตราก่อน การชำระหนี้แก่บุคคลผู้ไม่มีสิทธิจะได้รับนั้น ท่านว่าย่อมสมบูรณ์เพียงเท่าที่ตัวเจ้าหนี้ได้ลาภงอกขึ้นแต่การนั้น"}},{"id":"TH-H004-A318","no":318,"noLabel":{"th":"มาตรา 318"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๘ บุคคลผู้ถือใบเสร็จเป็นสำคัญ ท่านนับว่าเป็นผู้มีสิทธิจะได้รับชำระหนี้ แต่ความที่กล่าวนี้ท่านมิให้ใช้ ถ้าบุคคลผู้ชำระหนี้รู้ว่าสิทธิเช่นนั้นหามีไม่ หรือไม่รู้เท่าถึงสิทธินั้น เพราะความประมาทเลินเล่อของตน"}},{"id":"TH-H004-A319","no":319,"noLabel":{"th":"มาตรา 319"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๑๙ ถ้าศาลสั่งให้ลูกหนี้คนที่สามงดเว้นทำการชำระหนี้แล้ว ยังขืนชำระหนี้ให้แก่เจ้าหนี้ของตนเองไซร้ ท่านว่าเจ้าหนี้ผู้ที่ร้องขอให้ยึดทรัพย์จะเรียกให้ลูกหนี้คนที่สามนั้นทำการชำระหนี้อีกให้คุ้มกับความเสียหายอันตนได้รับก็ได้ อนึ่ง ข้อความซึ่งกล่าวมาในวรรคข้างต้นนี้หาเป็นข้อขัดขวางในการที่ลูกหนี้คนที่สามจะใช้สิทธิไล่เบี้ยเอาแก่เจ้าหนี้ของตนเองนั้นไม่"}},{"id":"TH-H004-A320","no":320,"noLabel":{"th":"มาตรา 320"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๐ อันจะบังคับให้เจ้าหนี้รับชำระหนี้แต่เพียงบางส่วน หรือให้รับชำระหนี้เป็นอย่างอื่นผิดไปจากที่จะต้องชำระแก่เจ้าหนี้นั้น ท่านว่าหาอาจจะบังคับได้ไม่"}},{"id":"TH-H004-A321","no":321,"noLabel":{"th":"มาตรา 321"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๑ ถ้าเจ้าหนี้ยอมรับการชำระหนี้อย่างอื่นแทนการชำระหนี้ที่ได้ตกลงกันไว้ ท่านว่าหนี้นั้นก็เป็นอันระงับสิ้นไป ถ้าเพื่อที่จะทำให้พอแก่ใจเจ้าหนี้นั้น ลูกหนี้รับภาระเป็นหนี้อย่างใดอย่างหนึ่งขึ้นใหม่ต่อเจ้าหนี้ไซร้ เมื่อกรณีเป็นที่สงสัย ท่านมิให้สันนิษฐานว่าลูกหนี้ได้ก่อหนี้นั้นขึ้นแทนการชำระหนี้ ถ้าชำระหนี้ด้วยออก ด้วยโอน หรือด้วยสลักหลังตั๋วเงิน หรือประทวนสินค้า ท่านว่าหนี้นั้นจะระงับสิ้นไปต่อเมื่อตั๋วเงิน หรือประทวนสินค้านั้นได้ใช้เงินแล้ว"}},{"id":"TH-H004-A322","no":322,"noLabel":{"th":"มาตรา 322"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๒ ถ้าเอาทรัพย์ก็ดี สิทธิเรียกร้องจากบุคคลภายนอกก็ดี หรือสิทธิอย่างอื่นก็ดี ให้แทนการชำระหนี้ ท่านว่าลูกหนี้จะต้องรับผิด เพื่อชำรุดบกพร่องและเพื่อการรอนสิทธิทำนองเดียวกับผู้ขาย"}},{"id":"TH-H004-A323","no":323,"noLabel":{"th":"มาตรา 323"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๓ ถ้าวัตถุแห่งหนี้เป็นอันให้ส่งมอบทรัพย์เฉพาะสิ่ง ท่านว่าบุคคลผู้ชำระหนี้จะต้องส่งมอบทรัพย์ตามสภาพที่เป็นอยู่ในเวลาที่จะพึงส่งมอบ ลูกหนี้จำต้องรักษาทรัพย์นั้นไว้ด้วยความระมัดระวังเช่นอย่างวิญญูชนจะพึงสงวนทรัพย์สินของตนเอง จนกว่าจะได้ส่งมอบทรัพย์นั้น"}},{"id":"TH-H004-A324","no":324,"noLabel":{"th":"มาตรา 324"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๔ เมื่อมิได้มีแสดงเจตนาไว้โดยเฉพาะเจาะจงว่าจะพึงชำระหนี้ ณ สถานที่ใดไซร้ หากจะต้องส่งมอบทรัพย์เฉพาะสิ่ง ท่านว่าต้องส่งมอบกัน ณ สถานที่ซึ่งทรัพย์นั้นได้อยู่ในเวลาเมื่อก่อให้เกิดหนี้นั้น ส่วนการชำระหนี้โดยประการอื่น ท่านว่าต้องชำระ ณ สถานที่ซึ่งเป็นภูมิลำเนาปัจจุบันของเจ้าหนี้"}},{"id":"TH-H004-A325","no":325,"noLabel":{"th":"มาตรา 325"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๕ เมื่อมิได้มีแสดงเจตนาไว้ในข้อค่าใช้จ่ายในการชำระหนี้ ท่านว่าฝ่ายลูกหนี้พึงเป็นผู้ออกค่าใช้จ่าย แต่ถ้าค่าใช้จ่ายนั้นมีจำนวนเพิ่มขึ้นเพราะเจ้าหนี้ย้ายภูมิลำเนาก็ดี หรือเพราะการอื่นใดอันเจ้าหนี้ได้กระทำก็ดี ค่าใช้จ่ายเพิ่มขึ้นเท่าใดเจ้าหนี้ต้องเป็นผู้ออก"}},{"id":"TH-H004-A326","no":326,"noLabel":{"th":"มาตรา 326"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๖ บุคคลผู้ชำระหนี้ชอบที่จะได้รับใบเสร็จเป็นสำคัญจากผู้รับชำระหนี้นั้น และถ้าหนี้นั้นได้ชำระสิ้นเชิงแล้ว ผู้ชำระหนี้ชอบที่จะได้รับเวนคืนเอกสารอันเป็นหลักฐานแห่งหนี้ หรือให้ขีดฆ่าเอกสารนั้นเสีย ถ้าและเอกสารนั้นสูญหาย บุคคลผู้ชำระหนี้ชอบที่จะให้จดแจ้งความข้อระงับหนี้ลงไว้ในใบเสร็จ หรือในเอกสารอีกฉบับหนึ่งต่างหากก็ได้ ถ้าหนี้นั้นได้ชำระแต่บางส่วนก็ดี หรือถ้าเอกสารนั้นยังให้สิทธิอย่างอื่นใดแก่เจ้าหนี้อยู่ก็ดี ท่านว่าลูกหนี้ชอบแต่ที่จะได้รับใบเสร็จไว้เป็นคู่มือ และให้จดแจ้งการชำระหนี้นั้นลงไว้ในเอกสาร"}},{"id":"TH-H004-A327","no":327,"noLabel":{"th":"มาตรา 327"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๗ ในกรณีชำระดอกเบี้ย หรือชำระหนี้อย่างอื่นอันมีกำหนดชำระเป็นระยะเวลานั้น ถ้าเจ้าหนี้ออกใบเสร็จให้เพื่อระยะหนึ่งแล้วโดยมิได้อิดเอื้อน ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าหนี้ได้รับชำระหนี้เพื่อระยะก่อน ๆ นั้นด้วยแล้ว ถ้าเจ้าหนี้ออกใบเสร็จให้เพื่อการชำระต้นเงิน ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าหนี้ได้รับดอกเบี้ยแล้ว ถ้าเอกสารอันเป็นหลักฐานแห่งหนี้ได้เวนคืนแล้วไซร้ ท่านให้สันนิษฐานไว้ก่อนว่าหนี้นั้นเป็นอันระงับสิ้นไปแล้ว"}},{"id":"TH-H004-A328","no":328,"noLabel":{"th":"มาตรา 328"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๘ ถ้าลูกหนี้ต้องผูกพันต่อเจ้าหนี้ในอันจะกระทำการเพื่อชำระหนี้เป็นการอย่างเดียวกันโดยมูลหนี้หลายราย และถ้าการที่ลูกหนี้ชำระหนี้นั้นไม่เพียงพอจะเปลื้องหนี้สินได้หมดทุกรายไซร้ เมื่อทำการชำระหนี้ ลูกหนี้ระบุว่าชำระหนี้สินรายใด ก็ให้หนี้สินรายนั้นเป็นอันได้เปลื้องไป ถ้าลูกหนี้ไม่ระบุ ท่านว่าหนี้สินรายไหนถึงกำหนด ก็ให้รายนั้นเป็นอันได้เปลื้องไปก่อน ในระหว่างหนี้สินหลายรายที่ถึงกำหนดนั้น รายใดเจ้าหนี้มีประกันน้อยที่สุด ก็ให้รายนั้นเป็นอันได้เปลื้องไปก่อน ในระหว่างหนี้สินหลายรายที่มีประกันเท่า ๆ กัน ให้รายที่ตกหนักที่สุดแก่ลูกหนี้เป็นอันได้เปลื้องไปก่อน ในระหว่างหนี้สินหลายรายที่ตกหนักแก่ลูกหนี้เท่า ๆ กัน ให้หนี้สินรายเก่าที่สุดเป็นอันได้เปลื้องไปก่อน และถ้ามีหนี้สินหลายรายเก่าเท่า ๆ กัน ก็ให้หนี้ทุกรายเป็นอันได้เปลื้องไปตามส่วนมากและน้อย"}},{"id":"TH-H004-A329","no":329,"noLabel":{"th":"มาตรา 329"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๒๙ ถ้านอกจากการชำระหนี้อันเป็นประธาน ลูกหนี้ยังจะต้องชำระดอกเบี้ยและเสียค่าฤชาธรรมเนียมอีกด้วยไซร้ หากการชำระหนี้ในครั้งหนึ่ง ๆ ไม่ได้ราคาเพียงพอจะเปลื้องหนี้สินได้ทั้งหมด ท่านให้เอาจัดใช้เป็นค่าฤชาธรรมเนียมเสียก่อนแล้วจึงใช้ดอกเบี้ย และในที่สุดจึงให้ใช้ในการชำระหนี้อันเป็นประธาน ถ้าลูกหนี้ระบุให้จัดใช้เป็นประการอื่น ท่านว่าเจ้าหนี้จะบอกปัดไม่ยอมรับชำระหนี้ก็ได้"}},{"id":"TH-H004-A330","no":330,"noLabel":{"th":"มาตรา 330"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๐ เมื่อขอปฏิบัติการชำระหนี้โดยชอบแล้ว บรรดาความรับผิดชอบอันเกิดแต่การไม่ชำระหนี้ ก็เป็นอันปลดเปลื้องไป นับแต่เวลาที่ขอปฏิบัติการชำระหนี้นั้น"}},{"id":"TH-H004-A331","no":331,"noLabel":{"th":"มาตรา 331"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๑ ถ้าเจ้าหนี้บอกปัดไม่ยอมรับชำระหนี้ก็ดี หรือไม่สามารถจะรับชำระหนี้ได้ก็ดี หากบุคคลผู้ชำระหนี้วางทรัพย์อันเป็นวัตถุแห่งหนี้ไว้เพื่อประโยชน์แก่เจ้าหนี้แล้ว ก็ย่อมจะเป็นอันหลุดพ้นจากหนี้ได้ ความข้อนี้ท่านให้ใช้ตลอดถึงกรณีที่บุคคลผู้ชำระหนี้ไม่สามารถจะหยั่งรู้ถึงสิทธิ หรือไม่รู้ตัวเจ้าหนี้ได้แน่นอนโดยมิใช่เป็นความผิดของตน"}},{"id":"TH-H004-A332","no":332,"noLabel":{"th":"มาตรา 332"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๒ ถ้าลูกหนี้จำต้องชำระหนี้ต่อเมื่อเจ้าหนี้จะต้องชำระหนี้ตอบแทนด้วยไซร้ ท่านว่าลูกหนี้จะกำหนดว่าต่อเมื่อเจ้าหนี้ชำระหนี้ตอบแทนจึงให้มีสิทธิรับเอาทรัพย์ที่วางไว้นั้นก็ได้"}},{"id":"TH-H004-A333","no":333,"noLabel":{"th":"มาตรา 333"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๓ การวางทรัพย์นั้นต้องวาง ณ สำนักงานวางทรัพย์ประจำตำบลที่จะต้องชำระหนี้ ถ้าไม่มีบทบัญญัติแห่งกฎหมายหรือกฎข้อบังคับเฉพาะการในเรื่องสำนักงานวางทรัพย์ เมื่อบุคคลผู้ชำระหนี้ร้องขอ ศาลจะต้องกำหนดสำนักงานวางทรัพย์และตั้งแต่งผู้พิทักษ์ทรัพย์ที่วางนั้นขึ้น ผู้วางต้องบอกกล่าวให้เจ้าหนี้ทราบการที่ได้วางทรัพย์นั้นโดยพลัน"}},{"id":"TH-H004-A334","no":334,"noLabel":{"th":"มาตรา 334"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๔ ลูกหนี้มีสิทธิจะถอนทรัพย์ที่วางนั้นได้ ถ้าลูกหนี้ถอนทรัพย์นั้น ท่านให้ถือเสมือนว่ามิได้วางทรัพย์ไว้เลย สิทธิถอนทรัพย์นี้เป็นอันขาดในกรณีต่อไปนี้ (๑) ถ้าลูกหนี้แสดงต่อสำนักงานวางทรัพย์ว่าตนยอมละสิทธิที่จะถอน (๒) ถ้าเจ้าหนี้แสดงต่อสำนักงานวางทรัพย์ว่าจะรับเอาทรัพย์นั้น (๓) ถ้าการวางทรัพย์นั้นได้เป็นไปโดยคำสั่งหรืออนุมัติของศาล และได้บอกกล่าวความนั้นแก่สำนักงานวางทรัพย์"}},{"id":"TH-H004-A335","no":335,"noLabel":{"th":"มาตรา 335"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๕ สิทธิถอนทรัพย์นั้น ตามกฎหมาย ศาลจะสั่งยึดหาได้ไม่ เมื่อได้ฟ้องคดีล้มละลายเกี่ยวกับทรัพย์สินของลูกหนี้แล้ว ท่านห้ามมิให้ใช้สิทธิถอนทรัพย์ในระหว่างพิจารณาคดีล้มละลาย"}},{"id":"TH-H004-A336","no":336,"noLabel":{"th":"มาตรา 336"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๖ ถ้าทรัพย์อันเป็นวัตถุแห่งการชำระหนี้ไม่ควรแก่การจะวางไว้ก็ดี หรือเป็นที่พึงวิตกว่าทรัพย์นั้นเกลือกจะเสื่อมเสีย หรือทำลาย หรือบุบสลายได้ก็ดี เมื่อได้รับอนุญาตจากศาล บุคคลผู้ชำระหนี้จะเอาทรัพย์นั้นออกขายทอดตลาด แล้วเอาเงินที่ได้แต่การขายวางแทนทรัพย์นั้นก็ได้ ความข้อนี้ท่านให้ใช้ตลอดถึงกรณีที่ค่ารักษาทรัพย์จะแพงเกินควรนั้นด้วย"}},{"id":"TH-H004-A337","no":337,"noLabel":{"th":"มาตรา 337"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๗ ท่านไม่อนุญาตให้เอาทรัพย์ออกขายทอดตลาดจนกว่าจะได้บอกให้เจ้าหนี้รู้ตัวก่อน การบอกนี้จะงดเสียก็ได้ ถ้าทรัพย์นั้นอาจเสื่อมทรามลง หรือภัยมีอยู่ในการที่จะหน่วงการขายทอดตลาดไว้ ในการที่จะขายทอดตลาดนั้น ท่านให้ลูกหนี้บอกกล่าวแก่เจ้าหนี้โดยไม่ชักช้า ถ้าละเลยเสียไม่บอกกล่าว ลูกหนี้จะต้องรับผิดใช้ค่าสินไหมทดแทน การบอกให้รู้ตัวและบอกกล่าวนี้ ถ้าไม่เป็นอันจะทำได้จะงดเสียก็ได้ เวลาและสถานที่ที่จะขายทอดตลาด กับทั้งคำพรรณนาลักษณะแห่งทรัพย์นั้น ท่านให้ประกาศโฆษณาให้ประชาชนทราบ"}},{"id":"TH-H004-A338","no":338,"noLabel":{"th":"มาตรา 338"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๘ ค่าฤชาธรรมเนียมในการวางทรัพย์หรือขายทอดตลาดนั้น ให้ฝ่ายเจ้าหนี้เป็นผู้ออก เว้นแต่ลูกหนี้จะได้ถอนทรัพย์ที่วาง"}},{"id":"TH-H004-A339","no":339,"noLabel":{"th":"มาตรา 339"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๓๓๙ สิทธิของเจ้าหนี้เหนือทรัพย์ที่วางไว้นั้นเป็นอันระงับสิ้นไปเมื่อพ้นเวลาสิบปี นับแต่ได้รับคำบอกกล่าวการวางทรัพย์ อนึ่ง เมื่อสิทธิของเจ้าหนี้ระงับสิ้นไปแล้วถึงแม้ลูกหนี้จะได้ละสิทธิถอนทรัพย์ ก็ยังชอบที่จะถอนทรัพย์นั้นได้"}},{"id":"TH-H004-A340","no":340,"noLabel":{"th":"มาตรา 340"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๓๔๐ ถ้าเจ้าหนี้แสดงเจตนาต่อลูกหนี้ว่าจะปลดหนี้ให้ ท่านว่าหนี้นั้นก็เป็นอันระงับสิ้นไป ถ้าหนี้มีหนังสือเป็นหลักฐาน การปลดหนี้ก็ต้องทำเป็นหนังสือด้วย หรือต้องเวนคืนเอกสารอันเป็นหลักฐานแห่งหนี้ให้แก่ลูกหนี้ หรือขีดฆ่าเอกสารนั้นเสีย"}},{"id":"TH-H004-A341","no":341,"noLabel":{"th":"มาตรา 341"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๑ ถ้าบุคคลสองคนต่างมีความผูกพันซึ่งกันและกัน โดยมูลหนี้อันมีวัตถุเป็นอย่างเดียวกัน และหนี้ทั้งสองรายนั้นถึงกำหนดจะชำระไซร้ ท่านว่าลูกหนี้ฝ่ายใดฝ่ายหนึ่งย่อมจะหลุดพ้นจากหนี้ของตนด้วยหักกลบลบกันได้เพียงเท่าจำนวนที่ตรงกันในมูลหนี้ทั้งสองฝ่ายนั้น เว้นแต่สภาพแห่งหนี้ฝ่ายหนึ่งจะไม่เปิดช่องให้หักกลบลบกันได้ บทบัญญัติดังกล่าวมาในวรรคก่อนนี้ท่านมิให้ใช้บังคับ หากเป็นการขัดกับเจตนาอันคู่กรณีได้แสดงไว้ แต่เจตนาเช่นนี้ท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริต"}},{"id":"TH-H004-A342","no":342,"noLabel":{"th":"มาตรา 342"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๒ หักกลบลบหนี้นั้น ทำได้ด้วยคู่กรณีฝ่ายหนึ่งแสดงเจตนาแก่อีกฝ่ายหนึ่ง การแสดงเจตนาเช่นนี้ท่านว่าจะมีเงื่อนไขหรือเงื่อนเวลาเริ่มต้นหรือเวลาสิ้นสุดอีกด้วยหาได้ไม่ การแสดงเจตนาดังกล่าวมาในวรรคก่อนนี้ ท่านว่ามีผลย้อนหลังขึ้นไปจนถึงเวลาซึ่งหนี้ทั้งสองฝ่ายนั้นจะอาจหักกลบลบกันได้เป็นครั้งแรก"}},{"id":"TH-H004-A343","no":343,"noLabel":{"th":"มาตรา 343"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๓ การหักกลบลบหนี้นั้น ถึงแม้ว่าสถานที่ซึ่งจะต้องชำระหนี้ทั้งสองจะต่างกัน ก็หักกันได้ แต่ฝ่ายผู้ขอหักหนี้จะต้องใช้ค่าเสียหายให้แก่อีกฝ่ายหนึ่งเพื่อความเสียหายอย่างหนึ่งอย่างใดอันเกิดแต่การนั้น"}},{"id":"TH-H004-A344","no":344,"noLabel":{"th":"มาตรา 344"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๔ สิทธิเรียกร้องใดยังมีข้อต่อสู้อยู่ สิทธิเรียกร้องนั้นท่านว่าหาอาจจะเอามาหักกลบลบหนี้ได้ไม่ อนึ่ง อายุความย่อมไม่ตัดรอนการหักกลบลบหนี้ แม้สิทธิเรียกร้องขาดอายุความแล้ว แต่ว่าในเวลาที่อาจจะหักกลบลบกับสิทธิเรียกร้องฝ่ายอื่นได้นั้น สิทธิยังไม่ขาด"}},{"id":"TH-H004-A345","no":345,"noLabel":{"th":"มาตรา 345"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๕ หนี้รายใดเกิดแต่การอันมิชอบด้วยกฎหมายเป็นมูล ท่านห้ามมิให้ลูกหนี้ถือเอาประโยชน์แห่งหนี้รายนั้นเพื่อหักกลบลบหนี้กับเจ้าหนี้"}},{"id":"TH-H004-A346","no":346,"noLabel":{"th":"มาตรา 346"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๖ สิทธิเรียกร้องรายใด ตามกฎหมายศาลจะสั่งยึดมิได้ สิทธิเรียกร้องรายนั้นหาอาจจะเอาไปหักกลบลบหนี้ได้ไม่"}},{"id":"TH-H004-A347","no":347,"noLabel":{"th":"มาตรา 347"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๗ ลูกหนี้คนที่สามหากได้รับคำสั่งศาลห้ามมิให้ใช้เงินแล้ว จะยกเอาหนี้ซึ่งตนได้มาภายหลังแต่นั้นขึ้นเป็นข้อต่อสู้เจ้าหนี้ผู้ที่ขอให้ยึดทรัพย์นั้น ท่านว่าหาอาจจะยกได้ไม่"}},{"id":"TH-H004-A348","no":348,"noLabel":{"th":"มาตรา 348"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๓๔๘ ถ้าคู่กรณีต่างฝ่ายต่างมีสิทธิเรียกร้องหลายราย อันควรแก่การที่จะใช้หักกลบลบหนี้ได้ไซร้ ฝ่ายผู้ที่ขอหักหนี้จะระบุก็ได้ว่าพึงเอาสิทธิเรียกร้องรายใดบ้างเข้าหักกลบลบกัน ถ้าการหักกลบลบหนี้ได้แสดงโดยมิได้ระบุเช่นนั้นก็ดี หรือถ้าระบุ แต่อีกฝ่ายหนึ่งท้วงขัดข้องโดยไม่ชักช้าก็ดี ท่านให้นำบทบัญญัติแห่งมาตรา ๓๒๘ วรรคสอง มาใช้บังคับโดยอนุโลม ถ้าฝ่ายที่ขอหักกลบลบหนี้ยังเป็นหนี้ค่าดอกเบี้ยและค่าฤชาธรรมเนียมแก่อีกฝ่ายหนึ่งอยู่ นอกจากการชำระหนี้อันเป็นประธานนั้นด้วยไซร้ ท่านให้นำบทบัญญัติแห่งมาตรา ๓๒๙ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A349","no":349,"noLabel":{"th":"มาตรา 349"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๓๔๙ เมื่อคู่กรณีที่เกี่ยวข้องได้ทำสัญญาเปลี่ยนสิ่งซึ่งเป็นสาระสำคัญแห่งหนี้ไซร้ ท่านว่าหนี้นั้นเป็นอันระงับสิ้นไปด้วยแปลงหนี้ใหม่ ถ้าทำหนี้มีเงื่อนไขให้กลายเป็นหนี้ปราศจากเงื่อนไขก็ดี เพิ่มเติมเงื่อนไขเข้าในหนี้อันปราศจากเงื่อนไขก็ดี เปลี่ยนเงื่อนไขก็ดี ท่านถือว่าเป็นอันเปลี่ยนสิ่งซึ่งเป็นสาระสำคัญแห่งหนี้นั้น ถ้าแปลงหนี้ใหม่ด้วยเปลี่ยนตัวเจ้าหนี้ ท่านให้บังคับด้วยบทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้ ว่าด้วยโอนสิทธิเรียกร้อง"}},{"id":"TH-H004-A350","no":350,"noLabel":{"th":"มาตรา 350"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๓๕๐ แปลงหนี้ใหม่ด้วยเปลี่ยนตัวลูกหนี้นั้น จะทำเป็นสัญญาระหว่างเจ้าหนี้กับลูกหนี้คนใหม่ก็ได้ แต่จะทำโดยขืนใจลูกหนี้เดิมหาได้ไม่"}},{"id":"TH-H004-A351","no":351,"noLabel":{"th":"มาตรา 351"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๓๕๑ ถ้าหนี้อันจะพึงเกิดขึ้นเพราะแปลงหนี้ใหม่นั้นมิได้เกิดมีขึ้นก็ดี ได้ยกเลิกเสียเพราะมูลแห่งหนี้ไม่ชอบด้วยกฎหมาย หรือเพราะเหตุอย่างใดอย่างหนึ่งอันมิรู้ถึงคู่กรณีก็ดี ท่านว่าหนี้เดิมนั้นก็ยังหาระงับสิ้นไปไม่"}},{"id":"TH-H004-A352","no":352,"noLabel":{"th":"มาตรา 352"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๓๕๒ คู่กรณีในการแปลงหนี้ใหม่อาจโอนสิทธิจำนำ หรือจำนองที่ได้ให้ไว้เป็นประกันหนี้เดิมนั้นไปเป็นประกันหนี้รายใหม่ได้ เพียงเท่าที่เป็นประกันวัตถุแห่งหนี้เดิม แต่หลักประกันเช่นว่านี้ ถ้าบุคคลภายนอกเป็นผู้ให้ไว้ไซร้ ท่านว่าจำต้องได้รับความยินยอมของบุคคลภายนอกนั้นด้วยจึงโอนได้"}},{"id":"TH-H004-A353","no":353,"noLabel":{"th":"มาตรา 353"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๓๕๓ ถ้าสิทธิและความรับผิดในหนี้รายใดตกอยู่แก่บุคคลคนเดียวกัน ท่านว่าหนี้รายนั้นเป็นอันระงับสิ้นไป เว้นแต่เมื่อหนี้นั้นตกไปอยู่ในบังคับแห่งสิทธิของบุคคลภายนอก หรือเมื่อสลักหลังตั๋วเงินกลับคืนตามความในมาตรา ๙๑๗ วรรคสาม"}},{"id":"TH-H004-A354","no":354,"noLabel":{"th":"มาตรา 354"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๔ คำเสนอจะทำสัญญาอันบ่งระยะเวลาให้ทำคำสนองนั้น ท่านว่าไม่อาจจะถอนได้ภายในระยะเวลาที่บ่งไว้"}},{"id":"TH-H004-A355","no":355,"noLabel":{"th":"มาตรา 355"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๕ บุคคลทำคำเสนอไปยังผู้อื่นซึ่งอยู่ห่างกันโดยระยะทาง และมิได้บ่งระยะเวลาให้ทำคำสนอง จะถอนคำเสนอของตนเสียภายในเวลาอันควรคาดหมายว่าจะได้รับคำบอกกล่าวสนองนั้น ท่านว่าหาอาจจะถอนได้ไม่"}},{"id":"TH-H004-A356","no":356,"noLabel":{"th":"มาตรา 356"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๖ คำเสนอทำแก่บุคคลผู้อยู่เฉพาะหน้า โดยมิได้บ่งระยะเวลาให้ทำคำสนองนั้น เสนอ ณ ที่ใดเวลาใดก็ย่อมจะสนองรับได้แต่ ณ ที่นั้นเวลานั้น ความข้อนี้ท่านให้ใช้ตลอดถึงการที่บุคคลคนหนึ่งทำคำเสนอไปยังบุคคลอีกคนหนึ่งทางโทรศัพท์ด้วย"}},{"id":"TH-H004-A357","no":357,"noLabel":{"th":"มาตรา 357"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๗ คำเสนอใดเขาบอกปัดไปยังผู้เสนอแล้วก็ดี หรือมิได้สนองรับภายในเวลากำหนดดังกล่าวมาในมาตราทั้งสามก่อนนี้ก็ดี คำเสนอนั้นท่านว่าเป็นอันสิ้นความผูกพันแต่นั้นไป"}},{"id":"TH-H004-A358","no":358,"noLabel":{"th":"มาตรา 358"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๘ ถ้าคำบอกกล่าวสนองมาถึงล่วงเวลา แต่เป็นที่เห็นประจักษ์ว่าคำบอกกล่าวนั้นได้ส่งโดยทางการซึ่งตามปกติควรจะมาถึงภายในเวลากำหนดไซร้ ผู้เสนอต้องบอกกล่าวแก่คู่กรณีอีกฝ่ายหนึ่งโดยพลันว่าคำสนองนั้นมาถึงเนิ่นช้า เว้นแต่จะได้บอกกล่าวเช่นนั้นก่อนแล้ว ถ้าผู้เสนอละเลยไม่บอกกล่าวดังว่ามาในวรรคต้น ท่านให้ถือว่าคำบอกกล่าวสนองนั้นมิได้ล่วงเวลา"}},{"id":"TH-H004-A359","no":359,"noLabel":{"th":"มาตรา 359"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๕๙ ถ้าคำสนองมาถึงล่วงเวลา ท่านให้ถือว่าคำสนองนั้นกลายเป็นคำเสนอขึ้นใหม่ คำสนองอันมีข้อความเพิ่มเติม มีข้อจำกัด หรือมีข้อแก้ไขอย่างอื่นประกอบด้วยนั้น ท่านให้ถือว่าเป็นคำบอกปัดไม่รับทั้งเป็นคำเสนอขึ้นใหม่ด้วยในตัว"}},{"id":"TH-H004-A360","no":360,"noLabel":{"th":"มาตรา 360"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๐ บทบัญญัติแห่งมาตรา ๑๖๙ วรรคสอง นั้น ท่านมิให้ใช้บังคับ ถ้าหากว่าขัดกับเจตนาอันผู้เสนอได้แสดง หรือหากว่าก่อนจะสนองรับนั้น คู่กรณีอีกฝ่ายหนึ่งได้รู้อยู่แล้วว่าผู้เสนอตายหรือตกเป็นผู้ไร้ความสามารถ"}},{"id":"TH-H004-A361","no":361,"noLabel":{"th":"มาตรา 361"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๑ อันสัญญาระหว่างบุคคลซึ่งอยู่ห่างกันโดยระยะทางนั้น ย่อมเกิดเป็นสัญญาขึ้นแต่เวลาเมื่อคำบอกกล่าวสนองไปถึงผู้เสนอ ถ้าตามเจตนาอันผู้เสนอได้แสดง หรือตามปกติประเพณีไม่จำเป็นจะต้องมีคำบอกกล่าวสนองไซร้ ท่านว่าสัญญานั้นเกิดเป็นสัญญาขึ้นในเวลาเมื่อมีการอันใดอันหนึ่งขึ้น อันจะพึงสันนิษฐานได้ว่าเป็นการแสดงเจตนาสนองรับ"}},{"id":"TH-H004-A362","no":362,"noLabel":{"th":"มาตรา 362"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๒ บุคคลออกโฆษณาให้คำมั่นว่าจะให้รางวัลแก่ผู้ซึ่งกระทำการอันใด ท่านว่าจำต้องให้รางวัลแก่บุคคลใด ๆ ผู้ได้กระทำการอันนั้น แม้ถึงมิใช่ว่าผู้นั้นจะได้กระทำเพราะเห็นแก่รางวัล"}},{"id":"TH-H004-A363","no":363,"noLabel":{"th":"มาตรา 363"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๓ ในกรณีที่กล่าวมาในมาตราก่อนนี้ เมื่อยังไม่มีใครทำการสำเร็จดังบ่งไว้นั้นอยู่ตราบใด ผู้ให้คำมั่นจะถอนคำมั่นของตนเสียโดยวิธีเดียวกับที่โฆษณานั้นก็ได้ เว้นแต่จะได้แสดงไว้ในโฆษณานั้นว่าจะไม่ถอน ถ้าคำมั่นนั้นไม่อาจจะถอนโดยวิธีดังกล่าวมาก่อน จะถอนโดยวิธีอื่นก็ได้ แต่ถ้าเช่นนั้นการถอนจะเป็นอันสมบูรณ์ใช้ได้เพียงเฉพาะต่อบุคคลที่รู้ ถ้าผู้ให้คำมั่นได้กำหนดระยะเวลาให้ด้วยเพื่อทำการอันบ่งนั้นไซร้ ท่านให้สันนิษฐานไว้ก่อนว่าผู้ให้คำมั่นได้สละสิทธิที่จะถอนคำมั่นนั้นเสียแล้ว"}},{"id":"TH-H004-A364","no":364,"noLabel":{"th":"มาตรา 364"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๔ ถ้าบุคคลหลายคนกระทำการอันบ่งไว้ในโฆษณา ท่านว่าเฉพาะแต่คนที่ทำได้ก่อนใครหมดเท่านั้นมีสิทธิจะได้รับรางวัล ถ้าบุคคลหลายคนกระทำการอันนั้นได้พร้อมกัน ท่านว่าแต่ละคนมีสิทธิจะได้รับรางวัลเป็นส่วนแบ่งเท่า ๆ กัน แต่ถ้ารางวัลนั้นมีสภาพแบ่งไม่ได้ก็ดี หรือถ้าตามข้อความแห่งคำมั่นนั้น บุคคลแต่คนเดียวจะพึงรับรางวัลก็ดี ท่านให้วินิจฉัยด้วยวิธีจับสลาก บทบัญญัติดังกล่าวมาในวรรคทั้งสองข้างต้นนั้นท่านมิให้ใช้บังคับ ถ้าในโฆษณานั้นแสดงเจตนาไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A365","no":365,"noLabel":{"th":"มาตรา 365"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๕ คำมั่นจะให้รางวัลอันมีความประสงค์เป็นการประกวดชิงรางวัลนั้น จะสมบูรณ์ก็ต่อเมื่อได้กำหนดระยะเวลาไว้ในคำโฆษณาด้วย การที่จะตัดสินว่าผู้ประกวดคนไหนได้กระทำสำเร็จตามเงื่อนไขในคำมั่นภายในเวลากำหนดหรือไม่ก็ดี หรือตัดสินในระหว่างผู้ประกวดหลายคนนั้นว่าคนไหนดีกว่ากันอย่างไรก็ดี ให้ผู้ชี้ขาดซึ่งได้ระบุชื่อไว้ในโฆษณานั้นเป็นผู้ตัดสิน หรือถ้ามิได้ระบุชื่อผู้ชี้ขาดไว้ ก็ให้ผู้ให้คำมั่นเป็นผู้ตัดสิน คำตัดสินอันนี้ย่อมผูกพันผู้ที่เกี่ยวข้องด้วยทุกฝ่าย ถ้าได้คะแนนทำดีเสมอกัน ท่านให้นำบทบัญญัติแห่งมาตรา ๓๖๔ วรรคสอง มาใช้บังคับ แล้วแต่กรณี การโอนกรรมสิทธิ์ในทรัพย์ที่ทำขึ้นประกวดนั้น ผู้ให้คำมั่นจะเรียกให้โอนแก่ตนได้ต่อเมื่อได้ระบุไว้ในโฆษณาว่าจะพึงโอนเช่นนั้น"}},{"id":"TH-H004-A366","no":366,"noLabel":{"th":"มาตรา 366"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๖ ข้อความใด ๆ แห่งสัญญาอันคู่สัญญาแม้เพียงฝ่ายเดียวได้แสดงไว้ว่าเป็นสาระสำคัญอันจะต้องตกลงกันหมดทุกข้อนั้น หากคู่สัญญายังไม่ตกลงกันได้หมดทุกข้ออยู่ตราบใด เมื่อกรณีเป็นที่สงสัย ท่านนับว่ายังมิได้มีสัญญาต่อกัน การที่ได้ทำความเข้าใจกันไว้เฉพาะบางสิ่งบางอย่าง ถึงแม้ว่าจะได้จดลงไว้ก็หาเป็นการผูกพันไม่ ถ้าได้ตกลงกันว่าสัญญาอันมุ่งจะทำนั้นจะต้องทำเป็นหนังสือไซร้ เมื่อกรณีเป็นที่สงสัย ท่านนับว่ายังมิได้มีสัญญาต่อกันจนกว่าจะได้ทำขึ้นเป็นหนังสือ"}},{"id":"TH-H004-A367","no":367,"noLabel":{"th":"มาตรา 367"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๗ สัญญาใดคู่สัญญาได้ถือว่าเป็นอันได้ทำกันขึ้นแล้ว แต่แท้จริงยังมิได้ตกลงกันในข้อหนึ่งข้อใดอันจะต้องทำความตกลงให้สำเร็จ ถ้าจะพึงอนุมานได้ว่า ถึงหากจะไม่ทำความตกลงกันในข้อนี้ได้ สัญญานั้นก็จะได้ทำขึ้นไซร้ ท่านว่าข้อความส่วนที่ได้ตกลงกันแล้วก็ย่อมเป็นอันสมบูรณ์"}},{"id":"TH-H004-A368","no":368,"noLabel":{"th":"มาตรา 368"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๓๖๘ สัญญานั้นท่านให้ตีความไปตามความประสงค์ในทางสุจริต โดยพิเคราะห์ถึงปกติประเพณีด้วย"}},{"id":"TH-H004-A369","no":369,"noLabel":{"th":"มาตรา 369"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๖๙ ในสัญญาต่างตอบแทนนั้น คู่สัญญาฝ่ายหนึ่งจะไม่ยอมชำระหนี้จนกว่าอีกฝ่ายหนึ่งจะชำระหนี้หรือขอปฏิบัติการชำระหนี้ก็ได้ แต่ความข้อนี้ท่านมิให้ใช้บังคับ ถ้าหนี้ของคู่สัญญาอีกฝ่ายหนึ่งยังไม่ถึงกำหนด"}},{"id":"TH-H004-A370","no":370,"noLabel":{"th":"มาตรา 370"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๐ ถ้าสัญญาต่างตอบแทนมีวัตถุที่ประสงค์เป็นการก่อให้เกิดหรือโอนทรัพยสิทธิในทรัพย์เฉพาะสิ่ง และทรัพย์นั้นสูญหรือเสียหายไปด้วยเหตุอย่างใดอย่างหนึ่งอันจะโทษลูกหนี้มิได้ไซร้ ท่านว่าการสูญหรือเสียหายนั้นตกเป็นพับแก่เจ้าหนี้ ถ้าไม่ใช่ทรัพย์เฉพาะสิ่ง ท่านให้ใช้บทบัญญัติที่กล่าวมาในวรรคก่อนนี้บังคับแต่เวลาที่ทรัพย์นั้นกลายเป็นทรัพย์เฉพาะสิ่งตามบทบัญญัติแห่งมาตรา ๑๙๕ วรรคสอง นั้นไป"}},{"id":"TH-H004-A371","no":371,"noLabel":{"th":"มาตรา 371"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๑ บทบัญญัติที่กล่าวมาในมาตราก่อนนี้ท่านมิให้ใช้บังคับ ถ้าเป็นสัญญาต่างตอบแทนมีเงื่อนไขบังคับก่อน และทรัพย์อันเป็นวัตถุแห่งสัญญานั้นสูญหรือทำลายลงในระหว่างที่เงื่อนไขยังไม่สำเร็จ ถ้าทรัพย์นั้นเสียหายเพราะเหตุอย่างใดอย่างหนึ่งอันจะโทษเจ้าหนี้มิได้ และเมื่อเงื่อนไขนั้นสำเร็จแล้ว เจ้าหนี้จะเรียกให้ชำระหนี้โดยลดส่วนอันตนจะต้องชำระหนี้ตอบแทนนั้นลงหรือเลิกสัญญานั้นเสียก็ได้ แล้วแต่จะเลือก แต่ในกรณีที่ต้นเหตุเสียหายเกิดเพราะฝ่ายลูกหนี้นั้น ท่านว่าหากระทบกระทั่งถึงสิทธิของเจ้าหนี้ที่จะเรียกค่าสินไหมทดแทนไม่"}},{"id":"TH-H004-A372","no":372,"noLabel":{"th":"มาตรา 372"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๒ นอกจากกรณีที่กล่าวไว้ในสองมาตราก่อน ถ้าการชำระหนี้ตกเป็นพ้นวิสัยเพราะเหตุอย่างใดอย่างหนึ่งอันจะโทษฝ่ายหนึ่งฝ่ายใดก็ไม่ได้ไซร้ ท่านว่าลูกหนี้หามีสิทธิจะรับชำระหนี้ตอบแทนไม่ ถ้าการชำระหนี้ตกเป็นพ้นวิสัยเพราะเหตุอย่างใดอย่างหนึ่งอันจะโทษเจ้าหนี้ได้ ลูกหนี้ก็หาเสียสิทธิที่จะรับชำระหนี้ตอบแทนไม่ แต่ว่าลูกหนี้ได้อะไรไว้เพราะการปลดหนี้ก็ดี หรือใช้คุณวุฒิความสามารถของตนเป็นประการอื่นเป็นเหตุให้ได้อะไรมา หรือแกล้งละเลยเสียไม่ขวนขวายเอาอะไรที่สามารถจะทำได้ก็ดี มากน้อยเท่าไร จะต้องเอามาหักกับจำนวนอันตนจะได้รับชำระหนี้ตอบแทน วิธีเดียวกันนี้ท่านให้ใช้ตลอดถึงกรณีที่การชำระหนี้อันฝ่ายหนึ่งยังค้างชำระอยู่นั้นตกเป็นพ้นวิสัย เพราะพฤติการณ์อันใดอันหนึ่งซึ่งฝ่ายนั้นมิต้องรับผิดชอบ ในเวลาเมื่ออีกฝ่ายหนึ่งผิดนัดไม่รับชำระหนี้"}},{"id":"TH-H004-A373","no":373,"noLabel":{"th":"มาตรา 373"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๓ ความตกลงทำไว้ล่วงหน้าเป็นข้อความยกเว้นมิให้ลูกหนี้ต้องรับผิดเพื่อกลฉ้อฉลหรือความประมาทเลินเล่ออย่างร้ายแรงของตนนั้น ท่านว่าเป็นโมฆะ"}},{"id":"TH-H004-A374","no":374,"noLabel":{"th":"มาตรา 374"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๔ ถ้าคู่สัญญาฝ่ายหนึ่งทำสัญญาตกลงว่าจะชำระหนี้แก่บุคคลภายนอกไซร้ ท่านว่าบุคคลภายนอกมีสิทธิจะเรียกชำระหนี้จากลูกหนี้โดยตรงได้ ในกรณีดังกล่าวมาในวรรคต้นนั้น สิทธิของบุคคลภายนอกย่อมเกิดมีขึ้นตั้งแต่เวลาที่แสดงเจตนาแก่ลูกหนี้ว่าจะถือเอาประโยชน์จากสัญญานั้น"}},{"id":"TH-H004-A375","no":375,"noLabel":{"th":"มาตรา 375"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๕ เมื่อสิทธิของบุคคลภายนอกได้เกิดมีขึ้นตามบทบัญญัติแห่งมาตราก่อนแล้ว คู่สัญญาหาอาจจะเปลี่ยนแปลงหรือระงับสิทธินั้นในภายหลังได้ไม่"}},{"id":"TH-H004-A376","no":376,"noLabel":{"th":"มาตรา 376"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๓๗๖ ข้อต่อสู้อันเกิดแต่มูลสัญญาดังกล่าวมาในมาตรา ๓๗๔ นั้น ลูกหนี้อาจจะยกขึ้นต่อสู้บุคคลภายนอกผู้จะได้รับประโยชน์จากสัญญานั้นได้"}},{"id":"TH-H004-A377","no":377,"noLabel":{"th":"มาตรา 377"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๗๗ เมื่อเข้าทำสัญญา ถ้าได้ให้สิ่งใดไว้เป็นมัดจำ ท่านให้ถือว่าการที่ให้มัดจำนั้นย่อมเป็นพยานหลักฐานว่าสัญญานั้นได้ทำกันขึ้นแล้ว อนึ่ง มัดจำนี้ย่อมเป็นประกันการที่จะปฏิบัติตามสัญญานั้นด้วย"}},{"id":"TH-H004-A378","no":378,"noLabel":{"th":"มาตรา 378"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๗๘ มัดจำนั้น ถ้ามิได้ตกลงกันไว้เป็นอย่างอื่น ท่านให้เป็นไปดังจะกล่าวต่อไปนี้ คือ (๑) ให้ส่งคืน หรือจัดเอาเป็นการใช้เงินบางส่วนในเมื่อชำระหนี้ (๒) ให้ริบ ถ้าฝ่ายที่วางมัดจำละเลยไม่ชำระหนี้ หรือการชำระหนี้ตกเป็นพ้นวิสัยเพราะพฤติการณ์อันใดอันหนึ่งซึ่งฝ่ายนั้นต้องรับผิดชอบ หรือถ้ามีการเลิกสัญญาเพราะความผิดของฝ่ายนั้น (๓) ให้ส่งคืน ถ้าฝ่ายที่รับมัดจำละเลยไม่ชำระหนี้ หรือการชำระหนี้ตกเป็นพ้นวิสัยเพราะพฤติการณ์อันใดอันหนึ่งซึ่งฝ่ายนี้ต้องรับผิดชอบ"}},{"id":"TH-H004-A379","no":379,"noLabel":{"th":"มาตรา 379"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๗๙ ถ้าลูกหนี้สัญญาแก่เจ้าหนี้ว่าจะใช้เงินจำนวนหนึ่งเป็นเบี้ยปรับเมื่อตนไม่ชำระหนี้ก็ดี หรือไม่ชำระหนี้ให้ถูกต้องสมควรก็ดี เมื่อลูกหนี้ผิดนัด ก็ให้ริบเบี้ยปรับ ถ้าการชำระหนี้อันจะพึงทำนั้นได้แก่งดเว้นการอันใดอันหนึ่ง หากทำการอันนั้นฝ่าฝืนมูลหนี้เมื่อใด ก็ให้ริบเบี้ยปรับเมื่อนั้น"}},{"id":"TH-H004-A380","no":380,"noLabel":{"th":"มาตรา 380"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๐ ถ้าลูกหนี้ได้สัญญาไว้ว่าจะให้เบี้ยปรับเมื่อตนไม่ชำระหนี้ เจ้าหนี้จะเรียกเอาเบี้ยปรับอันจะพึงริบนั้นแทนการชำระหนี้ก็ได้ แต่ถ้าเจ้าหนี้แสดงต่อลูกหนี้ว่าจะเรียกเอาเบี้ยปรับฉะนั้นแล้ว ก็เป็นอันขาดสิทธิเรียกร้องชำระหนี้อีกต่อไป ถ้าเจ้าหนี้มีสิทธิเรียกร้องค่าสินไหมทดแทนเพื่อการไม่ชำระหนี้ จะเรียกเอาเบี้ยปรับอันจะพึงริบนั้นในฐานเป็นจำนวนน้อยที่สุดแห่งค่าเสียหายก็ได้ การพิสูจน์ค่าเสียหายยิ่งกว่านั้น ท่านก็อนุญาตให้พิสูจน์ได้"}},{"id":"TH-H004-A381","no":381,"noLabel":{"th":"มาตรา 381"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๑ ถ้าลูกหนี้ได้สัญญาไว้ว่าจะให้เบี้ยปรับเมื่อตนไม่ชำระหนี้ให้ถูกต้องสมควร เช่นว่าไม่ชำระหนี้ตรงตามเวลาที่กำหนดไว้เป็นต้น นอกจากเรียกให้ชำระหนี้ เจ้าหนี้จะเรียกเอาเบี้ยปรับอันจะพึงริบนั้นอีกด้วยก็ได้ ถ้าเจ้าหนี้มีสิทธิเรียกร้องค่าสินไหมทดแทนในมูลชำระหนี้ไม่ถูกต้องสมควร ท่านให้บังคับตามบทบัญญัติแห่งมาตรา ๓๘๐ วรรคสอง ถ้าเจ้าหนี้ยอมรับชำระหนี้แล้ว จะเรียกเอาเบี้ยปรับได้ต่อเมื่อได้บอกสงวนสิทธิไว้เช่นนั้นในเวลารับชำระหนี้"}},{"id":"TH-H004-A382","no":382,"noLabel":{"th":"มาตรา 382"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๒ ถ้าสัญญาว่าจะทำการชำระหนี้อย่างอื่นให้เป็นเบี้ยปรับ ไม่ใช่ใช้เป็นจำนวนเงินไซร้ ท่านให้นำบทบัญญัติแห่งมาตรา ๓๗๙ ถึงมาตรา ๓๘๑ มาใช้บังคับ แต่ถ้าเจ้าหนี้เรียกเอาเบี้ยปรับแล้ว สิทธิเรียกร้องค่าสินไหมทดแทนก็เป็นอันขาดไป"}},{"id":"TH-H004-A383","no":383,"noLabel":{"th":"มาตรา 383"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๓ ถ้าเบี้ยปรับที่ริบนั้นสูงเกินส่วน ศาลจะลดลงเป็นจำนวนพอสมควรก็ได้ ในการที่จะวินิจฉัยว่าสมควรเพียงใดนั้น ท่านให้พิเคราะห์ถึงทางได้เสียของเจ้าหนี้ทุกอย่างอันชอบด้วยกฎหมาย ไม่ใช่แต่เพียงทางได้เสียในเชิงทรัพย์สิน เมื่อได้ใช้เงินตามเบี้ยปรับแล้ว สิทธิเรียกร้องขอลดก็เป็นอันขาดไป นอกจากกรณีที่กล่าวไว้ในมาตรา ๓๗๙ และมาตรา ๓๘๒ ท่านให้ใช้วิธีเดียวกันนี้บังคับ ในเมื่อบุคคลสัญญาว่าจะให้เบี้ยปรับเมื่อตนกระทำหรืองดเว้นกระทำการอันหนึ่งอันใดนั้นด้วย"}},{"id":"TH-H004-A384","no":384,"noLabel":{"th":"มาตรา 384"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๔ ถ้าการชำระหนี้ตามที่สัญญาไว้นั้นไม่สมบูรณ์ การที่ตกลงกันด้วยข้อเบี้ยปรับในการไม่ปฏิบัติตามสัญญานั้นก็ย่อมไม่สมบูรณ์ดุจกัน แม้ถึงคู่กรณีจะได้รู้ว่าข้อสัญญานั้นไม่สมบูรณ์"}},{"id":"TH-H004-A385","no":385,"noLabel":{"th":"มาตรา 385"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๓๘๕ ถ้าลูกหนี้โต้แย้งการริบเบี้ยปรับโดยอ้างเหตุว่าตนได้ชำระหนี้แล้วไซร้ ท่านว่าลูกหนี้จะต้องพิสูจน์การชำระหนี้ เว้นแต่การชำระหนี้อันตนจะต้องทำนั้นเป็นการให้งดเว้นการอันใดอันหนึ่ง"}},{"id":"TH-H004-A386","no":386,"noLabel":{"th":"มาตรา 386"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๘๖ ถ้าคู่สัญญาฝ่ายหนึ่งมีสิทธิเลิกสัญญาโดยข้อสัญญาหรือโดยบทบัญญัติแห่งกฎหมาย การเลิกสัญญาเช่นนั้นย่อมทำด้วยแสดงเจตนาแก่อีกฝ่ายหนึ่ง แสดงเจตนาดังกล่าวมาในวรรคก่อนนั้น ท่านว่าหาอาจจะถอนได้ไม่"}},{"id":"TH-H004-A387","no":387,"noLabel":{"th":"มาตรา 387"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๘๗ ถ้าคู่สัญญาฝ่ายหนึ่งไม่ชำระหนี้ อีกฝ่ายหนึ่งจะกำหนดระยะเวลาพอสมควร แล้วบอกกล่าวให้ฝ่ายนั้นชำระหนี้ภายในระยะเวลานั้นก็ได้ ถ้าและฝ่ายนั้นไม่ชำระหนี้ภายในระยะเวลาที่กำหนดให้ไซร้ อีกฝ่ายหนึ่งจะเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A388","no":388,"noLabel":{"th":"มาตรา 388"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๘๘ ถ้าวัตถุที่ประสงค์แห่งสัญญานั้น ว่าโดยสภาพหรือโดยเจตนาที่คู่สัญญาได้แสดงไว้ จะเป็นผลสำเร็จได้ก็แต่ด้วยการชำระหนี้ ณ เวลามีกำหนดก็ดี หรือภายในระยะเวลาอันใดอันหนึ่งซึ่งกำหนดไว้ก็ดี และกำหนดเวลาหรือระยะเวลานั้นได้ล่วงพ้นไปโดยฝ่ายใดฝ่ายหนึ่งมิได้ชำระหนี้ไซร้ ท่านว่าอีกฝ่ายหนึ่งจะเลิกสัญญานั้นเสียก็ได้ มิพักต้องบอกกล่าวดังว่าไว้ในมาตราก่อนนั้นเลย"}},{"id":"TH-H004-A389","no":389,"noLabel":{"th":"มาตรา 389"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๘๙ ถ้าการชำระหนี้ทั้งหมดหรือแต่บางส่วนกลายเป็นพ้นวิสัยเพราะเหตุอย่างใดอย่างหนึ่งอันจะโทษลูกหนี้ได้ไซร้ เจ้าหนี้จะเลิกสัญญานั้นเสียก็ได้"}},{"id":"TH-H004-A390","no":390,"noLabel":{"th":"มาตรา 390"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๙๐ ถ้าในสัญญาใดคู่สัญญาเป็นบุคคลหลายคนด้วยกันอยู่ข้างหนึ่งหรืออีกข้างหนึ่ง ท่านว่าจะใช้สิทธิเลิกสัญญาได้ก็แต่เมื่อบุคคลเหล่านั้นทั้งหมดรวมกันใช้ ทั้งใช้ต่อบุคคลเหล่านั้นรวมหมดทุกคนด้วย ถ้าสิทธิเลิกสัญญาอันมีแก่บุคคลคนหนึ่งในจำพวกที่มีสิทธินั้นเป็นอันระงับสิ้นไปแล้ว สิทธิเลิกสัญญาอันมีแก่คนอื่น ๆ ก็ย่อมระงับสิ้นไปด้วย"}},{"id":"TH-H004-A391","no":391,"noLabel":{"th":"มาตรา 391"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๙๑ เมื่อคู่สัญญาฝ่ายหนึ่งได้ใช้สิทธิเลิกสัญญาแล้ว คู่สัญญาแต่ละฝ่ายจำต้องให้อีกฝ่ายหนึ่งได้กลับคืนสู่ฐานะดังที่เป็นอยู่เดิม แต่ทั้งนี้จะให้เป็นที่เสื่อมเสียแก่สิทธิของบุคคลภายนอกหาได้ไม่ ส่วนเงินอันจะต้องใช้คืนในกรณีดังกล่าวมาในวรรคต้นนั้น ท่านให้บวกดอกเบี้ยเข้าด้วย คิดตั้งแต่เวลาที่ได้รับไว้ ส่วนที่เป็นการงานอันได้กระทำให้และเป็นการยอมให้ใช้ทรัพย์นั้น การที่จะชดใช้คืน ท่านให้ทำได้ด้วยใช้เงินตามควรค่าแห่งการนั้น ๆ หรือถ้าในสัญญามีกำหนดว่าให้ใช้เงินตอบแทน ก็ให้ใช้ตามนั้น การใช้สิทธิเลิกสัญญานั้นหากระทบกระทั่งถึงสิทธิเรียกร้องค่าเสียหายไม่"}},{"id":"TH-H004-A392","no":392,"noLabel":{"th":"มาตรา 392"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๙๒ การชำระหนี้ของคู่สัญญาอันเกิดแต่การเลิกสัญญานั้น ให้เป็นไปตามบทบัญญัติแห่งมาตรา ๓๖๙"}},{"id":"TH-H004-A393","no":393,"noLabel":{"th":"มาตรา 393"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๙๓ ถ้ามิได้กำหนดระยะเวลาไว้ให้ใช้สิทธิเลิกสัญญา คู่สัญญาอีกฝ่ายหนึ่งจะกำหนดระยะเวลาพอสมควรแล้วบอกกล่าวให้ฝ่ายที่มีสิทธิเลิกสัญญานั้นแถลงให้ทราบภายในระยะเวลานั้นก็ได้ ว่าจะเลิกสัญญาหรือหาไม่ ถ้ามิได้รับคำบอกกล่าวเลิกสัญญาภายในระยะเวลานั้น สิทธิเลิกสัญญาก็เป็นอันระงับสิ้นไป"}},{"id":"TH-H004-A394","no":394,"noLabel":{"th":"มาตรา 394"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๓๙๔ ถ้าทรัพย์อันเป็นวัตถุแห่งสัญญานั้นบุบสลายไปในส่วนสำคัญเพราะการกระทำหรือเพราะความผิดของบุคคลผู้มีสิทธิเลิกสัญญาก็ดี หรือบุคคลนั้นได้ทำให้การคืนทรัพย์กลายเป็นพ้นวิสัยก็ดี เปลี่ยนแปลงทรัพย์นั้นให้ผิดแผกไปเป็นอย่างอื่นด้วยประกอบขึ้นหรือดัดแปลงก็ดี ท่านว่าสิทธิเลิกสัญญานั้นก็เป็นอันระงับสิ้นไป แต่ถ้าทรัพย์อันเป็นวัตถุแห่งสัญญาได้สูญหายหรือบุบสลายไปโดยปราศจากการกระทำหรือความผิดของบุคคลผู้มีสิทธิเลิกสัญญาไซร้ สิทธิเลิกสัญญานั้นก็หาระงับสิ้นไปไม่"}},{"id":"TH-H004-A395","no":395,"noLabel":{"th":"มาตรา 395"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๓๙๕ บุคคลใดเข้าทำกิจการแทนผู้อื่นโดยเขามิได้ว่าขานวานใช้ให้ทำก็ดี หรือโดยมิได้มีสิทธิที่จะทำการงานนั้นแทนผู้อื่นด้วยประการใดก็ดี ท่านว่าบุคคลนั้นจะต้องจัดการงานไปในทางที่จะให้สมประโยชน์ของตัวการ ตามความประสงค์อันแท้จริงของตัวการ หรือตามที่จะพึงสันนิษฐานได้ว่าเป็นความประสงค์ของตัวการ"}},{"id":"TH-H004-A396","no":396,"noLabel":{"th":"มาตรา 396"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๓๙๖ ถ้าการที่เข้าจัดการงานนั้นเป็นการขัดกับความประสงค์อันแท้จริงของตัวการก็ดี หรือขัดกับความประสงค์ตามที่จะพึงสันนิษฐานได้ก็ดี และผู้จัดการก็ควรจะได้รู้สึกเช่นนั้นแล้วด้วยไซร้ ท่านว่าผู้จัดการจำต้องใช้ค่าสินไหมทดแทนให้แก่ตัวการเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่ที่ได้เข้าจัดการนั้น แม้ทั้งผู้จัดการจะมิได้มีความผิดประการอื่น"}},{"id":"TH-H004-A397","no":397,"noLabel":{"th":"มาตรา 397"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๓๙๗ ถ้าผู้จัดการทำกิจอันใดซึ่งเป็นหน้าที่บังคับให้ตัวการทำเพื่อสาธารณประโยชน์ก็ดี หรือเป็นหน้าที่ตามกฎหมายที่จะบำรุงรักษาผู้อื่นก็ดี และหากผู้จัดการมิได้เข้าทำแล้ว กิจอันนั้นจะไม่สำเร็จภายในเวลาอันควรไซร้ การที่ได้ทำขัดกับความประสงค์ของตัวการเช่นนั้นท่านมิให้ยกขึ้นเป็นข้อวินิจฉัย"}},{"id":"TH-H004-A398","no":398,"noLabel":{"th":"มาตรา 398"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๓๙๘ ถ้าผู้จัดการทำกิจอันใดเพื่อประสงค์จะปัดป้องอันตรายอันมีมาใกล้ตัวการ จะเป็นภัยแก่ตัวก็ดี แก่ชื่อเสียงก็ดี หรือแก่ทรัพย์สินก็ดี ท่านว่าผู้จัดการต้องรับผิดชอบแต่เพียงที่จงใจทำผิด หรือที่เป็นความประมาทเลินเล่ออย่างร้ายแรงเท่านั้น"}},{"id":"TH-H004-A399","no":399,"noLabel":{"th":"มาตรา 399"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๓๙๙ ผู้จัดการต้องบอกกล่าวแก่ตัวการโดยเร็วที่สุดที่จะทำได้ว่าตนได้เข้าจัดการงานแทน และต้องรอฟังคำวินิจฉัยของตัวการ เว้นแต่ภัยจะมีขึ้นเพราะการที่หน่วงเนิ่นไว้ นอกจากนี้ท่านให้นำบทบัญญัติแห่งมาตรา ๘๐๙ ถึงมาตรา ๘๑๑ อันบังคับแก่ตัวแทนนั้นมาใช้บังคับแก่หน้าที่ของผู้จัดการด้วย โดยอนุโลม"}},{"id":"TH-H004-A400","no":400,"noLabel":{"th":"มาตรา 400"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๐ ถ้าผู้จัดการเป็นผู้ไร้ความสามารถ ท่านว่าจะต้องรับผิดชอบแต่เพียงตามบทบัญญัติว่าด้วยค่าสินไหมทดแทนเพื่อละเมิด และว่าด้วยการคืนลาภมิควรได้เท่านั้น"}},{"id":"TH-H004-A401","no":401,"noLabel":{"th":"มาตรา 401"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๑ ถ้าการที่เข้าจัดการงานนั้นเป็นการสมประโยชน์ของตัวการ และต้องตามความประสงค์อันแท้จริงของตัวการหรือความประสงค์ตามที่จะพึงสันนิษฐานได้นั้นไซร้ ท่านว่าผู้จัดการจะเรียกให้ชดใช้เงินอันตนได้ออกไปคืนแก่ตนเช่นอย่างตัวแทนก็ได้ และบทบัญญัติมาตรา ๘๑๖ วรรคสอง นั้น ท่านก็ให้นำมาใช้บังคับด้วย โดยอนุโลม อนึ่ง ในกรณีที่กล่าวมาในมาตรา ๓๙๗ นั้น แม้ถึงว่าที่เข้าจัดการงานนั้นจะเป็นการขัดกับความประสงค์ของตัวการก็ดี ผู้จัดการก็ยังคงมีสิทธิเรียกร้องเช่นนั้นอยู่"}},{"id":"TH-H004-A402","no":402,"noLabel":{"th":"มาตรา 402"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๒ ถ้าเงื่อนไขดังว่ามาในมาตราก่อนนั้นมิได้มี ท่านว่าตัวการจำต้องคืนสิ่งทั้งหลายบรรดาที่ได้มาเพราะเขาเข้าจัดการงานนั้นให้แก่ผู้จัดการ ตามบทบัญญัติว่าด้วยการคืนลาภมิควรได้ ถ้าตัวการให้สัตยาบันแก่การที่จัดทำนั้น ท่านให้นำบทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้ว่าด้วยตัวแทนมาใช้บังคับ แล้วแต่กรณี"}},{"id":"TH-H004-A403","no":403,"noLabel":{"th":"มาตรา 403"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๓ ถ้าผู้จัดการมิได้มีบุรพเจตนาจะเรียกให้ตัวการชดใช้คืน ผู้จัดการก็ย่อมไม่มีสิทธิเรียกร้องเช่นนั้น การที่บิดามารดา ปู่ ย่า ตา ยาย บำรุงรักษาผู้สืบสันดานเป็นทางอุปการะก็ดี หรือกลับกันเป็นทางปฏิการะก็ดี เมื่อกรณีเป็นที่สงสัย ท่านให้สันนิษฐานไว้ก่อนว่าไม่มีเจตนาจะเรียกให้ผู้รับประโยชน์ชดใช้คืน"}},{"id":"TH-H004-A404","no":404,"noLabel":{"th":"มาตรา 404"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๔ ถ้าผู้จัดการทำแทนผู้หนึ่งโดยสำคัญว่าทำแทนผู้อื่นอีกคนหนึ่งไซร้ ท่านว่าผู้เป็นตัวการคนก่อนผู้เดียวมีสิทธิและหน้าที่อันเกิดแต่การที่ได้จัดทำไปนั้น"}},{"id":"TH-H004-A405","no":405,"noLabel":{"th":"มาตรา 405"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๔๐๕ บทบัญญัติทั้งหลายที่กล่าวมาในสิบมาตราก่อนนั้น ท่านมิให้ใช้บังคับแก่กรณีที่บุคคลคนหนึ่งเข้าทำการงานของผู้อื่นโดยสำคัญว่าเป็นการงานของตนเอง ถ้าบุคคลใดถือเอากิจการของผู้อื่นว่าเป็นของตนเองทั้งที่รู้แล้วว่าตนไม่มีสิทธิจะทำเช่นนั้นไซร้ ท่านว่าตัวการจะใช้สิทธิเรียกร้องบังคับโดยมูลดังบัญญัติไว้ในมาตรา ๓๙๕ มาตรา ๓๙๖ มาตรา ๓๙๙ และมาตรา ๔๐๐ นั้นก็ได้ แต่เมื่อได้ใช้สิทธิดังว่ามานี้แล้ว ตัวการจะต้องรับผิดต่อผู้จัดการดังบัญญัติไว้ในมาตรา ๔๐๒ วรรคหนึ่ง"}},{"id":"TH-H004-A406","no":406,"noLabel":{"th":"มาตรา 406"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๐๖ บุคคลใดได้มาซึ่งทรัพย์สิ่งใดเพราะการที่บุคคลอีกคนหนึ่งกระทำเพื่อชำระหนี้ก็ดี หรือได้มาด้วยประการอื่นก็ดี โดยปราศจากมูลอันจะอ้างกฎหมายได้ และเป็นทางให้บุคคลอีกคนหนึ่งนั้นเสียเปรียบไซร้ ท่านว่าบุคคลนั้นจำต้องคืนทรัพย์ให้แก่เขา อนึ่ง การรับสภาพหนี้สินว่ามีอยู่หรือหาไม่นั้น ท่านก็ให้ถือว่าเป็นการกระทำเพื่อชำระหนี้ด้วย บทบัญญัติอันนี้ท่านให้ใช้บังคับตลอดถึงกรณีที่ได้ทรัพย์มาเพราะเหตุอย่างใดอย่างหนึ่งซึ่งมิได้มีได้เป็นขึ้น หรือเป็นเหตุที่ได้สิ้นสุดไปเสียก่อนแล้วนั้นด้วย"}},{"id":"TH-H004-A407","no":407,"noLabel":{"th":"มาตรา 407"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๐๗ บุคคลใดได้กระทำการอันใดตามอำเภอใจเหมือนหนึ่งว่าเพื่อชำระหนี้โดยรู้อยู่ว่าตนไม่มีความผูกพันที่จะต้องชำระ ท่านว่าบุคคลผู้นั้นหามีสิทธิจะได้รับคืนทรัพย์ไม่"}},{"id":"TH-H004-A408","no":408,"noLabel":{"th":"มาตรา 408"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๐๘ บุคคลดังจะกล่าวต่อไปนี้ไม่มีสิทธิจะได้รับคืนทรัพย์ คือ (๑) บุคคลผู้ชำระหนี้อันมีเงื่อนเวลาบังคับเมื่อก่อนถึงกำหนดเวลานั้น (๒) บุคคลผู้ชำระหนี้ซึ่งขาดอายุความแล้ว (๓) บุคคลผู้ชำระหนี้ตามหน้าที่ศีลธรรม หรือตามควรแก่อัธยาศัยในสมาคม"}},{"id":"TH-H004-A409","no":409,"noLabel":{"th":"มาตรา 409"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๐๙ เมื่อบุคคลผู้หนึ่งผู้ใดซึ่งมิได้เป็นลูกหนี้ได้ชำระหนี้ไปโดยสำคัญผิด เป็นเหตุให้เจ้าหนี้ผู้ทำการโดยสุจริตได้ทำลาย หรือลบล้างเสียซึ่งเอกสารอันเป็นพยานหลักฐานแห่งหนี้ก็ดี ยกเลิกหลักประกันเสียก็ดี สิ้นสิทธิไปเพราะขาดอายุความก็ดี ท่านว่าเจ้าหนี้ไม่จำต้องคืนทรัพย์ บทบัญญัติที่กล่าวมาในวรรคก่อนนี้ไม่ขัดขวางต่อการที่บุคคลผู้ได้ชำระหนี้นั้นจะใช้สิทธิไล่เบี้ยเอาแก่ลูกหนี้และผู้ค้ำประกัน ถ้าจะพึงมี"}},{"id":"TH-H004-A410","no":410,"noLabel":{"th":"มาตรา 410"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๐ บุคคลผู้ใดได้ทำการชำระหนี้โดยมุ่งต่อผลอย่างหนึ่ง แต่มิได้เกิดผลขึ้นเช่นนั้น ถ้าและบุคคลนั้นได้รู้มาแต่แรกว่าการที่จะเกิดผลนั้นเป็นพ้นวิสัยก็ดี หรือได้เข้าป้องปัดขัดขวางเสียมิให้เกิดผลเช่นนั้นโดยอาการอันฝ่าฝืนความสุจริตก็ดี ท่านว่าบุคคลผู้นั้นไม่มีสิทธิจะได้รับคืนทรัพย์"}},{"id":"TH-H004-A411","no":411,"noLabel":{"th":"มาตรา 411"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๑ บุคคลใดได้กระทำการเพื่อชำระหนี้ เป็นการอันฝ่าฝืนข้อห้ามตามกฎหมายหรือศีลธรรมอันดี ท่านว่าบุคคลนั้นหาอาจจะเรียกร้องคืนทรัพย์ได้ไม่"}},{"id":"TH-H004-A412","no":412,"noLabel":{"th":"มาตรา 412"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๒ ถ้าทรัพย์สินซึ่งได้รับไว้เป็นลาภมิควรได้นั้นเป็นเงินจำนวนหนึ่ง ท่านว่าต้องคืนเต็มจำนวนนั้น เว้นแต่เมื่อบุคคลได้รับไว้โดยสุจริต จึงต้องคืนลาภมิควรได้เพียงส่วนที่ยังมีอยู่ในขณะเมื่อเรียกคืน"}},{"id":"TH-H004-A413","no":413,"noLabel":{"th":"มาตรา 413"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๓ เมื่อทรัพย์สินอันจะต้องคืนนั้นเป็นอย่างอื่นนอกจากจำนวนเงิน และบุคคลได้รับไว้โดยสุจริต ท่านว่าบุคคลเช่นนั้นจำต้องคืนทรัพย์สินเพียงตามสภาพที่เป็นอยู่ และมิต้องรับผิดชอบในการที่ทรัพย์นั้นสูญหายหรือบุบสลาย แต่ถ้าได้อะไรมาเป็นค่าสินไหมทดแทนเพื่อการสูญหายหรือบุบสลายเช่นนั้นก็ต้องให้ไปด้วย ถ้าบุคคลได้รับทรัพย์สินไว้โดยทุจริต ท่านว่าจะต้องรับผิดชอบในการสูญหายหรือบุบสลายนั้นเต็มภูมิ แม้กระทั่งการสูญหายหรือบุบสลายจะเกิดเพราะเหตุสุดวิสัย เว้นแต่จะพิสูจน์ได้ว่าถึงอย่างไรทรัพย์สินนั้นก็คงต้องสูญหายหรือบุบสลายอยู่นั่นเอง"}},{"id":"TH-H004-A414","no":414,"noLabel":{"th":"มาตรา 414"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๔ ถ้าการคืนทรัพย์ตกเป็นพ้นวิสัยเพราะสภาพแห่งทรัพย์สินที่ได้รับไว้นั้นเองก็ดี หรือเพราะเหตุอย่างอื่นก็ดี และบุคคลได้รับทรัพย์สินไว้โดยสุจริต ท่านว่าบุคคลเช่นนั้นจำต้องคืนลาภมิควรได้เพียงส่วนที่ยังมีอยู่ในขณะเมื่อเรียกคืน ถ้าบุคคลได้รับทรัพย์สินนั้นไว้โดยทุจริต ท่านว่าต้องใช้ราคาทรัพย์สินนั้นเต็มจำนวน"}},{"id":"TH-H004-A415","no":415,"noLabel":{"th":"มาตรา 415"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๕ บุคคลผู้ได้รับทรัพย์สินไว้โดยสุจริตย่อมจะได้ดอกผลอันเกิดแต่ทรัพย์สินนั้นตลอดเวลาที่ยังคงสุจริตอยู่ ถ้าผู้ที่ได้รับไว้จะต้องคืนทรัพย์สินนั้นเมื่อใด ให้ถือว่าผู้นั้นตกอยู่ในฐานะทุจริตจำเดิมแต่เวลาที่เรียกคืนนั้น"}},{"id":"TH-H004-A416","no":416,"noLabel":{"th":"มาตรา 416"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๖ ค่าใช้จ่ายทั้งหลายอันควรแก่การเพื่อรักษา บำรุงหรือซ่อมแซมทรัพย์สินนั้น ท่านว่าต้องชดใช้แก่บุคคลผู้คืนทรัพย์สินนั้นเต็มจำนวน แต่บุคคลเช่นว่านี้จะเรียกร้องให้ชดใช้ค่าใช้จ่ายตามธรรมดาเพื่อบำรุง ซ่อมแซมทรัพย์สินนั้น หรือค่าภาระติดพันที่ต้องเสียไปในระหว่างที่ตนคงเก็บดอกผลอยู่นั้นหาได้ไม่"}},{"id":"TH-H004-A417","no":417,"noLabel":{"th":"มาตรา 417"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๗ ในส่วนค่าใช้จ่ายอย่างอื่นนอกจากที่กล่าวมาในวรรคต้นแห่งมาตราก่อนนั้น บุคคลผู้คืนทรัพย์สินจะเรียกให้ชดใช้ได้แต่เฉพาะที่เสียไปในระหว่างที่ตนทำการโดยสุจริต และเมื่อทรัพย์สินนั้นได้มีราคาเพิ่มสูงขึ้นเพราะค่าใช้จ่ายนั้นในเวลาที่คืน และจะเรียกได้ก็แต่เพียงเท่าราคาที่เพิ่มขึ้นเท่านั้น อนึ่ง บทบัญญัติแห่งมาตรา ๔๑๕ วรรคสอง นั้น ท่านให้นำมาใช้บังคับด้วย แล้วแต่กรณี"}},{"id":"TH-H004-A418","no":418,"noLabel":{"th":"มาตรา 418"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๘ ถ้าบุคคลรับทรัพย์สินอันมิควรได้ไว้โดยทุจริต และได้ทำการดัดแปลงหรือต่อเติมขึ้นในทรัพย์สินนั้น ท่านว่าบุคคลเช่นนั้นต้องจัดทำทรัพย์สินนั้นให้คืนคงสภาพเดิมด้วยค่าใช้จ่ายของตนเองแล้วจึงส่งคืน เว้นแต่เจ้าของทรัพย์สินจะเลือกให้ส่งคืนตามสภาพที่เป็นอยู่ ในกรณีเช่นนี้เจ้าของจะใช้ราคาค่าทำดัดแปลงหรือต่อเติม หรือใช้เงินจำนวนหนึ่งเป็นราคาทรัพย์สินเท่าที่เพิ่มขึ้นนั้นก็ได้ แล้วแต่จะเลือก ถ้าในเวลาที่จะต้องคืนทรัพย์นั้นเป็นพ้นวิสัยจะทำให้ทรัพย์สินคืนคงสภาพเดิมได้ หรือถ้าทำไปทรัพย์สินนั้นจะบุบสลายไซร้ ท่านว่าบุคคลผู้ได้รับไว้จะต้องส่งคืนทรัพย์สินตามสภาพที่เป็นอยู่ และไม่มีสิทธิเรียกค่าสินไหมทดแทนเพื่อราคาทรัพย์สินที่เพิ่มขึ้นเพราะการดัดแปลงหรือต่อเติมนั้นได้"}},{"id":"TH-H004-A419","no":419,"noLabel":{"th":"มาตรา 419"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๔๑๙ ในเรื่องลาภมิควรได้นั้น ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นกำหนดปีหนึ่งนับแต่เวลาที่ฝ่ายผู้เสียหายรู้ว่าตนมีสิทธิเรียกคืน หรือเมื่อพ้นสิบปีนับแต่เวลาที่สิทธินั้นได้มีขึ้น"}},{"id":"TH-H004-A420","no":420,"noLabel":{"th":"มาตรา 420"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๐ ผู้ใดจงใจหรือประมาทเลินเล่อ ทำต่อบุคคลอื่นโดยผิดกฎหมายให้เขาเสียหายถึงแก่ชีวิตก็ดี แก่ร่างกายก็ดี อนามัยก็ดี เสรีภาพก็ดี ทรัพย์สินหรือสิทธิอย่างหนึ่งอย่างใดก็ดี ท่านว่าผู้นั้นทำละเมิดจำต้องใช้ค่าสินไหมทดแทนเพื่อการนั้น"}},{"id":"TH-H004-A421","no":421,"noLabel":{"th":"มาตรา 421"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๑ การใช้สิทธิซึ่งมีแต่จะให้เกิดเสียหายแก่บุคคลอื่นนั้น ท่านว่าเป็นการอันมิชอบด้วยกฎหมาย"}},{"id":"TH-H004-A422","no":422,"noLabel":{"th":"มาตรา 422"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๒ ถ้าความเสียหายเกิดแต่การฝ่าฝืนบทบังคับแห่งกฎหมายใดอันมีที่ประสงค์ เพื่อจะปกป้องบุคคลอื่น ๆ ผู้ใดทำการฝ่าฝืนเช่นนั้น ท่านให้สันนิษฐานไว้ก่อนว่าผู้นั้นเป็นผู้ผิด"}},{"id":"TH-H004-A423","no":423,"noLabel":{"th":"มาตรา 423"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๓ ผู้ใดกล่าวหรือไขข่าวแพร่หลายซึ่งข้อความอันฝ่าฝืนต่อความจริง เป็นที่เสียหายแก่ชื่อเสียงหรือเกียรติคุณของบุคคลอื่นก็ดี หรือเป็นที่เสียหายแก่ทางทำมาหาได้หรือทางเจริญของเขาโดยประการอื่นก็ดี ท่านว่าผู้นั้นจะต้องใช้ค่าสินไหมทดแทนให้แก่เขาเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่การนั้น แม้ทั้งเมื่อตนมิได้รู้ว่าข้อความนั้นไม่จริง แต่หากควรจะรู้ได้ ผู้ใดส่งข่าวสารอันตนมิได้รู้ว่าเป็นความไม่จริง หากว่าตนเองหรือผู้รับข่าวสารนั้นมีทางได้เสียโดยชอบในการนั้นด้วยแล้ว ท่านว่าเพียงที่ส่งข่าวสารเช่นนั้นหาทำให้ผู้นั้นต้องรับผิดใช้ค่าสินไหมทดแทนไม่"}},{"id":"TH-H004-A424","no":424,"noLabel":{"th":"มาตรา 424"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๔ ในการพิพากษาคดีข้อความรับผิดเพื่อละเมิดและกำหนดค่าสินไหมทดแทนนั้น ท่านว่าศาลไม่จำต้องดำเนินตามบทบัญญัติแห่งกฎหมายลักษณะอาญาอันว่าด้วยการที่จะต้องรับโทษ และไม่จำต้องพิเคราะห์ถึงการที่ผู้กระทำผิดต้องคำพิพากษาลงโทษทางอาญาหรือไม่"}},{"id":"TH-H004-A425","no":425,"noLabel":{"th":"มาตรา 425"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๕ นายจ้างต้องร่วมกันรับผิดกับลูกจ้างในผลแห่งละเมิดซึ่งลูกจ้างได้กระทำไปในทางการที่จ้างนั้น"}},{"id":"TH-H004-A426","no":426,"noLabel":{"th":"มาตรา 426"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๖ นายจ้างซึ่งได้ใช้ค่าสินไหมทดแทนให้แก่บุคคลภายนอกเพื่อละเมิดอันลูกจ้างได้ทำนั้น ชอบที่จะได้ชดใช้จากลูกจ้างนั้น"}},{"id":"TH-H004-A427","no":427,"noLabel":{"th":"มาตรา 427"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๗ บทบัญญัติในมาตราทั้งสองก่อนนั้น ท่านให้ใช้บังคับแก่ตัวการและตัวแทนด้วย โดยอนุโลม"}},{"id":"TH-H004-A428","no":428,"noLabel":{"th":"มาตรา 428"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๘ ผู้ว่าจ้างทำของไม่ต้องรับผิดเพื่อความเสียหายอันผู้รับจ้างได้ก่อให้เกิดขึ้นแก่บุคคลภายนอกในระหว่างทำการงานที่ว่าจ้าง เว้นแต่ผู้ว่าจ้างจะเป็นผู้ผิดในส่วนการงานที่สั่งให้ทำ หรือในคำสั่งที่ตนให้ไว้ หรือในการเลือกหาผู้รับจ้าง"}},{"id":"TH-H004-A429","no":429,"noLabel":{"th":"มาตรา 429"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๒๙ บุคคลใดแม้ไร้ความสามารถเพราะเหตุเป็นผู้เยาว์หรือวิกลจริตก็ยังต้องรับผิดในผลที่ตนทำละเมิด บิดามารดาหรือผู้อนุบาลของบุคคลเช่นว่านี้ย่อมต้องรับผิดร่วมกับเขาด้วย เว้นแต่จะพิสูจน์ได้ว่าตนได้ใช้ความระมัดระวังตามสมควรแก่หน้าที่ดูแลซึ่งทำอยู่นั้น"}},{"id":"TH-H004-A430","no":430,"noLabel":{"th":"มาตรา 430"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๐ ครูบาอาจารย์ นายจ้าง หรือบุคคลอื่นซึ่งรับดูแลบุคคลผู้ไร้ความสามารถอยู่เป็นนิตย์ก็ดี ชั่วครั้งคราวก็ดี จำต้องรับผิดร่วมกับผู้ไร้ความสามารถในการละเมิดซึ่งเขาได้กระทำลงในระหว่างที่อยู่ในความดูแลของตน ถ้าหากพิสูจน์ได้ว่าบุคคลนั้น ๆ มิได้ใช้ความระมัดระวังตามสมควร"}},{"id":"TH-H004-A431","no":431,"noLabel":{"th":"มาตรา 431"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๑ ในกรณีที่กล่าวมาในสองมาตราก่อนนั้น ท่านให้นำบทบัญญัติแห่งมาตรา ๔๒๖ มาใช้บังคับด้วย โดยอนุโลม"}},{"id":"TH-H004-A432","no":432,"noLabel":{"th":"มาตรา 432"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๒ ถ้าบุคคลหลายคนก่อให้เกิดเสียหายแก่บุคคลอื่นโดยร่วมกันทำละเมิด ท่านว่าบุคคลเหล่านั้นจะต้องร่วมกันรับผิดใช้ค่าสินไหมทดแทนเพื่อความเสียหายนั้น ความข้อนี้ท่านให้ใช้ตลอดถึงกรณีที่ไม่สามารถสืบรู้ตัวได้แน่ว่าในจำพวกที่ทำละเมิดร่วมกันนั้น คนไหนเป็นผู้ก่อให้เกิดเสียหายนั้นด้วย อนึ่ง บุคคลผู้ยุยงส่งเสริมหรือช่วยเหลือในการทำละเมิด ท่านก็ให้ถือว่าเป็นผู้กระทำละเมิดร่วมกันด้วย ในระหว่างบุคคลทั้งหลายซึ่งต้องรับผิดร่วมกันใช้ค่าสินไหมทดแทนนั้น ท่านว่าต่างต้องรับผิดเป็นส่วนเท่า ๆ กัน เว้นแต่โดยพฤติการณ์ ศาลจะวินิจฉัยเป็นประการอื่น"}},{"id":"TH-H004-A433","no":433,"noLabel":{"th":"มาตรา 433"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๓ ถ้าความเสียหายเกิดขึ้นเพราะสัตว์ ท่านว่าเจ้าของสัตว์หรือบุคคลผู้รับเลี้ยงรับรักษาไว้แทนเจ้าของจำต้องใช้ค่าสินไหมทดแทนให้แก่ฝ่ายที่ต้องเสียหายเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่สัตว์นั้น เว้นแต่จะพิสูจน์ได้ว่าตนได้ใช้ความระมัดระวังอันสมควรแก่การเลี้ยงการรักษาตามชนิดและวิสัยของสัตว์ หรือตามพฤติการณ์อย่างอื่น หรือพิสูจน์ได้ว่าความเสียหายนั้นย่อมจะต้องเกิดมีขึ้นทั้งที่ได้ใช้ความระมัดระวังถึงเพียงนั้น อนึ่ง บุคคลผู้ต้องรับผิดชอบดังกล่าวมาในวรรคต้นนั้น จะใช้สิทธิไล่เบี้ยเอาแก่บุคคลผู้ที่เร้าหรือยั่วสัตว์นั้นโดยละเมิด หรือเอาแก่เจ้าของสัตว์อื่นอันมาเร้าหรือยั่วสัตว์นั้น ๆ ก็ได้"}},{"id":"TH-H004-A434","no":434,"noLabel":{"th":"มาตรา 434"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๔ ถ้าความเสียหายเกิดขึ้นเพราะเหตุที่โรงเรือน หรือสิ่งปลูกสร้างอย่างอื่นก่อสร้างไว้ชำรุดบกพร่องก็ดี หรือบำรุงรักษาไม่เพียงพอก็ดี ท่านว่าผู้ครองโรงเรือนหรือสิ่งปลูกสร้างนั้น ๆ จำต้องใช้ค่าสินไหมทดแทน แต่ถ้าผู้ครองได้ใช้ความระมัดระวังตามสมควรเพื่อปัดป้องมิให้เกิดเสียหายฉะนั้นแล้ว ท่านว่าผู้เป็นเจ้าของจำต้องใช้ค่าสินไหมทดแทน บทบัญญัติที่กล่าวมาในวรรคก่อนนั้นให้ใช้บังคับได้ตลอดถึงความบกพร่องในการปลูกหรือค้ำจุนต้นไม้หรือกอไผ่ด้วย ในกรณีที่กล่าวมาในสองวรรคข้างต้นนั้น ถ้ายังมีผู้อื่นอีกที่ต้องรับผิดชอบในการก่อให้เกิดเสียหายนั้นด้วยไซร้ ท่านว่าผู้ครองหรือเจ้าของจะใช้สิทธิไล่เบี้ยเอาแก่ผู้นั้นก็ได้"}},{"id":"TH-H004-A435","no":435,"noLabel":{"th":"มาตรา 435"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๕ บุคคลใดจะประสบความเสียหายอันพึงเกิดจากโรงเรือนหรือสิ่งปลูกสร้างอย่างอื่นของผู้อื่น บุคคลผู้นั้นชอบที่จะเรียกให้จัดการตามที่จำเป็นเพื่อบำบัดปัดป้องภยันตรายนั้นเสียได้"}},{"id":"TH-H004-A436","no":436,"noLabel":{"th":"มาตรา 436"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๖ บุคคลผู้อยู่ในโรงเรือนต้องรับผิดชอบในความเสียหายอันเกิดเพราะของตกหล่นจากโรงเรือนนั้น หรือเพราะทิ้งขว้างของไปตกในที่อันมิควร"}},{"id":"TH-H004-A437","no":437,"noLabel":{"th":"มาตรา 437"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๔๓๗ บุคคลใดครอบครองหรือควบคุมดูแลยานพาหนะอย่างใด ๆ อันเดินด้วยกำลังเครื่องจักรกล บุคคลนั้นจะต้องรับผิดชอบเพื่อการเสียหายอันเกิดแต่ยานพาหนะนั้น เว้นแต่จะพิสูจน์ได้ว่าการเสียหายนั้นเกิดแต่เหตุสุดวิสัย หรือเกิดเพราะความผิดของผู้ต้องเสียหายนั้นเอง ความข้อนี้ให้ใช้บังคับได้ตลอดถึงบุคคลผู้มีไว้ในครอบครองของตนซึ่งทรัพย์อันเป็นของเกิดอันตรายได้โดยสภาพ หรือโดยความมุ่งหมายที่จะใช้ หรือโดยอาการกลไกของทรัพย์นั้นด้วย"}},{"id":"TH-H004-A438","no":438,"noLabel":{"th":"มาตรา 438"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๓๘ ค่าสินไหมทดแทนจะพึงใช้โดยสถานใดเพียงใดนั้น ให้ศาลวินิจฉัยตามควรแก่พฤติการณ์และความร้ายแรงแห่งละเมิด อนึ่ง ค่าสินไหมทดแทนนั้น ได้แก่การคืนทรัพย์สินอันผู้เสียหายต้องเสียไปเพราะละเมิด หรือใช้ราคาทรัพย์สินนั้น รวมทั้งค่าเสียหายอันจะพึงบังคับให้ใช้เพื่อความเสียหายอย่างใด ๆ อันได้ก่อขึ้นนั้นด้วย"}},{"id":"TH-H004-A439","no":439,"noLabel":{"th":"มาตรา 439"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๓๙ บุคคลผู้จำต้องคืนทรัพย์อันผู้อื่นต้องเสียไปเพราะละเมิดแห่งตนนั้น ยังต้องรับผิดชอบตลอดถึงการที่ทรัพย์นั้นทำลายลงโดยอุบัติเหตุ หรือการคืนทรัพย์ตกเป็นพ้นวิสัยเพราะเหตุอย่างอื่นโดยอุบัติเหตุ หรือทรัพย์นั้นเสื่อมเสียลงโดยอุบัติเหตุนั้นด้วย เว้นแต่เมื่อการที่ทรัพย์สินทำลาย หรือตกเป็นพ้นวิสัยจะคืน หรือเสื่อมเสียนั้น ถึงแม้ว่าจะมิได้มีการทำละเมิด ก็คงจะต้องตกไปเป็นไปอย่างนั้นอยู่เอง"}},{"id":"TH-H004-A440","no":440,"noLabel":{"th":"มาตรา 440"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๐ ในกรณีที่ต้องใช้ราคาทรัพย์อันได้เอาของเขาไปก็ดี ในกรณีที่ต้องใช้ราคาทรัพย์อันลดน้อยลงเพราะบุบสลายก็ดี ฝ่ายผู้ต้องเสียหายจะเรียกดอกเบี้ยในจำนวนเงินที่จะต้องใช้ คิดตั้งแต่เวลาอันเป็นฐานที่ตั้งแห่งการประมาณราคานั้นก็ได้"}},{"id":"TH-H004-A441","no":441,"noLabel":{"th":"มาตรา 441"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๑ ถ้าบุคคลจำต้องใช้ค่าสินไหมทดแทนเพื่อความเสียหายอย่างใด ๆ เพราะเอาสังหาริมทรัพย์ของเขาไปก็ดี หรือเพราะทำของเขาให้บุบสลายก็ดี เมื่อใช้ค่าสินไหมทดแทนให้แก่บุคคลซึ่งเป็นผู้ครองทรัพย์นั้นอยู่ในขณะที่เอาไป หรือขณะที่ทำให้บุบสลายนั้นแล้ว ท่านว่าเป็นอันหลุดพ้นไปเพราะการที่ได้ใช้ให้เช่นนั้น แม้กระทั่งบุคคลภายนอกจะเป็นเจ้าของทรัพย์หรือมีสิทธิอย่างอื่นเหนือทรัพย์นั้น เว้นแต่สิทธิของบุคคลภายนอกเช่นนั้นจะเป็นที่รู้อยู่แก่ตนหรือมิได้รู้เพราะความประมาทเลินเล่ออย่างร้ายแรงของตน"}},{"id":"TH-H004-A442","no":442,"noLabel":{"th":"มาตรา 442"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๒ ถ้าความเสียหายได้เกิดขึ้นเพราะความผิดอย่างหนึ่งอย่างใดของผู้ต้องเสียหายประกอบด้วยไซร้ ท่านให้นำบทบัญญัติแห่งมาตรา ๒๒๓ มาใช้บังคับ โดยอนุโลม"}},{"id":"TH-H004-A443","no":443,"noLabel":{"th":"มาตรา 443"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๓ ในกรณีที่ทำให้เขาถึงตายนั้น ค่าสินไหมทดแทนได้แก่ค่าปลงศพรวมทั้งค่าใช้จ่ายอันจำเป็นอย่างอื่น ๆ อีกด้วย ถ้ามิได้ตายในทันที ค่าสินไหมทดแทนได้แก่ค่ารักษาพยาบาลรวมทั้งค่าเสียหายที่ต้องขาดประโยชน์ทำมาหาได้เพราะไม่สามารถประกอบการงานนั้นด้วย ถ้าว่าเหตุที่ตายลงนั้นทำให้บุคคลหนึ่งคนใดต้องขาดไร้อุปการะตามกฎหมายไปด้วยไซร้ ท่านว่าบุคคลคนนั้นชอบที่จะได้รับค่าสินไหมทดแทนเพื่อการนั้น"}},{"id":"TH-H004-A444","no":444,"noLabel":{"th":"มาตรา 444"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๔ ในกรณีทำให้เสียหายแก่ร่างกายหรืออนามัยนั้น ผู้ต้องเสียหายชอบที่จะได้ชดใช้ค่าใช้จ่ายอันตนต้องเสียไป และค่าเสียหายเพื่อการที่เสียความสามารถประกอบการงานสิ้นเชิงหรือแต่บางส่วน ทั้งในเวลาปัจจุบันนั้นและในเวลาอนาคตด้วย ถ้าในเวลาที่พิพากษาคดี เป็นพ้นวิสัยจะหยั่งรู้ได้แน่ว่าความเสียหายนั้นได้มีแท้จริงเพียงใด ศาลจะกล่าวในคำพิพากษาว่ายังสงวนไว้ซึ่งสิทธิที่จะแก้ไขคำพิพากษานั้นอีกภายในระยะเวลาไม่เกินสองปีก็ได้"}},{"id":"TH-H004-A445","no":445,"noLabel":{"th":"มาตรา 445"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๕ ในกรณีทำให้เขาถึงตาย หรือให้เสียหายแก่ร่างกายหรืออนามัยก็ดี ในกรณีทำให้เขาเสียเสรีภาพก็ดี ถ้าผู้ต้องเสียหายมีความผูกพันตามกฎหมายจะต้องทำการงานให้เป็นคุณแก่บุคคลภายนอกในครัวเรือน หรืออุตสาหกรรมของบุคคลภายนอกนั้นไซร้ ท่านว่าบุคคลผู้จำต้องใช้ค่าสินไหมทดแทนนั้นจะต้องใช้ค่าสินไหมทดแทนให้แก่บุคคลภายนอกเพื่อที่เขาต้องขาดแรงงานอันนั้นไปด้วย"}},{"id":"TH-H004-A446","no":446,"noLabel":{"th":"มาตรา 446"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๖ ในกรณีทำให้เขาเสียหายแก่ร่างกายหรืออนามัยก็ดี ในกรณีทำให้เขาเสียเสรีภาพก็ดี ผู้ต้องเสียหายจะเรียกร้องเอาค่าสินไหมทดแทนเพื่อความที่เสียหายอย่างอื่นอันมิใช่ตัวเงินด้วยอีกก็ได้ สิทธิเรียกร้องอันนี้ไม่โอนกันได้ และไม่ตกสืบไปถึงทายาท เว้นแต่สิทธินั้นจะได้รับสภาพกันไว้โดยสัญญาหรือได้เริ่มฟ้องคดีตามสิทธินั้นแล้ว อนึ่ง หญิงที่ต้องเสียหายเพราะผู้ใดทำผิดอาญาเป็นทุรศีลธรรมแก่ตนก็ย่อมมีสิทธิเรียกร้องทำนองเดียวกันนี้"}},{"id":"TH-H004-A447","no":447,"noLabel":{"th":"มาตรา 447"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๗ บุคคลใดทำให้เขาต้องเสียหายแก่ชื่อเสียง เมื่อผู้ต้องเสียหายร้องขอ ศาลจะสั่งให้บุคคลนั้นจัดการตามควรเพื่อทำให้ชื่อเสียงของผู้นั้นกลับคืนดีแทนให้ใช้ค่าเสียหาย หรือทั้งให้ใช้ค่าเสียหายด้วยก็ได้"}},{"id":"TH-H004-A448","no":448,"noLabel":{"th":"มาตรา 448"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๔๔๘ สิทธิเรียกร้องค่าเสียหายอันเกิดแต่มูลละเมิดนั้น ท่านว่าขาดอายุความเมื่อพ้นปีหนึ่งนับแต่วันที่ผู้ต้องเสียหายรู้ถึงการละเมิดและรู้ตัวผู้จะพึงต้องใช้ค่าสินไหมทดแทน หรือเมื่อพ้นสิบปีนับแต่วันทำละเมิด แต่ถ้าเรียกร้องค่าเสียหายในมูลอันเป็นความผิดมีโทษตามกฎหมายลักษณะอาญา และมีกำหนดอายุความทางอาญายาวกว่าที่กล่าวมานั้นไซร้ ท่านให้เอาอายุความที่ยาวกว่านั้นมาบังคับ"}},{"id":"TH-H004-A449","no":449,"noLabel":{"th":"มาตรา 449"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๔๙ บุคคลใดเมื่อกระทำการป้องกันโดยชอบด้วยกฎหมายก็ดี กระทำตามคำสั่งอันชอบด้วยกฎหมายก็ดี หากก่อให้เกิดเสียหายแก่ผู้อื่นไซร้ ท่านว่าบุคคลนั้นหาต้องรับผิดใช้ค่าสินไหมทดแทนไม่ ผู้ต้องเสียหายอาจเรียกค่าสินไหมทดแทนจากผู้เป็นต้นเหตุให้ต้องป้องกันโดยชอบด้วยกฎหมาย หรือจากบุคคลผู้ให้คำสั่งโดยละเมิดนั้นก็ได้"}},{"id":"TH-H004-A450","no":450,"noLabel":{"th":"มาตรา 450"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๕๐ ถ้าบุคคลทำบุบสลาย หรือทำลายทรัพย์สิ่งหนึ่งสิ่งใด เพื่อจะบำบัดปัดป้องภยันตรายซึ่งมีมาเป็นสาธารณะโดยฉุกเฉิน ท่านว่าไม่จำต้องใช้ค่าสินไหมทดแทน หากความเสียหายนั้นไม่เกินสมควรแก่เหตุภยันตราย ถ้าบุคคลทำบุบสลาย หรือทำลายทรัพย์สิ่งหนึ่งสิ่งใด เพื่อจะบำบัดปัดป้องภยันตรายอันมีแก่เอกชนโดยฉุกเฉิน ผู้นั้นจะต้องใช้คืนทรัพย์นั้น ถ้าบุคคลทำบุบสลาย หรือทำลายทรัพย์สิ่งหนึ่งสิ่งใด เพื่อจะป้องกันสิทธิของตนหรือของบุคคลภายนอกจากภยันตรายอันมีมาโดยฉุกเฉินเพราะตัวทรัพย์นั้นเองเป็นเหตุ บุคคลเช่นว่านี้หาต้องรับผิดใช้ค่าสินไหมทดแทนไม่ หากว่าความเสียหายนั้นไม่เกินสมควรแก่เหตุ แต่ถ้าภยันตรายนั้นเกิดขึ้นเพราะความผิดของบุคคลนั้นเองแล้ว ท่านว่าจำต้องรับผิดใช้ค่าสินไหมทดแทนให้"}},{"id":"TH-H004-A451","no":451,"noLabel":{"th":"มาตรา 451"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๕๑ บุคคลใช้กำลังเพื่อป้องกันสิทธิของตน ถ้าตามพฤติการณ์จะขอให้ศาลหรือเจ้าหน้าที่ช่วยเหลือให้ทันท่วงทีไม่ได้ และถ้ามิได้ทำในทันใด ภัยมีอยู่ด้วยการที่ตนจะได้สมดังสิทธินั้นจะต้องประวิงไปมากหรือถึงแก่สาบสูญได้ไซร้ ท่านว่าบุคคลนั้นหาต้องรับผิดใช้ค่าสินไหมทดแทนไม่ การใช้กำลังดังกล่าวมาในวรรคก่อนนั้น ท่านว่าต้องจำกัดครัดเคร่งแต่เฉพาะที่จำเป็นเพื่อจะบำบัดปัดป้องภยันตรายเท่านั้น ถ้าบุคคลผู้ใดกระทำการดังกล่าวมาในวรรคต้น เพราะหลงสันนิษฐานพลาดไปว่ามีเหตุอันจำเป็นที่จะทำได้โดยชอบด้วยกฎหมายไซร้ ท่านว่าผู้นั้นจะต้องรับผิดใช้ค่าสินไหมทดแทนให้แก่บุคคลอื่น แม้ทั้งการที่หลงพลาดไปนั้นจะมิใช่เป็นเพราะความประมาทเลินเล่อของตน"}},{"id":"TH-H004-A452","no":452,"noLabel":{"th":"มาตรา 452"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๕๒ ผู้ครองอสังหาริมทรัพย์ชอบที่จะจับสัตว์ของผู้อื่นอันเข้ามาทำความเสียหายในอสังหาริมทรัพย์นั้น และยึดไว้เป็นประกันค่าสินไหมทดแทนอันจะพึงต้องใช้แก่ตนได้ และถ้าเป็นการจำเป็นโดยพฤติการณ์ แม้จะฆ่าสัตว์นั้นเสียก็ชอบที่จะทำได้ แต่ว่าผู้นั้นต้องบอกกล่าวแก่เจ้าของสัตว์โดยไม่ชักช้า ถ้าและหาตัวเจ้าของสัตว์ไม่พบ ผู้ที่จับสัตว์ไว้ต้องจัดการตามสมควรเพื่อสืบหาตัวเจ้าของ"}},{"id":"TH-H004-A453","no":453,"noLabel":{"th":"มาตรา 453"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๕๓ อันว่าซื้อขายนั้น คือสัญญาซึ่งบุคคลฝ่ายหนึ่ง เรียกว่าผู้ขาย โอนกรรมสิทธิ์แห่งทรัพย์สินให้แก่บุคคลอีกฝ่ายหนึ่ง เรียกว่าผู้ซื้อ และผู้ซื้อตกลงว่าจะใช้ราคาทรัพย์สินนั้นให้แก่ผู้ขาย"}},{"id":"TH-H004-A454","no":454,"noLabel":{"th":"มาตรา 454"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๕๔ การที่คู่กรณีฝ่ายหนึ่งให้คำมั่นไว้ก่อนว่าจะซื้อหรือขายนั้น จะมีผลเป็นการซื้อขายต่อเมื่ออีกฝ่ายหนึ่งได้บอกกล่าวความจำนงว่าจะทำการซื้อขายนั้นให้สำเร็จตลอดไป และคำบอกกล่าวเช่นนั้นได้ไปถึงบุคคลผู้ให้คำมั่นแล้ว ถ้าในคำมั่นมิได้กำหนดเวลาไว้เพื่อการบอกกล่าวเช่นนั้นไซร้ ท่านว่าบุคคลผู้ให้คำมั่นจะกำหนดเวลาพอสมควร และบอกกล่าวไปยังคู่กรณีอีกฝ่ายหนึ่งให้ตอบมาเป็นแน่นอนภายในเวลากำหนดนั้นก็ได้ ว่าจะทำการซื้อขายให้สำเร็จตลอดไปหรือไม่ ถ้าและไม่ตอบเป็นแน่นอนภายในกำหนดเวลานั้นไซร้ คำมั่นซึ่งได้ให้ไว้ก่อนนั้นก็เป็นอันไร้ผล"}},{"id":"TH-H004-A455","no":455,"noLabel":{"th":"มาตรา 455"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๕๕ เมื่อกล่าวต่อไปเบื้องหน้าถึงเวลาซื้อขาย ท่านหมายความว่าเวลาซึ่งทำสัญญาซื้อขายสำเร็จบริบูรณ์"}},{"id":"TH-H004-A456","no":456,"noLabel":{"th":"มาตรา 456"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๕๖ การซื้อขายอสังหาริมทรัพย์ ถ้ามิได้ทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่เป็นโมฆะ วิธีนี้ให้ใช้ถึงซื้อขายเรือมีระวางตั้งแต่ห้าตันขึ้นไป ทั้งซื้อขายแพและสัตว์พาหนะด้วย สัญญาจะขายหรือจะซื้อ หรือคำมั่นในการซื้อขายทรัพย์สินตามที่ระบุไว้ในวรรคหนึ่ง ถ้ามิได้มีหลักฐานเป็นหนังสืออย่างหนึ่งอย่างใดลงลายมือชื่อฝ่ายผู้ต้องรับผิดเป็นสำคัญ หรือได้วางประจำไว้หรือได้ชำระหนี้บางส่วนแล้ว จะฟ้องร้องให้บังคับคดีหาได้ไม่ บทบัญญัติที่กล่าวมาในวรรคก่อนนี้ ให้ใช้บังคับถึงสัญญาซื้อขายสังหาริมทรัพย์ซึ่งตกลงกันเป็นราคาสองหมื่นบาท หรือกว่านั้นขึ้นไปด้วย"}},{"id":"TH-H004-A457","no":457,"noLabel":{"th":"มาตรา 457"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๕๗ ค่าฤชาธรรมเนียมทำสัญญาซื้อขายนั้น ผู้ซื้อผู้ขายพึงออกใช้เท่ากันทั้งสองฝ่าย"}},{"id":"TH-H004-A458","no":458,"noLabel":{"th":"มาตรา 458"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๕๘ กรรมสิทธิ์ในทรัพย์สินที่ขายนั้น ย่อมโอนไปยังผู้ซื้อตั้งแต่ขณะเมื่อได้ทำสัญญาซื้อขายกัน"}},{"id":"TH-H004-A459","no":459,"noLabel":{"th":"มาตรา 459"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๕๙ ถ้าสัญญาซื้อขายมีเงื่อนไข หรือเงื่อนเวลาบังคับไว้ ท่านว่ากรรมสิทธิ์ในทรัพย์สินยังไม่โอนไปจนกว่าการจะได้เป็นไปตามเงื่อนไข หรือถึงกำหนดเงื่อนเวลานั้น"}},{"id":"TH-H004-A460","no":460,"noLabel":{"th":"มาตรา 460"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๖๐ ในการซื้อขายทรัพย์สินซึ่งมิได้กำหนดลงไว้แน่นอนนั้น ท่านว่ากรรมสิทธิ์ยังไม่โอนไปจนกว่าจะได้หมาย หรือนับ ชั่ง ตวง วัด หรือคัดเลือก หรือทำโดยวิธีอื่นเพื่อให้บ่งตัวทรัพย์สินนั้นออกเป็นแน่นอนแล้ว ในการซื้อขายทรัพย์สินเฉพาะสิ่ง ถ้าผู้ขายยังจะต้องนับ ชั่ง ตวง วัด หรือทำการอย่างอื่น หรือทำสิ่งหนึ่งสิ่งใดอันเกี่ยวแก่ทรัพย์สินเพื่อให้รู้กำหนดราคาทรัพย์สินนั้นแน่นอน ท่านว่ากรรมสิทธิ์ยังไม่โอนไปยังผู้ซื้อจนกว่าการหรือสิ่งนั้นได้ทำแล้ว"}},{"id":"TH-H004-A461","no":461,"noLabel":{"th":"มาตรา 461"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๑ ผู้ขายจำต้องส่งมอบทรัพย์สินซึ่งขายนั้นให้แก่ผู้ซื้อ"}},{"id":"TH-H004-A462","no":462,"noLabel":{"th":"มาตรา 462"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๒ การส่งมอบนั้นจะทำอย่างหนึ่งอย่างใดก็ได้สุดแต่ว่าเป็นผลให้ทรัพย์สินนั้นไปอยู่ในเงื้อมมือของผู้ซื้อ"}},{"id":"TH-H004-A463","no":463,"noLabel":{"th":"มาตรา 463"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๓ ถ้าในสัญญากำหนดว่าให้ส่งทรัพย์สินซึ่งขายนั้นจากที่แห่งหนึ่งไปถึงอีกแห่งหนึ่งไซร้ ท่านว่าการส่งมอบย่อมสำเร็จเมื่อได้ส่งมอบทรัพย์สินนั้นให้แก่ผู้ขนส่ง"}},{"id":"TH-H004-A464","no":464,"noLabel":{"th":"มาตรา 464"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๔ ค่าขนส่งทรัพย์สินซึ่งได้ซื้อขายกันไปยังที่แห่งอื่น นอกจากสถานที่อันพึงชำระหนี้นั้น ผู้ซื้อพึงออกใช้"}},{"id":"TH-H004-A465","no":465,"noLabel":{"th":"มาตรา 465"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๕ ในการซื้อขายสังหาริมทรัพย์นั้น (๑) หากว่าผู้ขายส่งมอบทรัพย์สินน้อยกว่าที่ได้สัญญาไว้ ท่านว่าผู้ซื้อจะปัดเสียไม่รับเอาเลยก็ได้ แต่ถ้าผู้ซื้อรับเอาทรัพย์สินนั้นไว้ ผู้ซื้อก็ต้องใช้ราคาตามส่วน (๒) หากว่าผู้ขายส่งมอบทรัพย์สินมากกว่าที่ได้สัญญาไว้ ท่านว่าผู้ซื้อจะรับเอาทรัพย์สินนั้นไว้แต่เพียงตามสัญญาและนอกกว่านั้นปัดเสียก็ได้ หรือจะปัดเสียทั้งหมดไม่รับเอาไว้เลยก็ได้ ถ้าผู้ซื้อรับเอาทรัพย์สินอันเขาส่งมอบเช่นนั้นไว้ทั้งหมด ผู้ซื้อก็ต้องใช้ราคาตามส่วน (๓) หากว่าผู้ขายส่งมอบทรัพย์สินตามที่ได้สัญญาไว้ ระคนกับทรัพย์สินอย่างอื่นอันมิได้รวมอยู่ในข้อสัญญาไซร้ ท่านว่าผู้ซื้อจะรับเอาทรัพย์สินไว้แต่ตามสัญญา และนอกกว่านั้นปัดเสียก็ได้ หรือจะปัดเสียทั้งหมดก็ได้"}},{"id":"TH-H004-A466","no":466,"noLabel":{"th":"มาตรา 466"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๖ ในการซื้อขายอสังหาริมทรัพย์นั้น หากว่าได้ระบุจำนวนเนื้อที่ทั้งหมดไว้ และผู้ขายส่งมอบทรัพย์สินน้อยหรือมากไปกว่าที่ได้สัญญาไซร้ ท่านว่าผู้ซื้อจะปัดเสีย หรือจะรับเอาไว้และใช้ราคาตามส่วนก็ได้ ตามแต่จะเลือก อนึ่ง ถ้าขาดตกบกพร่องหรือล้ำจำนวนไม่เกินกว่าร้อยละห้าแห่งเนื้อที่ทั้งหมดอันได้ระบุไว้นั้นไซร้ ท่านว่าผู้ซื้อจำต้องรับเอาและใช้ราคาตามส่วน แต่ว่าผู้ซื้ออาจจะเลิกสัญญาเสียได้ในเมื่อขาดตกบกพร่องหรือล้ำจำนวนถึงขนาดซึ่งหากผู้ซื้อได้ทราบก่อนแล้วคงจะมิได้เข้าทำสัญญานั้น"}},{"id":"TH-H004-A467","no":467,"noLabel":{"th":"มาตรา 467"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๗ ในข้อรับผิดเพื่อการที่ทรัพย์ขาดตกบกพร่องหรือล้ำจำนวนนั้น ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นกำหนดปีหนึ่งนับแต่เวลาส่งมอบ"}},{"id":"TH-H004-A468","no":468,"noLabel":{"th":"มาตรา 468"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๘ ถ้าในสัญญาไม่มีกำหนดเงื่อนเวลาให้ใช้ราคาไซร้ ผู้ขายชอบที่จะยึดหน่วงทรัพย์สินที่ขายไว้ได้จนกว่าจะใช้ราคา"}},{"id":"TH-H004-A469","no":469,"noLabel":{"th":"มาตรา 469"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๖๙ ถ้าผู้ซื้อล้มละลายก่อนส่งมอบทรัพย์สินก็ดี หรือผู้ซื้อเป็นคนล้มละลายแล้วในเวลาซื้อขายโดยผู้ขายไม่รู้ก็ดี หรือผู้ซื้อกระทำให้หลักทรัพย์ที่ให้ไว้เพื่อประกันการใช้เงินนั้นเสื่อมเสียหรือลดน้อยลงก็ดี ถึงแม้ในสัญญาจะมีกำหนดเงื่อนเวลาให้ใช้ราคา ผู้ขายก็ชอบที่จะยึดหน่วงทรัพย์สินซึ่งขายไว้ได้ เว้นแต่ผู้ซื้อจะหาประกันที่สมควรให้ได้"}},{"id":"TH-H004-A470","no":470,"noLabel":{"th":"มาตรา 470"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๗๐ ถ้าผู้ซื้อผิดนัด ผู้ขายซึ่งได้ยึดหน่วงทรัพย์สินไว้ตามมาตราทั้งหลายที่กล่าวมา อาจจะใช้ทางแก้ต่อไปนี้แทนทางแก้สามัญในการไม่ชำระหนี้ได้ คือมีจดหมายบอกกล่าวไปยังผู้ซื้อให้ใช้ราคากับทั้งค่าจับจ่ายเกี่ยวการภายในเวลาอันควรซึ่งต้องกำหนดลงไว้ในคำบอกกล่าวนั้นด้วย ถ้าผู้ซื้อละเลยเสียไม่ทำตามคำบอกกล่าว ผู้ขายอาจนำทรัพย์สินนั้นออกขายทอดตลาดได้"}},{"id":"TH-H004-A471","no":471,"noLabel":{"th":"มาตรา 471"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๗๑ เมื่อขายทอดตลาดได้เงินเป็นจำนวนสุทธิเท่าใด ให้ผู้ขายหักเอาจำนวนที่ค้างชำระแก่ตนเพื่อราคาและค่าจับจ่ายเกี่ยวการนั้นไว้ ถ้าและยังมีเงินเหลือ ก็ให้ส่งมอบแก่ผู้ซื้อโดยพลัน"}},{"id":"TH-H004-A472","no":472,"noLabel":{"th":"มาตรา 472"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๗๒ ในกรณีที่ทรัพย์สินซึ่งขายนั้นชำรุดบกพร่องอย่างหนึ่งอย่างใด อันเป็นเหตุให้เสื่อมราคาหรือเสื่อมความเหมาะสมแก่ประโยชน์อันมุ่งจะใช้เป็นปกติก็ดี ประโยชน์ที่มุ่งหมายโดยสัญญาก็ดี ท่านว่าผู้ขายต้องรับผิด ความที่กล่าวมาในมาตรานี้ย่อมใช้ได้ ทั้งที่ผู้ขายรู้อยู่แล้วหรือไม่รู้ว่าความชำรุดบกพร่องมีอยู่"}},{"id":"TH-H004-A473","no":473,"noLabel":{"th":"มาตรา 473"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๗๓ ผู้ขายย่อมไม่ต้องรับผิดในกรณีดังจะกล่าวต่อไปนี้ คือ (๑) ถ้าผู้ซื้อได้รู้อยู่แล้วแต่ในเวลาซื้อขายว่ามีความชำรุดบกพร่อง หรือควรจะได้รู้เช่นนั้นหากได้ใช้ความระมัดระวังอันจะพึงคาดหมายได้แต่วิญญูชน (๒) ถ้าความชำรุดบกพร่องนั้นเป็นอันเห็นประจักษ์แล้วในเวลาส่งมอบ และผู้ซื้อรับเอาทรัพย์สินนั้นไว้โดยมิได้อิดเอื้อน (๓) ถ้าทรัพย์สินนั้นได้ขายทอดตลาด"}},{"id":"TH-H004-A474","no":474,"noLabel":{"th":"มาตรา 474"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๔๗๔ ในข้อรับผิดเพื่อชำรุดบกพร่องนั้น ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นเวลาปีหนึ่งนับแต่เวลาที่ได้พบเห็นความชำรุดบกพร่อง"}},{"id":"TH-H004-A475","no":475,"noLabel":{"th":"มาตรา 475"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗๕ หากว่าบุคคลผู้ใดมาก่อการรบกวนขัดสิทธิของผู้ซื้อในอันจะครองทรัพย์สินโดยปกติสุข เพราะบุคคลผู้นั้นมีสิทธิเหนือทรัพย์สินที่ได้ซื้อขายกันนั้นอยู่ในเวลาซื้อขายก็ดี เพราะความผิดของผู้ขายก็ดี ท่านว่าผู้ขายจะต้องรับผิดในผลอันนั้น"}},{"id":"TH-H004-A476","no":476,"noLabel":{"th":"มาตรา 476"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗๖ ถ้าสิทธิของผู้ก่อการรบกวนนั้นผู้ซื้อรู้อยู่แล้วในเวลาซื้อขาย ท่านว่าผู้ขายไม่ต้องรับผิด"}},{"id":"TH-H004-A477","no":477,"noLabel":{"th":"มาตรา 477"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗๗ เมื่อใดการรบกวนขัดสิทธินั้นเกิดเป็นคดีขึ้นระหว่างผู้ซื้อกับบุคคลภายนอก ผู้ซื้อชอบที่จะขอให้ศาลเรียกผู้ขายเข้าเป็นจำเลยร่วมหรือเป็นโจทก์ร่วมกับผู้ซื้อในคดีนั้นได้ เพื่อศาลจะได้วินิจฉัยชี้ขาดข้อพิพาทระหว่างผู้เป็นคู่กรณีทั้งหลายรวมไปเป็นคดีเดียวกัน"}},{"id":"TH-H004-A478","no":478,"noLabel":{"th":"มาตรา 478"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗๘ ถ้าผู้ขายเห็นเป็นการสมควร จะสอดเข้าไปในคดีเพื่อปฏิเสธการเรียกร้องของบุคคลภายนอก ก็ชอบที่จะทำได้ด้วย"}},{"id":"TH-H004-A479","no":479,"noLabel":{"th":"มาตรา 479"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๗๙ ถ้าทรัพย์สินซึ่งซื้อขายกันหลุดไปจากผู้ซื้อทั้งหมดหรือแต่บางส่วน เพราะเหตุการรอนสิทธิก็ดี หรือว่าทรัพย์สินนั้นตกอยู่ในบังคับแห่งสิทธิอย่างหนึ่งอย่างใดซึ่งเป็นเหตุให้เสื่อมราคา หรือเสื่อมความเหมาะสมแก่การที่จะใช้ หรือเสื่อมความสะดวกในการใช้สอย หรือเสื่อมประโยชน์อันจะพึงได้แต่ทรัพย์สินนั้น และซึ่งผู้ซื้อหาได้รู้ในเวลาซื้อขายไม่ก็ดี ท่านว่าผู้ขายต้องรับผิด"}},{"id":"TH-H004-A480","no":480,"noLabel":{"th":"มาตรา 480"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๘๐ ถ้าอสังหาริมทรัพย์ต้องศาลแสดงว่าตกอยู่ในบังคับแห่งภาระจำยอมโดยกฎหมายไซร้ ท่านว่าผู้ขายไม่ต้องรับผิด เว้นไว้แต่ผู้ขายจะได้รับรองไว้ในสัญญาว่าทรัพย์สินนั้นปลอดจากภาระจำยอมอย่างใด ๆ ทั้งสิ้น หรือปลอดจากภาระจำยอมอันนั้น"}},{"id":"TH-H004-A481","no":481,"noLabel":{"th":"มาตรา 481"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๘๑ ถ้าผู้ขายไม่ได้เป็นคู่ความในคดีเดิม หรือถ้าผู้ซื้อได้ประนีประนอมยอมความกับบุคคลภายนอก หรือยอมตามที่บุคคลภายนอกเรียกร้องไซร้ ท่านห้ามมิให้ฟ้องคดีในข้อรับผิดเพื่อการรอนสิทธิเมื่อพ้นกำหนดสามเดือนนับแต่วันคำพิพากษาในคดีเดิมถึงที่สุด หรือนับแต่วันประนีประนอมยอมความ หรือวันที่ยอมตามบุคคลภายนอกเรียกร้องนั้น"}},{"id":"TH-H004-A482","no":482,"noLabel":{"th":"มาตรา 482"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๔๘๒ ผู้ขายไม่ต้องรับผิดในการรอนสิทธิเมื่อกรณีเป็นดังกล่าวต่อไปนี้ คือ (๑) ถ้าไม่มีการฟ้องคดี และผู้ขายพิสูจน์ได้ว่าสิทธิของผู้ซื้อได้สูญไปโดยความผิดของผู้ซื้อเอง หรือ (๒) ถ้าผู้ซื้อไม่ได้เรียกผู้ขายเข้ามาในคดี และผู้ขายพิสูจน์ได้ว่า ถ้าได้เรียกเข้ามาในคดีฝ่ายผู้ซื้อจะชนะ หรือ (๓) ถ้าผู้ขายได้เข้ามาในคดี แต่ศาลได้ยกคำเรียกร้องของผู้ซื้อเสียเพราะความผิดของผู้ซื้อเอง แต่ถึงกรณีจะเป็นอย่างไรก็ดี ถ้าผู้ขายถูกศาลหมายเรียกให้เข้ามาในคดีและไม่ยอมเข้าว่าคดีร่วมเป็นจำเลยหรือร่วมเป็นโจทก์กับผู้ซื้อไซร้ ท่านว่าผู้ขายคงต้องรับผิด"}},{"id":"TH-H004-A483","no":483,"noLabel":{"th":"มาตรา 483"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๔๘๓ คู่สัญญาซื้อขายจะตกลงกันว่าผู้ขายจะไม่ต้องรับผิดเพื่อความชำรุดบกพร่องหรือเพื่อการรอนสิทธิก็ได้"}},{"id":"TH-H004-A484","no":484,"noLabel":{"th":"มาตรา 484"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๔๘๔ ข้อสัญญาว่าจะไม่ต้องรับผิดนั้น ย่อมไม่คุ้มผู้ขายให้พ้นจากการต้องส่งเงินคืนตามราคา เว้นแต่จะได้ระบุไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A485","no":485,"noLabel":{"th":"มาตรา 485"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๔๘๕ ข้อสัญญาว่าจะไม่ต้องรับผิดนั้น ไม่อาจคุ้มความรับผิดของผู้ขายในผลของการอันผู้ขายได้กระทำไปเอง หรือผลแห่งข้อความจริงอันผู้ขายได้รู้อยู่แล้วและปกปิดเสีย"}},{"id":"TH-H004-A486","no":486,"noLabel":{"th":"มาตรา 486"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๘๖ ผู้ซื้อจำต้องรับมอบทรัพย์สินที่ตนได้รับซื้อและใช้ราคาตามข้อสัญญาซื้อขาย"}},{"id":"TH-H004-A487","no":487,"noLabel":{"th":"มาตรา 487"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๘๗ อันราคาทรัพย์สินที่ขายนั้นจะกำหนดลงไว้ในสัญญาก็ได้ หรือจะปล่อยไปให้กำหนดกันด้วยวิธีอย่างใดอย่างหนึ่งดังได้ตกลงกันไว้ในสัญญานั้นก็ได้ หรือจะถือเอาตามทางการที่คู่สัญญาประพฤติต่อกันอยู่นั้นก็ได้ ถ้าราคามิได้กำหนดเด็ดขาดอย่างใดดังว่ามานั้นไซร้ ท่านว่าผู้ซื้อจะต้องใช้ราคาตามสมควร"}},{"id":"TH-H004-A488","no":488,"noLabel":{"th":"มาตรา 488"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๘๘ ถ้าผู้ซื้อพบเห็นความชำรุดบกพร่องในทรัพย์สินซึ่งตนได้รับซื้อ ผู้ซื้อชอบที่จะยึดหน่วงราคาที่ยังไม่ได้ชำระไว้ได้ทั้งหมดหรือแต่บางส่วน เว้นแต่ผู้ขายจะหาประกันที่สมควรให้ได้"}},{"id":"TH-H004-A489","no":489,"noLabel":{"th":"มาตรา 489"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๘๙ ถ้าผู้ซื้อถูกผู้รับจำนองหรือบุคคลผู้เรียกร้องเอาทรัพย์สินที่ขายนั้นขู่ว่าจะฟ้องเป็นคดีขึ้นก็ดี หรือมีเหตุอันควรเชื่อว่าจะถูกขู่เช่นนั้นก็ดี ผู้ซื้อก็ชอบที่จะยึดหน่วงราคาไว้ทั้งหมดหรือบางส่วนได้ดุจกัน จนกว่าผู้ขายจะได้บำบัดภัยอันนั้นให้สิ้นไป หรือจนกว่าผู้ขายจะหาประกันที่สมควรให้ได้"}},{"id":"TH-H004-A490","no":490,"noLabel":{"th":"มาตรา 490"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๔๙๐ ถ้าได้กำหนดกันไว้ว่าให้ส่งมอบทรัพย์สินซึ่งขายนั้นเวลาใด ท่านให้สันนิษฐานไว้ก่อนว่าเวลาอันเดียวกันนั้นเองเป็นเวลากำหนดใช้ราคา"}},{"id":"TH-H004-A491","no":491,"noLabel":{"th":"มาตรา 491"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๑ อันว่าขายฝากนั้น คือสัญญาซื้อขายซึ่งกรรมสิทธิ์ในทรัพย์สินตกไปยังผู้ซื้อ โดยมีข้อตกลงกันว่าผู้ขายอาจไถ่ทรัพย์นั้นคืนได้"}},{"id":"TH-H004-A492","no":492,"noLabel":{"th":"มาตรา 492"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๒ ในกรณีที่มีการไถ่ทรัพย์สินซึ่งขายฝากภายในเวลาที่กำหนดไว้ในสัญญาหรือภายในเวลาที่กฎหมายกำหนด หรือผู้ไถ่ได้วางทรัพย์อันเป็นสินไถ่ต่อสำนักงานวางทรัพย์ภายในกำหนดเวลาไถ่โดยสละสิทธิถอนทรัพย์ที่ได้วางไว้ ให้ทรัพย์สินซึ่งขายฝากตกเป็นกรรมสิทธิ์ของผู้ไถ่ตั้งแต่เวลาที่ผู้ไถ่ได้ชำระสินไถ่หรือวางทรัพย์อันเป็นสินไถ่ แล้วแต่กรณี ในกรณีที่ได้วางทรัพย์ตามวรรคหนึ่ง ให้เจ้าพนักงานของสำนักงานวางทรัพย์แจ้งให้ผู้รับไถ่ทราบถึงการวางทรัพย์โดยพลัน โดยผู้ไถ่ไม่ต้องปฏิบัติตามมาตรา ๓๓๓ วรรคสาม"}},{"id":"TH-H004-A493","no":493,"noLabel":{"th":"มาตรา 493"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๓ ในการขายฝาก คู่สัญญาจะตกลงกันไม่ให้ผู้ซื้อจำหน่ายทรัพย์สินซึ่งขายฝากก็ได้ ถ้าและผู้ซื้อจำหน่ายทรัพย์สินนั้นฝ่าฝืนสัญญาไซร้ ก็ต้องรับผิดต่อผู้ขายในความเสียหายใด ๆ อันเกิดแต่การนั้น"}},{"id":"TH-H004-A494","no":494,"noLabel":{"th":"มาตรา 494"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๔ ท่านห้ามมิให้ใช้สิทธิไถ่ทรัพย์สินซึ่งขายฝากเมื่อพ้นเวลาดังจะกล่าวต่อไปนี้ (๑) ถ้าเป็นอสังหาริมทรัพย์ กำหนดสิบปีนับแต่เวลาซื้อขาย (๒) ถ้าเป็นสังหาริมทรัพย์ กำหนดสามปีนับแต่เวลาซื้อขาย"}},{"id":"TH-H004-A495","no":495,"noLabel":{"th":"มาตรา 495"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๕ ถ้าในสัญญามีกำหนดเวลาไถ่เกินไปกว่านั้น ท่านให้ลดลงมาเป็นสิบปีและสามปีตามประเภททรัพย์"}},{"id":"TH-H004-A496","no":496,"noLabel":{"th":"มาตรา 496"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๖ กำหนดเวลาไถ่นั้น อาจทำสัญญาขยายกำหนดเวลาไถ่ได้ แต่กำหนดเวลาไถ่รวมกันทั้งหมด ถ้าเกินกำหนดเวลาตามมาตรา ๔๙๔ ให้ลดลงมาเป็นกำหนดเวลาตามมาตรา ๔๙๔ การขยายกำหนดเวลาไถ่ตามวรรคหนึ่งอย่างน้อยต้องมีหลักฐานเป็นหนังสือลงลายมือชื่อผู้รับไถ่ ถ้าเป็นทรัพย์สินซึ่งการซื้อขายกันจะต้องทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่ ห้ามมิให้ยกการขยายเวลาขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริต และได้จดทะเบียนสิทธิโดยสุจริตแล้ว เว้นแต่จะได้นำหนังสือหรือหลักฐานเป็นหนังสือดังกล่าวไปจดทะเบียนหรือจดแจ้งต่อพนักงานเจ้าหน้าที่"}},{"id":"TH-H004-A497","no":497,"noLabel":{"th":"มาตรา 497"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๗ สิทธิในการไถ่ทรัพย์สินนั้น จะพึงใช้ได้แต่บุคคลเหล่านี้ คือ (๑) ผู้ขายเดิม หรือทายาทของผู้ขายเดิม หรือ (๒) ผู้รับโอนสิทธินั้น หรือ (๓) บุคคลซึ่งในสัญญายอมไว้โดยเฉพาะว่าให้เป็นผู้ไถ่ได้"}},{"id":"TH-H004-A498","no":498,"noLabel":{"th":"มาตรา 498"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๘ สิทธิในการไถ่ทรัพย์สินนั้น จะพึงใช้ได้เฉพาะต่อบุคคลเหล่านี้ คือ (๑) ผู้ซื้อเดิม หรือทายาทของผู้ซื้อเดิม หรือ (๒) ผู้รับโอนทรัพย์สิน หรือรับโอนสิทธิเหนือทรัพย์สินนั้น แต่ในข้อนี้ถ้าเป็นสังหาริมทรัพย์จะใช้สิทธิได้ต่อเมื่อผู้รับโอนได้รู้ในเวลาโอน ว่าทรัพย์สินตกอยู่ในบังคับแห่งสิทธิไถ่คืน"}},{"id":"TH-H004-A499","no":499,"noLabel":{"th":"มาตรา 499"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๔๙๙ สินไถ่นั้น ถ้าไม่ได้กำหนดกันไว้ว่าเท่าใดไซร้ ท่านให้ไถ่ตามราคาที่ขายฝาก ถ้าปรากฏในเวลาไถ่ว่าสินไถ่หรือราคาขายฝากที่กำหนดไว้สูงกว่าราคาขายฝากที่แท้จริงเกินอัตราร้อยละสิบห้าต่อปี ให้ไถ่ได้ตามราคาขายฝากที่แท้จริงรวมประโยชน์ตอบแทนร้อยละสิบห้าต่อปี"}},{"id":"TH-H004-A500","no":500,"noLabel":{"th":"มาตรา 500"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๕๐๐ ค่าฤชาธรรมเนียมการขายฝากซึ่งผู้ซื้อได้ออกไปนั้น ผู้ไถ่ต้องใช้ให้แก่ผู้ซื้อพร้อมกับสินไถ่ ส่วนค่าฤชาธรรมเนียมการไถ่ทรัพย์นั้น ผู้ไถ่พึงออกใช้"}},{"id":"TH-H004-A501","no":501,"noLabel":{"th":"มาตรา 501"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๕๐๑ ทรัพย์สินซึ่งไถ่นั้น ท่านว่าต้องส่งคืนตามสภาพที่เป็นอยู่ในเวลาไถ่ แต่ถ้าหากว่าทรัพย์สินนั้นถูกทำลายหรือทำให้เสื่อมเสียไปเพราะความผิดของผู้ซื้อไซร้ ท่านว่าผู้ซื้อจะต้องใช้ค่าสินไหมทดแทน"}},{"id":"TH-H004-A502","no":502,"noLabel":{"th":"มาตรา 502"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๕๐๒ ทรัพย์สินซึ่งไถ่นั้น ท่านว่าบุคคลผู้ไถ่ย่อมได้รับคืนไปโดยปลอดจากสิทธิใด ๆ ซึ่งผู้ซื้อเดิม หรือทายาท หรือผู้รับโอนจากผู้ซื้อเดิมก่อให้เกิดขึ้นก่อนเวลาไถ่ ถ้าว่าเช่าทรัพย์สินที่อยู่ในระหว่างขายฝากอันได้จดทะเบียนเช่าต่อพนักงานเจ้าหน้าที่แล้วไซร้ ท่านว่าการเช่านั้นหากมิได้ทำขึ้นเพื่อจะให้เสียหายแก่ผู้ขาย กำหนดเวลาเช่ายังคงมีเหลืออยู่อีกเพียงใด ก็ให้คงเป็นอันสมบูรณ์อยู่เพียงนั้น แต่มิให้เกินกว่าปีหนึ่ง"}},{"id":"TH-H004-A503","no":503,"noLabel":{"th":"มาตรา 503"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๓ ในการขายตามตัวอย่างนั้น ผู้ขายจำต้องส่งมอบทรัพย์สินให้ตรงตามตัวอย่าง ในการขายตามคำพรรณนา ผู้ขายจำต้องส่งมอบทรัพย์สินให้ตรงตามคำพรรณนา"}},{"id":"TH-H004-A504","no":504,"noLabel":{"th":"มาตรา 504"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๔ ในข้อรับผิดเพื่อการส่งของไม่ตรงตามตัวอย่าง หรือไม่ตรงตามคำพรรณนานั้น ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นกำหนดปีหนึ่งนับแต่เวลาส่งมอบ"}},{"id":"TH-H004-A505","no":505,"noLabel":{"th":"มาตรา 505"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๕ อันว่าขายเผื่อชอบนั้น คือการซื้อขายกันโดยมีเงื่อนไขว่าให้ผู้ซื้อได้มีโอกาสตรวจดูทรัพย์สินก่อนรับซื้อ"}},{"id":"TH-H004-A506","no":506,"noLabel":{"th":"มาตรา 506"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๖ การตรวจดูทรัพย์สินนั้น ถ้าไม่ได้กำหนดเวลากันไว้ ผู้ขายอาจกำหนดเวลาอันสมควร และบอกกล่าวแก่ผู้ซื้อให้ตอบภายในกำหนดนั้นได้ว่าจะรับซื้อหรือไม่"}},{"id":"TH-H004-A507","no":507,"noLabel":{"th":"มาตรา 507"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๗ ทรัพย์สินอันผู้ซื้อจะพึงตรวจดูก่อนที่จะส่งมอบแก่กันนั้น ถ้าผู้ซื้อไม่ตรวจรับภายในเวลาที่กำหนดไว้โดยสัญญา หรือโดยประเพณี หรือโดยคำบอกกล่าวของผู้ขาย ท่านว่าผู้ขายย่อมไม่มีความผูกพันต่อไป"}},{"id":"TH-H004-A508","no":508,"noLabel":{"th":"มาตรา 508"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๕๐๘ เมื่อทรัพย์สินนั้นได้ส่งมอบแก่ผู้ซื้อเพื่อให้ตรวจดูแล้ว การซื้อขายย่อมเป็นอันบริบูรณ์ในกรณีต่อไปนี้ คือ (๑) ถ้าผู้ซื้อมิได้บอกกล่าวว่าไม่ยอมรับซื้อภายในเวลาที่กำหนดไว้โดยสัญญา หรือโดยประเพณี หรือโดยคำบอกกล่าว หรือ (๒) ถ้าผู้ซื้อไม่ส่งทรัพย์สินคืนภายในกำหนดเวลาดังกล่าวมานั้น หรือ (๓) ถ้าผู้ซื้อใช้ราคาทรัพย์สินนั้นสิ้นเชิง หรือแต่บางส่วน หรือ (๔) ถ้าผู้ซื้อจำหน่ายทรัพย์สินนั้น หรือทำประการอื่นอย่างใดอันเป็นปริยายว่ารับซื้อของนั้น"}},{"id":"TH-H004-A509","no":509,"noLabel":{"th":"มาตรา 509"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๐๙ การขายทอดตลาดย่อมบริบูรณ์ เมื่อผู้ทอดตลาดแสดงความตกลงด้วยเคาะไม้ หรือด้วยกิริยาอื่นอย่างใดอย่างหนึ่งตามจารีตประเพณีในการขายทอดตลาด ถ้ายังมิได้แสดงเช่นนั้นอยู่ตราบใด ท่านว่าผู้สู้ราคาจะถอนคำสู้ราคาของตนเสียก็ยังถอนได้"}},{"id":"TH-H004-A510","no":510,"noLabel":{"th":"มาตรา 510"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๐ ผู้ซื้อในการขายทอดตลาดจะต้องทำตามคำโฆษณาบอกขาย และตามความข้ออื่น ๆ ซึ่งผู้ทอดตลาดได้แถลงก่อนประเดิมการสู้ราคาทรัพย์สินเฉพาะรายไป"}},{"id":"TH-H004-A511","no":511,"noLabel":{"th":"มาตรา 511"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๑ ท่านห้ามมิให้ผู้ทอดตลาดเข้าสู้ราคา หรือใช้ให้ผู้หนึ่งผู้ใดเข้าสู้ราคา ในการทอดตลาดซึ่งตนเป็นผู้อำนวยการเอง"}},{"id":"TH-H004-A512","no":512,"noLabel":{"th":"มาตรา 512"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๒ ท่านห้ามมิให้ผู้ขายเข้าสู้ราคาเอง หรือใช้ให้ผู้หนึ่งผู้ใดเข้าสู้ราคา เว้นแต่จะได้แถลงไว้โดยเฉพาะในคำโฆษณาบอกการทอดตลาดนั้น ว่าผู้ขายถือสิทธิที่จะเข้าสู้ราคาด้วย"}},{"id":"TH-H004-A513","no":513,"noLabel":{"th":"มาตรา 513"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๓ เมื่อใดผู้ทอดตลาดเห็นว่าราคาซึ่งมีผู้สู้สูงสุดนั้นยังไม่เพียงพอ ผู้ทอดตลาดอาจถอนทรัพย์สินจากการทอดตลาดได้"}},{"id":"TH-H004-A514","no":514,"noLabel":{"th":"มาตรา 514"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๔ ผู้สู้ราคาย่อมพ้นความผูกพันในราคาซึ่งตนสู้แต่ขณะเมื่อมีผู้อื่นสู้ราคาสูงขึ้นไป ไม่ว่าการที่ผู้อื่นสู้นั้นจะสมบูรณ์หรือมิสมบูรณ์ประการใด อีกประการหนึ่งเมื่อใดถอนทรัพย์สินรายนั้นจากการทอดตลาด ผู้สู้ราคาก็พ้นความผูกพันแต่ขณะที่ถอนนั้นดุจกัน"}},{"id":"TH-H004-A515","no":515,"noLabel":{"th":"มาตรา 515"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๕ ผู้สู้ราคาสูงสุดต้องใช้ราคาเป็นเงินสด เมื่อการซื้อขายบริบูรณ์หรือตามเวลาที่กำหนดไว้ในคำโฆษณาบอกขาย"}},{"id":"TH-H004-A516","no":516,"noLabel":{"th":"มาตรา 516"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๖ ถ้าผู้สู้ราคาสูงสุดละเลยเสียไม่ใช้ราคาไซร้ ท่านให้ผู้ทอดตลาดเอาทรัพย์สินนั้นออกขายอีกซ้ำหนึ่ง ถ้าและได้เงินเป็นจำนวนสุทธิไม่คุ้มราคาและค่าขายทอดตลาดชั้นเดิม ผู้สู้ราคาเดิมคนนั้นต้องรับผิดในส่วนที่ขาด"}},{"id":"TH-H004-A517","no":517,"noLabel":{"th":"มาตรา 517"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๕๑๗ ถ้าเงินรายได้ในการทอดตลาดส่วนหนึ่งส่วนใดค้างชำระอยู่ เพราะเหตุผู้ทอดตลาดละเลยไม่บังคับตามบทในมาตรา ๕๑๕ หรือมาตรา ๕๑๖ ไซร้ ท่านว่าผู้ทอดตลาดจะต้องรับผิด"}},{"id":"TH-H004-A518","no":518,"noLabel":{"th":"มาตรา 518"},"chapter":{"th":"ลักษณะ 2"},"text":{"th":"มาตรา ๕๑๘ อันว่าแลกเปลี่ยนนั้น คือสัญญาซึ่งคู่กรณีต่างโอนกรรมสิทธิ์แห่งทรัพย์สินให้กันและกัน"}},{"id":"TH-H004-A519","no":519,"noLabel":{"th":"มาตรา 519"},"chapter":{"th":"ลักษณะ 2"},"text":{"th":"มาตรา ๕๑๙ บทบัญญัติทั้งหลายในลักษณะซื้อขายนั้น ท่านให้ใช้ถึงการแลกเปลี่ยนด้วย โดยให้ถือว่าผู้เป็นคู่สัญญาแลกเปลี่ยนเป็นผู้ขายในส่วนทรัพย์สินซึ่งตนได้ส่งมอบ และเป็นผู้ซื้อในส่วนทรัพย์สินซึ่งตนได้รับในการแลกเปลี่ยนนั้น"}},{"id":"TH-H004-A520","no":520,"noLabel":{"th":"มาตรา 520"},"chapter":{"th":"ลักษณะ 2"},"text":{"th":"มาตรา ๕๒๐ ถ้าคู่สัญญาฝ่ายหนึ่งในสัญญาแลกเปลี่ยนตกลงจะโอนเงินเพิ่มเข้ากับทรัพย์สินสิ่งอื่นให้แก่อีกฝ่ายหนึ่งไซร้ บททั้งหลายอันว่าด้วยราคาในลักษณะซื้อขายนั้น ให้ใช้ถึงเงินเช่นว่านั้นด้วย"}},{"id":"TH-H004-A521","no":521,"noLabel":{"th":"มาตรา 521"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๑ อันว่าให้นั้น คือสัญญาซึ่งบุคคลคนหนึ่งเรียกว่าผู้ให้ โอนทรัพย์สินของตนให้โดยเสน่หาแก่บุคคลอีกคนหนึ่ง เรียกว่าผู้รับ และผู้รับยอมรับเอาทรัพย์สินนั้น"}},{"id":"TH-H004-A522","no":522,"noLabel":{"th":"มาตรา 522"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๒ การให้นั้นจะทำด้วยปลดหนี้ให้แก่ผู้รับ หรือด้วยชำระหนี้ซึ่งผู้รับค้างชำระอยู่ก็ได้"}},{"id":"TH-H004-A523","no":523,"noLabel":{"th":"มาตรา 523"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๓ การให้นั้น ท่านว่าย่อมสมบูรณ์ต่อเมื่อส่งมอบทรัพย์สินที่ให้"}},{"id":"TH-H004-A524","no":524,"noLabel":{"th":"มาตรา 524"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๔ การให้สิทธิอันมีหนังสือตราสารเป็นสำคัญนั้น ถ้ามิได้ส่งมอบตราสารให้แก่ผู้รับ และมิได้มีหนังสือบอกกล่าวแก่ลูกหนี้แห่งสิทธินั้น ท่านว่าการให้ย่อมไม่สมบูรณ์"}},{"id":"TH-H004-A525","no":525,"noLabel":{"th":"มาตรา 525"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๕ การให้ทรัพย์สินซึ่งถ้าจะซื้อขายกันจะต้องทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่นั้น ท่านว่าย่อมสมบูรณ์ต่อเมื่อได้ทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่ ในกรณีเช่นนี้ การให้ย่อมเป็นอันสมบูรณ์โดยมิพักต้องส่งมอบ"}},{"id":"TH-H004-A526","no":526,"noLabel":{"th":"มาตรา 526"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๖ ถ้าการให้ทรัพย์สินหรือให้คำมั่นว่าจะให้ทรัพย์สินนั้นได้ทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่แล้ว และผู้ให้ไม่ส่งมอบทรัพย์สินนั้นแก่ผู้รับไซร้ ท่านว่าผู้รับชอบที่จะเรียกให้ส่งมอบตัวทรัพย์สินหรือราคาแทนทรัพย์สินนั้นได้ แต่ไม่ชอบที่จะเรียกค่าสินไหมทดแทนอย่างหนึ่งอย่างใดด้วยอีกได้"}},{"id":"TH-H004-A527","no":527,"noLabel":{"th":"มาตรา 527"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๗ ถ้าผู้ให้ผูกตนไว้ว่าจะชำระหนี้เป็นคราว ๆ ท่านว่าหนี้นั้นเป็นอันระงับสิ้นไปเมื่อผู้ให้หรือผู้รับตาย เว้นแต่จะขัดกับเจตนาอันปรากฏแต่มูลหนี้"}},{"id":"TH-H004-A528","no":528,"noLabel":{"th":"มาตรา 528"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๘ ถ้าทรัพย์สินซึ่งให้นั้นมีค่าภาระติดพัน และผู้รับละเลยเสียไม่ชำระค่าภาระติดพันนั้นไซร้ ท่านว่าโดยเงื่อนไขอันระบุไว้ในกรณีสิทธิเลิกสัญญาต่างตอบแทนกันนั้น ผู้ให้จะเรียกให้ส่งทรัพย์สินที่ให้นั้นคืนตามบทบัญญัติว่าด้วยคืนลาภมิควรได้นั้นก็ได้ เพียงเท่าที่ควรจะเอาทรัพย์นั้นไปใช้ชำระค่าภาระติดพันนั้น แต่สิทธิเรียกคืนอันนี้ย่อมเป็นอันขาดไป ถ้าบุคคลภายนอกเป็นผู้มีสิทธิจะเรียกให้ชำระค่าภาระติดพันนั้น"}},{"id":"TH-H004-A529","no":529,"noLabel":{"th":"มาตรา 529"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๒๙ ถ้าทรัพย์สินที่ให้มีราคาไม่พอกับการที่จะชำระค่าภาระติดพันไซร้ ท่านว่าผู้รับจะต้องชำระแต่เพียงเท่าราคาทรัพย์สินเท่านั้น"}},{"id":"TH-H004-A530","no":530,"noLabel":{"th":"มาตรา 530"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๐ ถ้าการให้นั้นมีค่าภาระติดพัน ท่านว่าผู้ให้จะต้องรับผิดเพื่อความชำรุดบกพร่องหรือเพื่อการรอนสิทธิเช่นเดียวกันกับผู้ขาย แต่ท่านจำกัดไว้ว่าไม่เกินจำนวนค่าภาระติดพัน"}},{"id":"TH-H004-A531","no":531,"noLabel":{"th":"มาตรา 531"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๑ อันผู้ให้จะเรียกถอนคืนการให้เพราะเหตุผู้รับประพฤติเนรคุณนั้น ท่านว่าอาจจะเรียกได้แต่เพียงในกรณีดังจะกล่าวต่อไปนี้ (๑) ถ้าผู้รับได้ประทุษร้ายต่อผู้ให้เป็นความผิดฐานอาญาอย่างร้ายแรงตามประมวลกฎหมายลักษณะอาญา หรือ (๒) ถ้าผู้รับได้ทำให้ผู้ให้เสียชื่อเสียง หรือหมิ่นประมาทผู้ให้อย่างร้ายแรง หรือ (๓) ถ้าผู้รับได้บอกปัดไม่ยอมให้สิ่งของจำเป็นเลี้ยงชีวิตแก่ผู้ให้ ในเวลาที่ผู้ให้ยากไร้และผู้รับยังสามารถจะให้ได้"}},{"id":"TH-H004-A532","no":532,"noLabel":{"th":"มาตรา 532"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๒ ทายาทของผู้ให้อาจเรียกให้ถอนคืนการให้ได้แต่เฉพาะในเหตุที่ผู้รับได้ฆ่าผู้ให้ตายโดยเจตนาและไม่ชอบด้วยกฎหมาย หรือได้กีดกันผู้ให้ไว้มิให้ถอนคืนการให้ แต่ว่าผู้ให้ได้ฟ้องคดีไว้แล้วอย่างใดโดยชอบ ทายาทของผู้ให้จะว่าคดีอันนั้นต่อไปก็ได้"}},{"id":"TH-H004-A533","no":533,"noLabel":{"th":"มาตรา 533"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๓ เมื่อผู้ให้ได้ให้อภัยแก่ผู้รับในเหตุประพฤติเนรคุณนั้นแล้วก็ดี หรือเมื่อเวลาได้ล่วงไปแล้วหกเดือนนับแต่เหตุเช่นนั้นได้ทราบถึงบุคคลผู้ชอบที่จะเรียกถอนคืนการให้ได้นั้นก็ดี ท่านว่าหาอาจจะถอนคืนการให้ได้ไม่ อนึ่ง ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นเวลาสิบปีภายหลังเหตุการณ์เช่นว่านั้น"}},{"id":"TH-H004-A534","no":534,"noLabel":{"th":"มาตรา 534"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๔ เมื่อถอนคืนการให้ ท่านให้ส่งคืนทรัพย์สินตามบทบัญญัติแห่งประมวลฎหมายนี้ ว่าด้วยลาภมิควรได้"}},{"id":"TH-H004-A535","no":535,"noLabel":{"th":"มาตรา 535"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๕ การให้อันจะกล่าวต่อไปนี้ ท่านว่าจะถอนคืนเพราะเหตุเนรคุณไม่ได้ คือ (๑) ให้เป็นบำเหน็จสินจ้างโดยแท้ (๒) ให้สิ่งที่มีค่าภาระติดพัน (๓) ให้โดยหน้าที่ธรรมจรรยา (๔) ให้ในการสมรส"}},{"id":"TH-H004-A536","no":536,"noLabel":{"th":"มาตรา 536"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๕๓๖ การให้อันจะให้เป็นผลต่อเมื่อผู้ให้ตายนั้น ท่านให้บังคับด้วยบทกฎหมายว่าด้วยมรดกและพินัยกรรม"}},{"id":"TH-H004-A537","no":537,"noLabel":{"th":"มาตรา 537"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๓๗ อันว่าเช่าทรัพย์สินนั้น คือสัญญาซึ่งบุคคลคนหนึ่งเรียกว่า ผู้ให้เช่า ตกลงให้บุคคลอีกคนหนึ่งเรียกว่า ผู้เช่า ได้ใช้หรือได้รับประโยชน์ในทรัพย์สินอย่างใดอย่างหนึ่งชั่วระยะเวลาอันมีจำกัด และผู้เช่าตกลงจะให้ค่าเช่าเพื่อการนั้น"}},{"id":"TH-H004-A538","no":538,"noLabel":{"th":"มาตรา 538"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๓๘ เช่าอสังหาริมทรัพย์นั้น ถ้ามิได้มีหลักฐานเป็นหนังสืออย่างหนึ่งอย่างใดลงลายมือชื่อฝ่ายที่ต้องรับผิดเป็นสำคัญ ท่านว่าจะฟ้องร้องให้บังคับคดีหาได้ไม่ ถ้าเช่ามีกำหนดกว่าสามปีขึ้นไป หรือกำหนดตลอดอายุของผู้เช่าหรือผู้ให้เช่าไซร้ หากมิได้ทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่ ท่านว่าการเช่านั้นจะฟ้องร้องให้บังคับคดีได้แต่เพียงสามปี"}},{"id":"TH-H004-A539","no":539,"noLabel":{"th":"มาตรา 539"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๓๙ ค่าฤชาธรรมเนียมทำสัญญาเช่านั้น คู่สัญญาพึงออกใช้เสมอกันทั้งสองฝ่าย"}},{"id":"TH-H004-A540","no":540,"noLabel":{"th":"มาตรา 540"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๐ อันอสังหาริมทรัพย์ ท่านห้ามมิให้เช่ากันเป็นกำหนดเวลาเกินกว่าสามสิบปี ถ้าได้ทำสัญญากันไว้เป็นกำหนดเวลานานกว่านั้น ท่านก็ให้ลดลงมาเป็นสามสิบปี อนึ่ง กำหนดเวลาเช่าดังกล่าวมานี้ เมื่อสิ้นลงแล้วจะต่อสัญญาอีกก็ได้ แต่ต้องอย่าให้เกินสามสิบปีนับแต่วันต่อสัญญา"}},{"id":"TH-H004-A541","no":541,"noLabel":{"th":"มาตรา 541"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๑ สัญญาเช่านั้นจะทำกันเป็นกำหนดว่าตลอดอายุของผู้ให้เช่าหรือของผู้เช่าก็ให้ทำได้"}},{"id":"TH-H004-A542","no":542,"noLabel":{"th":"มาตรา 542"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๒ บุคคลหลายคนเรียกเอาสังหาริมทรัพย์อันเดียวกันอาศัยมูลสัญญาเช่าต่างราย ท่านว่าทรัพย์ตกไปอยู่ในครอบครองผู้เช่าคนใดก่อนด้วยสัญญาเช่าทรัพย์นั้น คนนั้นมีสิทธิยิ่งกว่าคนอื่น ๆ"}},{"id":"TH-H004-A543","no":543,"noLabel":{"th":"มาตรา 543"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๓ บุคคลหลายคนเรียกร้องเอาอสังหาริมทรัพย์อันเดียวกันอาศัยมูลสัญญาเช่าต่างราย ท่านให้วินิจฉัย ดังต่อไปนี้ (๑) ถ้าการเช่านั้นเป็นประเภทซึ่งมิได้บังคับไว้โดยกฎหมายว่าต้องจดทะเบียน ท่านให้ถือว่าผู้เช่าซึ่งได้ทรัพย์สินไปไว้ในครอบครองก่อนด้วยสัญญาเช่าของตนนั้นมีสิทธิยิ่งกว่าคนอื่น ๆ (๒) ถ้าการเช่าทุก ๆ รายเป็นประเภทซึ่งบังคับไว้โดยกฎหมายว่าต้องจดทะเบียน ท่านให้ถือว่าผู้เช่าซึ่งได้จดทะเบียนการเช่าของตนก่อนนั้นมีสิทธิยิ่งกว่าคนอื่น ๆ (๓) ถ้าการเช่ามีทั้งประเภทซึ่งต้องจดทะเบียนและประเภทซึ่งไม่ต้องจดทะเบียนตามกฎหมายยันกันอยู่ไซร้ ท่านว่าผู้เช่าคนที่ได้จดทะเบียนการเช่าของตนนั้นมีสิทธิยิ่งกว่า เว้นแต่ผู้เช่าคนอื่นจะได้ทรัพย์สินนั้นไปไว้ในครอบครองด้วยการเช่าของตนเสียแต่ก่อนวันจดทะเบียนนั้นแล้ว"}},{"id":"TH-H004-A544","no":544,"noLabel":{"th":"มาตรา 544"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๔ ทรัพย์สินซึ่งเช่านั้น ผู้เช่าจะให้เช่าช่วงหรือโอนสิทธิของตนอันมีในทรัพย์สินนั้นไม่ว่าทั้งหมดหรือแต่บางส่วนให้แก่บุคคลภายนอก ท่านว่าหาอาจทำได้ไม่ เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่นในสัญญาเช่า ถ้าผู้เช่าประพฤติฝ่าฝืนบทบัญญัติอันนี้ ผู้ให้เช่าจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A545","no":545,"noLabel":{"th":"มาตรา 545"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๕๔๕ ถ้าผู้เช่าเอาทรัพย์สินซึ่งตนเช่าไปให้ผู้อื่นเช่าช่วงอีกทอดหนึ่งโดยชอบ ท่านว่าผู้เช่าช่วงย่อมต้องรับผิดต่อผู้ให้เช่าเดิมโดยตรง ในกรณีเช่นว่านี้หากผู้เช่าช่วงจะได้ใช้ค่าเช่าให้แก่ผู้เช่าไปก่อน ท่านว่าผู้เช่าช่วงหาอาจจะยกขึ้นเป็นข้อต่อสู้ผู้ให้เช่าได้ไม่ อนึ่ง บทบัญญัติอันนี้ไม่ห้ามการที่ผู้ให้เช่าจะใช้สิทธิของตนต่อผู้เช่า"}},{"id":"TH-H004-A546","no":546,"noLabel":{"th":"มาตรา 546"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๔๖ ผู้ให้เช่าจำต้องส่งมอบทรัพย์สินซึ่งให้เช่านั้นในสภาพอันซ่อมแซมดีแล้ว"}},{"id":"TH-H004-A547","no":547,"noLabel":{"th":"มาตรา 547"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๔๗ ผู้เช่าต้องเสียค่าใช้จ่ายไปโดยความจำเป็นและสมควรเพื่อรักษาทรัพย์สินซึ่งเช่านั้นเท่าใด ผู้ให้เช่าจำต้องชดใช้ให้แก่ผู้เช่า เว้นแต่ค่าใช้จ่ายเพื่อบำรุงรักษาตามปกติและเพื่อซ่อมแซมเพียงเล็กน้อย"}},{"id":"TH-H004-A548","no":548,"noLabel":{"th":"มาตรา 548"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๔๘ ถ้าผู้ให้เช่าส่งมอบทรัพย์สินซึ่งเช่านั้นโดยสภาพไม่เหมาะแก่การที่จะใช้เพื่อประโยชน์ที่เช่ามา ผู้เช่าจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A549","no":549,"noLabel":{"th":"มาตรา 549"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๔๙ การส่งมอบทรัพย์สินซึ่งเช่าก็ดี ความรับผิดของผู้ให้เช่าในกรณีชำรุดบกพร่องและรอนสิทธิก็ดี ผลแห่งข้อสัญญาว่าจะไม่ต้องรับผิดก็ดี เหล่านี้ ท่านให้บังคับด้วยบทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้ ว่าด้วยการซื้อขายอนุโลมความตามควร"}},{"id":"TH-H004-A550","no":550,"noLabel":{"th":"มาตรา 550"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๕๐ ผู้ให้เช่าย่อมต้องรับผิดในความชำรุดบกพร่องอันเกิดขึ้นในระหว่างเวลาเช่า และผู้ให้เช่าต้องจัดการซ่อมแซมทุกอย่างบรรดาซึ่งเป็นการจำเป็นขึ้น เว้นแต่การซ่อมแซมชนิดซึ่งมีกฎหมายหรือจารีตประเพณีว่าผู้เช่าจะพึงต้องทำเอง"}},{"id":"TH-H004-A551","no":551,"noLabel":{"th":"มาตรา 551"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๕๕๑ ถ้าความชำรุดบกพร่องแห่งทรัพย์สินที่เช่านั้นไม่เป็นเหตุถึงแก่ผู้เช่าจะต้องปราศจากการใช้และประโยชน์ และผู้ให้เช่ายังแก้ไขได้ไซร้ ผู้เช่าต้องบอกกล่าวแก่ผู้ให้เช่าให้จัดการแก้ไขความชำรุดบกพร่องนั้นก่อน ถ้าและผู้ให้เช่าไม่จัดทำให้คืนดีภายในเวลาอันสมควร ผู้เช่าจะบอกเลิกสัญญาเสียก็ได้ หากว่าความชำรุดบกพร่องนั้นร้ายแรงถึงสมควรจะทำเช่นนั้น"}},{"id":"TH-H004-A552","no":552,"noLabel":{"th":"มาตรา 552"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๒ อันผู้เช่าจะใช้ทรัพย์สินที่เช่าเพื่อการอย่างอื่น นอกจากที่ใช้กันตามประเพณีนิยมปกติ หรือการดังกำหนดไว้ในสัญญานั้น ท่านว่าหาอาจจะทำได้ไม่"}},{"id":"TH-H004-A553","no":553,"noLabel":{"th":"มาตรา 553"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๓ ผู้เช่าจำต้องสงวนทรัพย์สินที่เช่านั้นเสมอกับที่วิญญูชนจะพึงสงวนทรัพย์สินของตนเอง และต้องบำรุงรักษาทั้งทำการซ่อมแซมเล็กน้อยด้วย"}},{"id":"TH-H004-A554","no":554,"noLabel":{"th":"มาตรา 554"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๔ ถ้าผู้เช่ากระทำการฝ่าฝืนบทบัญญัติในมาตรา ๕๕๒ มาตรา ๕๕๓ หรือฝ่าฝืนข้อสัญญา ผู้ให้เช่าจะบอกกล่าวให้ผู้เช่าปฏิบัติให้ถูกต้องตามบทกฎหมายหรือข้อสัญญานั้น ๆ ก็ได้ ถ้าและผู้เช่าละเลยเสียไม่ปฏิบัติตาม ท่านว่าผู้ให้เช่าจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A555","no":555,"noLabel":{"th":"มาตรา 555"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๕ ผู้เช่าจำต้องยอมให้ผู้ให้เช่าหรือตัวแทนของผู้ให้เช่าเข้าตรวจดูทรัพย์สินที่เช่าเป็นครั้งคราว ในเวลาและระยะอันสมควร"}},{"id":"TH-H004-A556","no":556,"noLabel":{"th":"มาตรา 556"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๖ ถ้าในระหว่างเวลาเช่ามีเหตุจะต้องซ่อมแซมทรัพย์สินซึ่งเช่านั้นเป็นการเร่งร้อน และผู้ให้เช่าประสงค์จะทำการอันจำเป็นเพื่อที่จะซ่อมแซมเช่นว่านั้นไซร้ ท่านว่าผู้เช่าจะไม่ยอมให้ทำนั้นไม่ได้ แม้ถึงว่าการนั้นจะเป็นความไม่สะดวกแก่ตน ถ้าการซ่อมแซมเป็นสภาพซึ่งต้องกินเวลานานเกินสมควร จนเป็นเหตุให้ทรัพย์สินนั้นไม่เหมาะแก่การที่จะใช้เพื่อประโยชน์ที่เช่ามา ผู้เช่าจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A557","no":557,"noLabel":{"th":"มาตรา 557"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๗ ในกรณีอย่างใด ๆ ดังจะกล่าวต่อไปนี้ คือ (๑) ถ้าทรัพย์สินที่เช่านั้นชำรุดควรที่ผู้ให้เช่าจะต้องซ่อมแซมก็ดี (๒) ถ้าจะต้องจัดการอย่างหนึ่งอย่างใดเพื่อปัดป้องภยันตรายแก่ทรัพย์สินนั้นก็ดี (๓) ถ้าบุคคลภายนอกรุกล้ำเข้ามาในทรัพย์สินที่เช่าหรือเรียกอ้างสิทธิอย่างใดอย่างหนึ่งเหนือทรัพย์สินนั้นก็ดี ในเหตุดังกล่าวนั้นให้ผู้เช่าแจ้งเหตุแก่ผู้ให้เช่าโดยพลัน เว้นแต่ผู้ให้เช่าจะได้ทราบเหตุนั้นอยู่ก่อนแล้ว ถ้าผู้เช่าละเลยเสียไม่ปฏิบัติตามบทบัญญัตินี้ไซร้ ท่านว่าผู้เช่าจะต้องรับผิดต่อผู้ให้เช่าในเมื่อผู้ให้เช่าต้องเสียหายอย่างใด ๆ เพราะความละเลยชักช้าของผู้เช่านั้น"}},{"id":"TH-H004-A558","no":558,"noLabel":{"th":"มาตรา 558"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๘ อันทรัพย์สินที่เช่านั้น ถ้ามิได้รับอนุญาตของผู้ให้เช่าก่อน ผู้เช่าจะทำการดัดแปลงหรือต่อเติมอย่างหนึ่งอย่างใดหาได้ไม่ ถ้าและผู้เช่าทำไปโดยมิได้รับอนุญาตของผู้ให้เช่าเช่นนั้นไซร้ เมื่อผู้ให้เช่าเรียกร้อง ผู้เช่าจะต้องทำให้ทรัพย์สินนั้นกลับคืนคงสภาพเดิม ทั้งจะต้องรับผิดต่อผู้ให้เช่าในความสูญหายหรือบุบสลายอย่างใด ๆ อันเกิดแต่การดัดแปลงต่อเติมนั้นด้วย"}},{"id":"TH-H004-A559","no":559,"noLabel":{"th":"มาตรา 559"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๕๙ ถ้าไม่มีกำหนดโดยสัญญาหรือโดยจารีตประเพณีว่าจะพึงชำระค่าเช่า ณ เวลาใด ท่านให้ชำระเมื่อสิ้นระยะเวลาอันได้ตกลงกำหนดกันไว้ทุกคราวไป กล่าวคือว่าถ้าเช่ากันเป็นรายปีก็พึงชำระค่าเช่าเมื่อสิ้นปี ถ้าเช่ากันเป็นรายเดือนก็พึงชำระค่าเช่าเมื่อสิ้นเดือน"}},{"id":"TH-H004-A560","no":560,"noLabel":{"th":"มาตรา 560"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๖๐ ถ้าผู้เช่าไม่ชำระค่าเช่า ผู้ให้เช่าจะบอกเลิกสัญญาเสียก็ได้ แต่ถ้าค่าเช่านั้นจะพึงส่งเป็นรายเดือน หรือส่งเป็นระยะเวลายาวกว่ารายเดือนขึ้นไป ผู้ให้เช่าต้องบอกกล่าวแก่ผู้เช่าก่อนว่าให้ชำระค่าเช่าภายในเวลาใด ซึ่งพึงกำหนดอย่าให้น้อยกว่าสิบห้าวัน"}},{"id":"TH-H004-A561","no":561,"noLabel":{"th":"มาตรา 561"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๖๑ ถ้ามิได้ทำหนังสือลงลายมือชื่อของคู่สัญญาแสดงไว้ต่อกันว่าทรัพย์สินที่ให้เช่ามีสภาพเป็นอยู่อย่างไร ท่านให้สันนิษฐานไว้ก่อนว่าผู้เช่าได้รับทรัพย์สินที่เช่านั้นไปโดยสภาพอันซ่อมแซมดีแล้ว และเมื่อสัญญาได้เลิกหรือระงับลง ผู้เช่าก็ต้องส่งคืนทรัพย์สินในสภาพเช่นนั้น เว้นแต่จะพิสูจน์ได้ว่าทรัพย์สินนั้นมิได้ซ่อมแซมไว้ดีในขณะที่ส่งมอบ"}},{"id":"TH-H004-A562","no":562,"noLabel":{"th":"มาตรา 562"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๖๒ ผู้เช่าจะต้องรับผิดในความสูญหายหรือบุบสลายอย่างใด ๆ อันเกิดขึ้นแก่ทรัพย์สินที่เช่า เพราะความผิดของผู้เช่าเอง หรือของบุคคลซึ่งอยู่กับผู้เช่า หรือของผู้เช่าช่วง แต่ผู้เช่าไม่ต้องรับผิดในความสูญหายหรือบุบสลายอันเกิดแต่การใช้ทรัพย์สินนั้นโดยชอบ"}},{"id":"TH-H004-A563","no":563,"noLabel":{"th":"มาตรา 563"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๕๖๓ คดีอันผู้ให้เช่าจะฟ้องผู้เช่าเกี่ยวแก่สัญญาเช่านั้น ท่านห้ามมิให้ฟ้องเมื่อพ้นกำหนดหกเดือนนับแต่วันส่งคืนทรัพย์สินที่เช่า"}},{"id":"TH-H004-A564","no":564,"noLabel":{"th":"มาตรา 564"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๔ อันสัญญาเช่านั้น ท่านว่าย่อมระงับไปเมื่อสิ้นกำหนดเวลาที่ได้ตกลงกันไว้ มิพักต้องบอกกล่าวก่อน"}},{"id":"TH-H004-A565","no":565,"noLabel":{"th":"มาตรา 565"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๕ การเช่าถือสวนนั้น ท่านให้สันนิษฐานไว้ก่อนว่าเช่ากันปีหนึ่ง การเช่านาก็ให้สันนิษฐานไว้ก่อนว่าเช่ากันตลอดฤดูทำนาปีหนึ่ง"}},{"id":"TH-H004-A566","no":566,"noLabel":{"th":"มาตรา 566"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๖ ถ้ากำหนดเวลาเช่าไม่ปรากฏในความที่ตกลงกันหรือไม่พึงสันนิษฐานได้ไซร้ ท่านว่าคู่สัญญาฝ่ายใดจะบอกเลิกสัญญาเช่าในขณะเมื่อสุดระยะเวลาอันเป็นกำหนดชำระค่าเช่าก็ได้ทุกระยะ แต่ต้องบอกกล่าวแก่อีกฝ่ายหนึ่งให้รู้ตัวก่อนชั่วกำหนดเวลาชำระค่าเช่าระยะหนึ่งเป็นอย่างน้อย แต่ไม่จำเป็นต้องบอกกล่าวล่วงหน้ากว่าสองเดือน"}},{"id":"TH-H004-A567","no":567,"noLabel":{"th":"มาตรา 567"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๗ ถ้าทรัพย์สินซึ่งให้เช่าสูญหายไปทั้งหมดไซร้ ท่านว่าสัญญาเช่าก็ย่อมระงับไปด้วย"}},{"id":"TH-H004-A568","no":568,"noLabel":{"th":"มาตรา 568"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๘ ถ้าทรัพย์สินซึ่งให้เช่าสูญหายไปแต่เพียงบางส่วน และมิได้เป็นเพราะความผิดของผู้เช่า ท่านว่าผู้เช่าจะเรียกให้ลดค่าเช่าลงตามส่วนที่สูญหายก็ได้ ในกรณีเช่นนี้ ถ้าผู้เช่าไม่สามารถใช้สอยทรัพย์สินส่วนที่ยังคงเหลืออยู่นั้นสำเร็จประโยชน์ได้ดังที่ได้มุ่งหมายเข้าทำสัญญาเช่าไซร้ ท่านว่าผู้เช่าจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A569","no":569,"noLabel":{"th":"มาตรา 569"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๖๙ อันสัญญาเช่าอสังหาริมทรัพย์นั้นย่อมไม่ระงับไป เพราะเหตุโอนกรรมสิทธิ์ทรัพย์สินซึ่งให้เช่า ผู้รับโอนย่อมรับไปทั้งสิทธิและหน้าที่ของผู้โอนซึ่งมีต่อผู้เช่านั้นด้วย"}},{"id":"TH-H004-A570","no":570,"noLabel":{"th":"มาตรา 570"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๗๐ ในเมื่อสิ้นกำหนดเวลาเช่าซึ่งได้ตกลงกันไว้นั้น ถ้าผู้เช่ายังคงครองทรัพย์สินอยู่ และผู้ให้เช่ารู้ความนั้นแล้วไม่ทักท้วงไซร้ ท่านให้ถือว่าคู่สัญญาเป็นอันได้ทำสัญญาใหม่ต่อไปไม่มีกำหนดเวลา"}},{"id":"TH-H004-A571","no":571,"noLabel":{"th":"มาตรา 571"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๕๗๑ ถ้าสัญญาเช่าที่นาได้เลิกหรือระงับลง เมื่อผู้เช่าได้เพาะปลูกข้าวลงแล้วไซร้ ท่านว่าผู้เช่าย่อมมีสิทธิที่จะครองนานั้นต่อไปจนกว่าจะเสร็จการเกี่ยวเก็บ แต่ต้องเสียค่าเช่า"}},{"id":"TH-H004-A572","no":572,"noLabel":{"th":"มาตรา 572"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๕๗๒ อันว่าเช่าซื้อนั้น คือสัญญาซึ่งเจ้าของเอาทรัพย์สินออกให้เช่า และให้คำมั่นว่าจะขายทรัพย์สินนั้นหรือว่าจะให้ทรัพย์สินนั้นตกเป็นสิทธิแก่ผู้เช่า โดยเงื่อนไขที่ผู้เช่าได้ใช้เงินเป็นจำนวนเท่านั้นเท่านี้คราว สัญญาเช่าซื้อนั้นถ้าไม่ทำเป็นหนังสือ ท่านว่าเป็นโมฆะ"}},{"id":"TH-H004-A573","no":573,"noLabel":{"th":"มาตรา 573"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๕๗๓ ผู้เช่าจะบอกเลิกสัญญาในเวลาใดเวลาหนึ่งก็ได้ ด้วยส่งมอบทรัพย์สินกลับคืนให้แก่เจ้าของโดยเสียค่าใช้จ่ายของตนเอง"}},{"id":"TH-H004-A574","no":574,"noLabel":{"th":"มาตรา 574"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๕๗๔ ในกรณีผิดนัดไม่ใช้เงินสองคราวติด ๆ กัน หรือกระทำผิดสัญญาในข้อที่เป็นส่วนสำคัญ เจ้าของทรัพย์สินจะบอกเลิกสัญญาเสียก็ได้ ถ้าเช่นนั้นบรรดาเงินที่ได้ใช้มาแล้วแต่ก่อน ให้ริบเป็นของเจ้าของทรัพย์สิน และเจ้าของทรัพย์สินชอบที่จะกลับเข้าครองทรัพย์สินนั้นได้ด้วย อนึ่ง ในกรณีกระทำผิดสัญญาเพราะผิดนัดไม่ใช้เงินซึ่งเป็นคราวที่สุดนั้น ท่านว่าเจ้าของทรัพย์สินชอบที่จะริบบรรดาเงินที่ได้ใช้มาแล้วแต่ก่อนและกลับเข้าครองทรัพย์สินได้ต่อเมื่อระยะเวลาใช้เงินได้พ้นกำหนดไปอีกงวดหนึ่ง"}},{"id":"TH-H004-A575","no":575,"noLabel":{"th":"มาตรา 575"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๗๕ อันว่าจ้างแรงงานนั้น คือสัญญาซึ่งบุคคลคนหนึ่ง เรียกว่าลูกจ้าง ตกลงจะทำงานให้แก่บุคคลอีกคนหนึ่ง เรียกว่านายจ้าง และนายจ้างตกลงจะให้สินจ้างตลอดเวลาที่ทำงานให้"}},{"id":"TH-H004-A576","no":576,"noLabel":{"th":"มาตรา 576"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๗๖ ถ้าตามพฤติการณ์ไม่อาจจะคาดหมายได้ว่างานนั้นจะพึงทำให้เปล่าไซร้ ท่านย่อมถือเอาโดยปริยายว่ามีคำมั่นจะให้สินจ้าง"}},{"id":"TH-H004-A577","no":577,"noLabel":{"th":"มาตรา 577"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๗๗ นายจ้างจะโอนสิทธิของตนให้แก่บุคคลภายนอกก็ได้เมื่อลูกจ้างยินยอมพร้อมใจด้วย ลูกจ้างจะให้บุคคลภายนอกทำงานแทนตนก็ได้เมื่อนายจ้างยินยอมพร้อมใจด้วย ถ้าคู่สัญญาฝ่ายใดทำการฝ่าฝืนบทบัญญัตินี้ คู่สัญญาอีกฝ่ายหนึ่งจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A578","no":578,"noLabel":{"th":"มาตรา 578"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๗๘ ถ้าลูกจ้างรับรองโดยแสดงออกชัดหรือโดยปริยายว่าตนเป็นผู้มีฝีมือพิเศษ หากมาปรากฏว่าไร้ฝีมือเช่นนั้นไซร้ ท่านว่านายจ้างชอบที่จะบอกเลิกสัญญาเสียได้"}},{"id":"TH-H004-A579","no":579,"noLabel":{"th":"มาตรา 579"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๗๙ การที่ลูกจ้างขาดงานไปโดยเหตุอันสมควรและชั่วระยะเวลาน้อยพอสมควรนั้น ท่านว่าไม่ทำให้นายจ้างมีสิทธิบอกเลิกสัญญาได้"}},{"id":"TH-H004-A580","no":580,"noLabel":{"th":"มาตรา 580"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๐ ถ้าไม่มีกำหนดโดยสัญญาหรือจารีตประเพณีว่าจะพึงจ่ายสินจ้างเมื่อไร ท่านว่าพึงจ่ายเมื่องานได้ทำแล้วเสร็จ ถ้าการจ่ายสินจ้างนั้นได้กำหนดกันไว้เป็นระยะเวลา ก็ให้พึงจ่ายเมื่อสุดระยะเวลาเช่นนั้นทุกคราวไป"}},{"id":"TH-H004-A581","no":581,"noLabel":{"th":"มาตรา 581"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๑ ถ้าระยะเวลาที่ได้ตกลงว่าจ้างกันนั้นสุดสิ้นลงแล้ว ลูกจ้างยังคงทำงานอยู่ต่อไปอีก และนายจ้างรู้ดังนั้นก็ไม่ทักท้วงไซร้ ท่านให้สันนิษฐานไว้ก่อนว่าคู่สัญญาเป็นอันได้ทำสัญญาจ้างกันใหม่โดยความอย่างเดียวกันกับสัญญาเดิม แต่คู่สัญญาฝ่ายใดฝ่ายหนึ่งอาจจะเลิกสัญญาเสียได้ด้วยการบอกกล่าวตามความในมาตราต่อไปนี้"}},{"id":"TH-H004-A582","no":582,"noLabel":{"th":"มาตรา 582"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๒ ถ้าคู่สัญญาไม่ได้กำหนดลงไว้ในสัญญาว่าจะจ้างกันนานเท่าไร ท่านว่าฝ่ายใดฝ่ายหนึ่งจะเลิกสัญญาด้วยการบอกกล่าวล่วงหน้าในเมื่อถึงหรือก่อนจะถึงกำหนดจ่ายสินจ้างคราวใดคราวหนึ่ง เพื่อให้เป็นผลเลิกสัญญากันเมื่อถึงกำหนดจ่ายสินจ้างคราวถัดไปข้างหน้าก็อาจทำได้ แต่ไม่จำต้องบอกกล่าวล่วงหน้ากว่าสามเดือน อนึ่ง ในเมื่อบอกกล่าวดังว่านี้ นายจ้างจะจ่ายสินจ้างแก่ลูกจ้างเสียให้ครบจำนวนที่จะต้องจ่ายจนถึงเวลาเลิกสัญญาตามกำหนดที่บอกกล่าวนั้นทีเดียว แล้วปล่อยลูกจ้างจากงานเสียในทันทีก็อาจทำได้"}},{"id":"TH-H004-A583","no":583,"noLabel":{"th":"มาตรา 583"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๓ ถ้าลูกจ้างจงใจขัดคำสั่งของนายจ้างอันชอบด้วยกฎหมายก็ดี หรือละเลยไม่นำพาต่อคำสั่งเช่นว่านั้นเป็นอาจิณก็ดี ละทิ้งการงานไปเสียก็ดี กระทำความผิดอย่างร้ายแรงก็ดี หรือทำประการอื่นอันไม่สมแก่การปฏิบัติหน้าที่ของตนให้ลุล่วงไปโดยถูกต้องและสุจริตก็ดี ท่านว่านายจ้างจะไล่ออกโดยมิพักต้องบอกกล่าวล่วงหน้าหรือให้สินไหมทดแทนก็ได้"}},{"id":"TH-H004-A584","no":584,"noLabel":{"th":"มาตรา 584"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๔ ถ้าจ้างแรงงานรายใดมีสาระสำคัญอยู่ที่ตัวบุคคลผู้เป็นนายจ้าง ท่านว่าสัญญาจ้างเช่นนั้นย่อมระงับไปด้วยมรณะแห่งนายจ้าง"}},{"id":"TH-H004-A585","no":585,"noLabel":{"th":"มาตรา 585"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๕ เมื่อการจ้างแรงงานสุดสิ้นลงแล้ว ลูกจ้างชอบที่จะได้รับใบสำคัญแสดงว่าลูกจ้างนั้นได้ทำงานมานานเท่าไรและงานที่ทำนั้นเป็นงานอย่างไร"}},{"id":"TH-H004-A586","no":586,"noLabel":{"th":"มาตรา 586"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๕๘๖ ถ้าลูกจ้างเป็นผู้ซึ่งนายจ้างได้จ้างเอามาแต่ต่างถิ่นโดยนายจ้างออกเงินค่าเดินทางให้ไซร้ เมื่อการจ้างแรงงานสุดสิ้นลง และถ้ามิได้กำหนดกันไว้เป็นอย่างอื่นในสัญญาแล้ว ท่านว่านายจ้างจำต้องใช้เงินค่าเดินทางขากลับให้ แต่จะต้องเป็นดังต่อไปนี้ คือ (๑) สัญญามิได้เลิกหรือระงับเพราะการกระทำหรือความผิดของลูกจ้าง และ (๒) ลูกจ้างกลับไปยังถิ่นที่ได้จ้างเอามาภายในเวลาอันสมควร"}},{"id":"TH-H004-A587","no":587,"noLabel":{"th":"มาตรา 587"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๘๗ อันว่าจ้างทำของนั้น คือสัญญาซึ่งบุคคลคนหนึ่ง เรียกว่าผู้รับจ้าง ตกลงรับจะทำการงานสิ่งใดสิ่งหนึ่งจนสำเร็จให้แก่บุคคลอีกคนหนึ่ง เรียกว่าผู้ว่าจ้าง และผู้ว่าจ้างตกลงจะให้สินจ้างเพื่อผลสำเร็จแห่งการที่ทำนั้น"}},{"id":"TH-H004-A588","no":588,"noLabel":{"th":"มาตรา 588"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๘๘ เครื่องมือต่าง ๆ สำหรับใช้ทำการงานให้สำเร็จนั้น ผู้รับจ้างเป็นผู้จัดหา"}},{"id":"TH-H004-A589","no":589,"noLabel":{"th":"มาตรา 589"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๘๙ ถ้าสัมภาระสำหรับทำการงานที่กล่าวนั้นผู้รับจ้างเป็นผู้จัดหา ท่านว่าต้องจัดหาชนิดที่ดี"}},{"id":"TH-H004-A590","no":590,"noLabel":{"th":"มาตรา 590"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๐ ถ้าสัมภาระนั้นผู้ว่าจ้างเป็นผู้จัดหามาส่ง ท่านให้ผู้รับจ้างใช้สัมภาระด้วยความระมัดระวังและประหยัดอย่าให้เปลืองเสียเปล่า เมื่อทำการงานสำเร็จแล้ว มีสัมภาระเหลืออยู่ก็ให้คืนแก่ผู้ว่าจ้าง"}},{"id":"TH-H004-A591","no":591,"noLabel":{"th":"มาตรา 591"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๑ ถ้าความชำรุดบกพร่องหรือความชักช้าในการที่ทำนั้นเกิดขึ้นเพราะสภาพแห่งสัมภาระซึ่งผู้ว่าจ้างส่งให้ก็ดี เพราะคำสั่งของผู้ว่าจ้างก็ดี ท่านว่าผู้รับจ้างไม่ต้องรับผิด เว้นแต่จะได้รู้อยู่แล้วว่าสัมภาระนั้นไม่เหมาะ หรือว่าคำสั่งนั้นไม่ถูกต้องและมิได้บอกกล่าวตักเตือน"}},{"id":"TH-H004-A592","no":592,"noLabel":{"th":"มาตรา 592"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๒ ผู้รับจ้างจำต้องยอมให้ผู้ว่าจ้างหรือตัวแทนของผู้ว่าจ้างตรวจตราการงานได้ตลอดเวลาที่ทำอยู่นั้น"}},{"id":"TH-H004-A593","no":593,"noLabel":{"th":"มาตรา 593"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๓ ถ้าผู้รับจ้างไม่เริ่มทำการในเวลาอันควร หรือทำการชักช้าฝ่าฝืนข้อกำหนดแห่งสัญญาก็ดี หรือทำการชักช้าโดยปราศจากความผิดของผู้ว่าจ้าง จนอาจคาดหมายล่วงหน้าได้ว่าการนั้นจะไม่สำเร็จภายในกำหนดเวลาที่ได้ตกลงกันไว้ก็ดี ผู้ว่าจ้างชอบที่จะเลิกสัญญาเสียได้ มิพักต้องรอคอยให้ถึงเวลากำหนดส่งมอบของนั้นเลย"}},{"id":"TH-H004-A594","no":594,"noLabel":{"th":"มาตรา 594"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๔ ถ้าในระหว่างเวลาที่ทำการอยู่นั้นเป็นวิสัยจะคาดหมายล่วงหน้าได้แน่นอนว่า การที่ทำนั้นจะสำเร็จอย่างบกพร่องหรือจะเป็นไปในทางอันฝ่าฝืนข้อสัญญาเพราะความผิดของผู้รับจ้างไซร้ ผู้ว่าจ้างจะบอกกล่าวให้ผู้รับจ้างแก้ไขสิ่งที่บกพร่องให้คืนดี หรือทำการให้เป็นไปตามสัญญา ภายในเวลาอันสมควรซึ่งกำหนดให้ในคำบอกกล่าวนั้นก็ได้ ถ้าและคลาดกำหนดนั้นไป ท่านว่าผู้ว่าจ้างชอบที่จะเอาการนั้นให้บุคคลภายนอกซ่อมแซมหรือทำต่อไปได้ ซึ่งผู้รับจ้างจะต้องเสี่ยงความเสียหายและออกค่าใช้จ่ายทั้งสิ้น"}},{"id":"TH-H004-A595","no":595,"noLabel":{"th":"มาตรา 595"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๕ ถ้าผู้รับจ้างเป็นผู้จัดหาสัมภาระไซร้ ความรับผิดของผู้รับจ้างในการบกพร่องนั้น ท่านให้บังคับด้วยบทแห่งประมวลกฎหมายนี้ ลักษณะซื้อขาย"}},{"id":"TH-H004-A596","no":596,"noLabel":{"th":"มาตรา 596"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๖ ถ้าผู้รับจ้างส่งมอบการที่ทำไม่ทันเวลาที่ได้กำหนดไว้ในสัญญาก็ดี หรือถ้าไม่ได้กำหนดเวลาไว้ในสัญญาเมื่อล่วงพ้นเวลาอันสมควรแก่เหตุก็ดี ผู้ว่าจ้างชอบที่จะได้ลดสินจ้างลง หรือถ้าสาระสำคัญแห่งสัญญาอยู่ที่เวลา ก็ชอบที่จะเลิกสัญญาได้"}},{"id":"TH-H004-A597","no":597,"noLabel":{"th":"มาตรา 597"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๗ ถ้าผู้ว่าจ้างยอมรับมอบการที่ทำนั้นแล้วโดยมิได้อิดเอื้อน ผู้รับจ้างก็ไม่ต้องรับผิดเพื่อการที่ส่งมอบเนิ่นช้า"}},{"id":"TH-H004-A598","no":598,"noLabel":{"th":"มาตรา 598"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๘ ถ้าผู้ว่าจ้างยอมรับมอบการที่ทำนั้นแล้วทั้งชำรุดบกพร่องมิได้อิดเอื้อนโดยแสดงออกชัดหรือโดยปริยาย ผู้รับจ้างก็ไม่ต้องรับผิด เว้นแต่ความชำรุดบกพร่องนั้นเป็นเช่นจะไม่พึงพบได้ในขณะเมื่อรับมอบ หรือผู้รับจ้างได้ปิดบังความนั้นเสีย"}},{"id":"TH-H004-A599","no":599,"noLabel":{"th":"มาตรา 599"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๕๙๙ ในกรณีที่ส่งมอบเนิ่นช้าไปก็ดี หรือส่งมอบการที่ทำชำรุดบกพร่องก็ดี ท่านว่าผู้ว่าจ้างชอบที่จะยึดหน่วงสินจ้างไว้ได้ เว้นแต่ผู้รับจ้างจะให้ประกันตามสมควร"}},{"id":"TH-H004-A600","no":600,"noLabel":{"th":"มาตรา 600"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๐ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในสัญญาไซร้ ท่านว่าผู้รับจ้างจะต้องรับผิดเพื่อการที่ทำชำรุดบกพร่องเพียงแต่ที่ปรากฏขึ้นภายในปีหนึ่งนับแต่วันส่งมอบ หรือที่ปรากฏขึ้นภายในห้าปี ถ้าการที่ทำนั้นเป็นสิ่งปลูกสร้างกับพื้นดิน นอกจากเรือนโรงทำด้วยเครื่องไม้ แต่ข้อจำกัดนี้ท่านมิให้ใช้บังคับเมื่อปรากฏว่าผู้รับจ้างได้ปิดบังความชำรุดบกพร่องนั้น"}},{"id":"TH-H004-A601","no":601,"noLabel":{"th":"มาตรา 601"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๑ ท่านห้ามมิให้ฟ้องผู้รับจ้างเมื่อพ้นปีหนึ่งนับแต่วันการชำรุดบกพร่องได้ปรากฏขึ้น"}},{"id":"TH-H004-A602","no":602,"noLabel":{"th":"มาตรา 602"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๒ อันสินจ้างนั้นพึงใช้ให้เมื่อรับมอบการที่ทำ ถ้าการที่ทำนั้นมีกำหนดว่าจะส่งรับกันเป็นส่วน ๆ และได้ระบุจำนวนสินจ้างไว้เป็นส่วน ๆ ไซร้ ท่านว่าพึงใช้สินจ้างเพื่อการแต่ละส่วนในเวลารับเอาส่วนนั้น"}},{"id":"TH-H004-A603","no":603,"noLabel":{"th":"มาตรา 603"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๓ ถ้าผู้รับจ้างเป็นผู้จัดหาสัมภาระ และการที่จ้างทำนั้นพังทลายหรือบุบสลายลงก่อนได้ส่งมอบกันถูกต้องไซร้ ท่านว่าความวินาศอันนั้นตกเป็นพับแก่ผู้รับจ้าง หากความวินาศนั้นมิได้เป็นเพราะการกระทำของผู้ว่าจ้าง ในกรณีเช่นว่านี้ สินจ้างก็เป็นอันไม่ต้องใช้"}},{"id":"TH-H004-A604","no":604,"noLabel":{"th":"มาตรา 604"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๔ ถ้าผู้ว่าจ้างเป็นผู้จัดหาสัมภาระ และการที่จ้างทำนั้นพังทลายหรือบุบสลายลงก่อนได้ส่งมอบกันถูกต้องไซร้ ท่านว่าความวินาศนั้นตกเป็นพับแก่ผู้ว่าจ้าง หากความวินาศนั้นมิได้เป็นเพราะการกระทำของผู้รับจ้าง ในกรณีเช่นว่านี้ สินจ้างก็เป็นอันไม่ต้องใช้ เว้นแต่ความวินาศนั้นเป็นเพราะการกระทำของผู้ว่าจ้าง"}},{"id":"TH-H004-A605","no":605,"noLabel":{"th":"มาตรา 605"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๕ ถ้าการที่จ้างยังทำไม่แล้วเสร็จอยู่ตราบใด ผู้ว่าจ้างอาจบอกเลิกสัญญาได้ เมื่อเสียค่าสินไหมทดแทนให้แก่ผู้รับจ้างเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่การเลิกสัญญานั้น"}},{"id":"TH-H004-A606","no":606,"noLabel":{"th":"มาตรา 606"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๖ ถ้าสาระสำคัญแห่งสัญญาอยู่ที่ความรู้ความสามารถของตัวผู้รับจ้างและผู้รับจ้างตายก็ดี หรือตกเป็นผู้ไม่สามารถทำการที่รับจ้างนั้นต่อไปได้ด้วยมิใช่เพราะความผิดของตนก็ดี ท่านว่าสัญญานั้นย่อมเป็นอันสิ้นลง ถ้าและการส่วนที่ได้ทำขึ้นแล้วนั้นเป็นประโยชน์แก่ผู้ว่าจ้างไซร้ ท่านว่าผู้ว่าจ้างจำต้องรับเอาไว้และใช้สินจ้างตามสมควรแก่ส่วนนั้น ๆ"}},{"id":"TH-H004-A607","no":607,"noLabel":{"th":"มาตรา 607"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๖๐๗ ผู้รับจ้างจะเอาการที่รับจ้างทั้งหมดหรือแบ่งการแต่บางส่วนไปให้ผู้รับจ้างช่วงทำอีกทอดหนึ่งก็ได้ เว้นแต่สาระสำคัญแห่งสัญญานั้นจะอยู่ที่ความรู้ความสามารถของตัวผู้รับจ้าง แต่ผู้รับจ้างคงต้องรับผิดเพื่อความประพฤติหรือความผิดอย่างใด ๆ ของผู้รับจ้างช่วง"}},{"id":"TH-H004-A608","no":608,"noLabel":{"th":"มาตรา 608"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๖๐๘ อันว่าผู้ขนส่งภายในความหมายแห่งกฎหมายลักษณะนี้ คือบุคคลผู้รับขนส่งของหรือคนโดยสารเพื่อบำเหน็จเป็นทางค้าปกติของตน"}},{"id":"TH-H004-A609","no":609,"noLabel":{"th":"มาตรา 609"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๖๐๙ การรับขนของหรือคนโดยสารในหน้าที่ของกรมรถไฟหลวงแห่งกรุงสยาม และการขนไปรษณียภัณฑ์ในหน้าที่กรมไปรษณีย์โทรเลขนั้น ท่านให้บังคับตามกฎหมายและกฎข้อบังคับสำหรับทบวงการนั้น ๆ รับขนของทางทะเล ท่านให้บังคับตามกฎหมายและกฎข้อบังคับว่าด้วยการนั้น"}},{"id":"TH-H004-A610","no":610,"noLabel":{"th":"มาตรา 610"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๐ อันบุคคลผู้ทำความตกลงกับผู้ขนส่งเพื่อให้ขนของส่งไปนั้น เรียกว่าผู้ส่ง หรือผู้ตราส่ง บุคคลผู้ซึ่งเขาส่งของไปถึงนั้น เรียกว่าผู้รับตราส่ง บำเหน็จอันจะต้องจ่ายให้เพื่อการขนส่งของนั้น เรียกว่าค่าระวางพาหนะ"}},{"id":"TH-H004-A611","no":611,"noLabel":{"th":"มาตรา 611"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๑ อันว่าอุปกรณ์แห่งค่าระวางพาหนะนั้น ได้แก่ค่าใช้จ่ายอย่างใด ๆ ตามจารีตประเพณีอันผู้ขนส่งได้เสียไปโดยควรในระหว่างขนส่ง"}},{"id":"TH-H004-A612","no":612,"noLabel":{"th":"มาตรา 612"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๒ ถ้าผู้ขนส่งเรียกเอาใบกำกับของ ผู้ส่งต้องทำให้ ใบกำกับของนั้นต้องแสดงรายการต่อไปนี้ คือ (๑) สภาพและน้ำหนัก หรือขนาดแห่งของที่ส่ง กับสภาพ จำนวน และเครื่องหมายแห่งหีบห่อ (๒) ตำบลที่กำหนดให้ส่ง (๓) ชื่อหรือยี่ห้อ และสำนักของผู้รับตราส่ง (๔) ตำบลและวันที่ออกใบกำกับของนั้น อนึ่ง ใบกำกับของนั้นต้องลงลายมือชื่อผู้ส่งเป็นสำคัญ"}},{"id":"TH-H004-A613","no":613,"noLabel":{"th":"มาตรา 613"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๓ ถ้าผู้ส่งเรียกเอาใบตราส่ง ผู้ขนส่งก็ต้องทำให้ ใบตราส่งนั้นต้องแสดงรายการต่อไปนี้ คือ (๑) รายการดังกล่าวไว้ในมาตรา ๖๑๒ (๑) (๒) และ (๓) (๒) ชื่อหรือยี่ห้อของผู้ส่ง (๓) จำนวนค่าระวางพาหนะ (๔) ตำบลและวันที่ออกใบตราส่ง อนึ่ง ใบตราส่งนั้นต้องลงลายมือชื่อผู้ขนส่งเป็นสำคัญ"}},{"id":"TH-H004-A614","no":614,"noLabel":{"th":"มาตรา 614"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๔ แม้ว่าใบตราส่งจะได้ออกให้แก่บุคคลผู้ใดโดยนามก็ตาม ท่านว่าย่อมสลักหลังโอนให้กันได้ เว้นแต่จะมีข้อห้ามการสลักหลังไว้"}},{"id":"TH-H004-A615","no":615,"noLabel":{"th":"มาตรา 615"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๕ ถ้าได้ทำใบตราส่งให้แก่กัน ท่านว่าของนั้นจะรับมอบเอาไปได้ต่อเมื่อเวนคืนใบตราส่ง หรือเมื่อผู้รับตราส่งให้ประกันตามควร"}},{"id":"TH-H004-A616","no":616,"noLabel":{"th":"มาตรา 616"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๖ ผู้ขนส่งจะต้องรับผิดในการที่ของอันเขาได้มอบหมายแก่ตนนั้นสูญหายหรือบุบสลายหรือส่งมอบชักช้า เว้นแต่จะพิสูจน์ได้ว่าการสูญหายหรือบุบสลายหรือชักช้านั้นเกิดแต่เหตุสุดวิสัย หรือเกิดแต่สภาพแห่งของนั้นเอง หรือเกิดเพราะความผิดของผู้ส่งหรือผู้รับตราส่ง"}},{"id":"TH-H004-A617","no":617,"noLabel":{"th":"มาตรา 617"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๗ ผู้ขนส่งจะต้องรับผิดในการที่ของสูญหายหรือบุบสลายหรือส่งชักช้า อันเกิดแต่ความผิดของผู้ขนส่งคนอื่น หรือบุคคลอื่นซึ่งตนหากได้มอบหมายของนั้นไปอีกทอดหนึ่ง"}},{"id":"TH-H004-A618","no":618,"noLabel":{"th":"มาตรา 618"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๘ ถ้าของนั้นได้ส่งไปโดยมีผู้ขนส่งหลายคนหลายทอด ท่านว่าผู้ขนส่งทั้งนั้นจะต้องรับผิดร่วมกันในการสูญหาย บุบสลาย หรือส่งชักช้า"}},{"id":"TH-H004-A619","no":619,"noLabel":{"th":"มาตรา 619"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๑๙ ถ้าของเป็นสภาพอันจะก่อให้เกิดอันตรายได้ หรือเป็นสภาพเกลือกจะก่อให้เกิดเสียหายแก่บุคคลหรือทรัพย์สินไซร้ ผู้ส่งต้องแสดงสภาพแห่งของนั้นไว้ก่อนทำสัญญา ถ้ามิได้ทำเช่นนั้นผู้ส่งจะต้องรับผิดในการเสียหายไม่ว่าอย่างใด ๆ อันเกิดแต่ของนั้น"}},{"id":"TH-H004-A620","no":620,"noLabel":{"th":"มาตรา 620"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๐ ผู้ขนส่งไม่ต้องรับผิดในเงินทองตรา ธนบัตร ธนาคารบัตร ตั๋วเงิน พันธบัตร ใบหุ้น ใบหุ้นกู้ ประทวนสินค้า อัญมณี และของมีค่าอย่างอื่น ๆ หากมิได้รับบอกราคาหรือสภาพแห่งของไว้ในขณะที่ส่งมอบแก่ตน แต่ถ้าของนั้นได้บอกราคา ท่านว่าความรับผิดของผู้ขนส่งก็ย่อมจำกัดเพียงไม่เกินราคาที่บอก"}},{"id":"TH-H004-A621","no":621,"noLabel":{"th":"มาตรา 621"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๑ ค่าสินไหมทดแทนในการส่งมอบของชักช้านั้น ท่านห้ามมิให้คิดเกินกว่าจำนวนเช่นจะพึงกำหนดให้ในเหตุของสูญหายสิ้นเชิง"}},{"id":"TH-H004-A622","no":622,"noLabel":{"th":"มาตรา 622"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๒ ของถึงเมื่อใด ผู้ขนส่งต้องบอกกล่าวแก่ผู้รับตราส่ง"}},{"id":"TH-H004-A623","no":623,"noLabel":{"th":"มาตรา 623"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๓ ความรับผิดของผู้ขนส่งย่อมสุดสิ้นลงในเมื่อผู้รับตราส่งได้รับเอาของไว้แล้วโดยไม่อิดเอื้อน และได้ใช้ค่าระวางพาหนะกับทั้งอุปกรณ์เสร็จแล้ว แต่ความที่กล่าวนี้ท่านมิให้ใช้บังคับในกรณีที่ของสูญหายหรือบุบสลายเห็นไม่ได้แต่สภาพภายนอกแห่งของนั้น หากว่าได้บอกกล่าวความสูญหายหรือบุบสลายแก่ผู้ขนส่งภายในแปดวันนับแต่วันส่งมอบ อนึ่ง บทบัญญัติทั้งหลายนี้ท่านมิให้ใช้บังคับในกรณีที่มีการทุจริตหรือประมาทเลินเล่ออย่างร้ายแรงอันจะปรับเอาเป็นความผิดของผู้ขนส่งได้"}},{"id":"TH-H004-A624","no":624,"noLabel":{"th":"มาตรา 624"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๔ ในข้อความรับผิดของผู้ขนส่งในการที่ของสูญหายหรือบุบสลายหรือส่งของชักช้านั้น ท่านห้ามมิให้ฟ้องเมื่อพ้นกำหนดปีหนึ่งนับแต่ส่งมอบ หรือปีหนึ่งนับแต่วันที่ควรจะได้ส่งมอบ เว้นแต่ในกรณีที่มีการทุจริต"}},{"id":"TH-H004-A625","no":625,"noLabel":{"th":"มาตรา 625"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๕ ใบรับ ใบตราส่ง หรือเอกสารอื่น ๆ ทำนองนั้นก็ดี ซึ่งผู้ขนส่งออกให้แก่ผู้ส่งนั้น ถ้ามีข้อความยกเว้นหรือจำกัดความรับผิดของผู้ขนส่งประการใด ท่านว่าความนั้นเป็นโมฆะ เว้นแต่ผู้ส่งจะได้แสดงความตกลงด้วยชัดแจ้งในการยกเว้นหรือจำกัดความรับผิดเช่นว่านั้น"}},{"id":"TH-H004-A626","no":626,"noLabel":{"th":"มาตรา 626"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๖ ตราบใดของยังอยู่ในมือผู้ขนส่ง ตราบนั้นผู้ส่ง หรือถ้าได้ทำใบตราส่ง ผู้ทรงใบตราส่งนั้น อาจจะให้ผู้ขนส่งงดการส่งของนั้นไป หรือให้ส่งกลับคืนมา หรือให้จัดการแก่ของนั้นเป็นอย่างอื่นประการใดก็ได้ ในเหตุเช่นนี้ ผู้ขนส่งชอบที่จะได้รับเงินค่าระวางพาหนะตามส่วนแห่งระยะทางที่ได้จัดการขนส่งไปแล้ว กับทั้งค่าใช้จ่ายอื่น ๆ ที่ต้องเสียไปเพราะเหตุที่บอกงดหรือเพราะส่งของกลับคืน หรือเพราะจัดการเป็นประการอื่นนั้น"}},{"id":"TH-H004-A627","no":627,"noLabel":{"th":"มาตรา 627"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๗ เมื่อของถึงตำบลที่กำหนดให้ส่ง และผู้รับตราส่งได้เรียกให้ส่งมอบแล้ว ท่านว่าแต่นั้นไปสิทธิทั้งหลายของผู้ส่งอันเกิดแต่สัญญารับขนนั้นย่อมตกไปได้แก่ผู้รับตราส่ง"}},{"id":"TH-H004-A628","no":628,"noLabel":{"th":"มาตรา 628"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๘ ถ้าว่าของสูญหายไปเพราะเหตุสุดวิสัย ท่านว่าผู้ขนส่งไม่มีสิทธิจะได้เงินค่าระวางพาหนะ ถ้าและได้รับไปก่อนแล้วเท่าใดต้องส่งคืนจงสิ้น"}},{"id":"TH-H004-A629","no":629,"noLabel":{"th":"มาตรา 629"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๒๙ ถ้าผู้ขนส่งคนใดส่งมอบของเสียแต่ก่อนได้รับค่าระวางพาหนะและอุปกรณ์ไซร้ ท่านว่าผู้ขนส่งคนนั้นยังคงต้องรับผิดต่อผู้ขนส่งก่อน ๆ ตนเพื่อค่าระวางพาหนะและอุปกรณ์ซึ่งยังค้างชำระแก่เขา"}},{"id":"TH-H004-A630","no":630,"noLabel":{"th":"มาตรา 630"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๓๐ ผู้ขนส่งชอบที่จะยึดหน่วงเอาของไว้ก่อนได้ตามที่จำเป็น เพื่อประกันการใช้เงินค่าระวางพาหนะและอุปกรณ์"}},{"id":"TH-H004-A631","no":631,"noLabel":{"th":"มาตรา 631"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๓๑ ถ้าหาตัวผู้รับตราส่งไม่พบก็ดี หรือถ้าผู้รับตราส่งบอกปัดไม่ยอมรับมอบของก็ดี ผู้ขนส่งต้องบอกกล่าวไปยังผู้ส่งทันที และถามเอาคำสั่งของผู้ส่ง ถ้าหากว่าพฤติการณ์ขัดขวางไม่สามารถจะทำได้ดังนี้ก็ดี หรือถ้าผู้ส่งละเลยเสียไม่ส่งคำสั่งมาในเวลาอันควรก็ดี หรือส่งมาเป็นคำสั่งอันไม่อาจปฏิบัติให้เป็นไปได้ก็ดี ท่านว่าผู้ขนส่งมีอำนาจที่จะเอาของไปฝากไว้ ณ สำนักงานฝากทรัพย์ได้ ถ้าของนั้นเป็นลหุภัณฑ์ของสดเสียได้ และการหน่วงช้าไว้ย่อมเป็นการเสี่ยงความเสียหายก็ดี หรือถ้าราคาของนั้นดูไม่น่าจะคุ้มค่าระวางพาหนะและอุปกรณ์ก็ดี ผู้ขนส่งจะเอาของนั้นออกขายทอดตลาดเสียก็ได้ อนึ่ง การเอาของไปฝากหรือเอาออกขายทอดตลาดเช่นว่านั้น ผู้ขนส่งต้องบอกกล่าวแก่ผู้ส่งหรือผู้รับตราส่งมิให้ชักช้า เว้นแต่ไม่สามารถจะทำได้ ถ้าและผู้ขนส่งละเลยเสียไม่บอกกล่าวไซร้ ท่านว่าจะต้องรับผิดใช้ค่าเสียหาย"}},{"id":"TH-H004-A632","no":632,"noLabel":{"th":"มาตรา 632"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๓๒ เมื่อเอาของออกขายทอดตลาดแล้วได้เงินจำนวนสุทธิเท่าใด ให้ผู้ขนส่งหักเอาไว้เป็นค่าระวางพาหนะและค่าอุปกรณ์ ถ้าและยังมีเงินเหลืออยู่อีกเท่าใด ต้องส่งมอบให้แก่บุคคลผู้ควรที่จะได้เงินนั้นโดยพลัน"}},{"id":"TH-H004-A633","no":633,"noLabel":{"th":"มาตรา 633"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๓๓ ถ้าของนั้นได้ขนส่งไปโดยมีผู้ขนส่งหลายคนหลายทอด ท่านว่าผู้ขนส่งทอดหลังที่สุดอาจใช้สิทธิดังกล่าวในมาตรา ๖๓๐ มาตรา ๖๓๑ มาตรา ๖๓๒ นั้น ในการเรียกเงินค่าระวางพาหนะและอุปกรณ์อันค้างชำระแก่ผู้ขนส่งทั่วทุกคนได้"}},{"id":"TH-H004-A634","no":634,"noLabel":{"th":"มาตรา 634"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๔ ผู้ขนส่งจะต้องรับผิดต่อคนโดยสารในความเสียหายอันเกิดแก่ตัวเขา หรือในความเสื่อมเสียอย่างใด ๆ อันเป็นผลโดยตรงแต่การที่ต้องชักช้าในการขนส่ง เว้นแต่การเสียหายหรือชักช้านั้นเกิดแต่เหตุสุดวิสัยหรือเกิดแต่ความผิดของคนโดยสารนั้นเอง"}},{"id":"TH-H004-A635","no":635,"noLabel":{"th":"มาตรา 635"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๕ เครื่องเดินทางหากได้มอบหมายแก่ผู้ขนส่งทันเวลา ท่านว่าต้องส่งมอบในขณะคนโดยสารถึง"}},{"id":"TH-H004-A636","no":636,"noLabel":{"th":"มาตรา 636"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๖ ถ้าคนโดยสารไม่รับมอบเครื่องเดินทางของตนภายในเวลาเดือนหนึ่งนับแต่วันเครื่องเดินทางนั้นถึงไซร้ ผู้ขนส่งอาจเอาออกขายทอดตลาดเสียได้ ถ้าเครื่องเดินทางนั้นมีสภาพเป็นของสดของเสียได้ ผู้ขนส่งอาจเอาออกขายทอดตลาดได้ เมื่อของนั้นถึงแล้วรออยู่ล่วงเวลากว่ายี่สิบสี่ชั่วโมง บทบัญญัติในมาตรา ๖๓๒ นั้น ท่านให้ใช้บังคับแก่คดีดังว่านี้ด้วยอนุโลมตามควร"}},{"id":"TH-H004-A637","no":637,"noLabel":{"th":"มาตรา 637"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๗ สิทธิและความรับผิดของผู้ขนส่งเพื่อเครื่องเดินทางอันได้มอบหมายแก่ผู้ขนส่งนั้น แม้ผู้ขนส่งจะมิได้คิดเอาค่าขนส่งต่างหากก็ตาม ท่านให้บังคับตามความในหมวด ๑"}},{"id":"TH-H004-A638","no":638,"noLabel":{"th":"มาตรา 638"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๘ ผู้ขนส่งไม่ต้องรับผิดในเครื่องเดินทางซึ่งตนมิได้รับมอบหมาย เว้นแต่เมื่อเครื่องเดินทางนั้นสูญหายหรือบุบสลายไปเพราะความผิดของผู้ขนส่งหรือลูกจ้างของผู้ขนส่ง"}},{"id":"TH-H004-A639","no":639,"noLabel":{"th":"มาตรา 639"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๓๙ ตั๋ว ใบรับ หรือเอกสารอื่นทำนองเช่นว่านี้อันผู้ขนส่งได้ส่งมอบแก่คนโดยสารนั้น หากมีข้อความยกเว้นหรือจำกัดความรับผิดของผู้ขนส่งอย่างใด ๆ ท่านว่าข้อความนั้นเป็นโมฆะ เว้นแต่คนโดยสารจะได้ตกลงด้วยชัดแจ้งในการยกเว้นหรือจำกัดความรับผิดเช่นนั้น"}},{"id":"TH-H004-A640","no":640,"noLabel":{"th":"มาตรา 640"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๐ อันว่ายืมใช้คงรูปนั้น คือสัญญาซึ่งบุคคลคนหนึ่ง เรียกว่าผู้ให้ยืม ให้บุคคลอีกคนหนึ่ง เรียกว่าผู้ยืม ใช้สอยทรัพย์สินสิ่งใดสิ่งหนึ่งได้เปล่า และผู้ยืมตกลงว่าจะคืนทรัพย์สินนั้น เมื่อได้ใช้สอยเสร็จแล้ว"}},{"id":"TH-H004-A641","no":641,"noLabel":{"th":"มาตรา 641"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๑ การให้ยืมใช้คงรูปนั้น ท่านว่าย่อมบริบูรณ์ต่อเมื่อส่งมอบทรัพย์สินซึ่งให้ยืม"}},{"id":"TH-H004-A642","no":642,"noLabel":{"th":"มาตรา 642"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๒ ค่าฤชาธรรมเนียมในการทำสัญญาก็ดี ค่าส่งมอบและค่าส่งคืนทรัพย์สินซึ่งยืมก็ดี ย่อมตกแก่ผู้ยืมเป็นผู้เสีย"}},{"id":"TH-H004-A643","no":643,"noLabel":{"th":"มาตรา 643"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๓ ทรัพย์สินซึ่งยืมนั้น ถ้าผู้ยืมเอาไปใช้การอย่างอื่นนอกจากการอันเป็นปกติแก่ทรัพย์สินนั้น หรือนอกจากการอันปรากฏในสัญญาก็ดี เอาไปให้บุคคลภายนอกใช้สอยก็ดี เอาไปไว้นานกว่าที่ควรจะเอาไว้ก็ดี ท่านว่าผู้ยืมจะต้องรับผิดในเหตุทรัพย์สินนั้นสูญหายหรือบุบสลายไปอย่างหนึ่งอย่างใด แม้ถึงจะเป็นเพราะเหตุสุดวิสัย เว้นแต่จะพิสูจน์ได้ว่าถึงอย่างไร ๆ ทรัพย์สินนั้นก็คงจะต้องสูญหายหรือบุบสลายอยู่นั่นเอง"}},{"id":"TH-H004-A644","no":644,"noLabel":{"th":"มาตรา 644"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๔ ผู้ยืมจำต้องสงวนทรัพย์สินซึ่งยืมไปเหมือนเช่นวิญญูชนจะพึงสงวนทรัพย์สินของตนเอง"}},{"id":"TH-H004-A645","no":645,"noLabel":{"th":"มาตรา 645"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๕ ในกรณีทั้งหลายดังกล่าวไว้ในมาตรา ๖๔๓ นั้นก็ดี หรือถ้าผู้ยืมประพฤติฝ่าฝืนต่อความในมาตรา ๖๔๔ ก็ดี ผู้ให้ยืมจะบอกเลิกสัญญาเสียก็ได้"}},{"id":"TH-H004-A646","no":646,"noLabel":{"th":"มาตรา 646"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๖ ถ้ามิได้กำหนดเวลากันไว้ ท่านให้คืนทรัพย์สินที่ยืมเมื่อผู้ยืมได้ใช้สอยทรัพย์สินนั้นเสร็จแล้วตามการอันปรากฏในสัญญา แต่ผู้ให้ยืมจะเรียกคืนก่อนนั้นก็ได้ เมื่อเวลาได้ล่วงไปพอแก่การที่ผู้ยืมจะได้ใช้สอยทรัพย์สินนั้นเสร็จแล้ว ถ้าเวลาก็มิได้กำหนดกันไว้ ทั้งในสัญญาก็ไม่ปรากฏว่ายืมไปใช้เพื่อการใดไซร้ ท่านว่าผู้ให้ยืมจะเรียกของคืนเมื่อไรก็ได้"}},{"id":"TH-H004-A647","no":647,"noLabel":{"th":"มาตรา 647"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๗ ค่าใช้จ่ายอันเป็นปกติแก่การบำรุงรักษาทรัพย์สินซึ่งยืมนั้น ผู้ยืมต้องเป็นผู้เสีย"}},{"id":"TH-H004-A648","no":648,"noLabel":{"th":"มาตรา 648"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๘ อันการยืมใช้คงรูป ย่อมระงับสิ้นไปด้วยมรณะแห่งผู้ยืม"}},{"id":"TH-H004-A649","no":649,"noLabel":{"th":"มาตรา 649"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๔๙ ในข้อความรับผิดเพื่อเสียค่าทดแทนอันเกี่ยวกับการยืมใช้คงรูปนั้น ท่านห้ามมิให้ฟ้องเมื่อพ้นเวลาหกเดือนนับแต่วันสิ้นสัญญา"}},{"id":"TH-H004-A650","no":650,"noLabel":{"th":"มาตรา 650"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๐ อันว่ายืมใช้สิ้นเปลืองนั้น คือสัญญาซึ่งผู้ให้ยืมโอนกรรมสิทธิ์ในทรัพย์สินชนิดใช้ไปสิ้นไปนั้นเป็นปริมาณมีกำหนดให้ไปแก่ผู้ยืม และผู้ยืมตกลงว่าจะคืนทรัพย์สินเป็นประเภท ชนิด และปริมาณเช่นเดียวกันให้แทนทรัพย์สินซึ่งให้ยืมนั้น สัญญานี้ย่อมบริบูรณ์ต่อเมื่อส่งมอบทรัพย์สินที่ยืม"}},{"id":"TH-H004-A651","no":651,"noLabel":{"th":"มาตรา 651"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๑ ค่าฤชาธรรมเนียมในการทำสัญญาก็ดี ค่าส่งมอบและส่งคืนทรัพย์สินซึ่งยืมก็ดี ย่อมตกแก่ผู้ยืมเป็นผู้เสีย"}},{"id":"TH-H004-A652","no":652,"noLabel":{"th":"มาตรา 652"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๒ ถ้าในสัญญาไม่มีกำหนดเวลาให้คืนทรัพย์สินซึ่งยืมไป ผู้ให้ยืมจะบอกกล่าวแก่ผู้ยืมให้คืนทรัพย์สินภายในเวลาอันควร ซึ่งกำหนดให้ในคำบอกกล่าวนั้นก็ได้"}},{"id":"TH-H004-A653","no":653,"noLabel":{"th":"มาตรา 653"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๓ การกู้ยืมเงินกว่าสองพันบาทขึ้นไปนั้น ถ้ามิได้มีหลักฐานแห่งการกู้ยืมเป็นหนังสืออย่างใดอย่างหนึ่งลงลายมือชื่อผู้ยืมเป็นสำคัญ จะฟ้องร้องให้บังคับคดีหาได้ไม่ ในการกู้ยืมเงินมีหลักฐานเป็นหนังสือนั้น ท่านว่าจะนำสืบการใช้เงินได้ต่อเมื่อมีหลักฐานเป็นหนังสืออย่างใดอย่างหนึ่งลงลายมือชื่อผู้ให้ยืมมาแสดง หรือเอกสารอันเป็นหลักฐานแห่งการกู้ยืมนั้นได้เวนคืนแล้ว หรือได้แทงเพิกถอนลงในเอกสารนั้นแล้ว"}},{"id":"TH-H004-A654","no":654,"noLabel":{"th":"มาตรา 654"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๔ ท่านห้ามมิให้คิดดอกเบี้ยเกินร้อยละสิบห้าต่อปี ถ้าในสัญญากำหนดดอกเบี้ยเกินกว่านั้น ก็ให้ลดลงมาเป็นร้อยละสิบห้าต่อปี"}},{"id":"TH-H004-A655","no":655,"noLabel":{"th":"มาตรา 655"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๕ ท่านห้ามมิให้คิดดอกเบี้ยในดอกเบี้ยที่ค้างชำระ แต่ทว่าเมื่อดอกเบี้ยค้างชำระไม่น้อยกว่าปีหนึ่ง คู่สัญญากู้ยืมจะตกลงกันให้เอาดอกเบี้ยนั้นทบเข้ากับต้นเงินแล้วให้คิดดอกเบี้ยในจำนวนเงินที่ทบเข้ากันนั้นก็ได้ แต่การตกลงเช่นนั้นต้องทำเป็นหนังสือ ส่วนประเพณีการค้าขายที่คำนวณดอกทบต้นในบัญชีเดินสะพัดก็ดี ในการค้าขายอย่างอื่นทำนองเช่นว่านี้ก็ดี หาอยู่ในบังคับแห่งบทบัญญัติซึ่งกล่าวมาในวรรคก่อนนั้นไม่"}},{"id":"TH-H004-A656","no":656,"noLabel":{"th":"มาตรา 656"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๕๖ ถ้าทำสัญญากู้ยืมเงินกัน และผู้กู้ยืมยอมรับเอาสิ่งของหรือทรัพย์สินอย่างอื่นแทนจำนวนเงินนั้นไซร้ ท่านให้คิดเป็นหนี้ค้างชำระโดยจำนวนเท่ากับราคาท้องตลาดแห่งสิ่งของหรือทรัพย์สินนั้นในเวลาและ ณ สถานที่ส่งมอบ ถ้าทำสัญญากู้ยืมเงินกัน และผู้ให้กู้ยืมยอมรับเอาสิ่งของหรือทรัพย์สินอย่างอื่นเป็นการชำระหนี้แทนเงินที่กู้ยืมไซร้ หนี้อันระงับไปเพราะการชำระเช่นนั้น ท่านให้คิดเป็นจำนวนเท่ากับราคาท้องตลาดแห่งสิ่งของหรือทรัพย์สินนั้นในเวลาและ ณ สถานที่ส่งมอบ ความตกลงกันอย่างใด ๆ ขัดกับข้อความดังกล่าวมานี้ท่านว่าเป็นโมฆะ"}},{"id":"TH-H004-A657","no":657,"noLabel":{"th":"มาตรา 657"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๕๗ อันว่าฝากทรัพย์นั้น คือสัญญาซึ่งบุคคลคนหนึ่ง เรียกว่าผู้ฝาก ส่งมอบทรัพย์สินให้แก่บุคคลอีกคนหนึ่ง เรียกว่าผู้รับฝาก และผู้รับฝากตกลงว่าจะเก็บรักษาทรัพย์สินนั้นไว้ในอารักขาแห่งตน แล้วจะคืนให้"}},{"id":"TH-H004-A658","no":658,"noLabel":{"th":"มาตรา 658"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๕๘ ถ้าโดยพฤติการณ์พึงคาดหมายได้ว่าเขารับฝากทรัพย์ก็เพื่อจะได้รับบำเหน็จค่าฝากทรัพย์เท่านั้นไซร้ ท่านให้ถือว่าเป็นอันตกลงกันแล้วโดยปริยายว่ามีบำเหน็จเช่นนั้น"}},{"id":"TH-H004-A659","no":659,"noLabel":{"th":"มาตรา 659"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๕๙ ถ้าการรับฝากทรัพย์เป็นการทำให้เปล่าไม่มีบำเหน็จไซร้ ท่านว่าผู้รับฝากจำต้องใช้ความระมัดระวังสงวนทรัพย์สินซึ่งฝากนั้นเหมือนเช่นเคยประพฤติในกิจการของตนเอง ถ้าการรับฝากทรัพย์นั้นมีบำเหน็จค่าฝาก ท่านว่าผู้รับฝากจำต้องใช้ความระมัดระวังและใช้ฝีมือเพื่อสงวนทรัพย์สินนั้นเหมือนเช่นวิญญูชนจะพึงประพฤติโดยพฤติการณ์ดังนั้น ทั้งนี้ ย่อมรวมทั้งการใช้ฝีมืออันพิเศษเฉพาะการในที่จะพึงใช้ฝีมือเช่นนั้นด้วย ถ้าและผู้รับฝากเป็นผู้มีวิชาชีพเฉพาะกิจการค้าขาย หรืออาชีวะอย่างหนึ่งอย่างใด ก็จำต้องใช้ความระมัดระวังและใช้ฝีมือเท่าที่เป็นธรรมดาจะต้องใช้และสมควรจะต้องใช้ในกิจการค้าขายหรืออาชีวะอย่างนั้น"}},{"id":"TH-H004-A660","no":660,"noLabel":{"th":"มาตรา 660"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๐ ถ้าผู้ฝากมิได้อนุญาต และผู้รับฝากเอาทรัพย์สินซึ่งฝากนั้นออกใช้สอยเอง หรือเอาไปให้บุคคลภายนอกใช้สอย หรือให้บุคคลภายนอกเก็บรักษาไซร้ ท่านว่าผู้รับฝากจะต้องรับผิดเมื่อทรัพย์สินซึ่งฝากนั้นสูญหายหรือบุบสลายอย่างหนึ่งอย่างใด แม้ถึงจะเป็นเพราะเหตุสุดวิสัย เว้นแต่จะพิสูจน์ได้ว่าถึงอย่างไร ๆ ทรัพย์สินนั้นก็คงจะต้องสูญหายหรือบุบสลายอยู่นั่นเอง"}},{"id":"TH-H004-A661","no":661,"noLabel":{"th":"มาตรา 661"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๑ ถ้าบุคคลภายนอกอ้างว่ามีสิทธิเหนือทรัพย์สินซึ่งฝากและยื่นฟ้องผู้รับฝากก็ดี หรือยึดทรัพย์สินนั้นก็ดี ผู้รับฝากต้องรีบบอกกล่าวแก่ผู้ฝากโดยพลัน"}},{"id":"TH-H004-A662","no":662,"noLabel":{"th":"มาตรา 662"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๒ ถ้าได้กำหนดเวลากันไว้ว่าจะพึงคืนทรัพย์สินซึ่งฝากนั้นเมื่อไร ท่านว่าผู้รับฝากไม่มีสิทธิจะคืนทรัพย์สินก่อนถึงเวลากำหนด เว้นแต่ในเหตุจำเป็นอันมิอาจจะก้าวล่วงเสียได้"}},{"id":"TH-H004-A663","no":663,"noLabel":{"th":"มาตรา 663"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๓ ถึงแม้ว่าคู่สัญญาจะได้กำหนดเวลาไว้ว่าจะพึงคืนทรัพย์สินซึ่งฝากนั้นเมื่อไรก็ตาม ถ้าว่าผู้ฝากจะเรียกคืนในเวลาใด ๆ ผู้รับฝากก็ต้องคืนให้"}},{"id":"TH-H004-A664","no":664,"noLabel":{"th":"มาตรา 664"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๔ ถ้าคู่สัญญาไม่ได้กำหนดเวลาไว้ว่าจะพึงคืนทรัพย์สินซึ่งฝากนั้นเมื่อไรไซร้ ผู้รับฝากอาจคืนทรัพย์สินนั้นได้ทุกเมื่อ"}},{"id":"TH-H004-A665","no":665,"noLabel":{"th":"มาตรา 665"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๕ ผู้รับฝากจำต้องคืนทรัพย์สินซึ่งรับฝากไว้นั้นให้แก่ผู้ฝาก หรือทรัพย์สินนั้นฝากในนามของผู้ใด คืนให้แก่ผู้นั้น หรือผู้รับฝากได้รับคำสั่งโดยชอบให้คืนทรัพย์สินนั้นไปแก่ผู้ใด คืนให้แก่ผู้นั้น แต่หากผู้ฝากทรัพย์ตาย ท่านให้คืนทรัพย์สินนั้นให้แก่ทายาท"}},{"id":"TH-H004-A666","no":666,"noLabel":{"th":"มาตรา 666"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๖ เมื่อคืนทรัพย์ ถ้ามีดอกผลเกิดแต่ทรัพย์สินซึ่งฝากนั้นเท่าใด ผู้รับฝากจำต้องส่งมอบพร้อมไปกับทรัพย์สินนั้นด้วย"}},{"id":"TH-H004-A667","no":667,"noLabel":{"th":"มาตรา 667"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๗ ค่าคืนทรัพย์สินซึ่งฝากนั้น ย่อมตกแก่ผู้ฝากเป็นผู้เสีย"}},{"id":"TH-H004-A668","no":668,"noLabel":{"th":"มาตรา 668"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๘ ค่าใช้จ่ายใดอันควรแก่การบำรุงรักษาทรัพย์สินซึ่งฝากนั้น ผู้ฝากจำต้องชดใช้ให้แก่ผู้รับฝาก เว้นแต่จะได้ตกลงกันไว้โดยสัญญาฝากทรัพย์ว่าผู้รับฝากจะต้องออกเงินค่าใช้จ่ายนั้นเอง"}},{"id":"TH-H004-A669","no":669,"noLabel":{"th":"มาตรา 669"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๖๙ ถ้าไม่ได้กำหนดเวลาไว้ในสัญญา หรือไม่มีกำหนดโดยจารีตประเพณีว่าบำเหน็จค่าฝากทรัพย์นั้นจะพึงชำระเมื่อไรไซร้ ท่านให้ชำระเมื่อคืนทรัพย์สินซึ่งฝาก ถ้าได้กำหนดเวลากันไว้เป็นระยะอย่างไร ก็พึงชำระเมื่อสิ้นระยะเวลานั้นทุกคราวไป"}},{"id":"TH-H004-A670","no":670,"noLabel":{"th":"มาตรา 670"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๗๐ ผู้รับฝากชอบที่จะยึดหน่วงเอาทรัพย์สินซึ่งฝากนั้นไว้ได้ จนกว่าจะได้รับเงินบรรดาที่ค้างชำระแก่ตนเกี่ยวด้วยการฝากทรัพย์นั้น"}},{"id":"TH-H004-A671","no":671,"noLabel":{"th":"มาตรา 671"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๗๑ ในข้อความรับผิดเพื่อใช้เงินบำเหน็จค่าฝากทรัพย์ก็ดี ชดใช้เงินค่าใช้จ่ายก็ดี ใช้ค่าสินไหมทดแทนเกี่ยวแก่การฝากทรัพย์ก็ดี ท่านห้ามมิให้ฟ้องเมื่อพ้นเวลาหกเดือนนับแต่วันสิ้นสัญญา"}},{"id":"TH-H004-A672","no":672,"noLabel":{"th":"มาตรา 672"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๗๒ ถ้าฝากเงิน ท่านให้สันนิษฐานไว้ก่อนว่าผู้รับฝากไม่พึงต้องส่งคืนเป็นเงินทองตราอันเดียวกันกับที่ฝาก แต่จะต้องคืนเงินให้ครบจำนวน อนึ่ง ผู้รับฝากจะเอาเงินซึ่งฝากนั้นออกใช้ก็ได้ แต่หากจำต้องคืนเงินให้ครบจำนวนเท่านั้น แม้ว่าเงินซึ่งฝากนั้นจะได้สูญหายไปด้วยเหตุสุดวิสัยก็ตาม ผู้รับฝากก็จำต้องคืนเงินเป็นจำนวนดังว่านั้น"}},{"id":"TH-H004-A673","no":673,"noLabel":{"th":"มาตรา 673"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๗๓ เมื่อใดผู้รับฝากจำต้องคืนเงินแต่เพียงเท่าจำนวนที่ฝาก ผู้ฝากจะเรียกถอนเงินคืนก่อนถึงเวลาที่ได้ตกลงกันไว้ไม่ได้ หรือฝ่ายผู้รับฝากจะส่งคืนเงินก่อนถึงเวลานั้นก็ไม่ได้ดุจกัน"}},{"id":"TH-H004-A674","no":674,"noLabel":{"th":"มาตรา 674"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๔ เจ้าสำนักโรงแรมหรือโฮเต็ล หรือสถานที่อื่นทำนองเช่นว่านั้น จะต้องรับผิดเพื่อความสูญหายหรือบุบสลายอย่างใด ๆ อันเกิดแก่ทรัพย์สินซึ่งคนเดินทางหรือแขกอาศัย หากได้พามา"}},{"id":"TH-H004-A675","no":675,"noLabel":{"th":"มาตรา 675"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๕ เจ้าสำนักต้องรับผิดในการที่ทรัพย์สินของคนเดินทางหรือแขกอาศัยสูญหายหรือบุบสลายไปอย่างใด ๆ แม้ถึงว่าความสูญหายหรือบุบสลายนั้นจะเกิดขึ้นเพราะผู้คนไปมาเข้าออก ณ โรงแรม โฮเต็ล หรือสถานที่เช่นนั้น ก็คงต้องรับผิด ความรับผิดนี้ ถ้าเกี่ยวด้วยเงินทองตรา ธนบัตร ตั๋วเงิน พันธบัตร ใบหุ้น ใบหุ้นกู้ ประทวนสินค้า อัญมณี หรือของมีค่าอื่น ๆ ให้จำกัดไว้เพียงห้าพันบาท เว้นแต่จะได้ฝากของมีค่าเช่นนี้ไว้แก่เจ้าสำนักและได้บอกราคาแห่งของนั้นชัดแจ้ง แต่เจ้าสำนักไม่ต้องรับผิดเพื่อความสูญหายหรือบุบสลายอันเกิดแต่เหตุสุดวิสัย หรือแต่สภาพแห่งทรัพย์สินนั้น หรือแต่ความผิดของคนเดินทาง หรือแขกอาศัยผู้นั้นเอง หรือบริวารของเขา หรือบุคคลซึ่งเขาได้ต้อนรับ"}},{"id":"TH-H004-A676","no":676,"noLabel":{"th":"มาตรา 676"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๖ ทรัพย์สินซึ่งมิได้นำฝากบอกราคาชัดแจ้งนั้น เมื่อพบเห็นว่าสูญหายหรือบุบสลายขึ้น คนเดินทางหรือแขกอาศัยต้องแจ้งความนั้นต่อเจ้าสำนักโรงแรม โฮเต็ล หรือสถานที่เช่นนั้นทันที มิฉะนั้นท่านว่าเจ้าสำนักย่อมพ้นจากความรับผิดดังบัญญัติไว้ในมาตรา ๖๗๔ และมาตรา ๖๗๕"}},{"id":"TH-H004-A677","no":677,"noLabel":{"th":"มาตรา 677"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๗ ถ้ามีคำแจ้งความปิดไว้ในโรงแรม โฮเต็ล หรือสถานที่อื่นทำนองเช่นว่านี้ เป็นข้อความยกเว้นหรือจำกัดความรับผิดของเจ้าสำนักไซร้ ท่านว่าความนั้นเป็นโมฆะ เว้นแต่คนเดินทางหรือแขกอาศัยจะได้ตกลงด้วยชัดแจ้งในการยกเว้นหรือจำกัดความรับผิดดังว่านั้น"}},{"id":"TH-H004-A678","no":678,"noLabel":{"th":"มาตรา 678"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๘ ในข้อความรับผิดใช้ค่าสินไหมทดแทนเพื่อทรัพย์สินของคนเดินทางหรือแขกอาศัยสูญหายหรือบุบสลายนั้น ท่านห้ามมิให้ฟ้องเมื่อพ้นเวลาหกเดือนนับแต่วันที่คนเดินทางหรือแขกอาศัยออกไปจากสถานที่นั้น"}},{"id":"TH-H004-A679","no":679,"noLabel":{"th":"มาตรา 679"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๗๙ เจ้าสำนักชอบที่จะยึดหน่วงเครื่องเดินทางหรือทรัพย์สินอย่างอื่นของคนเดินทางหรือแขกอาศัยอันเอาไว้ในโรงแรม โฮเต็ล หรือสถานที่เช่นนั้นได้จนกว่าจะได้รับใช้เงินบรรดาที่ค้างชำระแก่ตน เพื่อการพักอาศัยและการอื่น ๆ อันได้ทำให้แก่คนเดินทางหรือแขกอาศัยตามที่เขาพึงต้องการนั้น รวมทั้งการชดใช้เงินทั้งหลายที่ได้ออกแทนไปด้วย เจ้าสำนักจะเอาทรัพย์สินที่ได้ยึดหน่วงไว้เช่นว่านั้นออกขายทอดตลาด แล้วหักเอาเงินใช้จำนวนที่ค้างชำระแก่ตน รวมทั้งค่าฤชาธรรมเนียมและค่าใช้จ่ายในการขายทอดตลาดนั้นจากเงินที่ขายทรัพย์สินนั้นก็ได้ แต่ท่านมิให้เจ้าสำนักใช้สิทธิดังว่านี้ จนเมื่อ (๑) ทรัพย์สินนั้นตกอยู่แก่ตนเป็นเวลานานถึงหกสัปดาห์ยังมิได้รับชำระหนี้สิน และ (๒) อย่างน้อยเดือนหนึ่งก่อนวันขายทอดตลาด ตนได้ประกาศโฆษณาในหนังสือพิมพ์ประจำท้องถิ่นฉบับหนึ่งแจ้งความจำนงที่จะขายทรัพย์สิน บอกลักษณะแห่งทรัพย์สินที่จะขายโดยย่อ กับถ้ารู้ชื่อเจ้าของ ก็บอกด้วย เมื่อขายทอดตลาดหักใช้หนี้ดังกล่าวแล้ว มีเงินเหลืออยู่อีกเท่าใดต้องคืนให้แก่เจ้าของ หรือฝากไว้ ณ สำนักงานฝากทรัพย์ตามบทบัญญัติในมาตรา ๓๓๑ และมาตรา ๓๓๓"}},{"id":"TH-H004-A680","no":680,"noLabel":{"th":"มาตรา 680"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๐ อันว่าค้ำประกันนั้น คือสัญญาซึ่งบุคคลภายนอกคนหนึ่ง เรียกว่าผู้ค้ำประกัน ผูกพันตนต่อเจ้าหนี้คนหนึ่งเพื่อชำระหนี้ในเมื่อลูกหนี้ไม่ชำระหนี้นั้น อนึ่ง สัญญาค้ำประกันนั้น ถ้ามิได้มีหลักฐานเป็นหนังสืออย่างใดอย่างหนึ่งลงลายมือชื่อผู้ค้ำประกันเป็นสำคัญ ท่านว่าจะฟ้องร้องให้บังคับคดีหาได้ไม่"}},{"id":"TH-H004-A681","no":681,"noLabel":{"th":"มาตรา 681"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๑ อันค้ำประกันนั้นจะมีได้แต่เฉพาะเพื่อหนี้อันสมบูรณ์ หนี้ในอนาคตหรือหนี้มีเงื่อนไขจะประกันไว้เพื่อเหตุการณ์ซึ่งหนี้นั้นอาจเป็นผลได้จริงก็ประกันได้ แต่ต้องระบุวัตถุประสงค์ในการก่อหนี้รายที่ค้ำประกัน ลักษณะของมูลหนี้ จำนวนเงินสูงสุดที่ค้ำประกัน และระยะเวลาในการก่อหนี้ที่จะค้ำประกัน เว้นแต่เป็นการค้ำประกันเพื่อกิจการเนื่องกันไปหลายคราวตามมาตรา ๖๙๙ จะไม่ระบุระยะเวลาดังกล่าวก็ได้ สัญญาค้ำประกันต้องระบุหนี้หรือสัญญาที่ค้ำประกันไว้โดยชัดแจ้ง และผู้ค้ำประกันย่อมรับผิดเฉพาะหนี้หรือสัญญาที่ระบุไว้เท่านั้น หนี้อันเกิดแต่สัญญาซึ่งไม่ผูกพันลูกหนี้เพราะทำด้วยความสำคัญผิดหรือเพราะเป็นผู้ไร้ความสามารถนั้นก็อาจจะมีประกันอย่างสมบูรณ์ได้ ถ้าหากว่าผู้ค้ำประกันรู้เหตุสำคัญผิดหรือไร้ความสามารถนั้นในขณะที่เข้าทำสัญญาผูกพันตน"}},{"id":"TH-H004-A681.001","no":681.001,"noLabel":{"th":"มาตรา 681/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๑/๑ ข้อตกลงใดที่กำหนดให้ผู้ค้ำประกันต้องรับผิดอย่างเดียวกับลูกหนี้ร่วมหรือในฐานะเป็นลูกหนี้ร่วม ข้อตกลงนั้นเป็นโมฆะ ความในวรรคหนึ่ง มิให้ใช้บังคับแก่กรณีผู้ค้ำประกันซึ่งเป็นนิติบุคคลและยินยอมเข้าผูกพันตนเพื่อรับผิดอย่างลูกหนี้ร่วมหรือในฐานะเป็นลูกหนี้ร่วม ในกรณีเช่นนั้นผู้ค้ำประกันซึ่งเป็นนิติบุคคลนั้นย่อมไม่มีสิทธิดังที่บัญญัติไว้ในมาตรา ๖๘๘ มาตรา ๖๘๙ และมาตรา ๖๙๐"}},{"id":"TH-H004-A682","no":682,"noLabel":{"th":"มาตรา 682"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๒ ท่านว่าบุคคลจะยอมเข้าเป็นผู้รับเรือน คือเป็นประกันของผู้ค้ำประกันอีกชั้นหนึ่ง ก็เป็นได้ ถ้าบุคคลหลายคนยอมตนเข้าเป็นผู้ค้ำประกันในหนี้รายเดียวกันไซร้ ท่านว่าผู้ค้ำประกันเหล่านั้นมีความรับผิดอย่างลูกหนี้ร่วมกัน แม้ถึงว่าจะมิได้เข้ารับค้ำประกันรวมกัน"}},{"id":"TH-H004-A683","no":683,"noLabel":{"th":"มาตรา 683"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๓ อันค้ำประกันอย่างไม่มีจำกัดนั้นย่อมคุ้มถึงดอกเบี้ยและค่าสินไหมทดแทนซึ่งลูกหนี้ค้างชำระ ตลอดจนค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้นด้วย"}},{"id":"TH-H004-A684","no":684,"noLabel":{"th":"มาตรา 684"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๔ ผู้ค้ำประกันย่อมรับผิดเพื่อค่าฤชาธรรมเนียมความซึ่งลูกหนี้จะต้องใช้ให้แก่เจ้าหนี้ แต่ถ้าโจทก์ฟ้องคดีโดยมิได้เรียกให้ผู้ค้ำประกันชำระหนี้นั้นก่อนไซร้ ท่านว่าผู้ค้ำประกันหาต้องรับผิดเพื่อใช้ค่าฤชาธรรมเนียมเช่นนั้นไม่"}},{"id":"TH-H004-A685","no":685,"noLabel":{"th":"มาตรา 685"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๕ ถ้าเมื่อบังคับตามสัญญาค้ำประกันนั้น ผู้ค้ำประกันไม่ชำระหนี้ทั้งหมดของลูกหนี้ รวมทั้งดอกเบี้ย ค่าสินไหมทดแทน และอุปกรณ์ด้วยไซร้ หนี้ยังเหลืออยู่เท่าใด ท่านว่าลูกหนี้ยังคงรับผิดต่อเจ้าหนี้ในส่วนที่เหลือนั้น"}},{"id":"TH-H004-A685.001","no":685.001,"noLabel":{"th":"มาตรา 685/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๖๘๕/๑ บรรดาข้อตกลงเกี่ยวกับการค้ำประกันที่แตกต่างไปจากมาตรา ๖๘๑ วรรคหนึ่ง วรรคสอง และวรรคสาม มาตรา ๖๘๖ มาตรา ๖๙๔ มาตรา ๖๙๘ และมาตรา ๖๙๙ เป็นโมฆะ"}},{"id":"TH-H004-A686","no":686,"noLabel":{"th":"มาตรา 686"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๘๖ เมื่อลูกหนี้ผิดนัด ให้เจ้าหนี้มีหนังสือบอกกล่าวไปยังผู้ค้ำประกันภายในหกสิบวันนับแต่วันที่ลูกหนี้ผิดนัด และไม่ว่ากรณีจะเป็นประการใดเจ้าหนี้จะเรียกให้ผู้ค้ำประกันชำระหนี้ก่อนที่หนังสือบอกกล่าวจะไปถึงผู้ค้ำประกันมิได้ แต่ไม่ตัดสิทธิผู้ค้ำประกันที่จะชำระหนี้เมื่อหนี้ถึงกำหนดชำระ ในกรณีที่เจ้าหนี้มิได้มีหนังสือบอกกล่าวภายในกำหนดเวลาตามวรรคหนึ่ง ให้ผู้ค้ำประกันหลุดพ้นจากความรับผิดในดอกเบี้ยและค่าสินไหมทดแทน ตลอดจนค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้นบรรดาที่เกิดขึ้นภายหลังจากพ้นกำหนดเวลาตามวรรคหนึ่ง เมื่อเจ้าหนี้มีสิทธิเรียกให้ผู้ค้ำประกันชำระหนี้หรือผู้ค้ำประกันมีสิทธิชำระหนี้ได้ตามวรรคหนึ่ง ผู้ค้ำประกันอาจชำระหนี้ทั้งหมดหรือใช้สิทธิชำระหนี้ตามเงื่อนไขและวิธีการในการชำระหนี้ที่ลูกหนี้มีอยู่กับเจ้าหนี้ก่อนการผิดนัดชำระหนี้ ทั้งนี้ เฉพาะในส่วนที่ตนต้องรับผิดก็ได้ และให้นำความในมาตรา ๗๐๑ วรรคสอง มาใช้บังคับโดยอนุโลม ในระหว่างที่ผู้ค้ำประกันชำระหนี้ตามเงื่อนไขและวิธีการในการชำระหนี้ของลูกหนี้ตามวรรคสาม เจ้าหนี้จะเรียกดอกเบี้ยเพิ่มขึ้นเพราะเหตุที่ลูกหนี้ผิดนัดในระหว่างนั้นมิได้ การชำระหนี้ของผู้ค้ำประกันตามมาตรานี้ ไม่กระทบกระเทือนสิทธิของผู้ค้ำประกันตามมาตรา ๖๙๓"}},{"id":"TH-H004-A687","no":687,"noLabel":{"th":"มาตรา 687"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๘๗ ผู้ค้ำประกันไม่จำต้องชำระหนี้ก่อนถึงเวลากำหนดที่จะชำระ แม้ถึงว่าลูกหนี้จะไม่อาจถือเอาซึ่งประโยชน์แห่งเงื่อนเวลาเริ่มต้นหรือเวลาสุดสิ้นได้ต่อไปแล้ว"}},{"id":"TH-H004-A688","no":688,"noLabel":{"th":"มาตรา 688"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๘๘ เมื่อเจ้าหนี้ทวงให้ผู้ค้ำประกันชำระหนี้ ผู้ค้ำประกันจะขอให้เรียกลูกหนี้ชำระก่อนก็ได้ เว้นแต่ลูกหนี้จะถูกศาลพิพากษาให้เป็นคนล้มละลายเสียแล้ว หรือไม่ปรากฏว่าลูกหนี้ไปอยู่แห่งใดในพระราชอาณาเขต"}},{"id":"TH-H004-A689","no":689,"noLabel":{"th":"มาตรา 689"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๘๙ ถึงแม้จะได้เรียกให้ลูกหนี้ชำระหนี้ดังกล่าวมาในมาตราก่อนนั้นแล้วก็ตาม ถ้าผู้ค้ำประกันพิสูจน์ได้ว่าลูกหนี้นั้นมีทางที่จะชำระหนี้ได้ และการที่จะบังคับให้ลูกหนี้ชำระหนี้นั้นจะไม่เป็นการยากไซร้ ท่านว่าเจ้าหนี้จะต้องบังคับการชำระหนี้รายนั้นเอาจากทรัพย์สินของลูกหนี้ก่อน"}},{"id":"TH-H004-A690","no":690,"noLabel":{"th":"มาตรา 690"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๙๐ ถ้าเจ้าหนี้มีทรัพย์ของลูกหนี้ยึดถือไว้เป็นประกันไซร้ เมื่อผู้ค้ำประกันร้องขอ ท่านว่าเจ้าหนี้จะต้องให้ชำระหนี้เอาจากทรัพย์ซึ่งเป็นประกันนั้นก่อน"}},{"id":"TH-H004-A691","no":691,"noLabel":{"th":"มาตรา 691"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๙๑ ในกรณีที่เจ้าหนี้ตกลงกับลูกหนี้ อันมีผลเป็นการลดจำนวนหนี้ที่มีการค้ำประกันรวมทั้งดอกเบี้ย ค่าสินไหมทดแทน หรือค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้น ให้เจ้าหนี้มีหนังสือแจ้งให้ผู้ค้ำประกันทราบถึงข้อตกลงดังกล่าวภายในหกสิบวันนับแต่วันที่ตกลงกันนั้น ถ้าลูกหนี้ได้ชำระหนี้ตามที่ได้ลดแล้วก็ดี ลูกหนี้ชำระหนี้ตามที่ได้ลดไม่ครบถ้วนแต่ผู้ค้ำประกันได้ชำระหนี้ส่วนที่เหลือนั้นแล้วก็ดี หรือลูกหนี้ไม่ชำระหนี้ตามที่ได้ลดแต่ผู้ค้ำประกันได้ชำระหนี้ตามที่ได้ลดนั้นแล้วก็ดี ให้ผู้ค้ำประกันเป็นอันหลุดพ้นจากการค้ำประกัน ในการชำระหนี้ของผู้ค้ำประกันดังกล่าว ผู้ค้ำประกันมีสิทธิชำระหนี้ได้แม้จะล่วงเลยกำหนดเวลาชำระหนี้ตามที่ได้ลดแต่ต้องไม่เกินหกสิบวันนับแต่วันที่ครบกำหนดเวลาชำระหนี้ดังกล่าว ในกรณีที่เจ้าหนี้มีหนังสือแจ้งให้ผู้ค้ำประกันทราบถึงข้อตกลงดังกล่าวเมื่อล่วงเลยกำหนดเวลาชำระหนี้ตามที่ได้ลดแล้ว ให้ผู้ค้ำประกันมีสิทธิชำระหนี้ได้ภายในหกสิบวันนับแต่วันที่เจ้าหนี้มีหนังสือแจ้งให้ผู้ค้ำประกันทราบถึงข้อตกลงนั้น ทั้งนี้ ข้อตกลงที่ทำขึ้นภายหลังที่ลูกหนี้ผิดนัดชำระหนี้แล้ว หากในข้อตกลงนั้นมีการขยายเวลาชำระหนี้ให้แก่ลูกหนี้ มิให้ถือว่าเป็นการผ่อนเวลาตามมาตรา ๗๐๐ ข้อตกลงใดที่มีผลเป็นการเพิ่มภาระแก่ผู้ค้ำประกันให้มากกว่าที่บัญญัติไว้ในวรรคหนึ่ง ข้อตกลงนั้นเป็นโมฆะ"}},{"id":"TH-H004-A692","no":692,"noLabel":{"th":"มาตรา 692"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๖๙๒ อายุความสะดุดหยุดลงเป็นโทษแก่ลูกหนี้นั้น ย่อมเป็นโทษแก่ผู้ค้ำประกันด้วย"}},{"id":"TH-H004-A693","no":693,"noLabel":{"th":"มาตรา 693"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๙๓ ผู้ค้ำประกันซึ่งได้ชำระหนี้แล้ว ย่อมมีสิทธิที่จะไล่เบี้ยเอาจากลูกหนี้ เพื่อต้นเงินกับดอกเบี้ยและเพื่อการที่ต้องสูญหายหรือเสียหายไปอย่างใด ๆ เพราะการค้ำประกันนั้น อนึ่ง ผู้ค้ำประกันย่อมเข้ารับช่วงสิทธิของเจ้าหนี้บรรดามีเหนือลูกหนี้ด้วย"}},{"id":"TH-H004-A694","no":694,"noLabel":{"th":"มาตรา 694"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๙๔ นอกจากข้อต่อสู้ซึ่งผู้ค้ำประกันมีต่อเจ้าหนี้นั้น ท่านว่าผู้ค้ำประกันยังอาจยกข้อต่อสู้ทั้งหลายซึ่งลูกหนี้มีต่อเจ้าหนี้ขึ้นต่อสู้ได้ด้วย"}},{"id":"TH-H004-A695","no":695,"noLabel":{"th":"มาตรา 695"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๙๕ ผู้ค้ำประกันซึ่งละเลยไม่ยกข้อต่อสู้ของลูกหนี้ขึ้นต่อสู้เจ้าหนี้นั้น ท่านว่าย่อมสิ้นสิทธิที่จะไล่เบี้ยเอาแก่ลูกหนี้เพียงเท่าที่ไม่ยกขึ้นเป็นข้อต่อสู้ เว้นแต่จะพิสูจน์ได้ว่าตนมิได้รู้ว่ามีข้อต่อสู้เช่นนั้น และที่ไม่รู้นั้นมิได้เป็นเพราะความผิดของตนด้วย"}},{"id":"TH-H004-A696","no":696,"noLabel":{"th":"มาตรา 696"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๙๖ ผู้ค้ำประกันไม่มีสิทธิจะไล่เบี้ยเอาแก่ลูกหนี้ได้ ถ้าว่าตนได้ชำระหนี้แทนไปโดยมิได้บอกลูกหนี้ และลูกหนี้ยังมิรู้ความมาชำระหนี้ซ้ำอีก ในกรณีเช่นว่านี้ ผู้ค้ำประกันก็ได้แต่เพียงจะฟ้องเจ้าหนี้เพื่อคืนลาภมิควรได้เท่านั้น"}},{"id":"TH-H004-A697","no":697,"noLabel":{"th":"มาตรา 697"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๖๙๗ ถ้าเพราะการกระทำอย่างใดอย่างหนึ่งของเจ้าหนี้เอง เป็นเหตุให้ผู้ค้ำประกันไม่อาจเข้ารับช่วงได้ทั้งหมดหรือแต่บางส่วนในสิทธิก็ดี จำนองก็ดี จำนำก็ดี และบุริมสิทธิอันได้ให้ไว้แก่เจ้าหนี้แต่ก่อนหรือในขณะทำสัญญาค้ำประกันเพื่อชำระหนี้นั้น ท่านว่าผู้ค้ำประกันย่อมหลุดพ้นจากความรับผิดเพียงเท่าที่ตนต้องเสียหายเพราะการนั้น"}},{"id":"TH-H004-A698","no":698,"noLabel":{"th":"มาตรา 698"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๖๙๘ อันผู้ค้ำประกันย่อมหลุดพ้นจากความรับผิด ในขณะเมื่อหนี้ของลูกหนี้ระงับสิ้นไปไม่ว่าเพราะเหตุใด ๆ"}},{"id":"TH-H004-A699","no":699,"noLabel":{"th":"มาตรา 699"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๖๙๙ การค้ำประกันเพื่อกิจการเนื่องกันไปหลายคราวไม่มีจำกัดเวลาเป็นคุณแก่เจ้าหนี้นั้น ท่านว่าผู้ค้ำประกันอาจเลิกเสียเพื่อคราวอันเป็นอนาคตได้ โดยบอกกล่าวความประสงค์นั้นแก่เจ้าหนี้ ในกรณีเช่นนี้ ท่านว่าผู้ค้ำประกันไม่ต้องรับผิดในกิจการที่ลูกหนี้กระทำลงภายหลังคำบอกกล่าวนั้นได้ไปถึงเจ้าหนี้"}},{"id":"TH-H004-A700","no":700,"noLabel":{"th":"มาตรา 700"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๐๐ ถ้าค้ำประกันหนี้อันจะต้องชำระ ณ เวลามีกำหนดแน่นอนและเจ้าหนี้ยอมผ่อนเวลาให้แก่ลูกหนี้ ผู้ค้ำประกันย่อมหลุดพ้นจากความรับผิด เว้นแต่ผู้ค้ำประกันจะได้ตกลงด้วยในการผ่อนเวลานั้น ข้อตกลงที่ผู้ค้ำประกันทำไว้ล่วงหน้าก่อนเจ้าหนี้ผ่อนเวลาอันมีผลเป็นการยินยอมให้เจ้าหนี้ผ่อนเวลา ข้อตกลงนั้นใช้บังคับมิได้ ความในวรรคสอง มิให้ใช้บังคับแก่กรณีผู้ค้ำประกันซึ่งเป็นสถาบันการเงินหรือค้ำประกันเพื่อสินจ้างเป็นปกติธุระ"}},{"id":"TH-H004-A701","no":701,"noLabel":{"th":"มาตรา 701"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๐๑ ผู้ค้ำประกันจะขอชำระหนี้แก่เจ้าหนี้ตั้งแต่เมื่อถึงกำหนดชำระก็ได้ ถ้าเจ้าหนี้ไม่ยอมรับชำระหนี้ ผู้ค้ำประกันก็เป็นอันหลุดพ้นจากความรับผิด"}},{"id":"TH-H004-A702","no":702,"noLabel":{"th":"มาตรา 702"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๒ อันว่าจำนองนั้น คือสัญญาซึ่งบุคคลคนหนึ่ง เรียกว่าผู้จำนอง เอาทรัพย์สินตราไว้แก่บุคคลอีกคนหนึ่ง เรียกว่าผู้รับจำนอง เป็นประกันการชำระหนี้ โดยไม่ส่งมอบทรัพย์สินนั้นให้แก่ผู้รับจำนอง ผู้รับจำนองชอบที่จะได้รับชำระหนี้จากทรัพย์สินที่จำนองก่อนเจ้าหนี้สามัญ มิพักต้องพิเคราะห์ว่ากรรมสิทธิ์ในทรัพย์สินจะได้โอนไปยังบุคคลภายนอกแล้วหรือหาไม่"}},{"id":"TH-H004-A703","no":703,"noLabel":{"th":"มาตรา 703"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๓ อันอสังหาริมทรัพย์นั้นอาจจำนองได้ไม่ว่าประเภทใด ๆ สังหาริมทรัพย์อันจะกล่าวต่อไปนี้ก็อาจจำนองได้ดุจกัน หากว่าได้จดทะเบียนไว้แล้วตามกฎหมาย คือ (๑) เรือมีระวางตั้งแต่ห้าตันขึ้นไป (๒) แพ (๓) สัตว์พาหนะ (๔) สังหาริมทรัพย์อื่นใด ๆ ซึ่งกฎหมายหากบัญญัติไว้ให้จดทะเบียนเฉพาะการ"}},{"id":"TH-H004-A704","no":704,"noLabel":{"th":"มาตรา 704"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๔ สัญญาจำนองต้องระบุทรัพย์สินซึ่งจำนอง"}},{"id":"TH-H004-A705","no":705,"noLabel":{"th":"มาตรา 705"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๕ การจำนองทรัพย์สินนั้น นอกจากผู้เป็นเจ้าของในขณะนั้นแล้ว ท่านว่าใครอื่นจะจำนองหาได้ไม่"}},{"id":"TH-H004-A706","no":706,"noLabel":{"th":"มาตรา 706"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๖ บุคคลมีกรรมสิทธิ์ในทรัพย์สินแต่ภายในบังคับเงื่อนไขเช่นใด จะจำนองทรัพย์สินนั้นได้แต่ภายในบังคับเงื่อนไขเช่นนั้น"}},{"id":"TH-H004-A707","no":707,"noLabel":{"th":"มาตรา 707"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๗ บทบัญญัติมาตรา ๖๘๑ ว่าด้วยค้ำประกันนั้น ท่านให้ใช้ได้ในการจำนอง อนุโลมตามควร"}},{"id":"TH-H004-A708","no":708,"noLabel":{"th":"มาตรา 708"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๘ สัญญาจำนองนั้นต้องมีจำนวนเงินระบุไว้เป็นเรือนเงินไทยเป็นจำนวนแน่ตรงตัว หรือจำนวนขั้นสูงสุดที่ได้เอาทรัพย์สินจำนองนั้นตราไว้เป็นประกัน"}},{"id":"TH-H004-A709","no":709,"noLabel":{"th":"มาตรา 709"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๐๙ บุคคลหนึ่งจะจำนองทรัพย์สินของตนไว้เพื่อประกันหนี้อันบุคคลอื่นจะต้องชำระ ก็ให้ทำได้"}},{"id":"TH-H004-A710","no":710,"noLabel":{"th":"มาตรา 710"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๐ ทรัพย์สินหลายสิ่งมีเจ้าของคนเดียวหรือหลายคน จะจำนองเพื่อประกันการชำระหนี้แต่รายหนึ่งรายเดียว ท่านก็ให้ทำได้ และในการนี้คู่สัญญาจะตกลงกันดังต่อไปนี้ก็ได้ คือว่า (๑) ให้ผู้รับจำนองใช้สิทธิบังคับเอาแก่ทรัพย์สินซึ่งจำนองตามลำดับอันระบุไว้ (๒) ให้ถือเอาทรัพย์สินแต่ละสิ่งเป็นประกันหนี้เฉพาะแต่ส่วนหนึ่งส่วนใดที่ระบุไว้"}},{"id":"TH-H004-A711","no":711,"noLabel":{"th":"มาตรา 711"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๑ การที่จะตกลงกันไว้เสียแต่ก่อนเวลาหนี้ถึงกำหนดชำระเป็นข้อความอย่างใดอย่างหนึ่งว่า ถ้าไม่ชำระหนี้ ให้ผู้รับจำนองเข้าเป็นเจ้าของทรัพย์สินซึ่งจำนอง หรือว่าให้จัดการแก่ทรัพย์สินนั้นเป็นประการอื่นอย่างใด นอกจากตามบทบัญญัติทั้งหลายว่าด้วยการบังคับจำนองนั้นไซร้ ข้อตกลงเช่นนั้นท่านว่าไม่สมบูรณ์"}},{"id":"TH-H004-A712","no":712,"noLabel":{"th":"มาตรา 712"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๒ แม้ถึงว่ามีข้อสัญญาเป็นอย่างอื่นก็ตาม ทรัพย์สินซึ่งจำนองไว้แก่บุคคลหนึ่งนั้น ท่านว่าจะเอาไปจำนองแก่บุคคลอีกคนหนึ่งในระหว่างเวลาที่สัญญาก่อนยังมีอายุอยู่ก็ได้"}},{"id":"TH-H004-A713","no":713,"noLabel":{"th":"มาตรา 713"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๓ ถ้ามิได้ตกลงกันไว้เป็นอย่างอื่นในสัญญาจำนอง ท่านว่าผู้จำนองจะชำระหนี้ล้างจำนองเป็นงวด ๆ ก็ได้"}},{"id":"TH-H004-A714","no":714,"noLabel":{"th":"มาตรา 714"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๔ อันสัญญาจำนองนั้น ท่านว่าต้องทำเป็นหนังสือและจดทะเบียนต่อพนักงานเจ้าหน้าที่"}},{"id":"TH-H004-A714.001","no":714.001,"noLabel":{"th":"มาตรา 714/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๑๔/๑ บรรดาข้อตกลงเกี่ยวกับการจำนองที่แตกต่างไปจากมาตรา ๗๒๘ มาตรา ๗๒๙ และมาตรา ๗๓๕ เป็นโมฆะ"}},{"id":"TH-H004-A715","no":715,"noLabel":{"th":"มาตรา 715"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๑๕ ทรัพย์สินซึ่งจำนองย่อมเป็นประกันเพื่อการชำระหนี้กับทั้งค่าอุปกรณ์ต่อไปนี้ด้วย คือ (๑) ดอกเบี้ย (๒) ค่าสินไหมทดแทนในการไม่ชำระหนี้ (๓) ค่าฤชาธรรมเนียมในการบังคับจำนอง"}},{"id":"TH-H004-A716","no":716,"noLabel":{"th":"มาตรา 716"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๑๖ จำนองย่อมครอบไปถึงบรรดาทรัพย์สินซึ่งจำนองหมดทุกสิ่ง แม้จะได้ชำระหนี้แล้วบางส่วน"}},{"id":"TH-H004-A717","no":717,"noLabel":{"th":"มาตรา 717"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๑๗ แม้ว่าทรัพย์สินซึ่งจำนองจะแบ่งออกเป็นหลายส่วนก็ตาม ท่านว่าจำนองก็ยังคงครอบไปถึงส่วนเหล่านั้นหมดทุกส่วนด้วยกันอยู่นั่นเอง ถึงกระนั้นก็ดี ถ้าผู้รับจำนองยินยอมด้วย ท่านว่าจะโอนทรัพย์สินส่วนหนึ่งส่วนใดไปปลอดจากจำนองก็ให้ทำได้ แต่ความยินยอมดังว่านี้ หากมิได้จดทะเบียน ท่านว่าจะยกเอาขึ้นเป็นข้อต่อสู้แก่บุคคลภายนอกหาได้ไม่"}},{"id":"TH-H004-A718","no":718,"noLabel":{"th":"มาตรา 718"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๑๘ จำนองย่อมครอบไปถึงทรัพย์ทั้งปวงอันติดพันอยู่กับทรัพย์สินซึ่งจำนอง แต่ต้องอยู่ภายในบังคับซึ่งท่านจำกัดไว้ในสามมาตราต่อไปนี้"}},{"id":"TH-H004-A719","no":719,"noLabel":{"th":"มาตรา 719"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๑๙ จำนองที่ดินไม่ครอบไปถึงเรือนโรงอันผู้จำนองปลูกสร้างลงในที่ดินภายหลังวันจำนอง เว้นแต่จะมีข้อความกล่าวไว้โดยเฉพาะในสัญญาว่าให้ครอบไปถึง แต่กระนั้นก็ดี ผู้รับจำนองจะให้ขายเรือนโรงนั้นรวมไปกับที่ดินด้วยก็ได้ แต่ผู้รับจำนองอาจใช้บุริมสิทธิของตนได้เพียงแก่ราคาที่ดินเท่านั้น"}},{"id":"TH-H004-A720","no":720,"noLabel":{"th":"มาตรา 720"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๒๐ จำนองเรือนโรงหรือสิ่งปลูกสร้างอย่างอื่นซึ่งได้ทำขึ้นไว้บนดินหรือใต้ดิน ในที่ดินอันเป็นของคนอื่นเขานั้นย่อมไม่ครอบไปถึงที่ดินนั้นด้วย ฉันใดกลับกันก็ฉันนั้น"}},{"id":"TH-H004-A721","no":721,"noLabel":{"th":"มาตรา 721"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๒๑ จำนองไม่ครอบไปถึงดอกผลแห่งทรัพย์สินซึ่งจำนอง เว้นแต่ในเมื่อผู้รับจำนองได้บอกกล่าวแก่ผู้จำนองหรือผู้รับโอนแล้วว่าตนจำนงจะบังคับจำนอง"}},{"id":"TH-H004-A722","no":722,"noLabel":{"th":"มาตรา 722"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๒ ถ้าทรัพย์สินได้จำนองแล้ว และภายหลังที่จดทะเบียนจำนองมีจดทะเบียนภาระจำยอมหรือทรัพยสิทธิอย่างอื่น โดยผู้รับจำนองมิได้ยินยอมด้วยไซร้ ท่านว่าสิทธิจำนองย่อมเป็นใหญ่กว่าภาระจำยอมหรือทรัพยสิทธิอย่างอื่นนั้น หากว่าเป็นที่เสื่อมเสียแก่สิทธิของผู้รับจำนองในเวลาบังคับจำนอง ก็ให้ลบสิทธิที่กล่าวหลังนั้นเสียจากทะเบียน"}},{"id":"TH-H004-A723","no":723,"noLabel":{"th":"มาตรา 723"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๓ ถ้าทรัพย์สินซึ่งจำนองบุบสลาย หรือถ้าทรัพย์สินซึ่งจำนองแต่สิ่งใดสิ่งหนึ่งสูญหายหรือบุบสลาย เป็นเหตุให้ไม่เพียงพอแก่การประกันไซร้ ท่านว่าผู้รับจำนองจะบังคับจำนองเสียในทันทีก็ได้ เว้นแต่เมื่อเหตุนั้นมิได้เป็นเพราะความผิดของผู้จำนอง และผู้จำนองก็เสนอจะจำนองทรัพย์สินอื่นแทนให้มีราคาเพียงพอ หรือเสนอจะรับซ่อมแซมแก้ไขความบุบสลายนั้นภายในเวลาอันสมควรแก่เหตุ"}},{"id":"TH-H004-A724","no":724,"noLabel":{"th":"มาตรา 724"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๔ ผู้จำนองใดได้จำนองทรัพย์สินของตนไว้เพื่อประกันหนี้อันบุคคลอื่นจะต้องชำระแล้ว และเข้าชำระหนี้เสียเองแทนลูกหนี้เพื่อจะปัดป้องมิให้ต้องบังคับจำนอง ท่านว่าผู้จำนองนั้นชอบที่จะได้รับเงินใช้คืนจากลูกหนี้ตามจำนวนที่ตนได้ชำระไป ถ้าว่าต้องบังคับจำนอง ท่านว่าผู้จำนองชอบที่จะได้รับเงินใช้คืนจากลูกหนี้ตามจำนวนซึ่งผู้รับจำนองจะได้รับใช้หนี้จากการบังคับจำนองนั้น"}},{"id":"TH-H004-A725","no":725,"noLabel":{"th":"มาตรา 725"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๕ เมื่อบุคคลสองคนหรือกว่านั้นต่างได้จำนองทรัพย์สินแห่งตนเพื่อประกันหนี้แต่รายหนึ่งรายเดียวอันบุคคลอื่นจะต้องชำระและมิได้ระบุลำดับไว้ไซร้ ท่านว่าผู้จำนองซึ่งได้เป็นผู้ชำระหนี้ หรือเป็นเจ้าของทรัพย์สินซึ่งต้องบังคับจำนองนั้นหามีสิทธิจะไล่เบี้ยเอาแก่ผู้จำนองอื่น ๆ ต่อไปได้ไม่"}},{"id":"TH-H004-A726","no":726,"noLabel":{"th":"มาตรา 726"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๖ เมื่อบุคคลหลายคนต่างได้จำนองทรัพย์สินแห่งตนเพื่อประกันหนี้แต่รายหนึ่งรายเดียวอันบุคคลอื่นจะต้องชำระและได้ระบุลำดับไว้ด้วยไซร้ ท่านว่าการที่ผู้รับจำนองยอมปลดหนี้ให้แก่ผู้จำนองคนหนึ่งนั้น ย่อมทำให้ผู้จำนองคนหลัง ๆ ได้หลุดพ้นด้วยเพียงขนาดที่เขาต้องรับความเสียหายแต่การนั้น"}},{"id":"TH-H004-A727","no":727,"noLabel":{"th":"มาตรา 727"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๗ ให้นำบทบัญญัติมาตรา ๖๙๑ มาตรา ๖๙๗ มาตรา ๗๐๐ และมาตรา ๗๐๑ มาใช้บังคับกับกรณีที่บุคคลจำนองทรัพย์สินเพื่อประกันหนี้อันบุคคลอื่นจะต้องชำระด้วยโดยอนุโลม"}},{"id":"TH-H004-A727.001","no":727.001,"noLabel":{"th":"มาตรา 727/1"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๒๗/๑ ไม่ว่ากรณีจะเป็นประการใด ผู้จำนองซึ่งจำนองทรัพย์สินของตนไว้เพื่อประกันหนี้อันบุคคลอื่นจะต้องชำระ ไม่ต้องรับผิดในหนี้นั้นเกินราคาทรัพย์สินที่จำนองในเวลาที่บังคับจำนองหรือเอาทรัพย์จำนองหลุด ข้อตกลงใดอันมีผลให้ผู้จำนองรับผิดเกินที่บัญญัติไว้ในวรรคหนึ่ง หรือให้ผู้จำนองรับผิดอย่างผู้ค้ำประกัน ข้อตกลงนั้นเป็นโมฆะ ไม่ว่าข้อตกลงนั้นจะมีอยู่ในสัญญาจำนองหรือทำเป็นข้อตกลงต่างหาก ทั้งนี้ เว้นแต่เป็นกรณีที่นิติบุคคลเป็นลูกหนี้และบุคคลผู้มีอำนาจในการจัดการตามกฎหมายหรือบุคคลที่มีอำนาจควบคุมการดำเนินงานของนิติบุคคลนั้นเป็นผู้จำนองทรัพย์สินของตนไว้เพื่อประกันหนี้นั้นของนิติบุคคลและผู้จำนองได้ทำสัญญาค้ำประกันไว้เป็นสัญญาต่างหาก"}},{"id":"TH-H004-A728","no":728,"noLabel":{"th":"มาตรา 728"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๒๘ เมื่อจะบังคับจำนองนั้น ผู้รับจำนองต้องมีหนังสือบอกกล่าวไปยังลูกหนี้ก่อนว่าให้ชำระหนี้ภายในเวลาอันสมควรซึ่งต้องไม่น้อยกว่าหกสิบวันนับแต่วันที่ลูกหนี้ได้รับคำบอกกล่าวนั้น ถ้าและลูกหนี้ละเลยเสียไม่ปฏิบัติตามคำบอกกล่าว ผู้รับจำนองจะฟ้องคดีต่อศาลเพื่อให้พิพากษาสั่งให้ยึดทรัพย์สินซึ่งจำนองและให้ขายทอดตลาดก็ได้ ในกรณีตามวรรคหนึ่ง ถ้าเป็นกรณีผู้จำนองซึ่งจำนองทรัพย์สินของตนไว้เพื่อประกันหนี้อันบุคคลอื่นต้องชำระ ผู้รับจำนองต้องส่งหนังสือบอกกล่าวดังกล่าวให้ผู้จำนองทราบภายในสิบห้าวันนับแต่วันที่ส่งหนังสือแจ้งให้ลูกหนี้ทราบ ถ้าผู้รับจำนองมิได้ดำเนินการภายในกำหนดเวลาสิบห้าวันนั้น ให้ผู้จำนองเช่นว่านั้นหลุดพ้นจากความรับผิดในดอกเบี้ยและค่าสินไหมทดแทนซึ่งลูกหนี้ค้างชำระ ตลอดจนค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้นบรรดาที่เกิดขึ้นนับแต่วันที่พ้นกำหนดเวลาสิบห้าวันดังกล่าว"}},{"id":"TH-H004-A729","no":729,"noLabel":{"th":"มาตรา 729"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๒๙ ในการบังคับจำนองตามมาตรา ๗๒๘ ถ้าไม่มีการจำนองรายอื่นหรือบุริมสิทธิอื่นอันได้จดทะเบียนไว้เหนือทรัพย์สินอันเดียวกันนี้ ผู้รับจำนองจะฟ้องคดีต่อศาลเพื่อเรียกเอาทรัพย์จำนองหลุดภายในบังคับแห่งเงื่อนไขดังจะกล่าวต่อไปนี้แทนการขายทอดตลาดก็ได้ (๑) ลูกหนี้ได้ขาดส่งดอกเบี้ยมาแล้วเป็นเวลาถึงห้าปี และ (๒) ผู้รับจำนองแสดงให้เป็นที่พอใจแก่ศาลว่าราคาทรัพย์สินนั้นน้อยกว่าจำนวนเงินอันค้างชำระ"}},{"id":"TH-H004-A729.001","no":729.001,"noLabel":{"th":"มาตรา 729/1"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๒๙/๑ เวลาใด ๆ หลังจากที่หนี้ถึงกำหนดชำระ ถ้าไม่มีการจำนองรายอื่นหรือบุริมสิทธิอื่นอันได้จดทะเบียนไว้เหนือทรัพย์สินอันเดียวกันนี้ ผู้จำนองมีสิทธิแจ้งเป็นหนังสือไปยังผู้รับจำนองเพื่อให้ผู้รับจำนองดำเนินการให้มีการขายทอดตลาดทรัพย์สินที่จำนองโดยไม่ต้องฟ้องเป็นคดีต่อศาล โดยผู้รับจำนองต้องดำเนินการขายทอดตลาดทรัพย์สินที่จำนองภายในเวลาหนึ่งปีนับแต่วันที่ได้รับหนังสือแจ้งนั้น ทั้งนี้ ให้ถือว่าหนังสือแจ้งของผู้จำนองเป็นหนังสือยินยอมให้ขายทอดตลาด ในกรณีที่ผู้รับจำนองไม่ได้ดำเนินการขายทอดตลาดทรัพย์สินที่จำนองภายในระยะเวลาที่กำหนดไว้ในวรรคหนึ่ง ให้ผู้จำนองพ้นจากความรับผิดในดอกเบี้ยและค่าสินไหมทดแทนซึ่งลูกหนี้ค้างชำระ ตลอดจนค่าภาระติดพันอันเป็นอุปกรณ์แห่งหนี้รายนั้นบรรดาที่เกิดขึ้นภายหลังวันที่พ้นกำหนดเวลาดังกล่าว เมื่อผู้รับจำนองขายทอดตลาดทรัพย์สินที่จำนองได้เงินสุทธิจำนวนเท่าใด ผู้รับจำนองต้องจัดสรรชำระหนี้และอุปกรณ์ให้เสร็จสิ้นไป ถ้ายังมีเงินเหลือก็ต้องส่งคืนให้แก่ผู้จำนอง หรือแก่บุคคลผู้ควรจะได้เงินนั้น แต่ถ้าได้เงินน้อยกว่าจำนวนที่ค้างชำระ ให้เป็นไปตามที่กำหนดไว้ในมาตรา ๗๓๓ และในกรณีที่ผู้จำนองเป็นบุคคลซึ่งจำนองทรัพย์สินเพื่อประกันหนี้อันบุคคลอื่นจะต้องชำระ ผู้จำนองย่อมรับผิดเพียงเท่าที่มาตรา ๗๒๗/๑ กำหนดไว้"}},{"id":"TH-H004-A730","no":730,"noLabel":{"th":"มาตรา 730"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๐ เมื่อทรัพย์สินอันหนึ่งอันเดียวได้จำนองแก่ผู้รับจำนองหลายคนด้วยกัน ท่านให้ถือลำดับผู้รับจำนองเรียงตามวันและเวลาจดทะเบียน และผู้รับจำนองคนก่อนจักได้รับใช้หนี้ก่อนผู้รับจำนองคนหลัง"}},{"id":"TH-H004-A731","no":731,"noLabel":{"th":"มาตรา 731"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๑ อันผู้รับจำนองคนหลังจะบังคับตามสิทธิของตนให้เสียหายแก่ผู้รับจำนองคนก่อนนั้น ท่านว่าหาอาจทำได้ไม่"}},{"id":"TH-H004-A732","no":732,"noLabel":{"th":"มาตรา 732"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๒ ทรัพย์สินซึ่งจำนองขายทอดตลาดได้เงินเป็นจำนวนสุทธิเท่าใด ท่านให้จัดใช้แก่ผู้รับจำนองเรียงตามลำดับ และถ้ายังมีเงินเหลืออยู่อีก ก็ให้ส่งมอบแก่ผู้จำนอง"}},{"id":"TH-H004-A733","no":733,"noLabel":{"th":"มาตรา 733"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๓ ถ้าเอาทรัพย์จำนองหลุดและราคาทรัพย์สินนั้นมีประมาณต่ำกว่าจำนวนเงินที่ค้างชำระกันอยู่ก็ดี หรือถ้าเอาทรัพย์สินซึ่งจำนองออกขายทอดตลาดใช้หนี้ได้เงินจำนวนสุทธิน้อยกว่าจำนวนเงินที่ค้างชำระกันอยู่นั้นก็ดี เงินยังขาดจำนวนอยู่เท่าใดลูกหนี้ไม่ต้องรับผิดในเงินนั้น"}},{"id":"TH-H004-A734","no":734,"noLabel":{"th":"มาตรา 734"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๔ ถ้าจำนองทรัพย์สินหลายสิ่งเพื่อประกันหนี้แต่รายหนึ่งรายเดียวและมิได้ระบุลำดับไว้ไซร้ ท่านว่าผู้รับจำนองจะใช้สิทธิของตนบังคับแก่ทรัพย์สินนั้น ๆ ทั้งหมดหรือแต่เพียงบางสิ่งก็ได้ แต่ท่านห้ามมิให้ทำเช่นนั้นแก่ทรัพย์สินมากสิ่งกว่าที่จำเป็นเพื่อใช้หนี้ตามสิทธิแห่งตน ถ้าผู้รับจำนองใช้สิทธิของตนบังคับแก่ทรัพย์สินทั้งหมดพร้อมกัน ท่านให้แบ่งภาระแห่งหนี้นั้นกระจายไปตามส่วนราคาแห่งทรัพย์สินนั้น ๆ เว้นแต่ในกรณีที่ได้ระบุจำนวนเงินจำนองไว้เฉพาะทรัพย์สินแต่ละสิ่ง ๆ เป็นจำนวนเท่าใด ท่านให้แบ่งกระจายไปตามจำนวนเงินจำนองที่ระบุไว้เฉพาะทรัพย์สิ่งนั้น ๆ แต่ถ้าผู้รับจำนองใช้สิทธิของตนบังคับแก่ทรัพย์สินอันใดอันหนึ่งแต่เพียงสิ่งเดียวไซร้ ผู้รับจำนองจะให้ชำระหนี้อันเป็นส่วนของตนทั้งหมดจากทรัพย์สินอันนั้นก็ได้ ในกรณีเช่นนั้น ท่านให้ถือว่าผู้รับจำนองคนถัดไปโดยลำดับย่อมเข้ารับช่วงสิทธิของผู้รับจำนองคนก่อนและจะเข้าบังคับจำนองแทนที่คนก่อนก็ได้แต่เพียงเท่าจำนวนซึ่งผู้รับจำนองคนก่อนจะพึงได้รับจากทรัพย์สินอื่น ๆ ตามบทบัญญัติดังกล่าวมาในวรรคก่อนนั้น"}},{"id":"TH-H004-A735","no":735,"noLabel":{"th":"มาตรา 735"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๓๕ เมื่อผู้รับจำนองคนใดจะบังคับจำนองเอาแก่ผู้รับโอนทรัพย์สินซึ่งจำนอง ผู้รับจำนองต้องมีจดหมายบอกกล่าวแก่ผู้รับโอนล่วงหน้าเป็นระยะเวลาไม่น้อยกว่าหกสิบวันก่อน จึงจะบังคับจำนองได้"}},{"id":"TH-H004-A736","no":736,"noLabel":{"th":"มาตรา 736"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๓๖ ผู้รับโอนทรัพย์สินซึ่งจำนองจะไถ่ถอนจำนองก็ได้ ถ้าหากมิได้เป็นตัวลูกหนี้หรือผู้ค้ำประกัน หรือเป็นทายาทของลูกหนี้หรือผู้ค้ำประกัน"}},{"id":"TH-H004-A737","no":737,"noLabel":{"th":"มาตรา 737"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๓๗ ผู้รับโอนจะไถ่ถอนจำนองเมื่อใดก็ได้ แต่ถ้าผู้รับจำนองได้บอกกล่าวว่าจะบังคับจำนอง ผู้รับโอนต้องไถ่ถอนจำนองภายในหกสิบวันนับแต่วันรับคำบอกกล่าว"}},{"id":"TH-H004-A738","no":738,"noLabel":{"th":"มาตรา 738"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๓๘ ผู้รับโอนซึ่งประสงค์จะไถ่ถอนจำนองต้องบอกกล่าวความประสงค์นั้นแก่ผู้เป็นลูกหนี้ชั้นต้น และต้องส่งคำเสนอไปยังบรรดาเจ้าหนี้ที่ได้จดทะเบียน ไม่ว่าในทางจำนองหรือประการอื่น ว่าจะรับใช้เงินให้เป็นจำนวนอันสมควรกับราคาทรัพย์สินนั้น คำเสนอนั้นให้แจ้งข้อความทั้งหลายต่อไปนี้ คือ (๑) ตำแหน่งแหล่งที่และลักษณะแห่งทรัพย์สินซึ่งจำนอง (๒) วันซึ่งโอนกรรมสิทธิ์ (๓) ชื่อเจ้าของเดิม (๔) ชื่อและภูมิลำเนาของผู้รับโอน (๕) จำนวนเงินที่เสนอว่าจะใช้ (๖) คำนวณยอดจำนวนเงินที่ค้างชำระแก่เจ้าหนี้คนหนึ่ง ๆ รวมทั้งอุปกรณ์และจำนวนเงินที่จะจัดเป็นส่วนใช้แก่บรรดาเจ้าหนี้ตามลำดับกัน อนึ่ง ให้คัดสำเนารายงานจดทะเบียนของเจ้าพนักงานในเรื่องทรัพย์สินซึ่งจำนองนั้น อันเจ้าพนักงานรับรองว่าเป็นสำเนาถูกถ้วนสอดส่งไปด้วย"}},{"id":"TH-H004-A739","no":739,"noLabel":{"th":"มาตรา 739"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๓๙ ถ้าเจ้าหนี้คนหนึ่งคนใดไม่ยอมรับคำเสนอ เจ้าหนี้คนนั้นต้องฟ้องคดีต่อศาลภายในเดือนหนึ่งนับแต่วันมีคำเสนอเพื่อให้ศาลพิจารณาสั่งขายทอดตลาดทรัพย์สินซึ่งจำนองนั้น แต่ว่าเจ้าหนี้นั้นจะต้องปฏิบัติการดังจะกล่าวต่อไปนี้ด้วย คือ (๑) ออกเงินทดรองค่าฤชาธรรมเนียมการขายทอดตลาด (๒) ต้องเข้าสู้ราคาเอง หรือแต่งคนเข้าสู้ราคาเป็นจำนวนเงินสูงกว่าที่ผู้รับโอนเสนอจะใช้ (๓) บอกกล่าวการที่ตนไม่ยอมนั้นให้ผู้รับโอนและเจ้าหนี้คนอื่น ๆ บรรดาได้จดทะเบียน กับทั้งเจ้าของทรัพย์คนก่อนและลูกหนี้ชั้นต้นทราบด้วย"}},{"id":"TH-H004-A740","no":740,"noLabel":{"th":"มาตรา 740"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๔๐ ถ้าขายทอดตลาดได้เงินจำนวนสุทธิล้ำจำนวนเงินที่ผู้รับโอนเสนอว่าจะใช้ ท่านให้ผู้รับโอนเป็นผู้ออกใช้ค่าฤชาธรรมเนียมในการขายทอดตลาด ถ้าได้ไม่ถึงล้ำจำนวน ท่านให้เจ้าหนี้ผู้ร้องขอให้ขายทอดตลาดเป็นผู้ออก"}},{"id":"TH-H004-A741","no":741,"noLabel":{"th":"มาตรา 741"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๔๑ เมื่อเจ้าหนี้ทั้งหลายได้สนองรับคำเสนอทั่วทุกคนแล้ว โดยแสดงออกชัดหรือโดยปริยายก็ดี ท่านว่าจำนองหรือบุริมสิทธิก็เป็นอันไถ่ถอนได้ด้วยผู้รับโอนใช้เงินหรือวางเงินตามจำนวนที่เสนอจะใช้แทนการชำระหนี้"}},{"id":"TH-H004-A742","no":742,"noLabel":{"th":"มาตรา 742"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๔๒ ถ้าการบังคับจำนองก็ดี ถอนจำนองก็ดี เป็นเหตุให้ทรัพย์สินซึ่งจำนองหลุดมือไปจากบุคคลผู้ได้ทรัพย์สินนั้นไว้แต่ก่อนไซร้ ท่านว่าการที่ทรัพย์สินหลุดมือไปเช่นนั้นหามีผลย้อนหลังไม่ และบุริมสิทธิทั้งหลายของเจ้าหนี้แห่งผู้ที่ทรัพย์หลุดมือไปอันมีอยู่เหนือทรัพย์สินและได้จดทะเบียนไว้นั้น ก็ย่อมเข้าอยู่ในลำดับหลังบุริมสิทธิอันเจ้าหนี้ของผู้จำนอง หรือเจ้าของคนก่อนได้จดทะเบียนไว้ ในกรณีเช่นนี้ ถ้าสิทธิใด ๆ อันมีอยู่เหนือทรัพย์สินซึ่งจำนองเป็นคุณหรือเป็นโทษแก่บุคคลผู้ได้ทรัพย์สินซึ่งจำนองไว้แต่ก่อนได้ระงับไปแล้วด้วยเกลื่อนกลืนกันในขณะที่ได้ทรัพย์สินนั้นมาไซร้ สิทธินั้นท่านให้กลับคืนมาเป็นคุณหรือเป็นโทษแก่บุคคลผู้นั้นได้อีก ในเมื่อทรัพย์สินซึ่งจำนองกลับหลุดมือไป"}},{"id":"TH-H004-A743","no":743,"noLabel":{"th":"มาตรา 743"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๗๔๓ ถ้าผู้รับโอนได้ทำให้ทรัพย์สินซึ่งจำนองเสื่อมราคาลงเพราะการกระทำหรือความประมาทเลินเล่อแห่งตน เป็นเหตุให้เจ้าหนี้ทั้งหลายผู้มีสิทธิจำนองหรือบุริมสิทธิเหนือทรัพย์สินนั้นต้องเสียหายไซร้ ท่านว่าผู้รับโอนจะต้องรับผิดเพื่อความเสียหายนั้น อย่างไรก็ดี อันผู้รับโอนจะเรียกเอาเงินจำนวนใด ๆ ซึ่งตนได้ออกไป หรือเรียกให้ชดใช้ค่าใช้จ่ายที่ตนได้ทำให้ทรัพย์สินดีขึ้นนั้น ท่านว่าหาอาจจะเรียกได้ไม่ เว้นแต่ที่เป็นการทำให้ทรัพย์สินนั้นงอกราคาขึ้นและจะเรียกได้เพียงเท่าจำนวนราคาที่งอกขึ้นเมื่อขายทอดตลาดเท่านั้น"}},{"id":"TH-H004-A744","no":744,"noLabel":{"th":"มาตรา 744"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๗๔๔ อันจำนองย่อมระงับสิ้นไป (๑) เมื่อหนี้ที่ประกันระงับสิ้นไปด้วยเหตุประการอื่นใดมิใช่เหตุอายุความ (๒) เมื่อปลดจำนองให้แก่ผู้จำนองด้วยหนังสือเป็นสำคัญ (๓) เมื่อผู้จำนองหลุดพ้น (๔) เมื่อถอนจำนอง (๕) เมื่อขายทอดตลาดทรัพย์สินซึ่งจำนองตามคำสั่งศาลอันเนื่องมาแต่การบังคับจำนองหรือถอนจำนอง หรือเมื่อมีการขายทอดตลาดทรัพย์สินตามมาตรา ๗๒๙/๑ (๖) เมื่อเอาทรัพย์สินซึ่งจำนองนั้นหลุด"}},{"id":"TH-H004-A745","no":745,"noLabel":{"th":"มาตรา 745"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๗๔๕ ผู้รับจำนองจะบังคับจำนองแม้เมื่อหนี้ที่ประกันนั้นขาดอายุความแล้วก็ได้ แต่จะบังคับเอาดอกเบี้ยที่ค้างชำระในการจำนองเกินกว่าห้าปีไม่ได้"}},{"id":"TH-H004-A746","no":746,"noLabel":{"th":"มาตรา 746"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๗๔๖ การชำระหนี้ไม่ว่าครั้งใด ๆ สิ้นเชิงหรือแต่บางส่วนก็ดี การระงับหนี้อย่างใด ๆ ก็ดี การตกลงกันแก้ไขเปลี่ยนแปลงจำนองหรือหนี้อันจำนองเป็นประกันนั้นเป็นประการใดก็ดี ท่านว่าต้องนำความไปจดทะเบียนต่อพนักงานเจ้าหน้าที่ในเมื่อมีคำร้องของผู้มีส่วนได้เสีย มิฉะนั้นท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอก"}},{"id":"TH-H004-A747","no":747,"noLabel":{"th":"มาตรา 747"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๔๗ อันว่าจำนำนั้น คือสัญญาซึ่งบุคคลหนึ่ง เรียกว่าผู้จำนำ ส่งมอบสังหาริมทรัพย์สิ่งหนึ่งให้แก่บุคคลอีกคนหนึ่ง เรียกว่าผู้รับจำนำ เพื่อเป็นประกันการชำระหนี้"}},{"id":"TH-H004-A748","no":748,"noLabel":{"th":"มาตรา 748"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๔๘ การจำนำนั้นย่อมเป็นประกันเพื่อการชำระหนี้ กับทั้งค่าอุปกรณ์ต่อไปนี้ด้วย คือ (๑) ดอกเบี้ย (๒) ค่าสินไหมทดแทนในการไม่ชำระหนี้ (๓) ค่าฤชาธรรมเนียมในการบังคับจำนำ (๔) ค่าใช้จ่ายเพื่อรักษาทรัพย์สินซึ่งจำนำ (๕) ค่าสินไหมทดแทนเพื่อความเสียหายอันเกิดแต่ความชำรุดบกพร่องแห่งทรัพย์สินจำนำซึ่งไม่เห็นประจักษ์"}},{"id":"TH-H004-A749","no":749,"noLabel":{"th":"มาตรา 749"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๔๙ คู่สัญญาจำนำจะตกลงกันให้บุคคลภายนอกเป็นผู้เก็บรักษาทรัพย์สินจำนำไว้ก็ได้"}},{"id":"TH-H004-A750","no":750,"noLabel":{"th":"มาตรา 750"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๐ ถ้าทรัพย์สินที่จำนำเป็นสิทธิซึ่งมีตราสารและมิได้ส่งมอบตราสารนั้นให้แก่ผู้รับจำนำ ทั้งมิได้บอกกล่าวเป็นหนังสือแจ้งการจำนำแก่ลูกหนี้แห่งสิทธินั้นด้วยไซร้ ท่านว่าการจำนำย่อมเป็นโมฆะ"}},{"id":"TH-H004-A751","no":751,"noLabel":{"th":"มาตรา 751"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๑ ถ้าจำนำตราสารชนิดออกให้แก่บุคคลเพื่อเขาสั่ง ท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอก เว้นแต่จะได้สลักหลังไว้ที่ตราสารให้ปรากฏการจำนำเช่นนั้น อนึ่ง ในการนี้ไม่จำเป็นต้องบอกกล่าวแก่ลูกหนี้แห่งตราสาร"}},{"id":"TH-H004-A752","no":752,"noLabel":{"th":"มาตรา 752"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๒ ถ้าจำนำตราสารชนิดออกให้แก่บุคคลโดยนามและจะโอนกันด้วยสลักหลังไม่ได้ ท่านว่าต้องจดข้อความแสดงการจำนำไว้ให้ปรากฏในตราสารนั้นเอง และท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้ลูกหนี้แห่งตราสารหรือบุคคลภายนอก เว้นแต่จะได้บอกกล่าวการจำนำนั้นให้ทราบถึงลูกหนี้แห่งตราสาร"}},{"id":"TH-H004-A753","no":753,"noLabel":{"th":"มาตรา 753"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๓ ถ้าจำนำใบหุ้น หรือใบหุ้นกู้ชนิดระบุชื่อท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บริษัทหรือบุคคลภายนอก เว้นแต่จะได้จดทะเบียนการจำนำนั้นไว้ในสมุดของบริษัทตามบทบัญญัติทั้งหลายในลักษณะ ๒๒ ว่าด้วยการโอนหุ้นหรือหุ้นกู้"}},{"id":"TH-H004-A754","no":754,"noLabel":{"th":"มาตรา 754"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๔ ถ้าสิทธิซึ่งจำนำนั้นถึงกำหนดชำระก่อนหนี้ซึ่งประกันไว้นั้นไซร้ ท่านว่าลูกหนี้แห่งสิทธิต้องส่งมอบทรัพย์สินอันเป็นวัตถุแห่งสิทธิให้แก่ผู้รับจำนำ และทรัพย์สินนั้นก็กลายเป็นของจำนำแทนสิทธิซึ่งจำนำ ถ้าสิทธิซึ่งจำนำนั้นเป็นมูลหนี้ซึ่งต้องชำระเป็นเงิน และถึงกำหนดชำระก่อนหนี้ซึ่งประกันไว้นั้นไซร้ ท่านว่าต้องใช้เงินให้แก่ผู้รับจำนำและผู้จำนำร่วมกัน ถ้าและเขาทั้งสองนั้นไม่ปรองดองตกลงกันได้ ท่านว่าแต่ละคนชอบที่จะเรียกให้วางเงินจำนวนนั้นไว้ ณ สำนักงานฝากทรัพย์ได้เพื่อประโยชน์อันร่วมกัน"}},{"id":"TH-H004-A755","no":755,"noLabel":{"th":"มาตรา 755"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๕ ถ้าจำนำสิทธิ ท่านห้ามมิให้ทำสิทธินั้นให้สิ้นไป หรือแก้ไขสิทธินั้นให้เสียหายแก่ผู้รับจำนำโดยผู้รับจำนำมิได้ยินยอมด้วย"}},{"id":"TH-H004-A756","no":756,"noLabel":{"th":"มาตรา 756"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๖ การที่จะตกลงกันไว้เสียแต่ก่อนเวลาหนี้ถึงกำหนดชำระเป็นข้อความอย่างใดอย่างหนึ่งว่า ถ้าไม่ชำระหนี้ ให้ผู้รับจำนำเข้าเป็นเจ้าของทรัพย์สินจำนำ หรือให้จัดการแก่ทรัพย์สินนั้นเป็นประการอื่นนอกจากตามบทบัญญัติทั้งหลายว่าด้วยการบังคับจำนำนั้นไซร้ ข้อตกลงเช่นนั้นท่านว่าไม่สมบูรณ์"}},{"id":"TH-H004-A757","no":757,"noLabel":{"th":"มาตรา 757"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๕๗ บทบัญญัติทั้งหลายในลักษณะ ๑๓ นี้ ท่านให้ใช้บังคับแก่สัญญาจำนำที่ทำกับผู้ตั้งโรงรับจำนำโดยอนุญาตรัฐบาลแต่เพียงที่ไม่ขัดกับกฎหมายหรือกฎข้อบังคับว่าด้วยโรงจำนำ"}},{"id":"TH-H004-A758","no":758,"noLabel":{"th":"มาตรา 758"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๕๘ ผู้รับจำนำชอบที่จะยึดของจำนำไว้ได้ทั้งหมดจนกว่าจะได้รับชำระหนี้และค่าอุปกรณ์ครบถ้วน"}},{"id":"TH-H004-A759","no":759,"noLabel":{"th":"มาตรา 759"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๕๙ ผู้รับจำนำต้องรักษาทรัพย์สินจำนำไว้ให้ปลอดภัย และต้องสงวนทรัพย์สินจำนำนั้นเช่นอย่างวิญญูชนจะพึงสงวนทรัพย์สินของตนเอง"}},{"id":"TH-H004-A760","no":760,"noLabel":{"th":"มาตรา 760"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๖๐ ถ้าผู้รับจำนำเอาทรัพย์สินซึ่งจำนำออกใช้เอง หรือเอาไปให้บุคคลภายนอกใช้สอย หรือเก็บรักษาโดยผู้จำนำมิได้ยินยอมด้วยไซร้ ท่านว่าผู้รับจำนำจะต้องรับผิดเพื่อที่ทรัพย์สินจำนำนั้นสูญหาย หรือบุบสลายไปอย่างใด ๆ แม้ทั้งเป็นเพราะเหตุสุดวิสัย เว้นแต่จะพิสูจน์ได้ว่าถึงอย่างไร ๆ ก็คงจะต้องสูญหาย หรือบุบสลายอยู่นั่นเอง"}},{"id":"TH-H004-A761","no":761,"noLabel":{"th":"มาตรา 761"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๖๑ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในสัญญาหากมีดอกผลนิตินัยงอกจากทรัพย์สินนั้นอย่างไร ท่านให้ผู้รับจำนำจัดสรรใช้เป็นค่าดอกเบี้ยอันค้างชำระแก่ตน และถ้าไม่มีดอกเบี้ยค้างชำระ ท่านให้จัดสรรใช้ต้นเงินแห่งหนี้อันได้จำนำทรัพย์สินเป็นประกันนั้น"}},{"id":"TH-H004-A762","no":762,"noLabel":{"th":"มาตรา 762"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๖๒ ค่าใช้จ่ายใด ๆ อันควรแก่การบำรุงรักษาทรัพย์สินจำนำนั้น ผู้จำนำจำต้องชดใช้ให้แก่ผู้รับจำนำ เว้นแต่จะได้กำหนดไว้เป็นอย่างอื่นในสัญญา"}},{"id":"TH-H004-A763","no":763,"noLabel":{"th":"มาตรา 763"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๖๓ ท่านห้ามมิให้ฟ้องคดีดังจะกล่าวต่อไปนี้ เมื่อพ้นหกเดือนนับแต่วันส่งคืน หรือขายทอดตลาดทรัพย์สินจำนำ คือ (๑) ฟ้องเรียกค่าสินไหมทดแทนเพื่อความบุบสลายอันผู้รับจำนำก่อให้เกิดแก่ทรัพย์สินจำนำ (๒) ฟ้องเรียกให้ชดใช้ค่าใช้จ่ายเพื่อการบำรุงรักษาทรัพย์สินจำนำ (๓) ฟ้องเรียกค่าสินไหมทดแทนเพื่อความเสียหายอันเกิดแก่ผู้รับจำนำ เพราะความชำรุดบกพร่องในทรัพย์สินจำนำซึ่งไม่เห็นประจักษ์"}},{"id":"TH-H004-A764","no":764,"noLabel":{"th":"มาตรา 764"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๖๔ เมื่อจะบังคับจำนำ ผู้รับจำนำต้องบอกกล่าวเป็นหนังสือไปยังลูกหนี้ก่อนว่า ให้ชำระหนี้และอุปกรณ์ภายในเวลาอันควรซึ่งกำหนดให้ในคำบอกกล่าวนั้น ถ้าลูกหนี้ละเลยไม่ปฏิบัติตามคำบอกกล่าว ผู้รับจำนำชอบที่จะเอาทรัพย์สินซึ่งจำนำออกขายได้ แต่ต้องขายทอดตลาด อนึ่ง ผู้รับจำนำต้องมีจดหมายบอกกล่าวไปยังผู้จำนำบอกเวลาและสถานที่ซึ่งจะขายทอดตลาดด้วย"}},{"id":"TH-H004-A765","no":765,"noLabel":{"th":"มาตรา 765"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๖๕ ถ้าไม่สามารถจะบอกกล่าวก่อนได้ ผู้รับจำนำจะเอาทรัพย์สินจำนำออกขายทอดตลาดเสียในเมื่อหนี้ค้างชำระมาล่วงเวลาเดือนหนึ่งแล้วก็ให้ทำได้"}},{"id":"TH-H004-A766","no":766,"noLabel":{"th":"มาตรา 766"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๖๖ ถ้าจำนำตั๋วเงิน ท่านให้ผู้รับจำนำเก็บเรียกเงินตามตั๋วเงินนั้นในวันถึงกำหนด ไม่จำเป็นต้องบอกกล่าวก่อน"}},{"id":"TH-H004-A767","no":767,"noLabel":{"th":"มาตรา 767"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๖๗ เมื่อบังคับจำนำได้เงินจำนวนสุทธิเท่าใด ท่านว่าผู้รับจำนำต้องจัดสรรชำระหนี้และอุปกรณ์เพื่อให้เสร็จสิ้นไป และถ้ายังมีเงินเหลือก็ต้องส่งคืนให้แก่ผู้จำนำ หรือแก่บุคคลผู้ควรจะได้เงินนั้น ถ้าได้เงินน้อยกว่าจำนวนค้างชำระ ท่านว่าลูกหนี้ก็ยังคงต้องรับใช้ในส่วนที่ขาดอยู่นั้น"}},{"id":"TH-H004-A768","no":768,"noLabel":{"th":"มาตรา 768"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๗๖๘ ถ้าจำนำทรัพย์สินหลายสิ่งเพื่อประกันหนี้แต่รายหนึ่งรายเดียว ท่านว่าผู้รับจำนำจะเลือกเอาทรัพย์สินสิ่งหนึ่งสิ่งใดออกขายก็ได้ แต่จะขายจนเกินกว่าที่จำเป็นเพื่อใช้เงินตามสิทธิแห่งตนนั้นหาได้ไม่"}},{"id":"TH-H004-A769","no":769,"noLabel":{"th":"มาตรา 769"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๗๖๙ อันจำนำย่อมระงับสิ้นไป (๑) เมื่อหนี้ซึ่งจำนำเป็นประกันอยู่นั้นระงับสิ้นไปเพราะเหตุประการอื่นมิใช่เพราะอายุความ หรือ (๒) เมื่อผู้รับจำนำยอมให้ทรัพย์สินจำนำกลับคืนไปสู่ครอบครองของผู้จำนำ"}},{"id":"TH-H004-A770","no":770,"noLabel":{"th":"มาตรา 770"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๗๐ อันว่านายคลังสินค้านั้น คือบุคคลผู้รับทำการเก็บรักษาสินค้าเพื่อบำเหน็จเป็นทางค้าปกติของตน"}},{"id":"TH-H004-A771","no":771,"noLabel":{"th":"มาตรา 771"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๗๑ บทบัญญัติทั้งหลายในประมวลกฎหมายนี้ อันว่าด้วยฝากทรัพย์นั้น ท่านให้นำมาใช้บังคับแก่การเก็บของในคลังสินค้าด้วยเพียงเท่าที่ไม่ขัดกับบทบัญญัติในลักษณะนี้"}},{"id":"TH-H004-A772","no":772,"noLabel":{"th":"มาตรา 772"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๗๒ บทบัญญัติมาตรา ๖๑๖ มาตรา ๖๑๙ มาตรา ๖๒๓ มาตรา ๖๒๕ มาตรา ๖๓๐ มาตรา ๖๓๑ และมาตรา ๖๓๒ อันว่าด้วยการรับขนนั้น ท่านให้นำมาใช้บังคับแก่การเก็บของในคลังสินค้า อนุโลมตามควรแก่บท"}},{"id":"TH-H004-A773","no":773,"noLabel":{"th":"มาตรา 773"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๗๓ นายคลังสินค้าจำต้องยอมให้ผู้ทรงใบรับของคลังสินค้า หรือผู้ทรงประทวนสินค้าตรวจสินค้าและเอาตัวอย่างไปได้ในเวลาอันควรระหว่างเวลาทำงานทุกเมื่อ"}},{"id":"TH-H004-A774","no":774,"noLabel":{"th":"มาตรา 774"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๗๔ นายคลังสินค้าจะเรียกให้ผู้ฝากถอนสินค้าไปก่อนสิ้นระยะเวลาที่ตกลงกันไว้นั้น ท่านว่าหาอาจทำได้ไม่ ถ้าไม่มีกำหนดเวลาส่งคืนสินค้า นายคลังสินค้าจะส่งคืนได้ต่อเมื่อบอกกล่าวให้ผู้ฝากทราบล่วงหน้าเดือนหนึ่ง แต่ท่านมิให้ผู้ฝากต้องถูกบังคับให้ถอนสินค้าไปก่อนเวลาล่วงแล้วสองเดือน นับแต่วันที่ได้ส่งมอบฝากไว้"}},{"id":"TH-H004-A775","no":775,"noLabel":{"th":"มาตรา 775"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๗๕ ถ้าผู้ฝากต้องการไซร้ นายคลังสินค้าต้องส่งมอบเอกสารซึ่งเอาออกจากทะเบียนมีต้นขั้วเฉพาะการอันมีใบรับของคลังสินค้าฉบับหนึ่ง และประทวนสินค้าฉบับหนึ่งให้แก่ผู้ฝาก"}},{"id":"TH-H004-A776","no":776,"noLabel":{"th":"มาตรา 776"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๗๖ อันใบรับของคลังสินค้านั้น ย่อมให้สิทธิแก่ผู้ฝากที่จะสลักหลังโอนกรรมสิทธิ์ในสินค้าไปเป็นของผู้อื่นได้"}},{"id":"TH-H004-A777","no":777,"noLabel":{"th":"มาตรา 777"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๗๗ อันประทวนสินค้านั้น ย่อมให้สิทธิแก่ผู้ฝากที่จะสลักหลังจำนำสินค้าซึ่งจดแจ้งไว้ในประทวนได้โดยไม่ต้องส่งมอบสินค้านั้นแก่ผู้รับสลักหลัง แต่ว่าเมื่อผู้ฝากประสงค์จะจำนำสินค้า ต้องแยกประทวนออกเสียจากใบรับของคลังสินค้า และส่งมอบประทวนนั้นให้แก่ผู้รับสลักหลัง"}},{"id":"TH-H004-A778","no":778,"noLabel":{"th":"มาตรา 778"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๗๘ ใบรับของคลังสินค้าและประทวนสินค้าต้องมีเลขลำดับตรงกันกับเลขในต้นขั้ว และลงลายมือชื่อของนายคลังสินค้า อนึ่ง ใบรับของคลังสินค้าและประทวนสินค้านั้น ท่านให้มีรายละเอียดดังกล่าวต่อไปนี้ คือ (๑) ชื่อหรือยี่ห้อ และสำนักของผู้ฝาก (๒) ที่ตั้งคลังสินค้า (๓) ค่าบำเหน็จสำหรับเก็บรักษา (๔) สภาพของสินค้าที่เก็บรักษา และน้ำหนักหรือขนาดแห่งสินค้านั้น กับทั้งสภาพ จำนวน และเครื่องหมายหีบห่อ (๕) สถานที่และวันออกใบรับของคลังสินค้าและประทวนสินค้านั้น (๖) ถ้าได้กำหนดกันไว้ว่าให้เก็บสินค้าไว้ชั่วเวลาเท่าใดให้แจ้งกำหนดนั้นด้วย (๗) ถ้าของที่เก็บรักษามีประกันภัย ให้แสดงจำนวนเงินที่ประกันภัยกำหนดเวลาที่ประกันภัย และชื่อหรือยี่ห้อของผู้รับประกันภัยด้วย อนึ่ง นายคลังสินค้าต้องจดรายละเอียดทั้งนี้ลงไว้ในต้นขั้วด้วย"}},{"id":"TH-H004-A779","no":779,"noLabel":{"th":"มาตรา 779"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๗๙ อันใบรับของคลังสินค้าก็ดี ประทวนสินค้าก็ดี ท่านว่าหาอาจออกให้หรือสลักหลังให้แก่ผู้ถือได้ไม่"}},{"id":"TH-H004-A780","no":780,"noLabel":{"th":"มาตรา 780"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๐ เมื่อใดผู้ฝากสลักหลังประทวนสินค้าให้แก่ผู้รับจำนำ คู่สัญญาต้องจดแจ้งการที่สลักหลังนั้นลงไว้ในใบรับของคลังสินค้าด้วย ถ้ามิได้จดแจ้งไว้ดังนั้น ท่านว่าการจำนำนั้นหาอาจยกขึ้นเป็นข้อต่อสู้ผู้ซื้อสินค้าสืบไปนั้นได้ไม่"}},{"id":"TH-H004-A781","no":781,"noLabel":{"th":"มาตรา 781"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๑ เมื่อประทวนสินค้าได้สลักหลังและส่งมอบแก่ผู้รับจำนำแล้ว ให้ผู้ฝากกับผู้รับจำนำจดลงไว้ในประทวนสินค้าเป็นสำคัญ ว่าได้จดข้อความตามที่บัญญัติในมาตราก่อนไว้ในใบรับของคลังสินค้าแล้ว"}},{"id":"TH-H004-A782","no":782,"noLabel":{"th":"มาตรา 782"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๒ เมื่อใดผู้ฝากจำนำสินค้าและส่งมอบประทวนสินค้าแก่ผู้รับสลักหลังแล้ว ผู้รับสลักหลังเช่นนั้นต้องมีจดหมายบอกกล่าวแก่นายคลังสินค้าให้ทราบจำนวนหนี้ซึ่งจำนำสินค้านั้นเป็นประกัน ทั้งจำนวนดอกเบี้ยและวันอันหนี้นั้นจะถึงกำหนดชำระ เมื่อนายคลังสินค้าได้รับคำบอกกล่าวเช่นนั้นแล้วต้องจดรายการทั้งนั้นลงในต้นขั้ว ถ้าและมิได้จดในต้นขั้วเช่นนั้น ท่านว่าการจำนำนั้นหาอาจจะยกขึ้นเป็นข้อต่อสู้เจ้าหนี้ทั้งหลายของผู้ฝากได้ไม่"}},{"id":"TH-H004-A783","no":783,"noLabel":{"th":"มาตรา 783"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๓ ผู้ทรงเอกสารอันมีทั้งใบรับของคลังสินค้าและประทวนสินค้านั้น จะให้นายคลังสินค้าแยกสินค้าที่เก็บรักษาไว้ออกเป็นหลายส่วนและให้ส่งมอบเอกสารแก่ตนส่วนละใบก็ได้ ในกรณีเช่นนี้ผู้ทรงเอกสารต้องคืนเอกสารเดิมแก่นายคลังสินค้า อนึ่ง ค่าใช้จ่ายในการแยกสินค้าและการส่งมอบเอกสารใหม่นั้น ผู้ทรงเอกสารต้องรับใช้"}},{"id":"TH-H004-A784","no":784,"noLabel":{"th":"มาตรา 784"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๔ กรรมสิทธิ์ในสินค้าที่เก็บรักษาไว้นั้น ท่านว่าอาจโอนได้แต่ด้วยสลักหลังใบรับของคลังสินค้าเท่านั้น"}},{"id":"TH-H004-A785","no":785,"noLabel":{"th":"มาตรา 785"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๕ สินค้าซึ่งเก็บรักษาไว้นั้นอาจจำนำได้แต่ด้วยสลักหลังประทวนสินค้า เมื่อประทวนสินค้าได้สลักหลังแล้ว สินค้านั้นจะจำนำแก่ผู้อื่นอีกชั้นหนึ่งด้วยสลักหลังใบรับของคลังสินค้าอย่างเดียวกับสลักหลังประทวนสินค้านั้นก็ได้"}},{"id":"TH-H004-A786","no":786,"noLabel":{"th":"มาตรา 786"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๖ ตราบใดสินค้าที่เก็บรักษาไว้ไม่ได้จำนำ ท่านว่าจะโอนใบรับของคลังสินค้าและประทวนสินค้าไปต่างหากจากกันไม่ได้อยู่ตราบนั้น"}},{"id":"TH-H004-A787","no":787,"noLabel":{"th":"มาตรา 787"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๗ ในการสลักหลังลงในประทวนสินค้าครั้งแรกนั้น ต้องจดแจ้งจำนวนหนี้ที่จำนำสินค้าเป็นประกันทั้งจำนวนดอกเบี้ยที่จะต้องชำระและวันที่หนี้จะถึงกำหนดชำระด้วย"}},{"id":"TH-H004-A788","no":788,"noLabel":{"th":"มาตรา 788"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๘ อันสินค้าที่เก็บรักษาไว้ในคลังสินค้านั้น จะรับเอาไปได้แต่เมื่อเวนคืนใบรับของคลังสินค้า"}},{"id":"TH-H004-A789","no":789,"noLabel":{"th":"มาตรา 789"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๘๙ ถ้าได้แยกประทวนสินค้าออกสลักหลังจำนำแล้ว จะรับเอาสินค้าได้แต่เมื่อเวนคืนทั้งใบรับของคลังสินค้าและประทวนสินค้า แต่ว่าผู้ทรงใบรับของคลังสินค้าอาจให้คืนสินค้าแก่ตนได้ในเวลาใด ๆ เมื่อวางเงินแก่นายคลังสินค้าเต็มจำนวนหนี้ซึ่งลงไว้ในประทวนสินค้า กับทั้งดอกเบี้ยจนถึงวันกำหนดชำระหนี้นั้นด้วย อนึ่ง จำนวนเงินที่วางเช่นนี้นายคลังสินค้าต้องชำระแก่ผู้ทรงประทวนสินค้าในเมื่อเขาเวนคืนประทวนนั้น"}},{"id":"TH-H004-A790","no":790,"noLabel":{"th":"มาตรา 790"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๐ ถ้าหนี้ซึ่งสินค้าจำนำเป็นประกันมิได้ชำระเมื่อวันถึงกำหนดไซร้ ผู้ทรงประทวนสินค้าเมื่อได้ยื่นคำคัดค้านตามระเบียบแล้ว ชอบที่จะให้นายคลังสินค้าขายทอดตลาดสินค้านั้นได้ แต่ท่านห้ามมิให้ขายทอดตลาดก่อนแปดวันนับแต่วันคัดค้าน"}},{"id":"TH-H004-A791","no":791,"noLabel":{"th":"มาตรา 791"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๑ ผู้ทรงประทวนสินค้าต้องมีจดหมายบอกกล่าวให้ผู้ฝากทราบเวลาและสถานที่จะขายทอดตลาด"}},{"id":"TH-H004-A792","no":792,"noLabel":{"th":"มาตรา 792"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๒ นายคลังสินค้าต้องหักเงินที่ค้างชำระแก่ตนเนื่องด้วยการเก็บรักษาสินค้านั้นจากจำนวนเงินสุทธิที่ขายทอดตลาดได้ และเมื่อผู้ทรงประทวนสินค้านำประทวนมาเวนคืน ต้องเอาเงินที่เหลือนั้นให้ตามจำนวนที่ค้างชำระแก่เขา ถ้ามีเงินเหลือเท่าใด ต้องใช้แก่ผู้รับจำนำคนหลังเมื่อเขาเวนคืนใบรับของคลังสินค้า หรือถ้าไม่มีผู้รับจำนำคนหลังหรือผู้รับจำนำคนหลังได้รับชำระหนี้แล้ว ก็ให้ชำระเงินที่เหลืออยู่นั้นแก่ผู้ทรงใบรับของคลังสินค้า"}},{"id":"TH-H004-A793","no":793,"noLabel":{"th":"มาตรา 793"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๓ ถ้าจำนวนเงินสุทธิที่ขายทอดตลาดได้ไม่พอชำระหนี้แก่ผู้ทรงประทวนสินค้าไซร้ นายคลังสินค้าต้องคืนประทวนสินค้าแก่เขา กับจดบอกจำนวนเงินที่ได้ชำระลงไว้ในประทวนสินค้านั้นแล้วจดลงไว้ในสมุดบัญชีของตนด้วย"}},{"id":"TH-H004-A794","no":794,"noLabel":{"th":"มาตรา 794"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๔ ผู้ทรงประทวนสินค้ามีสิทธิจะไล่เบี้ยเอาจำนวนเงินที่ยังค้างชำระนั้นแก่ผู้สลักหลังคนก่อน ๆ ทั้งหมดหรือแต่คนใดคนหนึ่งได้ แต่ต้องได้ขายทอดตลาดภายในเดือนหนึ่งนับแต่วันคัดค้าน อนึ่ง ท่านห้ามมิให้ฟ้องไล่เบี้ยเมื่อพ้นเวลาปีหนึ่งนับแต่วันขายทอดตลาด"}},{"id":"TH-H004-A795","no":795,"noLabel":{"th":"มาตรา 795"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๕ บทบัญญัติทั้งหลายในประมวลกฎหมายนี้อันว่าด้วยตั๋วเงินนั้น ท่านให้ใช้ได้ถึงประทวนสินค้าและใบรับของคลังสินค้าซึ่งได้สลักหลังอย่างประทวนสินค้านั้นด้วยเพียงที่ไม่ขัดกับบทบัญญัติทั้งหลายในลักษณะนี้"}},{"id":"TH-H004-A796","no":796,"noLabel":{"th":"มาตรา 796"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๗๙๖ ถ้าเอกสารมีทั้งใบรับของคลังสินค้าและประทวนสินค้าหรือแต่อย่างหนึ่งอย่างใดสูญหายไป เมื่อผู้ทรงเอกสารนั้น ๆ ให้ประกันตามสมควรแล้ว จะให้นายคลังสินค้าออกให้ใหม่ก็ได้ ในกรณีเช่นนี้นายคลังสินค้าต้องจดหมายลงไว้ในต้นขั้วเป็นสำคัญ"}},{"id":"TH-H004-A797","no":797,"noLabel":{"th":"มาตรา 797"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๙๗ อันว่าสัญญาตัวแทนนั้น คือสัญญาซึ่งให้บุคคลหนึ่ง เรียกว่าตัวแทน มีอำนาจทำการแทนบุคคลอีกคนหนึ่ง เรียกว่าตัวการ และตกลงจะทำการดังนั้น อันความเป็นตัวแทนนั้นจะเป็นโดยตั้งแต่งแสดงออกชัดหรือโดยปริยายก็ย่อมได้"}},{"id":"TH-H004-A798","no":798,"noLabel":{"th":"มาตรา 798"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๙๘ กิจการอันใดท่านบังคับไว้โดยกฎหมายว่าต้องทำเป็นหนังสือ การตั้งตัวแทนเพื่อกิจการอันนั้นก็ต้องทำเป็นหนังสือด้วย กิจการอันใดท่านบังคับไว้ว่าต้องมีหลักฐานเป็นหนังสือ การตั้งตัวแทนเพื่อกิจการอันนั้นก็ต้องมีหลักฐานเป็นหนังสือด้วย"}},{"id":"TH-H004-A799","no":799,"noLabel":{"th":"มาตรา 799"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๗๙๙ ตัวการคนใดใช้บุคคลผู้ไร้ความสามารถเป็นตัวแทน ท่านว่าตัวการคนนั้นย่อมต้องผูกพันในกิจการที่ตัวแทนกระทำ"}},{"id":"TH-H004-A800","no":800,"noLabel":{"th":"มาตรา 800"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๐ ถ้าตัวแทนได้รับมอบอำนาจแต่เฉพาะการ ท่านว่าจะทำการแทนตัวการได้แต่เพียงในสิ่งที่จำเป็นเพื่อให้กิจอันเขาได้มอบหมายแก่ตนนั้นสำเร็จลุล่วงไป"}},{"id":"TH-H004-A801","no":801,"noLabel":{"th":"มาตรา 801"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๑ ถ้าตัวแทนได้รับมอบอำนาจทั่วไป ท่านว่าจะทำกิจใด ๆ ในทางจัดการแทนตัวการก็ย่อมทำได้ทุกอย่าง แต่การเช่นอย่างจะกล่าวต่อไปนี้ ท่านว่าหาอาจจะทำได้ไม่ คือ (๑) ขายหรือจำนองอสังหาริมทรัพย์ (๒) ให้เช่าอสังหาริมทรัพย์กว่าสามปีขึ้นไป (๓) ให้ (๔) ประนีประนอมยอมความ (๕) ยื่นฟ้องต่อศาล (๖) มอบข้อพิพาทให้อนุญาโตตุลาการพิจารณา"}},{"id":"TH-H004-A802","no":802,"noLabel":{"th":"มาตรา 802"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๒ ในเหตุฉุกเฉิน เพื่อจะป้องกันมิให้ตัวการต้องเสียหาย ท่านให้สันนิษฐานไว้ก่อนว่าตัวแทนจะทำการใด ๆ เช่นอย่างวิญญูชนจะพึงกระทำ ก็ย่อมมีอำนาจจะทำได้ทั้งสิ้น"}},{"id":"TH-H004-A803","no":803,"noLabel":{"th":"มาตรา 803"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๓ ตัวแทนไม่มีสิทธิจะได้รับบำเหน็จ เว้นแต่จะได้มีข้อตกลงกันไว้ในสัญญาว่ามีบำเหน็จ หรือทางการที่คู่สัญญาประพฤติต่อกันนั้นเป็นปริยายว่ามีบำเหน็จ หรือเคยเป็นธรรมเนียมมีบำเหน็จ"}},{"id":"TH-H004-A804","no":804,"noLabel":{"th":"มาตรา 804"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๔ ถ้าในสัญญาอันเดียวตัวการคนเดียวตั้งตัวแทนหลายคนเพื่อแก่การอันเดียวกันไซร้ ท่านให้สันนิษฐานไว้ก่อนว่าตัวแทนจะต่างคนต่างทำการนั้น ๆ แยกกันไม่ได้"}},{"id":"TH-H004-A805","no":805,"noLabel":{"th":"มาตรา 805"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๕ ตัวแทนนั้น เมื่อไม่ได้รับความยินยอมของตัวการ จะเข้าทำนิติกรรมอันใดในนามของตัวการทำกับตนเองในนามของตนเองหรือในฐานเป็นตัวแทนของบุคคลภายนอกหาได้ไม่ เว้นแต่นิติกรรมนั้นมีเฉพาะแต่การชำระหนี้"}},{"id":"TH-H004-A806","no":806,"noLabel":{"th":"มาตรา 806"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๐๖ ตัวการซึ่งมิได้เปิดเผยชื่อจะกลับแสดงตนให้ปรากฏและเข้ารับเอาสัญญาใด ๆ ซึ่งตัวแทนได้ทำไว้แทนตนก็ได้ แต่ถ้าตัวการผู้ใดได้ยอมให้ตัวแทนของตนทำการออกหน้าเป็นตัวการไซร้ ท่านว่าตัวการผู้นั้นหาอาจจะทำให้เสื่อมเสียถึงสิทธิของบุคคลภายนอกอันเขามีต่อตัวแทน และเขาขวนขวายได้มาแต่ก่อนที่รู้ว่าเป็นตัวแทนนั้นได้ไม่"}},{"id":"TH-H004-A807","no":807,"noLabel":{"th":"มาตรา 807"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๐๗ ตัวแทนต้องทำการตามคำสั่งแสดงออกชัดหรือโดยปริยายของตัวการ เมื่อไม่มีคำสั่งเช่นนั้น ก็ต้องดำเนินตามทางที่เคยทำกันมาในกิจการค้าขายอันเขาให้ตนทำอยู่นั้น อนึ่ง บทบัญญัติมาตรา ๖๕๙ ว่าด้วยการฝากทรัพย์นั้น ท่านให้นำมาใช้ด้วยโดยอนุโลมตามควร"}},{"id":"TH-H004-A808","no":808,"noLabel":{"th":"มาตรา 808"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๐๘ ตัวแทนต้องทำการด้วยตนเอง เว้นแต่จะมีอำนาจใช้ตัวแทนช่วงทำการได้"}},{"id":"TH-H004-A809","no":809,"noLabel":{"th":"มาตรา 809"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๐๙ เมื่อตัวการมีประสงค์จะทราบความเป็นไปของการที่ได้มอบหมายแก่ตัวแทนนั้นในเวลาใด ๆ ซึ่งสมควรแก่เหตุ ตัวแทนก็ต้องแจ้งให้ตัวการทราบ อนึ่ง เมื่อการเป็นตัวแทนสิ้นสุดลงแล้ว ตัวแทนต้องแถลงบัญชีด้วย"}},{"id":"TH-H004-A810","no":810,"noLabel":{"th":"มาตรา 810"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๑๐ เงินและทรัพย์สินอย่างอื่นบรรดาที่ตัวแทนได้รับไว้เกี่ยวด้วยการเป็นตัวแทนนั้น ท่านว่าตัวแทนต้องส่งให้แก่ตัวการจงสิ้น อนึ่ง สิทธิทั้งหลายซึ่งตัวแทนขวนขวายได้มาในนามของตนเองแต่โดยฐานที่ทำการแทนตัวการนั้น ตัวแทนก็ต้องโอนให้แก่ตัวการจงสิ้น"}},{"id":"TH-H004-A811","no":811,"noLabel":{"th":"มาตรา 811"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๑๑ ถ้าตัวแทนเอาเงินซึ่งควรจะได้ส่งแก่ตัวการหรือซึ่งควรจะใช้ในกิจของตัวการนั้นไปใช้สอยเป็นประโยชน์ตนเสีย ท่านว่าตัวแทนต้องเสียดอกเบี้ยในเงินนั้นนับแต่วันที่ได้เอาไปใช้"}},{"id":"TH-H004-A812","no":812,"noLabel":{"th":"มาตรา 812"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๑๒ ถ้ามีความเสียหายเกิดขึ้นอย่างใด ๆ เพราะความประมาทเลินเล่อของตัวแทนก็ดี เพราะไม่ทำการเป็นตัวแทนก็ดี หรือเพราะทำการโดยปราศจากอำนาจหรือนอกเหนืออำนาจก็ดี ท่านว่าตัวแทนจะต้องรับผิด"}},{"id":"TH-H004-A813","no":813,"noLabel":{"th":"มาตรา 813"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๑๓ ตัวแทนผู้ใดตั้งตัวแทนช่วงตามที่ตัวการระบุตัวให้ตั้ง ท่านว่าตัวแทนผู้นั้นจะต้องรับผิดแต่เพียงในกรณีที่ตนได้รู้ว่าตัวแทนช่วงนั้นเป็นผู้ที่ไม่เหมาะแก่การ หรือเป็นผู้ที่ไม่สมควรไว้วางใจแล้วและมิได้แจ้งความนั้นให้ตัวการทราบหรือมิได้เลิกถอนตัวแทนช่วงนั้นเสียเอง"}},{"id":"TH-H004-A814","no":814,"noLabel":{"th":"มาตรา 814"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๘๑๔ ตัวแทนช่วงย่อมรับผิดโดยตรงต่อตัวการ ฉันใดกลับกันก็ฉันนั้น"}},{"id":"TH-H004-A815","no":815,"noLabel":{"th":"มาตรา 815"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๑๕ ถ้าตัวแทนมีประสงค์ไซร้ ตัวการต้องจ่ายเงินทดรองให้แก่ตัวแทนตามจำนวนที่จำเป็น เพื่อทำการอันมอบหมายแก่ตัวแทนนั้น"}},{"id":"TH-H004-A816","no":816,"noLabel":{"th":"มาตรา 816"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๑๖ ถ้าในการจัดทำกิจการอันเขามอบหมายแก่ตนนั้น ตัวแทนได้ออกเงินทดรองหรือออกเงินค่าใช้จ่ายไป ซึ่งพิเคราะห์ตามเหตุควรนับว่าเป็นการจำเป็นได้ไซร้ ท่านว่าตัวแทนจะเรียกเอาเงินชดใช้จากตัวการ รวมทั้งดอกเบี้ยนับแต่วันที่ได้ออกเงินไปนั้นด้วยก็ได้ ถ้าในการจัดทำกิจการอันเขามอบหมายแก่ตนนั้น ตัวแทนต้องรับภาระเป็นหนี้ขึ้นอย่างหนึ่งอย่างใด ซึ่งพิเคราะห์ตามเหตุควรนับว่าเป็นการจำเป็นได้ไซร้ ท่านว่าตัวแทนจะเรียกให้ตัวการชำระหนี้แทนตนก็ได้ หรือถ้ายังไม่ถึงเวลากำหนดชำระหนี้ จะให้ตัวการให้ประกันอันสมควรก็ได้ ถ้าในการจัดทำกิจการอันเขามอบหมายแก่ตนนั้น เป็นเหตุให้ตัวแทนต้องเสียหายอย่างหนึ่งอย่างใด มิใช่เป็นเพราะความผิดของตนเองไซร้ ท่านว่าตัวแทนจะเรียกเอาค่าสินไหมทดแทนจากตัวการก็ได้"}},{"id":"TH-H004-A817","no":817,"noLabel":{"th":"มาตรา 817"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๑๗ ในกรณีที่มีบำเหน็จตัวแทนถ้าไม่มีข้อสัญญาตกลงกันไว้เป็นอย่างอื่น ท่านว่าบำเหน็จนั้นพึงจ่ายให้ต่อเมื่อการเป็นตัวแทนได้สุดสิ้นลงแล้ว"}},{"id":"TH-H004-A818","no":818,"noLabel":{"th":"มาตรา 818"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๑๘ การในหน้าที่ตัวแทนส่วนใดตัวแทนได้ทำมิชอบในส่วนนั้น ท่านว่าตัวแทนไม่มีสิทธิจะได้บำเหน็จ"}},{"id":"TH-H004-A819","no":819,"noLabel":{"th":"มาตรา 819"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๑๙ ตัวแทนชอบที่จะยึดหน่วงทรัพย์สินของใด ๆ ของตัวการอันตกอยู่ในความครอบครองของตนเพราะเป็นตัวแทนนั้นเอาไว้ได้ จนกว่าจะได้รับเงินบรรดาค้างชำระแก่ตนเพราะการเป็นตัวแทน"}},{"id":"TH-H004-A820","no":820,"noLabel":{"th":"มาตรา 820"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๐ ตัวการย่อมมีความผูกพันต่อบุคคลภายนอกในกิจการทั้งหลายอันตัวแทนหรือตัวแทนช่วงได้ทำไปภายในขอบอำนาจแห่งฐานตัวแทน"}},{"id":"TH-H004-A821","no":821,"noLabel":{"th":"มาตรา 821"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๑ บุคคลผู้ใดเชิดบุคคลอีกคนหนึ่งออกแสดงเป็นตัวแทนของตนก็ดี รู้แล้วยอมให้บุคคลอีกคนหนึ่งเชิดตัวเขาเองออกแสดงเป็นตัวแทนของตนก็ดี ท่านว่าบุคคลผู้นั้นจะต้องรับผิดต่อบุคคลภายนอกผู้สุจริตเสมือนว่าบุคคลอีกคนหนึ่งนั้นเป็นตัวแทนของตน"}},{"id":"TH-H004-A822","no":822,"noLabel":{"th":"มาตรา 822"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๒ ถ้าตัวแทนทำการอันใดเกินอำนาจตัวแทน แต่ทางปฏิบัติของตัวการทำให้บุคคลภายนอกมีมูลเหตุอันสมควรจะเชื่อว่าการอันนั้นอยู่ภายในขอบอำนาจของตัวแทนไซร้ ท่านให้ใช้บทบัญญัติมาตราก่อนนี้เป็นบทบังคับ แล้วแต่กรณี"}},{"id":"TH-H004-A823","no":823,"noLabel":{"th":"มาตรา 823"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๓ ถ้าตัวแทนกระทำการอันใดอันหนึ่งโดยปราศจากอำนาจก็ดี หรือทำนอกทำเหนือขอบอำนาจก็ดี ท่านว่าย่อมไม่ผูกพันตัวการ เว้นแต่ตัวการจะให้สัตยาบันแก่การนั้น ถ้าตัวการไม่ให้สัตยาบัน ท่านว่าตัวแทนย่อมต้องรับผิดต่อบุคคลภายนอกโดยลำพังตนเอง เว้นแต่จะพิสูจน์ได้ว่าบุคคลภายนอกนั้นได้รู้อยู่ว่าตนทำการโดยปราศจากอำนาจหรือทำนอกเหนือขอบอำนาจ"}},{"id":"TH-H004-A824","no":824,"noLabel":{"th":"มาตรา 824"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๔ ตัวแทนคนใดทำสัญญาแทนตัวการซึ่งอยู่ต่างประเทศและมีภูมิลำเนาในต่างประเทศ ท่านว่าตัวแทนคนนั้นจะต้องรับผิดตามสัญญานั้นแต่ลำพังตนเอง แม้ทั้งชื่อและตัวการจะได้เปิดเผยแล้ว เว้นแต่ข้อความแห่งสัญญาจะแย้งกันกับความรับผิดของตัวแทน"}},{"id":"TH-H004-A825","no":825,"noLabel":{"th":"มาตรา 825"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๘๒๕ ถ้าตัวแทนเข้าทำสัญญากับบุคคลภายนอกโดยเห็นแก่อามิสสินจ้างเป็นทรัพย์สินอย่างใด ๆ หรือประโยชน์อย่างอื่นอันบุคคลภายนอกได้ให้เป็นลาภส่วนตัวก็ดี หรือให้คำมั่นว่าจะให้ก็ดี ท่านว่าตัวการหาต้องผูกพันในสัญญาซึ่งตัวแทนของตนได้ทำนั้นไม่ เว้นแต่ตัวการจะได้ยินยอมด้วย"}},{"id":"TH-H004-A826","no":826,"noLabel":{"th":"มาตรา 826"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๒๖ อันสัญญาตัวแทนย่อมระงับสิ้นไปด้วยตัวการถอนตัวแทน หรือด้วยตัวแทนบอกเลิกเป็นตัวแทน อนึ่ง สัญญาตัวแทนย่อมระงับสิ้นไป เมื่อคู่สัญญาฝ่ายใดฝ่ายหนึ่งตาย หรือตกเป็นผู้ไร้ความสามารถ หรือล้มละลาย เว้นแต่จะปรากฏว่าขัดกับข้อสัญญาหรือสภาพแห่งกิจการนั้น"}},{"id":"TH-H004-A827","no":827,"noLabel":{"th":"มาตรา 827"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๒๗ ตัวการจะถอนตัวแทน และตัวแทนจะบอกเลิกเป็นตัวแทนเสียในเวลาใด ๆ ก็ได้ทุกเมื่อ คู่สัญญาฝ่ายซึ่งถอนตัวแทนหรือบอกเลิกเป็นตัวแทนในเวลาที่ไม่สะดวกแก่อีกฝ่ายหนึ่ง จะต้องรับผิดต่อคู่สัญญาฝ่ายนั้นในความเสียหายอย่างใด ๆ อันเกิดแต่การนั้น เว้นแต่ในกรณีที่เป็นความจำเป็นอันมิอาจจะก้าวล่วงเสียได้"}},{"id":"TH-H004-A828","no":828,"noLabel":{"th":"มาตรา 828"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๒๘ เมื่อสัญญาตัวแทนระงับสิ้นไปเพราะตัวการตายก็ดี ตัวการตกเป็นผู้ไร้ความสามารถหรือล้มละลายก็ดี ท่านว่าตัวแทนต้องจัดการอันสมควรทุกอย่างเพื่อจะปกปักรักษาประโยชน์อันเขาได้มอบหมายแก่ตนไป จนกว่าทายาทหรือผู้แทนของตัวการจะอาจเข้าปกปักรักษาประโยชน์นั้น ๆ ได้"}},{"id":"TH-H004-A829","no":829,"noLabel":{"th":"มาตรา 829"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๒๙ เมื่อสัญญาตัวแทนระงับสิ้นไปเพราะตัวแทนตายก็ดี ตัวแทนตกเป็นผู้ไร้ความสามารถหรือล้มละลายก็ดี ท่านว่าทายาทหรือบุคคลผู้รับหน้าที่ดูแลทรัพย์มรดกของตัวแทนโดยชอบด้วยกฎหมายต้องบอกกล่าวแก่ตัวการและจัดการเพื่อปกปักรักษาประโยชน์ของตัวการไปตามสมควรแก่พฤติการณ์ จนกว่าตัวการอาจเข้าปกปักรักษาประโยชน์นั้น ๆ ได้"}},{"id":"TH-H004-A830","no":830,"noLabel":{"th":"มาตรา 830"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๓๐ อันเหตุที่ทำให้สัญญาตัวแทนระงับสิ้นไปนั้นจะเกิดแต่ตัวการหรือตัวแทนก็ตาม ท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้คู่สัญญาอีกฝ่ายหนึ่ง จนกว่าจะได้บอกกล่าวเหตุนั้น ๆ ไปยังคู่สัญญาฝ่ายนั้นแล้ว หรือจนกว่าคู่สัญญาฝ่ายนั้นจะได้ทราบเหตุแล้ว"}},{"id":"TH-H004-A831","no":831,"noLabel":{"th":"มาตรา 831"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๓๑ อันความระงับสิ้นไปแห่งสัญญาตัวแทนนั้น ท่านห้ามมิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้ทำการโดยสุจริต เว้นแต่บุคคลภายนอกหากไม่ทราบความนั้นเพราะความประมาทเลินเล่อของตนเอง"}},{"id":"TH-H004-A832","no":832,"noLabel":{"th":"มาตรา 832"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๘๓๒ ในเมื่อสัญญาตัวแทนระงับสิ้นไป ตัวการชอบที่จะเรียกให้เวนคืนหนังสือมอบอำนาจอย่างใด ๆ อันได้ให้ไว้แก่ตัวแทนนั้นได้"}},{"id":"TH-H004-A833","no":833,"noLabel":{"th":"มาตรา 833"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๓ อันว่าตัวแทนค้าต่าง คือบุคคลซึ่งในทางค้าขายของเขาย่อมทำการซื้อ หรือขายทรัพย์สิน หรือรับจัดทำกิจการค้าขายอย่างอื่นในนามของตนเองต่างตัวการ"}},{"id":"TH-H004-A834","no":834,"noLabel":{"th":"มาตรา 834"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๔ ถ้ามิได้ตกลงกันไว้เป็นอย่างอื่น ท่านว่าตัวแทนค้าต่างชอบที่จะได้รับบำเหน็จโดยอัตราตามธรรมเนียมเพื่อกิจการอันขายอันตนได้จัดการให้ตกลงไปนั้นทุกรายไป"}},{"id":"TH-H004-A835","no":835,"noLabel":{"th":"มาตรา 835"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๕ บทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้อันว่าด้วยตัวแทนนั้น ท่านให้ใช้บังคับถึงตัวแทนค้าต่างด้วยเพียงที่ไม่ขัดกับบทบัญญัติในหมวดนี้"}},{"id":"TH-H004-A836","no":836,"noLabel":{"th":"มาตรา 836"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๖ บุคคลผู้ไร้ความสามารถหาอาจจะทำการเป็นตัวแทนค้าต่างได้ไม่ เว้นแต่จะได้รับอำนาจโดยชอบให้ทำได้"}},{"id":"TH-H004-A837","no":837,"noLabel":{"th":"มาตรา 837"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๗ ในการที่ตัวแทนค้าต่างทำการขายหรือซื้อหรือจัดทำกิจการค้าขายอย่างอื่นต่างตัวการนั้น ท่านว่าตัวแทนค้าต่างย่อมได้ซึ่งสิทธิอันมีต่อคู่สัญญาอีกฝ่ายหนึ่งในกิจการเช่นนั้น และตัวแทนค้าต่างย่อมเป็นผู้ต้องผูกพันต่อคู่สัญญาฝ่ายนั้นด้วย"}},{"id":"TH-H004-A838","no":838,"noLabel":{"th":"มาตรา 838"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๘ ถ้าคู่สัญญาอีกฝ่ายหนึ่งไม่ชำระหนี้ไซร้ ท่านว่าตัวแทนค้าต่างหาต้องรับผิดต่อตัวการเพื่อชำระหนี้นั้นเองไม่ เว้นแต่จะได้มีข้อกำหนดในสัญญาหรือมีปริยายแต่ทางการที่ตัวการกับตัวแทนประพฤติต่อกัน หรือมีธรรมเนียมในท้องถิ่นว่าจะต้องรับผิดถึงเพียงนั้น อนึ่ง ตัวแทนค้าต่างคนใดเข้ารับประกันการปฏิบัติตามสัญญาโดยนัยดังกล่าวมาในวรรคก่อนนั้นไซร้ ท่านว่าตัวแทนคนนั้นชื่อว่าเป็นตัวแทนฐานประกัน ชอบที่จะได้รับบำเหน็จพิเศษ"}},{"id":"TH-H004-A839","no":839,"noLabel":{"th":"มาตรา 839"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๓๙ ถ้าตัวแทนค้าต่างได้ทำการขายเป็นราคาต่ำไปกว่าที่ตัวการกำหนด หรือทำการซื้อเป็นราคาสูงไปกว่าที่ตัวการกำหนดไซร้ หากว่าตัวแทนรับใช้เศษที่ขาดเกินนั้นแล้ว ท่านว่าการขายหรือการซื้ออันนั้นตัวการก็ต้องรับขายรับซื้อ"}},{"id":"TH-H004-A840","no":840,"noLabel":{"th":"มาตรา 840"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๔๐ ถ้าตัวแทนค้าต่างได้ทำการขายได้ราคาสูงกว่าที่ตัวการกำหนด หรือทำการซื้อได้ราคาต่ำกว่าที่ตัวการกำหนดไซร้ ท่านว่าตัวแทนหาอาจจะถือเอาเป็นประโยชน์ของตนได้ไม่ ต้องคิดให้แก่ตัวการ"}},{"id":"TH-H004-A841","no":841,"noLabel":{"th":"มาตรา 841"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๔๑ ตัวแทนค้าต่างทำการไปอย่างไรบ้าง ท่านให้แถลงรายงานแก่ตัวการ และเมื่อได้ทำการค้าต่างเสร็จลงแล้ว ก็ให้แจ้งแก่ตัวการทราบมิให้ชักช้า"}},{"id":"TH-H004-A842","no":842,"noLabel":{"th":"มาตรา 842"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๔๒ เมื่อใดเขามอบหมายทรัพย์สินไว้แก่ตัวแทนค้าต่าง ท่านให้นำบทบัญญัติทั้งหลายแห่งประมวลกฎหมายนี้ ลักษณะฝากทรัพย์มาใช้บังคับ อนุโลมตามควร อนึ่ง ในกรณีที่เป็นความจำเป็นอันมิก้าวล่วงเสียได้ ท่านว่าตัวแทนค้าต่างจะจัดการแก่ทรัพย์สินนั้นตามวิธีการดังบัญญัติไว้ในมาตรา ๖๓๑ ว่าด้วยรับขนนั้นก็ได้"}},{"id":"TH-H004-A843","no":843,"noLabel":{"th":"มาตรา 843"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๔๓ ตัวแทนค้าต่างคนใดได้รับคำสั่งให้ขายหรือซื้อทรัพย์สินอันมีรายการขานราคาของสถานแลกเปลี่ยน ท่านว่าตัวแทนคนนั้นจะเป็นผู้ซื้อหรือผู้ขายเองก็ได้ เว้นแต่จะมีข้อห้ามไว้ชัดแจ้งโดยสัญญา ในกรณีเช่นนั้น ราคาอันจะพึงใช้เงินแก่กันก็พึงกำหนดตามรายการขานราคาทรัพย์สินนั้น ณ สถานแลกเปลี่ยนในเวลาเมื่อตัวแทนค้าต่างให้คำบอกกล่าวว่าตนจะเป็นผู้ซื้อหรือผู้ขาย เมื่อตัวการรับคำบอกกล่าวเช่นนั้น ถ้าไม่บอกปัดเสียในทันที ท่านให้ถือว่าตัวการเป็นอันได้สนองรับการนั้นแล้ว อนึ่ง แม้ในกรณีเช่นนั้น ตัวแทนค้าต่างจะคิดเอาบำเหน็จก็ย่อมคิดได้"}},{"id":"TH-H004-A844","no":844,"noLabel":{"th":"มาตรา 844"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๘๔๔ ในระหว่างตัวการกับตัวแทนค้าต่าง ท่านให้ถือว่ากิจการอันตัวแทนได้ทำให้ตกลงไปนั้น ย่อมมีผลเสมือนดังว่าได้ทำให้ตกลงไปในนามของตัวการโดยตรง"}},{"id":"TH-H004-A845","no":845,"noLabel":{"th":"มาตรา 845"},"chapter":{"th":"ลักษณะ 16"},"text":{"th":"มาตรา ๘๔๕ บุคคลผู้ใดตกลงจะให้ค่าบำเหน็จแก่นายหน้าเพื่อที่ชี้ช่องให้ได้เข้าทำสัญญาก็ดี จัดการให้ได้ทำสัญญากันก็ดี ท่านว่าบุคคลผู้นั้นจะต้องรับผิดใช้ค่าบำเหน็จก็ต่อเมื่อสัญญานั้นได้ทำกันสำเร็จเนื่องแต่ผลแห่งการที่นายหน้าได้ชี้ช่องหรือจัดการนั้น ถ้าสัญญาที่ได้ทำกันไว้นั้นมีเงื่อนไขเป็นเงื่อนบังคับก่อนไซร้ ท่านว่าจะเรียกร้องบำเหน็จค่านายหน้ายังหาได้ไม่ จนกว่าเงื่อนไขนั้นสำเร็จแล้ว นายหน้ามีสิทธิจะได้รับชดใช้ค่าใช้จ่ายที่ได้เสียไปก็ต่อเมื่อได้ตกลงกันไว้เช่นนั้น ความข้อนี้ท่านให้ใช้บังคับแม้ถึงว่าสัญญาจะมิได้ทำกันสำเร็จ"}},{"id":"TH-H004-A846","no":846,"noLabel":{"th":"มาตรา 846"},"chapter":{"th":"ลักษณะ 16"},"text":{"th":"มาตรา ๘๔๖ ถ้ากิจการอันได้มอบหมายแก่นายหน้านั้นโดยพฤติการณ์เป็นที่คาดหมายได้ว่าย่อมทำให้แต่เพื่อจะเอาค่าบำเหน็จไซร้ ท่านให้ถือว่าได้ตกลงกันโดยปริยายว่ามีค่าบำเหน็จนายหน้า ค่าบำเหน็จนั้นถ้ามิได้กำหนดจำนวนกันไว้ ท่านให้ถือว่าได้ตกลงกันเป็นจำนวนตามธรรมเนียม"}},{"id":"TH-H004-A847","no":847,"noLabel":{"th":"มาตรา 847"},"chapter":{"th":"ลักษณะ 16"},"text":{"th":"มาตรา ๘๔๗ ถ้านายหน้าทำการให้แก่บุคคลภายนอกด้วยก็ดี หรือได้รับคำมั่นแต่บุคคลภายนอกเช่นนั้นว่าจะให้ค่าบำเหน็จอันไม่ควรแก่นายหน้าผู้กระทำการโดยสุจริตก็ดี เป็นการฝ่าฝืนต่อการที่ตนเข้ารับทำหน้าที่ไซร้ ท่านว่านายหน้าหามีสิทธิจะได้รับค่าบำเหน็จหรือรับชดใช้ค่าใช้จ่ายที่ได้เสียไปไม่"}},{"id":"TH-H004-A848","no":848,"noLabel":{"th":"มาตรา 848"},"chapter":{"th":"ลักษณะ 16"},"text":{"th":"มาตรา ๘๔๘ ตัวนายหน้าไม่ต้องรับผิดไปถึงการชำระหนี้ตามสัญญาซึ่งได้ทำต่อกันเพราะตนเป็นสื่อ เว้นแต่จะมิได้บอกชื่อของฝ่ายหนึ่งให้รู้ถึงอีกฝ่ายหนึ่ง"}},{"id":"TH-H004-A849","no":849,"noLabel":{"th":"มาตรา 849"},"chapter":{"th":"ลักษณะ 16"},"text":{"th":"มาตรา ๘๔๙ การรับเงินหรือรับชำระหนี้อันจะพึงชำระตามสัญญานั้น ท่านให้สันนิษฐานไว้ก่อนว่านายหน้าย่อมไม่มีอำนาจที่จะรับแทนผู้เป็นคู่สัญญา"}},{"id":"TH-H004-A850","no":850,"noLabel":{"th":"มาตรา 850"},"chapter":{"th":"ลักษณะ 17"},"text":{"th":"มาตรา ๘๕๐ อันว่าประนีประนอมยอมความนั้น คือสัญญาซึ่งผู้เป็นคู่สัญญาทั้งสองฝ่ายระงับข้อพิพาทอันใดอันหนึ่งซึ่งมีอยู่หรือจะมีขึ้นนั้นให้เสร็จไปด้วยต่างยอมผ่อนผันให้แก่กัน"}},{"id":"TH-H004-A851","no":851,"noLabel":{"th":"มาตรา 851"},"chapter":{"th":"ลักษณะ 17"},"text":{"th":"มาตรา ๘๕๑ อันสัญญาประนีประนอมยอมความนั้น ถ้ามิได้มีหลักฐานเป็นหนังสืออย่างใดอย่างหนึ่งลงลายมือชื่อฝ่ายที่ต้องรับผิด หรือลายมือชื่อตัวแทนของฝ่ายนั้นเป็นสำคัญ ท่านว่าจะฟ้องร้องให้บังคับคดีหาได้ไม่"}},{"id":"TH-H004-A852","no":852,"noLabel":{"th":"มาตรา 852"},"chapter":{"th":"ลักษณะ 17"},"text":{"th":"มาตรา ๘๕๒ ผลของสัญญาประนีประนอมยอมความนั้น ย่อมทำให้การเรียกร้องซึ่งแต่ละฝ่ายได้ยอมสละนั้นระงับสิ้นไป และทำให้แต่ละฝ่ายได้สิทธิตามที่แสดงในสัญญานั้นว่าเป็นของตน"}},{"id":"TH-H004-A853","no":853,"noLabel":{"th":"มาตรา 853"},"chapter":{"th":"ลักษณะ 18"},"text":{"th":"มาตรา ๘๕๓ อันการพนันหรือขันต่อนั้น ท่านว่าหาก่อให้เกิดหนี้ไม่ สิ่งที่ได้ให้กันไปในการพนันหรือขันต่อก็จะทวงคืนไม่ได้ เพราะเหตุหามูลหนี้อย่างหนึ่งอย่างใดมิได้ ข้อบัญญัติที่กล่าวนี้ ท่านให้ใช้ตลอดถึงข้อตกลงเป็นมูลหนี้อย่างหนึ่งอย่างใดอันฝ่ายข้างเสียพนันขันต่อหากทำให้แก่อีกฝ่ายหนึ่งเพื่อจะใช้หนี้เงินพนันหรือขันต่อนั้นด้วย"}},{"id":"TH-H004-A854","no":854,"noLabel":{"th":"มาตรา 854"},"chapter":{"th":"ลักษณะ 18"},"text":{"th":"มาตรา ๘๕๔ อันการออกสลากกินแบ่งก็ดี ออกสลากกินรวบก็ดี ท่านว่าเป็นสัญญาอันจะผูกพันต่อเมื่อรัฐบาลได้ให้อำนาจหรือให้สัตยาบันแก่การนั้นเฉพาะราย นอกนั้นท่านให้บังคับตามบทบัญญัติมาตรา ๘๕๓"}},{"id":"TH-H004-A855","no":855,"noLabel":{"th":"มาตรา 855"},"chapter":{"th":"ลักษณะ 18"},"text":{"th":"มาตรา ๘๕๕ ภายในบังคับแห่งบทบัญญัติมาตรา ๓๑๒ และมาตรา ๙๑๖ ตั๋วเงินหรือเอกสารอย่างอื่นทุกฉบับซึ่งออกให้เต็มจำนวน หรือแต่โดยส่วน เพื่อแทนเงินใด ๆ อันได้แต่ชนะพนันหรือขัดต่อก็ดี ออกให้เพื่อใช้เงินที่ยืมมาใช้ในการพนันหรือขันต่อเช่นว่านั้นก็ดี ท่านว่าไม่สมบูรณ์ เพื่อประโยชน์แห่งบทบัญญัตินี้ เงินรายได้ให้ยืมแก่บุคคลกำลังเล่นการพนันหรือขันต่อ ในเวลาหรือ ณ สถานที่เล่นเช่นนั้น ท่านให้สันนิษฐานไว้ก่อนว่าเงินนั้นได้ให้ยืมไปเพื่อเล่นการพนันหรือขันต่อ"}},{"id":"TH-H004-A856","no":856,"noLabel":{"th":"มาตรา 856"},"chapter":{"th":"ลักษณะ 19"},"text":{"th":"มาตรา ๘๕๖ อันว่าสัญญาบัญชีเดินสะพัดนั้น คือสัญญาซึ่งบุคคลสองคนตกลงกันว่าสืบแต่นั้นไป หรือในชั่วเวลากำหนดอันใดอันหนึ่ง ให้ตัดทอนบัญชีหนี้ทั้งหมดหรือแต่บางส่วนอันเกิดขึ้นแต่กิจการในระหว่างเขาทั้งสองนั้นหักกลบลบกัน และคงชำระแต่ส่วนที่เป็นจำนวนคงเหลือโดยดุลยภาค"}},{"id":"TH-H004-A857","no":857,"noLabel":{"th":"มาตรา 857"},"chapter":{"th":"ลักษณะ 19"},"text":{"th":"มาตรา ๘๕๗ การนำตั๋วเงินลงเป็นรายการในบัญชีเดินสะพัดนั้น ท่านให้สันนิษฐานไว้ก่อนว่าได้ลงด้วยเงื่อนไขว่าจะมีผู้ชำระเงินตามตั๋วนั้น ถ้าและตั๋วนั้นมิได้ชำระเงินไซร้ จะเพิกถอนรายการอันนั้นเสียก็ได้"}},{"id":"TH-H004-A858","no":858,"noLabel":{"th":"มาตรา 858"},"chapter":{"th":"ลักษณะ 19"},"text":{"th":"มาตรา ๘๕๘ ถ้าคู่สัญญามิได้กำหนดกันไว้ว่าให้หักทอนบัญชีโดยระยะเวลาอย่างไรไซร้ ท่านให้ถือเอาเป็นกำหนดหกเดือน"}},{"id":"TH-H004-A859","no":859,"noLabel":{"th":"มาตรา 859"},"chapter":{"th":"ลักษณะ 19"},"text":{"th":"มาตรา ๘๕๙ คู่สัญญาฝ่ายใดจะบอกเลิกสัญญาบัญชีเดินสะพัด และให้หักทอนบัญชีกันเสียในเวลาใด ๆ ก็ได้ ถ้าไม่มีอะไรปรากฏเป็นข้อขัดกับที่กล่าวมานี้"}},{"id":"TH-H004-A860","no":860,"noLabel":{"th":"มาตรา 860"},"chapter":{"th":"ลักษณะ 19"},"text":{"th":"มาตรา ๘๖๐ เงินส่วนที่ผิดกันอยู่นั้นถ้ายังมิได้ชำระ ท่านให้คิดดอกเบี้ยนับแต่วันที่หักทอนบัญชีเสร็จเป็นต้นไป"}},{"id":"TH-H004-A861","no":861,"noLabel":{"th":"มาตรา 861"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๑ อันว่าสัญญาประกันภัยนั้น คือสัญญาซึ่งบุคคลหนึ่งตกลงจะใช้ค่าสินไหมทดแทน หรือใช้เงินจำนวนหนึ่งให้ในกรณีวินาศภัยหากมีขึ้น หรือในเหตุอย่างอื่นในอนาคตดังได้ระบุไว้ในสัญญา และในการนี้บุคคลอีกคนหนึ่งตกลงจะส่งเงินซึ่งเรียกว่า เบี้ยประกันภัย"}},{"id":"TH-H004-A862","no":862,"noLabel":{"th":"มาตรา 862"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๒ ตามข้อความในลักษณะนี้ คำว่า “ผู้รับประกันภัย” ท่านหมายความว่า คู่สัญญาฝ่ายซึ่งตกลงจะใช้ค่าสินไหมทดแทน หรือใช้เงินจำนวนหนึ่งให้ คำว่า “ผู้เอาประกันภัย” ท่านหมายความว่า คู่สัญญาฝ่ายซึ่งตกลงจะส่งเบี้ยประกันภัย คำว่า “ผู้รับประโยชน์” ท่านหมายความว่า บุคคลผู้จะพึงได้รับค่าสินไหมทดแทน หรือรับจำนวนเงินใช้ให้ อนึ่ง ผู้เอาประกันภัยและผู้รับประโยชน์นั้น จะเป็นบุคคลคนหนึ่งคนเดียวกันก็ได้"}},{"id":"TH-H004-A863","no":863,"noLabel":{"th":"มาตรา 863"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๓ อันสัญญาประกันภัยนั้น ถ้าผู้เอาประกันภัยมิได้มีส่วนได้เสียในเหตุที่ประกันภัยไว้นั้นไซร้ ท่านว่าย่อมไม่ผูกพันคู่สัญญาแต่อย่างหนึ่งอย่างใด"}},{"id":"TH-H004-A864","no":864,"noLabel":{"th":"มาตรา 864"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๔ เมื่อคู่สัญญาประกันภัยยกเอาภัยใดโดยเฉพาะขึ้นเป็นข้อพิจารณาในการวางกำหนดจำนวนเบี้ยประกันภัย และภัยเช่นนั้นสิ้นไปหามีไม่แล้ว ท่านว่าภายหน้าแต่นั้นไป ผู้เอาประกันภัยชอบที่จะได้ลดเบี้ยประกันภัยลงตามส่วน"}},{"id":"TH-H004-A865","no":865,"noLabel":{"th":"มาตรา 865"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๕ ถ้าในเวลาทำสัญญาประกันภัย ผู้เอาประกันภัยก็ดี หรือในกรณีประกันชีวิต บุคคลอันการใช้เงินย่อมอาศัยความทรงชีพหรือมรณะของเขานั้นก็ดี รู้อยู่แล้วละเว้นเสียไม่เปิดเผยข้อความจริงซึ่งอาจจะได้จูงใจผู้รับประกันภัยให้เรียกเบี้ยประกันภัยสูงขึ้นอีกหรือให้บอกปัดไม่ยอมทำสัญญา หรือว่ารู้อยู่แล้วแถลงข้อความนั้นเป็นความเท็จไซร้ ท่านว่าสัญญานั้นเป็นโมฆียะ ถ้ามิได้ใช้สิทธิบอกล้างภายในกำหนดเดือนหนึ่งนับแต่วันที่ผู้รับประกันภัยทราบมูลอันจะบอกล้างได้ก็ดี หรือมิได้ใช้สิทธินั้นภายในกำหนดห้าปีนับแต่วันทำสัญญาก็ดี ท่านว่าสิทธินั้นเป็นอันระงับสิ้นไป"}},{"id":"TH-H004-A866","no":866,"noLabel":{"th":"มาตรา 866"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๖ ถ้าผู้รับประกันภัยได้รู้ข้อความจริงดังกล่าวในมาตรา ๘๖๕ นั้นก็ดี หรือรู้ว่าข้อแถลงความเป็นความเท็จก็ดี หรือควรจะได้รู้เช่นนั้นหากใช้ความระมัดระวังดังจะพึงคาดหมายได้แต่วิญญูชนก็ดี ท่านให้ฟังว่าสัญญานั้นเป็นอันสมบูรณ์"}},{"id":"TH-H004-A867","no":867,"noLabel":{"th":"มาตรา 867"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๗ อันสัญญาประกันภัยนั้น ถ้ามิได้มีหลักฐานเป็นหนังสืออย่างใดอย่างหนึ่งลงลายมือชื่อฝ่ายที่ต้องรับผิดหรือลายมือชื่อตัวแทนของฝ่ายนั้นเป็นสำคัญ ท่านว่าจะฟ้องร้องให้บังคับคดีหาได้ไม่ ให้ส่งมอบกรมธรรม์ประกันภัยอันมีเนื้อความต้องตามสัญญานั้นแก่ผู้เอาประกันภัยฉบับหนึ่ง กรมธรรม์ประกันภัย ต้องลงลายมือชื่อของผู้รับประกันภัย และมีรายการดังต่อไปนี้ (๑) วัตถุที่เอาประกันภัย (๒) ภัยใดซึ่งผู้รับประกันภัยรับเสี่ยง (๓) ราคาแห่งมูลประกันภัย ถ้าหากได้กำหนดกันไว้ (๔) จำนวนเงินซึ่งเอาประกันภัย (๕) จำนวนเบี้ยประกันภัย และวิธีส่งเบี้ยประกันภัย (๖) ถ้าหากสัญญาประกันภัยมีกำหนดเวลา ต้องลงเวลาเริ่มต้นและเวลาสิ้นสุดไว้ด้วย (๗) ชื่อหรือยี่ห้อของผู้รับประกันภัย (๘) ชื่อหรือยี่ห้อของผู้เอาประกันภัย (๙) ชื่อของผู้รับประโยชน์ ถ้าจะพึงมี (๑๐) วันทำสัญญาประกันภัย (๑๑) สถานที่และวันที่ได้ทำกรมธรรม์ประกันภัย"}},{"id":"TH-H004-A868","no":868,"noLabel":{"th":"มาตรา 868"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๖๘ อันสัญญาประกันภัยทะเล ท่านให้บังคับตามบทบัญญัติแห่งกฎหมายทะเล"}},{"id":"TH-H004-A869","no":869,"noLabel":{"th":"มาตรา 869"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๖๙ อันคำว่า “วินาศภัย” ในหมวดนี้ ท่านหมายรวมเอาความเสียหายอย่างใด ๆ บรรดาซึ่งจะพึงประมาณเป็นเงินได้"}},{"id":"TH-H004-A870","no":870,"noLabel":{"th":"มาตรา 870"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๐ ถ้าได้ทำสัญญาประกันภัยเป็นสองรายหรือกว่านั้นพร้อมกันเพื่อความวินาศภัยอันเดียวกัน และจำนวนเงินซึ่งเอาประกันภัยรวมกันทั้งหมดนั้นท่วมจำนวนที่วินาศจริงไซร้ ท่านว่าผู้รับประโยชน์ชอบที่จะได้รับค่าสินไหมทดแทนเพียงเสมอจำนวนวินาศจริงเท่านั้น ผู้รับประกันภัยแต่ละคนต้องใช้เงินจำนวนวินาศจริงแบ่งตามส่วนมากน้อยที่ตนได้รับประกันภัยไว้ อันสัญญาประกันภัยทั้งหลาย ถ้าลงวันเดียวกัน ท่านให้ถือว่าได้ทำพร้อมกัน ถ้าได้ทำสัญญาประกันภัยเป็นสองรายหรือกว่านั้นสืบเนื่องเป็นลำดับกัน ท่านว่าผู้รับประกันภัยคนแรกจะต้องรับผิดเพื่อความวินาศภัยก่อน ถ้าและจำนวนเงินซึ่งผู้รับประกันภัยคนแรกได้ใช้นั้นยังไม่คุ้มจำนวนวินาศภัยไซร้ ผู้รับประกันภัยคนถัดไปก็ต้องรับผิดในส่วนที่ยังขาดอยู่นั้นต่อ ๆ กันไปจนกว่าจะคุ้มวินาศ"}},{"id":"TH-H004-A871","no":871,"noLabel":{"th":"มาตรา 871"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๑ ถ้าได้ทำสัญญาประกันภัยเป็นสองรายหรือกว่านั้นพร้อมกันก็ดี หรือสืบเนื่องเป็นลำดับกันก็ดี ท่านว่าการที่ยอมสละสิทธิอันมีต่อผู้รับประกันภัยรายหนึ่งนั้น ไม่กระทบกระทั่งถึงสิทธิและหน้าที่ของผู้รับประกันภัยรายอื่น ๆ"}},{"id":"TH-H004-A872","no":872,"noLabel":{"th":"มาตรา 872"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๒ ก่อนเริ่มเสี่ยงภัย ผู้เอาประกันภัยจะบอกเลิกสัญญาเสียก็ได้ แต่ผู้รับประกันภัยชอบที่จะได้เบี้ยประกันภัยกึ่งจำนวน"}},{"id":"TH-H004-A873","no":873,"noLabel":{"th":"มาตรา 873"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๓ ถ้าในระหว่างอายุสัญญาประกันภัยนั้น มูลประกันภัยได้ลดน้อยถอยลงไปหนักไซร้ ท่านว่าผู้เอาประกันภัยชอบที่จะได้ลดจำนวนเงินซึ่งเอาประกันภัยไว้ และลดจำนวนเงินเบี้ยประกันภัย การลดจำนวนเบี้ยประกันภัยนั้น ให้เป็นผลต่อในอนาคต"}},{"id":"TH-H004-A874","no":874,"noLabel":{"th":"มาตรา 874"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๔ ถ้าคู่สัญญาได้กำหนดราคาแห่งมูลประกันภัยไว้ ผู้รับประกันภัยชอบที่จะได้ลดจำนวนค่าสินไหมทดแทนก็แต่เมื่อพิสูจน์ได้ว่าราคาแห่งมูลประกันภัยตามที่ได้ตกลงกันไว้นั้นเป็นจำนวนสูงเกินไปหนัก และคืนจำนวนเบี้ยประกันภัยให้ตามส่วนกับทั้งดอกเบี้ยด้วย"}},{"id":"TH-H004-A875","no":875,"noLabel":{"th":"มาตรา 875"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๕ ถ้าวัตถุอันได้เอาประกันภัยไว้นั้น เปลี่ยนมือไปจากผู้เอาประกันภัยโดยพินัยกรรมก็ดี หรือโดยบัญญัติกฎหมายก็ดี ท่านว่าสิทธิอันมีอยู่ในสัญญาประกันภัยก็ย่อมโอนตามไปด้วย ถ้าในสัญญามิได้กำหนดไว้เป็นอย่างอื่น เมื่อผู้เอาประกันภัยโอนวัตถุที่เอาประกันภัยและบอกกล่าวการโอนไปยังผู้รับประกันภัยไซร้ ท่านว่าสิทธิอันมีอยู่ในสัญญาประกันภัยนั้นย่อมโอนตามไปด้วย อนึ่ง ถ้าในการโอนเช่นนี้ช่องแห่งภัยเปลี่ยนแปลงไปหรือเพิ่มขึ้นหนักไซร้ ท่านว่าสัญญาประกันภัยนั้นกลายเป็นโมฆะ"}},{"id":"TH-H004-A876","no":876,"noLabel":{"th":"มาตรา 876"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๖ ถ้าผู้รับประกันภัยต้องคำพิพากษาให้เป็นคนล้มละลาย ผู้เอาประกันภัยจะเรียกให้หาประกันอันสมควรให้แก่ตนก็ได้ หรือจะบอกเลิกสัญญาเสียก็ได้ ถ้าผู้เอาประกันภัยต้องคำพิพากษาให้เป็นคนล้มละลาย ท่านให้ใช้วิธีเดียวกันนี้บังคับตามควรแก่เรื่อง แต่กระนั้นก็ดี ถ้าเบี้ยประกันภัยได้ส่งแล้วเต็มจำนวนเพื่ออายุประกันภัยเป็นระยะเวลามากน้อยเท่าใดไซร้ ท่านห้ามมิให้ผู้รับประกันภัยบอกเลิกสัญญาก่อนระยะเวลานั้นสุดลง"}},{"id":"TH-H004-A877","no":877,"noLabel":{"th":"มาตรา 877"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๗ ผู้รับประกันภัยจำต้องใช้ค่าสินไหมทดแทนดังจะกล่าวต่อไปนี้ คือ (๑) เพื่อจำนวนวินาศภัยอันแท้จริง (๒) เพื่อความบุบสลายอันเกิดแก่ทรัพย์สินซึ่งได้เอาประกันภัยไว้เพราะได้จัดการตามสมควรเพื่อป้องปัดความวินาศภัย (๓) เพื่อบรรดาค่าใช้จ่ายอันสมควรซึ่งได้เสียไปเพื่อรักษาทรัพย์สินซึ่งเอาประกันภัยไว้นั้นมิให้วินาศ อันจำนวนวินาศจริงนั้น ท่านให้ตีราคา ณ สถานที่และในเวลาซึ่งเหตุวินาศภัยนั้นได้เกิดขึ้น อนึ่ง จำนวนเงินซึ่งได้เอาประกันภัยไว้นั้น ท่านให้สันนิษฐานไว้ก่อนว่าเป็นหลักประมาณอันถูกต้องในการตีราคาเช่นว่านั้น ท่านห้ามมิให้คิดค่าสินไหมทดแทนเกินไปกว่าจำนวนเงินซึ่งเอาประกันภัยไว้"}},{"id":"TH-H004-A878","no":878,"noLabel":{"th":"มาตรา 878"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๘ ค่าใช้จ่ายในการตีราคาวินาศภัยนั้น ท่านว่าผู้รับประกันภัยต้องเป็นผู้ออกใช้"}},{"id":"TH-H004-A879","no":879,"noLabel":{"th":"มาตรา 879"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๗๙ ผู้รับประกันภัยไม่ต้องรับผิดในเมื่อความวินาศภัยหรือเหตุอื่นซึ่งได้ระบุไว้ในสัญญานั้นได้เกิดขึ้นเพราะความทุจริต หรือความประมาทเลินเล่ออย่างร้ายแรงของผู้เอาประกันภัยหรือผู้รับประโยชน์ ผู้รับประกันภัยไม่ต้องรับผิดในความวินาศภัยอันเป็นผลโดยตรงมาแต่ความไม่สมประกอบในเนื้อแห่งวัตถุที่เอาประกันภัย เว้นแต่จะได้ตกลงกันเป็นอย่างอื่น"}},{"id":"TH-H004-A880","no":880,"noLabel":{"th":"มาตรา 880"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๘๐ ถ้าความวินาศภัยนั้นได้เกิดขึ้นเพราะการกระทำของบุคคลภายนอกไซร้ ผู้รับประกันภัยได้ใช้ค่าสินไหมทดแทนไปเป็นจำนวนเพียงใด ผู้รับประกันภัยย่อมเข้ารับช่วงสิทธิของผู้เอาประกันภัยและของผู้รับประโยชน์ซึ่งมีต่อบุคคลภายนอกเพียงนั้น ถ้าผู้รับประกันภัยได้ใช้ค่าสินไหมทดแทนไปแต่เพียงบางส่วนไซร้ ท่านห้ามมิให้ผู้รับประกันภัยนั้นใช้สิทธิของตนให้เสื่อมเสียสิทธิของผู้เอาประกันภัยหรือผู้รับประโยชน์ ในการที่เขาจะเรียกร้องเอาค่าสินไหมทดแทนจากบุคคลภายนอกเพื่อเศษแห่งจำนวนวินาศนั้น"}},{"id":"TH-H004-A881","no":881,"noLabel":{"th":"มาตรา 881"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๘๑ ถ้าความวินาศเกิดขึ้นเพราะภัยมีขึ้นดังผู้รับประกันภัยตกลงประกันภัยไว้ไซร้ เมื่อผู้เอาประกันภัยหรือผู้รับประโยชน์ทราบความวินาศนั้นแล้ว ต้องบอกกล่าวแก่ผู้รับประกันภัยโดยไม่ชักช้า ถ้ามิได้ปฏิบัติตามบทบัญญัติที่กล่าวมาในวรรคก่อน ผู้รับประกันภัยอาจเรียกร้องค่าสินไหมทดแทนเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่การนั้นได้ เว้นแต่อีกฝ่ายหนึ่งจะพิสูจน์ได้ว่าไม่สามารถที่จะปฏิบัติได้"}},{"id":"TH-H004-A882","no":882,"noLabel":{"th":"มาตรา 882"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๘๘๒ ในการเรียกให้ใช้ค่าสินไหมทดแทน ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นกำหนดสองปีนับแต่วันวินาศภัย ในการเรียกให้ใช้หรือให้คืนเบี้ยประกันภัย ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นเวลาสองปีนับแต่วันซึ่งสิทธิจะเรียกให้ใช้หรือคืนเบี้ยประกันภัยถึงกำหนด"}},{"id":"TH-H004-A883","no":883,"noLabel":{"th":"มาตรา 883"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๘๓ อันสัญญาประกันภัยในการรับขนนั้น ย่อมคุ้มถึงความวินาศภัยทุกอย่างซึ่งอาจเกิดแก่ของที่ขนส่งในระหว่างเวลาตั้งแต่ผู้ขนส่งได้รับของไป จนได้ส่งมอบของนั้นแก่ผู้รับตราส่ง และจำนวนค่าสินไหมทดแทนนั้น ย่อมกำหนดตามที่ของซึ่งขนส่งนั้นจะได้มีราคาเมื่อถึงตำบลอันกำหนดให้ส่ง"}},{"id":"TH-H004-A884","no":884,"noLabel":{"th":"มาตรา 884"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๘๔ ถ้าของซึ่งขนส่งนั้นได้เอาประกันภัยเมื่ออยู่ในระหว่างส่งเดินทางไป ท่านให้คิดมูลประกันภัยในของนั้นนับรวมทั้งราคาของ ณ สถานที่และในเวลาที่ผู้ขนส่งได้รับของ และให้เพิ่มค่าระวางส่งของไปยังสถานที่ส่งมอบแก่ผู้รับตราส่ง กับทั้งค่าใช้จ่ายอื่น ๆ เนื่องด้วยการส่งของไปนั้นเข้าด้วย กำไรอันจะพึงได้ในเวลาเมื่อส่งมอบของนั้นย่อมจะคิดรวมเข้าเป็นมูลประกันภัยได้ต่อเมื่อได้มีข้อตกลงกันไว้เช่นนั้นชัดแจ้ง"}},{"id":"TH-H004-A885","no":885,"noLabel":{"th":"มาตรา 885"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๘๕ อันสัญญาประกันภัยในการรับขนนั้น ถึงแม้การขนส่งจะต้องสะดุดหยุดลงชั่วขณะหรือจะต้องเปลี่ยนทางหรือเปลี่ยนวิธีขนส่งอย่างหนึ่งอย่างใดโดยเหตุจำเป็นในระหว่างส่งเดินทางก็ดี ท่านว่าสัญญานั้นก็ย่อมคงเป็นอันสมบูรณ์อยู่ เว้นแต่จะได้ระบุไว้ในสัญญาเป็นอย่างอื่น"}},{"id":"TH-H004-A886","no":886,"noLabel":{"th":"มาตรา 886"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๘๘๖ อันกรมธรรม์ประกันภัยในการรับขนนั้น นอกจากที่ได้ระบุไว้แล้วในมาตรา ๘๖๗ ต้องมีรายการเพิ่มขึ้นอีกดังจะกล่าวต่อไปนี้ คือ (๑) ระบุทางและวิธีขนส่ง (๒) ชื่อหรือยี่ห้อของผู้ขนส่ง (๓) สถานที่ซึ่งกำหนดให้รับและส่งมอบของ (๔) กำหนดระยะเวลาขนส่งตามแต่มี"}},{"id":"TH-H004-A887","no":887,"noLabel":{"th":"มาตรา 887"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๘๘๗ อันว่าประกันภัยค้ำจุนนั้น คือสัญญาประกันภัยซึ่งผู้รับประกันภัยตกลงว่าจะใช้ค่าสินไหมทดแทนในนามของผู้เอาประกันภัย เพื่อความวินาศภัยอันเกิดขึ้นแก่บุคคลอีกคนหนึ่ง และซึ่งผู้เอาประกันภัยจะต้องรับผิดชอบ บุคคลผู้ต้องเสียหายชอบที่จะได้รับค่าสินไหมทดแทนตามที่ตนควรจะได้นั้นจากผู้รับประกันภัยโดยตรง แต่ค่าสินไหมทดแทนเช่นว่านี้หาอาจจะคิดเกินไปกว่าจำนวนอันผู้รับประกันภัยจะพึงต้องใช้ตามสัญญานั้นได้ไม่ ในคดีระหว่างบุคคลผู้ต้องเสียหายกับผู้รับประกันภัยนั้น ท่านให้ผู้ต้องเสียหายเรียกตัวผู้เอาประกันภัยเข้ามาในคดีด้วย อนึ่ง ผู้รับประกันภัยนั้นแม้จะได้ส่งค่าสินไหมทดแทนให้แก่ผู้เอาประกันภัยแล้ว ก็ยังหาหลุดพ้นจากความรับผิดต่อบุคคลผู้ต้องเสียหายนั้นไม่ เว้นแต่ตนจะพิสูจน์ได้ว่าสินไหมทดแทนนั้นผู้เอาประกันภัยได้ใช้แก่ผู้ต้องเสียหายแล้ว"}},{"id":"TH-H004-A888","no":888,"noLabel":{"th":"มาตรา 888"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๘๘๘ ถ้าค่าสินไหมทดแทนอันผู้รับประกันภัยได้ใช้ไปโดยคำพิพากษานั้นยังไม่คุ้มค่าวินาศภัยเต็มจำนวนไซร้ ท่านว่าผู้เอาประกันภัยก็ยังคงต้องรับใช้จำนวนที่ยังขาด เว้นไว้แต่บุคคลผู้ต้องเสียหายจะได้ละเลยเสียไม่เรียกตัวผู้เอาประกันภัยเข้ามาสู่คดีด้วยดังกล่าวไว้ในมาตราก่อน"}},{"id":"TH-H004-A889","no":889,"noLabel":{"th":"มาตรา 889"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๘๙ ในสัญญาประกันชีวิตนั้น การใช้จำนวนเงินย่อมอาศัยความทรงชีพ หรือมรณะของบุคคลคนหนึ่ง"}},{"id":"TH-H004-A890","no":890,"noLabel":{"th":"มาตรา 890"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๐ จำนวนเงินอันจะพึงใช้นั้น จะชำระเป็นเงินจำนวนเดียว หรือเป็นเงินรายปีก็ได้ สุดแล้วแต่จะตกลงกันระหว่างคู่สัญญา"}},{"id":"TH-H004-A891","no":891,"noLabel":{"th":"มาตรา 891"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๑ แม้ในกรณีที่ผู้เอาประกันภัยมิได้เป็นผู้รับประโยชน์เองก็ดี ผู้เอาประกันภัยย่อมมีสิทธิที่จะโอนประโยชน์แห่งสัญญานั้นให้แก่บุคคลอีกคนหนึ่งได้ เว้นแต่จะได้ส่งมอบกรมธรรม์ประกันภัยให้แก่ผู้รับประโยชน์ไปแล้ว และผู้รับประโยชน์ได้บอกกล่าวเป็นหนังสือไปยังผู้รับประกันภัยแล้วว่าตนจำนงจะถือเอาประโยชน์แห่งสัญญานั้น ถ้ากรมธรรม์ประกันภัยได้ทำเป็นรูปให้ใช้เงินตามเขาสั่งแล้ว ท่านให้นำบทบัญญัติมาตรา ๓๐๙ มาใช้บังคับ"}},{"id":"TH-H004-A892","no":892,"noLabel":{"th":"มาตรา 892"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๒ ในกรณีบอกล้างสัญญาตามความในมาตรา ๘๖๕ ผู้รับประกันภัยต้องคืนค่าไถ่ถอนกรมธรรม์ประกันภัยให้แก่ผู้เอาประกันภัยหรือทายาทของผู้นั้น"}},{"id":"TH-H004-A893","no":893,"noLabel":{"th":"มาตรา 893"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๓ การใช้เงินอาศัยเหตุความทรงชีพ หรือมรณะของบุคคลผู้ใด แม้ได้แถลงอายุของบุคคลผู้นั้นไว้คลาดเคลื่อนไม่ถูกต้องเป็นเหตุให้ได้กำหนดจำนวนเบี้ยประกันภัยไว้ต่ำไซร้ ท่านให้ลดจำนวนเงินอันผู้รับประกันภัยจะพึงต้องใช้นั้นลงตามส่วน แต่ถ้าผู้รับประกันภัยพิสูจน์ได้ว่าในขณะที่ทำสัญญานั้น อายุที่ถูกต้องแท้จริงอยู่นอกจำกัดอัตราตามทางค้าปกติของเขาแล้ว ท่านว่าสัญญานั้นเป็นโมฆียะ"}},{"id":"TH-H004-A894","no":894,"noLabel":{"th":"มาตรา 894"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๔ ผู้เอาประกันภัยชอบที่จะบอกเลิกสัญญาประกันภัยเสียในเวลาใด ๆ ก็ได้ด้วยการงดไม่ส่งเบี้ยประกันภัยต่อไป ถ้าและได้ส่งเบี้ยประกันภัยมาแล้วอย่างน้อยสามปีไซร้ ท่านว่าผู้เอาประกันภัยชอบที่จะได้รับเงินค่าเวนคืนกรมธรรม์ประกันภัย หรือรับกรมธรรม์ใช้เงินสำเร็จจากผู้รับประกันภัย"}},{"id":"TH-H004-A895","no":895,"noLabel":{"th":"มาตรา 895"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๕ เมื่อใดจะต้องใช้จำนวนเงินในเหตุมรณะของบุคคลคนหนึ่งคนใด ท่านว่าผู้รับประกันภัยจำต้องใช้เงินนั้นในเมื่อมรณภัยอันนั้นเกิดขึ้น เว้นแต่ (๑) บุคคลผู้นั้นได้กระทำอัตตวินิบาตด้วยใจสมัครภายในปีหนึ่งนับแต่วันทำสัญญา หรือ (๒) บุคคลผู้นั้นถูกผู้รับประโยชน์ฆ่าตายโดยเจตนา ในกรณีที่ ๒ นี้ ท่านว่าผู้รับประกันภัยจำต้องใช้เงินค่าไถ่ถอนกรมธรรม์ให้แก่ผู้เอาประกันภัย หรือให้แก่ทายาทของผู้นั้น"}},{"id":"TH-H004-A896","no":896,"noLabel":{"th":"มาตรา 896"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๖ ถ้ามรณภัยเกิดขึ้นเพราะความผิดของบุคคลภายนอก ผู้รับประกันภัยหาอาจจะเรียกเอาค่าสินไหมทดแทนจากบุคคลภายนอกนั้นได้ไม่ แต่สิทธิของฝ่ายทายาทแห่งผู้มรณะในอันจะได้ค่าสินไหมทดแทนจากบุคคลภายนอกนั้นหาสูญสิ้นไปด้วยไม่ แม้ทั้งจำนวนเงินอันจะพึงใช้ตามสัญญาประกันชีวิตนั้นจะหวนกลับมาได้แก่ตนด้วย"}},{"id":"TH-H004-A897","no":897,"noLabel":{"th":"มาตรา 897"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๘๙๗ ถ้าผู้เอาประกันภัยได้เอาประกันภัยไว้โดยกำหนดว่า เมื่อตนถึงซึ่งความมรณะให้ใช้เงินแก่ทายาททั้งหลายของตนโดยมิได้เจาะจงระบุชื่อผู้หนึ่งผู้ใดไว้ไซร้ จำนวนเงินอันจะพึงใช้นั้นท่านให้ฟังเอาเป็นสินทรัพย์ส่วนหนึ่งแห่งกองมรดกของผู้เอาประกันภัย ซึ่งเจ้าหนี้จะเอาใช้หนี้ได้ ถ้าได้เอาประกันภัยไว้โดยกำหนดว่าให้ใช้เงินแก่บุคคลคนใดคนหนึ่งโดยเฉพาะเจาะจง ท่านว่าเฉพาะแต่จำนวนเงินเบี้ยประกันภัยซึ่งผู้เอาประกันภัยได้ส่งไปแล้วเท่านั้นจักเป็นสินทรัพย์ส่วนหนึ่งแห่งกองมรดกของผู้เอาประกันภัยอันเจ้าหนี้จะเอาใช้หนี้ได้"}},{"id":"TH-H004-A898","no":898,"noLabel":{"th":"มาตรา 898"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๙๘ อันตั๋วเงินตามความหมายแห่งประมวลกฎหมายนี้มีสามประเภท ประเภทหนึ่ง คือตั๋วแลกเงิน ประเภทหนึ่ง คือตั๋วสัญญาใช้เงิน ประเภทหนึ่ง คือเช็ค"}},{"id":"TH-H004-A899","no":899,"noLabel":{"th":"มาตรา 899"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๘๙๙ ข้อความอันใดซึ่งมิได้มีบัญญัติไว้ในประมวลกฎหมายลักษณะนี้ ถ้าเขียนลงในตั๋วเงิน ท่านว่าข้อความอันนั้นหาเป็นผลอย่างหนึ่งอย่างใดแก่ตั๋วเงินนั้นไม่"}},{"id":"TH-H004-A900","no":900,"noLabel":{"th":"มาตรา 900"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๐ บุคคลผู้ลงลายมือชื่อของตนในตั๋วเงินย่อมจะต้องรับผิดตามเนื้อความในตั๋วเงินนั้น ถ้าลงเพียงแต่เครื่องหมายอย่างหนึ่งอย่างใด เช่น แกงได หรือลายพิมพ์นิ้วมืออ้างเอาเป็นลายมือชื่อในตั๋วเงินไซร้ แม้ถึงว่าจะมีพยานลงชื่อรับรองก็ตาม ท่านว่าหาให้ผลเป็นลงลายมือชื่อในตั๋วเงินนั้นไม่"}},{"id":"TH-H004-A901","no":901,"noLabel":{"th":"มาตรา 901"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๑ ถ้าบุคคลคนใดลงลายมือชื่อของตนในตั๋วเงิน และมิได้เขียนแถลงว่ากระทำการแทนบุคคลอีกคนหนึ่งไซร้ ท่านว่าบุคคลคนนั้นย่อมเป็นผู้รับผิดตามความในตั๋วเงินนั้น"}},{"id":"TH-H004-A902","no":902,"noLabel":{"th":"มาตรา 902"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๒ ถ้าตั๋วเงินลงลายมือชื่อของบุคคลหลายคน มีทั้งบุคคลซึ่งไม่อาจจะเป็นคู่สัญญาแห่งตั๋วเงินนั้นได้เลย หรือเป็นได้แต่ไม่เต็มผลไซร้ ท่านว่าการนี้ย่อมไม่กระทบกระทั่งถึงความรับผิดของบุคคลอื่น ๆ นอกนั้นซึ่งคงต้องรับผิดตามตั๋วเงิน"}},{"id":"TH-H004-A903","no":903,"noLabel":{"th":"มาตรา 903"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๓ ในการใช้เงินตามตั๋วเงิน ท่านมิให้ให้วันผ่อน"}},{"id":"TH-H004-A904","no":904,"noLabel":{"th":"มาตรา 904"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๔ อันผู้ทรงนั้น หมายความว่า บุคคลผู้มีตั๋วเงินไว้ในครอบครอง โดยฐานเป็นผู้รับเงิน หรือเป็นผู้รับสลักหลัง ถ้าและเป็นตั๋วเงินสั่งจ่ายให้แก่ผู้ถือ ๆ ก็นับว่าเป็นผู้ทรงเหมือนกัน"}},{"id":"TH-H004-A905","no":905,"noLabel":{"th":"มาตรา 905"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๕ ภายในบังคับแห่งบทบัญญัติมาตรา ๑๐๐๘ บุคคลผู้ได้ตั๋วเงินไว้ในครอบครอง ถ้าแสดงให้ปรากฏสิทธิด้วยการสลักหลังไม่ขาดสาย แม้ถึงว่าการสลักหลังรายที่สุดจะเป็นสลักหลังลอยก็ตาม ท่านให้ถือว่าเป็นผู้ทรงโดยชอบด้วยกฎหมาย เมื่อใดรายการสลักหลังลอยมีสลักหลังรายอื่นตามหลังไปอีก ท่านให้ถือว่าบุคคลผู้ที่ลงลายมือชื่อในการสลักหลังรายที่สุดนั้น เป็นผู้ได้ไปซึ่งตั๋วเงินด้วยการสลักหลังลอย อนึ่ง คำสลักหลังเมื่อขีดฆ่าเสียแล้ว ท่านให้ถือเสมือนว่ามิได้มีเลย ถ้าบุคคลผู้หนึ่งผู้ใดต้องปราศจากตั๋วเงินไปจากครอบครอง ท่านว่าผู้ทรงซึ่งแสดงให้ปรากฏสิทธิของตนในตั๋วตามวิธีการดังกล่าวมาในวรรคก่อนนั้น หาจำต้องสละตั๋วเงินไม่ เว้นแต่จะได้มาโดยทุจริต หรือได้มาด้วยความประมาทเลินเล่ออย่างร้ายแรง อนึ่ง ข้อความในวรรคก่อนนี้ ให้ใช้บังคับตลอดถึงผู้ทรงตั๋วเงินสั่งจ่ายให้แก่ผู้ถือด้วย"}},{"id":"TH-H004-A906","no":906,"noLabel":{"th":"มาตรา 906"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๖ คำว่าคู่สัญญาคนก่อน ๆ นั้น รวมทั้งผู้สั่งจ่ายหรือผู้ออกตั๋วเงินและผู้สลักหลังคนก่อน ๆ ด้วย"}},{"id":"TH-H004-A907","no":907,"noLabel":{"th":"มาตรา 907"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๙๐๗ เมื่อใดไม่มีที่ในตั๋วเงินซึ่งจะสลักหลังได้ต่อไปไซร้ ท่านอนุญาตให้เอากระดาษแผ่นหนึ่งผนึกต่อเข้ากับตั๋วเงินเรียกว่าใบประจำต่อ นับเป็นส่วนหนึ่งแห่งตั๋วเงินนั้น การสลักหลังในใบประจำต่อครั้งแรกต้องเขียนคาบบนตั๋วเงินเดิมบ้าง บนใบประจำต่อบ้าง"}},{"id":"TH-H004-A908","no":908,"noLabel":{"th":"มาตรา 908"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๐๘ อันว่าตั๋วแลกเงินนั้น คือหนังสือตราสารซึ่งบุคคลคนหนึ่ง เรียกว่าผู้สั่งจ่าย สั่งบุคคลอีกคนหนึ่ง เรียกว่าผู้จ่าย ให้ใช้เงินจำนวนหนึ่งแก่บุคคลคนหนึ่ง หรือให้ใช้ตามคำสั่งของบุคคลคนหนึ่งซึ่งเรียกว่าผู้รับเงิน"}},{"id":"TH-H004-A909","no":909,"noLabel":{"th":"มาตรา 909"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๐๙ อันตั๋วแลกเงินนั้น ต้องมีรายการดังกล่าวต่อไปนี้ คือ (๑) คำบอกชื่อว่าเป็นตั๋วแลกเงิน (๒) คำสั่งอันปราศจากเงื่อนไขให้จ่ายเงินเป็นจำนวนแน่นอน (๓) ชื่อ หรือยี่ห้อผู้จ่าย (๔) วันถึงกำหนดใช้เงิน (๕) สถานที่ใช้เงิน (๖) ชื่อ หรือยี่ห้อผู้รับเงิน หรือคำจดแจ้งว่าให้ใช้เงินแก่ผู้ถือ (๗) วันและสถานที่ออกตั๋วเงิน (๘) ลายมือชื่อผู้สั่งจ่าย"}},{"id":"TH-H004-A910","no":910,"noLabel":{"th":"มาตรา 910"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๐ ตราสารอันมีรายการขาดตกบกพร่องไปจากที่ท่านระบุบังคับไว้ในมาตราก่อนนี้ ย่อมไม่สมบูรณ์เป็นตั๋วแลกเงิน เว้นแต่ในกรณีดังจะกล่าวต่อไปนี้ คือ ตั๋วแลกเงินซึ่งไม่ระบุเวลาใช้เงิน ท่านให้ถือว่าพึงใช้เงินเมื่อได้เห็น ถ้าสถานที่ใช้เงินมิได้แถลงไว้ในตั๋วแลกเงิน ท่านให้ถือเอาภูมิลำเนาของผู้จ่ายเป็นสถานที่ใช้เงิน ถ้าตั๋วแลกเงินไม่แสดงให้ปรากฏสถานที่ออกตั๋ว ท่านให้ถือว่าตั๋วเงินนั้นได้ออก ณ ภูมิลำเนาของผู้สั่งจ่าย ถ้ามิได้ลงวันออกตั๋ว ท่านว่าผู้ทรงโดยชอบด้วยกฎหมายคนหนึ่งคนใดทำการโดยสุจริตจะจดวันตามที่ถูกต้องแท้จริงลงก็ได้"}},{"id":"TH-H004-A911","no":911,"noLabel":{"th":"มาตรา 911"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๑ ผู้สั่งจ่ายจะเขียนข้อความกำหนดลงไว้ว่าจำนวนเงินอันจะพึงใช้นั้นให้คิดดอกเบี้ยด้วยก็ได้ และในกรณีเช่นนั้น ถ้ามิได้กล่าวลงไว้เป็นอย่างอื่น ท่านว่าดอกเบี้ยย่อมคิดแต่วันที่ลงในตั๋วเงิน"}},{"id":"TH-H004-A912","no":912,"noLabel":{"th":"มาตรา 912"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๒ อันตั๋วแลกเงินนั้นจะออกสั่งให้ใช้เงินตามคำสั่งของผู้สั่งจ่ายก็ได้ อนึ่ง จะสั่งจ่ายเอาจากตัวผู้สั่งจ่ายเอง หรือสั่งจ่ายเพื่อบุคคลภายนอกก็ได้"}},{"id":"TH-H004-A913","no":913,"noLabel":{"th":"มาตรา 913"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๓ อันวันถึงกำหนดของตั๋วแลกเงินนั้น ท่านว่าย่อมเป็นอย่างใดอย่างหนึ่งดังกล่าวต่อไปนี้ คือ (๑) ในวันใดวันหนึ่งที่กำหนดไว้ หรือ (๒) เมื่อสิ้นระยะเวลาอันกำหนดไว้นับแต่วันที่ลงในตั๋วนั้น หรือ (๓) เมื่อทวงถาม หรือเมื่อได้เห็น หรือ (๔) เมื่อสิ้นระยะเวลาอันกำหนดไว้นับแต่ได้เห็น"}},{"id":"TH-H004-A914","no":914,"noLabel":{"th":"มาตรา 914"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๔ บุคคลผู้สั่งจ่ายหรือสลักหลังตั๋วแลกเงินย่อมเป็นอันสัญญาว่า เมื่อตั๋วนั้นได้นำยื่นโดยชอบแล้วจะมีผู้รับรองและใช้เงินตามเนื้อความแห่งตั๋ว ถ้าและตั๋วแลกเงินนั้นเขาไม่เชื่อถือโดยไม่ยอมรับรองก็ดี หรือไม่ยอมจ่ายเงินก็ดี ผู้สั่งจ่ายหรือผู้สลักหลังก็จะใช้เงินแก่ผู้ทรง หรือแก่ผู้สลักหลังคนหลังซึ่งต้องถูกบังคับให้ใช้เงินตามตั๋วนั้น ถ้าหากว่าได้ทำถูกต้องตามวิธีการในข้อไม่รับรองหรือไม่จ่ายเงินนั้นแล้ว"}},{"id":"TH-H004-A915","no":915,"noLabel":{"th":"มาตรา 915"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๕ ผู้สั่งจ่ายตั๋วแลกเงินและผู้สลักหลังคนใด ๆ ก็ดี จะจดข้อกำหนดซึ่งจะกล่าวต่อไปนี้ลงไว้ชัดแจ้งในตั๋วนั้นก็ได้ คือ (๑) ข้อกำหนดลบล้างหรือจำกัดความรับผิดของตนเองต่อผู้ทรงตั๋วเงิน (๒) ข้อกำหนดยอมลดละให้แก่ผู้ทรงตั๋วเงินซึ่งหน้าที่ทั้งหลายอันผู้ทรงจะพึงต้องมีแก่ตนบางอย่างหรือทั้งหมด"}},{"id":"TH-H004-A916","no":916,"noLabel":{"th":"มาตรา 916"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๖ บุคคลทั้งหลายผู้ถูกฟ้องในมูลตั๋วแลกเงิน หาอาจจะต่อสู้ผู้ทรงด้วยข้อต่อสู้อันอาศัยความเกี่ยวพันกันเฉพาะบุคคลระหว่างตนกับผู้สั่งจ่ายหรือกับผู้ทรงคนก่อน ๆ นั้นได้ไม่ เว้นแต่การโอนจะได้มีขึ้นด้วยคบคิดกันฉ้อฉล"}},{"id":"TH-H004-A917","no":917,"noLabel":{"th":"มาตรา 917"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๗ อันตั๋วแลกเงินทุกฉบับ ถึงแม้ว่าจะมิใช่สั่งจ่ายให้แก่บุคคลเพื่อเขาสั่งก็ตาม ท่านว่าย่อมโอนให้กันได้ด้วยสลักหลังและส่งมอบ เมื่อผู้สั่งจ่ายเขียนลงในด้านหน้าแห่งตั๋วแลกเงินว่า “เปลี่ยนมือไม่ได้” ดังนี้ก็ดี หรือเขียนคำอื่นอันได้ความเป็นทำนองเช่นเดียวกันนั้นก็ดี ท่านว่าตั๋วเงินนั้นย่อมจะโอนให้กันได้แต่โดยรูปการและด้วยผลอย่างการโอนสามัญ อนึ่ง ตั๋วเงินจะสลักหลังให้แก่ผู้จ่ายก็ได้ ไม่ว่าผู้จ่ายจะได้รับรองตั๋วนั้นหรือไม่ หรือจะสลักหลังให้แก่ผู้สั่งจ่าย หรือให้แก่คู่สัญญาฝ่ายอื่นใดแห่งตั๋วเงินนั้นก็ได้ ส่วนบุคคลทั้งหลายเหล่านี้ก็ย่อมจะสลักหลังตั๋วเงินนั้นต่อไปอีกได้"}},{"id":"TH-H004-A918","no":918,"noLabel":{"th":"มาตรา 918"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๘ ตั๋วแลกเงินอันสั่งให้ใช้เงินแก่ผู้ถือนั้น ท่านว่าย่อมโอนไปเพียงด้วยส่งมอบให้กัน"}},{"id":"TH-H004-A919","no":919,"noLabel":{"th":"มาตรา 919"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๑๙ คำสลักหลังนั้นต้องเขียนลงในตั๋วแลกเงิน หรือใบประจำต่อ และต้องลงลายมือชื่อผู้สลักหลัง การสลักหลังย่อมสมบูรณ์แม้ทั้งมิได้ระบุชื่อผู้รับประโยชน์ไว้ด้วย หรือแม้ผู้สลักหลังจะมิได้กระทำอะไรยิ่งไปกว่าลงลายมือชื่อของตนที่ด้านหลังตั๋วแลกเงินหรือที่ใบประจำต่อก็ย่อมฟังเป็นสมบูรณ์ดุจกัน การสลักหลังเช่นนี้เรียกว่า “สลักหลังลอย”"}},{"id":"TH-H004-A920","no":920,"noLabel":{"th":"มาตรา 920"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๐ อันการสลักหลังย่อมโอนไปซึ่งบรรดาสิทธิอันเกิดแต่ตั๋วแลกเงิน ถ้าสลักหลังลอย ผู้ทรงจะปฏิบัติดังกล่าวต่อไปนี้ประการหนึ่งประการใดก็ได้ คือ (๑) กรอกความลงในที่ว่างด้วยเขียนชื่อของตนเอง หรือชื่อบุคคลอื่นผู้ใดผู้หนึ่ง (๒) สลักหลังตั๋วเงินต่อไปอีกเป็นสลักหลังลอย หรือสลักหลังให้แก่บุคคลอื่นผู้ใดผู้หนึ่ง (๓) โอนตั๋วเงินนั้นให้ไปแก่บุคคลภายนอกโดยไม่กรอกความลงในที่ว่าง และไม่สลักหลังอย่างหนึ่งอย่างใด"}},{"id":"TH-H004-A921","no":921,"noLabel":{"th":"มาตรา 921"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๑ การสลักหลังตั๋วแลกเงินซึ่งสั่งให้ใช้เงินแก่ผู้ถือนั้น ย่อมเป็นเพียงประกัน (อาวัล) สำหรับผู้สั่งจ่าย"}},{"id":"TH-H004-A922","no":922,"noLabel":{"th":"มาตรา 922"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๒ การสลักหลังนั้นต้องให้เป็นข้อความอันปราศจากเงื่อนไข ถ้าและวางเงื่อนไขบังคับลงไว้อย่างใด ท่านให้ถือเสมือนว่าข้อเงื่อนไขนั้นมิได้เขียนลงไว้เลย อนึ่ง การสลักหลังโอนแต่บางส่วน ท่านว่าเป็นโมฆะ"}},{"id":"TH-H004-A923","no":923,"noLabel":{"th":"มาตรา 923"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๓ ผู้สลักหลังคนใดระบุข้อความห้ามสลักหลังสืบไปลงไว้แล้ว ผู้สลักหลังคนนั้นย่อมไม่ต้องรับผิดต่อบุคคลอันเขาสลักหลังตั๋วแลกเงินนั้นให้ไปในภายหลัง"}},{"id":"TH-H004-A924","no":924,"noLabel":{"th":"มาตรา 924"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๔ ถ้าตั๋วแลกเงินสลักหลังต่อเมื่อสิ้นเวลาเพื่อคัดค้านการไม่รับรองหรือการไม่ใช้เงินนั้นแล้วไซร้ ท่านว่าผู้รับสลักหลังย่อมได้ไปซึ่งสิทธิแห่งการรับรองตามแต่มีต่อผู้จ่าย กับสิทธิไล่เบี้ยเอาแก่บรรดาผู้ซึ่งสลักหลังตั๋วเงินนั้น ภายหลังที่สิ้นเวลาเช่นนั้น แต่ถ้าตั๋วเงินนั้นได้มีคัดค้านการไม่รับรองหรือการไม่ใช้เงินมาแต่ก่อนสลักหลังแล้วไซร้ ท่านว่าผู้รับสลักหลังย่อมได้ไปแต่เพียงสิทธิของผู้ซึ่งสลักหลังให้แก่ตนอันมีต่อผู้รับรองต่อผู้สั่งจ่าย และต่อบรรดาผู้ที่สลักหลังตั๋วเงินนั้นมาก่อนย้อนขึ้นไปจนถึงเวลาคัดค้านเท่านั้น"}},{"id":"TH-H004-A925","no":925,"noLabel":{"th":"มาตรา 925"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๕ เมื่อใดความที่สลักหลังมีข้อกำหนดว่า “ราคาอยู่ที่เรียกเก็บ” ก็ดี “เพื่อเรียกเก็บ” ก็ดี “ในฐานจัดการแทน” ก็ดี หรือความสำนวนอื่นใดอันเป็นปริยายว่าตัวแทนไซร้ ท่านว่าผู้ทรงตั๋วแลกเงินจะใช้สิทธิทั้งปวงอันเกิดแต่ตั๋วนั้นก็ย่อมได้ทั้งสิ้น แต่ว่าจะสลักหลังได้เพียงในฐานเป็นตัวแทน ในกรณีเช่นนี้ คู่สัญญาทั้งหลายซึ่งต้องรับผิดอาจจะต่อสู้ผู้ทรงได้แต่เพียงด้วยข้อต่อสู้อันจะพึงใช้ได้ต่อผู้สลักหลังเท่านั้น"}},{"id":"TH-H004-A926","no":926,"noLabel":{"th":"มาตรา 926"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๙๒๖ เมื่อใดความที่สลักหลังมีข้อกำหนดว่า “ราคาเป็นประกัน” ก็ดี “ราคาเป็นจำนำ” ก็ดี หรือข้อกำหนดอย่างอื่นใดอันเป็นปริยายว่าจำนำไซร้ ท่านว่าผู้ทรงตั๋วแลกเงินจะใช้สิทธิทั้งปวงอันเกิดแต่ตั๋วนั้นก็ย่อมได้ทั้งสิ้น แต่ถ้าผู้ทรงสลักหลังตั๋วนั้น ท่านว่าการสลักหลังย่อมใช้ได้เพียงในฐานเป็นคำสลักหลังของตัวแทน คู่สัญญาทั้งหลายซึ่งต้องรับผิดหาอาจจะต่อสู้ผู้ทรงด้วยข้อต่อสู้อันอาศัยความเกี่ยวพันเฉพาะบุคคลระหว่างตนกับผู้สลักหลังนั้นได้ไม่ เว้นแต่การสลักหลังจะได้มีขึ้นด้วยคบคิดกันฉ้อฉล"}},{"id":"TH-H004-A927","no":927,"noLabel":{"th":"มาตรา 927"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๒๗ อันตั๋วแลกเงินนั้นจะนำไปยื่นแก่ผู้จ่าย ณ ที่อยู่ของผู้จ่าย เพื่อให้รับรองเมื่อไร ๆ ก็ได้ จนกว่าจะถึงเวลากำหนดใช้เงิน และผู้ทรงจะเป็นผู้ยื่นหรือเพียงแต่ผู้ที่ได้ตั๋วนั้นไว้ในครอบครองจะเป็นผู้นำไปยื่นก็ได้ ในตั๋วแลกเงินนั้น ผู้สั่งจ่ายจะลงข้อกำหนดไว้ว่าให้นำยื่นเพื่อรับรอง โดยกำหนดเวลาจำกัดไว้ให้ยื่น หรือไม่กำหนดเวลาก็ได้ ผู้สั่งจ่ายจะห้ามการนำตั๋วแลกเงินยื่นเพื่อรับรองก็ได้ เว้นแต่ในกรณีที่เป็นตั๋วเงินอันได้ออกสั่งให้ใช้เงินเฉพาะ ณ สถานที่อื่นใดอันมิใช่ภูมิลำเนาของผู้จ่าย หรือได้ออกสั่งให้ใช้เงินในเวลาใดเวลาหนึ่งนับแต่ได้เห็น อนึ่ง ผู้สั่งจ่ายจะลงข้อกำหนดไว้ว่ายังมิให้นำตั๋วยื่นเพื่อให้รับรองก่อนถึงกำหนดวันใดวันหนึ่งก็ได้ ผู้สลักหลังทุกคนจะลงข้อกำหนดไว้ว่า ให้นำตั๋วเงินยื่นเพื่อรับรอง โดยกำหนดเวลาจำกัดไว้ให้ยื่น หรือไม่กำหนดเวลาก็ได้ เว้นแต่ผู้สั่งจ่ายจะได้ห้ามการรับรอง"}},{"id":"TH-H004-A928","no":928,"noLabel":{"th":"มาตรา 928"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๒๘ ผู้ทรงตั๋วแลกเงินอันสั่งให้ใช้เงินเมื่อสิ้นระยะเวลากำหนดอย่างใดอย่างหนึ่งนับแต่ได้เห็นนั้น ต้องนำตั๋วเงินยื่นเพื่อให้รับรองภายในหกเดือนนับแต่วันที่ลงในตั๋วเงิน หรือภายในเวลาช้าเร็วกว่านั้นตามแต่ผู้สั่งจ่ายจะได้ระบุไว้"}},{"id":"TH-H004-A929","no":929,"noLabel":{"th":"มาตรา 929"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๒๙ ภายในบังคับบทบัญญัติมาตรา ๙๒๗ ผู้ทรงตั๋วแลกเงินมีสิทธิที่จะยื่นตั๋วเงินแก่ผู้จ่ายได้ในทันใดเพื่อให้รับรอง ถ้าและเขาไม่รับรองภายในเวลายี่สิบสี่ชั่วโมงไซร้ ผู้ทรงก็มีสิทธิที่จะคัดค้าน"}},{"id":"TH-H004-A930","no":930,"noLabel":{"th":"มาตรา 930"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๐ ในการยื่นตั๋วแลกเงินเพื่อให้เขารับรองนั้น ผู้ทรงไม่จำต้องปล่อยตั๋วนั้นให้ไว้ในมือผู้จ่าย อนึ่ง ผู้จ่ายจะเรียกให้ยื่นตั๋วแลกเงินแก่ตนอีกเป็นครั้งที่สองในวันรุ่งขึ้นแต่วันที่ยื่นครั้งแรกนั้นก็ได้ ท่านห้ามมิให้คู่กรณีที่มีส่วนได้เสียยกเอาการที่มิได้อนุวัตตามคำเรียกอันนี้ขึ้นเป็นข้อต่อสู้ เว้นแต่การเรียกนั้นได้ระบุไว้ในคำคัดค้าน"}},{"id":"TH-H004-A931","no":931,"noLabel":{"th":"มาตรา 931"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๑ การรับรองนั้นพึงกระทำด้วยเขียนลงไว้ในด้านหน้าแห่งตั๋วแลกเงินเป็นถ้อยคำสำนวนว่า “รับรองแล้ว” หรือความอย่างอื่นทำนองเช่นเดียวกันนั้น และลงลายมือชื่อของผู้จ่าย อนึ่ง แต่เพียงลงลายมือชื่อของผู้จ่ายลงไว้ในด้านหน้าแห่งตั๋วแลกเงิน ท่านก็จัดว่าเป็นคำรับรองแล้ว"}},{"id":"TH-H004-A932","no":932,"noLabel":{"th":"มาตรา 932"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๒ ตั๋วแลกเงินฉบับใดเขียนสั่งให้ใช้เงินในกำหนดระยะเวลาอย่างใดอย่างหนึ่งนับแต่วันที่ลงในตั๋วเงินนั้น แต่หากมิได้ลงวันไว้ก็ดี หรือตั๋วเงินฉบับใดสั่งให้ใช้เงินในกำหนดระยะเวลาอย่างใดอย่างหนึ่งนับแต่ได้เห็น แต่หากคำรับรองตั๋วนั้นมิได้ลงวันไว้ก็ดี ตั๋วแลกเงินเช่นว่ามานี้ ท่านว่าผู้ทรงจะจดวันออกตั๋วหรือวันรับรองลงตามที่แท้จริงก็ได้แล้วพึงให้ใช้เงินตามนั้น อนึ่ง ท่านบัญญัติไว้ว่า ในกรณีที่ผู้ทรงทำการโดยสุจริต แต่ลงวันคลาดเคลื่อนไปด้วยสำคัญผิด และในกรณีลงวันผิดทุกสถาน หากว่าในภายหลังตั๋วเงินนั้นตกไปยังมือผู้ทรงโดยชอบด้วยกฎหมายแล้ว ตั๋วเงินจะเสียไปเพราะเหตุนั้นก็หาไม่ ท่านให้คงเป็นตั๋วเงินที่ใช้ได้ และพึงใช้เงินกันเสมือนดังว่าวันที่ได้จดลงนั้นเป็นวันที่ถูกต้องแท้จริง"}},{"id":"TH-H004-A933","no":933,"noLabel":{"th":"มาตรา 933"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๓ ถ้าการรับรองมิได้ลงวัน ท่านให้ถือเอาวันสุดท้ายแห่งระยะเวลาอันกำหนดไว้เพื่อรับรองนั้นเป็นวันรับรอง"}},{"id":"TH-H004-A934","no":934,"noLabel":{"th":"มาตรา 934"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๔ ถ้าผู้จ่ายเขียนคำรับรองลงในตั๋วแลกเงินแล้ว แต่หากกลับขีดฆ่าเสียก่อนตั๋วเงินนั้นหลุดพ้นไปจากมือตนไซร้ ท่านให้ถือเป็นอันว่าได้บอกปัดไม่รับรอง แต่ถ้าผู้จ่ายได้แจ้งความเป็นหนังสือไปยังผู้ทรง หรือคู่สัญญาฝ่ายอื่นซึ่งได้ลงนามในตั๋วเงินว่าตนรับรองตั๋วเงินนั้นก่อนแล้ว จึงมาขีดฆ่าคำรับรองต่อภายหลังไซร้ ท่านว่าผู้จ่ายก็คงต้องผูกพันอยู่ตามเนื้อความที่ตนได้เขียนรับรองนั้นเอง"}},{"id":"TH-H004-A935","no":935,"noLabel":{"th":"มาตรา 935"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๕ อันการรับรองนั้นย่อมมีได้สองสถาน คือ รับรองตลอดไป หรือรับรองเบี่ยงบ่าย การรับรองตลอดไป คือยอมตกลงโดยไม่แก้แย้งคำสั่งของผู้สั่งจ่ายแต่อย่างหนึ่งอย่างใดเลย ส่วนการรับรองเบี่ยงบ่ายนั้น กล่าวเป็นเนื้อความทำผลแห่งตั๋วเงินให้แผกไปจากที่เขียนสั่งไว้ กล่าวโดยเฉพาะก็คือว่า ถ้าคำรับรองมีเงื่อนไขก็ดี หรือรับรองแต่เพียงบางส่วนก็ดี ท่านว่าเป็นรับรองเบี่ยงบ่าย"}},{"id":"TH-H004-A936","no":936,"noLabel":{"th":"มาตรา 936"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๖ คำรับรองเบี่ยงบ่ายนั้น ผู้ทรงตั๋วแลกเงินจะบอกปัดเสียก็ได้ และถ้าไม่ได้คำรับรองอันไม่เบี่ยงบ่าย จะถือเอาว่าตั๋วเงินนั้นเป็นอันขาดความเชื่อถือรับรองก็ได้ ถ้าผู้ทรงรับเอาคำรับรองเบี่ยงบ่าย และผู้สั่งจ่ายหรือผู้สลักหลังมิได้ให้อำนาจแก่ผู้ทรงโดยแสดงออกชัดหรือโดยปริยายให้รับเอาคำรับรองเบี่ยงบ่ายเช่นนั้นก็ดี หรือไม่ยินยอมด้วยในภายหลังก็ดี ท่านว่าผู้สั่งจ่ายหรือผู้สลักหลังนั้น ๆ ย่อมหลุดพ้นจากความรับผิดตามตั๋วเงินนั้น แต่บทบัญญัติ ทั้งนี้ ท่านมิให้ใช้ไปถึงการรับรองแต่บางส่วนซึ่งได้บอกกล่าวก่อนแล้วโดยชอบ ถ้าผู้สั่งจ่ายหรือผู้สลักหลังตั๋วเงินรับคำบอกกล่าวการรับรองเบี่ยงบ่ายแล้วไม่โต้แย้งไปยังผู้ทรงภายในเวลาอันสมควร ท่านให้ถือว่าผู้สั่งจ่ายหรือผู้สลักหลังนั้นเป็นอันได้ยินยอมด้วยกับการนั้นแล้ว"}},{"id":"TH-H004-A937","no":937,"noLabel":{"th":"มาตรา 937"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๙๓๗ ผู้จ่ายได้ทำการรับรองตั๋วแลกเงินแล้วย่อมต้องผูกพันในอันจะจ่ายเงินจำนวนที่รับรองตามเนื้อความแห่งคำรับรองของตน"}},{"id":"TH-H004-A938","no":938,"noLabel":{"th":"มาตรา 938"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๙๓๘ ตั๋วแลกเงินจะมีผู้ค้ำประกันรับประกันการใช้เงินทั้งจำนวนหรือแต่บางส่วนก็ได้ ซึ่งท่านเรียกว่า “อาวัล” อันอาวัลนั้นบุคคลภายนอกคนใดคนหนึ่งจะเป็นผู้รับ หรือแม้คู่สัญญาแห่งตั๋วเงินนั้นฝ่ายใดฝ่ายหนึ่งจะเป็นผู้รับก็ได้"}},{"id":"TH-H004-A939","no":939,"noLabel":{"th":"มาตรา 939"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๙๓๙ อันการรับอาวัลย่อมทำให้กันด้วยเขียนลงในตั๋วเงินนั้นเอง หรือที่ใบประจำต่อ ในการนี้พึงใช้ถ้อยคำสำนวนว่า “ใช้ได้เป็นอาวัล” หรือสำนวนอื่นใดทำนองเดียวกันนั้น และลงลายมือชื่อผู้รับอาวัล อนึ่ง เพียงแต่ลงลายมือชื่อของผู้รับอาวัลในด้านหน้าแห่งตั๋วเงิน ท่านก็จัดว่าเป็นคำรับอาวัลแล้ว เว้นแต่ในกรณีที่เป็นลายมือชื่อของผู้จ่ายหรือผู้สั่งจ่าย ในคำรับอาวัลต้องระบุว่ารับประกันผู้ใด หากมิได้ระบุ ท่านให้ถือว่ารับประกันผู้สั่งจ่าย"}},{"id":"TH-H004-A940","no":940,"noLabel":{"th":"มาตรา 940"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๙๔๐ ผู้รับอาวัลย่อมต้องผูกพันเป็นอย่างเดียวกันกับบุคคลซึ่งตนประกัน แม้ถึงว่าความรับผิดใช้เงินอันผู้รับอาวัลได้ประกันอยู่นั้น จะตกเป็นใช้ไม่ได้ด้วยเหตุใด ๆ นอกจากเพราะทำผิดแบบระเบียบ ท่านว่าข้อที่สัญญารับอาวัลนั้นก็ยังคงสมบูรณ์ เมื่อผู้รับอาวัลได้ใช้เงินไปตามตั๋วแลกเงินแล้ว ย่อมได้สิทธิในอันจะไล่เบี้ยเอาแก่บุคคลซึ่งตนได้ประกันไว้ กับทั้งบุคคลทั้งหลายผู้รับผิดแทนตัวผู้นั้น"}},{"id":"TH-H004-A941","no":941,"noLabel":{"th":"มาตรา 941"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๑ อันตั๋วแลกเงินนั้น ย่อมจะพึงใช้เงินในวันถึงกำหนด และถึงกำหนดวันใด ผู้ทรงต้องนำตั๋วเงินไปยื่นเพื่อให้ใช้เงินในวันนั้น"}},{"id":"TH-H004-A942","no":942,"noLabel":{"th":"มาตรา 942"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๒ อันจะบังคับให้ผู้ทรงตั๋วแลกเงินรับเงินใช้ก่อนตั๋วเงินถึงกำหนดนั้น ท่านว่าหาอาจจะทำได้ไม่ อนึ่ง ผู้จ่ายคนใดใช้เงินไปแต่ก่อนเวลาตั๋วเงินถึงกำหนด ท่านว่าย่อมทำเช่นนั้นด้วยเสี่ยงเคราะห์ของตนเอง"}},{"id":"TH-H004-A943","no":943,"noLabel":{"th":"มาตรา 943"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๓ อันการถึงกำหนดแห่งตั๋วแลกเงินซึ่งสั่งให้ใช้เงินเมื่อสิ้นระยะเวลาอันใดอันหนึ่งนับแต่วันได้เห็นนั้น ท่านให้กำหนดนับแต่วันรับรอง หรือวันคัดค้าน ถ้าไม่มีคำคัดค้าน และคำรับรองมิได้ลงวัน ท่านให้ถือว่าผู้รับรองได้ให้คำรับรองนั้นในวันท้ายแห่งกำหนดเวลาซึ่งจำกัดไว้ตามกฎหมาย หรือตามสัญญาเพื่อการยื่นตั๋วนั้น"}},{"id":"TH-H004-A944","no":944,"noLabel":{"th":"มาตรา 944"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๔ อันตั๋วแลกเงินซึ่งให้ใช้เงินเมื่อได้เห็นนั้น ท่านว่าย่อมจะพึงใช้เงินในวันเมื่อยื่นตั๋ว ทั้งนี้ ต้องยื่นให้ใช้เงินภายในกำหนดเวลา ซึ่งบังคับไว้เพื่อการยื่นให้รับรองตั๋วเงินชนิดให้ใช้เงินในเวลาใดเวลาหนึ่งภายหลังได้เห็นนั้น"}},{"id":"TH-H004-A945","no":945,"noLabel":{"th":"มาตรา 945"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๕ การใช้เงินจะเรียกเอาได้ต่อเมื่อได้เวนตั๋วแลกเงินให้ ผู้ใช้เงินจะให้ผู้ทรงลงลายมือชื่อรับเงินในตั๋วเงินนั้นก็ได้"}},{"id":"TH-H004-A946","no":946,"noLabel":{"th":"มาตรา 946"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๖ อันตั๋วแลกเงินนั้น ถ้าเขาจะใช้เงินให้แต่เพียงบางส่วน ท่านว่าผู้ทรงจะบอกปัดเสียไม่ยอมรับเอาก็ได้ ถ้าและรับเอาเงินที่เขาใช้แต่เพียงบางส่วน ผู้ทรงต้องบันทึกข้อความนั้นลงไว้ในตั๋วเงิน และส่งมอบใบรับให้แก่ผู้ใช้เงิน"}},{"id":"TH-H004-A947","no":947,"noLabel":{"th":"มาตรา 947"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๗ ถ้าตั๋วแลกเงินมิได้ยื่นเพื่อให้ใช้เงินในวันถึงกำหนดไซร้ ท่านว่าผู้รับรองจะเปลื้องตนให้พ้นจากความรับผิดโดยวางจำนวนเงินที่ค้างชำระตามตั๋วนั้นไว้ก็ได้"}},{"id":"TH-H004-A948","no":948,"noLabel":{"th":"มาตรา 948"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๘ ถ้าผู้ทรงตั๋วแลกเงินยอมผ่อนเวลาให้แก่ผู้จ่ายไซร้ ท่านว่าผู้ทรงสิ้นสิทธิที่จะไล่เบี้ยเอาแก่ผู้เป็นคู่สัญญาคนก่อน ๆ ซึ่งมิได้ตกลงในการผ่อนเวลานั้น"}},{"id":"TH-H004-A949","no":949,"noLabel":{"th":"มาตรา 949"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๙๔๙ ภายในบังคับแห่งบทบัญญัติมาตรา ๑๐๐๙ บุคคลผู้ใช้เงินในเวลาถึงกำหนดย่อมเป็นอันหลุดพ้นจากความรับผิด เว้นแต่ตนจะได้ทำการฉ้อฉลหรือมีความประมาทเลินเล่ออย่างร้ายแรง อนึ่ง บุคคลซึ่งกล่าวนี้จำต้องพิสูจน์ให้เห็นจริงว่าได้มีการสลักหลังติดต่อกันเรียบร้อยไม่ขาดสาย แต่ไม่จำต้องพิสูจน์ลายมือชื่อของเหล่าผู้สลักหลัง"}},{"id":"TH-H004-A950","no":950,"noLabel":{"th":"มาตรา 950"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๐ ผู้สั่งจ่ายหรือผู้สลักหลังจะระบุบุคคลผู้หนึ่งผู้ใดไว้ก็ได้ว่าเป็นผู้จะรับรอง หรือใช้เงินยามประสงค์ ณ สถานที่ใช้เงิน ภายในเงื่อนบังคับดังจะกล่าวต่อไปข้างหน้า บุคคลผู้หนึ่งผู้ใดจะรับรองหรือใช้เงินตามตั๋วแลกเงินในฐานเป็นผู้สอดเข้าแก้หน้าบุคคลใดผู้ลงลายมือชื่อในตั๋วนั้นก็ได้ ผู้สอดเข้าแก้หน้านั้นจะเป็นบุคคลภายนอกก็ได้ แม้จะเป็นผู้จ่ายหรือบุคคลซึ่งต้องรับผิดโดยตั๋วเงินนั้นอยู่แล้วก็ได้ ห้ามแต่ผู้รับรองเท่านั้น ผู้สอดเข้าแก้หน้าจำต้องให้คำบอกกล่าวโดยไม่ชักช้า เพื่อให้คู่สัญญาฝ่ายซึ่งตนเข้าแก้หน้านั้นทราบการที่ตนเข้าแก้หน้า"}},{"id":"TH-H004-A951","no":951,"noLabel":{"th":"มาตรา 951"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๑ การรับรองด้วยสอดเข้าแก้หน้า ย่อมมีได้ในบรรดากรณีซึ่งผู้ทรงมีสิทธิไล่เบี้ยได้ก่อนถึงกำหนดตามตั๋วเงินอันเป็นตั๋วสามารถจะรับรองได้ การรับรองด้วยสอดเข้าแก้หน้านั้น ผู้ทรงจะบอกปัดเสียก็ได้ แม้ถึงว่าบุคคลผู้ซึ่งบ่งไว้ว่าจะเป็นผู้รับรอง หรือใช้เงินยามประสงค์นั้นจะเป็นผู้เสนอเข้ารับรองก็บอกปัดได้ ถ้าผู้ทรงยอมให้เขารับรองแล้ว ผู้ทรงย่อมเสียสิทธิไล่เบี้ยก่อนถึงกำหนดเอาแก่คู่สัญญาทั้งหลายซึ่งต้องรับผิดต่อตน"}},{"id":"TH-H004-A952","no":952,"noLabel":{"th":"มาตรา 952"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๒ อันการรับรองด้วยสอดเข้าแก้หน้านั้น ย่อมทำด้วยเขียนระบุความลงบนตั๋วแลกเงิน และลงลายมือชื่อของผู้สอดเข้าแก้หน้าเป็นสำคัญ อนึ่ง ต้องระบุลงไว้ว่าการรับรองนั้นทำให้เพื่อผู้ใด ถ้ามิได้ระบุไว้เช่นนั้น ท่านให้ถือว่าทำให้เพื่อผู้สั่งจ่าย"}},{"id":"TH-H004-A953","no":953,"noLabel":{"th":"มาตรา 953"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๓ ผู้รับรองด้วยสอดเข้าแก้หน้าย่อมต้องรับผิดต่อผู้ทรงตั๋วเงินนั้น และรับผิดต่อผู้สลักหลังทั้งหลายภายหลังคู่สัญญาฝ่ายซึ่งตนเข้าแก้หน้าอย่างเดียวกันกับที่คู่สัญญาฝ่ายนั้นต้องรับผิดอยู่เอง"}},{"id":"TH-H004-A954","no":954,"noLabel":{"th":"มาตรา 954"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๔ อันการใช้เงินเพื่อแก้หน้าย่อมมีได้ในบรรดากรณีซึ่งผู้ทรงมีสิทธิไล่เบี้ยเมื่อตั๋วเงินถึงกำหนดหรือก่อนถึงกำหนด การใช้เงินนั้น ท่านว่าอย่างช้าที่สุดต้องทำในวันรุ่งขึ้น แต่วันท้ายแห่งกำหนดเวลาซึ่งจำกัดอนุญาตไว้ให้ทำคำคัดค้านการไม่ใช้เงิน"}},{"id":"TH-H004-A955","no":955,"noLabel":{"th":"มาตรา 955"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๕ ถ้าตั๋วแลกเงินได้รับรองเพื่อแก้หน้าแล้วก็ดี หรือได้มีตัวบุคคลระบุว่าเป็นผู้จะใช้เงินยามประสงค์แล้วก็ดี ผู้ทรงต้องยื่นตั๋วเงินนั้นต่อบุคคลนั้น ๆ ณ สถานที่ใช้เงิน และถ้าจำเป็นก็ต้องจัดการทำคำคัดค้านการไม่ใช้เงินอย่างช้าที่สุดในวันรุ่งขึ้นแต่วันท้ายแห่งกำหนดเวลาอันจำกัดไว้เพื่อทำคำคัดค้าน ถ้าไม่คัดค้านภายในกำหนดเวลานั้น ท่านว่าคู่สัญญาฝ่ายที่ได้ระบุตัวผู้ใช้เงินยามประสงค์ หรือคู่สัญญาฝ่ายซึ่งได้มีผู้รับรองตั๋วเงินให้แล้วนั้น กับทั้งบรรดาผู้สลักหลังในภายหลังย่อมเป็นอันหลุดพ้นจากความรับผิด"}},{"id":"TH-H004-A956","no":956,"noLabel":{"th":"มาตรา 956"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๖ การใช้เงินเพื่อแก้หน้านั้น ใช้เพื่อคู่สัญญาฝ่ายใดต้องใช้จงเต็มจำนวนอันคู่สัญญาฝ่ายนั้นจะต้องใช้ เว้นแต่ค่าชักส่วนลดดังบัญญัติไว้ในมาตรา ๙๖๘ (๔) ผู้ทรงคนใดบอกปัดไม่ยอมรับเงินอันเขาใช้ให้ ท่านว่าผู้ทรงคนนั้นย่อมเสียสิทธิในอันจะไล่เบี้ยเอาแก่บุคคลทั้งหลายเหล่านั้นซึ่งพอที่จะได้หลุดพ้นจากความรับผิดเพราะการใช้เงินนั้น"}},{"id":"TH-H004-A957","no":957,"noLabel":{"th":"มาตรา 957"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๗ การใช้เงินเพื่อแก้หน้าต้องทำให้เป็นหลักฐานด้วยใบรับเขียนลงในตั๋วแลกเงิน ระบุความว่าได้ใช้เงินเพื่อบุคคลผู้ใด ถ้ามิได้ระบุตัวไว้ดังนั้น ท่านให้ถือว่าการใช้เงินนั้นได้ทำไปเพื่อผู้สั่งจ่าย ตั๋วแลกเงินกับทั้งคำคัดค้านหากว่าได้ทำคัดค้าน ต้องส่งให้แก่บุคคลผู้ใช้เงินเพื่อแก้หน้า"}},{"id":"TH-H004-A958","no":958,"noLabel":{"th":"มาตรา 958"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๙๕๘ บุคคลผู้ใช้เงินเพื่อแก้หน้าย่อมรับช่วงสิทธิทั้งปวงของผู้ทรงอันมีต่อคู่สัญญาฝ่ายซึ่งตนได้ใช้เงินแทนไป และต่อคู่สัญญาทั้งหลายผู้ต้องรับผิดต่อคู่สัญญาฝ่ายนั้น แต่หาอาจจะสลักหลังตั๋วแลกเงินนั้นอีกต่อไปได้ไม่ อนึ่ง บรรดาผู้ซึ่งสลักหลังภายหลังคู่สัญญาฝ่ายซึ่งเขาได้ใช้เงินแทนไปนั้น ย่อมหลุดพ้นจากความรับผิด ในกรณีแข่งกันเข้าใช้เงินเพื่อแก้หน้า ท่านว่าการใช้เงินรายใดจะให้ผลปลดหนี้มากรายที่สุด พึงนิยมเอารายนั้นเป็นดียิ่ง ถ้าไม่ดำเนินตามวิธีดังกล่าวนี้ ท่านว่าผู้ใช้เงินทั้งที่รู้เช่นนั้นย่อมเสียสิทธิในอันจะไล่เบี้ยเอาแก่บุคคลทั้งหลายซึ่งพอที่จะได้หลุดพ้นจากความรับผิด"}},{"id":"TH-H004-A959","no":959,"noLabel":{"th":"มาตรา 959"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๕๙ ผู้ทรงตั๋วแลกเงินจะใช้สิทธิไล่เบี้ยเอาแก่บรรดาผู้สลักหลัง ผู้สั่งจ่าย และบุคคลอื่น ๆ ซึ่งต้องรับผิดตามตั๋วเงินนั้นก็ได้ คือ ก) ไล่เบี้ยได้เมื่อตั๋วเงินถึงกำหนดในกรณีไม่ใช้เงิน ข) ไล่เบี้ยได้แม้ทั้งตั๋วเงินยังไม่ถึงกำหนดในกรณีดังจะกล่าวต่อไปนี้ คือ (๑) ถ้าเขาบอกปัดไม่รับรองตั๋วเงิน (๒) ถ้าผู้จ่ายหากจะได้รับรองหรือไม่ก็ตาม ตกเป็นคนล้มละลาย หรือได้งดเว้นการใช้หนี้ แม้การงดเว้นใช้หนี้นั้น จะมิได้มีคำพิพากษาเป็นหลักฐานก็ตาม หรือถ้าผู้จ่ายถูกยึดทรัพย์และการยึดทรัพย์นั้นไร้ผล (๓) ถ้าผู้สั่งจ่ายตั๋วเงินชนิดไม่จำเป็นต้องให้ผู้ใดรับรองนั้นตกเป็นคนล้มละลาย"}},{"id":"TH-H004-A960","no":960,"noLabel":{"th":"มาตรา 960"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๐ การที่ตั๋วแลกเงินขาดรับรองหรือขาดใช้เงินนั้น ต้องทำให้เป็นหลักฐานตามแบบระเบียบด้วยเอกสารฉบับหนึ่ง เรียกว่าคำคัดค้าน คำคัดค้านการไม่ใช้เงินต้องทำในวันซึ่งจะพึงใช้เงินตามตั๋วนั้น หรือวันใดวันหนึ่งภายในสามวันต่อแต่นั้นไป คำคัดค้านการไม่รับรองต้องทำภายในจำกัดเวลาซึ่งกำหนดไว้เพื่อการยื่นตั๋วเงินให้เขารับรอง หรือภายในสามวันต่อแต่นั้นไป เมื่อมีคำคัดค้านการไม่รับรองขึ้นแล้วก็เป็นอันไม่ต้องยื่นเพื่อใช้เงิน และไม่ต้องทำคำคัดค้านการไม่ใช้เงิน ในกรณีทั้งหลายซึ่งกล่าวไว้ในมาตรา ๙๕๙ ข) (๒) นั้น ท่านว่าผู้ทรงยังหาอาจจะใช้สิทธิไล่เบี้ยได้ไม่ จนกว่าจะได้ยื่นตั๋วเงินให้ผู้จ่ายใช้เงิน และได้ทำคำคัดค้านขึ้นแล้ว ในกรณีทั้งหลายดังกล่าวไว้ในมาตรา ๙๕๙ ข) (๓) นั้น ท่านว่าถ้าเอาคำพิพากษาซึ่งสั่งให้ผู้สั่งจ่ายเป็นคนล้มละลายออกแสดง ก็เป็นการเพียงพอที่จะทำให้ผู้ทรงสามารถใช้สิทธิไล่เบี้ยได้"}},{"id":"TH-H004-A961","no":961,"noLabel":{"th":"มาตรา 961"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๑ คำคัดค้านนั้นให้นายอำเภอ หรือผู้ทำการแทนนายอำเภอ หรือทนายความผู้ได้รับอนุญาตเพื่อการนี้เป็นผู้ทำ รัฐมนตรีกระทรวงยุติธรรมมีอำนาจออกกฎข้อบังคับเพื่อปฏิบัติการให้เป็นไปตามบทบัญญัติแห่งประมวลกฎหมายนี้ อันว่าด้วยการออกใบอนุญาตและการทำคำคัดค้าน รวมทั้งกำหนดอัตราค่าฤชาธรรมเนียมอันเกี่ยวกับการนั้น"}},{"id":"TH-H004-A962","no":962,"noLabel":{"th":"มาตรา 962"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๒ ในคำคัดค้านนั้นนอกจากชื่อ ตำแหน่ง และลายมือชื่อของผู้ทำ ต้องมีสำเนาตั๋วเงินกับรายการสลักหลังทั้งหมดตรงถ้อยตรงคำกับระบุความดังจะกล่าวต่อไปนี้ คือ (๑) ชื่อ หรือยี่ห้อของบุคคลผู้คัดค้านและผู้ถูกคัดค้าน (๒) มูล หรือเหตุที่ต้องทำคำคัดค้านตั๋วเงิน การทวงถามและคำตอบ ถ้ามี หรือข้อที่ว่าหาตัวผู้จ่ายหรือผู้รับรองไม่พบ (๓) ถ้ามีการรับรอง หรือใช้เงินเพื่อแก้หน้า ให้แถลงลักษณะแห่งการเข้าแก้หน้าทั้งชื่อหรือยี่ห้อของผู้รับรองหรือผู้ใช้เงินเพื่อแก้หน้าและชื่อบุคคลซึ่งเขาเข้าแก้หน้านั้นด้วย (๔) สถานที่และวันทำคำคัดค้าน ให้ผู้ทำคำคัดค้านส่งมอบคำคัดค้านแก่ผู้ร้องขอให้ทำ และให้ผู้ทำคำคัดค้านรีบส่งคำบอกกล่าวการคัดค้านนั้นไปยังผู้ถูกคัดค้าน ถ้าทราบภูมิลำเนาก็ให้ส่งโดยจดหมายลงทะเบียนไปรษณีย์ หรือส่งมอบไว้ ณ ภูมิลำเนาของผู้นั้นก็ได้ ถ้าไม่ทราบภูมิลำเนาก็ให้ปิดสำเนาคำคัดค้านไว้ยังที่ซึ่งเห็นได้ง่าย ณ ที่ว่าการอำเภอประจำท้องที่อันผู้ถูกคัดค้านมีถิ่นที่อยู่ครั้งหลังที่สุด"}},{"id":"TH-H004-A963","no":963,"noLabel":{"th":"มาตรา 963"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๓ ผู้ทรงต้องให้คำบอกกล่าวการที่เขาไม่รับรองตั๋วแลกเงิน หรือไม่ใช้เงินนั้นไปยังผู้สลักหลังถัดตนขึ้นไปกับทั้งผู้สั่งจ่ายด้วยภายในเวลาสี่วันต่อจากวันคัดค้าน หรือต่อจากวันยื่นตั๋วในกรณีที่มีข้อกำหนดว่า “ไม่จำต้องมีคำคัดค้าน” ผู้สลักหลังทุก ๆ คนต้องให้คำบอกกล่าวไปยังผู้สลักหลังถัดตนขึ้นไปภายในสองวัน ให้ทราบคำบอกกล่าวอันตนได้รับ จดแจ้งให้ทราบชื่อและสำนักของผู้ที่ได้ให้คำบอกกล่าวมาก่อน ๆ นั้นด้วย ทำเช่นนี้ติดต่อกันไปโดยลำดับจนกระทั่งถึงผู้สั่งจ่าย อนึ่ง จำกัดเวลาซึ่งกล่าวมานั้น ท่านนับแต่เมื่อคนหนึ่ง ๆ ได้รับคำบอกกล่าวแต่คนก่อน ถ้าผู้สลักหลังคนหนึ่งคนใดมิได้ระบุสำนักของตนไว้ก็ดี หรือได้ระบุแต่อ่านไม่ได้ความก็ดี ท่านว่าสุดแต่คำบอกกล่าวได้ส่งไปยังผู้สลักหลังคนก่อนก็เป็นอันพอแล้ว บุคคลผู้จะต้องให้คำบอกกล่าว จะทำคำบอกกล่าวเป็นรูปอย่างใดก็ได้ทั้งสิ้น แม้เพียงแต่ด้วยส่งตั๋วแลกเงินคืนก็ใช้ได้ อนึ่ง ต้องพิสูจน์ได้ว่าได้ส่งคำบอกกล่าวภายในเวลากำหนด ถ้าส่งคำบอกกล่าวเป็นหนังสือจดทะเบียนไปรษณีย์ หากว่าหนังสือนั้นได้ส่งไปรษณีย์ภายในเวลากำหนดดังกล่าวมานั้นไซร้ ท่านให้ถือว่าคำบอกกล่าวเป็นอันได้ส่งภายในจำกัดเวลาบังคับแล้ว บุคคลซึ่งมิได้ให้คำบอกกล่าวภายในจำกัดเวลาดังได้ว่ามานั้นหาเสียสิทธิไล่เบี้ยไม่ แต่จะต้องรับผิดเพื่อความเสียหายอย่างใด ๆ อันเกิดแต่ความประมาทเลินเล่อของตน แต่ท่านมิให้คิดค่าสินไหมทดแทนเกินกว่าจำนวนในตั๋วแลกเงิน"}},{"id":"TH-H004-A964","no":964,"noLabel":{"th":"มาตรา 964"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๔ ด้วยข้อกำหนดเขียนลงไว้ว่า “ไม่จำเป็นต้องมีคำคัดค้าน” ก็ดี “ไม่มีคัดค้าน” ก็ดี หรือสำนวนอื่นใดทำนองนั้นก็ดี ผู้สั่งจ่ายหรือผู้สลักหลังจะยอมปลดเปลื้องผู้ทรงจากการทำคำคัดค้านการไม่รับรองหรือการไม่ใช้เงินก็ได้ เพื่อตนจะได้ใช้สิทธิไล่เบี้ย ข้อกำหนดอันนี้ ย่อมไม่ปลดผู้ทรงให้พ้นจากหน้าที่นำตั๋วเงินยื่นภายในเวลากำหนด หรือจากหน้าที่ให้คำบอกกล่าวตั๋วเงินขาดความเชื่อถือแก่ผู้สลักหลังคนก่อนหรือผู้สั่งจ่าย อนึ่ง หน้าที่นำสืบว่าไม่ปฏิบัติให้เป็นไปตามกำหนดเวลาจำกัดนั้น ย่อมตกอยู่แก่บุคคลผู้แสวงจะใช้ความข้อนั้นเป็นข้อต่อสู้ผู้ทรงตั๋วแลกเงิน ข้อกำหนดอันนี้ ถ้าผู้สั่งจ่ายเป็นผู้เขียนลงไปแล้ว ย่อมเป็นผลตลอดถึงคู่สัญญาทั้งปวงบรรดาที่ได้ลงลายมือชื่อในตั๋วเงินนั้น ถ้าและทั้งมีข้อกำหนดดังนี้แล้ว ผู้ทรงยังขืนทำคำคัดค้านไซร้ ท่านว่าผู้ทรงต้องเป็นผู้ออกค่าใช้จ่ายเพื่อการนั้น หากว่าข้อกำหนดนั้นผู้สลักหลังเป็นผู้เขียนลง และถ้ามีคัดค้านทำขึ้นไซร้ ท่านว่าค่าใช้จ่ายในการคัดค้านนั้น อาจจะเรียกเอาใช้ได้จากคู่สัญญาอื่น ๆ บรรดาที่ได้ลงลายมือชื่อในตั๋วเงินนั้น"}},{"id":"TH-H004-A965","no":965,"noLabel":{"th":"มาตรา 965"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๕ ในกรณีตั๋วเงินภายในประเทศ ถ้าผู้จ่ายบันทึกลงไว้ในตั๋วแลกเงินเป็นข้อความบอกปัดไม่รับรองหรือไม่ยอมใช้เงิน ทั้งลงวันที่บอกปัดลงลายมือชื่อไว้ด้วยแล้ว ท่านว่าคำคัดค้านนั้นก็เป็นอันไม่จำเป็นต้องทำ และผู้ทรงต้องส่งคำบอกกล่าวขาดความเชื่อถือไปยังบุคคลซึ่งตนจำนงจะไล่เบี้ยภายในสี่วันต่อจากวันเขาบอกปัดไม่รับรองนั้น"}},{"id":"TH-H004-A966","no":966,"noLabel":{"th":"มาตรา 966"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๖ คำบอกกล่าวขาดความเชื่อถือในกรณีไม่รับรองหรือไม่ใช้เงินนั้น ต้องมีรายการคือ วันที่ลงในตั๋วแลกเงิน ชื่อหรือยี่ห้อของผู้สั่งจ่ายและของผู้จ่าย จำนวนเงินในตั๋วเงิน วันถึงกำหนดใช้เงิน ชื่อหรือยี่ห้อและสำนักของผู้ทรงตั๋วเงิน วันที่คัดค้านหรือวันที่บอกปัดไม่รับรองหรือไม่ใช้เงิน กับข้อความว่าเขาไม่รับรองหรือไม่ใช้เงินตามตั๋วเงินนั้น"}},{"id":"TH-H004-A967","no":967,"noLabel":{"th":"มาตรา 967"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๗ ในเรื่องตั๋วแลกเงินนั้น บรรดาบุคคลผู้สั่งจ่ายก็ดี รับรองก็ดี สลักหลังก็ดี หรือรับประกันด้วยอาวัลก็ดี ย่อมต้องร่วมกันรับผิดต่อผู้ทรง ผู้ทรงย่อมมีสิทธิว่ากล่าวเอาความแก่บรรดาบุคคลเหล่านี้เรียงตัวหรือรวมกันก็ได้ โดยมิพักต้องดำเนินตามลำดับที่คนเหล่านั้นมาต้องผูกพัน สิทธิเช่นเดียวกันนี้ ย่อมมีแก่บุคคลทุกคนซึ่งได้ลงลายมือชื่อในตั๋วเงินและเข้าถือเอาตั๋วเงินนั้น ในการที่จะใช้บังคับเอาแก่ผู้ที่มีความผูกพันอยู่แล้วก่อนตน การว่ากล่าวเอาความแก่คู่สัญญาคนหนึ่ง ซึ่งต้องรับผิดย่อมไม่ตัดหนทางที่จะว่ากล่าวเอาความแก่คู่สัญญาคนอื่น ๆ แม้ทั้งจะเป็นฝ่ายอยู่ในลำดับภายหลังบุคคลที่ได้ว่ากล่าวเอาความมาก่อน"}},{"id":"TH-H004-A968","no":968,"noLabel":{"th":"มาตรา 968"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๘ ผู้ทรงจะเรียกร้องเอาเงินใช้จากบุคคลซึ่งตนใช้สิทธิไล่เบี้ยนั้นก็ได้ คือ (๑) จำนวนเงินในตั๋วแลกเงินซึ่งเขาไม่รับรองหรือไม่ใช้กับทั้งดอกเบี้ยด้วย หากว่ามีข้อกำหนดไว้ว่าให้คิดดอกเบี้ย (๒) ดอกเบี้ยอัตราร้อยละห้าต่อปีนับแต่วันถึงกำหนด (๓) ค่าใช้จ่ายในการคัดค้าน และในการส่งคำบอกกล่าวของผู้ทรงไปยังผู้สลักหลังถัดจากตนขึ้นไปและผู้สั่งจ่าย กับทั้งค่าใช้จ่ายอื่น ๆ (๔) ค่าชักส่วนลดซึ่งถ้าไม่มีข้อตกลงกันไว้ ท่านให้คิดร้อยละ ในต้นเงินอันจะพึงใช้ตามตั๋วเงิน และไม่ว่ากรณีจะเป็นอย่างไร ท่านมิให้คิดสูงกว่าอัตรานี้ ถ้าใช้สิทธิไล่เบี้ยก่อนถึงกำหนด ท่านให้หักลดจำนวนเงินในตั๋วเงินลงให้ร้อยละห้า"}},{"id":"TH-H004-A969","no":969,"noLabel":{"th":"มาตรา 969"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๖๙ คู่สัญญาฝ่ายซึ่งเข้าถือเอาและใช้เงินตามตั๋วแลกเงิน อาจจะเรียกเอาเงินใช้จากคู่สัญญาทั้งหลายซึ่งต้องรับผิดต่อตนได้ คือ (๑) เงินเต็มจำนวนซึ่งตนได้ใช้ไป (๒) ดอกเบี้ยในจำนวนเงินนั้น คิดอัตราร้อยละห้าต่อปีนับแต่วันที่ได้ใช้เงินไป (๓) ค่าใช้จ่ายต่าง ๆ อันตนต้องออกไป (๔) ค่าชักส่วนลดจากต้นเงินจำนวนในตั๋วแลกเงิน ตามที่กำหนดไว้ในมาตรา ๙๖๘ อนุมาตรา (๔)"}},{"id":"TH-H004-A970","no":970,"noLabel":{"th":"มาตรา 970"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๗๐ คู่สัญญาทุกฝ่ายซึ่งต้องรับผิดและถูกไล่เบี้ย หรืออยู่ในฐานจะถูกไล่เบี้ยได้นั้น อาจจะใช้เงินแล้วเรียกให้เขาสละตั๋วเงินให้แก่ตนได้ รวมทั้งคำคัดค้านและบัญชีรับเงินด้วย ผู้สลักหลังทุกคนซึ่งเข้าถือเอาและใช้เงินตามตั๋วแลกเงินแล้ว จะขีดฆ่าคำสลักหลังของตนเองและของเหล่าผู้สลักหลังภายหลังตนนั้นเสียก็ได้"}},{"id":"TH-H004-A971","no":971,"noLabel":{"th":"มาตรา 971"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๗๑ ผู้สั่งจ่ายก็ดี ผู้รับรองก็ดี ผู้สลักหลังคนก่อนก็ดี ซึ่งเขาสลักหลังหรือโอนตั๋วแลกเงินให้อีกทอดหนึ่งนั้น หามีสิทธิจะไล่เบี้ยเอาแก่คู่สัญญาฝ่ายซึ่งตนย่อมต้องรับผิดต่อเขาอยู่ก่อนแล้วตามตั๋วเงินนั้นได้ไม่"}},{"id":"TH-H004-A972","no":972,"noLabel":{"th":"มาตรา 972"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๗๒ ในกรณีใช้สิทธิไล่เบี้ยภายหลังการรับรองแต่บางส่วน ท่านว่าคู่สัญญาฝ่ายซึ่งใช้เงินอันเป็นจำนวนเขาไม่รับรองนั้น อาจจะเรียกให้จดระบุความที่ใช้เงินนี้ลงไว้ในตั๋วเงิน และเรียกให้ทำใบรับให้แก่ตนได้ อนึ่ง ผู้ทรงตั๋วเงินต้องให้สำเนาตั๋วเงินอันรับรองว่าถูกต้องแก่คู่สัญญาฝ่ายนั้นพร้อมทั้งคำคัดค้านด้วย เพื่อให้เขาสามารถใช้สิทธิไล่เบี้ยในภายหลังได้สืบไป"}},{"id":"TH-H004-A973","no":973,"noLabel":{"th":"มาตรา 973"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๗๓ เมื่อกำหนดเวลาจำกัดซึ่งจะกล่าวต่อไปนี้ได้ล่วงพ้นไปแล้ว คือ (๑) กำหนดเวลาสำหรับยื่นตั๋วแลกเงินชนิดให้ใช้เงินเมื่อได้เห็น หรือในระยะเวลาอย่างใดอย่างหนึ่งภายหลังได้เห็น (๒) กำหนดเวลาสำหรับทำคำคัดค้านการไม่รับรองหรือการไม่ใช้เงิน (๓) กำหนดเวลาสำหรับยื่นตั๋วเพื่อให้ใช้เงิน ในกรณีที่มีข้อกำหนดว่า “ไม่จำต้องมีคำคัดค้าน” ท่านว่าผู้ทรงย่อมสิ้นสิทธิที่จะไล่เบี้ยเอาแก่เหล่าผู้สลักหลัง ผู้สั่งจ่าย และคู่สัญญาอื่น ๆ ผู้ต้องรับผิด เว้นแต่ผู้รับรอง อนึ่ง ถ้าไม่ยื่นตั๋วแลกเงินเพื่อให้เขารับรองภายในเวลาจำกัดดังผู้สั่งจ่ายได้กำหนดไว้ ท่านว่าผู้ทรงย่อมเสียสิทธิที่จะไล่เบี้ยทั้งเพื่อการที่เขาไม่ใช้เงิน และเพื่อการที่เขาไม่รับรอง เว้นแต่จะปรากฏจากข้อกำหนดว่า ผู้สั่งจ่ายหมายเพียงแต่จะปลดตนเองให้พ้นจากประกันการรับรอง ถ้าข้อกำหนดจำกัดเวลายื่นตั๋วแลกเงินนั้นมีอยู่ที่คำสลักหลัง ท่านว่าเฉพาะแต่ผู้สลักหลังเท่านั้นจะอาจเอาประโยชน์ในข้อกำหนดนั้นได้"}},{"id":"TH-H004-A974","no":974,"noLabel":{"th":"มาตรา 974"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๙๗๔ การยื่นตั๋วแลกเงินก็ดี การทำคำคัดค้านก็ดี ถ้ามีเหตุจำเป็นอันมิอาจก้าวล่วงเสียได้มาขัดขวางมิให้ทำได้ภายในกำหนดเวลาจำกัดสำหรับการนั้นไซร้ ท่านให้ยืดกำหนดเวลาออกไปอีกได้ เหตุจำเป็นอันมิอาจก้าวล่วงเสียได้ดังว่ามานั้น ผู้ทรงต้องบอกกล่าวแก่ผู้สลักหลังคนถัดตนขึ้นไปโดยไม่ชักช้า และคำบอกกล่าวนั้นต้องเขียนระบุลงในตั๋วเงิน หรือใบประจำต่อ ต้องลงวันและลงลายมือชื่อของผู้ทรง การอื่น ๆ นอกจากที่กล่าวนี้ ท่านให้บังคับตามบทบัญญัติมาตรา ๙๖๓ เมื่อเหตุจำเป็นอันมิอาจก้าวล่วงเสียได้นั้นสุดสิ้นลงแล้ว ผู้ทรงต้องยื่นตั๋วเงินให้เขารับรองหรือใช้เงินโดยไม่ชักช้า และถ้าจำเป็นก็ทำคำคัดค้านขึ้น ถ้าเหตุจำเป็นอันมิอาจก้าวล่วงเสียได้นั้น ยังคงมีอยู่ต่อไปจนเป็นเวลากว่าสามสิบวันภายหลังตั๋วเงินถึงกำหนดไซร้ ท่านว่าจะใช้สิทธิไล่เบี้ยก็ได้ และถ้าเช่นนั้นการยื่นตั๋วเงินก็ดี การทำคำคัดค้านก็ดี เป็นอันไม่จำเป็นต้องทำ ในส่วนตั๋วเงินชนิดที่ให้ใช้เงินเมื่อได้เห็น หรือให้ใช้เงินในระยะเวลาอย่างหนึ่งอย่างใดภายหลังได้เห็นนั้น กำหนดสามสิบวันเช่นว่ามานี้ ท่านให้นับแต่วันที่ผู้ทรงได้ให้คำบอกกล่าวเหตุจำเป็นอันมิอาจก้าวล่วงเสียได้นั้นแก่ผู้สลักหลังถัดตนขึ้นไป และถึงแม้ว่าจะเป็นการก่อนล่วงกำหนดเวลายื่นตั๋วเงิน ก็ให้นับเช่นนั้น"}},{"id":"TH-H004-A975","no":975,"noLabel":{"th":"มาตรา 975"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๗๕ อันตั๋วแลกเงินนั้น นอกจากชนิดที่สั่งจ่ายแก่ผู้ถือแล้ว จะออกไปเป็นคู่ฉีกความต้องกันสองฉบับหรือกว่านั้นก็อาจจะออกได้ คู่ฉีกเหล่านี้ต้องมีหมายลำดับลงไว้ในตัวตราสารนั้นเอง มิฉะนั้นคู่ฉีกแต่ละฉบับย่อมใช้ได้เป็นตั๋วแลกเงินฉบับหนึ่ง ๆ แยกเป็นตั๋วเงินต่างฉบับกัน บุคคลทุกคนซึ่งเป็นผู้ทรงตั๋วเงินอันมิได้ระบุว่าได้ออกเป็นตั๋วเดี่ยวนั้น จะเรียกให้ส่งมอบคู่ฉีกสองฉบับหรือกว่านั้นแก่ตนก็ได้ โดยยอมให้คิดค่าใช้จ่ายเอาแก่ตน ในการนี้ผู้ทรงต้องว่ากล่าวไปยังผู้สลักหลังคนถัดตนขึ้นไป และผู้สลักหลังคนนั้นก็จำต้องช่วยผู้ทรงว่ากล่าวไปยังผู้ที่สลักหลังให้แก่ตนต่อไปอีก สืบเนื่องกันไปเช่นนี้ตลอดสายจนกระทั่งถึงผู้สั่งจ่าย อนึ่ง ผู้สลักหลังทั้งหลายจำต้องเขียนคำสลักหลังของตนเป็นความเดียวกันลงในฉบับคู่ฉีกใหม่แห่งตั๋วสำรับนั้นอีกด้วย"}},{"id":"TH-H004-A976","no":976,"noLabel":{"th":"มาตรา 976"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๗๖ ถ้าผู้ทรงตั๋วแลกเงินสำรับหนึ่งสลักหลังคู่ฉีกสองฉบับหรือกว่านั้นให้แก่บุคคลต่างคนกัน ท่านว่าผู้ทรงย่อมต้องรับผิดตามคู่ฉีกเช่นว่านั้นทุก ๆ ฉบับ และผู้สลักหลังภายหลังผู้ทรงทุก ๆ คนก็ต้องรับผิดตามคู่ฉีกอันตนเองได้สลักหลังลงไปนั้น เสมือนดังว่าคู่ฉีกที่ว่านั้นแยกเป็นตั๋วเงินต่างฉบับกัน"}},{"id":"TH-H004-A977","no":977,"noLabel":{"th":"มาตรา 977"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๗๗ ถ้าคู่ฉีกสองฉบับหรือกว่านั้นในสำรับหนึ่ง ได้เปลี่ยนมือไปยังผู้ทรงโดยชอบด้วยกฎหมายต่างคนกันไซร้ ในระหว่างผู้ทรงเหล่านั้นด้วยกัน คนใดได้ไปเป็นสิทธิก่อน ท่านให้ถือว่าคนนั้นเป็นเจ้าของอันแท้จริงแห่งตั๋วเงินนั้น แต่ความใด ๆ ในบทมาตรานี้ไม่กระทบกระทั่งถึงสิทธิของบุคคลผู้ทำการโดยชอบด้วยกฎหมายรับรองหรือใช้เงินไปตามคู่ฉีกฉบับซึ่งเขายื่นแก่ตนก่อน"}},{"id":"TH-H004-A978","no":978,"noLabel":{"th":"มาตรา 978"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๗๘ คำรับรองนั้นจะเขียนลงในคู่ฉีกฉบับใดก็ได้ และจะต้องเขียนลงในคู่ฉีกแต่เพียงฉบับเดียวเท่านั้น ถ้าผู้จ่ายรับรองลงไปกว่าฉบับหนึ่ง และคู่ฉีกซึ่งรับรองเช่นนั้นตกไปถึงมือผู้ทรงโดยชอบด้วยกฎหมายต่างคนกันไซร้ ท่านว่าผู้จ่ายจะต้องรับผิดตามคู่ฉีกนั้น ๆ ทุกฉบับ เสมือนดังว่าแยกเป็นตั๋วเงินต่างฉบับกัน"}},{"id":"TH-H004-A979","no":979,"noLabel":{"th":"มาตรา 979"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๗๙ ถ้าผู้รับรองตั๋วเงินซึ่งออกเป็นสำรับใช้เงินไปโดยมิได้เรียกให้ส่งมอบคู่ฉีกฉบับซึ่งมีคำรับรองของตนนั้นให้แก่ตนและในเวลาตั๋วเงินถึงกำหนด คู่ฉีกฉบับนั้นไปตกอยู่ในมือผู้ทรงโดยชอบด้วยกฎหมายคนใดคนหนึ่งไซร้ ท่านว่าผู้รับรองจะต้องรับผิดต่อผู้ทรงคู่ฉีกฉบับนั้น"}},{"id":"TH-H004-A980","no":980,"noLabel":{"th":"มาตรา 980"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๘๐ ภายในบังคับแห่งบทบัญญัติทั้งหลายซึ่งกล่าวมาก่อนนั้น ถ้าคู่ฉีกฉบับใดแห่งตั๋วเงินออกเป็นสำรับได้หลุดพ้นไปด้วยการใช้เงินหรือประการอื่นฉบับหนึ่งแล้ว ท่านว่าตั๋วเงินทั้งสำรับก็ย่อมหลุดพ้นไปตามกัน"}},{"id":"TH-H004-A981","no":981,"noLabel":{"th":"มาตรา 981"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๙๘๑ คู่สัญญาซึ่งส่งคู่ฉีกฉบับหนึ่งไปให้เขารับรอง ต้องเขียนแถลงลงในคู่ฉีกฉบับอื่นว่าคู่ฉีกฉบับโน้นอยู่ในมือบุคคลชื่อไร ส่วนบุคคลคนนั้นก็จำต้องสละตั๋วให้แก่ผู้ทรงโดยชอบด้วยกฎหมายแห่งคู่ฉีกฉบับอื่นนั้น ถ้าบุคคลคนนั้นบอกปัดไม่ยอมให้ ท่านว่าผู้ทรงยังจะใช้สิทธิไล่เบี้ยไม่ได้จนกว่าจะได้ทำคัดค้านระบุความดังต่อไปนี้ คือ (๑) ว่าคู่ฉีกฉบับซึ่งได้ส่งไปเพื่อรับรองนั้น เขาไม่สละให้แก่ตนเมื่อทวงถาม (๒) ว่าไม่สามารถจะให้เขารับรองหรือใช้เงินด้วยคู่ฉีกฉบับอื่นได้"}},{"id":"TH-H004-A982","no":982,"noLabel":{"th":"มาตรา 982"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๙๘๒ อันว่าตั๋วสัญญาใช้เงินนั้น คือหนังสือตราสารซึ่งบุคคลหนึ่ง เรียกว่าผู้ออกตั๋ว ให้คำมั่นสัญญาว่าจะใช้เงินจำนวนหนึ่งให้แก่บุคคลอีกคนหนึ่ง หรือใช้ให้ตามคำสั่งของบุคคลอีกคนหนึ่ง เรียกว่าผู้รับเงิน"}},{"id":"TH-H004-A983","no":983,"noLabel":{"th":"มาตรา 983"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๙๘๓ ตั๋วสัญญาใช้เงินนั้น ต้องมีรายการดังจะกล่าวต่อไปนี้ คือ (๑) คำบอกชื่อว่าเป็นตั๋วสัญญาใช้เงิน (๒) คำมั่นสัญญาอันปราศจากเงื่อนไขว่าจะใช้เงินเป็นจำนวนแน่นอน (๓) วันถึงกำหนดใช้เงิน (๔) สถานที่ใช้เงิน (๕) ชื่อ หรือยี่ห้อของผู้รับเงิน (๖) วันและสถานที่ออกตั๋วสัญญาใช้เงิน (๗) ลายมือชื่อผู้ออกตั๋ว"}},{"id":"TH-H004-A984","no":984,"noLabel":{"th":"มาตรา 984"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๙๘๔ ตราสารอันมีรายการขาดตกบกพร่องไปจากที่ท่านระบุบังคับไว้ในมาตราก่อนนี้ ย่อมไม่สมบูรณ์เป็นตั๋วสัญญาใช้เงิน เว้นแต่ในกรณีดังจะกล่าวต่อไปนี้ คือ ตั๋วสัญญาใช้เงินซึ่งไม่ระบุเวลาใช้เงิน ท่านให้ถือว่าพึงใช้เงินเมื่อได้เห็น ถ้าสถานที่ใช้เงินมิได้แถลงไว้ในตั๋วสัญญาใช้เงิน ท่านให้ถือเอาภูมิลำเนาของผู้ออกตราสารนั้นเป็นสถานที่ใช้เงิน ถ้าตั๋วสัญญาใช้เงินไม่ระบุสถานที่ออกตั๋ว ท่านให้ถือว่าตั๋วนั้นได้ออก ณ ภูมิลำเนาของผู้ออกตั๋ว ถ้ามิได้ลงวันออกตั๋ว ท่านว่าผู้ทรงโดยชอบด้วยกฎหมายคนหนึ่งคนใดทำการโดยสุจริตจะจดวันตามที่ถูกต้องแท้จริงลงก็ได้"}},{"id":"TH-H004-A985","no":985,"noLabel":{"th":"มาตรา 985"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๙๘๕ บทบัญญัติทั้งหลายในหมวด ๒ ว่าด้วยตั๋วแลกเงินดังจะกล่าวต่อไปนี้ ท่านให้ยกมาบังคับในเรื่องตั๋วสัญญาใช้เงินเพียงเท่าที่ไม่ขัดกับสภาพแห่งตราสารชนิดนี้คือบทมาตรา ๙๑๑ มาตรา ๙๑๓ มาตรา ๙๑๖ มาตรา ๙๑๗ มาตรา ๙๑๙ มาตรา ๙๒๐ มาตรา ๙๒๒ ถึงมาตรา ๙๒๖ มาตรา ๙๓๘ ถึงมาตรา ๙๔๗ มาตรา ๙๔๙ มาตรา ๙๕๐ มาตรา ๙๕๔ ถึงมาตรา ๙๕๙ มาตรา ๙๖๗ ถึงมาตรา ๙๗๑ ถ้าเป็นตั๋วสัญญาใช้เงินที่ออกมาแต่ต่างประเทศ ท่านให้นำบทบัญญัติต่อไปนี้มาใช้บังคับด้วย คือบทมาตรา ๙๖๐ ถึงมาตรา ๙๖๔ มาตรา ๙๗๓ มาตรา ๙๗๔"}},{"id":"TH-H004-A986","no":986,"noLabel":{"th":"มาตรา 986"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๙๘๖ ผู้ออกตั๋วสัญญาใช้เงินย่อมต้องผูกพันเป็นอย่างเดียวกันกับผู้รับรองตั๋วแลกเงิน ตั๋วสัญญาใช้เงินซึ่งให้ใช้เงินในเวลาใดเวลาหนึ่งภายหลังได้เห็นนั้น ต้องนำยื่นให้ผู้ออกตั๋วจดรับรู้ภายในจำกัดเวลาดังกำหนดไว้ในมาตรา ๙๒๘ กำหนดเวลานี้ให้นับแต่วันจดรับรู้ซึ่งลงลายมือชื่อผู้ออกตั๋ว ถ้าผู้ออกตั๋วบอกปัดไม่ยอมจดรับรู้และลงวันไซร้ การที่เขาบอกปัดเช่นนี้ท่านว่าต้องทำให้เป็นหลักฐานขึ้นด้วยคำคัดค้าน และวันคัดค้านนั้นให้ถือเป็นวันเริ่มต้นในการนับกำหนดเวลาแต่ได้เห็น"}},{"id":"TH-H004-A987","no":987,"noLabel":{"th":"มาตรา 987"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๘๗ อันว่าเช็คนั้น คือหนังสือตราสารซึ่งบุคคลคนหนึ่ง เรียกว่าผู้สั่งจ่าย สั่งธนาคารให้ใช้เงินจำนวนหนึ่งเมื่อทวงถามให้แก่บุคคลอีกคนหนึ่ง หรือให้ใช้ตามคำสั่งของบุคคลอีกคนหนึ่ง อันเรียกว่าผู้รับเงิน"}},{"id":"TH-H004-A988","no":988,"noLabel":{"th":"มาตรา 988"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๘๘ อันเช็คนั้น ต้องมีรายการดังกล่าวต่อไปนี้ คือ (๑) คำบอกชื่อว่าเป็นเช็ค (๒) คำสั่งอันปราศจากเงื่อนไขให้ใช้เงินเป็นจำนวนแน่นอน (๓) ชื่อ หรือยี่ห้อและสำนักของธนาคาร (๔) ชื่อ หรือยี่ห้อของผู้รับเงิน หรือคำจดแจ้งว่าให้ใช้เงินแก่ผู้ถือ (๕) สถานที่ใช้เงิน (๖) วันและสถานที่ออกเช็ค (๗) ลายมือชื่อผู้สั่งจ่าย"}},{"id":"TH-H004-A989","no":989,"noLabel":{"th":"มาตรา 989"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๘๙ บทบัญญัติทั้งหลายในหมวด ๒ อันว่าด้วยตั๋วแลกเงินดังจะกล่าวต่อไปนี้ ท่านให้ยกมาบังคับในเรื่องเช็คเพียงเท่าที่ไม่ขัดกับสภาพแห่งตราสารชนิดนี้ คือบทมาตรา ๙๑๐ มาตรา ๙๑๔ ถึงมาตรา ๙๒๓ มาตรา ๙๒๕ มาตรา ๙๒๖ มาตรา ๙๓๘ ถึงมาตรา ๙๔๐ มาตรา ๙๔๕ มาตรา ๙๔๖ มาตรา ๙๕๙ มาตรา ๙๖๗ มาตรา ๙๗๑ ถ้าเป็นเช็คที่ออกมาแต่ต่างประเทศ ท่านให้นำบทบัญญัติดังต่อไปนี้มาใช้บังคับด้วย คือบทมาตรา ๙๒๔ มาตรา ๙๖๐ ถึงมาตรา ๙๖๔ มาตรา ๙๗๓ ถึงมาตรา ๙๗๗ มาตรา ๙๘๐"}},{"id":"TH-H004-A990","no":990,"noLabel":{"th":"มาตรา 990"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๐ ผู้ทรงเช็คต้องยื่นเช็คแก่ธนาคารเพื่อให้ใช้เงิน คือว่าถ้าเป็นเช็คให้ใช้เงินในเมืองเดียวกันกับที่ออกเช็คต้องยื่นภายในเดือนหนึ่งนับแต่วันออกเช็คนั้น ถ้าเป็นเช็คให้ใช้เงินที่อื่นต้องยื่นภายในสามเดือน ถ้ามิฉะนั้นท่านว่าผู้ทรงสิ้นสิทธิที่จะไล่เบี้ยเอาแก่ผู้สลักหลังทั้งปวง ทั้งเสียสิทธิอันมีต่อผู้สั่งจ่ายด้วยเพียงเท่าที่จะเกิดความเสียหายอย่างหนึ่งอย่างใดแก่ผู้สั่งจ่ายเพราะการที่ละเลยเสียไม่ยื่นเช็คนั้น อนึ่ง ผู้ทรงเช็คซึ่งผู้สั่งจ่ายหลุดพ้นจากความรับผิดไปแล้วนั้น ท่านให้รับช่วงสิทธิของผู้สั่งจ่ายคนนั้นอันมีต่อธนาคาร"}},{"id":"TH-H004-A991","no":991,"noLabel":{"th":"มาตรา 991"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๑ ธนาคารจำต้องใช้เงินตามเช็คซึ่งผู้เคยค้ากับธนาคารได้ออกเบิกเงินแก่ตน เว้นแต่ในกรณีดังกล่าวต่อไปนี้ คือ (๑) ไม่มีเงินในบัญชีของผู้เคยค้าคนนั้นเป็นเจ้าหนี้พอจะจ่ายตามเช็คนั้น หรือ (๒) เช็คนั้นยื่นเพื่อให้ใช้เงินเมื่อพ้นเวลาหกเดือนนับแต่วันออกเช็ค หรือ (๓) ได้มีคำบอกกล่าวว่าเช็คนั้นหายหรือถูกลักไป"}},{"id":"TH-H004-A992","no":992,"noLabel":{"th":"มาตรา 992"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๒ หน้าที่และอำนาจของธนาคารซึ่งจะใช้เงินตามเช็คอันเบิกแก่ตนนั้น ท่านว่าเป็นอันสุดสิ้นไปเมื่อกรณีเป็นดังจะกล่าวต่อไปนี้ คือ (๑) มีคำบอกห้ามการใช้เงิน (๒) รู้ว่าผู้สั่งจ่ายตาย (๓) รู้ว่าศาลได้มีคำสั่งรักษาทรัพย์ชั่วคราว หรือคำสั่งให้ผู้สั่งจ่ายเป็นคนล้มละลาย หรือได้มีประกาศโฆษณาคำสั่งเช่นนั้น"}},{"id":"TH-H004-A993","no":993,"noLabel":{"th":"มาตรา 993"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๓ ถ้าธนาคารเขียนข้อความลงลายมือชื่อบนเช็ค เช่นคำว่า “ใช้ได้” หรือ “ใช้เงินได้” หรือคำใด ๆ อันแสดงผลอย่างเดียวกัน ท่านว่าธนาคารต้องผูกพันในฐานเป็นลูกหนี้ชั้นต้นในอันจะต้องใช้เงินแก่ผู้ทรงตามเช็คนั้น ถ้าผู้ทรงเช็คเป็นผู้จัดการให้ธนาคารลงข้อความรับรองดังว่านั้น ท่านว่าผู้สั่งจ่ายและผู้สลักหลังทั้งปวงเป็นอันหลุดพ้นจากความรับผิดตามเช็คนั้น ถ้าธนาคารลงข้อความรับรองดังนั้น โดยคำขอร้องของผู้สั่งจ่าย ท่านว่าผู้สั่งจ่ายและปวงผู้สลักหลังก็หาหลุดพ้นไปไม่"}},{"id":"TH-H004-A994","no":994,"noLabel":{"th":"มาตรา 994"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๔ ถ้าในเช็คมีเส้นขนานคู่ขีดขวางไว้ข้างด้านหน้า กับมีหรือไม่มีคำว่า “และบริษัท” หรือคำย่ออย่างใด ๆ แห่งข้อความนี้อยู่ในระหว่างเส้นทั้งสองนั้นไซร้ เช็คนั้นชื่อว่าเป็นเช็คขีดคร่อมทั่วไป และจะใช้เงินตามเช็คนั้นได้แต่เฉพาะให้แก่ธนาคารเท่านั้น ถ้าในระวางเส้นทั้งสองนั้นกรอกชื่อธนาคารอันหนึ่งอันใดลงไว้โดยเฉพาะ เช็คเช่นนั้นชื่อว่าเป็นเช็คขีดคร่อมเฉพาะ และจะใช้เงินตามเช็คนั้นได้เฉพาะให้แก่ธนาคารอันนั้น"}},{"id":"TH-H004-A995","no":995,"noLabel":{"th":"มาตรา 995"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๕ (๑) เช็คไม่มีขีดคร่อม ผู้สั่งจ่ายหรือผู้ทรงคนใดคนหนึ่งจะขีดคร่อมเสียก็ได้ และจะทำเป็นขีดคร่อมทั่วไปหรือขีดคร่อมเฉพาะก็ได้ (๒) เช็คขีดคร่อมทั่วไป ผู้ทรงจะทำให้เป็นขีดคร่อมเฉพาะเสียก็ได้ (๓) เช็คขีดคร่อมทั่วไปก็ดี ขีดคร่อมเฉพาะก็ดี ผู้ทรงจะเติมคำลงว่า“ห้ามเปลี่ยนมือ” ก็ได้ (๔) เช็คขีดคร่อมเฉพาะให้แก่ธนาคารใด ธนาคารนั้นจะซ้ำขีดคร่อมเฉพาะให้ไปแก่ธนาคารอื่นเพื่อเรียกเก็บเงินก็ได้ (๕) เช็คไม่มีขีดคร่อมก็ดี เช็คขีดคร่อมทั่วไปก็ดี ส่งไปยังธนาคารใดเพื่อให้เรียกเก็บเงิน ธนาคารนั้นจะลงขีดคร่อมเฉพาะให้แก่ตนเองก็ได้"}},{"id":"TH-H004-A996","no":996,"noLabel":{"th":"มาตรา 996"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๖ การขีดคร่อมเช็คตามที่อนุญาตไว้ในมาตราก่อนนั้น ท่านว่าเป็นส่วนสำคัญอันหนึ่งของเช็ค ใครจะลบล้างย่อมไม่เป็นการชอบด้วยกฎหมาย"}},{"id":"TH-H004-A997","no":997,"noLabel":{"th":"มาตรา 997"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๗ เช็คขีดคร่อมเฉพาะให้แก่ธนาคารกว่าธนาคารหนึ่งขึ้นไปเมื่อนำเบิกเอาแก่ธนาคารใด ท่านให้ธนาคารนั้นบอกปัดเสียอย่าใช้เงินให้ เว้นแต่ที่ขีดคร่อมให้แก่ธนาคารในฐานเป็นตัวแทนเรียกเก็บเงิน ธนาคารใดซึ่งเขานำเช็คเบิกขืนใช้เงินไปตามเช็คที่ขีดคร่อมอย่างว่ามานั้นก็ดี ใช้เงินตามเช็คอันเขาขีดคร่อมทั่วไปเป็นประการอื่นนอกจากใช้ให้แก่ธนาคารอันใดอันหนึ่งก็ดี ใช้เงินตามเช็คอันเขาขีดคร่อมเฉพาะเป็นประการอื่นนอกจากใช้ให้แก่ธนาคารซึ่งเขาเจาะจงขีดคร่อมให้โดยเฉพาะ หรือแก่ธนาคารตัวแทนเรียกเก็บเงินของธนาคารนั้นก็ดี ท่านว่าธนาคารซึ่งใช้เงินไปดังกล่าวนี้จะต้องรับผิดต่อผู้เป็นเจ้าของอันแท้จริงแห่งเช็คนั้น ในการที่เขาจะต้องเสียหายอย่างใด ๆ เพราะการที่ตนใช้เงินไปตามเช็คดังนั้น แต่หากเช็คใดเขานำยื่นเพื่อให้ใช้เงิน และเมื่อยื่นไม่ปรากฏว่าเป็นเช็คขีดคร่อมก็ดี หรือไม่ปรากฏว่ามีรอยขีดคร่อมอันได้ลบล้างหรือแก้ไขเปลี่ยนแปลงเพิ่มเติมเป็นประการอื่นนอกจากที่อนุญาตไว้โดยกฎหมายก็ดี เช็คเช่นนี้ถ้าธนาคารใดใช้เงินไปโดยสุจริตและปราศจากประมาทเลินเล่อ ท่านว่าธนาคารนั้นไม่ต้องรับผิดหรือต้องมีหน้าที่รับใช้เงินอย่างใด ๆ"}},{"id":"TH-H004-A998","no":998,"noLabel":{"th":"มาตรา 998"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๘ ธนาคารใดซึ่งเขานำเช็คขีดคร่อมเบิกเงิน ใช้เงินไปตามเช็คนั้นโดยสุจริตและปราศจากประมาทเลินเล่อ กล่าวคือว่าถ้าเป็นเช็คขีดคร่อมทั่วไปก็ใช้เงินให้แก่ธนาคารอันใดอันหนึ่ง ถ้าเป็นเช็คขีดคร่อมเฉพาะก็ใช้ให้แก่ธนาคารซึ่งเขาเจาะจงขีดคร่อมให้โดยเฉพาะ หรือใช้ให้แก่ธนาคารตัวแทนเรียกเก็บเงินของธนาคารนั้นไซร้ ท่านว่าธนาคารซึ่งใช้เงินไปตามเช็คนั้นฝ่ายหนึ่ง กับถ้าเช็คตกไปถึงมือผู้รับเงินแล้ว ผู้สั่งจ่ายอีกฝ่ายหนึ่งต่างมีสิทธิเป็นอย่างเดียวกัน และเข้าอยู่ในฐานอันเดียวกันเสมือนดังว่าเช็คนั้นได้ใช้เงินให้แก่ผู้เป็นเจ้าของอันแท้จริงแล้ว"}},{"id":"TH-H004-A999","no":999,"noLabel":{"th":"มาตรา 999"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๙๙๙ บุคคลใดได้เช็คขีดคร่อมของเขามาซึ่งมีคำว่า “ห้ามเปลี่ยนมือ” ท่านว่าบุคคลนั้นไม่มีสิทธิในเช็คนั้นยิ่งไปกว่า และไม่สามารถให้สิทธิในเช็คนั้นต่อไปได้ดีกว่าสิทธิของบุคคลอันตนได้เช็คของเขามา"}},{"id":"TH-H004-A1000","no":1000,"noLabel":{"th":"มาตรา 1000"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๐๐๐ ธนาคารใดได้รับเงินไว้เพื่อผู้เคยค้าของตนโดยสุจริตและปราศจากประมาทเลินเล่อ อันเป็นเงินเขาใช้ให้ตามเช็คขีดคร่อมทั่วไปก็ดี ขีดคร่อมเฉพาะให้แก่ตนก็ดี หากปรากฏว่าผู้เคยค้านั้นไม่มีสิทธิหรือมีสิทธิเพียงอย่างบกพร่องในเช็คนั้นไซร้ ท่านว่าเพียงแต่เหตุที่ได้รับเงินไว้หาทำให้ธนาคารนั้นต้องรับผิดต่อผู้เป็นเจ้าของอันแท้จริงแห่งเช็คนั้นแต่อย่างหนึ่งอย่างใดไม่"}},{"id":"TH-H004-A1001","no":1001,"noLabel":{"th":"มาตรา 1001"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๐๐๑ ในคดีฟ้องผู้รับรองตั๋วแลกเงินก็ดี ผู้ออกตั๋วสัญญาใช้เงินก็ดี ท่านห้ามมิให้ฟ้องเมื่อพ้นเวลาสามปีนับแต่วันตั๋วนั้น ๆ ถึงกำหนดใช้เงิน"}},{"id":"TH-H004-A1002","no":1002,"noLabel":{"th":"มาตรา 1002"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๐๐๒ ในคดีที่ผู้ทรงตั๋วเงินฟ้องผู้สลักหลังและผู้สั่งจ่าย ท่านห้ามมิให้ฟ้องเมื่อพ้นเวลาปีหนึ่งนับแต่วันที่ได้ลงในคำคัดค้านซึ่งได้ทำขึ้นภายในเวลาอันถูกต้องตามกำหนด หรือนับแต่วันตั๋วเงินถึงกำหนด ในกรณีที่มีข้อกำหนดไว้ว่า “ไม่จำต้องมีคำคัดค้าน”"}},{"id":"TH-H004-A1003","no":1003,"noLabel":{"th":"มาตรา 1003"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๐๐๓ ในคดีผู้สลักหลังทั้งหลายฟ้องไล่เบี้ยกันเองและไล่เบี้ยเอาแก่ผู้สั่งจ่ายแห่งตั๋วเงิน ท่านห้ามมิให้ฟ้องคดีเมื่อพ้นเวลาหกเดือนนับแต่วันที่ผู้สลักหลังเข้าถือเอาตั๋วเงินและใช้เงิน หรือนับแต่วันที่ผู้สลักหลังนั้นเองถูกฟ้อง"}},{"id":"TH-H004-A1004","no":1004,"noLabel":{"th":"มาตรา 1004"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๐๐๔ เมื่ออายุความสะดุดหยุดลงเพราะการอันหนึ่งอันใด ซึ่งกระทำแก่คู่สัญญาแห่งตั๋วเงินฝ่ายใดฝ่ายหนึ่ง ท่านว่าย่อมมีผลสะดุดหยุดลงเพียงแต่แก่คู่สัญญาฝ่ายนั้น"}},{"id":"TH-H004-A1005","no":1005,"noLabel":{"th":"มาตรา 1005"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๐๐๕ ถ้าตั๋วเงินได้ทำขึ้นหรือได้โอนหรือสลักหลังไปแล้วในมูลหนี้อันหนึ่งอันใด และสิทธิตามตั๋วเงินนั้นมาสูญสิ้นไปเพราะอายุความก็ดี หรือเพราะละเว้นไม่ดำเนินการให้ต้องตามวิธีใด ๆ อันจะพึงต้องทำก็ดี ท่านว่าหนี้เดิมนั้นก็ยังคงมีอยู่ตามหลักกฎหมายอันแพร่หลายทั่วไป เท่าที่ลูกหนี้มิได้ต้องเสียหายแต่การนั้น เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1006","no":1006,"noLabel":{"th":"มาตรา 1006"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๐๖ การที่ลายมือชื่ออันหนึ่งในตั๋วเงินเป็นลายมือปลอม ย่อมไม่กระทบกระทั่งถึงความสมบูรณ์แห่งลายมือชื่ออื่น ๆ ในตั๋วเงินนั้น"}},{"id":"TH-H004-A1007","no":1007,"noLabel":{"th":"มาตรา 1007"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๐๗ ถ้าข้อความในตั๋วเงินใด หรือในคำรับรองตั๋วเงินรายใด มีผู้แก้ไขเปลี่ยนแปลงในข้อสำคัญโดยที่คู่สัญญาทั้งปวงผู้ต้องรับผิดตามตั๋วเงินมิได้ยินยอมด้วยหมดทุกคนไซร้ ท่านว่าตั๋วเงินนั้นก็เป็นอันเสีย เว้นแต่ยังคงใช้ได้ต่อคู่สัญญาซึ่งเป็นผู้ทำการแก้ไขเปลี่ยนแปลงนั้น หรือได้ยินยอมด้วยกับการแก้ไขเปลี่ยนแปลงนั้น กับทั้งผู้สลักหลังในภายหลัง แต่หากตั๋วเงินใดได้มีผู้แก้ไขเปลี่ยนแปลงในข้อสำคัญ แต่ความเปลี่ยนแปลงนั้นไม่ประจักษ์ และตั๋วเงินนั้นตกอยู่ในมือผู้ทรงโดยชอบด้วยกฎหมายไซร้ ท่านว่าผู้ทรงคนนั้นจะเอาประโยชน์จากตั๋วเงินนั้นก็ได้เสมือนดังว่ามิได้มีการแก้ไขเปลี่ยนแปลงเลย และจะบังคับการใช้เงินตามเนื้อความเดิมแห่งตั๋วนั้นก็ได้ กล่าวโดยเฉพาะ การแก้ไขเปลี่ยนแปลงเช่นจะกล่าวต่อไปนี้ ท่านถือว่าเป็นการแก้ไขเปลี่ยนแปลงในข้อสำคัญ คือแก้ไขเปลี่ยนแปลงอย่างใด ๆ แก่วันที่ลง จำนวนเงินอันจะพึงใช้ เวลาใช้เงิน สถานที่ใช้เงิน กับทั้งเมื่อตั๋วเงินเขารับรองไว้ทั่วไปไม่เจาะจงสถานที่ใช้เงิน ไปเติมความระบุสถานที่ใช้เงินเข้าโดยที่ผู้รับรองมิได้ยินยอมด้วย"}},{"id":"TH-H004-A1008","no":1008,"noLabel":{"th":"มาตรา 1008"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๐๘ ภายในบังคับแห่งบทบัญญัติทั้งหลายในประมวลกฎหมายนี้ เมื่อใดลายมือชื่อในตั๋วเงินเป็นลายมือปลอมก็ดี เป็นลายมือชื่อลงไว้โดยที่บุคคลซึ่งอ้างเอาเป็นเจ้าของลายมือชื่อนั้นมิได้มอบอำนาจให้ลงก็ดี ท่านว่าลายมือชื่อปลอมหรือลงปราศจากอำนาจเช่นนั้นเป็นอันใช้ไม่ได้เลย ใครจะอ้างอิงอาศัยแสวงสิทธิอย่างหนึ่งอย่างใดเพื่อยึดหน่วงตั๋วเงินไว้ก็ดี เพื่อทำให้ตั๋วนั้นหลุดพ้นก็ดี หรือเพื่อบังคับการใช้เงินเอาแก่คู่สัญญาแห่งตั๋วนั้นคนใดคนหนึ่งก็ดี ท่านว่าไม่อาจจะทำได้เป็นอันขาด เว้นแต่คู่สัญญาฝ่ายซึ่งจะพึงถูกยึดหน่วงหรือถูกบังคับใช้เงินนั้นจะอยู่ในฐานเป็นผู้ต้องตัดบทมิให้ยกข้อลายมือชื่อปลอม หรือข้อลงลายมือชื่อปราศจากอำนาจนั้นขึ้นเป็นข้อต่อสู้ แต่ข้อความใด ๆ อันกล่าวมาในมาตรานี้ ท่านมิให้กระทบกระทั่งถึงการให้สัตยาบันแก่ลายมือชื่อซึ่งลงไว้โดยปราศจากอำนาจแต่หากไม่ถึงแก่เป็นลายมือปลอม"}},{"id":"TH-H004-A1009","no":1009,"noLabel":{"th":"มาตรา 1009"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๐๙ ถ้ามีผู้นำตั๋วเงินชนิดจะพึงใช้เงินตามเขาสั่งเมื่อทวงถามมาเบิกต่อธนาคารใด และธนาคารนั้นได้ใช้เงินให้ไปตามทางค้าปกติโดยสุจริตและปราศจากประมาทเลินเล่อไซร้ ท่านว่าธนาคารไม่มีหน้าที่จะต้องนำสืบว่าการสลักหลังของผู้รับเงิน หรือการสลักหลังในภายหลังรายใด ๆ ได้ทำไปด้วยอาศัยรับมอบอำนาจแต่บุคคลซึ่งอ้างเอาเป็นเจ้าของคำสลักหลังนั้น และถึงแม้ว่ารายการสลักหลังนั้นจะเป็นสลักหลังปลอมหรือปราศจากอำนาจก็ตาม ท่านให้ถือว่าธนาคารได้ใช้เงินไปถูกระเบียบ"}},{"id":"TH-H004-A1010","no":1010,"noLabel":{"th":"มาตรา 1010"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๑๐ เมื่อผู้ทรงตั๋วเงินซึ่งหายหรือถูกลักทราบเหตุแล้ว ในทันใดนั้นต้องบอกกล่าวเป็นหนังสือไปยังผู้ออกตั๋วเงิน ผู้จ่าย ผู้สมอ้างยามประสงค์ ผู้รับรองเพื่อแก้หน้าและผู้รับอาวัล ตามแต่มี เพื่อให้บอกปัดไม่ใช้เงินตามตั๋วเงินนั้น"}},{"id":"TH-H004-A1011","no":1011,"noLabel":{"th":"มาตรา 1011"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๐๑๑ ถ้าตั๋วเงินหายไปแต่ก่อนเวลาล่วงเลยกำหนดใช้เงิน ท่านว่าบุคคลซึ่งได้เป็นผู้ทรงตั๋วเงินนั้นจะร้องขอไปยังผู้สั่งจ่ายให้ ๆ ตั๋วเงินเป็นเนื้อความเดียวกันแก่ตนใหม่อีกฉบับหนึ่งก็ได้ และในการนี้ถ้าเขาประสงค์ก็วางประกันให้ไว้แก่ผู้สั่งจ่าย เพื่อไว้ทดแทนที่เขาหากจะต้องเสียหายแก่ผู้หนึ่งผู้ใดในกรณีที่ตั๋วเงินซึ่งว่าหายนั้นจะกลับหาได้ อนึ่ง ผู้สั่งจ่ายรับคำขอร้องดังว่ามานั้นแล้ว หากบอกปัดไม่ยอมให้ตั๋วเงินคู่ฉบับเช่นนั้น อาจจะถูกบังคับให้ออกให้ก็ได้"}},{"id":"TH-H004-A1012","no":1012,"noLabel":{"th":"มาตรา 1012"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๒ อันว่าสัญญาจัดตั้งห้างหุ้นส่วนหรือบริษัทนั้น คือสัญญาซึ่งบุคคลตั้งแต่สองคนขึ้นไปตกลงเข้ากันเพื่อกระทำกิจการร่วมกัน ด้วยประสงค์จะแบ่งปันกำไรอันจะพึงได้แต่กิจการที่ทำนั้น"}},{"id":"TH-H004-A1013","no":1013,"noLabel":{"th":"มาตรา 1013"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๓ อันห้างหุ้นส่วนหรือบริษัทนั้น ท่านกำหนดเป็นสามประเภท คือ (๑) ห้างหุ้นส่วนสามัญ (๒) ห้างหุ้นส่วนจำกัด (๓) บริษัทจำกัด"}},{"id":"TH-H004-A1014","no":1014,"noLabel":{"th":"มาตรา 1014"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๔ บรรดาสำนักงานสำหรับจดทะเบียนห้างหุ้นส่วนและบริษัททั้งหลายนั้น ให้รัฐมนตรีเจ้ากระทรวงซึ่งบัญชาการจดทะเบียนห้างหุ้นส่วนและบริษัทเป็นผู้ออกกฎข้อบังคับจัดตั้งขึ้น"}},{"id":"TH-H004-A1015","no":1015,"noLabel":{"th":"มาตรา 1015"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๕ ห้างหุ้นส่วนหรือบริษัทเมื่อได้จดทะเบียนตามบัญญัติแห่งลักษณะนี้แล้ว ท่านจัดว่าเป็นนิติบุคคลต่างหากจากผู้เป็นหุ้นส่วนหรือผู้ถือหุ้นทั้งหลายซึ่งรวมเข้ากันเป็นหุ้นส่วนหรือบริษัทนั้น"}},{"id":"TH-H004-A1016","no":1016,"noLabel":{"th":"มาตรา 1016"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๖ การจดทะเบียนห้างหุ้นส่วนหรือบริษัท การแก้ไขข้อความที่ได้จดทะเบียนไว้ในภายหลัง และการจดทะเบียนอย่างอื่นตามลักษณะ ๒๒ หุ้นส่วนและบริษัท ที่กำหนดให้จดทะเบียน ให้จดทะเบียน ณ สำนักงานทะเบียนหุ้นส่วนบริษัทที่สำนักงานแห่งใหญ่ตั้งอยู่หรือตามที่รัฐมนตรีเจ้ากระทรวงประกาศกำหนด"}},{"id":"TH-H004-A1017","no":1017,"noLabel":{"th":"มาตรา 1017"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๗ ถ้าข้อความหรือข้อมูลที่จะใช้ในการจดทะเบียนหรือประกาศโฆษณาเกิดขึ้นในต่างประเทศ ให้เริ่มนับระยะเวลาสำหรับการจดทะเบียนหรือประกาศโฆษณา ตั้งแต่เมื่อข้อความหรือข้อมูลนั้นมาถึงสำนักงานแห่งใหญ่ของห้างหุ้นส่วนหรือบริษัท"}},{"id":"TH-H004-A1018","no":1018,"noLabel":{"th":"มาตรา 1018"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๘ ในการจดทะเบียน ท่านให้เสียค่าธรรมเนียมตามกฎข้อบังคับซึ่งรัฐมนตรีเจ้ากระทรวงตั้งไว้"}},{"id":"TH-H004-A1019","no":1019,"noLabel":{"th":"มาตรา 1019"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๑๙ ถ้าคำขอจดทะเบียนหรือเอกสารซึ่งต้องจดทะเบียนไม่มีรายการบริบูรณ์ตามที่บังคับไว้ในลักษณะนี้ ว่าให้จดแจ้งก็ดี หรือถ้ารายการอันใดซึ่งจดแจ้งในคำขอหรือในเอกสารนั้นขัดกับกฎหมายก็ดี หรือถ้าเอกสารใดซึ่งกำหนดไว้ว่าให้ส่งด้วยกันกับคำขอจดทะเบียนยังขาดอยู่มิได้ส่งให้ครบก็ดี หรือถ้าไม่ปฏิบัติตามเงื่อนไขข้ออื่นซึ่งกฎหมายบังคับไว้ก็ดี นายทะเบียนจะไม่ยอมรับจดทะเบียนก็ได้ จนกว่าคำขอจดทะเบียนหรือเอกสารนั้นจะได้ทำให้บริบูรณ์หรือแก้ไขให้ถูกต้อง หรือได้ส่งเอกสารซึ่งกำหนดไว้นั้นครบทุกสิ่งอันหรือได้ปฏิบัติตามเงื่อนไขข้อนั้นแล้ว"}},{"id":"TH-H004-A1020","no":1020,"noLabel":{"th":"มาตรา 1020"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๐ บุคคลทุกคนเมื่อได้เสียค่าธรรมเนียมตามที่กำหนดในกฎกระทรวงแล้วชอบที่จะตรวจเอกสารซึ่งนายทะเบียนเก็บรักษาไว้ได้ หรือจะขอให้คัดสำเนาหรือเนื้อความในเอกสารฉบับใดๆ พร้อมด้วยคำรับรองว่าถูกต้องมอบให้ก็ได้ ผู้มีส่วนได้เสียของห้างหุ้นส่วนหรือบริษัทใดๆ เมื่อได้เสียค่าธรรมเนียมตามที่กำหนดในกฎกระทรวงแล้ว ชอบที่จะขอให้นายทะเบียนทำใบสำคัญแสดงการจดทะเบียนห้างหุ้นส่วนหรือบริษัทนั้นให้ก็ได้"}},{"id":"TH-H004-A1020.001","no":1020.001,"noLabel":{"th":"มาตรา 1020/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๐/๑ ให้รัฐมนตรีเจ้ากระทรวงมีอำนาจออกกฎกระทรวงกำหนด ลด หรือ ยกเว้นค่าธรรมเนียมที่ออกตามมาตรา ๑๐๑๘ และมาตรา ๑๐๒๐ กฎกระทรวงตามวรรคหนึ่ง จะกำหนดค่าธรรมเนียมให้แตกต่างกันตามรูปแบบการทำธุรกรรมก็ได้"}},{"id":"TH-H004-A1021","no":1021,"noLabel":{"th":"มาตรา 1021"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๑ นายทะเบียนทุกคนจะต้องแต่งย่อรายการซึ่งได้ลงทะเบียนส่งไปลงพิมพ์โฆษณาในหนังสือราชกิจจานุเบกษาเป็นคราว ๆ ตามแบบซึ่งรัฐมนตรีเจ้ากระทรวงจะได้กำหนดให้"}},{"id":"TH-H004-A1022","no":1022,"noLabel":{"th":"มาตรา 1022"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๒ เมื่อได้พิมพ์โฆษณาดังนั้นแล้ว ท่านให้ถือว่าบรรดาเอกสารและข้อความซึ่งลงทะเบียนอันได้กล่าวถึงในย่อรายการนั้น เป็นอันรู้แก่บุคคลทั้งปวงไม่เลือกว่าเป็นผู้เกี่ยวข้องด้วยห้างหุ้นส่วนหรือด้วยบริษัทนั้น หรือที่ไม่เกี่ยวข้อง"}},{"id":"TH-H004-A1023","no":1023,"noLabel":{"th":"มาตรา 1023"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๓ ผู้เป็นหุ้นส่วนก็ดี ห้างหุ้นส่วนก็ดี หรือบริษัทก็ดี จะถือเอาประโยชน์แก่บุคคลภายนอกเพราะเหตุที่มีสัญญาหรือเอกสาร หรือข้อความอันบังคับให้จดทะเบียนตามลักษณะนี้ยังไม่ได้ จนกว่าจะได้จดทะเบียนแล้ว แต่ฝ่ายบุคคลภายนอกจะถือเอาประโยชน์เช่นว่านั้นได้ แต่ถึงกระนั้นก็ดี ผู้เป็นหุ้นส่วน ผู้ถือหุ้น ห้างหุ้นส่วน หรือบริษัทซึ่งได้รับชำระหนี้ก่อนจดทะเบียนนั้นย่อมไม่จำต้องคืน"}},{"id":"TH-H004-A1023.001","no":1023.001,"noLabel":{"th":"มาตรา 1023/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๓/๑ ห้างหุ้นส่วนหรือบริษัทจะยกมาตรา ๑๐๒๓ ขึ้นต่อสู้บุคคลภายนอกผู้สุจริตเพื่อไม่ให้ต้องรับผิดโดยอ้างว่าผู้เป็นหุ้นส่วน ห้างหุ้นส่วน บริษัทหรือกรรมการไม่มีอำนาจกระทำการมิได้"}},{"id":"TH-H004-A1024","no":1024,"noLabel":{"th":"มาตรา 1024"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๐๒๔ ในระหว่างผู้เป็นหุ้นส่วนด้วยกันก็ดี หรือในระหว่างผู้ถือหุ้นด้วยกันก็ดี ในระหว่างผู้เป็นหุ้นส่วนกับห้างหุ้นส่วนก็ดี ในระหว่างผู้ถือหุ้นกับบริษัทก็ดี ท่านให้สันนิษฐานไว้ก่อนว่าบรรดาสมุดบัญชีเอกสารของห้างหุ้นส่วนหรือบริษัท หรือของผู้ชำระบัญชีห้างหุ้นส่วนหรือบริษัทใด ๆ นั้น ย่อมเป็นพยานหลักฐานอันถูกต้องตามข้อความที่ได้บันทึกไว้ในนั้นทุกประการ"}},{"id":"TH-H004-A1025","no":1025,"noLabel":{"th":"มาตรา 1025"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๒๕ อันว่าห้างหุ้นส่วนสามัญนั้น คือห้างหุ้นส่วนประเภทซึ่งผู้เป็นหุ้นส่วนหมดทุกคนต้องรับผิดร่วมกันเพื่อหนี้ทั้งปวงของหุ้นส่วนโดยไม่มีจำกัด"}},{"id":"TH-H004-A1026","no":1026,"noLabel":{"th":"มาตรา 1026"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๒๖ ผู้เป็นหุ้นส่วนทุกคนต้องมีสิ่งหนึ่งสิ่งใดมาลงหุ้นด้วยในห้างหุ้นส่วน สิ่งที่นำมาลงหุ้นด้วยนั้น จะเป็นเงินหรือทรัพย์สินสิ่งอื่นหรือลงแรงงานก็ได้"}},{"id":"TH-H004-A1027","no":1027,"noLabel":{"th":"มาตรา 1027"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๒๗ ในเมื่อมีกรณีเป็นข้อสงสัย ท่านให้สันนิษฐานไว้ก่อนว่าสิ่งซึ่งนำมาลงหุ้นด้วยกันนั้นมีค่าเท่ากัน"}},{"id":"TH-H004-A1028","no":1028,"noLabel":{"th":"มาตรา 1028"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๒๘ ถ้าผู้เป็นหุ้นส่วนคนใดได้ลงแต่แรงงานของตนเข้าเป็นหุ้น และในสัญญาเข้าหุ้นส่วนมิได้ตีราคาค่าแรงไว้ ท่านให้คำนวณส่วนกำไรของผู้ที่เป็นหุ้นส่วนด้วยลงแรงงานเช่นนั้น เสมอด้วยส่วนถัวเฉลี่ยของผู้เป็นหุ้นส่วนซึ่งได้ลงเงินหรือลงทรัพย์สินเข้าหุ้นในการนั้น"}},{"id":"TH-H004-A1029","no":1029,"noLabel":{"th":"มาตรา 1029"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๒๙ ถ้าผู้เป็นหุ้นส่วนคนหนึ่งเอาทรัพย์สินมาให้ใช้เป็นการลงหุ้นด้วยไซร้ ความเกี่ยวพันระหว่างผู้เป็นหุ้นส่วนคนนั้นกับห้างหุ้นส่วนในเรื่องส่งมอบและซ่อมแซมก็ดี ความรับผิดเพื่อชำรุดบกพร่องก็ดี ความรับผิดเพื่อการรอนสิทธิก็ดี ข้อยกเว้นความรับผิดก็ดี ท่านให้บังคับตามบทบัญญัติแห่งประมวลกฎหมายนี้ ว่าด้วยเช่าทรัพย์"}},{"id":"TH-H004-A1030","no":1030,"noLabel":{"th":"มาตรา 1030"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๐ ถ้าผู้เป็นหุ้นส่วนคนหนึ่งให้กรรมสิทธิ์ในทรัพย์สินอันใดอันหนึ่งเป็นการลงหุ้นด้วยไซร้ ความเกี่ยวพันระหว่างผู้เป็นหุ้นส่วนคนนั้นกับห้างหุ้นส่วนในเรื่องส่งมอบและซ่อมแซมก็ดี ความรับผิดเพื่อชำรุดบกพร่องก็ดี ความรับผิดเพื่อการรอนสิทธิก็ดี ข้อยกเว้นความรับผิดก็ดี ท่านให้บังคับตามบทบัญญัติแห่งประมวลกฎหมายนี้ ว่าด้วยซื้อขาย"}},{"id":"TH-H004-A1031","no":1031,"noLabel":{"th":"มาตรา 1031"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๑ ถ้าผู้เป็นหุ้นส่วนคนใดละเลยไม่ส่งมอบส่วนลงหุ้นของตนเสียเลย ท่านว่าต้องส่งคำบอกกล่าวเป็นจดหมายจดทะเบียนไปรษณีย์ไปยังผู้เป็นหุ้นส่วนคนนั้น ให้ส่งมอบส่วนลงหุ้นของตนมาภายในเวลาอันสมควร มิฉะนั้นผู้เป็นหุ้นส่วนคนอื่น ๆ จะลงเนื้อเห็นพร้อมกัน หรือโดยเสียข้างมากด้วยกันสุดแต่ข้อสัญญา ให้เอาผู้เป็นหุ้นส่วนคนนั้นออกเสียได้"}},{"id":"TH-H004-A1032","no":1032,"noLabel":{"th":"มาตรา 1032"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๒ ห้ามมิให้เปลี่ยนแปลงข้อสัญญาเดิมแห่งห้างหุ้นส่วนหรือประเภทแห่งกิจการ นอกจากด้วยความยินยอมของผู้เป็นหุ้นส่วนหมดด้วยกันทุกคน เว้นแต่จะมีข้อตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1033","no":1033,"noLabel":{"th":"มาตรา 1033"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๓ ถ้าผู้เป็นหุ้นส่วนมิได้ตกลงกันไว้ในกระบวนจัดการห้างหุ้นส่วนไซร้ ท่านว่าผู้เป็นหุ้นส่วนย่อมจัดการห้างหุ้นส่วนนั้นได้ทุกคน แต่ผู้เป็นหุ้นส่วนคนหนึ่งคนใดจะเข้าทำสัญญาอันใดซึ่งผู้เป็นหุ้นส่วนอีกคนหนึ่งทักท้วงนั้นไม่ได้ ในกรณีเช่นนี้ ท่านให้ถือว่าผู้เป็นหุ้นส่วนย่อมเป็นหุ้นส่วนผู้จัดการทุกคน"}},{"id":"TH-H004-A1034","no":1034,"noLabel":{"th":"มาตรา 1034"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๔ ถ้าได้ตกลงกันไว้ว่าการงานของห้างหุ้นส่วนนั้นจักให้เป็นไปตามเสียงข้างมากแห่งผู้เป็นหุ้นส่วนไซร้ ท่านให้ผู้เป็นหุ้นส่วนคนหนึ่งมีเสียงเป็นคะแนนหนึ่ง โดยไม่ต้องคำนึงถึงจำนวนที่ลงหุ้นด้วยมากหรือน้อย"}},{"id":"TH-H004-A1035","no":1035,"noLabel":{"th":"มาตรา 1035"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๕ ถ้าได้ตกลงกันไว้ว่าจะให้ผู้เป็นหุ้นส่วนหลายคนจัดการห้างหุ้นส่วนไซร้ หุ้นส่วนผู้จัดการแต่ละคนจะจัดการห้างหุ้นส่วนนั้นก็ได้ แต่หุ้นส่วนผู้จัดการคนหนึ่งคนใดจะทำการอันใดซึ่งหุ้นส่วนผู้จัดการอีกคนหนึ่งทักท้วงนั้นไม่ได้"}},{"id":"TH-H004-A1036","no":1036,"noLabel":{"th":"มาตรา 1036"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๖ อันหุ้นส่วนผู้จัดการนั้น จะเอาออกจากตำแหน่งได้ต่อเมื่อผู้เป็นหุ้นส่วนทั้งหลายอื่นยินยอมพร้อมกัน เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1037","no":1037,"noLabel":{"th":"มาตรา 1037"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๗ ถึงแม้ว่าผู้เป็นหุ้นส่วนทั้งหลายได้ตกลงให้ผู้เป็นหุ้นส่วนคนเดียวหรือหลายคนเป็นผู้จัดการห้างหุ้นส่วนก็ดี ผู้เป็นหุ้นส่วนทุกคนนอกจากผู้จัดการย่อมมีสิทธิที่จะไต่ถามถึงการงานของห้างหุ้นส่วนที่จัดอยู่นั้นได้ทุกเมื่อ และมีสิทธิที่จะตรวจและคัดสำเนาสมุด บัญชี และเอกสารใด ๆ ของห้างหุ้นส่วนได้ด้วย"}},{"id":"TH-H004-A1038","no":1038,"noLabel":{"th":"มาตรา 1038"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๘ ห้ามมิให้ผู้เป็นหุ้นส่วนประกอบกิจการอย่างหนึ่งอย่างใดซึ่งมีสภาพดุจเดียวกัน และเป็นการแข่งขันกับกิจการของห้างหุ้นส่วนนั้น ไม่ว่าทำเพื่อประโยชน์ตนหรือประโยชน์ผู้อื่น โดยมิได้รับความยินยอมของผู้เป็นหุ้นส่วนคนอื่น ๆ ถ้าผู้เป็นหุ้นส่วนคนใดทำการฝ่าฝืนต่อบทบัญญัติมาตรานี้ไซร้ ผู้เป็นหุ้นส่วนคนอื่น ๆ ชอบที่จะเรียกเอาผลกำไรซึ่งผู้นั้นหาได้ทั้งหมด หรือเรียกเอาค่าสินไหมทดแทนเพื่อการที่ห้างหุ้นส่วนได้รับความเสียหายเพราะเหตุนั้น แต่ท่านห้ามมิให้ฟ้องเรียกเมื่อพ้นเวลาปีหนึ่งนับแต่วันทำการฝ่าฝืน"}},{"id":"TH-H004-A1039","no":1039,"noLabel":{"th":"มาตรา 1039"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๓๙ ผู้เป็นหุ้นส่วนจำต้องจัดการงานของห้างหุ้นส่วนด้วยความระมัดระวังให้มากเสมือนกับจัดการงานของตนเองฉะนั้น"}},{"id":"TH-H004-A1040","no":1040,"noLabel":{"th":"มาตรา 1040"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๐ ห้ามมิให้ชักนำเอาบุคคลผู้อื่นเข้ามาเป็นหุ้นส่วนในห้างหุ้นส่วนโดยมิได้รับความยินยอมของผู้เป็นหุ้นส่วนหมดด้วยกันทุกคน เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1041","no":1041,"noLabel":{"th":"มาตรา 1041"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๑ ถ้าผู้เป็นหุ้นส่วนคนใดคนหนึ่งโอนส่วนกำไรของตนในห้างหุ้นส่วนทั้งหมดก็ดี หรือแต่บางส่วนก็ดีให้แก่บุคคลภายนอกโดยมิได้รับความยินยอมของผู้เป็นหุ้นส่วนทั้งหลายอื่นไซร้ ท่านว่าบุคคลภายนอกนั้นจะกลายเป็นเข้าหุ้นส่วนด้วยก็หามิได้"}},{"id":"TH-H004-A1042","no":1042,"noLabel":{"th":"มาตรา 1042"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๒ ความเกี่ยวพันระหว่างหุ้นส่วนผู้จัดการกับผู้เป็นหุ้นส่วนทั้งหลายอื่นนั้น ท่านให้บังคับด้วยบทบัญญัติแห่งประมวลกฎหมายนี้ ว่าด้วยตัวแทน"}},{"id":"TH-H004-A1043","no":1043,"noLabel":{"th":"มาตรา 1043"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๓ ถ้าผู้เป็นหุ้นส่วนอันมิได้เป็นผู้จัดการเอื้อมเข้ามาจัดการงานของห้างหุ้นส่วนก็ดี หรือผู้เป็นหุ้นส่วนซึ่งเป็นผู้จัดการกระทำล่วงขอบอำนาจของตนก็ดี ท่านให้บังคับด้วยบทบัญญัติแห่งประมวลกฎหมายนี้ ว่าด้วยจัดการงานนอกสั่ง"}},{"id":"TH-H004-A1044","no":1044,"noLabel":{"th":"มาตรา 1044"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๔ อันส่วนกำไรก็ดี ส่วนขาดทุนก็ดี ของผู้เป็นหุ้นส่วนทุก ๆ คนนั้น ย่อมเป็นไปตามส่วนที่ลงหุ้น"}},{"id":"TH-H004-A1045","no":1045,"noLabel":{"th":"มาตรา 1045"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๕ ถ้าหุ้นส่วนของผู้ใดได้กำหนดไว้แต่เพียงข้างฝ่ายกำไรว่าจะแบ่งเอาเท่าไร หรือกำหนดแต่เพียงข้างขาดทุนว่าจะยอมขาดเท่าไรฉะนี้ไซร้ ท่านให้สันนิษฐานไว้ก่อนว่าหุ้นส่วนของผู้นั้นมีส่วนกำไรและส่วนขาดทุนเป็นอย่างเดียวกัน"}},{"id":"TH-H004-A1046","no":1046,"noLabel":{"th":"มาตรา 1046"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๖ ผู้เป็นหุ้นส่วนไม่ว่าคนหนึ่งคนใดหามีสิทธิจะได้รับบำเหน็จเพื่อที่ได้จัดการงานของห้างหุ้นส่วนนั้นไม่ เว้นแต่จะได้มีความตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1047","no":1047,"noLabel":{"th":"มาตรา 1047"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๗ ถ้าชื่อของผู้เป็นหุ้นส่วนซึ่งออกจากหุ้นส่วนไปแล้วยังคงใช้เรียกขานติดเป็นชื่อห้างหุ้นส่วนอยู่ ท่านว่าผู้เป็นหุ้นส่วนนั้นชอบที่จะเรียกให้งดใช้ชื่อของตนเสียได้"}},{"id":"TH-H004-A1048","no":1048,"noLabel":{"th":"มาตรา 1048"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๐๔๘ ผู้เป็นหุ้นส่วนคนหนึ่งจะเรียกเอาส่วนของตนจากหุ้นส่วนอื่น ๆ แม้ในกิจการค้าขายอันใดซึ่งไม่ปรากฏชื่อของตนก็ได้"}},{"id":"TH-H004-A1049","no":1049,"noLabel":{"th":"มาตรา 1049"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๔๙ ผู้เป็นหุ้นส่วนจะถือเอาสิทธิใด ๆ แก่บุคคลภายนอกในกิจการค้าขายซึ่งไม่ปรากฏชื่อของตนนั้นหาได้ไม่"}},{"id":"TH-H004-A1050","no":1050,"noLabel":{"th":"มาตรา 1050"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๕๐ การใด ๆ อันผู้เป็นหุ้นส่วนคนใดคนหนึ่งได้จัดทำไปในทางที่เป็นธรรมดาการค้าขายของห้างหุ้นส่วนนั้น ท่านว่าผู้เป็นหุ้นส่วนหมดทุกคนย่อมมีความผูกพันในการนั้น ๆ ด้วย และจะต้องรับผิดร่วมกันโดยไม่จำกัดจำนวนในการชำระหนี้ อันได้ก่อให้เกิดขึ้นเพราะจัดการไปเช่นนั้น"}},{"id":"TH-H004-A1051","no":1051,"noLabel":{"th":"มาตรา 1051"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๕๑ ผู้เป็นหุ้นส่วนซึ่งออกจากหุ้นส่วนไปแล้วยังคงต้องรับผิดในหนี้ซึ่งห้างหุ้นส่วนได้ก่อให้เกิดขึ้นก่อนที่ตนได้ออกจากหุ้นส่วนไป"}},{"id":"TH-H004-A1052","no":1052,"noLabel":{"th":"มาตรา 1052"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๕๒ บุคคลผู้เข้าเป็นหุ้นส่วนในห้างหุ้นส่วนย่อมต้องรับผิดในหนี้ใด ๆ ซึ่งห้างหุ้นส่วนได้ก่อให้เกิดขึ้นก่อนที่ตนเข้ามาเป็นหุ้นส่วนด้วย"}},{"id":"TH-H004-A1053","no":1053,"noLabel":{"th":"มาตรา 1053"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๕๓ ห้างหุ้นส่วนซึ่งมิได้จดทะเบียนนั้น ถึงแม้จะมีข้อจำกัดอำนาจของหุ้นส่วนคนหนึ่งในการที่จะผูกพันผู้เป็นหุ้นส่วนคนอื่น ๆ ท่านว่าข้อจำกัดเช่นนั้นก็หามีผลถึงบุคคลภายนอกไม่"}},{"id":"TH-H004-A1054","no":1054,"noLabel":{"th":"มาตรา 1054"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๐๕๔ บุคคลใดแสดงตนว่าเป็นหุ้นส่วนด้วยวาจาก็ดี ด้วยลายลักษณ์อักษรก็ดี ด้วยกิริยาก็ดี ด้วยยินยอมให้เขาใช้ชื่อตนเป็นชื่อห้างหุ้นส่วนก็ดี หรือรู้แล้วไม่คัดค้านปล่อยให้เขาแสดงว่าตนเป็นหุ้นส่วนก็ดี ท่านว่าบุคคลนั้นย่อมต้องรับผิดต่อบุคคลภายนอกในบรรดาหนี้ของห้างหุ้นส่วนเสมือนเป็นหุ้นส่วน ถ้าผู้เป็นหุ้นส่วนคนหนึ่งคนใดตายไปแล้ว และห้างหุ้นส่วนนั้นยังคงค้าต่อไปในชื่อเดิมของห้าง ท่านว่าเหตุเพียงที่คงใช้ชื่อเดิมนั้นก็ดี หรือใช้ชื่อของหุ้นส่วนผู้ตายควบอยู่ด้วยก็ดี หาทำให้ความรับผิดมีแก่กองทรัพย์มรดกของผู้ตายเพื่อหนี้ใด ๆ อันห้างหุ้นส่วนได้ก่อให้เกิดขึ้นภายหลังมรณะนั้นไม่"}},{"id":"TH-H004-A1055","no":1055,"noLabel":{"th":"มาตรา 1055"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๕๕ ห้างหุ้นส่วนสามัญย่อมเลิกกันด้วยเหตุดังกล่าวต่อไปนี้ (๑) ถ้าในสัญญาทำไว้มีกำหนดกรณีอันใดเป็นเหตุที่จะเลิกกัน เมื่อมีกรณีนั้น (๒) ถ้าสัญญาทำไว้เฉพาะกำหนดกาลใด เมื่อสิ้นกำหนดกาลนั้น (๓) ถ้าสัญญาทำไว้เฉพาะเพื่อทำกิจการอย่างหนึ่งอย่างใดแต่อย่างเดียว เมื่อเสร็จการนั้น (๔) เมื่อผู้เป็นหุ้นส่วนคนใดคนหนึ่งให้คำบอกกล่าวแก่ผู้เป็นหุ้นส่วนคนอื่น ๆ ตามกำหนดดังบัญญัติไว้ในมาตรา ๑๐๕๖ (๕) เมื่อผู้เป็นหุ้นส่วนคนใดคนหนึ่งตาย หรือล้มละลาย หรือตกเป็นผู้ไร้ความสามารถ"}},{"id":"TH-H004-A1056","no":1056,"noLabel":{"th":"มาตรา 1056"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๕๖ ถ้าห้างหุ้นส่วนได้ตั้งขึ้นไม่มีกำหนดการอย่างหนึ่งอย่างใดเป็นยุติ ท่านว่าจะเลิกได้ต่อเมื่อผู้เป็นหุ้นส่วนคนใดคนหนึ่งบอกเลิกเมื่อสิ้นรอบปีในทางบัญชีเงินของห้างหุ้นส่วนนั้น และผู้เป็นหุ้นส่วนนั้นต้องบอกกล่าวความจำนงจะเลิกล่วงหน้าไม่น้อยกว่าหกเดือน"}},{"id":"TH-H004-A1057","no":1057,"noLabel":{"th":"มาตรา 1057"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๕๗ ถ้าผู้เป็นหุ้นส่วนคนใดร้องขอเมื่อมีกรณีอย่างใดอย่างหนึ่งดังจะกล่าวต่อไปนี้ ศาลอาจสั่งให้ห้างหุ้นส่วนสามัญเลิกกันเสียก็ได้ คือ (๑) เมื่อผู้เป็นหุ้นส่วนคนใดคนหนึ่งนอกจากผู้ร้องฟ้องนั้น ล่วงละเมิดบทบังคับใด ๆ อันเป็นข้อสาระสำคัญซึ่งสัญญาหุ้นส่วนกำหนดไว้แก่ตน โดยจงใจหรือเลินเล่ออย่างร้ายแรง (๒) เมื่อกิจการของห้างหุ้นส่วนนั้นจะทำไปก็มีแต่ขาดทุนอย่างเดียวและไม่มีหวังว่าจะกลับฟื้นตัวได้อีก (๓) เมื่อมีเหตุอื่นใด ๆ ทำให้ห้างหุ้นส่วนนั้นเหลือวิสัยที่จะดำรงคงอยู่ต่อไปได้"}},{"id":"TH-H004-A1058","no":1058,"noLabel":{"th":"มาตรา 1058"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๕๘ เมื่อเหตุอันใดอันหนึ่งเกิดขึ้นเกี่ยวด้วยผู้เป็นหุ้นส่วนคนหนึ่งซึ่งตามความในมาตรา ๑๐๕๗ หรือมาตรา ๑๐๖๗ เป็นเหตุให้ผู้เป็นหุ้นส่วนทั้งหลายนอกนั้นมีสิทธิจะเรียกให้เลิกห้างหุ้นส่วนได้ไซร้ ในเมื่อผู้เป็นหุ้นส่วนเหล่านั้นยื่นคำร้อง ท่านว่าศาลจะสั่งให้กำจัดหุ้นส่วนผู้ต้นเหตุคนนั้นออกเสียจากห้างหุ้นส่วนแทนสั่งให้เลิกห้างหุ้นส่วนก็ได้ ในการแบ่งทรัพย์สินระหว่างห้างหุ้นส่วนกับผู้เป็นหุ้นส่วนซึ่งถูกกำจัดนั้น ท่านให้ตีราคาทรัพย์สินของห้างหุ้นส่วนตามราคาที่เป็นอยู่ในเวลาแรกยื่นคำร้องขอให้จำกัด"}},{"id":"TH-H004-A1059","no":1059,"noLabel":{"th":"มาตรา 1059"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๕๙ ถ้าเมื่อสิ้นกำหนดการซึ่งได้ตกลงกันไว้และผู้เป็นหุ้นส่วนทั้งหลายหรือผู้เป็นหุ้นส่วนซึ่งเคยได้จัดการอยู่ในระหว่างกำหนดนั้น ยังคงดำเนินการค้าของห้างหุ้นส่วนอยู่ต่อไปโดยมิได้ชำระบัญชีหรือชำระเงินกันให้เสร็จไปไซร้ ท่านให้ถือว่าผู้เป็นหุ้นส่วนทั้งปวงได้ตกลงคงทำการเป็นหุ้นส่วนกันสืบไปโดยไม่มีกำหนดการ"}},{"id":"TH-H004-A1060","no":1060,"noLabel":{"th":"มาตรา 1060"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๖๐ ในกรณีอย่างใดอย่างหนึ่งซึ่งกล่าวไว้ในมาตรา ๑๐๕๕ อนุมาตรา ๔ หรือ อนุมาตรา ๕ นั้น ถ้าผู้เป็นหุ้นส่วนที่ยังอยู่รับซื้อหุ้นของผู้ที่ออกจากหุ้นส่วนไปไซร้ ท่านว่าสัญญาหุ้นส่วนนั้นก็ยังคงใช้ได้ต่อไปในระหว่างผู้เป็นหุ้นส่วนที่ยังอยู่ด้วยกัน"}},{"id":"TH-H004-A1061","no":1061,"noLabel":{"th":"มาตรา 1061"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๖๑ เมื่อห้างหุ้นส่วนเลิกกันแล้วก็ให้จัดการชำระบัญชี เว้นแต่จะได้ตกลงกันให้จัดการทรัพย์สินโดยวิธีอื่นในระหว่างผู้เป็นหุ้นส่วนด้วยกัน หรือว่าห้างหุ้นส่วนนั้นศาลได้พิพากษาให้ล้มละลาย ถ้าการเลิกห้างหุ้นส่วนนั้นได้เป็นไปโดยที่เจ้าหนี้เฉพาะตัวของผู้เป็นหุ้นส่วนคนใดคนหนึ่งได้ให้คำบอกกล่าวก็ดี หรือโดยที่ผู้เป็นหุ้นส่วนคนใดคนหนึ่งล้มละลายก็ดี ท่านว่าจะงดการชำระบัญชีเสียได้ต่อเมื่อเจ้าหนี้คนนั้น หรือเจ้าพนักงานรักษาทรัพย์ยินยอมด้วย การชำระบัญชีนั้น ให้ผู้เป็นหุ้นส่วนทั้งหมดด้วยกันจัดทำหรือให้บุคคลอื่นซึ่งผู้เป็นหุ้นส่วนได้ตั้งแต่งขึ้นนั้นเป็นผู้จัดทำ การตั้งแต่งผู้ชำระบัญชี ให้วินิจฉัยชี้ขาดโดยคะแนนเสียงข้างมากของผู้เป็นหุ้นส่วน"}},{"id":"TH-H004-A1062","no":1062,"noLabel":{"th":"มาตรา 1062"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๖๒ การชำระบัญชี ให้ทำโดยลำดับดังนี้ คือ (๑) ให้ชำระหนี้ทั้งหลายซึ่งค้างชำระแก่บุคคลภายนอก (๒) ให้ชดใช้เงินทดรองและค่าใช้จ่ายซึ่งผู้เป็นหุ้นส่วนได้ออกของตนไปเพื่อจัดการค้าของห้าง (๓) ให้คืนทุนทรัพย์ซึ่งผู้เป็นหุ้นส่วนแต่ละคนได้ลงเป็นหุ้น ถ้ายังมีทรัพย์เหลืออยู่อีกเท่าไร ก็ให้เฉลี่ยแจกเป็นกำไรในระหว่างผู้เป็นหุ้นส่วน"}},{"id":"TH-H004-A1063","no":1063,"noLabel":{"th":"มาตรา 1063"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๐๖๓ ถ้าเมื่อได้ชำระหนี้ซึ่งค้างชำระแก่บุคคลภายนอกและชดใช้เงินทดรองและค่าใช้จ่ายแล้ว สินทรัพย์ที่ยังอยู่ไม่พอจะคืนแก่ผู้เป็นหุ้นส่วนให้ครบจำนวนที่ลงหุ้นไซร้ ส่วนที่ขาดนี้คือขาดทุน ซึ่งต้องคิดเฉลี่ยช่วยกันขาด"}},{"id":"TH-H004-A1064","no":1064,"noLabel":{"th":"มาตรา 1064"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๔ อันห้างหุ้นส่วนสามัญนั้น จะจดทะเบียนก็ได้ การลงทะเบียนนั้น ท่านบังคับให้มีรายการดังนี้ คือ (๑) ชื่อห้างหุ้นส่วน (๒) วัตถุที่ประสงค์ของห้างหุ้นส่วน (๓) ที่ตั้งสำนักงานแห่งใหญ่และสาขาทั้งปวง (๔) ชื่อและที่สำนักกับทั้งอาชีวะของผู้เป็นหุ้นส่วนทุก ๆ คน ถ้าผู้เป็นหุ้นส่วนคนใดมีชื่อยี่ห้อ ก็ให้ลงทะเบียนทั้งชื่อและยี่ห้อด้วย (๕) ชื่อหุ้นส่วนผู้จัดการ ในเมื่อได้ตั้งแต่งให้เป็นผู้จัดการแต่เพียงบางคน (๖) ถ้ามีข้อจำกัดอำนาจของหุ้นส่วนผู้จัดการประการใดให้ลงไว้ด้วย (๗) ตราซึ่งใช้เป็นสำคัญของห้างหุ้นส่วน ข้อความซึ่งลงทะเบียนนั้น จะลงรายการอื่น ๆ อีกอันคู่สัญญาเห็นสมควรจะให้ประชาชนทราบด้วยก็ได้ การลงทะเบียนนั้น ต้องลงลายมือชื่อของผู้เป็นหุ้นส่วนทุกคน และต้องประทับตราของห้างหุ้นส่วนนั้นด้วย ให้พนักงานทะเบียนทำใบสำคัญแสดงการจดทะเบียนส่งมอบให้แก่ห้างหุ้นส่วนนั้นฉบับหนึ่ง"}},{"id":"TH-H004-A1064.001","no":1064.001,"noLabel":{"th":"มาตรา 1064/1"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๔/๑ หุ้นส่วนผู้จัดการคนใดในห้างหุ้นส่วนจดทะเบียนจะลาออกจากตำแหน่ง ให้ยื่นใบลาออกต่อหุ้นส่วนผู้จัดการอื่นคนหนึ่งคนใด การลาออกมีผลนับแต่วันที่ใบลาออกไปถึงหุ้นส่วนผู้จัดการอื่นนั้น ในกรณีที่ห้างหุ้นส่วนจดทะเบียนมีหุ้นส่วนผู้จัดการคนเดียว ให้หุ้นส่วนผู้จัดการที่จะลาออกจากตำแหน่งแจ้งเป็นหนังสือให้ผู้เป็นหุ้นส่วนคนหนึ่งคนใดทราบเพื่อนัดประชุมและพิจารณาตั้งผู้จัดการคนใหม่ พร้อมกับแนบใบลาออกไปด้วย การลาออกมีผลนับแต่วันที่ใบลาออกไปถึงหุ้นส่วนผู้นั้น หุ้นส่วนผู้จัดการซึ่งลาออกตามวรรคหนึ่งหรือวรรคสอง จะแจ้งการลาออกของตนให้นายทะเบียนทราบด้วยก็ได้"}},{"id":"TH-H004-A1064.002","no":1064.002,"noLabel":{"th":"มาตรา 1064/2"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๔/๒ เมื่อมีการเปลี่ยนแปลงหุ้นส่วนผู้จัดการ ให้ห้างหุ้นส่วนจดทะเบียนนำความไปจดทะเบียนภายในสิบสี่วันนับแต่วันที่มีการเปลี่ยนแปลง"}},{"id":"TH-H004-A1065","no":1065,"noLabel":{"th":"มาตรา 1065"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๕ ผู้เป็นหุ้นส่วนอาจถือประโยชน์แก่บุคคลภายนอกในบรรดาสิทธิอันห้างหุ้นส่วนจดทะเบียนนั้นได้มา แม้ในกิจการซึ่งไม่ปรากฏชื่อของตน"}},{"id":"TH-H004-A1066","no":1066,"noLabel":{"th":"มาตรา 1066"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๖ ห้ามมิให้ผู้เป็นหุ้นส่วนคนหนึ่งคนใดในห้างหุ้นส่วนจดทะเบียนประกอบกิจการอย่างหนึ่งอย่างใดอันมีสภาพเป็นอย่างเดียวกัน และเป็นการแข่งขันกับกิจการของห้างหุ้นส่วนนั้น ไม่ว่าทำเพื่อประโยชน์ตนหรือเพื่อประโยชน์ผู้อื่น หรือไปเข้าเป็นหุ้นส่วนไม่จำกัดความรับผิดในห้างหุ้นส่วนอื่น ซึ่งประกอบกิจการอันมีสภาพเป็นอย่างเดียวกัน และแข่งขันกับกิจการของห้างหุ้นส่วนจดทะเบียนนั้น เว้นไว้แต่จะได้รับคำยินยอมของผู้เป็นหุ้นส่วนอื่นทั้งหมด แต่ข้อห้ามเช่นว่ามานี้ ท่านว่าจะไม่พึงใช้ได้ ถ้าหากผู้เป็นหุ้นส่วนทั้งหลายได้รู้อยู่แล้วในเวลาเมื่อลงทะเบียนห้างหุ้นส่วนนั้นว่า ผู้เป็นหุ้นส่วนคนหนึ่งได้ทำกิจการ หรือเข้าเป็นหุ้นส่วนอยู่ในห้างหุ้นส่วนอื่นอันมีวัตถุที่ประสงค์อย่างเดียวกัน และในสัญญาเข้าหุ้นส่วนที่ทำไว้ต่อกันนั้นก็ไม่ได้บังคับให้ถอนตัวออก"}},{"id":"TH-H004-A1067","no":1067,"noLabel":{"th":"มาตรา 1067"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๗ ถ้าผู้เป็นหุ้นส่วนคนใดกระทำการฝ่าฝืนต่อบทบัญญัติในมาตราก่อนนี้ไซร้ ท่านว่าห้างหุ้นส่วนซึ่งจดทะเบียนนั้นชอบที่จะเรียกเอาผลกำไรอันผู้นั้นหาได้ทั้งหมด หรือเรียกเอาค่าสินไหมทดแทนเพื่อความเสียหายซึ่งห้างหุ้นส่วนได้รับเพราะเหตุนั้น แต่ทั้งนี้ท่านห้ามมิให้ฟ้องเรียกเมื่อพ้นเวลาปีหนึ่งนับแต่วันทำการฝ่าฝืน อนึ่ง บทบัญญัติมาตรานี้ไม่ลบล้างสิทธิของผู้เป็นหุ้นส่วนทั้งหลายนอกนั้น ในอันจะเรียกให้เลิกห้างหุ้นส่วน"}},{"id":"TH-H004-A1068","no":1068,"noLabel":{"th":"มาตรา 1068"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๘ ความรับผิดของผู้เป็นหุ้นส่วนในห้างหุ้นส่วนจดทะเบียน อันเกี่ยวแก่หนี้ซึ่งห้างหุ้นส่วนได้ก่อให้เกิดขึ้นก่อนที่ตนออกจากหุ้นส่วนนั้น ย่อมมีจำกัดเพียงสองปีนับแต่เมื่อออกจากหุ้นส่วน"}},{"id":"TH-H004-A1069","no":1069,"noLabel":{"th":"มาตรา 1069"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๖๙ นอกจากในกรณีทั้งหลายที่บัญญัติไว้ในมาตรา ๑๐๕๕ ท่านว่าห้างหุ้นส่วนจดทะเบียนย่อมเลิกกันเมื่อห้างหุ้นส่วนนั้นล้มละลาย"}},{"id":"TH-H004-A1070","no":1070,"noLabel":{"th":"มาตรา 1070"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๗๐ เมื่อใดห้างหุ้นส่วนซึ่งจดทะเบียนผิดนัดชำระหนี้ เมื่อนั้นเจ้าหนี้ของห้างหุ้นส่วนนั้นชอบที่จะเรียกให้ชำระหนี้เอาแต่ผู้เป็นหุ้นส่วนคนใดคนหนึ่งก็ได้"}},{"id":"TH-H004-A1071","no":1071,"noLabel":{"th":"มาตรา 1071"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๗๑ ในกรณีที่กล่าวไว้ในมาตรา ๑๐๗๐ นั้น ถ้าผู้เป็นหุ้นส่วนนำพิสูจน์ได้ว่า (๑) สินทรัพย์ของห้างหุ้นส่วนยังมีพอที่จะชำระหนี้ได้ทั้งหมดหรือบางส่วน และ (๒) การที่จะบังคับเอาแก่ห้างหุ้นส่วนนั้นไม่เป็นการยากฉะนี้ไซร้ ศาลจะบังคับให้เอาสินทรัพย์ของห้างหุ้นส่วนนั้นชำระหนี้ก่อนก็ได้ สุดแต่ศาลจะเห็นสมควร"}},{"id":"TH-H004-A1072","no":1072,"noLabel":{"th":"มาตรา 1072"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๐๗๒ ถ้าห้างหุ้นส่วนซึ่งจดทะเบียนยังมิได้เลิกกันตราบใด เจ้าหนี้ของผู้เป็นหุ้นส่วนเฉพาะตัวย่อมใช้สิทธิได้แต่เพียงในผลกำไรหรือเงินซึ่งห้างหุ้นส่วนค้างชำระแก่ผู้เป็นหุ้นส่วนคนนั้นเท่านั้น ถ้าห้างหุ้นส่วนนั้นเลิกกันแล้ว เจ้าหนี้ย่อมใช้สิทธิได้ตลอดจนถึงหุ้นของผู้เป็นหุ้นส่วนคนนั้นอันมีในสินทรัพย์ของห้างหุ้นส่วน"}},{"id":"TH-H004-A1073","no":1073,"noLabel":{"th":"มาตรา 1073"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๐๗๓ ห้างหุ้นส่วนจดทะเบียนห้างหนึ่งจะควบเข้าเป็นอันเดียวกับห้างหุ้นส่วนจดทะเบียนอีกห้างหนึ่งก็ได้ โดยความยินยอมของผู้เป็นหุ้นส่วนทั้งหมด เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1074","no":1074,"noLabel":{"th":"มาตรา 1074"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๐๗๔ เมื่อห้างหุ้นส่วนจดทะเบียนห้างใดปลงใจจะควบเข้ากันกับห้างอื่น ห้างหุ้นส่วนนั้นต้องโฆษณาในหนังสือพิมพ์แห่งท้องที่นั้นสองครั้งเป็นอย่างน้อย และส่งคำบอกกล่าวความประสงค์ที่จะควบเข้ากันนั้นแก่บรรดาผู้ซึ่งห้างหุ้นส่วนรู้ว่าเป็นเจ้าหนี้ และขอให้เจ้าหนี้ผู้มีข้อคัดค้านอย่างหนึ่งอย่างใดในการที่จะทำนั้นส่งคำคัดค้านไปภายในสามเดือนนับแต่วันบอกกล่าว ถ้าไม่มีใครคัดค้านภายในกำหนดเวลาเช่นว่านั้น ก็ให้พึงถือว่าไม่มีคัดค้าน ถ้ามีคัดค้านไซร้ ท่านมิให้ห้างหุ้นส่วนจัดการควบเข้ากัน เว้นแต่จะได้ใช้หนี้ที่เรียกร้องหรือให้ประกันเพื่อหนี้นั้นแล้ว"}},{"id":"TH-H004-A1075","no":1075,"noLabel":{"th":"มาตรา 1075"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๐๗๕ เมื่อห้างได้ควบเข้ากันแล้ว ต่างห้างก็ต่างมีหน้าที่จะต้องนำความนั้นไปจดลงทะเบียน ว่าได้ควบเข้ากันเป็นห้างหุ้นส่วนขึ้นใหม่"}},{"id":"TH-H004-A1076","no":1076,"noLabel":{"th":"มาตรา 1076"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๐๗๖ ห้างหุ้นส่วนใหม่นี้ย่อมได้ไปทั้งสิทธิทั้งต้องอยู่ในความรับผิดของห้างหุ้นส่วนเดิมที่ได้ควบเข้ากันนั้นทั้งสิ้น"}},{"id":"TH-H004-A1077","no":1077,"noLabel":{"th":"มาตรา 1077"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๗๗ อันห้างหุ้นส่วนจำกัดนั้น คือห้างหุ้นส่วนประเภทหนึ่งซึ่งมีผู้เป็นหุ้นส่วนสองจำพวกดังจะกล่าวต่อไปนี้ คือ (๑) ผู้เป็นหุ้นส่วนคนเดียวหรือหลายคนซึ่งมีจำกัดความรับผิดเพียงไม่เกินจำนวนเงินที่ตนรับจะลงหุ้นในห้างหุ้นส่วนนั้นจำพวกหนึ่ง และ (๒) ผู้เป็นหุ้นส่วนคนเดียวหรือหลายคนซึ่งต้องรับผิดร่วมกันในบรรดาหนี้ของห้างหุ้นส่วนไม่มีจำกัดจำนวนอีกจำพวกหนึ่ง"}},{"id":"TH-H004-A1078","no":1078,"noLabel":{"th":"มาตรา 1078"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๗๘ อันห้างหุ้นส่วนจำกัดนั้น ท่านบังคับว่าต้องจดทะเบียน การลงทะเบียนนั้น ต้องมีรายการดังต่อไปนี้ คือ (๑) ชื่อห้างหุ้นส่วน (๒) ข้อแถลงความว่าเป็นห้างหุ้นส่วนจำกัด และวัตถุที่ประสงค์ของห้างหุ้นส่วนนั้น (๓) ที่ตั้งสำนักงานแห่งใหญ่และสำนักงานสาขาทั้งปวง (๔) ชื่อ ยี่ห้อ สำนัก และอาชีวะของผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดและจำนวนเงินซึ่งเขาเหล่านั้นได้ลงหุ้นด้วยในห้างหุ้นส่วน (๕) ชื่อ ยี่ห้อ สำนัก และอาชีวะของผู้เป็นหุ้นส่วนจำพวกไม่จำกัดความรับผิด (๖) ชื่อหุ้นส่วนผู้จัดการ (๗) ถ้ามีข้อจำกัดอำนาจหุ้นส่วนผู้จัดการอันจะผูกพันห้างหุ้นส่วนนั้นประการใดให้ลงไว้ด้วย ข้อความซึ่งลงทะเบียนนั้น จะลงรายการอื่น ๆ อีกอันคู่สัญญาเห็นสมควรจะให้ประชาชนทราบด้วยก็ได้ การลงทะเบียนนั้น ต้องลงลายมือชื่อของผู้เป็นหุ้นส่วนทุกคน และต้องประทับตราของห้างหุ้นส่วนนั้นด้วย ให้พนักงานทะเบียนทำใบสำคัญแสดงการจดทะเบียนส่งมอบให้แก่ห้างหุ้นส่วนนั้นฉบับหนึ่ง"}},{"id":"TH-H004-A1078.001","no":1078.001,"noLabel":{"th":"มาตรา 1078/1"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๗๘/๑ หุ้นส่วนผู้จัดการคนใดจะลาออกจากตำแหน่ง ให้ยื่นใบลาออกต่อหุ้นส่วนผู้จัดการคนหนึ่งคนใด การลาออกมีผลนับแต่วันที่ใบลาออกไปถึงหุ้นส่วนผู้จัดการอื่นนั้น ในกรณีที่ห้างหุ้นส่วนจำกัดมีหุ้นส่วนผู้จัดการคนเดียว ให้หุ้นส่วนผู้จัดการที่จะลาออกจากตำแหน่งแจ้งเป็นหนังสือให้ผู้เป็นหุ้นส่วนคนหนึ่งคนใดทราบเพื่อนัดประชุมและพิจารณาตั้งหุ้นส่วนผู้จัดการคนใหม่ พร้อมกับแนบใบลาออกไปด้วย การลาออกมีผลนับแต่วันที่ใบลาออกไปถึงหุ้นส่วนผู้นั้น หุ้นส่วนผู้จัดการซึ่งลาออกตามวรรคหนึ่งหรือวรรคสอง จะแจ้งการลาออกของตนให้นายทะเบียนทราบด้วยก็ได้"}},{"id":"TH-H004-A1078.002","no":1078.002,"noLabel":{"th":"มาตรา 1078/2"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๗๘/๒ เมื่อมีการเปลี่ยนแปลงหุ้นส่วนผู้จัดการ ให้ห้างหุ้นส่วนจำกัดนำความไปจดทะเบียนภายในสิบสี่วันนับแต่วันที่มีการเปลี่ยนแปลง"}},{"id":"TH-H004-A1079","no":1079,"noLabel":{"th":"มาตรา 1079"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๗๙ อันห้างหุ้นส่วนจำกัดนั้น ถ้ายังมิได้จดทะเบียนอยู่ตราบใดท่านให้ถือว่าเป็นห้างหุ้นส่วนสามัญซึ่งผู้เป็นหุ้นส่วนทั้งหมดย่อมต้องรับผิดร่วมกันในบรรดาหนี้ของห้างหุ้นส่วนโดยไม่มีจำกัดจำนวน จนกว่าจะได้จดทะเบียน"}},{"id":"TH-H004-A1080","no":1080,"noLabel":{"th":"มาตรา 1080"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๐ บทบัญญัติว่าด้วยห้างหุ้นส่วนสามัญข้อใด ๆ หากมิได้ยกเว้นหรือแก้ไขเปลี่ยนแปลงไปโดยบทบัญญัติแห่งหมวด ๓ นี้ ท่านให้นำมาใช้บังคับแก่ห้างหุ้นส่วนจำกัดด้วย ถ้าผู้เป็นหุ้นส่วนจำพวกไม่จำกัดความรับผิดนั้นมีอยู่หลายคนด้วยกัน ท่านให้ใช้บทบัญญัติสำหรับห้างหุ้นส่วนสามัญเป็นวิธีบังคับในความเกี่ยวพันระหว่างคนเหล่านั้นเอง และความเกี่ยวพันระหว่างผู้เป็นหุ้นส่วนเหล่านั้นกับห้างหุ้นส่วน"}},{"id":"TH-H004-A1081","no":1081,"noLabel":{"th":"มาตรา 1081"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๑ ห้ามมิให้เอาชื่อของผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดมาเรียกขานระคนเป็นชื่อห้าง"}},{"id":"TH-H004-A1082","no":1082,"noLabel":{"th":"มาตรา 1082"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๒ ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดคนใดยินยอมโดยแสดงออกชัดหรือโดยปริยายให้ใช้ชื่อของตนระคนเป็นชื่อห้างไซร้ ท่านว่าผู้เป็นหุ้นส่วนคนนั้นจะต้องรับผิดต่อบุคคลภายนอกเสมือนดังว่าเป็นหุ้นส่วนจำพวกไม่จำกัดความรับผิดฉะนั้น แต่ในระหว่างผู้เป็นหุ้นส่วนกันเองนั้น ความรับผิดของผู้เป็นหุ้นส่วนเช่นนี้ ท่านให้คงบังคับตามสัญญาหุ้นส่วน"}},{"id":"TH-H004-A1083","no":1083,"noLabel":{"th":"มาตรา 1083"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๓ การลงหุ้นของผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดนั้น ท่านว่าต้องให้ลงเป็นเงินหรือทรัพย์สินอย่างอื่น ๆ"}},{"id":"TH-H004-A1084","no":1084,"noLabel":{"th":"มาตรา 1084"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๔ ห้ามมิให้แบ่งเงินปันผลหรือดอกเบี้ยให้แก่ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิด นอกจากผลกำไรซึ่งห้างหุ้นส่วนทำมาค้าได้ ถ้าทุนของห้างหุ้นส่วนลดน้อยลงไปเพราะค้าขายขาดทุน ท่านห้ามมิให้แบ่งเงินปันผลหรือดอกเบี้ยให้แก่ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิด จนกว่าทุนซึ่งขาดไปนั้นจะได้คืนมาเต็มจำนวนเดิม แต่ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดคนใดได้รับเงินปันผลหรือดอกเบี้ยไปแล้วโดยสุจริต ท่านว่าหาอาจจะบังคับให้เขาคืนเงินนั้นได้ไม่"}},{"id":"TH-H004-A1085","no":1085,"noLabel":{"th":"มาตรา 1085"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๕ ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดได้แสดงด้วยจดหมายหรือใบแจ้งความหรือด้วยวิธีอย่างอื่นให้บุคคลภายนอกทราบว่าตนได้ลงหุ้นไว้มากกว่าจำนวนซึ่งได้จดทะเบียนเพียงใด ท่านว่าผู้นั้นจะต้องรับผิดเท่าถึงจำนวนเพียงนั้น"}},{"id":"TH-H004-A1086","no":1086,"noLabel":{"th":"มาตรา 1086"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๖ ข้อซึ่งตกลงกันในระหว่างผู้เป็นหุ้นส่วนทั้งหลายเพื่อจะเปลี่ยนแปลงประเภททรัพย์สินที่ลงหุ้น หรือเพื่อจะลดจำนวนลงหุ้นแห่งผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดคนหนึ่งคนใดนั้น ท่านว่ายังไม่เป็นผลแก่บุคคลภายนอกจนกว่าจะได้จดทะเบียน เมื่อได้จดทะเบียนแล้วไซร้ ข้อตกลงนั้น ๆ ก็ย่อมมีผลแต่เพียงเฉพาะแก่หนี้อันห้างหุ้นส่วนได้ก่อให้เกิดขึ้นภายหลังเวลาที่ได้จดทะเบียนแล้วเท่านั้น"}},{"id":"TH-H004-A1087","no":1087,"noLabel":{"th":"มาตรา 1087"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๗ อันห้างหุ้นส่วนจำกัดนั้น ท่านว่าต้องให้แต่เฉพาะผู้เป็นหุ้นส่วนจำพวกไม่จำกัดความรับผิดเท่านั้นเป็นผู้จัดการ"}},{"id":"TH-H004-A1088","no":1088,"noLabel":{"th":"มาตรา 1088"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๘ ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดผู้ใดสอดเข้าไปเกี่ยวข้องจัดการงานของห้างหุ้นส่วน ท่านว่าผู้นั้นจะต้องรับผิดร่วมกันในบรรดาหนี้ทั้งหลายของห้างหุ้นส่วนนั้นโดยไม่จำกัดจำนวน แต่การออกความเห็นและแนะนำก็ดี ออกเสียงเป็นคะแนนนับในการตั้งและถอดถอนผู้จัดการตามกรณีที่มีบังคับไว้ในสัญญาหุ้นส่วนนั้นก็ดี ท่านหานับว่าเป็นการสอดเข้าไปเกี่ยวข้องจัดการงานของห้างหุ้นส่วนนั้นไม่"}},{"id":"TH-H004-A1089","no":1089,"noLabel":{"th":"มาตรา 1089"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๘๙ ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดนั้น จะตั้งให้เป็นผู้ชำระบัญชีของห้างหุ้นส่วนก็ได้"}},{"id":"TH-H004-A1090","no":1090,"noLabel":{"th":"มาตรา 1090"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๐ ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดจะประกอบการค้าขายอย่างใด ๆ เพื่อประโยชน์ตนหรือเพื่อประโยชน์บุคคลภายนอกก็ได้ แม้ว่าการงานเช่นนั้นจะมีสภาพเป็นอย่างเดียวกันกับการค้าขายของห้างหุ้นส่วนก็ไม่ห้าม"}},{"id":"TH-H004-A1091","no":1091,"noLabel":{"th":"มาตรา 1091"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๑ ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดจะโอนหุ้นของตนปราศจากความยินยอมของผู้เป็นหุ้นส่วนอื่น ๆ ก็โอนได้"}},{"id":"TH-H004-A1092","no":1092,"noLabel":{"th":"มาตรา 1092"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๒ การที่ผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดตายก็ดี ล้มละลายหรือตกเป็นคนไร้ความสามารถก็ดี หาเป็นเหตุให้ห้างหุ้นส่วนจำกัดต้องเลิกกันไม่ เว้นแต่จะได้มีข้อสัญญากันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1093","no":1093,"noLabel":{"th":"มาตรา 1093"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๓ ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดผู้ใดตาย ท่านว่าทายาทของผู้นั้นย่อมเข้าเป็นหุ้นส่วนแทนที่ผู้ตาย เว้นแต่จะได้มีข้อสัญญากันไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1094","no":1094,"noLabel":{"th":"มาตรา 1094"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๔ ถ้าผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดผู้ใดล้มละลาย ท่านว่าต้องเอาหุ้นของผู้นั้นในห้างหุ้นส่วนออกขายเป็นสินทรัพย์ในกองล้มละลาย"}},{"id":"TH-H004-A1095","no":1095,"noLabel":{"th":"มาตรา 1095"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๐๙๕ ตราบใดห้างหุ้นส่วนจำกัดยังมิได้เลิกกัน ตราบนั้นเจ้าหนี้ของห้างย่อมไม่มีสิทธิจะฟ้องร้องผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดได้ แต่เมื่อห้างหุ้นส่วนนั้นได้เลิกกันแล้ว เจ้าหนี้ของห้างมีสิทธิฟ้องร้องผู้เป็นหุ้นส่วนจำพวกจำกัดความรับผิดได้เพียงจำนวนดังนี้ คือ (๑) จำนวนลงหุ้นของผู้เป็นหุ้นส่วนเท่าที่ยังค้างส่งแก่ห้างหุ้นส่วน (๒) จำนวนลงหุ้นเท่าที่ผู้เป็นหุ้นส่วนได้ถอนไปจากสินทรัพย์ของห้างหุ้นส่วน (๓) จำนวนเงินปันผลและดอกเบี้ยซึ่งผู้เป็นหุ้นส่วนได้รับไปแล้วโดยทุจริตและฝ่าฝืนต่อบทมาตรา ๑๐๘๔"}},{"id":"TH-H004-A1096","no":1096,"noLabel":{"th":"มาตรา 1096"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๙๖ อันว่าบริษัทจำกัดนั้น คือบริษัทประเภทซึ่งตั้งขึ้นด้วยแบ่งทุนเป็นหุ้นมีมูลค่าเท่า ๆ กัน โดยผู้ถือหุ้นต่างรับผิดจำกัดเพียงไม่เกินจำนวนเงินที่ตนยังส่งใช้ไม่ครบมูลค่าของหุ้นที่ตนถือ"}},{"id":"TH-H004-A1096.2","no":1096.2,"noLabel":{"th":"มาตรา 1096 ทวิ"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๙๖ ทวิ (ยกเลิก)"}},{"id":"TH-H004-A1097","no":1097,"noLabel":{"th":"มาตรา 1097"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๙๗ บุคคลใด ๆ ตั้งแต่สองคนขึ้นไปจะเริ่มก่อการและตั้งเป็นบริษัทจำกัดก็ได้ โดยเข้าชื่อกันทำหนังสือบริคณห์สนธิ และกระทำการอย่างอื่นตามบทบัญญัติแห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A1098","no":1098,"noLabel":{"th":"มาตรา 1098"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๙๘ หนังสือบริคณห์สนธินั้น ต้องมีรายการดังต่อไปนี้ คือ (๑) ชื่อบริษัทอันคิดจะตั้งขึ้น ซึ่งต้องมีคำว่า “จำกัด” ไว้ปลายชื่อนั้นด้วยเสมอไป (๒) ที่สำนักงานของบริษัทซึ่งบอกทะเบียนนั้นจะตั้งอยู่ ณ ที่ใดในพระราชอาณาเขต (๓) วัตถุที่ประสงค์ทั้งหลายของบริษัท (๔) ถ้อยคำสำแดงว่า ความรับผิดของผู้ถือหุ้นจะมีจำกัด (๕) จำนวนทุนเรือนหุ้นซึ่งบริษัทคิดกำหนดจะจดทะเบียนแบ่งออกเป็นหุ้นมีมูลค่ากำหนดหุ้นละเท่าไร (๖) ชื่อ สำนัก อาชีวะ และลายมือชื่อของบรรดาผู้เริ่มก่อการ ทั้งจำนวนหุ้นซึ่งต่างคนต่างเข้าชื่อซื้อไว้คนละเท่าใด"}},{"id":"TH-H004-A1099","no":1099,"noLabel":{"th":"มาตรา 1099"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๐๙๙ หนังสือบริคณห์สนธินั้น ให้ทำเป็นต้นฉบับไว้ไม่น้อยกว่าสองฉบับ และให้ลงลายมือชื่อของบรรดาผู้เริ่มก่อการ โดยมีพยานลงชื่อรับรองด้วยสองคน และให้นำฉบับหนึ่งไปจดทะเบียน ถ้าการจดทะเบียนบริษัทมิได้ทำภายในสามปีนับแต่วันที่นายทะเบียนรับจดทะเบียนหนังสือบริคณห์สนธิ ให้หนังสือบริคณห์สนธินั้นสิ้นผล"}},{"id":"TH-H004-A1100","no":1100,"noLabel":{"th":"มาตรา 1100"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๐ ผู้เริ่มก่อการทุกคนต้องลงชื่อซื้อหุ้น ๆ หนึ่งเป็นอย่างน้อย"}},{"id":"TH-H004-A1101","no":1101,"noLabel":{"th":"มาตรา 1101"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๑ บุคคลซึ่งเป็นกรรมการของบริษัทจำกัดจะรับผิดโดยไม่จำกัดก็ได้ ถ้ากรณีเป็นเช่นนั้นไซร้ ท่านว่าต้องจดแถลงความรับผิดเช่นนั้นลงไว้ในหนังสือบริคณห์สนธิด้วย อันความรับผิดโดยไม่จำกัดของผู้เป็นกรรมการนั้น ย่อมถึงที่สุดเมื่อล่วงเวลาสองปีนับแต่วันที่ตัวเขาออกจากตำแหน่งกรรมการ"}},{"id":"TH-H004-A1102","no":1102,"noLabel":{"th":"มาตรา 1102"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๒ ห้ามมิให้ชี้ชวนประชาชนให้ซื้อหุ้น"}},{"id":"TH-H004-A1103","no":1103,"noLabel":{"th":"มาตรา 1103"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๓ (ยกเลิก)"}},{"id":"TH-H004-A1104","no":1104,"noLabel":{"th":"มาตรา 1104"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๔ จำนวนหุ้นทั้งหมดซึ่งบริษัทคิดจะจดทะเบียนนั้น ต้องมีผู้เข้าชื่อซื้อหรือออกให้กันเสร็จก่อนการจดทะเบียนของบริษัท"}},{"id":"TH-H004-A1105","no":1105,"noLabel":{"th":"มาตรา 1105"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๕ อันหุ้นนั้น ท่านห้ามมิให้ออกโดยราคาต่ำไปกว่ามูลค่าของหุ้นที่ตั้งไว้ การออกหุ้นโดยราคาสูงกว่ามูลค่าของหุ้นที่ตั้งไว้นั้น หากว่าหนังสือบริคณห์สนธิให้อำนาจไว้ ก็ให้ออกได้ และในกรณีเช่นนั้น ต้องส่งใช้จำนวนที่ล้ำมูลค่าพร้อมกันไปกับการส่งใช้เงินคราวแรก อนึ่ง เงินส่งใช้ค่าหุ้นคราวแรกนั้น ต้องมิให้น้อยกว่าร้อยละยี่สิบห้าแห่งมูลค่าของหุ้นที่ตั้งไว้"}},{"id":"TH-H004-A1106","no":1106,"noLabel":{"th":"มาตรา 1106"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๖ การที่เข้าชื่อซื้อหุ้นนั้นย่อมผูกพันผู้เข้าชื่อโดยเงื่อนไขว่า ถ้าบริษัทตั้งขึ้นแล้วจะใช้จำนวนเงินค่าหุ้นนั้น ๆ ให้แก่บริษัทตามหนังสือชี้ชวนและข้อบังคับของบริษัท"}},{"id":"TH-H004-A1107","no":1107,"noLabel":{"th":"มาตรา 1107"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๗ เมื่อหุ้นชนิดซึ่งจะต้องลงเงินนั้นได้มีผู้เข้าชื่อซื้อหมดแล้ว ผู้เริ่มก่อการต้องนัดบรรดาผู้เข้าชื่อซื้อหุ้นมาประชุมกันเป็นการประชุมใหญ่โดยไม่ชักช้า ประชุมอันนี้ให้เรียกว่าประชุมตั้งบริษัท อนึ่ง ให้ผู้เริ่มก่อการส่งรายงานการตั้งบริษัทมีคำรับรองของตนว่าถูกต้องและมีข้อความที่เกี่ยวแก่กิจการอันจะพึงกระทำในที่ประชุมตั้งบริษัททุก ๆ ข้อตามความในมาตราต่อไปนี้ ไปยังผู้เข้าชื่อซื้อหุ้นทุกคนอย่างน้อยเจ็ดวันก่อนวันนัดประชุม เมื่อได้ส่งรายงานตั้งบริษัทแก่ผู้เข้าชื่อซื้อหุ้นแล้ว ผู้เริ่มก่อการต้องจัดส่งสำเนารายงานอันมีคำรับรองว่าถูกต้องตามที่บังคับไว้ในมาตรานี้ไปยังนายทะเบียนบริษัทโดยพลัน อนึ่ง ให้ผู้เริ่มก่อการจัดให้มีบัญชีแถลงรายชื่อ ฐานะ และสำนักของผู้เข้าชื่อซื้อหุ้นกับจำนวนหุ้นซึ่งต่างคนได้ลงชื่อซื้อไว้เพื่อเสนอต่อที่ประชุมนั้นด้วย บทบัญญัติทั้งหลายแห่งมาตรา ๑๑๗๖ มาตรา ๑๑๘๗ มาตรา ๑๑๘๘ มาตรา ๑๑๘๙ มาตรา ๑๑๙๑ มาตรา ๑๑๙๒ และมาตรา ๑๑๙๕ นั้น ท่านให้นำมาใช้บังคับแก่การประชุมตั้งบริษัทด้วยโดยอนุโลม"}},{"id":"TH-H004-A1108","no":1108,"noLabel":{"th":"มาตรา 1108"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๘ กิจการอันจะพึงทำในที่ประชุมตั้งบริษัทนั้น คือ (๑) ทำความตกลงตั้งข้อบังคับต่าง ๆ ของบริษัท ทั้งนี้ ควรกำหนดวิธีการแก้ไขปัญหาหรือข้อขัดแย้งที่ไม่สามารถหาข้อยุติหรือไม่สามารถลงมติระหว่างกรรมการหรือผู้ถือหุ้นไว้ด้วย (๒) ให้สัตยาบันแก่บรรดาสัญญาซึ่งผู้เริ่มก่อการได้ทำไว้และค่าใช้จ่ายอย่างหนึ่งอย่างใดซึ่งเขาต้องออกไปในการเริ่มก่อบริษัท (๓) วางกำหนดจำนวนเงินซึ่งจะให้แก่ผู้เริ่มก่อการ ถ้าหากมีเจตนาว่าจะให้ (๔) วางกำหนดจำนวนหุ้นบุริมสิทธิ ทั้งกำหนดสภาพและบุริมสิทธิแห่งหุ้นนั้น ๆ ว่าเป็นสถานใดเพียงใด ถ้าหากจะมีหุ้นเช่นนั้นในบริษัท (๕) วางกำหนดจำนวนหุ้นสามัญ หรือหุ้นบุริมสิทธิซึ่งออกให้เหมือนหนึ่งว่าได้ใช้เต็มค่าแล้วหรือได้ใช้แต่บางส่วนแล้ว เพราะใช้ให้ด้วยอย่างอื่นนอกจากตัวเงิน และกำหนดว่าเพียงใดซึ่งจะถือเอาเป็นว่าได้ใช้เงินแล้ว ถ้าหากจะมีหุ้นเช่นนั้นในบริษัท ให้แถลงในที่ประชุมโดยเฉพาะว่า ซึ่งจะออกหุ้นสามัญหรือหุ้นบุริมสิทธิให้เหมือนหนึ่งว่าได้ใช้เงินแล้วเช่นนั้น เพื่อแทนคุณแรงงานหรือตอบแทนทรัพย์สินอย่างใด ให้พรรณนาจงชัดเจนทุกประการ (๖) เลือกตั้งกรรมการและพนักงานสอบบัญชีอันเป็นชุดแรกของบริษัท และวางกำหนดอำนาจของคนเหล่านี้ด้วย"}},{"id":"TH-H004-A1109","no":1109,"noLabel":{"th":"มาตรา 1109"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๐๙ ผู้เริ่มก่อการหรือผู้เข้าชื่อซื้อหุ้นจะออกเสียงลงคะแนนไม่ได้ ถ้าตนมีส่วนได้เสียโดยพิเศษในปัญหาที่ยกขึ้นวินิจฉัยนั้น อนึ่ง มติของที่ประชุมตั้งบริษัทย่อมไม่สมบูรณ์ เว้นแต่ที่ประชุมจะได้ลงมติโดยเสียงข้างมาก อันมีคะแนนของผู้เข้าชื่อซื้อหุ้นรวมกันไม่น้อยกว่ากึ่งจำนวนผู้เข้าชื่อซื้อหุ้นทั้งหมดซึ่งมีสิทธิลงคะแนนได้ และคิดตามจำนวนหุ้นรวมกันไม่น้อยกว่ากึ่งจำนวนหุ้นของผู้ถือหุ้นนั้น ๆ ทั้งหมดด้วยกัน"}},{"id":"TH-H004-A1110","no":1110,"noLabel":{"th":"มาตรา 1110"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๐ เมื่อได้ประชุมตั้งบริษัทแล้ว ให้ผู้เริ่มก่อการบริษัทมอบการทั้งปวงให้แก่กรรมการของบริษัท เมื่อกรรมการได้รับการแล้ว ก็ให้ลงมือจัดการเรียกให้ผู้เริ่มก่อการและผู้เข้าชื่อซื้อหุ้นทั้งหลายใช้เงินในหุ้นซึ่งจะต้องใช้เป็นตัวเงิน เรียกหุ้นหนึ่งไม่น้อยกว่าร้อยละยี่สิบห้า ตามที่ได้กำหนดไว้ในหนังสือชี้ชวนบอกกล่าวป่าวร้องหรือหนังสือชวนให้ซื้อหุ้น"}},{"id":"TH-H004-A1111","no":1111,"noLabel":{"th":"มาตรา 1111"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๑ เมื่อจำนวนเงินซึ่งว่าไว้ในมาตรา ๑๑๑๐ ได้ใช้เสร็จแล้ว กรรมการต้องไปขอจดทะเบียนบริษัทนั้น คำขอและข้อความที่ลงในทะเบียนนั้น ให้ระบุรายการตามที่ได้ตกลงกันในที่ประชุมตั้งบริษัท ดังต่อไปนี้ คือ (๑) จำนวนหุ้นทั้งสิ้นซึ่งได้มีผู้เข้าชื่อซื้อ หรือได้จัดออกให้แล้ว แยกให้ปรากฏว่าเป็นชนิดหุ้นสามัญเท่าใด หุ้นบุริมสิทธิเท่าใด (๒) จำนวนหุ้นสามัญหรือหุ้นบุริมสิทธิ ซึ่งออกให้เหมือนหนึ่งว่าได้ใช้เต็มค่าแล้วหรือได้ใช้แต่บางส่วนแล้ว นอกจากที่ใช้เป็นตัวเงิน และหุ้นที่ได้ใช้แต่บางส่วนนั้น ให้บอกว่าได้ใช้แล้วเพียงใด (๓) จำนวนเงินที่ได้ใช้แล้วหุ้นละเท่าใด (๔) จำนวนเงินที่ได้รับไว้เป็นค่าหุ้นรวมทั้งสิ้นเท่าใด (๕) ชื่อ อาชีวะ และที่สำนักของกรรมการทุกคน (๖) ถ้าให้กรรมการต่างมีอำนาจจัดการของบริษัทได้โดยลำพังตัวให้แสดงอำนาจของกรรมการนั้น ๆ ว่าคนใดมีเพียงใด และบอกจำนวนหรือชื่อกรรมการซึ่งจะลงชื่อเป็นสำคัญผูกพันบริษัทได้นั้นด้วย (๗) ถ้าตั้งบริษัทขึ้นชั่วกาลกำหนดอันหนึ่ง ให้บอกกาลกำหนดอันนั้นด้วย (๘) ที่ตั้งสำนักงานแห่งใหญ่และสาขาทั้งปวง การลงทะเบียนจะมีรายการอย่างอื่นซึ่งกรรมการเห็นสมควรจะให้ทราบแก่ประชาชนก็ลงได้ ในการขอจดทะเบียนนั้น ถ้าได้ทำข้อบังคับของบริษัทไว้ประการใดบ้างต้องส่งสำเนาข้อบังคับนั้น ๆ ไปด้วย กับทั้งสำเนารายงานการประชุมตั้งบริษัทหนังสือทั้งสองนี้กรรมการต้องลงลายมือชื่อรับรองคนหนึ่งเป็นอย่างน้อย วรรคห้า (ยกเลิก) ให้พนักงานทะเบียนทำใบสำคัญแสดงการจดทะเบียนส่งมอบให้แก่บริษัทฉบับหนึ่ง"}},{"id":"TH-H004-A1111.001","no":1111.001,"noLabel":{"th":"มาตรา 1111/1"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๑/๑ ในการจัดตั้งบริษัท ถ้าได้ดำเนินการครบทุกขั้นตอนดังต่อไปนี้ภายในวันเดียวกับวันที่ผู้เริ่มก่อการจัดทำหนังสือบริคณห์สนธิ กรรมการจะขอจดทะเบียนหนังสือบริคณห์สนธิและจดทะเบียนบริษัทไปพร้อมกันภายในวันเดียวกันก็ได้ (๑) จัดให้มีผู้เข้าชื่อซื้อหุ้นครบตามจำนวนหุ้นทั้งหมดที่บริษัทจะจดทะเบียน (๒) ประชุมจัดตั้งบริษัทเพื่อพิจารณากิจการต่างๆ ตามมาตรา ๑๑๐๘ โดยมีผู้เริ่มก่อการและผู้เข้าชื่อซื้อหุ้นทุกคนเข้าร่วมประชุม และผู้เริ่มก่อการและผู้เข้าชื่อซื้อหุ้นทุกคนให้ความเห็นชอบในกิจการที่ได้ประชุมกันนั้น (๓) ผู้เริ่มก่อการได้มอบกิจการทั้งปวงให้แก่กรรมการ (๔) กรรมการได้เรียกให้ผู้เข้าชื่อซื้อหุ้นใช้เงินค่าหุ้นตามมาตรา ๑๑๑๐ วรรคสอง และเงินค่าหุ้นดังกล่าวได้ใช้เสร็จแล้ว"}},{"id":"TH-H004-A1112","no":1112,"noLabel":{"th":"มาตรา 1112"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๒ ถ้าการจดทะเบียนมิได้ทำภายในสามเดือนนับแต่ประชุมตั้งบริษัทไซร้ ท่านว่าบริษัทนั้นเป็นอันไม่ได้ตั้งขึ้น และบรรดาเงินที่ได้รับไว้จากผู้เข้าชื่อซื้อหุ้นนั้นต้องใช้คืนเต็มจำนวนมิให้ลดเลย ถ้ามีจำนวนเงินเช่นว่านั้นค้างอยู่มิได้คืนในสามเดือนภายหลังการประชุมตั้งบริษัทไซร้ ท่านว่ากรรมการของบริษัทต้องรับผิดร่วมกันที่จะใช้ทั้งต้นเงินและดอกเบี้ยคิดตั้งแต่เวลาสิ้นกำหนดสามเดือนนั้น แต่ถ้ากรรมการคนใดพิสูจน์ได้ว่า การที่เงินขาดหรือที่ใช้คืนช้าไปมิได้เป็นเพราะความผิดของตนไซร้ กรรมการคนนั้นก็ไม่ต้องรับผิดในการใช้ต้นเงินหรือดอกเบี้ย"}},{"id":"TH-H004-A1113","no":1113,"noLabel":{"th":"มาตรา 1113"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๓ ผู้เริ่มก่อการบริษัทต้องรับผิดร่วมกันและโดยไม่จำกัด ในบรรดาหนี้และการจ่ายเงินซึ่งที่ประชุมตั้งบริษัทมิได้อนุมัติ และแม้จะได้มีอนุมัติก็ยังคงต้องรับผิดอยู่เช่นนั้นไปจนกว่าจะได้จดทะเบียนบริษัท"}},{"id":"TH-H004-A1114","no":1114,"noLabel":{"th":"มาตรา 1114"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๔ เมื่อบริษัทได้จดทะเบียนแล้ว ผู้เข้าชื่อซื้อหุ้นจะฟ้องร้องขอให้ศาลเพิกถอนการที่ตนได้เข้าชื่อซื้อ โดยยกเหตุว่าสำคัญผิด หรือต้องข่มขู่ หรือถูกลวงล่อฉ้อฉลนั้น ท่านว่าหาอาจทำได้ไม่"}},{"id":"TH-H004-A1115","no":1115,"noLabel":{"th":"มาตรา 1115"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๕ ถ้าหากว่าชื่อบริษัทซึ่งตั้งไว้ในหนังสือบริคณห์สนธิพ้องกับชื่อบริษัทอื่นซึ่งได้จดทะเบียนแล้วก็ดี หรือพ้องกับชื่อซึ่งตั้งไว้ในหนังสือบริคณห์สนธิฉบับอื่นอันได้จดทะเบียนแล้วก็ดี หรือคล้ายคลึงกับชื่อเช่นกล่าวนั้นจนน่าจะลวงให้มหาชนหลงไปได้ก็ดี ท่านว่าบุคคลผู้ที่มีส่วนได้เสียคนหนึ่งคนใดจะฟ้องเรียกเอาค่าสินไหมทดแทนแก่ผู้เริ่มก่อการบริษัทก็ได้ และจะร้องขอให้ศาลสั่งบังคับให้เปลี่ยนชื่อนั้นเสียใหม่ก็ได้ เมื่อศาลมีคำสั่งเช่นนั้นแล้ว ก็ต้องบอกชื่อซึ่งเปลี่ยนใหม่นั้นจดทะเบียนแทนชื่อเก่า และต้องแก้ใบสำคัญการจดทะเบียนด้วยตามกันไป"}},{"id":"TH-H004-A1116","no":1116,"noLabel":{"th":"มาตรา 1116"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๑๑๖ บุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งประสงค์จะได้สำเนาหนังสือบริคณห์สนธิและข้อบังคับบรรดามีในบริษัทหนึ่งบริษัทใด ก็ชอบที่จะเรียกได้จากบริษัทนั้น ในการนี้บริษัทจะเรียกเอาเงินไม่เกินฉบับละสิบบาทก็ได้"}},{"id":"TH-H004-A1117","no":1117,"noLabel":{"th":"มาตรา 1117"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๑๗ อันมูลค่าของหุ้น ๆ หนึ่งนั้น มิให้ต่ำกว่าห้าบาท"}},{"id":"TH-H004-A1118","no":1118,"noLabel":{"th":"มาตรา 1118"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๑๘ อันหุ้นนั้น ท่านว่าจะแบ่งแยกหาได้ไม่ ถ้าบุคคลมีจำนวนแต่สองคนขึ้นไปถือหุ้น ๆ เดียวร่วมกัน ท่านว่าต้องตั้งให้คนใดคนหนึ่งในจำนวนนั้นแต่คนเดียวเป็นผู้ใช้สิทธิในฐานเป็นผู้ถือหุ้น อนึ่ง บุคคลทั้งหลายซึ่งถือหุ้น ๆ เดียวร่วมกัน ต้องร่วมกันรับผิดต่อบริษัทในการส่งใช้มูลค่าของหุ้น"}},{"id":"TH-H004-A1119","no":1119,"noLabel":{"th":"มาตรา 1119"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๑๙ หุ้นทุก ๆ หุ้นจำต้องให้ใช้เป็นเงินจนเต็มค่า เว้นแต่หุ้นซึ่งออกตามบทบัญญัติมาตรา ๑๑๐๘ อนุมาตรา (๕) หรือมาตรา ๑๒๒๑ ในการใช้เงินเป็นค่าหุ้นนั้น ผู้ถือหุ้นจะหักหนี้กับบริษัทหาได้ไม่"}},{"id":"TH-H004-A1120","no":1120,"noLabel":{"th":"มาตรา 1120"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๐ บรรดาเงินค่าหุ้นซึ่งยังจะต้องส่งอีกนั้น กรรมการจะเรียกให้ผู้ถือหุ้นส่งใช้เสียเมื่อใดก็ได้ เว้นแต่ที่ประชุมใหญ่จะได้วินิจฉัยเป็นอย่างอื่น"}},{"id":"TH-H004-A1121","no":1121,"noLabel":{"th":"มาตรา 1121"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๑ การเรียกเงินค่าหุ้นแต่ละคราวนั้น ท่านบังคับว่าให้ส่งคำบอกกล่าวล่วงหน้าไม่ต่ำกว่ายี่สิบเอ็ดวันด้วย จดหมายส่งลงทะเบียนไปรษณีย์ และผู้ถือหุ้นทุกคนจะต้องใช้เงินตามจำนวนที่เรียกนั้น สุดแต่กรรมการจะได้กำหนดไปว่าให้ส่งไปยังผู้ใด ณ ที่ใดและเวลาใด"}},{"id":"TH-H004-A1122","no":1122,"noLabel":{"th":"มาตรา 1122"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๒ ถ้าและเงินอันจะพึงส่งใช้เป็นค่าหุ้นตามเรียกนั้นผู้ถือหุ้นคนใดมิได้ส่งใช้ตามวันกำหนดไซร้ ผู้นั้นจำต้องเสียดอกเบี้ยนับแต่วันที่กำหนดให้ส่งใช้จนถึงวันที่ได้ส่งเสร็จ"}},{"id":"TH-H004-A1123","no":1123,"noLabel":{"th":"มาตรา 1123"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๓ ถ้าผู้ถือหุ้นคนใดละเลยไม่ส่งใช้เงินที่เรียกค่าหุ้นตามวันกำหนด กรรมการจะส่งคำบอกกล่าวด้วยจดหมายส่งลงทะเบียนไปรษณีย์ไปยังผู้นั้น ให้ส่งใช้เงินที่เรียกกับทั้งดอกเบี้ยด้วยก็ได้ ในคำบอกกล่าวอันนี้ ให้กำหนดเวลาไปพอสมควรเพื่อให้ใช้เงินที่เรียกกับทั้งดอกเบี้ย และต้องบอกไปด้วยว่าให้ส่งใช้ ณ สถานที่ใด อนึ่ง ในคำบอกกล่าวนั้นจะแจ้งไปด้วยก็ได้ว่า ถ้าไม่ใช้เงินตามเรียก หุ้นนั้นอาจจะถูกริบ"}},{"id":"TH-H004-A1124","no":1124,"noLabel":{"th":"มาตรา 1124"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๔ ถ้าในคำบอกกล่าวมีข้อแถลงความถึงการริบหุ้นด้วยแล้ว หากเงินค่าหุ้นที่เรียกกับทั้งดอกเบี้ยยังคงค้างชำระอยู่ตราบใด กรรมการจะบอกริบหุ้นนั้น ๆ เมื่อใดก็ได้"}},{"id":"TH-H004-A1125","no":1125,"noLabel":{"th":"มาตรา 1125"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๕ หุ้นซึ่งริบแล้วนั้นให้เอาออกขายทอดตลาดโดยไม่ชักช้า ได้จำนวนเงินเท่าใดให้เอาหักใช้ค่าหุ้นที่เรียกกับดอกเบี้ยค้างชำระ ถ้ายังมีเงินเหลือเท่าใดต้องส่งคืนให้แก่ผู้ถือหุ้นนั้น"}},{"id":"TH-H004-A1126","no":1126,"noLabel":{"th":"มาตรา 1126"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๖ แม้ว่าวิธีการริบหุ้นขายหุ้นจะไม่ถูกต้องด้วยระเบียบก็ดี ท่านว่าหาเป็นเหตุให้สิทธิของผู้ซื้อหุ้นซึ่งริบนั้นเสื่อมเสียไปอย่างไรไม่"}},{"id":"TH-H004-A1127","no":1127,"noLabel":{"th":"มาตรา 1127"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๗ ให้บริษัททำใบหุ้น คือใบสำคัญสำหรับหุ้นใบหนึ่งหรือหลายใบ มอบให้เป็นคู่มือแก่ผู้ถือหุ้นจงทุก ๆ คน เมื่อมอบใบหุ้นนั้น จะเรียกค่าธรรมเนียมก็ได้ สุดแต่กรรมการจะกำหนด แต่มิให้เกินสิบบาท"}},{"id":"TH-H004-A1128","no":1128,"noLabel":{"th":"มาตรา 1128"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๘ ในใบหุ้นทุก ๆ ใบให้กรรมการอย่างน้อยหนึ่งคนลงลายมือชื่อและประทับตราของบริษัทถ้ามี ในใบหุ้นนั้นต้องมีข้อความต่อไปนี้ คือ (๑) ชื่อบริษัท (๒) เลขหมายหุ้นที่กล่าวถึงในใบหุ้นนั้น (๓) มูลค่าหุ้นหนึ่งเป็นเงินเท่าใด (๔) ถ้าและเป็นหุ้นที่ยังไม่ได้ใช้เงินเสร็จ ให้จัดลงว่าได้ใช้เงินค่าหุ้นแล้วหุ้นละเท่าใด (๕) ชื่อผู้ถือหุ้น หรือคำแถลงว่าได้ออกใบหุ้นนั้นให้แก่ผู้ถือ"}},{"id":"TH-H004-A1129","no":1129,"noLabel":{"th":"มาตรา 1129"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๒๙ อันว่าหุ้นนั้นย่อมโอนกันได้โดยมิต้องได้รับความยินยอมของบริษัท เว้นแต่เมื่อเป็นหุ้นชนิดระบุชื่อลงในใบหุ้น ซึ่งมีข้อบังคับของบริษัทกำหนดไว้เป็นอย่างอื่น การโอนหุ้นชนิดระบุชื่อลงในใบหุ้นนั้น ถ้ามิได้ทำเป็นหนังสือและลงลายมือชื่อของผู้โอนกับผู้รับโอน มีพยานคนหนึ่งเป็นอย่างน้อยลงชื่อรับรองลายมือนั้น ๆ ด้วยแล้ว ท่านว่าเป็นโมฆะ อนึ่ง ตราสารอันนั้นต้องแถลงเลขหมายของหุ้นซึ่งโอนกันนั้นด้วย การโอนเช่นนี้จะนำมาใช้แก่บริษัทหรือบุคคลภายนอกไม่ได้ จนกว่าจะได้จดแจ้งการโอนทั้งชื่อและสำนักของผู้รับโอนนั้นลงในทะเบียนผู้ถือหุ้น"}},{"id":"TH-H004-A1130","no":1130,"noLabel":{"th":"มาตรา 1130"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๐ หุ้นใดเงินที่เรียกค่าหุ้นยังค้างชำระอยู่ หุ้นนั้นบริษัทจะไม่ยอมรับจดทะเบียนให้โอนก็ได้"}},{"id":"TH-H004-A1131","no":1131,"noLabel":{"th":"มาตรา 1131"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๑ ในระหว่างสิบสี่วันก่อนการประชุมใหญ่สามัญ บริษัทจะปิดสมุดทะเบียนพักการโอนหุ้นเสียก็ได้"}},{"id":"TH-H004-A1132","no":1132,"noLabel":{"th":"มาตรา 1132"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๒ ในเหตุบางอย่างเช่นผู้ถือหุ้นตายก็ดี หรือล้มละลายก็ดี อันเป็นเหตุให้บุคคลอื่นเป็นผู้มีสิทธิจะได้หุ้นขึ้นนั้น หากว่าบุคคลนั้นนำใบหุ้นมาเวนคืน เมื่อเป็นวิสัยจะทำได้ ทั้งได้นำหลักฐานอันสมควรมาแสดงด้วยแล้ว ก็ให้บริษัทรับบุคคลนั้นลงทะเบียนเป็นผู้ถือหุ้นสืบไป"}},{"id":"TH-H004-A1133","no":1133,"noLabel":{"th":"มาตรา 1133"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๓ หุ้นซึ่งโอนกันนั้น ถ้าเป็นหุ้นอันมิได้ส่งเงินใช้เต็มจำนวนค่าหุ้น ท่านว่าผู้โอนยังคงต้องรับผิดในจำนวนเงินที่ยังมิได้ส่งใช้ให้ครบถ้วนนั้น แต่ว่า (๑) ผู้โอนไม่ต้องรับผิดในหนี้อันหนึ่งอันใดของบริษัทซึ่งได้ก่อให้เกิดขึ้นภายหลังโอน (๒) ผู้โอนไม่ต้องรับผิดออกส่วนใช้หนี้ เว้นแต่ความปรากฏขึ้นแก่ศาลว่าบรรดาผู้ที่ยังถือหุ้นของบริษัทอยู่นั้นไม่สามารถออกส่วนใช้หนี้อันเขาจะพึงต้องออกใช้นั้นได้ ในข้อความรับผิดเช่นว่ามานั้น ท่านห้ามมิให้ฟ้องผู้โอนเมื่อพ้นสองปีนับแต่ได้จดแจ้งการโอนนั้นลงในทะเบียนผู้ถือหุ้น"}},{"id":"TH-H004-A1134","no":1134,"noLabel":{"th":"มาตรา 1134"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๔ ใบหุ้นออกให้แก่ผู้ถือนั้น จะออกได้ก็แต่เมื่อมีข้อบังคับของบริษัทอนุญาตไว้ และจะออกให้ได้แต่เฉพาะเพื่อหุ้นซึ่งได้ใช้เต็มค่าแล้ว ในกรณีเช่นว่านี้ ผู้ทรงใบหุ้นชนิดระบุชื่อย่อมมีสิทธิจะได้รับใบหุ้นชนิดออกให้แก่ผู้ถือ เมื่อเวนคืนใบหุ้นชนิดระบุชื่อนั้นให้ขีดฆ่าเสีย"}},{"id":"TH-H004-A1135","no":1135,"noLabel":{"th":"มาตรา 1135"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๕ หุ้นชนิดที่มีใบหุ้นออกให้แก่ผู้ถือนั้น ย่อมโอนกันได้เพียงด้วยส่งมอบใบหุ้นแก่กัน"}},{"id":"TH-H004-A1136","no":1136,"noLabel":{"th":"มาตรา 1136"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๖ ผู้ทรงใบหุ้นชนิดออกให้แก่ผู้ถือย่อมมีสิทธิจะมาขอเปลี่ยนเอาใบหุ้นชนิดระบุชื่อได้ เมื่อเวนคืนใบหุ้นฉบับออกให้แก่ผู้ถือนั้นให้ขีดฆ่าเสีย"}},{"id":"TH-H004-A1137","no":1137,"noLabel":{"th":"มาตรา 1137"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๗ ถ้าข้อบังคับของบริษัทมีกำหนดไว้เป็นองค์คุณอันหนึ่งสำหรับผู้จะเป็นกรรมการ ว่าจำจะต้องเป็นผู้ถือหุ้นเป็นจำนวนเท่าหนึ่งใดไซร้ หุ้นเช่นนี้ท่านว่าต้องเป็นหุ้นชนิดระบุชื่อ"}},{"id":"TH-H004-A1138","no":1138,"noLabel":{"th":"มาตรา 1138"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๘ บริษัทจำกัดต้องมีสมุดทะเบียนผู้ถือหุ้น มีรายการดั่งต่อไปนี้ คือ (๑) ชื่อและสำนัก กับอาชีวะ ถ้าว่ามี ของผู้ถือหุ้น ข้อแถลงเรื่องหุ้นของผู้ถือหุ้นคนหนึ่ง ๆ แยกหุ้นออกตามเลขหมายและจำนวนเงินที่ได้ใช้แล้วหรือที่ได้ตกลงกันให้ถือว่าเป็นอันได้ใช้แล้วในหุ้นของผู้ถือหุ้นคนหนึ่ง ๆ (๒) วันเดือนปีซึ่งได้ลงทะเบียนบุคคลผู้หนึ่ง ๆ เป็นผู้ถือหุ้น (๓) วันเดือนปีซึ่งบุคคลคนใดคนหนึ่งขาดจากเป็นผู้ถือหุ้น (๔) เลขหมายใบหุ้นและวันที่ลงในใบหุ้นชนิดออกให้แก่ผู้ถือ และเลขหมายของหุ้นซึ่งได้ลงไว้ในใบหุ้นนั้น ๆ (๕) วันที่ได้ขีดฆ่าใบหุ้นชนิดระบุชื่อ หรือชนิดออกให้แก่ผู้ถือ"}},{"id":"TH-H004-A1139","no":1139,"noLabel":{"th":"มาตรา 1139"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๓๙ สมุดทะเบียนผู้ถือหุ้นเริ่มแต่วันจดทะเบียนบริษัทนั้นให้รักษาไว้ ณ สำนักงานของบริษัทแห่งที่ได้บอกทะเบียนไว้ สมุดทะเบียนนี้ให้เปิดให้แก่ผู้ถือหุ้นทั้งหลายดูได้ในระหว่างเวลาทำการโดยไม่เรียกค่าธรรมเนียมอย่างหนึ่งอย่างใด แต่กรรมการจะจำกัดเวลาลงไว้อย่างไรพอสมควรก็ได้หากไม่น้อยกว่าวันละสองชั่วโมง ให้เป็นหน้าที่ของกรรมการที่จะส่งสำเนาบัญชีรายชื่อผู้ที่ยังคงเป็นผู้ถือหุ้นอยู่ทั้งหมดในเวลาที่ประชุม และรายชื่อผู้ที่ขาดจากเป็นผู้ถือหุ้นจำเดิมแต่วันประชุมสามัญครั้งที่แล้วมานั้น ไปยังนายทะเบียนอย่างน้อยปีละครั้ง และมิให้ช้ากว่าวันที่สิบสี่นับแต่การประชุมสามัญ บัญชีรายชื่อนี้ให้มีรายการบรรดาที่ระบุไว้ในมาตราก่อนนั้นทุกประการ"}},{"id":"TH-H004-A1140","no":1140,"noLabel":{"th":"มาตรา 1140"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๔๐ ผู้ถือหุ้นชอบที่จะเรียกให้ส่งมอบสำเนาทะเบียนเช่นว่านั้นหรือแต่ตอนหนึ่งตอนใดแก่ตนได้ เมื่อเสียค่าสำเนาแต่ไม่เกินหน้าละห้าบาท"}},{"id":"TH-H004-A1141","no":1141,"noLabel":{"th":"มาตรา 1141"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๔๑ สมุดทะเบียนผู้ถือหุ้นนั้น ท่านให้สันนิษฐานไว้ก่อนว่าเป็นพยานหลักฐานอันถูกต้องในข้อกระทงความบรรดาที่กฎหมายบังคับ หรือให้อำนาจให้เอาลงในทะเบียนนั้น"}},{"id":"TH-H004-A1142","no":1142,"noLabel":{"th":"มาตรา 1142"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๔๒ ถ้าบริษัทได้ออกหุ้นบุริมสิทธิไปแล้ว ได้กำหนดไว้ว่าบุริมสิทธิจะมีแก่หุ้นนั้น ๆ เป็นอย่างไร ท่านห้ามมิให้แก้ไขอีกเลย"}},{"id":"TH-H004-A1143","no":1143,"noLabel":{"th":"มาตรา 1143"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๑๔๓ ห้ามมิให้บริษัทจำกัดเป็นเจ้าของถือหุ้นของตนเอง หรือรับจำนำหุ้นของตนเอง"}},{"id":"TH-H004-A1144","no":1144,"noLabel":{"th":"มาตรา 1144"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๔ บรรดาบริษัทจำกัด ให้มีกรรมการคนหนึ่งหรือหลายคนด้วยกันจัดการตามข้อบังคับของบริษัท และอยู่ในความครอบงำของที่ประชุมใหญ่แห่งผู้ถือหุ้นทั้งปวง"}},{"id":"TH-H004-A1145","no":1145,"noLabel":{"th":"มาตรา 1145"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๕ จำเดิมแต่ได้จดทะเบียนบริษัทแล้ว ท่านห้ามมิให้ตั้งข้อบังคับใหม่ หรือเพิ่มเติมเปลี่ยนแปลงข้อบังคับหรือข้อความในหนังสือบริคณห์สนธิแต่อย่างหนึ่งอย่างใด เว้นแต่จะได้มีการลงมติพิเศษ"}},{"id":"TH-H004-A1146","no":1146,"noLabel":{"th":"มาตรา 1146"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๖ บรรดาข้อบังคับอันได้ตั้งขึ้นใหม่ หรือได้เพิ่มเติมเปลี่ยนแปลงนั้น เป็นหน้าที่ของบริษัทที่จะจัดให้ไปจดทะเบียนภายในกำหนดสิบสี่วันนับแต่วันที่ได้มีการลงมติพิเศษ"}},{"id":"TH-H004-A1147","no":1147,"noLabel":{"th":"มาตรา 1147"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๗ (ยกเลิก)"}},{"id":"TH-H004-A1148","no":1148,"noLabel":{"th":"มาตรา 1148"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๘ บรรดาบริษัทจำกัด ต้องมีสำนักงานบอกทะเบียนไว้แห่งหนึ่งซึ่งธุรการติดต่อและคำบอกกล่าวทั้งปวงจะส่งถึงบริษัทได้ ณ ที่นั้น คำบอกกล่าวสถานที่ตั้งแห่งสำนักงานที่ได้บอกทะเบียนไว้ก็ดี หรือเปลี่ยนย้ายสถานที่ก็ดี ให้ส่งแก่นายทะเบียนบริษัทและให้นายทะเบียนจดข้อความนั้นลงในทะเบียน"}},{"id":"TH-H004-A1149","no":1149,"noLabel":{"th":"มาตรา 1149"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๔๙ ตราบใดหุ้นทั้งหลายยังมิได้ชำระเงินเต็มจำนวน ท่านว่าตราบนั้นบริษัทจะลงพิมพ์หรือแสดงจำนวนต้นทุนของบริษัทในหนังสืออย่างหนึ่งอย่างใดเช่นในคำบอกกล่าวป่าวร้องก็ดี ในตั๋วเงินและบัญชีสิ่งของก็ดี ในจดหมายก็ดี ต้องแสดงไว้ให้ชัดเจนด้วยในทีเดียวกันว่า จำนวนเงินต้นทุนได้ชำระแล้วเพียงกี่ส่วน"}},{"id":"TH-H004-A1150","no":1150,"noLabel":{"th":"มาตรา 1150"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๐ ผู้เป็นกรรมการจะพึงมีจำนวนมากน้อยเท่าใด และจะพึงได้บำเหน็จเท่าใด ให้สุดแล้วแต่ที่ประชุมใหญ่จะกำหนด"}},{"id":"TH-H004-A1151","no":1151,"noLabel":{"th":"มาตรา 1151"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๑ อันผู้เป็นกรรมการนั้น เฉพาะแต่ที่ประชุมใหญ่เท่านั้นอาจจะตั้งหรือถอนได้"}},{"id":"TH-H004-A1152","no":1152,"noLabel":{"th":"มาตรา 1152"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๒ ในเมื่อมีการประชุมสามัญครั้งแรกภายหลังแต่จดทะเบียนบริษัทก็ดี และในเมื่อมีการประชุมสามัญครั้งแรกในปีทุก ๆ ปีต่อไปก็ดี ผู้เป็นกรรมการต้องออกจากตำแหน่งโดยจำนวนหนึ่งในสามเป็นอัตรา ถ้าและจำนวนกรรมการจะแบ่งออกให้ตรงเป็นส่วนสามไม่ได้ ก็ให้ออกโดยจำนวนใกล้ที่สุดกับส่วนหนึ่งในสาม"}},{"id":"TH-H004-A1153","no":1153,"noLabel":{"th":"มาตรา 1153"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๓ ตัวกรรมการที่จะต้องออกจากตำแหน่งในปีแรกและปีที่สองภายหลังจดทะเบียนบริษัทนั้น ถ้ากรรมการมิได้ตกลงกันไว้เองเป็นวิธีอื่นไซร้ ก็ให้จับสลากกัน ส่วนปีหลัง ๆ ต่อไปให้กรรมการคนที่ได้อยู่ในตำแหน่งนานที่สุดนั้นเป็นผู้ต้องออก กรรมการผู้ออกไปนั้นจะเลือกเข้ารับตำแหน่งอีกก็ได้"}},{"id":"TH-H004-A1153.001","no":1153.001,"noLabel":{"th":"มาตรา 1153/1"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๓/๑ กรรมการคนใดจะลาออกจากตำแหน่ง ให้ยื่นใบลาออกต่อบริษัท การลาออกมีผลนับแต่วันที่ใบลาออกไปถึงบริษัท กรรมการซึ่งลาออกตามวรรคหนึ่ง จะแจ้งการลาออกของตนให้นายทะเบียนทราบด้วยก็ได้"}},{"id":"TH-H004-A1154","no":1154,"noLabel":{"th":"มาตรา 1154"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๔ ถ้ากรรมการคนใดล้มละลาย หรือตกเป็นผู้ไร้ความสามารถไซร้ ท่านว่ากรรมการคนนั้นเป็นอันขาดจากตำแหน่ง"}},{"id":"TH-H004-A1155","no":1155,"noLabel":{"th":"มาตรา 1155"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๕ ถ้าตำแหน่งว่างลงในสภากรรมการเพราะเหตุอื่นนอกจากถึงคราวออกตามเวรไซร้ ท่านว่ากรรมการจะเลือกผู้อื่นตั้งขึ้นใหม่ให้เต็มที่ว่างก็ได้ แต่บุคคลที่ได้เป็นกรรมการใหม่เช่นนั้น ให้มีเวลาอยู่ในตำแหน่งได้เพียงเท่ากำหนดเวลาที่กรรมการผู้ออกไปนั้นชอบที่จะอยู่ได้"}},{"id":"TH-H004-A1156","no":1156,"noLabel":{"th":"มาตรา 1156"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๖ ถ้าที่ประชุมใหญ่ถอนกรรมการผู้หนึ่งออกก่อนครบกาลกำหนดของเขา และตั้งคนอื่นขึ้นไว้แทนที่ไซร้ ท่านว่าบุคคลที่เป็นกรรมการใหม่นั้นให้อยู่ในตำแหน่งได้เพียงเท่ากำหนดเวลาที่กรรมการผู้ถูกถอนนั้นชอบที่จะอยู่ได้"}},{"id":"TH-H004-A1157","no":1157,"noLabel":{"th":"มาตรา 1157"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๗ เมื่อมีการเปลี่ยนแปลงกรรมการ ให้บริษัทนำความไปจดทะเบียนภายในสิบสี่วันนับแต่วันที่มีการเปลี่ยนแปลง"}},{"id":"TH-H004-A1158","no":1158,"noLabel":{"th":"มาตรา 1158"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๘ นอกจากจะมีข้อบังคับของบริษัทไว้เป็นอย่างอื่น กรรมการมีอำนาจตามบทบัญญัติในเจ็ดมาตราต่อไปนี้"}},{"id":"TH-H004-A1159","no":1159,"noLabel":{"th":"มาตรา 1159"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๕๙ ในจำนวนกรรมการนั้น แม้ตำแหน่งจะว่างไปบ้าง กรรมการที่มีตัวอยู่ก็ย่อมทำกิจการได้ แต่ถ้าในเวลาใดจำนวนกรรมการลดน้อยลงกว่าจำนวนอันจำเป็นที่จะเป็นองค์ประชุมได้ตลอดเวลาเช่นนั้น กรรมการที่มีตัวอยู่ย่อมทำกิจการได้เฉพาะแต่ในเรื่องที่จะเพิ่มกรรมการขึ้นให้ครบจำนวนหรือนัดเรียกประชุมใหญ่ของบริษัทเท่านั้น จะกระทำกิจการอย่างอื่นไม่ได้"}},{"id":"TH-H004-A1160","no":1160,"noLabel":{"th":"มาตรา 1160"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๐ กรรมการจะวางกำหนดไว้ก็ได้ว่า จำนวนกรรมการเข้าประชุมกี่คนจึงจะเป็นองค์ประชุมทำกิจการได้ ถ้าและมิได้กำหนดไว้ดังนั้นไซร้ (เมื่อจำนวนกรรมการเกินกว่าสามคน) ท่านว่าต้องมีกรรมการเข้าประชุมสามคนจึงจะเป็นองค์ประชุมได้"}},{"id":"TH-H004-A1161","no":1161,"noLabel":{"th":"มาตรา 1161"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๑ ข้อปรึกษาซึ่งเกิดเป็นปัญหาในประชุมกรรมการนั้น ให้ชี้ขาดตัดสินเอาเสียงข้างมากเป็นใหญ่ ถ้าและคะแนนเสียงเท่ากัน ให้ผู้เป็นประธานเป็นผู้ออกเสียงชี้ขาด"}},{"id":"TH-H004-A1162","no":1162,"noLabel":{"th":"มาตรา 1162"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๒ กรรมการคนหนึ่งคนใดจะนัดเรียกให้ประชุมกรรมการเมื่อใดก็ได้"}},{"id":"TH-H004-A1162.001","no":1162.001,"noLabel":{"th":"มาตรา 1162/1"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๒/๑ การประชุมกรรมการอาจดำเนินการโดยการติดต่อสื่อสารด้วยเทคโนโลยีอย่างหนึ่งอย่างใด โดยกรรมการไม่จำเป็นต้องปรากฏตัวในที่ประชุมก็ได้ เว้นแต่ข้อบังคับของบริษัทจะกำหนดห้ามไว้ การประชุมกรรมการโดยการติดต่อสื่อสารด้วยเทคโนโลยีตามวรรคหนึ่ง ให้เป็นไปตามกฎหมายว่าด้วยการประชุมผ่านสื่ออิเล็กทรอนิกส์ ให้ถือว่ากรรมการซึ่งใช้การติดต่อสื่อสารตามวรรคหนึ่งได้เข้าร่วมประชุมกรรมการ และให้นับเป็นองค์ประชุมและมีสิทธิออกเสียงในการประชุมด้วย"}},{"id":"TH-H004-A1163","no":1163,"noLabel":{"th":"มาตรา 1163"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๓ กรรมการจะเลือกกรรมการคนหนึ่งขึ้นเป็นประธานที่ประชุม และจะกำหนดเวลาว่าให้อยู่ในตำแหน่งเพียงใดก็ได้ แต่ถ้าหากมิได้เลือกกันไว้เช่นนั้น หรือผู้เป็นประธานไม่มาประชุมตามเวลาที่ได้นัดหมายไซร้ กรรมการที่มาประชุมนั้นจะเลือกกันคนหนึ่งขึ้นเป็นประธานในการประชุมเช่นนั้นก็ได้"}},{"id":"TH-H004-A1164","no":1164,"noLabel":{"th":"มาตรา 1164"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๔ กรรมการจะมอบอำนาจอย่างหนึ่งอย่างใดของตนให้แก่ผู้จัดการ หรือให้แก่อนุกรรมการซึ่งตั้งขึ้นจากผู้ที่เป็นกรรมการด้วยกันก็ได้ ในการใช้อำนาจซึ่งได้มอบหมายเช่นนั้น ผู้จัดการทุกคนหรืออนุกรรมการทุกคนต้องทำตามคำสั่งหรือข้อบังคับซึ่งกรรมการทั้งหลายได้กำหนดให้ทุกอย่างทุกประการ"}},{"id":"TH-H004-A1165","no":1165,"noLabel":{"th":"มาตรา 1165"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๕ ถ้าการมอบอำนาจมิได้กำหนดไว้เป็นอย่างอื่นไซร้ ข้อปรึกษาซึ่งเกิดเป็นปัญหาขึ้นในที่ประชุมอนุกรรมการทั้งหลายให้ตัดสินเอาเสียงข้างมากเป็นใหญ่ ถ้าและคะแนนเสียงเท่ากัน ให้ผู้เป็นประธานชี้ขาด"}},{"id":"TH-H004-A1166","no":1166,"noLabel":{"th":"มาตรา 1166"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๖ บรรดาการซึ่งกรรมการคนหนึ่งได้ทำไปแม้ในภายหลังความปรากฏว่าการตั้งแต่งกรรมการคนนั้นมีข้อบกพร่องอยู่บ้างก็ดี หรือเป็นผู้บกพร่องด้วยองค์คุณควรแก่ตำแหน่งกรรมการก็ดี ท่านว่าการที่ได้ทำนั้นย่อมสมบูรณ์เสมือนดังว่าบุคคลผู้นั้นได้รับการแต่งตั้งโดยถูกต้องและบริบูรณ์ด้วยองค์คุณของกรรมการ"}},{"id":"TH-H004-A1167","no":1167,"noLabel":{"th":"มาตรา 1167"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๗ ความเกี่ยวพันกันในระหว่างกรรมการและบริษัทและบุคคลภายนอกนั้น ท่านให้บังคับตามบทบัญญัติแห่งประมวลกฎหมายนี้ ว่าด้วยตัวแทน"}},{"id":"TH-H004-A1168","no":1168,"noLabel":{"th":"มาตรา 1168"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๘ ในอันที่จะประกอบกิจการของบริษัทนั้น กรรมการต้องใช้ความเอื้อเฟื้อสอดส่องอย่างบุคคลค้าขายผู้ประกอบด้วยความระมัดระวัง ว่าโดยเฉพาะ กรรมการต้องรับผิดชอบร่วมกันในประการต่าง ๆ ดังจะกล่าวต่อไปนี้ คือ (๑) การใช้เงินค่าหุ้นนั้น ได้ใช้กันจริง (๒) จัดให้มีและรักษาไว้ให้เรียบร้อย ซึ่งบรรดาสมุดบัญชีและเอกสารที่กฎหมายกำหนดไว้ (๓) การแจกเงินปันผลหรือดอกเบี้ยให้เป็นไปโดยถูกต้องตามที่กฎหมายกำหนดไว้ (๔) บังคับการให้เป็นไปโดยถูกต้องตามมติของที่ประชุมใหญ่ อนึ่ง ท่านห้ามมิให้ผู้เป็นกรรมการประกอบการค้าขายใด ๆ อันมีสภาพเป็นอย่างเดียวกัน และเป็นการแข่งขันกับการค้าขายของบริษัทนั้น ไม่ว่าทำเพื่อประโยชน์ตนหรือเพื่อประโยชน์ผู้อื่น หรือไปเข้าหุ้นส่วนไม่จำกัดความรับผิดในห้างค้าขายอื่นซึ่งประกอบกิจการมีสภาพเป็นอย่างเดียวกันและแข่งขันกับกิจการของบริษัท โดยมิได้รับความยินยอมของที่ประชุมใหญ่ของผู้ถือหุ้น บทบัญญัติที่กล่าวมาข้างบนนี้ให้ใช้บังคับตลอดถึงบุคคลซึ่งเป็นผู้แทนของกรรมการด้วย"}},{"id":"TH-H004-A1169","no":1169,"noLabel":{"th":"มาตรา 1169"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๖๙ ถ้ากรรมการทำให้เกิดเสียหายแก่บริษัท บริษัทจะฟ้องร้องเรียกเอาสินไหมทดแทนแก่กรรมการก็ได้ หรือในกรณีที่บริษัทไม่ยอมฟ้องร้อง ผู้ถือหุ้นคนหนึ่งคนใดจะเอาคดีนั้นขึ้นว่าก็ได้ อนึ่ง การเรียกร้องเช่นนี้ เจ้าหนี้ของบริษัทจะเป็นผู้เรียกบังคับก็ได้ เท่าที่เจ้าหนี้ยังคงสิทธิเรียกร้องแก่บริษัทอยู่"}},{"id":"TH-H004-A1170","no":1170,"noLabel":{"th":"มาตรา 1170"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๐ เมื่อการซึ่งกรรมการคนใดได้ทำไปได้รับอนุมัติของที่ประชุมใหญ่แล้ว ท่านว่ากรรมการคนนั้นไม่ต้องรับผิดในการนั้นต่อผู้ถือหุ้นซึ่งได้ให้อนุมัติหรือต่อบริษัทอีกต่อไป ท่านห้ามมิให้ผู้ถือหุ้นซึ่งมิได้ให้อนุมัติด้วยนั้นฟ้องคดีเมื่อพ้นเวลาหกเดือนนับแต่วันที่ประชุมใหญ่ให้อนุมัติแก่การเช่นว่านั้น"}},{"id":"TH-H004-A1171","no":1171,"noLabel":{"th":"มาตรา 1171"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๑ ให้มีการประชุมผู้ถือหุ้นทั่วไปเป็นประชุมใหญ่ภายในหกเดือนนับแต่วันที่ได้จดทะเบียนบริษัท และต่อนั้นไปก็ให้มีการประชุมเช่นนี้ครั้งหนึ่งเป็นอย่างน้อยทุกระยะเวลาสิบสองเดือน การประชุมเช่นนี้ เรียกว่าประชุมสามัญ การประชุมใหญ่คราวอื่นบรรดามีนอกจากนี้ เรียกว่าประชุมวิสามัญ"}},{"id":"TH-H004-A1172","no":1172,"noLabel":{"th":"มาตรา 1172"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๒ กรรมการจะเรียกประชุมวิสามัญเมื่อใดก็ได้สุดแต่จะเห็นสมควร ถ้าบริษัทขาดทุนลงถึงกึ่งจำนวนต้นทุน กรรมการต้องเรียกประชุมวิสามัญทันทีเพื่อแจ้งให้ผู้ถือหุ้นทราบการที่ขาดทุนนั้น"}},{"id":"TH-H004-A1173","no":1173,"noLabel":{"th":"มาตรา 1173"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๓ การประชุมวิสามัญจะต้องนัดเรียกให้มีขึ้นในเมื่อผู้ถือหุ้นมีจำนวนหุ้นรวมกันไม่น้อยกว่าหนึ่งในห้าแห่งจำนวนหุ้นของบริษัทได้เข้าชื่อกันทำหนังสือร้องขอให้เรียกประชุมเช่นนั้น ในหนังสือร้องขอนั้นต้องระบุว่าประสงค์ให้เรียกประชุมเพื่อการใด"}},{"id":"TH-H004-A1174","no":1174,"noLabel":{"th":"มาตรา 1174"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๔ เมื่อผู้ถือหุ้นยื่นคำร้องขอให้เรียกประชุมวิสามัญดังได้กล่าวมาในมาตราก่อนนี้แล้ว ให้กรรมการเรียกประชุมโดยพลัน ถ้าและกรรมการมิได้เรียกประชุมภายในสามสิบวันนับแต่วันยื่นคำร้องไซร้ ผู้ถือหุ้นทั้งหลายซึ่งเป็นผู้ร้อง หรือผู้ถือหุ้นคนอื่น ๆ รวมกันได้จำนวนดังบังคับไว้นั้นจะเรียกประชุมเองก็ได้"}},{"id":"TH-H004-A1175","no":1175,"noLabel":{"th":"มาตรา 1175"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๕ คำบอกกล่าวเรียกประชุมใหญ่ให้ส่งทางไปรษณีย์ตอบรับไปยังผู้ถือหุ้นทุกคนที่มีชื่อในทะเบียนของบริษัทก่อนวันนัดประชุมไม่น้อยกว่าเจ็ดวัน แต่ในกรณีที่บริษัทมีหุ้นชนิดที่มีใบหุ้นออกให้แก่ผู้ถือ ให้โฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งครั้งหรือในสื่ออิเล็กทรอนิกส์ตามหลักเกณฑ์ วิธีการที่กำหนดในกฎกระทรวง ก่อนวันนัดประชุมไม่น้อยกว่าเจ็ดวันด้วย หากเป็นคำบอกกล่าวเรียกประชุมใหญ่เพื่อลงมติพิเศษให้กระทำการดังกล่าว ก่อนวันนัดประชุมไม่น้อยกว่าสิบสี่วัน คำบอกกล่าวเรียกประชุมใหญ่นั้น ให้ระบุสถานที่ วัน เวลา และสภาพแห่งกิจการที่จะได้ประชุมปรึกษากัน และในกรณีที่เป็นคำบอกกล่าวเรียกประชุมใหญ่เพื่อลงมติพิเศษให้ระบุข้อความที่จะนำเสนอให้ลงมติด้วย"}},{"id":"TH-H004-A1176","no":1176,"noLabel":{"th":"มาตรา 1176"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๖ ผู้ถือหุ้นทั่วทุกคนมีสิทธิจะเข้าประชุมในที่ประชุมใหญ่ได้เสมอ ไม่ว่าจะเป็นประชุมชนิดใดคราวใด"}},{"id":"TH-H004-A1177","no":1177,"noLabel":{"th":"มาตรา 1177"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๗ วิธีดังบัญญัติไว้ในมาตราต่อ ๆ ไปนี้ ท่านให้ใช้บังคับแก่การประชุมใหญ่ เว้นแต่จะมีข้อบังคับของบริษัทกำหนดไว้เป็นข้อความขัดกัน"}},{"id":"TH-H004-A1178","no":1178,"noLabel":{"th":"มาตรา 1178"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๘ การประชุมใหญ่ต้องมีผู้ถือหุ้นหรือผู้รับมอบฉันทะจากผู้ถือหุ้นเข้าร่วมประชุมกันไม่น้อยกว่าสองคนและมีจำนวนหุ้นนับรวมกันได้ไม่น้อยกว่าหนึ่งในสี่แห่งทุนของบริษัท จึงจะสามารถลงมติในเรื่องใด ๆ ได้"}},{"id":"TH-H004-A1179","no":1179,"noLabel":{"th":"มาตรา 1179"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๗๙ การประชุมใหญ่เรียกนัดเวลาใด เมื่อล่วงเวลานัดนั้นไปแล้วถึงชั่วโมงหนึ่ง จำนวนผู้ถือหุ้นซึ่งมาเข้าประชุมยังไม่ครบถ้วนเป็นองค์ประชุมดังบัญญัติไว้ในมาตรา ๑๑๗๘ นั้นไซร้ หากว่าการประชุมใหญ่นั้นได้เรียกนัดเพราะผู้ถือหุ้นร้องขอ ท่านให้เลิกประชุม ถ้าการประชุมใหญ่นั้นมิใช่ชนิดซึ่งเรียกนัดเพราะผู้ถือหุ้นร้องขอไซร้ ท่านให้เรียกนัดใหม่อีกคราวหนึ่งภายในสิบสี่วัน และการประชุมใหญ่ครั้งหลังนี้ท่านไม่บังคับว่าจำต้องครบองค์ประชุม"}},{"id":"TH-H004-A1180","no":1180,"noLabel":{"th":"มาตรา 1180"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๐ ในการประชุมผู้ถือหุ้นทั่วไปเป็นประชุมใหญ่ทุก ๆ ครั้ง ให้ผู้เป็นประธานในสภากรรมการนั่งเป็นประธาน ถ้าประธานกรรมการเช่นว่านี้ไม่มีตัวก็ดี หรือไม่มาเข้าประชุมจนล่วงเวลานัดไปแล้วสิบห้านาทีก็ดี ให้ผู้ถือหุ้นทั้งหลายซึ่งอยู่ในที่นั้นเลือกผู้ถือหุ้นคนหนึ่งในจำนวนซึ่งมาประชุมขึ้นนั่งเป็นประธาน"}},{"id":"TH-H004-A1181","no":1181,"noLabel":{"th":"มาตรา 1181"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๑ ผู้นั่งเป็นประธานจะเลื่อนการประชุมใหญ่ใด ๆ ไปเวลาอื่นโดยความยินยอมของที่ประชุมก็ได้ แต่ในที่ประชุมซึ่งได้เลื่อนมานั้นท่านมิให้ปรึกษากิจการอันใดนอกไปจากที่ค้างมาแต่วันประชุมก่อน"}},{"id":"TH-H004-A1182","no":1182,"noLabel":{"th":"มาตรา 1182"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๒ ในการลงคะแนนโดยวิธีชูมือนั้น ท่านให้นับว่าผู้ถือหุ้นทุกคนที่มาประชุมเองหรือมอบฉันทะให้ผู้อื่นมาประชุมแทนมีเสียงหนึ่งเป็นคะแนน แต่ในการลงคะแนนลับ ท่านให้นับว่าผู้ถือหุ้นทุกคนมีคะแนนเสียง เสียงหนึ่งต่อหุ้นหนึ่งที่ตนถือ"}},{"id":"TH-H004-A1183","no":1183,"noLabel":{"th":"มาตรา 1183"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๓ ถ้ามีข้อบังคับของบริษัทวางเป็นกำหนดไว้ว่า ต่อเมื่อผู้ถือหุ้นเป็นผู้มีหุ้นแต่จำนวนเท่าใดขึ้นไปจึงให้ออกเสียงเป็นคะแนนได้ไซร้ ท่านว่าผู้ถือหุ้นทั้งหลายซึ่งไม่มีหุ้นถึงจำนวนเท่านั้นย่อมมีสิทธิที่จะเข้ารวมกันให้ได้จำนวนหุ้นดังกล่าว แล้วตั้งคนหนึ่งในพวกของตนให้เป็นผู้รับฉันทะออกเสียงแทนในการประชุมใหญ่ใด ๆ ได้"}},{"id":"TH-H004-A1184","no":1184,"noLabel":{"th":"มาตรา 1184"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๔ ผู้ถือหุ้นคนใดยังมิได้ชำระเงินค่าหุ้นซึ่งบริษัทได้เรียกเอาแต่ตนให้เสร็จสิ้น ท่านว่าผู้ถือหุ้นคนนั้นไม่มีสิทธิออกเสียงเป็นคะแนน"}},{"id":"TH-H004-A1185","no":1185,"noLabel":{"th":"มาตรา 1185"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๕ ผู้ถือหุ้นคนใดมีส่วนได้เสียเป็นพิเศษในข้ออันใดซึ่งที่ประชุมจะลงมติ ท่านห้ามมิให้ผู้ถือหุ้นคนนั้นออกเสียงลงคะแนนด้วยในข้อนั้น"}},{"id":"TH-H004-A1186","no":1186,"noLabel":{"th":"มาตรา 1186"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๖ ผู้ทรงใบหุ้นชนิดออกให้แก่ผู้ถือหาอาจออกเสียงเป็นคะแนนได้ไม่ เว้นแต่จะได้นำใบหุ้นของตนนั้นมาวางไว้แก่บริษัทแต่ก่อนเวลาประชุม"}},{"id":"TH-H004-A1187","no":1187,"noLabel":{"th":"มาตรา 1187"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๗ ผู้ถือหุ้นทุกคนจะมอบฉันทะให้ผู้อื่นออกเสียงแทนตนก็ได้ แต่การมอบฉันทะเช่นนี้ต้องทำเป็นหนังสือ"}},{"id":"TH-H004-A1188","no":1188,"noLabel":{"th":"มาตรา 1188"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๘ หนังสือตั้งผู้รับฉันทะนั้น ให้ลงวันและลงลายมือชื่อผู้ถือหุ้นและให้มีรายการดังต่อไปนี้ คือ (๑) จำนวนหุ้นซึ่งผู้มอบฉันทะนั้นถืออยู่ (๒) ชื่อผู้รับฉันทะ (๓) ตั้งผู้รับฉันทะนั้นเพื่อการประชุมครั้งคราวใด หรือตั้งไว้ชั่วระยะเวลาเพียงใด"}},{"id":"TH-H004-A1189","no":1189,"noLabel":{"th":"มาตรา 1189"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๘๙ อันหนังสือตั้งผู้รับฉันทะนั้น ถ้าผู้มีชื่อรับฉันทะประสงค์จะออกเสียงในการประชุมครั้งใด ต้องนำไปวางต่อผู้เป็นประธานแต่เมื่อเริ่ม หรือก่อนเริ่มประชุมครั้งนั้น"}},{"id":"TH-H004-A1190","no":1190,"noLabel":{"th":"มาตรา 1190"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๐ ในการประชุมใหญ่ใด ๆ ข้อมติอันเสนอให้ลงคะแนนท่านให้ตัดสินด้วยวิธีชูมือ เว้นแต่เมื่อก่อนหรือในเวลาที่แสดงผลแห่งการชูมือนั้น จะได้มีผู้ถือหุ้นสองคนเป็นอย่างน้อยติดใจร้องขอให้ลงคะแนนลับ"}},{"id":"TH-H004-A1191","no":1191,"noLabel":{"th":"มาตรา 1191"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๑ ในการประชุมใหญ่ใด ๆ เมื่อผู้เป็นประธานแสดงว่ามติอันใดนับคะแนนชูมือเป็นอันว่าได้หรือตกก็ดี และได้จดลงไว้ในสมุดรายงานประชุมของบริษัทดังนั้นแล้ว ท่านให้ถือเป็นหลักฐานเพียงพอที่จะฟังได้ตามนั้น ถ้ามีผู้ติดใจร้องขอให้ลงคะแนนลับไซร้ ท่านให้ถือว่าผลแห่งคะแนนลับนั้นเป็นมติของที่ประชุม"}},{"id":"TH-H004-A1192","no":1192,"noLabel":{"th":"มาตรา 1192"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๒ ถ้ามีผู้ติดใจร้องขอโดยชอบให้ลงคะแนนลับ การลงคะแนนเช่นนั้นจะทำด้วยวิธีใดสุดแล้วแต่ผู้เป็นประธานจะสั่ง"}},{"id":"TH-H004-A1193","no":1193,"noLabel":{"th":"มาตรา 1193"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๓ ถ้าคะแนนเสียงเท่ากัน จะเป็นในการชูมือก็ดี หรือในการลงคะแนนลับก็ดี ให้ผู้เป็นประธานในที่ประชุมมีคะแนนอีกเสียงหนึ่งเป็นเสียงชี้ขาด"}},{"id":"TH-H004-A1194","no":1194,"noLabel":{"th":"มาตรา 1194"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๔ การใดที่กฎหมายกำหนดให้ต้องทำโดยมติพิเศษ ที่ประชุมใหญ่ต้องลงมติในเรื่องนั้นโดยคะแนนเสียงข้างมากไม่ต่ำกว่าสามในสี่ของจำนวนเสียงทั้งหมดของผู้ถือหุ้นที่มาประชุมและมีสิทธิออกเสียงลงคะแนน"}},{"id":"TH-H004-A1195","no":1195,"noLabel":{"th":"มาตรา 1195"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๕ การประชุมใหญ่นั้นถ้าได้นัดเรียกหรือได้ประชุมกัน หรือได้ลงมติฝ่าฝืนบทบัญญัติในลักษณะนี้ก็ดี หรือฝ่าฝืนข้อบังคับของบริษัทก็ดี เมื่อกรรมการหรือผู้ถือหุ้นคนหนึ่งคนใดร้องขึ้นแล้ว ให้ศาลเพิกถอนมติของที่ประชุมใหญ่อันผิดระเบียบนั้นเสีย แต่ต้องร้องขอภายในกำหนดเดือนหนึ่งนับแต่วันลงมตินั้น"}},{"id":"TH-H004-A1196","no":1196,"noLabel":{"th":"มาตรา 1196"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๖ อันบัญชีงบดุลนั้น ท่านว่าต้องทำอย่างน้อยครั้งหนึ่งทุกรอบสิบสองเดือน คือเมื่อเวลาสุดรอบสิบสองเดือนอันจัดว่าเป็นขวบปีในทางบัญชีเงินของบริษัทนั้น อนึ่ง งบดุลต้องมีรายการย่อแสดงจำนวนสินทรัพย์และหนี้สินของบริษัทกับทั้งบัญชีกำไรและขาดทุน"}},{"id":"TH-H004-A1197","no":1197,"noLabel":{"th":"มาตรา 1197"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๗ งบดุลนั้นต้องจัดให้มีผู้สอบบัญชีคนหนึ่งหรือหลายคนตรวจสอบแล้วนำเสนอเพื่ออนุมัติในที่ประชุมใหญ่ภายในสี่เดือนนับแต่วันที่ลงในงบดุลนั้น อนึ่ง ให้ส่งสำเนางบดุลไปยังบุคคลทุกคนบรรดามีชื่อในทะเบียนผู้ถือหุ้นของบริษัทแต่ก่อนวันนัดประชุมใหญ่ล่วงหน้าไม่น้อยกว่าสามวัน นอกจากนั้นให้มีสำเนางบดุลเปิดเผยไว้ในสำนักงานของบริษัทในระหว่างเวลาเช่นว่านั้น เพื่อให้ผู้ทรงใบหุ้นชนิดออกให้แก่ผู้ถือนั้นตรวจดูได้ด้วย"}},{"id":"TH-H004-A1198","no":1198,"noLabel":{"th":"มาตรา 1198"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๘ ในเมื่อเสนองบดุล กรรมการต้องเสนอรายงานต่อที่ประชุมใหญ่ แสดงว่าภายในรอบปีซึ่งพิจารณากันอยู่นั้นการงานของบริษัทได้จัดทำไปเป็นประการใด"}},{"id":"TH-H004-A1199","no":1199,"noLabel":{"th":"มาตรา 1199"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๑๙๙ บุคคลใดประสงค์จะได้สำเนางบดุลฉบับหลังที่สุดจากบริษัทใด ๆ ก็ชอบที่จะซื้อเอาได้โดยราคาไม่เกินฉบับละยี่สิบบาท ให้เป็นหน้าที่ของกรรมการที่จะส่งสำเนางบดุลทุกฉบับไปยังนายทะเบียนไม่ช้ากว่าเดือนหนึ่งนับแต่วันซึ่งงบดุลนั้นได้รับอนุมัติในที่ประชุมใหญ่"}},{"id":"TH-H004-A1200","no":1200,"noLabel":{"th":"มาตรา 1200"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๐ การแจกเงินปันผลนั้น ต้องคิดตามส่วนจำนวนซึ่งผู้ถือหุ้นได้ส่งเงินแล้วในหุ้นหนึ่ง ๆ เว้นแต่จะได้ตกลงกันไว้เป็นอย่างอื่นในเรื่องหุ้นบุริมสิทธิ"}},{"id":"TH-H004-A1201","no":1201,"noLabel":{"th":"มาตรา 1201"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๑ ห้ามมิให้ประกาศอนุญาตเงินปันผล นอกจากโดยมติของที่ประชุมใหญ่ กรรมการอาจจ่ายเงินปันผลระวางกาลให้แก่ผู้ถือหุ้นได้เป็นครั้งเป็นคราว ในเมื่อปรากฏแก่กรรมการว่าบริษัทมีกำไรสมควรพอที่จะทำเช่นนั้น ห้ามมิให้จ่ายเงินปันผลจากเงินประเภทอื่นนอกจากเงินกำไร ถ้าหากบริษัทขาดทุน ห้ามมิให้จ่ายเงินปันผลจนกว่าจะได้แก้ไขให้หายขาดทุนเช่นนั้น การจ่ายเงินปันผลนั้นให้ดำเนินการให้แล้วเสร็จภายในหนึ่งเดือนนับแต่วันที่ที่ประชุมใหญ่หรือกรรมการลงมติ แล้วแต่กรณี"}},{"id":"TH-H004-A1202","no":1202,"noLabel":{"th":"มาตรา 1202"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๒ ทุกคราวที่แจกเงินปันผล บริษัทต้องจัดสรรเงินไว้เป็นทุนสำรองอย่างน้อยหนึ่งในยี่สิบส่วนของจำนวนผลกำไรซึ่งบริษัททำมาหาได้จากกิจการของบริษัท จนกว่าทุนสำรองนั้นจะมีจำนวนถึงหนึ่งในสิบของจำนวนทุนของบริษัทหรือมากกว่านั้น แล้วแต่จะได้ตกลงกำหนดไว้ในข้อบังคับของบริษัท ถ้าได้ออกหุ้นโดยคิดเอาราคาเกินกว่าที่ปรากฏในใบหุ้นเท่าใด จำนวนที่คิดเกินนี้ท่านให้บวกทบเข้าในทุนสำรองจนกว่าทุนสำรองจะมีจำนวนเท่าถึงที่กำหนดไว้ในวรรคก่อน"}},{"id":"TH-H004-A1203","no":1203,"noLabel":{"th":"มาตรา 1203"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๓ ถ้าจ่ายเงินปันผลไปโดยฝ่าฝืนความในมาตราทั้งสองซึ่งกล่าวมาไซร้ เจ้าหนี้ทั้งหลายของบริษัทชอบที่จะเรียกเอาเงินจำนวนซึ่งได้แจกไปคืนมายังบริษัทได้ แต่ว่าถ้าผู้ถือหุ้นคนใดได้รับเงินปันผลไปแล้วโดยสุจริต ท่านว่าจะกลับบังคับให้เขาจำคืนนั้นหาได้ไม่"}},{"id":"TH-H004-A1204","no":1204,"noLabel":{"th":"มาตรา 1204"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๔ การบอกกล่าวว่าจะปันผลอย่างใดๆ อันได้อนุญาตให้จ่ายนั้น ให้บริษัทมีจดหมายบอกกล่าวไปยังตัวผู้ถือหุ้นที่ปรากฏชื่ออยู่ในทะเบียนผู้ถือหุ้นทุกคน แต่ในกรณีที่บริษัทมีหุ้นชนิดที่มีใบหุ้นออกให้แก่ผู้ถือ ให้โฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราวด้วย"}},{"id":"TH-H004-A1205","no":1205,"noLabel":{"th":"มาตรา 1205"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๕ เงินปันผลนั้น แม้จะค้างจ่ายอยู่ ท่านว่าหาอาจจะคิดเอาดอกเบี้ยแก่บริษัทได้ไม่"}},{"id":"TH-H004-A1206","no":1206,"noLabel":{"th":"มาตรา 1206"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๖ กรรมการต้องจัดให้ถือบัญชีซึ่งกล่าวต่อไปนี้ไว้ให้ถูกถ้วนจริง ๆ คือ (๑) จำนวนเงินที่บริษัทได้รับและได้จ่าย ทั้งรายการอันเป็นเหตุให้รับหรือจ่ายเงินทุกรายไป (๒) สินทรัพย์และหนี้สินของบริษัท"}},{"id":"TH-H004-A1207","no":1207,"noLabel":{"th":"มาตรา 1207"},"chapter":{"th":"ส่วน 3"},"text":{"th":"มาตรา ๑๒๐๗ กรรมการต้องจัดให้จดบันทึกรายงานการประชุม และข้อมติทั้งหมดของที่ประชุมผู้ถือหุ้นและของที่ประชุมกรรมการลงไว้ในสมุดโดยถูกต้อง สมุดนี้ให้เก็บรักษาไว้ ณ สำนักงานที่ได้จดทะเบียนของบริษัท บันทึกเช่นนั้นอย่างหนึ่งอย่างใด เมื่อได้ลงลายมือชื่อของผู้เป็นประธานแห่งการประชุมซึ่งได้ลงมติ หรือซึ่งได้ดำเนินการงานประชุมก็ดี หรือได้ลงลายมือชื่อของผู้เป็นประธานแห่งการประชุมถัดจากครั้งนั้นมาก็ดี ท่านให้สันนิษฐานไว้ก่อนว่าเป็นหลักฐานอันถูกต้องแห่งข้อความที่ได้จดบันทึกลงในสมุดนั้น ๆ และให้สันนิษฐานไว้ก่อนว่าการลงมติและการดำเนินของที่ประชุมอันได้จดบันทึกไว้นั้นได้เป็นไปโดยชอบ ผู้ถือหุ้นคนใดจะขอตรวจดูเอกสารดังกล่าวมาข้างต้นในเวลาใดเวลาหนึ่งระหว่างเวลาทำการงานก็ได้"}},{"id":"TH-H004-A1208","no":1208,"noLabel":{"th":"มาตรา 1208"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๐๘ ผู้สอบบัญชีนั้น จะเป็นผู้ถือหุ้นของบริษัทก็ได้ แต่บุคคลผู้มีส่วนได้เสียในการงานที่บริษัททำโดยสถานอื่นอย่างหนึ่งอย่างใด นอกจากเป็นแต่ผู้ถือหุ้นในบริษัทเท่านั้นแล้ว ท่านว่าจะเลือกเอามาเป็นตำแหน่งผู้สอบบัญชีหาได้ไม่ กรรมการก็ดี หรือผู้อื่นซึ่งเป็นตัวแทนหรือเป็นลูกจ้างของบริษัทก็ดี เวลาอยู่ในตำแหน่งนั้น ๆ ก็จะเลือกเอามาเป็นตำแหน่งผู้สอบบัญชีของบริษัทหาได้ไม่"}},{"id":"TH-H004-A1209","no":1209,"noLabel":{"th":"มาตรา 1209"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๐๙ ผู้สอบบัญชีนั้น ให้ที่ประชุมสามัญเลือกตั้งทุกปี ผู้สอบบัญชีคนซึ่งออกไปนั้นจะเลือกกลับเข้ารับตำแหน่งอีกก็ได้"}},{"id":"TH-H004-A1210","no":1210,"noLabel":{"th":"มาตรา 1210"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๑๐ ผู้สอบบัญชีควรจะได้สินจ้างเท่าใด ให้ที่ประชุมใหญ่กำหนด"}},{"id":"TH-H004-A1211","no":1211,"noLabel":{"th":"มาตรา 1211"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๑๑ ถ้ามีตำแหน่งว่างลงในจำนวนผู้สอบบัญชี ให้กรรมการนัดเรียกประชุมวิสามัญ เพื่อให้เลือกตั้งขึ้นใหม่ให้ครบจำนวน"}},{"id":"TH-H004-A1212","no":1212,"noLabel":{"th":"มาตรา 1212"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๑๒ ถ้ามิได้เลือกตั้งผู้สอบบัญชีโดยวิธีดังกล่าวมา เมื่อผู้ถือหุ้นไม่น้อยกว่าห้าคนร้องขอ ก็ให้ศาลตั้งผู้สอบบัญชีประจำปีนั้น และกำหนดสินจ้างให้ด้วย"}},{"id":"TH-H004-A1213","no":1213,"noLabel":{"th":"มาตรา 1213"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๑๓ ให้ผู้สอบบัญชีทุกคนเข้าตรวจสอบสรรพสมุดและบัญชีของบริษัทในเวลาอันสมควรได้ทุกเมื่อ และในการอันเกี่ยวด้วยสมุดและบัญชีเช่นนั้นให้ไต่ถามสอบสวนกรรมการ หรือผู้อื่น ๆ ซึ่งเป็นตัวแทน หรือเป็นลูกจ้างของบริษัทได้ไม่ว่าคนหนึ่งคนใด"}},{"id":"TH-H004-A1214","no":1214,"noLabel":{"th":"มาตรา 1214"},"chapter":{"th":"ส่วน 4"},"text":{"th":"มาตรา ๑๒๑๔ ผู้สอบบัญชีต้องทำรายงานว่าด้วยงบดุลและบัญชียื่นต่อที่ประชุมสามัญ ผู้สอบบัญชีต้องแถลงในรายงานเช่นนั้นด้วยว่าตนเห็นว่างบดุลได้ทำโดยถูกถ้วนควรฟังว่าสำแดงให้เห็นการงานของบริษัทที่เป็นอยู่ตามจริงและถูกต้องหรือไม่"}},{"id":"TH-H004-A1215","no":1215,"noLabel":{"th":"มาตรา 1215"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๒๑๕ เมื่อผู้ถือหุ้นในบริษัทมีจำนวนรวมกันไม่น้อยกว่าหนึ่งในห้าของจำนวนหุ้นทั้งหมด ทำเรื่องราวร้องขอไซร้ ให้รัฐมนตรีเจ้าหน้าที่ตั้งผู้ตรวจอันทรงความสามารถ จะเป็นคนเดียวหรือหลายคนก็ตามไปตรวจการงานของบริษัทจำกัดนั้นและทำรายงานยื่นให้ทราบ ก่อนที่จะตั้งผู้ตรวจเช่นนั้น รัฐมนตรีจะบังคับให้คนทั้งหลายผู้ยื่นเรื่องราววางประกัน เพื่อรับออกเงินค่าใช้สอยในการตรวจนั้นก็ได้"}},{"id":"TH-H004-A1216","no":1216,"noLabel":{"th":"มาตรา 1216"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๒๑๖ กรรมการก็ดี ลูกจ้างและตัวแทนของบริษัทก็ดี จำต้องส่งสรรพสมุดและเอกสารทั้งปวงซึ่งตนเก็บรักษาหรืออยู่ในอำนาจแห่งตนนั้นให้แก่ผู้ตรวจ ผู้ตรวจคนหนึ่งคนใดจะให้กรรมการ ลูกจ้าง และตัวแทนของบริษัทสาบานตัวแล้วสอบถามคำให้การในเรื่องอันเนื่องด้วยการงานของบริษัทนั้นก็ได้"}},{"id":"TH-H004-A1217","no":1217,"noLabel":{"th":"มาตรา 1217"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๒๑๗ ผู้ตรวจต้องทำรายงานยื่น และรายงานนั้นจะเขียนหรือตีพิมพ์สุดแต่รัฐมนตรีเจ้าหน้าที่จะบัญชา สำเนารายงานนั้นให้รัฐมนตรีส่งไปยังสำนักงานบริษัทซึ่งได้จดทะเบียนไว้ กับทั้งส่งแก่ผู้ถือหุ้นซึ่งยื่นเรื่องราวขอให้ตรวจนั้นด้วย"}},{"id":"TH-H004-A1218","no":1218,"noLabel":{"th":"มาตรา 1218"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๒๑๘ ค่าใช้สอยในการตรวจเช่นนี้ ผู้ยื่นเรื่องราวขอให้ตรวจต้องใช้ทั้งสิ้น เว้นแต่ถ้าบริษัทในคราวประชุมใหญ่ครั้งแรกเมื่อตรวจสำเร็จลงแล้วได้ยินยอมว่าจะจ่ายจากสินทรัพย์ของบริษัทนั้น"}},{"id":"TH-H004-A1219","no":1219,"noLabel":{"th":"มาตรา 1219"},"chapter":{"th":"ส่วน 5"},"text":{"th":"มาตรา ๑๒๑๙ รัฐมนตรีเจ้าหน้าที่โดยลำพังตนเอง จะตั้งผู้ตรวจคนเดียวหรือหลายคนให้ไปตรวจการของบริษัทเพื่อทำรายงานยื่นต่อรัฐบาลก็ได้ การตั้งผู้ตรวจเช่นว่ามานี้จะพึงมีเมื่อใดสุดแล้วแต่รัฐมนตรีจะเห็นสมควร"}},{"id":"TH-H004-A1220","no":1220,"noLabel":{"th":"มาตรา 1220"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๐ บริษัทจำกัดอาจเพิ่มทุนของบริษัทขึ้นได้ด้วยออกหุ้นใหม่โดยมติพิเศษของประชุมผู้ถือหุ้น"}},{"id":"TH-H004-A1221","no":1221,"noLabel":{"th":"มาตรา 1221"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๑ บริษัทจำกัดจะออกหุ้นใหม่ให้เหมือนหนึ่งว่าได้ใช้เต็มค่าแล้ว หรือได้ใช้แต่บางส่วนแล้วด้วยอย่างอื่นนอกจากให้ใช้เป็นตัวเงินนั้นไม่ได้ เว้นแต่จะทำตามมติพิเศษของประชุมผู้ถือหุ้น"}},{"id":"TH-H004-A1222","no":1222,"noLabel":{"th":"มาตรา 1222"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๒ บรรดาหุ้นที่ออกใหม่นั้น ต้องเสนอให้แก่ผู้ถือหุ้นทั้งหลายตามส่วนจำนวนหุ้นซึ่งเขาถืออยู่ คำเสนอเช่นนี้ ต้องทำเป็นหนังสือบอกกล่าวไปยังผู้ถือหุ้นทุก ๆ คนระบุจำนวนหุ้นให้ทราบว่าผู้นั้นชอบที่จะซื้อได้กี่หุ้น และให้กำหนดวันว่าถ้าพ้นวันนั้นไปมิได้มีคำสนองมาแล้วจะถือว่าเป็นอันไม่รับซื้อ เมื่อวันที่กำหนดล่วงไปแล้วก็ดี หรือผู้ถือหุ้นได้บอกมาว่าไม่รับซื้อหุ้นนั้นก็ดีกรรมการจะเอาหุ้นเช่นนั้นขายให้แก่ผู้ถือหุ้นคนอื่นหรือจะรับซื้อไว้เองก็ได้"}},{"id":"TH-H004-A1223","no":1223,"noLabel":{"th":"มาตรา 1223"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๓ หนังสือบอกกล่าวที่เสนอให้ผู้ถือหุ้นซื้อหุ้นใหม่นั้น ต้องลงวันเดือนปีและลายมือชื่อของกรรมการ"}},{"id":"TH-H004-A1224","no":1224,"noLabel":{"th":"มาตรา 1224"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๔ บริษัทจำกัดจะลดทุนของบริษัทลงด้วยลดมูลค่าแต่ละหุ้น ๆ ให้ต่ำลง หรือลดจำนวนหุ้นให้น้อยลงโดยมติพิเศษของประชุมผู้ถือหุ้นก็ได้"}},{"id":"TH-H004-A1225","no":1225,"noLabel":{"th":"มาตรา 1225"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๕ อันทุนของบริษัทนั้นจะลดลงไปให้ถึงต่ำกว่าจำนวนหนึ่งในสี่ของทุนทั้งหมดหาได้ไม่"}},{"id":"TH-H004-A1226","no":1226,"noLabel":{"th":"มาตรา 1226"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๖ เมื่อบริษัทประสงค์จะลดทุน ต้องโฆษณาความประสงค์นั้นในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราว และต้องมีหนังสือบอกกล่าวไปยังบรรดาผู้ซึ่งบริษัทรู้ว่าเป็นเจ้าหนี้ของบริษัท บอกให้ทราบรายการซึ่งประสงค์จะลดทุนลงและขอให้เจ้าหนี้ผู้มีข้อคัดค้านอย่างหนึ่งอย่างใดในการลดทุนนั้น ส่งคำคัดค้านไปภายในสามสิบวันนับแต่วันที่บอกกล่าวนั้น ถ้าไม่มีผู้ใดคัดค้านภายในกำหนดเวลาสามสิบวัน ก็ให้พึงถือว่าไม่มีการคัดค้าน ถ้าหากมีเจ้าหนี้คัดค้าน บริษัทจะจัดการลดทุนลงไม่ได้ จนกว่าจะได้ใช้หนี้หรือให้ประกันเพื่อหนี้รายนั้นแล้ว"}},{"id":"TH-H004-A1227","no":1227,"noLabel":{"th":"มาตรา 1227"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๗ ถ้ามีเจ้าหนี้คนหนึ่งคนใดละเลยเสียมิได้คัดค้านในการที่บริษัทจะลดทุนลง เพราะเหตุว่าตนไม่ทราบความ และเหตุที่ไม่ทราบนั้นมิได้เป็นเพราะความผิดของเจ้าหนี้คนนั้นแต่อย่างใดไซร้ ท่านว่าผู้ถือหุ้นทั้งหลายบรรดาที่ได้รับเงินคืนไปตามส่วนที่ลดหุ้นลงนั้น ยังคงจะต้องรับผิดต่อเจ้าหนี้เช่นนั้นเพียงจำนวนที่ได้รับทุนคืนไปชั่วเวลาสองปีนับแต่วันที่ได้จดทะเบียนการลดทุนนั้น"}},{"id":"TH-H004-A1228","no":1228,"noLabel":{"th":"มาตรา 1228"},"chapter":{"th":"ส่วน 6"},"text":{"th":"มาตรา ๑๒๒๘ มติพิเศษซึ่งอนุญาตให้เพิ่มทุนหรือลดทุนนั้น บริษัทต้องจดทะเบียนภายในสิบสี่วันนับแต่วันที่ได้ลงมตินั้น"}},{"id":"TH-H004-A1229","no":1229,"noLabel":{"th":"มาตรา 1229"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๒๙ บริษัทจะออกหุ้นกู้ไม่ได้"}},{"id":"TH-H004-A1230","no":1230,"noLabel":{"th":"มาตรา 1230"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๐ (ยกเลิก)"}},{"id":"TH-H004-A1231","no":1231,"noLabel":{"th":"มาตรา 1231"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๑ (ยกเลิก)"}},{"id":"TH-H004-A1232","no":1232,"noLabel":{"th":"มาตรา 1232"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๒ (ยกเลิก)"}},{"id":"TH-H004-A1233","no":1233,"noLabel":{"th":"มาตรา 1233"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๓ (ยกเลิก)"}},{"id":"TH-H004-A1234","no":1234,"noLabel":{"th":"มาตรา 1234"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๔ (ยกเลิก)"}},{"id":"TH-H004-A1235","no":1235,"noLabel":{"th":"มาตรา 1235"},"chapter":{"th":"ส่วน 7"},"text":{"th":"มาตรา ๑๒๓๕ (ยกเลิก)"}},{"id":"TH-H004-A1236","no":1236,"noLabel":{"th":"มาตรา 1236"},"chapter":{"th":"ส่วน 8"},"text":{"th":"มาตรา ๑๒๓๖ อันบริษัทจำกัดย่อมเลิกกันด้วยเหตุดังจะกล่าวต่อไปนี้ คือ (๑) ถ้าในข้อบังคับของบริษัทมีกำหนดกรณีอันใดเป็นเหตุที่จะเลิกกันเมื่อมีกรณีนั้น (๒) ถ้าบริษัทได้ตั้งขึ้นไว้เฉพาะกำหนดกาลใด เมื่อสิ้นกำหนดกาลนั้น (๓) ถ้าบริษัทได้ตั้งขึ้นเฉพาะเพื่อทำกิจการอย่างหนึ่งอย่างใดแต่อย่างเดียว เมื่อเสร็จการนั้น (๔) เมื่อมีมติพิเศษให้เลิก (๕) เมื่อบริษัทล้มละลาย"}},{"id":"TH-H004-A1237","no":1237,"noLabel":{"th":"มาตรา 1237"},"chapter":{"th":"ส่วน 8"},"text":{"th":"มาตรา ๑๒๓๗ นอกจากนี้ศาลอาจสั่งให้เลิกบริษัทจำกัดด้วยเหตุต่อไปนี้ คือ (๑) ถ้าทำผิดในการยื่นรายงานประชุมตั้งบริษัท หรือทำผิดในการประชุมตั้งบริษัท (๒) ถ้าบริษัทไม่เริ่มทำการภายในปีหนึ่งนับแต่วันจดทะเบียน หรือหยุดทำการถึงปีหนึ่งเต็ม (๓) ถ้าการค้าของบริษัททำไปก็มีแต่ขาดทุนอย่างเดียว และไม่มีทางหวังว่าจะกลับฟื้นตัวได้ (๔) ถ้าจำนวนผู้ถือหุ้นลดน้อยลงจนเหลือเพียงคนเดียว (๕) เมื่อมีเหตุอื่นใดทำให้บริษัทนั้นไม่สามารถที่จะดำรงคงอยู่ต่อไปได้ แต่อย่างไรก็ดี ในกรณีทำผิดในการยื่นรายงานประชุมตั้งบริษัท หรือทำผิดในการประชุมตั้งบริษัท ศาลจะสั่งให้ยื่นรายงานประชุมตั้งบริษัท หรือให้มีการประชุมตั้งบริษัทแทนสั่งให้เลิกบริษัทก็ได้ แล้วแต่จะเห็นควร"}},{"id":"TH-H004-A1238","no":1238,"noLabel":{"th":"มาตรา 1238"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๓๘ บริษัทจำกัดจะควบรวมกันได้ โดยใช้มติพิเศษ บริษัทตั้งแต่สองบริษัทขึ้นไป จะควบรวมในลักษณะใดลักษณะหนึ่งดังต่อไปนี้ (๑) ควบรวมกันโดยเป็นบริษัทขึ้นใหม่ และบริษัทที่มาควบรวมกันต่างหมดสภาพการเป็นนิติบุคคล (๒) ควบรวมกันโดยบริษัทหนึ่งบริษัทใดยังคงมีสภาพเป็นนิติบุคคล และบริษัทอื่นที่ควบรวมกันหมดสภาพจากการเป็นนิติบุคคล"}},{"id":"TH-H004-A1239","no":1239,"noLabel":{"th":"มาตรา 1239"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๓๙ มติพิเศษซึ่งวินิจฉัยให้ควบรวมบริษัทจำกัด บริษัทต้องนำไปจดทะเบียนภายในสิบสี่วันนับตั้งแต่วันลงมติ"}},{"id":"TH-H004-A1239.001","no":1239.001,"noLabel":{"th":"มาตรา 1239/1"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๓๙/๑ เมื่อมีมติพิเศษให้ควบรวมบริษัทแล้ว แต่มีผู้ถือหุ้นที่เข้าร่วมประชุมคัดค้านการควบรวมบริษัท บริษัทต้องจัดให้มีผู้ซื้อหุ้นของผู้ถือหุ้นดังกล่าวในราคาที่ตกลงกัน หรือในกรณีที่ไม่สามารถตกลงกันได้ให้ใช้ราคาตามที่ผู้ประเมินราคาเป็นผู้กำหนด ถ้าผู้ถือหุ้นนั้นไม่ยอมขายภายในสิบสี่วันนับแต่วันที่ได้รับคำเสนอขอซื้อ ให้บริษัทดำเนินการควบรวมบริษัทต่อไปได้ และให้ถือว่าผู้ถือหุ้นดังกล่าวนั้นเป็นผู้ถือหุ้นของบริษัทที่ควบรวม การแต่งตั้งผู้ประเมินราคาตามวรรคหนึ่งให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง"}},{"id":"TH-H004-A1240","no":1240,"noLabel":{"th":"มาตรา 1240"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๐ เมื่อมีมติพิเศษให้ควบรวมบริษัทแล้ว บริษัทต้องมีหนังสือบอกกล่าวมติดังกล่าวภายในสิบสี่วันนับแต่วันที่ได้มีมติไปยังเจ้าหนี้ของบริษัทตามรายชื่อที่ปรากฏในบัญชีของบริษัท ณ วันที่ที่ประชุมผู้ถือหุ้นลงมติให้ควบรวมบริษัทโดยกำหนดเวลาให้ส่งคำคัดค้านภายในหนึ่งเดือนนับแต่วันที่ได้รับหนังสือบอกกล่าวมตินั้น และให้บริษัทโฆษณามตินั้นทางหนังสือพิมพ์รายวันที่แพร่หลายภายในกำหนดเวลาสิบสี่วันนั้นด้วย ถ้ามีการคัดค้าน บริษัทจะควบรวมมิได้จนกว่าจะได้ชำระหนี้หรือได้ให้ประกันเพื่อหนี้นั้นแล้ว"}},{"id":"TH-H004-A1240.001","no":1240.001,"noLabel":{"th":"มาตรา 1240/1"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๐/๑ เมื่อได้ดำเนินการตามมาตรา ๑๒๓๙ และมาตรา ๑๒๔๐ แล้ว ให้กรรมการบริษัทที่จะควบรวมเรียกประชุมผู้ถือหุ้นของบริษัทนั้น ๆ ให้มาประชุมร่วมกันเพื่อพิจารณาในเรื่อง ดังต่อไปนี้ (๑) ชื่อของบริษัทที่ควบรวม โดยจะใช้ชื่อใหม่หรือจะใช้ชื่อเดิมของบริษัทใดบริษัทหนึ่งที่จะควบรวมก็ได้ (๒) วัตถุประสงค์ของบริษัทที่ควบรวม (๓) ทุนเรือนหุ้นของบริษัทที่ควบรวม โดยจะต้องมีทุนเรือนหุ้นไม่น้อยกว่าทุนเรือนหุ้นของบริษัทเดิมอันมาควบรวม (๔) จัดสรรหุ้นของบริษัทที่ควบรวมให้แก่ผู้ถือหุ้น ทั้งนี้ มิให้นำมาตรา ๑๒๒๒ มาใช้บังคับ (๕) หนังสือบริคณห์สนธิของบริษัทที่ควบรวม (๖) ข้อบังคับของบริษัทที่ควบรวม (๗) เลือกตั้งกรรมการบริษัทที่ควบรวม (๘) เลือกตั้งผู้สอบบัญชีบริษัทที่ควบรวม (๙) เรื่องอื่น ๆ ที่จำเป็นในการควบรวมบริษัท ถ้าหากมี ทั้งนี้ ต้องดำเนินการประชุมให้เสร็จสิ้นภายในหกเดือนนับแต่วันที่บริษัทใดบริษัทหนึ่งได้ลงมติให้ควบรวมเป็นรายหลังสุด เว้นแต่ที่ประชุมตามมาตรานี้ลงมติให้ขยายเวลาออกไปแต่เมื่อรวมเวลาทั้งหมดแล้วต้องไม่เกินหนึ่งปี"}},{"id":"TH-H004-A1240.002","no":1240.002,"noLabel":{"th":"มาตรา 1240/2"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๐/๒ ในการประชุมเพื่อพิจารณาเรื่องต่าง ๆ ร่วมกันตามมาตรา ๑๒๔๐/๑ ให้ประชุมในท้องที่อันเป็นที่ตั้งสำนักงานแห่งใหญ่ของบริษัทใดบริษัทหนึ่งที่จะควบรวม หรือในจังหวัดที่ใกล้เคียงที่ตั้งของสำนักงานแห่งใหญ่ของบริษัทใดบริษัทหนึ่งที่จะควบรวม โดย (๑) ต้องมีผู้ถือหุ้นซึ่งมีหุ้นนับรวมกันได้ไม่น้อยกว่ากึ่งหนึ่งของจำนวนหุ้นทั้งหมดของแต่ละบริษัทที่จะควบรวมมาประชุมจึงจะเป็นองค์ประชุม (๒) ให้ผู้ถือหุ้นซึ่งมาประชุมเลือกผู้ถือหุ้นคนหนึ่งเป็นประธาน (๓) การวินิจฉัยชี้ขาดของที่ประชุม ให้ถือเสียงข้างมากของผู้ถือหุ้นซึ่งมาประชุมตาม (๑) เว้นแต่จะตกลงกันเป็นอย่างอื่น"}},{"id":"TH-H004-A1240.003","no":1240.003,"noLabel":{"th":"มาตรา 1240/3"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๐/๓ คณะกรรมการบริษัทเดิมต้องส่งมอบกิจการ ทรัพย์สิน บัญชี เอกสาร และหลักฐานต่าง ๆ ของบริษัทให้แก่คณะกรรมการบริษัทที่ควบรวมแล้วภายในเจ็ดวันนับแต่วันที่เสร็จสิ้น การประชุมตามมาตรา ๑๒๔๐/๑"}},{"id":"TH-H004-A1241","no":1241,"noLabel":{"th":"มาตรา 1241"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๑ คณะกรรมการบริษัทที่ควบรวมต้องขอจดทะเบียนการควบรวมบริษัทพร้อมกับยื่นหนังสือบริคณห์สนธิ และข้อบังคับที่ที่ประชุมตามมาตรา ๑๒๔๐/๑ ได้อนุมัติแล้วต่อนายทะเบียนภายในสิบสี่วันนับแต่วันที่เสร็จสิ้นการประชุมตามมาตรา ๑๒๔๐/๑"}},{"id":"TH-H004-A1242","no":1242,"noLabel":{"th":"มาตรา 1242"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๒ เมื่อนายทะเบียนรับจดทะเบียนการควบรวมบริษัทแล้ว ให้นายทะเบียนหมายเหตุไว้ในทะเบียนดังนี้ (๑) ในกรณีที่ควบรวมกันเป็นบริษัทขึ้นใหม่ ให้หมายเหตุว่าบริษัทเดิมที่ควบรวมกันนั้นหมดสภาพจากการเป็นนิติบุคคล (๒) ในกรณีที่ควบรวมกันโดยมีบริษัทใดบริษัทหนึ่งยังคงมีสภาพเป็นนิติบุคคล ให้หมายเหตุว่าบริษัทอื่นที่เหลือนั้นหมดสภาพจากการเป็นนิติบุคคล"}},{"id":"TH-H004-A1243","no":1243,"noLabel":{"th":"มาตรา 1243"},"chapter":{"th":"ส่วน 9"},"text":{"th":"มาตรา ๑๒๔๓ บริษัทที่ควบรวมนี้ย่อมได้ไปทั้งทรัพย์สิน หนี้ สิทธิ หน้าที่และความรับผิดชอบบรรดามีอยู่แก่บริษัทเดิมอันได้มาควบรวมนั้นทั้งสิ้น"}},{"id":"TH-H004-A1244","no":1244,"noLabel":{"th":"มาตรา 1244"},"chapter":{"th":"ส่วน 10"},"text":{"th":"มาตรา ๑๒๔๔ อันหนังสือบอกกล่าวซึ่งบริษัทจะพึงส่งถึงผู้ถือหุ้นนั้น ถ้าว่าได้ส่งมอบให้แล้วถึงตัวก็ดี หรือส่งไปโดยทางไปรษณีย์สลักหลังถึงสำนักอาศัยของผู้ถือหุ้นดังที่ปรากฏในทะเบียนของบริษัทแล้วก็ดี ท่านให้ถือว่าเป็นอันได้ส่งชอบแล้ว"}},{"id":"TH-H004-A1245","no":1245,"noLabel":{"th":"มาตรา 1245"},"chapter":{"th":"ส่วน 10"},"text":{"th":"มาตรา ๑๒๔๕ หนังสือบอกกล่าวใด ๆ เมื่อได้ส่งโดยทางไปรษณีย์สลักหลังถูกต้องแล้ว ท่านให้ถือว่าเป็นอันได้ส่งถึงมือผู้รับในเวลาที่หนังสือเช่นนั้นจะควรไปถึงได้ตามทางการปกติแห่งไปรษณีย์"}},{"id":"TH-H004-A1246","no":1246,"noLabel":{"th":"มาตรา 1246"},"chapter":{"th":"ส่วนที่ 11 การถอนทะเบียนบริษัทร้าง (ยกเลิก)"},"text":{"th":"มาตรา ๑๒๔๖ (ยกเลิก)"},"status":"repealed"},{"id":"TH-H004-A1246.001","no":1246.001,"noLabel":{"th":"มาตรา 1246/1"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๑ ห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัดอาจแปรสภาพเป็นบริษัทจำกัดได้ โดยความยินยอมของผู้เป็นหุ้นส่วนทุกคนและดำเนินการ ดังต่อไปนี้ (๑) แจ้งความยินยอมของผู้เป็นหุ้นส่วนที่จะให้แปรสภาพห้างหุ้นส่วนเป็นบริษัทจำกัดเป็นหนังสือต่อนายทะเบียนภายในสิบสี่วันนับแต่วันที่ผู้เป็นหุ้นส่วนทุกคนให้ความยินยอม (๒) ประกาศโฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราว และมีหนังสือบอกกล่าวไปยังบรรดาผู้ซึ่งรู้ว่าเป็นเจ้าหนี้ของห้างหุ้นส่วนบอกให้ทราบรายการที่ประสงค์จะแปรสภาพห้างหุ้นส่วนเป็นบริษัท และขอให้เจ้าหนี้ผู้มีข้อคัดค้านอย่างหนึ่งอย่างใดในการแปรสภาพเป็นบริษัทจำกัดนั้น ส่งคำคัดค้านไปภายในสามสิบวันนับแต่วันที่บอกกล่าวนั้น ถ้ามีการคัดค้าน ห้างหุ้นส่วนนั้นจะแปรสภาพมิได้จนกว่าจะได้ชำระหนี้หรือให้ประกันเพื่อหนี้นั้นแล้ว"}},{"id":"TH-H004-A1246.002","no":1246.002,"noLabel":{"th":"มาตรา 1246/2"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๒ ในกรณีไม่มีการคัดค้านหรือมีการคัดค้านแต่ห้างหุ้นส่วนได้ชำระหนี้หรือให้ประกันเพื่อหนี้นั้นแล้ว ผู้เป็นหุ้นส่วนทุกคนต้องประชุมเพื่อให้ความยินยอมและดำเนินการในเรื่อง ดังต่อไปนี้ (๑) จัดทำหนังสือบริคณห์สนธิและข้อบังคับของบริษัท (ถ้ามี) (๒) กำหนดจำนวนทุนเรือนหุ้นของบริษัท ซึ่งต้องเท่ากับส่วนลงหุ้นของผู้เป็นหุ้นส่วนทุกคนในห้างหุ้นส่วน และกำหนดจำนวนหุ้นของบริษัทที่จะตกได้แก่หุ้นส่วนแต่ละคน (๓) กำหนดจำนวนเงินที่ได้ใช้แล้วในแต่ละหุ้น ซึ่งต้องไม่น้อยกว่าร้อยละยี่สิบห้าแห่งมูลค่าของหุ้นแต่ละหุ้นที่ตั้งไว้ (๔) กำหนดจำนวนหุ้นสามัญหรือหุ้นบุริมสิทธิ รวมทั้งกำหนดสภาพและบุริมสิทธิของหุ้นซึ่งจะออกและจัดสรรหุ้นให้แก่ผู้เป็นหุ้นส่วน (๕) แต่งตั้งกรรมการและกำหนดอำนาจของกรรมการ (๖) แต่งตั้งผู้สอบบัญชี (๗) ดำเนินการในเรื่องอื่นๆ ที่จำเป็นในการแปรสภาพ ในการดำเนินการตามวรรคหนึ่ง ให้นำบทบัญญัติเกี่ยวกับบริษัทจำกัดว่าด้วยการนั้นๆ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1246.003","no":1246.003,"noLabel":{"th":"มาตรา 1246/3"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๓ หุ้นส่วนผู้จัดการเดิมต้องส่งมอบกิจการ ทรัพย์สิน บัญชีเอกสารและหลักฐานต่าง ๆ ของห้างหุ้นส่วนให้แก่คณะกรรมการบริษัท ภายในสิบสี่วันนับแต่วันที่ผู้เป็นหุ้นส่วนได้ให้ความยินยอมและดำเนินการในเรื่องต่างๆ ตามมาตรา ๑๒๔๖/๒ เสร็จสิ้นแล้ว ในกรณีที่ผู้เป็นหุ้นส่วนยังไม่ได้ชำระเงินค่าหุ้นหรือชำระเงินค่าหุ้นไม่ครบร้อยละยี่สิบห้าของมูลค่าหุ้น หรือยังไม่ได้โอนกรรมสิทธิ์ทรัพย์สิน หรือทำเอกสารหลักฐานการใช้สิทธิต่างๆ ให้แก่คณะกรรมการ ให้คณะกรรมการบริษัทมีหนังสือแจ้งให้ผู้เป็นหุ้นส่วนชำระเงินค่าหุ้น โอนกรรมสิทธิ์หรือทำเอกสารหลักฐานการใช้สิทธิต่างๆ แล้วแต่กรณี ให้แก่คณะกรรมการภายในสามสิบวันนับแต่วันที่ได้รับหนังสือแจ้ง"}},{"id":"TH-H004-A1246.004","no":1246.004,"noLabel":{"th":"มาตรา 1246/4"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๔ คณะกรรมการบริษัทต้องขอจดทะเบียนการแปรสภาพเป็นบริษัทจำกัดต่อนายทะเบียน ภายในสิบสี่วันนับแต่วันที่ได้ดำเนินการตามมาตรา ๑๒๔๖/๓ ครบถ้วนแล้ว ในการขอจดทะเบียนแปรสภาพเป็นบริษัทจำกัด คณะกรรมการต้องยื่นรายงานการประชุมที่ผู้เป็นหุ้นส่วนได้ร่วมกันพิจารณาให้ความยินยอมและดำเนินการแปรสภาพห้างหุ้นส่วนเป็นบริษัทจำกัดตามมาตรา ๑๒๔๖/๒ หนังสือบริคณห์สนธิ ข้อบังคับ และบัญชีรายชื่อผู้ถือหุ้น พร้อมกับการขอจดทะเบียนด้วย"}},{"id":"TH-H004-A1246.005","no":1246.005,"noLabel":{"th":"มาตรา 1246/5"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๕ เมื่อนายทะเบียนได้รับจดทะเบียนการแปรสภาพห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัดเป็นบริษัทจำกัดแล้ว ให้ห้างหุ้นส่วนจดทะเบียน หรือห้างหุ้นส่วนจำกัดเดิมหมดสภาพการเป็นห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัดตามประมวลกฎหมายแพ่งและพาณิชย์และให้นายทะเบียนหมายเหตุไว้ในทะเบียน"}},{"id":"TH-H004-A1246.006","no":1246.006,"noLabel":{"th":"มาตรา 1246/6"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๖ เมื่อห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัดได้จดทะเบียนแปรสภาพเป็นบริษัทจำกัดแล้ว บริษัทย่อมได้ไปทั้งทรัพย์สิน หนี้ สิทธิ และความรับผิดของห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัดเดิมทั้งหมด"}},{"id":"TH-H004-A1246.007","no":1246.007,"noLabel":{"th":"มาตรา 1246/7"},"chapter":{"th":"ส่วน 12"},"text":{"th":"มาตรา ๑๒๔๖/๗ เมื่อจดทะเบียนแปรสภาพเป็นบริษัทจำกัดแล้ว หากบริษัทไม่สามารถชำระหนี้ที่รับมาจากห้างหุ้นส่วนที่แปรสภาพได้ ให้เจ้าหนี้บังคับชำระหนี้เอาจากผู้เป็นหุ้นส่วนในห้างหุ้นส่วนที่แปรสภาพได้ตามที่ผู้เป็นหุ้นส่วนจะต้องรับผิดในหนี้ของห้างหุ้นส่วน"}},{"id":"TH-H004-A1247","no":1247,"noLabel":{"th":"มาตรา 1247"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๔๗ การชำระบัญชีห้างหุ้นส่วนจดทะเบียนหรือห้างหุ้นส่วนจำกัด หรือบริษัทจำกัดซึ่งล้มละลายนั้น ให้จัดทำไปตามบทกฎหมายลักษณะล้มละลายที่คงใช้อยู่ตามแต่จะทำได้ รัฐมนตรีเจ้าหน้าที่จะออกกฎกระทรวงว่าด้วยการชำระบัญชีห้างหุ้นส่วนและบริษัท และกำหนดอัตราค่าฤชาธรรมเนียมก็ออกได้"}},{"id":"TH-H004-A1248","no":1248,"noLabel":{"th":"มาตรา 1248"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๔๘ เมื่อกล่าวถึงประชุมใหญ่ในหมวดนี้ ท่านหมายความดังต่อไปนี้ คือ (๑) ถ้าเกี่ยวกับห้างหุ้นส่วนจดทะเบียนและห้างหุ้นส่วนจำกัด ก็คือการประชุมหุ้นส่วนทั้งปวงซึ่งอาศัยคะแนนเสียงข้างมากเป็นใหญ่ในการวินิจฉัย (๒) ถ้าเกี่ยวกับบริษัทจำกัด ก็คือการประชุมใหญ่ตามที่ได้บัญญัติไว้ในมาตรา ๑๑๗๑"}},{"id":"TH-H004-A1249","no":1249,"noLabel":{"th":"มาตรา 1249"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๔๙ ห้างหุ้นส่วนก็ดี บริษัทก็ดี แม้ว่าจะได้เลิกกันแล้ว ก็ให้พึงถือว่ายังคงตั้งอยู่ตราบเท่าเวลาที่จำเป็นเพื่อการชำระบัญชี"}},{"id":"TH-H004-A1250","no":1250,"noLabel":{"th":"มาตรา 1250"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๐ หน้าที่ของผู้ชำระบัญชี คือชำระสะสางการงานของห้างหุ้นส่วนหรือบริษัทนั้นให้เสร็จไป กับจัดการใช้หนี้เงินและแจกจำหน่ายสินทรัพย์ของห้างหุ้นส่วนหรือบริษัทนั้น"}},{"id":"TH-H004-A1251","no":1251,"noLabel":{"th":"มาตรา 1251"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๑ ห้างหุ้นส่วนก็ดี บริษัทก็ดี ในเมื่อเลิกกันเพราะเหตุอื่นนอกจากล้มละลาย หุ้นส่วนผู้จัดการห้างหรือกรรมการของบริษัทย่อมเข้าเป็นผู้ชำระบัญชี เว้นไว้แต่ข้อสัญญาของห้าง หรือข้อบังคับบริษัทจะมีกำหนดไว้เป็นสถานอื่น ถ้าไม่มีผู้ชำระบัญชีดังว่ามานี้ และเมื่อพนักงานอัยการหรือบุคคลอื่นผู้มีส่วนได้เสียในการนี้ร้องขอ ท่านให้ศาลตั้งผู้ชำระบัญชี"}},{"id":"TH-H004-A1252","no":1252,"noLabel":{"th":"มาตรา 1252"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๒ หุ้นส่วนผู้จัดการ หรือกรรมการบริษัทมีอำนาจโดยตำแหน่งเดิมฉันใด เมื่อเป็นผู้ชำระบัญชีก็ยังคงมีอำนาจอยู่ฉันนั้น"}},{"id":"TH-H004-A1253","no":1253,"noLabel":{"th":"มาตรา 1253"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๓ ภายในสิบสี่วันนับแต่ได้เลิกห้างเลิกบริษัท หรือถ้าศาลได้ตั้งผู้ชำระบัญชีนับแต่วันที่ศาลตั้ง ผู้ชำระบัญชีต้องกระทำดังจะกล่าวต่อไปนี้ คือ (๑) บอกกล่าวแก่ประชาชนโดยประกาศโฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราวว่าห้างหุ้นส่วนหรือบริษัทนั้นได้เลิกกันแล้วและให้ผู้เป็นเจ้าหนี้ทั้งหลายยื่นคำทวงหนี้แก่ผู้ชำระบัญชี (๒) ส่งคำบอกกล่าวอย่างเดียวกันเป็นจดหมายลงทะเบียนไปรษณีย์ไปยังเจ้าหนี้ทั้งหลายทุก ๆ คนบรรดามีชื่อปรากฏในสมุด บัญชี หรือเอกสารของห้างหรือบริษัทนั้น"}},{"id":"TH-H004-A1254","no":1254,"noLabel":{"th":"มาตรา 1254"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๔ การเลิกหุ้นส่วนหรือบริษัทนั้น ผู้ชำระบัญชีต้องนำบอกให้จดทะเบียนภายในสิบสี่วันนับแต่วันที่เลิกกัน และในการนี้ต้องระบุชื่อผู้ชำระบัญชีทุก ๆ คนให้จดลงทะเบียนไว้ด้วย"}},{"id":"TH-H004-A1255","no":1255,"noLabel":{"th":"มาตรา 1255"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๕ ผู้ชำระบัญชีต้องทำงบดุลขึ้นโดยเร็วที่สุดที่เป็นวิสัยจะทำได้ ส่งให้ผู้สอบบัญชีตรวจสอบลงสำคัญว่าถูกต้อง แล้วต้องเรียกประชุมใหญ่"}},{"id":"TH-H004-A1256","no":1256,"noLabel":{"th":"มาตรา 1256"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๖ ธุรการอันที่ประชุมใหญ่จะพึงทำนั้น คือ (๑) รับรองให้หุ้นส่วนผู้จัดการหรือกรรมการบริษัทคงเป็นผู้ชำระบัญชีต่อไป หรือเลือกตั้งผู้ชำระบัญชีใหม่ขึ้นแทนที่ และ (๒) อนุมัติบัญชีงบดุล อนึ่ง ที่ประชุมใหญ่จะสั่งให้ผู้ชำระบัญชีทำบัญชีตีราคาทรัพย์สิน หรือให้ทำการใด ๆ ก็ได้สุดแต่ที่ประชุมจะเห็นสมควร เพื่อชำระสะสางกิจการของห้างหุ้นส่วนหรือบริษัทให้เสร็จไป"}},{"id":"TH-H004-A1257","no":1257,"noLabel":{"th":"มาตรา 1257"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๗ ผู้ชำระบัญชีซึ่งมิใช่เป็นขึ้นเพราะศาลตั้งนั้น ท่านว่าจะถอนเสียจากตำแหน่งและตั้งผู้อื่นแทนที่ก็ได้ ในเมื่อผู้เป็นหุ้นส่วนทั้งหลายออกเสียงเป็นน้ำหนึ่งใจเดียวกัน หรือที่ประชุมใหญ่ของผู้ถือหุ้นได้ลงมติดังนั้น แต่ศาลย่อมสั่งถอนผู้ชำระบัญชีจากตำแหน่งและตั้งผู้อื่นแทนที่ได้ ไม่เลือกว่าจะเป็นผู้ชำระบัญชีซึ่งศาลตั้งหรือมิใช่ศาลตั้ง ในเมื่อมีคำร้องขอของผู้เป็นหุ้นส่วนในห้างคนใดคนหนึ่งหรือของผู้ถือหุ้นในบริษัทมีหุ้นรวมกันนับได้ถึงหนึ่งในยี่สิบแห่งทุนของบริษัท โดยจำนวนที่ส่งใช้เงินเข้าทุนแล้วนั้น"}},{"id":"TH-H004-A1258","no":1258,"noLabel":{"th":"มาตรา 1258"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๘ เมื่อมีการเปลี่ยนตัวผู้ชำระบัญชีใหม่ครั้งใด ผู้ชำระบัญชีต้องนำความจดทะเบียนภายในสิบสี่วันนับแต่วันที่ได้เปลี่ยนตัวกันนั้น"}},{"id":"TH-H004-A1259","no":1259,"noLabel":{"th":"มาตรา 1259"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๕๙ ผู้ชำระบัญชีทั้งหลายย่อมมีอำนาจดังจะกล่าวต่อไปนี้ คือ (๑) แก้ต่างว่าต่างในนามของห้างหุ้นส่วนหรือบริษัทในอรรถคดีพิพาทอันเป็นแพ่งหรืออาญาทั้งปวง และทำประณีประนอมยอมความ (๒) ดำเนินกิจการของห้างหุ้นส่วนหรือบริษัทตามแต่จำเป็น เพื่อการชำระสะสางกิจการให้เสร็จไปด้วยดี (๓) ขายทรัพย์สินของห้างหุ้นส่วนหรือบริษัท (๔) ทำการอย่างอื่น ๆ ตามแต่จำเป็น เพื่อชำระบัญชีให้เสร็จไปด้วยดี"}},{"id":"TH-H004-A1260","no":1260,"noLabel":{"th":"มาตรา 1260"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๐ ข้อจำกัดอำนาจของผู้ชำระบัญชีอย่างใด ๆ จะอ้างเป็นสมบูรณ์ต่อบุคคลภายนอกหาได้ไม่"}},{"id":"TH-H004-A1261","no":1261,"noLabel":{"th":"มาตรา 1261"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๑ ถ้ามีผู้ชำระบัญชีหลายคน การใด ๆ ที่ผู้ชำระบัญชีกระทำย่อมไม่เป็นอันสมบูรณ์นอกจากผู้ชำระบัญชีทั้งหลายจะได้ทำร่วมกัน เว้นแต่ที่ประชุมใหญ่หรือศาลจะได้กำหนดอำนาจไว้เป็นอย่างอื่นในเวลาตั้งผู้ชำระบัญชี"}},{"id":"TH-H004-A1262","no":1262,"noLabel":{"th":"มาตรา 1262"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๒ ถ้ามีมติของที่ประชุมใหญ่หรือคำบังคับของศาลให้อำนาจผู้ชำระบัญชีให้ทำการแยกกันได้ ท่านว่าต้องนำความจดทะเบียนภายในสิบสี่วันนับแต่วันลงมติหรือออกคำบังคับนั้น"}},{"id":"TH-H004-A1263","no":1263,"noLabel":{"th":"มาตรา 1263"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๓ ค่าธรรมเนียม ค่าภาระติดพัน และค่าใช้จ่ายซึ่งต้องเสียโดยควรในการชำระบัญชีนั้น ท่านว่าผู้ชำระบัญชีต้องจัดการใช้ก่อนหนี้เงินรายอื่น ๆ"}},{"id":"TH-H004-A1264","no":1264,"noLabel":{"th":"มาตรา 1264"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๔ ถ้าเจ้าหนี้คนใดมิได้มาทวงถามให้ใช้หนี้ ผู้ชำระบัญชีต้องวางเงินเท่าจำนวนหนี้นั้น ตามบทแห่งประมวลกฎหมายนี้ ว่าด้วยวางทรัพย์สินแทนชำระหนี้"}},{"id":"TH-H004-A1265","no":1265,"noLabel":{"th":"มาตรา 1265"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๕ ผู้ชำระบัญชีจะเรียกให้ผู้เป็นหุ้นส่วนหรือผู้ถือหุ้นส่งใช้เงินลงหุ้นอันเป็นส่วนยังค้างชำระอยู่นั้นก็ได้ และเงินที่ค้างชำระนี้ถึงแม้จะได้ตกลงกันไว้ก่อนโดยสัญญาเข้าหุ้นส่วน หรือโดยข้อบังคับของบริษัทว่าจะได้เรียกต่อภายหลังก็ตาม เมื่อเรียกเช่นนี้แล้ว ท่านว่าต้องส่งใช้ทันที"}},{"id":"TH-H004-A1266","no":1266,"noLabel":{"th":"มาตรา 1266"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๖ ถ้าผู้ชำระบัญชีมาพิจารณาเห็นว่า เมื่อเงินลงทุนหรือเงินค่าหุ้นได้ใช้เสร็จหมดแล้ว สินทรัพย์ก็ยังไม่พอกับหนี้สินไซร้ ผู้ชำระบัญชีต้องร้องขอต่อศาลทันที เพื่อให้ออกคำสั่งว่าห้างหุ้นส่วนหรือบริษัทนั้นล้มละลาย"}},{"id":"TH-H004-A1267","no":1267,"noLabel":{"th":"มาตรา 1267"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๗ ผู้ชำระบัญชีต้องทำรายงานยื่นไว้ ณ หอทะเบียนทุกระยะสามเดือนครั้งหนึ่งว่าได้จัดการไปอย่างใดบ้าง แสดงให้เป็นความเป็นไปของบัญชีที่ชำระอยู่นั้น และรายงานนี้ให้เปิดเผยแก่ผู้เป็นหุ้นส่วนและผู้ถือหุ้น และเจ้าหนี้ทั้งหลายตรวจดูได้โดยไม่ต้องเสียค่าธรรมเนียม"}},{"id":"TH-H004-A1268","no":1268,"noLabel":{"th":"มาตรา 1268"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๘ ถ้าการชำระบัญชีนั้นยังคงทำอยู่โดยกาลกว่าปีหนึ่งขึ้นไป ผู้ชำระบัญชีต้องเรียกประชุมใหญ่ในเวลาสิ้นปีทุกปีนับแต่เริ่มทำการชำระบัญชี และต้องทำรายงานยื่นที่ประชุมว่าได้จัดการไปอย่างไรบ้าง ทั้งแถลงให้ทราบความเป็นไปแห่งบัญชีโดยละเอียด"}},{"id":"TH-H004-A1269","no":1269,"noLabel":{"th":"มาตรา 1269"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๖๙ อันทรัพย์สินของห้างหุ้นส่วนหรือของบริษัทนั้น จะแบ่งคืนให้แก่ผู้เป็นหุ้นส่วนหรือผู้ถือหุ้นได้แต่เพียงเท่าที่ไม่ต้องเอาไว้ใช้ในการชำระหนี้ของห้างหุ้นส่วนหรือบริษัทเท่านั้น"}},{"id":"TH-H004-A1270","no":1270,"noLabel":{"th":"มาตรา 1270"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๗๐ เมื่อการชำระบัญชีกิจการของห้างหุ้นส่วนหรือบริษัทสำเร็จลง ผู้ชำระบัญชีต้องทำรายงานการชำระบัญชีแสดงว่า การชำระบัญชีนั้นได้ดำเนินไปอย่างใด และได้จัดการทรัพย์สินของห้างหุ้นส่วนหรือบริษัทนั้นไปประการใด แล้วให้เรียกประชุมใหญ่เพื่อเสนอรายงานนั้น และชี้แจงกิจการต่อที่ประชุม เมื่อที่ประชุมใหญ่ได้ให้อนุมัติรายงานนั้นแล้ว ผู้ชำระบัญชีต้องนำข้อความที่ได้ประชุมกันนั้นไปจดทะเบียนภายในสิบสี่วันนับแต่วันประชุม เมื่อได้จดทะเบียนแล้วดังนี้ให้ถือว่าเป็นที่สุดแห่งการชำระบัญชี"}},{"id":"TH-H004-A1271","no":1271,"noLabel":{"th":"มาตรา 1271"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๗๑ เมื่อเสร็จการชำระบัญชีแล้ว ท่านให้มอบบรรดาสมุดและบัญชี และเอกสารทั้งหลายของห้างหุ้นส่วนหรือบริษัทซึ่งได้ชำระบัญชีนั้นไว้แก่นายทะเบียนภายในกำหนดสิบสี่วันดังกล่าวไว้ในมาตราก่อน และให้นายทะเบียนรักษาสมุดและบัญชี และเอกสารเหล่านั้นไว้สิบปีนับแต่วันถึงที่สุดแห่งการชำระบัญชี สมุดและบัญชีและเอกสารเหล่านี้ ให้เปิดให้แก่บรรดาบุคคลผู้มีส่วนได้เสียตรวจดูได้โดยไม่เรียกค่าธรรมเนียมอย่างหนึ่งอย่างใด"}},{"id":"TH-H004-A1272","no":1272,"noLabel":{"th":"มาตรา 1272"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๗๒ ในคดีฟ้องเรียกหนี้สินซึ่งห้างหุ้นส่วนหรือบริษัท หรือผู้เป็นหุ้นส่วน หรือผู้ถือหุ้น หรือผู้ชำระบัญชีเป็นลูกหนี้อยู่ในฐานเช่นนั้น ท่านห้ามมิให้ฟ้องเมื่อพ้นกำหนดสองปีนับแต่วันถึงที่สุดแห่งการชำระบัญชี"}},{"id":"TH-H004-A1273","no":1273,"noLabel":{"th":"มาตรา 1273"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๒๗๓ บทบัญญัติแห่งมาตรา ๑๑๗๒ ถึงมาตรา ๑๑๙๓ กับมาตรา ๑๑๙๕ และมาตรา ๑๒๐๗ เหล่านี้ ท่านให้ใช้บังคับแก่การประชุมใหญ่ซึ่งมีขึ้นในระหว่างชำระบัญชีด้วยโดยอนุโลม"}},{"id":"TH-H004-A1273.001","no":1273.001,"noLabel":{"th":"มาตรา 1273/1"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๒๗๓/๑ เมื่อใดนายทะเบียนมีมูลเหตุอันควรเชื่อว่าห้างหุ้นส่วนจดทะเบียน ห้างหุ้นส่วนจำกัด หรือบริษัทจำกัดใด มิได้ทำการค้าขายหรือประกอบการงานแล้ว ให้นายทะเบียนมีหนังสือส่งทางไปรษณีย์ตอบรับไปยังห้างหุ้นส่วนหรือบริษัท เพื่อสอบถามว่ายังทำการค้าขายหรือประกอบการงานอยู่หรือไม่ และแจ้งว่าหากมิได้รับคำตอบภายในสามสิบวันนับแต่วันที่ส่งหนังสือจะได้โฆษณาในหนังสือพิมพ์เพื่อขีดชื่อห้างหุ้นส่วนหรือบริษัทนั้นออกเสียจากทะเบียน ถ้านายทะเบียนได้รับคำตอบจากห้างหุ้นส่วนหรือบริษัทนั้นว่า ห้างหุ้นส่วนหรือบริษัทมิได้ทำการค้าขายหรือประกอบการงานแล้วหรือมิได้รับคำตอบภายในสามสิบวันนับแต่วันที่ส่งหนังสือ ให้นายทะเบียนโฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราวและส่งหนังสือบอกกล่าวทางไปรษณีย์ตอบรับไปยังห้างหุ้นส่วนหรือบริษัทว่า เมื่อพ้นเวลาเก้าสิบวันนับแต่วันที่ส่งหนังสือบอกกล่าวห้างหุ้นส่วนหรือบริษัทนั้นจะถูกขีดชื่อออกจากทะเบียน เว้นแต่จะแสดงเหตุให้เห็นเป็นอย่างอื่น"}},{"id":"TH-H004-A1273.002","no":1273.002,"noLabel":{"th":"มาตรา 1273/2"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๒๗๓/๒ ในกรณีที่ห้างหุ้นส่วนหรือบริษัทเลิกกันแล้วและอยู่ระหว่างการชำระบัญชี หากนายทะเบียนมีมูลเหตุอันควรเชื่อว่าไม่มีตัวผู้ชำระบัญชีทำการอยู่ หรือการงานของห้างหุ้นส่วนหรือบริษัทได้ชำระสะสางตลอดแล้ว แต่ผู้ชำระบัญชีมิได้ทำรายงานการชำระบัญชี หรือมิได้ยื่นจดทะเบียนเสร็จการชำระบัญชีต่อนายทะเบียน ให้นายทะเบียนมีหนังสือส่งทางไปรษณีย์ตอบรับไปยังห้างหุ้นส่วนหรือบริษัท และผู้ชำระบัญชี ณ สถานที่อันปรากฏเป็นสำนักงานสุดท้าย แจ้งให้ดำเนินการเพื่อให้มีตัวผู้ชำระบัญชี หรือยื่นรายงานการชำระบัญชี หรือจดทะเบียนเสร็จการชำระบัญชี แล้วแต่กรณี และแจ้งว่าหากมิได้ดำเนินการดังกล่าวภายในระยะเวลาหนึ่งร้อยแปดสิบวันนับแต่วันที่ส่งหนังสือนั้นแล้วจะได้โฆษณาในหนังสือพิมพ์เพื่อขีดชื่อห้างหุ้นส่วนหรือบริษัทนั้นออกเสียจากทะเบียน ถ้าห้างหุ้นส่วนหรือบริษัท หรือผู้ชำระบัญชีมิได้ดำเนินการภายในกำหนดเวลาตามวรรคหนึ่งให้นายทะเบียนโฆษณาในหนังสือพิมพ์แห่งท้องที่อย่างน้อยหนึ่งคราว และส่งหนังสือบอกกล่าวทางไปรษณีย์ตอบรับไปยังห้างหุ้นส่วนหรือบริษัทและผู้ชำระบัญชีว่าเมื่อพ้นกำหนดเวลาเก้าสิบวันนับแต่วันที่ส่งหนังสือบอกกล่าว ห้างหุ้นส่วนหรือบริษัทนั้นจะถูกขีดชื่อออกจากทะเบียน เว้นแต่จะแสดงเหตุให้เห็นเป็นอย่างอื่น"}},{"id":"TH-H004-A1273.003","no":1273.003,"noLabel":{"th":"มาตรา 1273/3"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๒๗๓/๓ เมื่อสิ้นกำหนดเวลาตามที่แจ้งในหนังสือบอกกล่าวตามมาตรา ๑๒๗๓/๑ หรือมาตรา ๑๒๗๓/๒ แล้ว และห้างหุ้นส่วนหรือบริษัท หรือผู้ชำระบัญชีมิได้แสดงเหตุให้เห็นเป็นอย่างอื่น นายทะเบียนจะขีดชื่อห้างหุ้นส่วนหรือบริษัทนั้นออกเสียจากทะเบียนก็ได้ ในการนี้ให้ห้างหุ้นส่วนหรือบริษัทนั้นสิ้นสภาพนิติบุคคลตั้งแต่เมื่อนายทะเบียนขีดชื่อห้างหุ้นส่วนหรือบริษัทออกเสียจากทะเบียน แต่ความรับผิดของหุ้นส่วนผู้จัดการ ผู้เป็นหุ้นส่วน กรรมการ ผู้จัดการ และผู้ถือหุ้นมีอยู่เท่าไรก็ให้คงมีอยู่อย่างนั้นและพึงเรียกบังคับได้เสมือนห้างหุ้นส่วนหรือบริษัทนั้นยังมิได้สิ้นสภาพนิติบุคคล"}},{"id":"TH-H004-A1273.004","no":1273.004,"noLabel":{"th":"มาตรา 1273/4"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๒๗๓/๔ ถ้าห้างหุ้นส่วน ผู้เป็นหุ้นส่วน บริษัท ผู้ถือหุ้น หรือเจ้าหนี้ใด ๆ ของห้างหุ้นส่วนหรือบริษัทนั้นรู้สึกว่าต้องเสียหายโดยไม่เป็นธรรมเพราะการที่ห้างหุ้นส่วนหรือบริษัทถูกขีดชื่อออกจากทะเบียน เมื่อห้างหุ้นส่วน ผู้เป็นหุ้นส่วน บริษัท ผู้ถือหุ้นหรือเจ้าหนี้ยื่นคำร้องต่อศาลและศาลพิจารณาได้ความเป็นที่พอใจว่าในขณะที่ขีดชื่อห้างหุ้นส่วนหรือบริษัทออกจากทะเบียนห้างหุ้นส่วนหรือบริษัทยังทำการค้าขายหรือยังประกอบการงานอยู่ หรือเห็นเป็นการยุติธรรมในการที่จะให้ห้างหุ้นส่วนหรือบริษัทได้กลับคืนสู่ทะเบียนก็ดี ศาลจะสั่งให้จดชื่อห้างหุ้นส่วนหรือบริษัทกลับคืนเข้าสู่ทะเบียนก็ได้ และให้ถือว่าห้างหุ้นส่วนหรือบริษัทนั้นยังคงอยู่ตลอดมาเสมือนมิได้มีการขีดชื่อออกเลย โดยศาลจะสั่งและวางข้อกำหนดไว้เป็นประการใดๆ ตามที่เห็นเป็นการยุติธรรมด้วยก็ได้เพื่อให้ห้างหุ้นส่วนหรือบริษัทและบรรดาบุคคลอื่นๆ กลับคืนสู่ฐานะอันใกล้ที่สุดกับฐานะเดิมเสมือนห้างหุ้นส่วนหรือบริษัทนั้นมิได้ถูกขีดชื่อออกจากทะเบียนเลย การร้องขอให้ห้างหุ้นส่วนหรือบริษัทกลับคืนสู่ทะเบียน ห้ามมิให้ร้องขอเมื่อพ้นกำหนดสิบปีนับแต่วันที่นายทะเบียนขีดชื่อห้างหุ้นส่วนหรือบริษัทออกจากทะเบียน"}},{"id":"TH-H004-A1274","no":1274,"noLabel":{"th":"มาตรา 1274 ถึง มาตรา 1297"},"chapter":{"th":"ลักษณะ 23 (ยกเลิก)"},"text":{"th":"มาตรา ๑๒๗๔ ถึง มาตรา ๑๒๙๗ (ยกเลิก)"},"status":"repealed"},{"id":"TH-H004-A1298","no":1298,"noLabel":{"th":"มาตรา 1298"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๒๙๘ ทรัพยสิทธิทั้งหลายนั้น ท่านว่าจะก่อตั้งขึ้นได้แต่ด้วยอาศัยอำนาจในประมวลกฎหมายนี้หรือกฎหมายอื่น"}},{"id":"TH-H004-A1299","no":1299,"noLabel":{"th":"มาตรา 1299"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๒๙๙ ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่าการได้มาโดยนิติกรรมซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นไม่บริบูรณ์ เว้นแต่นิติกรรมจะได้ทำเป็นหนังสือและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่ ถ้ามีผู้ได้มาซึ่งอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์โดยทางอื่นนอกจากนิติกรรม สิทธิของผู้ได้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิทธิอันยังมิได้จดทะเบียนนั้น มิให้ยกขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้ได้สิทธิมาโดยเสียค่าตอบแทนและโดยสุจริต และได้จดทะเบียนสิทธิโดยสุจริตแล้ว"}},{"id":"TH-H004-A1300","no":1300,"noLabel":{"th":"มาตรา 1300"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๐ ถ้าได้จดทะเบียนการโอนอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์เป็นทางเสียเปรียบแก่บุคคลผู้อยู่ในฐานะอันจะให้จดทะเบียนสิทธิของตนได้อยู่ก่อนไซร้ ท่านว่าบุคคลนั้นอาจเรียกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผู้รับโอนกระทำการโดยสุจริตนั้น ไม่ว่ากรณีจะเป็นประการใดท่านว่าจะเรียกให้เพิกถอนทะเบียนไม่ได้"}},{"id":"TH-H004-A1301","no":1301,"noLabel":{"th":"มาตรา 1301"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๑ บทบัญญัติแห่งสองมาตราก่อนนี้ ท่านให้ใช้บังคับถึงการเปลี่ยนแปลง ระงับ และกลับคืนมาแห่งทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้นด้วยโดยอนุโลม"}},{"id":"TH-H004-A1302","no":1302,"noLabel":{"th":"มาตรา 1302"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๒ บทบัญญัติแห่งสามมาตราก่อนนี้ ให้ใช้บังคับถึงเรือมีระวางตั้งแต่ห้าตันขึ้นไป ทั้งแพและสัตว์พาหนะด้วยโดยอนุโลม"}},{"id":"TH-H004-A1303","no":1303,"noLabel":{"th":"มาตรา 1303"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๓ ถ้าบุคคลหลายคนเรียกเอาสังหาริมทรัพย์เดียวกัน โดยอาศัยหลักกรรมสิทธิ์ต่างกันไซร้ ท่านว่าทรัพย์สินตกอยู่ในครอบครองของบุคคลใด บุคคลนั้นมีสิทธิยิ่งกว่าบุคคลอื่น ๆ แต่ต้องได้ทรัพย์นั้นมาโดยมีค่าตอบแทนและได้การครอบครองโดยสุจริต ท่านมิให้ใช้มาตรานี้บังคับถึงสังหาริมทรัพย์ซึ่งระบุไว้ในมาตราก่อนและในเรื่องทรัพย์สินหาย กับทรัพย์สินที่ได้มาโดยการกระทำผิด"}},{"id":"TH-H004-A1304","no":1304,"noLabel":{"th":"มาตรา 1304"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๔ สาธารณสมบัติของแผ่นดินนั้น รวมทรัพย์สินทุกชนิดของแผ่นดินซึ่งใช้เพื่อสาธารณประโยชน์หรือสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น (๑) ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผู้เวนคืนหรือทอดทิ้งหรือกลับมาเป็นของแผ่นดินโดยประการอื่น ตามกฎหมายที่ดิน (๒) ทรัพย์สินสำหรับพลเมืองใช้ร่วมกัน เป็นต้นว่า ที่ชายตลิ่ง ทางน้ำ ทางหลวง ทะเลสาบ (๓) ทรัพย์สินใช้เพื่อประโยชน์ของแผ่นดินโดยเฉพาะ เป็นต้นว่า ป้อมและโรงทหาร สำนักราชการบ้านเมือง เรือรบ อาวุธยุทธภัณฑ์"}},{"id":"TH-H004-A1305","no":1305,"noLabel":{"th":"มาตรา 1305"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๕ ทรัพย์สินซึ่งเป็นสาธารณสมบัติของแผ่นดินนั้นจะโอนแก่กันมิได้ เว้นแต่อาศัยอำนาจแห่งบทกฎหมายเฉพาะหรือพระราชกฤษฎีกา"}},{"id":"TH-H004-A1306","no":1306,"noLabel":{"th":"มาตรา 1306"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๖ ท่านห้ามมิให้ยกอายุความขึ้นเป็นข้อต่อสู้กับแผ่นดินในเรื่องทรัพย์สินอันเป็นสาธารณสมบัติของแผ่นดิน"}},{"id":"TH-H004-A1307","no":1307,"noLabel":{"th":"มาตรา 1307"},"chapter":{"th":"ลักษณะ 1"},"text":{"th":"มาตรา ๑๓๐๗ ท่านห้ามมิให้ยึดทรัพย์สินของแผ่นดิน ไม่ว่าทรัพย์สินนั้นจะเป็นสาธารณสมบัติของแผ่นดินหรือไม่"}},{"id":"TH-H004-A1308","no":1308,"noLabel":{"th":"มาตรา 1308"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๐๘ ที่ดินแปลงใดเกิดที่งอกริมตลิ่ง ที่งอกย่อมเป็นทรัพย์สินของเจ้าของที่ดินแปลงนั้น"}},{"id":"TH-H004-A1309","no":1309,"noLabel":{"th":"มาตรา 1309"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๐๙ เกาะที่เกิดในทะเลสาบ หรือในทางน้ำหรือในเขตน่านน้ำของประเทศก็ดี และท้องทางน้ำที่เขินขึ้นก็ดี เป็นทรัพย์สินของแผ่นดิน"}},{"id":"TH-H004-A1310","no":1310,"noLabel":{"th":"มาตรา 1310"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๐ บุคคลใดสร้างโรงเรือนในที่ดินของผู้อื่นโดยสุจริตไซร้ ท่านว่าเจ้าของที่ดินเป็นเจ้าของโรงเรือนนั้น ๆ แต่ต้องใช้ค่าแห่งที่ดินเพียงที่เพิ่มขึ้นเพราะสร้างโรงเรือนนั้นให้แก่ผู้สร้าง แต่ถ้าเจ้าของที่ดินสามารถแสดงได้ว่า มิได้มีความประมาทเลินเล่อ จะบอกปัดไม่ยอมรับโรงเรือนนั้นและเรียกให้ผู้สร้างรื้อถอนไป และทำที่ดินให้เป็นตามเดิมก็ได้ เว้นไว้แต่ถ้าการนี้จะทำไม่ได้โดยใช้เงินพอสมควรไซร้ ท่านว่าเจ้าของที่ดินจะเรียกให้ผู้สร้างซื้อที่ดินทั้งหมดหรือแต่บางส่วนตามราคาตลาดก็ได้"}},{"id":"TH-H004-A1311","no":1311,"noLabel":{"th":"มาตรา 1311"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๑ บุคคลใดสร้างโรงเรือนในที่ดินของผู้อื่นโดยไม่สุจริตไซร้ ท่านว่าบุคคลนั้นต้องทำที่ดินให้เป็นตามเดิมแล้วส่งคืนเจ้าของ เว้นแต่เจ้าของจะเลือกให้ส่งคืนตามที่เป็นอยู่ ในกรณีเช่นนี้เจ้าของที่ดินต้องใช้ราคาโรงเรือนหรือใช้ค่าแห่งที่ดินเพียงที่เพิ่มขึ้นเพราะสร้างโรงเรือนนั้น แล้วแต่จะเลือก"}},{"id":"TH-H004-A1312","no":1312,"noLabel":{"th":"มาตรา 1312"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๒ บุคคลใดสร้างโรงเรือนรุกล้ำเข้าไปในที่ดินของผู้อื่นโดยสุจริตไซร้ ท่านว่าบุคคลนั้นเป็นเจ้าของโรงเรือนที่สร้างขึ้น แต่ต้องเสียเงินให้แก่เจ้าของที่ดินเป็นค่าใช้ที่ดินนั้น และจดทะเบียนสิทธิเป็นภาระจำยอม ต่อภายหลังถ้าโรงเรือนนั้นสลายไปทั้งหมด เจ้าของที่ดินจะเรียกให้เพิกถอนการจดทะเบียนเสียก็ได้ ถ้าบุคคลผู้สร้างโรงเรือนนั้นกระทำการโดยไม่สุจริต ท่านว่าเจ้าของที่ดินจะเรียกให้ผู้สร้างรื้อถอนไป และทำที่ดินให้เป็นตามเดิมโดยผู้สร้างเป็นผู้ออกค่าใช้จ่ายก็ได้"}},{"id":"TH-H004-A1313","no":1313,"noLabel":{"th":"มาตรา 1313"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๓ ถ้าผู้เป็นเจ้าของที่ดินโดยมีเงื่อนไขสร้างโรงเรือนในที่ดินนั้น และภายหลังที่ดินตกเป็นของบุคคลอื่นตามเงื่อนไขไซร้ ท่านให้นำบทบัญญัติแห่งประมวลกฎหมายนี้ว่าด้วยลาภมิควรได้มาใช้บังคับ"}},{"id":"TH-H004-A1314","no":1314,"noLabel":{"th":"มาตรา 1314"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๔ ท่านให้ใช้บทบัญญัติมาตรา ๑๓๑๐ มาตรา ๑๓๑๑ และมาตรา ๑๓๑๓ บังคับตลอดถึงการก่อสร้างใด ๆ ซึ่งติดที่ดินและการเพาะปลูกต้นไม้หรือธัญชาติด้วยโดยอนุโลม แต่ข้าวหรือธัญชาติอย่างอื่นอันจะเก็บเกี่ยวรวงผลได้คราวหนึ่งหรือหลายคราวต่อปี เจ้าของที่ดินต้องยอมให้บุคคลผู้กระทำการโดยสุจริต หรือผู้เป็นเจ้าของที่ดินโดยมีเงื่อนไขซึ่งได้เพาะปลูกลงไว้นั้น คงครองที่ดินจนกว่าจะเสร็จการเก็บเกี่ยวโดยใช้เงินคำนวณตามเกณฑ์ค่าเช่าที่ดินนั้น หรือเจ้าของที่ดินจะเข้าครอบครองในทันทีโดยใช้ค่าทดแทนให้แก่อีกฝ่ายหนึ่งก็ได้"}},{"id":"TH-H004-A1315","no":1315,"noLabel":{"th":"มาตรา 1315"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๕ บุคคลใดสร้างโรงเรือน หรือทำการก่อสร้างอย่างอื่นซึ่งติดที่ดิน หรือเพาะปลูกต้นไม้หรือธัญชาติในที่ดินของตนด้วยสัมภาระของผู้อื่น ท่านว่าบุคคลนั้นเป็นเจ้าของสัมภาระ แต่ต้องใช้ค่าสัมภาระ"}},{"id":"TH-H004-A1316","no":1316,"noLabel":{"th":"มาตรา 1316"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๖ ถ้าเอาสังหาริมทรัพย์ของบุคคลหลายคนมารวมเข้ากันจนเป็นส่วนควบหรือแบ่งแยกไม่ได้ไซร้ ท่านว่าบุคคลเหล่านั้นเป็นเจ้าของรวมแห่งทรัพย์ที่รวมเข้ากัน แต่ละคนมีส่วนตามค่าแห่งทรัพย์ของตนในเวลาที่รวมเข้ากับทรัพย์อื่น ถ้าทรัพย์อันหนึ่งอาจถือได้ว่าเป็นทรัพย์ประธานไซร้ ท่านว่าเจ้าของทรัพย์นั้นเป็นเจ้าของทรัพย์ที่รวมเข้ากันแต่ผู้เดียว แต่ต้องใช้ค่าแห่งทรัพย์อื่น ๆ ให้แก่เจ้าของทรัพย์นั้น ๆ"}},{"id":"TH-H004-A1317","no":1317,"noLabel":{"th":"มาตรา 1317"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๗ บุคคลใดใช้สัมภาระของบุคคลอื่นทำสิ่งใดขึ้นใหม่ไซร้ ท่านว่าเจ้าของสัมภาระเป็นเจ้าของสิ่งนั้นโดยมิต้องคำนึงว่าสัมภาระนั้นจะกลับคืนตามเดิมได้หรือไม่ แต่ต้องใช้ค่าแรงงาน แต่ถ้าค่าแรงงานเกินกว่าค่าสัมภาระที่ใช้นั้นมากไซร้ ท่านว่าผู้ทำเป็นเจ้าของทรัพย์ที่ทำขึ้น แต่ต้องใช้ค่าสัมภาระ"}},{"id":"TH-H004-A1318","no":1318,"noLabel":{"th":"มาตรา 1318"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๘ บุคคลอาจได้มาซึ่งกรรมสิทธิ์แห่งสังหาริมทรัพย์อันไม่มีเจ้าของโดยเข้าถือเอา เว้นแต่การเข้าถือเอานั้นต้องห้ามตามกฎหมาย หรือฝ่าฝืนสิทธิของบุคคลอื่นที่จะเข้าถือเอาสังหาริมทรัพย์นั้น"}},{"id":"TH-H004-A1319","no":1319,"noLabel":{"th":"มาตรา 1319"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๑๙ ถ้าเจ้าของสังหาริมทรัพย์เลิกครอบครองทรัพย์ด้วยเจตนาสละกรรมสิทธิ์ไซร้ ท่านว่าสังหาริมทรัพย์นั้นไม่มีเจ้าของ"}},{"id":"TH-H004-A1320","no":1320,"noLabel":{"th":"มาตรา 1320"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๐ ภายในบังคับแห่งกฎหมายเฉพาะและกฎข้อบังคับในเรื่องนั้น ท่านว่าสัตว์ป่าไม่มีเจ้าของตราบเท่าที่ยังอยู่อิสระ สัตว์ป่าในสวนสัตว์และปลาในบ่อ หรือในที่น้ำซึ่งเจ้าของกั้นไว้นั้น ท่านว่าไม่ใช่สัตว์ไม่มีเจ้าของ สัตว์ป่าที่คนจับได้นั้น ถ้ามันกลับคืนอิสระและเจ้าของไม่ติดตามโดยพลันหรือเลิกติดตามเสียแล้ว ฉะนี้ท่านว่าไม่มีเจ้าของ สัตว์ซึ่งเลี้ยงเชื่องแล้ว ถ้ามันทิ้งที่ไปเลย ท่านว่าไม่มีเจ้าของ"}},{"id":"TH-H004-A1321","no":1321,"noLabel":{"th":"มาตรา 1321"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๑ ภายในบังคับแห่งกฎหมายเฉพาะและกฎข้อบังคับในเรื่องนั้น ผู้ใดจับสัตว์ป่าได้ในที่รกร้างว่างเปล่าหรือในที่น้ำสาธารณะก็ดี หรือจับได้ในที่ดิน หรือที่น้ำมีเจ้าของโดยเจ้าของมิได้แสดงความหวงห้ามก็ดี ท่านว่าผู้นั้นเป็นเจ้าของสัตว์"}},{"id":"TH-H004-A1322","no":1322,"noLabel":{"th":"มาตรา 1322"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๒ บุคคลใดทำให้สัตว์ป่าบาดเจ็บแล้วติดตามไปและบุคคลอื่นจับสัตว์นั้นได้ก็ดี หรือสัตว์นั้นตายลงในที่ดินของบุคคลอื่นก็ดี ท่านว่าบุคคลแรกเป็นเจ้าของสัตว์"}},{"id":"TH-H004-A1323","no":1323,"noLabel":{"th":"มาตรา 1323"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๓ บุคคลเก็บได้ซึ่งทรัพย์สินหาย ต้องทำอย่างหนึ่งอย่างใดดังต่อไปนี้ (๑) ส่งมอบทรัพย์สินนั้นแก่ผู้ของหายหรือเจ้าของ หรือบุคคลอื่นผู้มีสิทธิจะรับทรัพย์สินนั้น หรือ (๒) แจ้งแก่ผู้ของหายหรือเจ้าของ หรือบุคคลอื่นผู้มีสิทธิจะรับทรัพย์สินนั้นโดยมิชักช้า หรือ (๓) ส่งมอบทรัพย์สินนั้นแก่เจ้าพนักงานตำรวจ หรือพนักงานเจ้าหน้าที่อื่นภายในสามวันและแจ้งพฤติการณ์ตามที่ทราบอันอาจเป็นเครื่องช่วยในการสืบหาตัวบุคคลผู้มีสิทธิจะรับทรัพย์สินนั้น แต่ถ้าไม่ทราบตัวผู้ของหาย เจ้าของ หรือบุคคลอื่นผู้มีสิทธิจะรับทรัพย์สินก็ดี หรือบุคคลดังระบุนั้นไม่รับมอบทรัพย์สินก็ดี ท่านให้ดำเนินการตามวิธีอันบัญญัติไว้ในอนุมาตรา (๓) ทั้งนี้ ท่านว่าผู้เก็บได้ซึ่งทรัพย์สินหายต้องรักษาทรัพย์สินนั้นไว้ด้วยความระมัดระวังอันสมควรจนกว่าจะส่งมอบ"}},{"id":"TH-H004-A1324","no":1324,"noLabel":{"th":"มาตรา 1324"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๔ ผู้เก็บได้ซึ่งทรัพย์สินหาย อาจเรียกร้องเอารางวัลจากบุคคลผู้มีสิทธิจะรับทรัพย์สินนั้นเป็นจำนวนร้อยละสิบแห่งค่าทรัพย์สินภายในราคาสามหมื่นบาทและถ้าราคาสูงกว่านั้นขึ้นไปให้คิดให้อีกร้อยละห้าในจำนวนที่เพิ่มขึ้น แต่ถ้าผู้เก็บได้ซึ่งทรัพย์สินหายได้ส่งมอบทรัพย์สินแก่เจ้าพนักงานตำรวจหรือพนักงานเจ้าหน้าที่อื่น ให้เสียเงินอีกร้อยละสองครึ่งแห่งค่าทรัพย์สินเป็นค่าธรรมเนียมแก่ทบวงการนั้น ๆ เพิ่มขึ้นเป็นส่วนหนึ่งต่างหากจากรางวัลซึ่งให้แก่ผู้เก็บได้แต่ค่าธรรมเนียมนี้ให้จำกัดไว้ไม่เกินหนึ่งพันบาท ถ้าผู้เก็บได้ซึ่งทรัพย์สินหายมิได้ปฏิบัติตามบทบัญญัติในมาตราก่อนไซร้ ท่านว่าผู้นั้นไม่มีสิทธิจะรับรางวัล"}},{"id":"TH-H004-A1325","no":1325,"noLabel":{"th":"มาตรา 1325"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๕ ถ้าผู้เก็บได้ซึ่งทรัพย์สินหายได้ปฏิบัติตามบทบัญญัติมาตรา ๑๓๒๓ แล้ว และผู้มีสิทธิจะรับทรัพย์สินนั้นมิได้เรียกเอาภายในหนึ่งปีนับแต่วันที่เก็บได้ไซร้ ท่านว่ากรรมสิทธิ์ตกแก่ผู้เก็บได้ แต่ถ้าทรัพย์สินซึ่งไม่มีผู้เรียกเอานั้นเป็นโบราณวัตถุไซร้ กรรมสิทธิ์แห่งทรัพย์สินนั้นตกแก่แผ่นดิน แต่ผู้เก็บได้มีสิทธิจะได้รับรางวัลร้อยละสิบแห่งค่าทรัพย์สินนั้น"}},{"id":"TH-H004-A1326","no":1326,"noLabel":{"th":"มาตรา 1326"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๖ การเก็บได้ซึ่งทรัพย์สินอันตกหรือทิ้งทะเล หรือทางน้ำหรือน้ำซัดขึ้นฝั่งนั้น ท่านให้บังคับตามกฎหมายและกฎข้อบังคับว่าด้วยการนั้น"}},{"id":"TH-H004-A1327","no":1327,"noLabel":{"th":"มาตรา 1327"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๗ ภายในบังคับแห่งกฎหมายอาญา กรรมสิทธิ์แห่งสิ่งใด ๆ ซึ่งได้ใช้ในการกระทำผิด หรือได้มาโดยการกระทำผิด หรือเกี่ยวกับการกระทำผิดโดยประการอื่น และได้ส่งไว้ในความรักษาของกรมในรัฐบาลนั้น ท่านว่าตกเป็นของแผ่นดิน ถ้าเจ้าของมิได้เรียกเอาภายในหนึ่งปีนับแต่วันส่ง หรือถ้าได้ฟ้องคดีอาญาต่อศาลแล้วนับแต่วันที่คำพิพากษาถึงที่สุด แต่ถ้าไม่ทราบตัวเจ้าของ ท่านให้ผ่อนเวลาออกไปเป็นห้าปี ถ้าทรัพย์สินเป็นของเสียง่าย หรือถ้าหน่วงช้าไว้จะเป็นการเสี่ยงความเสียหายหรือค่าใช้จ่ายจะเกินส่วนกับค่าของทรัพย์สินนั้นไซร้ ท่านว่ากรมในรัฐบาลจะจัดให้เอาออกขายทอดตลาดก่อนถึงกำหนดก็ได้ แต่ก่อนที่จะขายให้จัดการตามควรเพื่อบันทึกรายการอันเป็นเครื่องให้บุคคลผู้มีสิทธิจะรับทรัพย์สินนั้นอาจทราบว่าเป็นทรัพย์สินของตนและพิสูจน์สิทธิได้ เมื่อขายแล้วได้เงินเป็นจำนวนสุทธิเท่าใดให้ถือไว้แทนตัวทรัพย์สิน"}},{"id":"TH-H004-A1328","no":1328,"noLabel":{"th":"มาตรา 1328"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๘ สังหาริมทรัพย์มีค่าซึ่งซ่อนหรือฝังไว้นั้น ถ้ามีผู้เก็บได้โดยพฤติการณ์ซึ่งไม่มีผู้ใดสามารถอ้างว่าเป็นเจ้าของได้ ให้กรรมสิทธิ์ตกเป็นของแผ่นดิน ผู้เก็บได้ต้องส่งมอบทรัพย์นั้นแก่เจ้าพนักงานตำรวจหรือพนักงานเจ้าหน้าที่อื่น แล้วมีสิทธิจะได้รับรางวัลหนึ่งในสามแห่งค่าทรัพย์นั้น"}},{"id":"TH-H004-A1329","no":1329,"noLabel":{"th":"มาตรา 1329"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๒๙ สิทธิของบุคคลผู้ได้มาซึ่งทรัพย์สินโดยมีค่าตอบแทนและโดยสุจริตนั้น ท่านว่ามิเสียไป ถึงแม้ว่าผู้โอนทรัพย์สินให้จะได้ทรัพย์สินนั้นมาโดยนิติกรรมอันเป็นโมฆียะ และนิติกรรมนั้นได้ถูกบอกล้างภายหลัง"}},{"id":"TH-H004-A1330","no":1330,"noLabel":{"th":"มาตรา 1330"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๓๐ สิทธิของบุคคลผู้ซื้อทรัพย์สินโดยสุจริตในการขายทอดตลาดตามคำสั่งศาล หรือคำสั่งเจ้าพนักงานรักษาทรัพย์ในคดีล้มละลายนั้น ท่านว่ามิเสียไป ถึงแม้ภายหลังจะพิสูจน์ได้ว่าทรัพย์สินนั้นมิใช่ของจำเลย หรือลูกหนี้โดยคำพิพากษา หรือผู้ล้มละลาย"}},{"id":"TH-H004-A1331","no":1331,"noLabel":{"th":"มาตรา 1331"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๓๑ สิทธิของบุคคลผู้ได้เงินตรามาโดยสุจริตนั้น ท่านว่ามิเสียไป ถึงแม้ภายหลังจะพิสูจน์ได้ว่าเงินนั้นมิใช่ของบุคคลซึ่งได้โอนให้มา"}},{"id":"TH-H004-A1332","no":1332,"noLabel":{"th":"มาตรา 1332"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๓๒ บุคคลผู้ซื้อทรัพย์สินมาโดยสุจริตในการขายทอดตลาด หรือในท้องตลาด หรือจากพ่อค้าซึ่งขายของชนิดนั้น ไม่จำต้องคืนให้แก่เจ้าของแท้จริง เว้นแต่เจ้าของจะชดใช้ราคาที่ซื้อมา"}},{"id":"TH-H004-A1333","no":1333,"noLabel":{"th":"มาตรา 1333"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๓๓ ท่านว่ากรรมสิทธิ์นั้น อาจได้มาโดยอายุความตามที่บัญญัติไว้ในลักษณะ ๓ แห่งบรรพนี้"}},{"id":"TH-H004-A1334","no":1334,"noLabel":{"th":"มาตรา 1334"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๓๓๔ ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผู้เวนคืนหรือทอดทิ้งหรือกลับมาเป็นของแผ่นดินโดยประการอื่นตามกฎหมายที่ดินนั้น ท่านว่าบุคคลอาจได้มาตามกฎหมายที่ดิน"}},{"id":"TH-H004-A1335","no":1335,"noLabel":{"th":"มาตรา 1335"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๓๕ ภายในบังคับแห่งบทบัญญัติในประมวลกฎหมายนี้หรือกฎหมายอื่น ท่านว่าแดนแห่งกรรมสิทธิ์ที่ดินนั้นกินทั้งเหนือพื้นดินและใต้พื้นดินด้วย"}},{"id":"TH-H004-A1336","no":1336,"noLabel":{"th":"มาตรา 1336"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๓๖ ภายในบังคับแห่งกฎหมาย เจ้าของทรัพย์สินมีสิทธิใช้สอยและจำหน่ายทรัพย์สินของตนและได้ซึ่งดอกผลแห่งทรัพย์สินนั้น กับทั้งมีสิทธิติดตามและเอาคืนซึ่งทรัพย์สินของตนจากบุคคลผู้ไม่มีสิทธิจะยึดถือไว้ และมีสิทธิขัดขวางมิให้ผู้อื่นสอดเข้าเกี่ยวข้องกับทรัพย์สินนั้นโดยมิชอบด้วยกฎหมาย"}},{"id":"TH-H004-A1337","no":1337,"noLabel":{"th":"มาตรา 1337"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๓๗ บุคคลใดใช้สิทธิของตนเป็นเหตุให้เจ้าของอสังหาริมทรัพย์ได้รับความเสียหาย หรือเดือดร้อนเกินที่ควรคิดหรือคาดหมายได้ว่าจะเป็นไปตามปกติและเหตุอันควรในเมื่อเอาสภาพและตำแหน่งที่อยู่แห่งทรัพย์สินนั้นมาคำนึงประกอบไซร้ ท่านว่าเจ้าของอสังหาริมทรัพย์มีสิทธิจะปฏิบัติการเพื่อยังความเสียหายหรือเดือนร้อนนั้นให้สิ้นไป ทั้งนี้ ไม่ลบล้างสิทธิที่จะเรียกเอาค่าทดแทน"}},{"id":"TH-H004-A1338","no":1338,"noLabel":{"th":"มาตรา 1338"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๓๘ ข้อจำกัดสิทธิแห่งเจ้าของอสังหาริมทรัพย์ซึ่งกฎหมายกำหนดไว้นั้น ท่านว่าไม่จำต้องจดทะเบียน ข้อจำกัดเช่นนี้ ท่านว่าจะถอนหรือแก้ให้หย่อนลงโดยนิติกรรมไม่ได้ นอกจากจะได้ทำนิติกรรมเป็นหนังสือและจดทะเบียนกับพนักงานเจ้าหน้าที่ ข้อจำกัดซึ่งกำหนดไว้เพื่อสาธารณประโยชน์นั้น ท่านว่าจะถอนหรือแก้ให้หย่อนลงมิได้เลย"}},{"id":"TH-H004-A1339","no":1339,"noLabel":{"th":"มาตรา 1339"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๓๙ เจ้าของที่ดินจำต้องรับน้ำซึ่งไหลตามธรรมดาจากที่ดินสูงมาในที่ดินของตน น้ำไหลตามธรรมดามายังที่ดินต่ำ และจำเป็นแก่ที่ดินนั้นไซร้ ท่านว่าเจ้าของที่ดินซึ่งอยู่สูงกว่าจะกันเอาไว้ได้เพียงที่จำเป็นแก่ที่ดินของตน"}},{"id":"TH-H004-A1340","no":1340,"noLabel":{"th":"มาตรา 1340"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๐ เจ้าของที่ดินจำต้องรับน้ำซึ่งไหลเพราะระบายจากที่ดินสูงมาในที่ดินของตน ถ้าก่อนที่ระบายนั้นน้ำได้ไหลเข้ามาในที่ดินของตนตามธรรมดาอยู่แล้ว ถ้าได้รับความเสียหายเพราะการระบายน้ำ ท่านว่าเจ้าของที่ดินต่ำอาจเรียกร้องให้เจ้าของที่ดินสูงทำทางระบายน้ำและออกค่าใช้จ่ายในการนั้น เพื่อระบายน้ำไปให้ตลอดที่ดินต่ำจนถึงทางน้ำ หรือท่อน้ำสาธารณะ ทั้งนี้ ไม่ลบล้างสิทธิแห่งเจ้าของที่ดินต่ำในอันจะเรียกเอาค่าทดแทน"}},{"id":"TH-H004-A1341","no":1341,"noLabel":{"th":"มาตรา 1341"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๑ ท่านมิให้เจ้าของอสังหาริมทรัพย์ทำหลังคาหรือการปลูกสร้างอย่างอื่น ซึ่งทำให้น้ำฝนตกลงยังทรัพย์สินซึ่งอยู่ติดต่อกัน"}},{"id":"TH-H004-A1342","no":1342,"noLabel":{"th":"มาตรา 1342"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๒ บ่อ สระ หลุมรับน้ำโสโครก หรือหลุมรับปุ๋ย หรือขยะมูลฝอยนั้น ท่านว่าจะขุดในระยะสองเมตรจากแนวเขตที่ดินไม่ได้ คูหรือการขุดร่องเพื่อวางท่อน้ำใต้ดินหรือสิ่งอื่นซึ่งคล้ายกันนั้น ท่านว่าจะทำใกล้แนวเขตที่ดินกว่าครึ่งหนึ่งแห่งส่วนลึกของคูหรือร่องนั้นไม่ได้ แต่ถ้าทำห่างแนวเขตหนึ่งเมตรหรือกว่านั้น ท่านว่าทำได้ ถ้ากระทำการดังกล่าวไว้ในสองวรรคก่อนใกล้แนวเขตไซร้ ท่านว่าต้องใช้ความระมัดระวังตามควร เพื่อป้องกันมิให้ดินหรือทรายพังลง หรือมิให้น้ำหรือสิ่งโสโครกซึมเข้าไป"}},{"id":"TH-H004-A1343","no":1343,"noLabel":{"th":"มาตรา 1343"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๓ ห้ามมิให้ขุดดินหรือบรรทุกน้ำหนักบนที่ดินเกินควรจนอาจเป็นเหตุอันตรายแก่ความอยู่มั่นแห่งที่ดินติดต่อ เว้นแต่จะจัดการเพียงพอเพื่อป้องกันความเสียหาย"}},{"id":"TH-H004-A1344","no":1344,"noLabel":{"th":"มาตรา 1344"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๔ รั้ว กำแพง รั้วต้นไม้ คู ซึ่งหมายเขตที่ดินนั้น ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าของที่ดินทั้งสองข้างเป็นเจ้าของรวมกัน"}},{"id":"TH-H004-A1345","no":1345,"noLabel":{"th":"มาตรา 1345"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๕ เมื่อรั้วต้นไม้ หรือคูซึ่งมิได้ใช้เป็นทางระบายน้ำ เป็นของเจ้าของที่ดินทั้งสองข้างรวมกัน ท่านว่าเจ้าของข้างใดข้างหนึ่งมีสิทธิที่จะตัดรั้วต้นไม้ หรือถมคูนั้นได้ถึงแนวเขตที่ดินของตน แต่ต้องก่อกำแพง หรือทำรั้วตามแนวเขตนั้น"}},{"id":"TH-H004-A1346","no":1346,"noLabel":{"th":"มาตรา 1346"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๖ ถ้ามีต้นไม้อยู่บนแนวเขตที่ดิน ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าของที่ดินทั้งสองข้างเป็นเจ้าของต้นไม้รวมกัน ดอกผลเป็นของเจ้าของที่ดินคนละส่วนเสมอกัน และถ้าตัดต้นลงไซร้ ไม้นั้นเป็นของเจ้าของที่ดินคนละส่วนดุจกัน เจ้าของแต่ละฝ่ายจะต้องการให้ขุดหรือตัดต้นไม้ก็ได้ ค่าใช้จ่ายในการนั้นต้องเสียเท่ากันทั้งสองฝ่าย แต่ถ้าเจ้าของอีกฝ่ายหนึ่งสละสิทธิในต้นไม้ไซร้ ฝ่ายที่ต้องการขุดหรือตัดต้องเสียค่าใช้จ่ายฝ่ายเดียว ถ้าต้นไม้นั้นเป็นหลักเขตและจะหาหลักเขตอื่นไม่เหมาะเหมือน ท่านว่าฝ่ายหนึ่งฝ่ายใดจะต้องการให้ขุดหรือตัดไม่ได้"}},{"id":"TH-H004-A1347","no":1347,"noLabel":{"th":"มาตรา 1347"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๗ เจ้าของที่ดินอาจตัดรากไม้ซึ่งรุกเข้ามาจากที่ดินติดต่อและเอาไว้เสีย ถ้ากิ่งไม้ยื่นล้ำเข้ามา เมื่อเจ้าของที่ดินได้บอกผู้ครอบครองที่ดินติดต่อให้ตัดภายในเวลาอันสมควรแล้ว แต่ผู้นั้นไม่ตัด ท่านว่าเจ้าของที่ดินตัดเอาเสียได้"}},{"id":"TH-H004-A1348","no":1348,"noLabel":{"th":"มาตรา 1348"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๘ ดอกผลแห่งต้นไม้ที่หล่นตามธรรมดาลงในที่ดินติดต่อแปลงใด ท่านให้สันนิษฐานไว้ก่อนว่าเป็นดอกผลของที่ดินแปลงนั้น"}},{"id":"TH-H004-A1349","no":1349,"noLabel":{"th":"มาตรา 1349"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๔๙ ที่ดินแปลงใดมีที่ดินแปลงอื่นล้อมอยู่จนไม่มีทางออกถึงทางสาธารณะได้ไซร้ ท่านว่าเจ้าของที่ดินแปลงนั้นจะผ่านที่ดินซึ่งล้อมอยู่ไปสู่ทางสาธารณะได้ ที่ดินแปลงใดมีทางออกได้แต่เมื่อต้องข้ามสระ บึง หรือทะเล หรือมีที่ชันอันระดับที่ดินกับทางสาธารณะสูงกว่ากันมากไซร้ ท่านว่าให้ใช้ความในวรรคต้นบังคับ ที่และวิธีทำทางผ่านนั้นต้องเลือกให้พอควรแก่ความจำเป็นของผู้มีสิทธิจะผ่าน กับทั้งให้คำนึงถึงที่ดินที่ล้อมอยู่ให้เสียหายแต่น้อยที่สุดที่จะเป็นได้ ถ้าจำเป็น ผู้มีสิทธิจะผ่านจะสร้างถนนเป็นทางผ่านก็ได้ ผู้มีสิทธิจะผ่านต้องใช้ค่าทดแทนให้แก่เจ้าของที่ดินที่ล้อมอยู่เพื่อความเสียหายอันเกิดแต่เหตุที่มีทางผ่านนั้น ค่าทดแทนนั้นนอกจากค่าเสียหายเพราะสร้างถนน ท่านว่าจะกำหนดเป็นเงินรายปีก็ได้"}},{"id":"TH-H004-A1350","no":1350,"noLabel":{"th":"มาตรา 1350"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๐ ถ้าที่ดินแบ่งแยกหรือแบ่งโอนกันเป็นเหตุให้แปลงหนึ่งไม่มีทางออกไปสู่ทางสาธารณะไซร้ ท่านว่าเจ้าของที่ดินแปลงนั้นมีสิทธิเรียกร้องเอาทางเดินตามมาตราก่อนได้เฉพาะบนที่ดินแปลงที่ได้แบ่งแยกหรือแบ่งโอนกันและไม่ต้องเสียค่าทดแทน"}},{"id":"TH-H004-A1351","no":1351,"noLabel":{"th":"มาตรา 1351"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๑ เจ้าของที่ดิน เมื่อบอกล่วงหน้าตามสมควรแล้ว อาจใช้ที่ดินติดต่อเพียงที่จำเป็นในการปลูกสร้างหรือซ่อมแซมรั้ว กำแพง หรือโรงเรือน ตรงหรือใกล้แนวเขตของตน แต่จะเข้าไปในเรือนที่อยู่ของเพื่อนบ้านข้างเคียงไม่ได้ เว้นแต่ได้รับความยินยอม ถ้าได้ก่อความเสียหายให้เกิดขึ้นไซร้ ท่านว่าเพื่อนบ้านข้างเคียงจะเรียกเอาค่าทดแทนก็ได้"}},{"id":"TH-H004-A1352","no":1352,"noLabel":{"th":"มาตรา 1352"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๒ ท่านว่าถ้าเจ้าของที่ดินได้รับค่าทดแทนตามสมควรแล้ว ต้องยอมให้ผู้อื่นวางท่อน้ำ ท่อระบายน้ำ สายไฟฟ้า หรือสิ่งอื่นซึ่งคล้ายกันผ่านที่ดินของตน เพื่อประโยชน์แก่ที่ดินติดต่อ ซึ่งถ้าไม่ยอมให้ผ่านก็ไม่มีทางจะวางได้ หรือถ้าจะวางได้ก็เปลืองเงินมากเกินควร แต่เจ้าของที่ดินอาจให้ยกเอาประโยชน์ของตนขึ้นพิจารณาด้วย เมื่อมีเหตุผลพิเศษ ถ้าจะต้องวางเหนือพื้นดินไซร้ ท่านว่าเจ้าของที่ดินอาจเรียกให้ซื้อที่ดินของตนบางส่วนตามควรที่จะใช้ในการนั้น โดยราคาคุ้มค่าที่ดินและค่าทดแทนความเสียหาย ซึ่งอาจมีเพราะการขายนั้นด้วย ถ้าพฤติการณ์เปลี่ยนไป เจ้าของที่ดินอาจเรียกให้ย้ายถอนสิ่งที่วางนั้นไปไว้ ณ ส่วนอื่นแห่งที่ดินของตนตามแต่จะเหมาะแก่ประโยชน์แห่งเจ้าของที่ดิน ค่าย้ายถอนนั้นเจ้าของที่ดินติดต่อเป็นผู้เสีย แต่ถ้ามีพฤติการณ์พิเศษไซร้ ท่านว่าจะให้เจ้าของที่ดินอีกฝ่ายหนึ่งช่วยเสียค่าย้ายถอนตามส่วนอันควรก็ได้"}},{"id":"TH-H004-A1353","no":1353,"noLabel":{"th":"มาตรา 1353"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๓ บุคคลอาจพาปศุสัตว์ของตนผ่านหรือเข้าไปในที่ดินของผู้อื่นซึ่งมิได้กั้นเพื่อไปเลี้ยง และอาจเข้าไปเอาน้ำในบ่อหรือสระในที่เช่นว่านั้นมาใช้ได้ เว้นแต่ที่ดินเป็นที่เพาะปลูก หรือเตรียมเพื่อเพาะปลูก หว่าน หรือมีธัญชาติขึ้นอยู่แล้ว แต่ท่านว่าเจ้าของที่ดินย่อมห้ามได้เสมอ"}},{"id":"TH-H004-A1354","no":1354,"noLabel":{"th":"มาตรา 1354"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๔ ถ้ามีจารีตประเพณีแห่งท้องถิ่นให้ทำได้ และถ้าเจ้าของไม่ห้าม บุคคลอาจเข้าไปในที่ป่า ที่ดง หรือในที่มีหญ้าเลี้ยงสัตว์ซึ่งเป็นที่ดินของผู้อื่น เพื่อเก็บฟืน หรือผลไม้ป่า ผัก เห็ด และสิ่งเช่นกัน"}},{"id":"TH-H004-A1355","no":1355,"noLabel":{"th":"มาตรา 1355"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๓๕๕ เจ้าของที่ดินริมทางน้ำ หรือมีทางน้ำผ่าน ไม่มีสิทธิจะชักเอาน้ำไว้เกินกว่าที่จำเป็นแก่ประโยชน์ของตนตามควร ให้เป็นเหตุเสื่อมเสียแก่ที่ดินแปลงอื่นซึ่งอยู่ตามทางน้ำนั้น"}},{"id":"TH-H004-A1356","no":1356,"noLabel":{"th":"มาตรา 1356"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๕๖ ถ้าทรัพย์สินเป็นของบุคคลหลายคนรวมกัน ท่านให้ใช้บทบัญญัติในหมวดนี้บังคับ เว้นแต่จะมีกฎหมายบัญญัติไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1357","no":1357,"noLabel":{"th":"มาตรา 1357"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๕๗ ท่านให้สันนิษฐานไว้ก่อนว่าผู้เป็นเจ้าของรวมกันมีส่วนเท่ากัน"}},{"id":"TH-H004-A1358","no":1358,"noLabel":{"th":"มาตรา 1358"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๕๘ ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าของรวมมีสิทธิจัดการทรัพย์สินรวมกัน ในเรื่องจัดการตามธรรมดา ท่านว่าพึงตกลงโดยคะแนนข้างมากแห่งเจ้าของรวม แต่เจ้าของรวมคนหนึ่ง ๆ อาจทำสิ่งใดสิ่งหนึ่งในทางจัดการตามธรรมดาได้ เว้นแต่ฝ่ายข้างมากได้ตกลงไว้เป็นอย่างอื่น แต่เจ้าของรวมคนหนึ่ง ๆ อาจทำการเพื่อรักษาทรัพย์สินได้เสมอ ในเรื่องจัดการอันเป็นสาระสำคัญ ท่านว่าต้องตกลงกัน โดยคะแนนข้างมากแห่งเจ้าของรวม และคะแนนข้างมากนั้น ต้องมีส่วนไม่ต่ำกว่าครึ่งหนึ่งแห่งค่าทรัพย์สิน การเปลี่ยนแปลงวัตถุที่ประสงค์นั้น ท่านว่าจะตกลงกันได้ก็แต่เมื่อเจ้าของรวมเห็นชอบทุกคน"}},{"id":"TH-H004-A1359","no":1359,"noLabel":{"th":"มาตรา 1359"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๕๙ เจ้าของรวมคนหนึ่ง ๆ อาจใช้สิทธิอันเกิดแต่กรรมสิทธิ์ครอบไปถึงทรัพย์สินทั้งหมดเพื่อต่อสู้บุคคลภายนอก แต่ในการเรียกร้องเอาทรัพย์สินคืนนั้น ท่านว่าต้องอยู่ในบังคับแห่งเงื่อนไขที่ระบุไว้ในมาตรา ๓๐๒ แห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A1360","no":1360,"noLabel":{"th":"มาตรา 1360"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๐ เจ้าของรวมคนหนึ่ง ๆ มีสิทธิใช้ทรัพย์สินได้ แต่การใช้นั้นต้องไม่ขัดต่อสิทธิแห่งเจ้าของรวมคนอื่น ๆ ท่านให้สันนิษฐานไว้ก่อนว่าเจ้าของรวมคนหนึ่ง ๆ มีสิทธิได้ดอกผลตามส่วนของตนที่มีในทรัพย์สินนั้น"}},{"id":"TH-H004-A1361","no":1361,"noLabel":{"th":"มาตรา 1361"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๑ เจ้าของรวมคนหนึ่ง ๆ จะจำหน่ายส่วนของตน หรือจำนอง หรือก่อให้เกิดภาระติดพันก็ได้ แต่ตัวทรัพย์สินนั้นจะจำหน่าย จำนำ จำนอง หรือก่อให้เกิดภาระติดพันได้ ก็แต่ด้วยความยินยอมแห่งเจ้าของรวมทุกคน ถ้าเจ้าของรวมคนใดจำหน่าย จำนำ จำนอง หรือก่อให้เกิดภาระติดพันทรัพย์สินโดยมิได้รับความยินยอมแห่งเจ้าของรวมทุกคน แต่ภายหลังเจ้าของรวมคนนั้นได้เป็นเจ้าของทรัพย์สินแต่ผู้เดียวไซร้ ท่านว่านิติกรรมนั้นเป็นอันสมบูรณ์"}},{"id":"TH-H004-A1362","no":1362,"noLabel":{"th":"มาตรา 1362"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๒ เจ้าของรวมคนหนึ่ง ๆ จำต้องช่วยเจ้าของรวมคนอื่น ๆ ตามส่วนของตนในการออกค่าจัดการ ค่าภาษีอากร และค่ารักษา กับทั้งค่าใช้ทรัพย์สินรวมกันด้วย"}},{"id":"TH-H004-A1363","no":1363,"noLabel":{"th":"มาตรา 1363"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๓ เจ้าของรวมคนหนึ่ง ๆ มีสิทธิเรียกให้แบ่งทรัพย์สินได้ เว้นแต่จะมีนิติกรรมขัดอยู่ หรือถ้าวัตถุที่ประสงค์ที่เป็นเจ้าของรวมกันนั้นมีลักษณะเป็นการถาวร ก็เรียกให้แบ่งไม่ได้ สิทธิเรียกให้แบ่งทรัพย์สินนั้น ท่านว่าจะตัดโดยนิติกรรมเกินคราวละสิบปีไม่ได้ ท่านว่าเจ้าของรวมจะเรียกให้แบ่งทรัพย์สินในเวลาที่ไม่เป็นโอกาสอันควรไม่ได้"}},{"id":"TH-H004-A1364","no":1364,"noLabel":{"th":"มาตรา 1364"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๔ การแบ่งทรัพย์สินพึงกระทำโดยแบ่งทรัพย์สินนั้นเองระหว่างเจ้าของรวม หรือโดยขายทรัพย์สินแล้วเอาเงินที่ขายได้แบ่งกัน ถ้าเจ้าของรวมไม่ตกลงกันว่าจะแบ่งทรัพย์สินอย่างไรไซร้ เมื่อเจ้าของรวมคนหนึ่งคนใดขอ ศาลอาจสั่งให้เอาทรัพย์สินนั้นออกแบ่ง ถ้าส่วนที่แบ่งให้ไม่เท่ากันไซร้ จะสั่งให้ทดแทนกันเป็นเงินก็ได้ ถ้าการแบ่งเช่นว่านี้ไม่อาจทำได้หรือจะเสียหายมากนักก็ดี ศาลจะสั่งให้ขายโดยประมูลราคากันระหว่างเจ้าของรวมหรือขายทอดตลาดก็ได้"}},{"id":"TH-H004-A1365","no":1365,"noLabel":{"th":"มาตรา 1365"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๕ ถ้าเจ้าของรวมต้องรับผิดร่วมกันต่อบุคคลภายนอกในหนี้อันเกี่ยวกับทรัพย์สินรวม หรือในหนี้ซึ่งได้ก่อขึ้นใหม่เพื่อชำระหนี้เดิมดังว่านั้นก็ดี ในเวลาแบ่ง เจ้าของรวมคนหนึ่ง ๆ จะเรียกให้เอาทรัพย์สินรวมนั้นชำระหนี้เสียก่อน หรือให้เอาเป็นประกันก็ได้ ถ้าเจ้าของรวมคนหนึ่งต้องรับผิดต่อเจ้าของรวมคนอื่นในหนี้ ซึ่งเกิดจากการเป็นเจ้าของรวม หรือในหนี้ซึ่งได้ก่อขึ้นใหม่เพื่อชำระหนี้เดิมดังว่านั้นก็ดี ในเวลาแบ่ง เจ้าของรวมผู้เป็นเจ้าหนี้จะเรียกให้เอาส่วนซึ่งจะได้แก่ลูกหนี้ของตนในทรัพย์สินรวมนั้นชำระหนี้เสียก่อน หรือให้เอาเป็นประกันก็ได้ สิทธิที่กล่าวมาข้างต้นนี้อาจใช้แก่ผู้รับโอน หรือผู้สืบกรรมสิทธิ์ในส่วนของเจ้าของรวมนั้น ถ้าจำเป็นจะต้องขายทรัพย์สินรวมไซร้ ท่านให้นำบทบัญญัติมาตราก่อนมาใช้บังคับ"}},{"id":"TH-H004-A1366","no":1366,"noLabel":{"th":"มาตรา 1366"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๓๖๖ เจ้าของรวมคนหนึ่ง ๆ ต้องรับผิดตามส่วนของตนเช่นเดียวกับผู้ขายในทรัพย์สินซึ่งเจ้าของรวมคนอื่น ๆ ได้รับไปในการแบ่ง"}},{"id":"TH-H004-A1367","no":1367,"noLabel":{"th":"มาตรา 1367"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๖๗ บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน ท่านว่าบุคคลนั้นได้ซึ่งสิทธิครอบครอง"}},{"id":"TH-H004-A1368","no":1368,"noLabel":{"th":"มาตรา 1368"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๖๘ บุคคลอาจได้มาซึ่งสิทธิครอบครองโดยผู้อื่นยึดถือไว้ให้"}},{"id":"TH-H004-A1369","no":1369,"noLabel":{"th":"มาตรา 1369"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๖๙ บุคคลใดยึดถือทรัพย์สินไว้ ท่านให้สันนิษฐานไว้ก่อนว่า บุคคลนั้นยึดถือเพื่อตน"}},{"id":"TH-H004-A1370","no":1370,"noLabel":{"th":"มาตรา 1370"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๐ ผู้ครอบครองนั้น ท่านให้สันนิษฐานไว้ก่อนว่าครอบครองโดยสุจริต โดยความสงบและโดยเปิดเผย"}},{"id":"TH-H004-A1371","no":1371,"noLabel":{"th":"มาตรา 1371"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๑ ถ้าพิสูจน์ได้ว่าบุคคลใดครอบครองทรัพย์สินเดียวกันสองคราว ท่านให้สันนิษฐานไว้ก่อนว่า บุคคลนั้นได้ครอบครองติดต่อกันตลอดเวลา"}},{"id":"TH-H004-A1372","no":1372,"noLabel":{"th":"มาตรา 1372"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๒ สิทธิซึ่งผู้ครอบครองใช้ในทรัพย์สินที่ครอบครองนั้น ท่านให้สันนิษฐานไว้ก่อนว่าเป็นสิทธิซึ่งผู้ครอบครองมีตามกฎหมาย"}},{"id":"TH-H004-A1373","no":1373,"noLabel":{"th":"มาตรา 1373"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๓ ถ้าทรัพย์สินเป็นอสังหาริมทรัพย์ที่ได้จดไว้ในทะเบียนที่ดิน ท่านให้สันนิษฐานไว้ก่อนว่าบุคคลผู้มีชื่อในทะเบียนเป็นผู้มีสิทธิครอบครอง"}},{"id":"TH-H004-A1374","no":1374,"noLabel":{"th":"มาตรา 1374"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๔ ถ้าผู้ครอบครองถูกรบกวนในการครอบครองทรัพย์สิน เพราะมีผู้สอดเข้าเกี่ยวข้องโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ครอบครองมีสิทธิจะให้ปลดเปลื้องการรบกวนนั้นได้ ถ้าเป็นที่น่าวิตกว่าจะยังมีการรบกวนอีก ผู้ครอบครองจะขอต่อศาลให้สั่งห้ามก็ได้ การฟ้องคดีเพื่อปลดเปลื้องการรบกวนนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกรบกวน"}},{"id":"TH-H004-A1375","no":1375,"noLabel":{"th":"มาตรา 1375"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๕ ถ้าผู้ครอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมายไซร้ ท่านว่าผู้ครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่าซึ่งจะเป็นเหตุให้เรียกคืนจากผู้ครอบครองได้ การฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปีหนึ่งนับแต่เวลาถูกแย่งการครอบครอง"}},{"id":"TH-H004-A1376","no":1376,"noLabel":{"th":"มาตรา 1376"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๖ ถ้าจะต้องส่งทรัพย์สินคืนแก่บุคคลผู้มีสิทธิเอาคืนไซร้ ท่านให้นำบทบัญญัติมาตรา ๔๑๒ ถึงมาตรา ๔๑๘ แห่งประมวลกฎหมายนี้ว่าด้วยลาภมิควรได้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1377","no":1377,"noLabel":{"th":"มาตรา 1377"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๗ ถ้าผู้ครอบครองสละเจตนาครอบครองหรือไม่ยึดถือทรัพย์สินต่อไปไซร้ การครอบครองย่อมสุดสิ้นลง ถ้าเหตุอันมีสภาพเป็นเหตุชั่วคราวมีมาขัดขวางมิให้ผู้ครอบครองยึดถือทรัพย์สินไซร้ ท่านว่าการครอบครองไม่สุดสิ้นลง"}},{"id":"TH-H004-A1378","no":1378,"noLabel":{"th":"มาตรา 1378"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๘ การโอนไปซึ่งการครอบครองนั้นย่อมทำได้โดยส่งมอบทรัพย์สินที่ครอบครอง"}},{"id":"TH-H004-A1379","no":1379,"noLabel":{"th":"มาตรา 1379"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๗๙ ถ้าผู้รับโอนหรือผู้แทนยึดถือทรัพย์สินอยู่แล้ว ท่านว่าการโอนไปซึ่งการครอบครองจะทำเพียงแสดงเจตนาก็ได้"}},{"id":"TH-H004-A1380","no":1380,"noLabel":{"th":"มาตรา 1380"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๐ การโอนไปซึ่งการครอบครองย่อมเป็นผล แม้ผู้โอนยังยึดถือทรัพย์สินอยู่ ถ้าผู้โอนแสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผู้รับโอน ถ้าทรัพย์สินนั้นผู้แทนของผู้โอนยึดถืออยู่ การโอนไปซึ่งการครอบครองจะทำโดยผู้โอนสั่งผู้แทนว่า ต่อไปให้ยึดถือทรัพย์สินไว้แทนผู้รับโอนก็ได้"}},{"id":"TH-H004-A1381","no":1381,"noLabel":{"th":"มาตรา 1381"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๑ บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็นผู้แทนผู้ครอบครอง บุคคลนั้นจะเปลี่ยนลักษณะแห่งการยึดถือได้ ก็แต่โดยบอกกล่าวไปยังผู้ครอบครองว่าไม่เจตนาจะยึดถือทรัพย์สินแทนผู้ครอบครองต่อไป หรือตนเองเป็นผู้ครอบครองโดยสุจริต อาศัยอำนาจใหม่อันได้จากบุคคลภายนอก"}},{"id":"TH-H004-A1382","no":1382,"noLabel":{"th":"มาตรา 1382"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๒ บุคคลใดครอบครองทรัพย์สินของผู้อื่นไว้โดยความสงบและโดยเปิดเผยด้วยเจตนาเป็นเจ้าของ ถ้าเป็นอสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาสิบปี ถ้าเป็นสังหาริมทรัพย์ได้ครอบครองติดต่อกันเป็นเวลาห้าปีไซร้ ท่านว่าบุคคลนั้นได้กรรมสิทธิ์"}},{"id":"TH-H004-A1383","no":1383,"noLabel":{"th":"มาตรา 1383"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๓ ทรัพย์สินอันได้มาโดยการกระทำผิดนั้น ท่านว่าผู้กระทำผิดหรือผู้รับโอนไม่สุจริตจะได้กรรมสิทธิ์โดยอายุความก็แต่เมื่อพ้นกำหนดอายุความอาญา หรือพ้นเวลาที่กำหนดไว้ในมาตราก่อน ถ้ากำหนดไหนยาวกว่า ท่านให้ใช้กำหนดนั้น"}},{"id":"TH-H004-A1384","no":1384,"noLabel":{"th":"มาตรา 1384"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๔ ถ้าผู้ครอบครองขาดยึดถือทรัพย์สินโดยไม่สมัครและได้คืนภายในเวลาปีหนึ่งนับตั้งแต่วันขาดยึดถือหรือได้คืนโดยฟ้องคดีภายในกำหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุดหยุดลง"}},{"id":"TH-H004-A1385","no":1385,"noLabel":{"th":"มาตรา 1385"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๕ ถ้าโอนการครอบครองแก่กัน ผู้รับโอนจะนับเวลาซึ่งผู้โอนครอบครองอยู่ก่อนนั้นรวมเข้ากับเวลาครอบครองของตนก็ได้ ถ้าผู้รับโอนนับรวมเช่นนั้น และถ้ามีข้อบกพร่องในระหว่างครอบครองของผู้โอนไซร้ ท่านว่าข้อบกพร่องนั้นอาจยกขึ้นเป็นข้อต่อสู้ผู้รับโอนได้"}},{"id":"TH-H004-A1386","no":1386,"noLabel":{"th":"มาตรา 1386"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๓๘๖ บทบัญญัติว่าด้วยอายุความในประมวลกฎหมายนี้ ท่านให้ใช้บังคับในเรื่องอายุความได้สิทธิอันกล่าวไว้ในลักษณะนี้โดยอนุโลม"}},{"id":"TH-H004-A1387","no":1387,"noLabel":{"th":"มาตรา 1387"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๘๗ อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระจำยอมอันเป็นเหตุให้เจ้าของต้องยอมรับกรรมบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรือต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยู่ในกรรมสิทธิ์ทรัพย์สินนั้น เพื่อประโยชน์แก่อสังหาริมทรัพย์อื่น"}},{"id":"TH-H004-A1388","no":1388,"noLabel":{"th":"มาตรา 1388"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๘๘ เจ้าของสามยทรัพย์ไม่มีสิทธิทำการเปลี่ยนแปลงในภารยทรัพย์หรือในสามยทรัพย์ซึ่งทำให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์"}},{"id":"TH-H004-A1389","no":1389,"noLabel":{"th":"มาตรา 1389"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๘๙ ถ้าความต้องการแห่งเจ้าของสามยทรัพย์เปลี่ยนแปลงไป ท่านว่าความเปลี่ยนแปลงนั้นไม่ให้สิทธิแก่เจ้าของสามยทรัพย์ที่จะทำให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์ได้"}},{"id":"TH-H004-A1390","no":1390,"noLabel":{"th":"มาตรา 1390"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๐ ท่านมิให้เจ้าของภารยทรัพย์ประกอบกรรมใด ๆ อันจะเป็นเหตุให้ประโยชน์แห่งภาระจำยอมลดไปหรือเสื่อมความสะดวก"}},{"id":"TH-H004-A1391","no":1391,"noLabel":{"th":"มาตรา 1391"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๑ เจ้าของสามยทรัพย์มีสิทธิทำการทุกอย่างอันจำเป็นเพื่อรักษาและใช้ภาระจำยอม แต่ต้องเสียค่าใช้จ่ายของตนเอง ในการนี้เจ้าของสามยทรัพย์จะก่อให้เกิดความเสียหายแก่ภารยทรัพย์ได้ก็แต่น้อยที่สุดตามพฤติการณ์ เจ้าของสามยทรัพย์ต้องเสียค่าใช้จ่ายของตนเองรักษาซ่อมแซมการที่ได้ทำไปแล้วให้เป็นไปด้วยดี แต่ถ้าเจ้าของภารยทรัพย์ได้รับประโยชน์ด้วยไซร้ ท่านว่าต้องออกค่าใช้จ่ายตามส่วนแห่งประโยชน์ที่ได้รับ"}},{"id":"TH-H004-A1392","no":1392,"noLabel":{"th":"มาตรา 1392"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๒ ถ้าภาระจำยอมแตะต้องเพียงส่วนหนึ่งแห่งภารยทรัพย์ เจ้าของทรัพย์นั้นอาจเรียกให้ย้ายไปยังส่วนอื่นก็ได้ แต่ต้องแสดงได้ว่าการย้ายนั้นเป็นประโยชน์แก่ตนและรับเสียค่าใช้จ่าย ทั้งนี้ ต้องไม่ทำให้ความสะดวกของเจ้าของสามยทรัพย์ลดน้อยลง"}},{"id":"TH-H004-A1393","no":1393,"noLabel":{"th":"มาตรา 1393"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๓ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในนิติกรรมอันก่อให้เกิดภาระจำยอมไซร้ ท่านว่าภาระจำยอมย่อมติดไปกับสามยทรัพย์ซึ่งได้จำหน่าย หรือตกไปในบังคับแห่งสิทธิอื่น ท่านว่าจะจำหน่าย หรือทำให้ภาระจำยอมตกไปในบังคับแห่งสิทธิอื่นต่างหากจากสามยทรัพย์ไม่ได้"}},{"id":"TH-H004-A1394","no":1394,"noLabel":{"th":"มาตรา 1394"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๔ ถ้ามีการแบ่งแยกภารยทรัพย์ ท่านว่าภาระจำยอมยังคงมีอยู่ทุกส่วนที่แยกออก แต่ถ้าในส่วนใดภาระจำยอมนั้นไม่ใช้และใช้ไม่ได้ตามรูปการ ท่านว่าเจ้าของส่วนนั้นจะเรียกให้พ้นจากภาระจำยอมก็ได้"}},{"id":"TH-H004-A1395","no":1395,"noLabel":{"th":"มาตรา 1395"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๕ ถ้ามีการแบ่งแยกสามยทรัพย์ ท่านว่าภาระจำยอมยังคงมีอยู่เพื่อประโยชน์แก่ทุกส่วนที่แยกออกนั้น แต่ถ้าภาระจำยอมนั้นไม่ใช้และใช้ไม่ได้ตามรูปการเพื่อประโยชน์แก่ส่วนใดไซร้ ท่านว่าเจ้าของภารยทรัพย์จะเรียกให้พ้นจากภาระจำยอมอันเกี่ยวกับทรัพย์ส่วนนั้นก็ได้"}},{"id":"TH-H004-A1396","no":1396,"noLabel":{"th":"มาตรา 1396"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๖ ภาระจำยอมซึ่งเจ้าของรวมแห่งสามยทรัพย์คนหนึ่งได้มา หรือใช้อยู่นั้น ท่านให้ถือว่าเจ้าของรวมได้มาหรือใช้อยู่ด้วยกันทุกคน"}},{"id":"TH-H004-A1397","no":1397,"noLabel":{"th":"มาตรา 1397"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๗ ถ้าภารยทรัพย์หรือสามยทรัพย์สลายไปทั้งหมด ท่านว่าภาระจำยอมสิ้นไป"}},{"id":"TH-H004-A1398","no":1398,"noLabel":{"th":"มาตรา 1398"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๘ ถ้าภารยทรัพย์และสามยทรัพย์ตกเป็นของเจ้าของคนเดียวกัน ท่านว่าเจ้าของจะให้เพิกถอนการจดทะเบียนภาระจำยอมก็ได้ แต่ถ้ายังมิได้เพิกถอนทะเบียนไซร้ ภาระจำยอมยังคงมีอยู่ในส่วนบุคคลภายนอก"}},{"id":"TH-H004-A1399","no":1399,"noLabel":{"th":"มาตรา 1399"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๓๙๙ ภาระจำยอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้นไป"}},{"id":"TH-H004-A1400","no":1400,"noLabel":{"th":"มาตรา 1400"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๔๐๐ ถ้าภาระจำยอมหมดประโยชน์แก่สามยทรัพย์ไซร้ ท่านว่าภาระจำยอมนั้นสิ้นไป แต่ถ้าความเป็นไปมีทางให้กลับใช้ภาระจำยอมได้ไซร้ ท่านว่าภาระจำยอมนั้นกลับมีขึ้นอีก แต่ต้องยังไม่พ้นอายุความที่ระบุไว้ในมาตราก่อน ถ้าภาระจำยอมยังเป็นประโยชน์แก่สามยทรัพย์อยู่บ้าง แต่เมื่อเทียบกับภาระอันตกอยู่แก่ภารยทรัพย์แล้ว ประโยชน์นั้นน้อยนักไซร้ ท่านว่าเจ้าของภารยทรัพย์จะขอให้พ้นจากภาระจำยอมทั้งหมด หรือแต่บางส่วนก็ได้ แต่ต้องใช้ค่าทดแทน"}},{"id":"TH-H004-A1401","no":1401,"noLabel":{"th":"มาตรา 1401"},"chapter":{"th":"ลักษณะ 4"},"text":{"th":"มาตรา ๑๔๐๑ ภาระจำยอมอาจได้มาโดยอายุความ ท่านให้นำบทบัญญัติว่าด้วยอายุความได้สิทธิอันกล่าวไว้ในลักษณะ ๓ แห่งบรรพนี้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1402","no":1402,"noLabel":{"th":"มาตรา 1402"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๒ บุคคลใดได้รับสิทธิอาศัยในโรงเรือน บุคคลนั้นย่อมมีสิทธิอยู่ในโรงเรือนนั้นโดยไม่ต้องเสียค่าเช่า"}},{"id":"TH-H004-A1403","no":1403,"noLabel":{"th":"มาตรา 1403"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๓ สิทธิอาศัยนั้น ท่านว่าจะก่อให้เกิดโดยมีกำหนดเวลา หรือตลอดชีวิตของผู้อาศัยก็ได้ ถ้าไม่มีกำหนดเวลา ท่านว่าสิทธินั้นจะเลิกเสียในเวลาใด ๆ ก็ได้ แต่ต้องบอกล่วงหน้าแก่ผู้อาศัยตามสมควร ถ้าให้สิทธิอาศัยโดยมีกำหนดเวลา กำหนดนั้นท่านมิให้เกินสามสิบปี ถ้ากำหนดไว้นานกว่านั้น ให้ลดลงมาเป็นสามสิบปี การให้สิทธิอาศัยจะต่ออายุก็ได้ แต่ต้องกำหนดเวลาไม่เกินสามสิบปีนับแต่วันทำต่อ"}},{"id":"TH-H004-A1404","no":1404,"noLabel":{"th":"มาตรา 1404"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๔ สิทธิอาศัยนั้นจะโอนกันไม่ได้แม้โดยทางมรดก"}},{"id":"TH-H004-A1405","no":1405,"noLabel":{"th":"มาตรา 1405"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๕ สิทธิอาศัยนั้นถ้ามิได้จำกัดไว้ชัดแจ้งว่าให้เพื่อประโยชน์แก่ผู้อาศัยเฉพาะตัวไซร้ บุคคลในครอบครัวและในครัวเรือนของผู้อาศัยจะอยู่ด้วยก็ได้"}},{"id":"TH-H004-A1406","no":1406,"noLabel":{"th":"มาตรา 1406"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๖ ถ้าผู้ให้อาศัยมิได้ห้ามไว้ชัดแจ้ง ผู้อาศัยจะเก็บเอาดอกผลธรรมดาหรือผลแห่งที่ดิน มาใช้เพียงที่จำเป็นแก่ความต้องการของครัวเรือนก็ได้"}},{"id":"TH-H004-A1407","no":1407,"noLabel":{"th":"มาตรา 1407"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๗ ผู้ให้อาศัยไม่จำต้องบำรุงรักษาทรัพย์สินให้อยู่ในความซ่อมแซมอันดี ผู้อาศัยจะเรียกให้ชดใช้ค่าใช้จ่าย ซึ่งได้ออกไปในการทำให้ทรัพย์สินดีขึ้นหาได้ไม่"}},{"id":"TH-H004-A1408","no":1408,"noLabel":{"th":"มาตรา 1408"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๘ เมื่อสิทธิอาศัยสิ้นลง ผู้อาศัยต้องส่งทรัพย์สินคืนแก่ผู้ให้อาศัย"}},{"id":"TH-H004-A1409","no":1409,"noLabel":{"th":"มาตรา 1409"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๔๐๙ ท่านให้นำบทบัญญัติแห่งประมวลกฎหมายนี้ว่าด้วยหน้าที่และความรับผิดของผู้เช่าอันกล่าวไว้ในมาตรา ๕๕๒ ถึงมาตรา ๕๕๕ มาตรา ๕๕๘ มาตรา ๕๖๒ และมาตรา ๕๖๓ มาใช้บังคับโอนอนุโลม"}},{"id":"TH-H004-A1410","no":1410,"noLabel":{"th":"มาตรา 1410"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๐ เจ้าของที่ดินอาจก่อให้เกิดสิทธิเหนือพื้นดินเป็นคุณแก่บุคคลอื่น โดยให้บุคคลนั้นมีสิทธิเป็นเจ้าของโรงเรือน สิ่งปลูกสร้าง หรือสิ่งเพาะปลูก บนดินหรือใต้ดินนั้น"}},{"id":"TH-H004-A1411","no":1411,"noLabel":{"th":"มาตรา 1411"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๑ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในนิติกรรมอันก่อให้เกิดสิทธิเหนือพื้นดินไซร้ ท่านว่าสิทธินั้นอาจโอนได้และรับมรดกกันได้"}},{"id":"TH-H004-A1412","no":1412,"noLabel":{"th":"มาตรา 1412"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๒ สิทธิเหนือพื้นดินนั้นจะก่อให้เกิดโดยมีกำหนดเวลา หรือตลอดชีวิตเจ้าของที่ดิน หรือตลอดชีวิตผู้ทรงสิทธิเหนือพื้นดินนั้นก็ได้ ถ้าก่อให้เกิดสิทธิเหนือพื้นดินโดยมีกำหนดเวลาไซร้ ท่านให้นำบทบัญญัติมาตรา ๑๔๐๓ วรรคสาม มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1413","no":1413,"noLabel":{"th":"มาตรา 1413"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๓ ถ้าสิทธิเหนือพื้นดินนั้นไม่มีกำหนดเวลาไซร้ ท่านว่าคู่กรณีฝ่ายใดจะบอกเลิกเสียในเวลาใดก็ได้ แต่ต้องบอกล่วงหน้าแก่อีกฝ่ายหนึ่งตามสมควร ถ้ามีค่าเช่าซึ่งจำต้องให้แก่กันไซร้ ท่านว่าต้องบอกล่วงหน้าปีหนึ่ง หรือให้ค่าเช่าปีหนึ่ง"}},{"id":"TH-H004-A1414","no":1414,"noLabel":{"th":"มาตรา 1414"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๔ ถ้าผู้ทรงสิทธิเหนือพื้นดินละเลยไม่ปฏิบัติตามเงื่อนไขอันเป็นสาระสำคัญซึ่งระบุไว้ในนิติกรรมก่อตั้งสิทธินั้นก็ดี หรือถ้ามีค่าเช่าซึ่งจะต้องให้แก่กัน แต่ผู้ทรงสิทธิเหนือพื้นดินละเลยไม่ชำระถึงสองปีติด ๆ กันก็ดี ท่านว่าคู่กรณีอีกฝ่ายหนึ่งจะบอกเลิกสิทธิเหนือพื้นดินก็ได้"}},{"id":"TH-H004-A1415","no":1415,"noLabel":{"th":"มาตรา 1415"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๕ สิทธิเหนือพื้นดินนั้นไม่สิ้นไปโดยเหตุที่โรงเรือน สิ่งปลูกสร้าง หรือสิ่งเพาะปลูกสลายไป แม้การสลายนั้นจะเป็นเพราะเหตุสุดวิสัย"}},{"id":"TH-H004-A1416","no":1416,"noLabel":{"th":"มาตรา 1416"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๔๑๖ เมื่อสิทธิเหนือพื้นดินสิ้นไป ผู้ทรงสิทธิจะรื้อถอนโรงเรือน สิ่งปลูกสร้าง สิ่งเพาะปลูกของตนไปก็ได้ แต่ต้องทำให้ที่ดินเป็นตามเดิม แต่ถ้าเจ้าของที่ดินจะไม่ยอมให้รื้อถอนไป และบอกเจตนาจะซื้อตามราคาท้องตลาดไซร้ ท่านว่าผู้ทรงสิทธิเหนือพื้นดินจะไม่ยอมขายไม่ได้ เว้นแต่จะมีเหตุอันสมควร"}},{"id":"TH-H004-A1417","no":1417,"noLabel":{"th":"มาตรา 1417"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๑๗ อสังหาริมทรัพย์อาจต้องตกอยู่ในบังคับสิทธิเก็บกิน อันเป็นเหตุให้ผู้ทรงสิทธินั้นมีสิทธิครอบครอง ใช้ และถือเอาซึ่งประโยชน์แห่งทรัพย์สินนั้น ผู้ทรงสิทธิเก็บกินมีอำนาจจัดการทรัพย์สิน ผู้ทรงสิทธิเก็บกินในป่าไม้ เหมืองแร่ หรือที่ขุดหิน มีสิทธิทำการแสวงประโยชน์จากป่าไม้ เหมืองแร่ หรือที่ขุดหินนั้น"}},{"id":"TH-H004-A1418","no":1418,"noLabel":{"th":"มาตรา 1418"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๑๘ สิทธิเก็บกินนั้น จะก่อให้เกิดโดยมีกำหนดเวลา หรือตลอดชีวิตแห่งผู้ทรงสิทธิก็ได้ ถ้าไม่มีกำหนดเวลา ท่านให้สันนิษฐานไว้ก่อนว่าสิทธิเก็บกินมีอยู่ตลอดชีวิตผู้ทรงสิทธิ ถ้ามีกำหนดเวลา ท่านให้นำบทบัญญัติมาตรา ๑๔๐๓ วรรคสาม มาใช้บังคับโดยอนุโลม ถ้าผู้ทรงสิทธิเก็บกินถึงแก่ความตาย ท่านว่าสิทธินั้นย่อมสิ้นไปเสมอ"}},{"id":"TH-H004-A1419","no":1419,"noLabel":{"th":"มาตรา 1419"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๑๙ ถ้าทรัพย์สินสลายไปโดยไม่ได้ค่าทดแทนไซร้ ท่านว่าเจ้าของไม่จำต้องทำให้คืนดี แต่ถ้าเจ้าของทำให้ทรัพย์สินคืนดีขึ้นเพียงใด ท่านว่าสิทธิเก็บกินก็กลับมีขึ้นเพียงนั้น ถ้าได้ค่าทดแทนไซร้ ท่านว่าเจ้าของหรือผู้ทรงสิทธิเก็บกิน ต้องให้ทรัพย์สินคืนดีเพียงที่สามารถทำได้ตามจำนวนเงินค่าทดแทนที่ได้รับ และสิทธิเก็บกินกลับมีขึ้นเพียงที่ทรัพย์สินกลับคืนดี แต่ถ้าพ้นวิสัยที่จะทำให้กลับคืนดีได้ สิทธิเก็บกินก็เป็นอันสิ้นไป และค่าทดแทนนั้นต้องแบ่งกันระหว่างเจ้าของทรัพย์สิน และผู้ทรงสิทธิเก็บกินตามส่วนแห่งความเสียหายของตน วิธีนี้ให้ใช้บังคับโดยอนุโลมถึงกรณีซึ่งทรัพย์สินถูกบังคับซื้อ และกรณีซึ่งทรัพย์สินสลายไปแต่บางส่วน หรือการทำให้คืนดีนั้นพ้นวิสัยในบางส่วน"}},{"id":"TH-H004-A1420","no":1420,"noLabel":{"th":"มาตรา 1420"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๐ เมื่อสิทธิเก็บกินสิ้นลง ผู้ทรงสิทธิต้องส่งทรัพย์สินคืนแก่เจ้าของ ถ้าทรัพย์สินสลายไป หรือเสื่อมราคาลง ผู้ทรงสิทธิเก็บกินต้องรับผิด เว้นแต่จะพิสูจน์ได้ว่าความเสียหายนั้นมิได้เกิดขึ้นเพราะความผิดของตน ถ้าผู้ทรงสิทธิเก็บกินใช้ทรัพย์สินสิ้นเปลืองไปโดยมิชอบ ท่านว่าต้องทำให้มีมาแทน ถ้าทรัพย์สินเสื่อมราคาเพราะการใช้ตามควรไซร้ ท่านว่าผู้ทรงสิทธิเก็บกินไม่จำต้องให้ค่าทดแทน"}},{"id":"TH-H004-A1421","no":1421,"noLabel":{"th":"มาตรา 1421"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๑ ในการใช้สิทธิเก็บกินนั้น ผู้ทรงสิทธิต้องรักษาทรัพย์สินเสมอกับที่วิญญูชนพึงรักษาทรัพย์สินของตนเอง"}},{"id":"TH-H004-A1422","no":1422,"noLabel":{"th":"มาตรา 1422"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๒ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในนิติกรรมอันก่อให้เกิดสิทธิเก็บกินไซร้ ท่านว่าผู้ทรงสิทธินั้นจะโอนการใช้สิทธิของตนให้บุคคลภายนอกก็ได้ ในกรณีเช่นนั้นเจ้าของทรัพย์สินอาจฟ้องร้องผู้รับโอนโดยตรง"}},{"id":"TH-H004-A1423","no":1423,"noLabel":{"th":"มาตรา 1423"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๓ เจ้าของทรัพย์สินจะคัดค้านมิให้ใช้ทรัพย์สินในทางอันมิชอบด้วยกฎหมาย หรือมิสมควรก็ได้ ถ้าเจ้าของพิสูจน์ได้ว่าสิทธิของตนตกอยู่ในภยันตราย ท่านว่าจะเรียกให้ผู้ทรงสิทธิเก็บกินหาประกันให้ก็ได้ เว้นแต่ในกรณีซึ่งผู้ให้ทรัพย์สินสงวนสิทธิเก็บกินในทรัพย์สินนั้นไว้เพื่อตนเอง ถ้าผู้ทรงสิทธิเก็บกินละเลยไม่หาประกันมาให้ภายในเวลาอันควรซึ่งกำหนดให้เพื่อการนั้น หรือถ้าผู้ทรงสิทธิเก็บกินมินำพาต่อคำคัดค้านแห่งเจ้าของ ยังคงใช้ทรัพย์สินนั้นในทางอันมิชอบด้วยกฎหมาย หรือมิควรไซร้ ท่านว่าศาลจะตั้งผู้รักษาทรัพย์เพื่อจัดการทรัพย์สินแทนผู้ทรงสิทธิเก็บกินก็ได้ แต่เมื่อหาประกันมาให้แล้ว ศาลจะถอนผู้รักษาทรัพย์ที่ตั้งขึ้นไว้นั้นก็ได้"}},{"id":"TH-H004-A1424","no":1424,"noLabel":{"th":"มาตรา 1424"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๔ ผู้ทรงสิทธิเก็บกินจำต้องสงวนภาวะแห่งทรัพย์สินมิให้เปลี่ยนไปในสาระสำคัญ กับต้องบำรุงรักษาปกติและซ่อมแซมเล็กน้อยด้วย ถ้าจำเป็นต้องซ่อมแซมใหญ่ หรือมีการสำคัญอันต้องทำเพื่อรักษาทรัพย์สินไซร้ ท่านว่าผู้ทรงสิทธิเก็บกินต้องแจ้งแก่เจ้าของทรัพย์สินโดยพลัน และต้องยอมให้จัดทำการนั้น ๆ ไป ถ้าเจ้าของทรัพย์สินละเลยเสีย ท่านว่าผู้ทรงสิทธิเก็บกินจะจัดทำการนั้นไปโดยให้เจ้าของทรัพย์สินออกค่าใช้จ่ายก็ได้"}},{"id":"TH-H004-A1425","no":1425,"noLabel":{"th":"มาตรา 1425"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๕ ค่าใช้จ่ายอันเป็นการจรนั้น ท่านว่าเจ้าของต้องเป็นผู้ออก แต่เพื่อจะออกค่าใช้จ่ายเช่นว่านี้ หรือค่าใช้จ่ายตามความในมาตราก่อน เจ้าของจะจำหน่ายทรัพย์สินบางส่วนก็ได้ เว้นแต่ผู้ทรงสิทธิเก็บกินจะเต็มใจทดรองเงินตามที่จำเป็นโดยไม่คิดดอกเบี้ย"}},{"id":"TH-H004-A1426","no":1426,"noLabel":{"th":"มาตรา 1426"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๖ ในระหว่างที่สิทธิเก็บกินยังมีอยู่ ผู้ทรงสิทธิต้องออกค่าใช้จ่ายในการจัดการทรัพย์สินตลอดจนเสียภาษีอากร กับทั้งต้องใช้ดอกเบี้ยหนี้สินซึ่งติดพันทรัพย์สินนั้น"}},{"id":"TH-H004-A1427","no":1427,"noLabel":{"th":"มาตรา 1427"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๗ ถ้าเจ้าของทรัพย์สินต้องการ ผู้ทรงสิทธิเก็บกินจำต้องเอาทรัพย์สินประกันวินาศภัยเพื่อประโยชน์แก่เจ้าของทรัพย์สิน และถ้าทรัพย์สินนั้นได้เอาประกันภัยไว้แล้ว ผู้ทรงสิทธิเก็บกินต้องต่อสัญญาประกันนั้นเมื่อถึงคราวต่อ ผู้ทรงสิทธิเก็บกินต้องเสียเบี้ยประกันภัยระหว่างที่สิทธิของตนยังมีอยู่"}},{"id":"TH-H004-A1428","no":1428,"noLabel":{"th":"มาตรา 1428"},"chapter":{"th":"ลักษณะ 7"},"text":{"th":"มาตรา ๑๔๒๘ คดีอันเกี่ยวกับสิทธิเก็บกินในระหว่างเจ้าของทรัพย์สินกับผู้ทรงสิทธิเก็บกิน หรือผู้รับโอนนั้น ท่านห้ามมิให้ฟ้องเมื่อเกินปีหนึ่งนับแต่วันสิทธิเก็บกินสุดสิ้นลง แต่ในคดีที่เจ้าของทรัพย์สินเป็นโจทก์นั้น ถ้าเจ้าของไม่อาจรู้ว่าสิทธิเก็บกินสุดสิ้นลงเมื่อใด ท่านให้นับอายุความปีหนึ่งนั้นตั้งแต่เวลาที่เจ้าของทรัพย์สินได้รู้ หรือควรรู้ว่าสิทธิเก็บกินสุดสิ้นลง"}},{"id":"TH-H004-A1429","no":1429,"noLabel":{"th":"มาตรา 1429"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๒๙ อสังหาริมทรัพย์อาจต้องตกอยู่ในภาระติดพันอันเป็นเหตุให้ผู้รับประโยชน์มีสิทธิได้รับการชำระหนี้เป็นคราว ๆ จากทรัพย์สินนั้น หรือได้ใช้และถือเอาซึ่งประโยชน์แห่งทรัพย์สินตามที่ระบุไว้"}},{"id":"TH-H004-A1430","no":1430,"noLabel":{"th":"มาตรา 1430"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๓๐ ภาระติดพันในอสังหาริมทรัพย์นั้น จะก่อให้เกิดโดยมีกำหนดเวลา หรือตลอดชีวิตแห่งผู้รับประโยชน์ก็ได้ ถ้าไม่มีกำหนดเวลา ท่านให้สันนิษฐานไว้ก่อนว่าภาระติดพันในอสังหาริมทรัพย์มีอยู่ตลอดชีวิตผู้รับประโยชน์ ถ้ามีกำหนดเวลา ท่านให้นำบทบัญญัติมาตรา ๑๔๐๓ วรรคสาม มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1431","no":1431,"noLabel":{"th":"มาตรา 1431"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๓๑ ถ้ามิได้กำหนดไว้เป็นอย่างอื่นในนิติกรรมอันก่อให้เกิดภาระติดพันไซร้ ท่านว่าภาระติดพันในอสังหาริมทรัพย์นั้นจะโอนกันไม่ได้แม้โดยทางมรดก"}},{"id":"TH-H004-A1432","no":1432,"noLabel":{"th":"มาตรา 1432"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๓๒ ถ้าผู้รับประโยชน์ละเลยไม่ปฏิบัติตามเงื่อนไขอันเป็นสาระสำคัญซึ่งระบุไว้ในนิติกรรมก่อตั้งภาระติดพันนั้นไซร้ ท่านว่าคู่กรณีอีกฝ่ายหนึ่งจะบอกเลิกสิทธิของผู้รับประโยชน์เสียก็ได้"}},{"id":"TH-H004-A1433","no":1433,"noLabel":{"th":"มาตรา 1433"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๓๓ ถ้าเจ้าของทรัพย์สินมิได้ชำระหนี้ตามภาระติดพันไซร้ ท่านว่านอกจากทางแก้สำหรับการไม่ชำระหนี้ ผู้รับประโยชน์อาจขอให้ศาลตั้งผู้รักษาทรัพย์เพื่อจัดการทรัพย์สินและชำระหนี้แทนเจ้าของ หรือสั่งให้เอาทรัพย์สินออกขายทอดตลาด และเอาเงินที่ขายได้จ่ายให้ผู้รับประโยชน์ตามจำนวนที่ควรได้ เพราะเจ้าของทรัพย์สินไม่ชำระหนี้ กับทั้งค่าแห่งภาระติดพันด้วย ถ้าเจ้าของทรัพย์สินหาประกันมาให้แล้ว ศาลจะไม่ออกคำสั่งตั้งผู้รักษาทรัพย์ หรือคำสั่งขายทอดตลาด หรือจะถอนผู้รักษาทรัพย์ที่ตั้งขึ้นไว้นั้น ก็ได้"}},{"id":"TH-H004-A1434","no":1434,"noLabel":{"th":"มาตรา 1434"},"chapter":{"th":"ลักษณะ 8"},"text":{"th":"มาตรา ๑๔๓๔ ท่านให้นำมาตรา ๑๓๘๘ ถึงมาตรา ๑๓๙๕ และมาตรา ๑๓๙๗ ถึงมาตรา ๑๔๐๐ มาใช้บังคับถึงภาระติดพันในอสังหาริมทรัพย์โดยอนุโลม"}},{"id":"TH-H004-A1435","no":1435,"noLabel":{"th":"มาตรา 1435"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๓๕ การหมั้นจะทำได้ต่อเมื่อบุคคลทั้งสองฝ่ายมีอายุสิบแปดปีบริบูรณ์แล้ว การหมั้นที่ฝ่าฝืนบทบัญญัติวรรคหนึ่งเป็นโมฆะ"}},{"id":"TH-H004-A1436","no":1436,"noLabel":{"th":"มาตรา 1436"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๓๖ ผู้เยาว์จะทำการหมั้นได้ต้องได้รับความยินยอมของบุคคลดังต่อไปนี้ (๑) บิดาและมารดา ในกรณีที่มีทั้งบิดามารดา (๒) บิดาหรือมารดา ในกรณีที่มารดาหรือบิดาตายหรือถูกถอนอำนาจปกครองหรือไม่อยู่ในสภาพหรือฐานะที่อาจให้ความยินยอม หรือโดยพฤติการณ์ผู้เยาว์ไม่อาจขอความยินยอมจากมารดาหรือบิดาได้ (๓) ผู้รับบุตรบุญธรรม ในกรณีที่ผู้เยาว์เป็นบุตรบุญธรรม (๔) ผู้ปกครอง ในกรณีที่ไม่มีบุคคลซึ่งอาจให้ความยินยอมตาม (๑) (๒) และ (๓) หรือมีแต่บุคคลดังกล่าวถูกถอนอำนาจปกครอง การหมั้นที่ผู้เยาว์ทำโดยปราศจากความยินยอมดังกล่าวเป็นโมฆียะ"}},{"id":"TH-H004-A1437","no":1437,"noLabel":{"th":"มาตรา 1437"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๓๗ การหมั้นจะสมบูรณ์เมื่อฝ่ายผู้หมั้นได้ส่งมอบหรือโอนทรัพย์สินอันเป็นของหมั้นให้แก่ผู้รับหมั้นเพื่อเป็นหลักฐานว่าจะสมรสกับผู้รับหมั้นนั้น เมื่อหมั้นแล้วให้ของหมั้นตกเป็นสิทธิแก่ผู้รับหมั้น สินสอด เป็นทรัพย์สินซึ่งฝ่ายผู้หมั้นให้แก่บิดามารดา ผู้รับบุตรบุญธรรมหรือผู้ปกครองฝ่ายผู้รับหมั้น แล้วแต่กรณี เพื่อตอบแทนการที่ผู้รับหมั้นยอมสมรส ถ้าไม่มีการสมรสโดยมีเหตุสำคัญอันเกิดแก่ผู้รับหมั้นหรือโดยมีพฤติการณ์ซึ่งฝ่ายผู้รับหมั้นต้องรับผิดชอบ ทำให้ผู้หมั้นไม่สมควรหรือไม่อาจสมรสกับผู้รับหมั้นนั้น ฝ่ายผู้หมั้นเรียกสินสอดคืนได้ ถ้าจะต้องคืนของหมั้นหรือสินสอดตามหมวดนี้ ให้นำบทบัญญัติมาตรา ๔๑๒ ถึงมาตรา ๔๑๘ แห่งประมวลกฎหมายนี้ว่าด้วยลาภมิควรได้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1438","no":1438,"noLabel":{"th":"มาตรา 1438"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๓๘ การหมั้นไม่เป็นเหตุที่จะร้องขอให้ศาลบังคับให้สมรสได้ ถ้าได้มีข้อตกลงกันไว้ว่าจะให้เบี้ยปรับในเมื่อผิดสัญญาหมั้น ข้อตกลงนั้นเป็นโมฆะ"}},{"id":"TH-H004-A1439","no":1439,"noLabel":{"th":"มาตรา 1439"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๓๙ เมื่อมีการหมั้นแล้ว ถ้าฝ่ายใดผิดสัญญาหมั้นอีกฝ่ายหนึ่งมีสิทธิเรียกให้รับผิดใช้ค่าทดแทน ในกรณีที่ฝ่ายผู้รับหมั้นเป็นฝ่ายผิดสัญญาหมั้นให้คืนของหมั้นแก่ฝ่ายผู้หมั้นด้วย"}},{"id":"TH-H004-A1440","no":1440,"noLabel":{"th":"มาตรา 1440"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๐ ค่าทดแทนนั้นอาจเรียกได้ ดังต่อไปนี้ (๑) ทดแทนความเสียหายต่อกายหรือชื่อเสียงแห่งผู้หมั้นหรือผู้รับหมั้นนั้น (๒) ทดแทนความเสียหายเนื่องจากการที่คู่หมั้น บิดามารดา หรือบุคคลผู้กระทำการในฐานะเช่นบิดามารดาได้ใช้จ่ายหรือต้องตกเป็นลูกหนี้เนื่องในการเตรียมการสมรสโดยสุจริตและตามสมควร (๓) ทดแทนความเสียหายเนื่องจากการที่คู่หมั้นได้จัดการทรัพย์สินหรือการอื่นอันเกี่ยวแก่อาชีพหรือทางทำมาหาได้ของตนไปโดยสมควรด้วยการคาดหมายว่าจะได้มีการสมรส ในกรณีที่ผู้รับหมั้นเป็นผู้มีสิทธิได้ค่าทดแทน ศาลอาจชี้ขาดว่า ของหมั้นที่ตกเป็นสิทธิแก่ผู้รับหมั้นนั้นเป็นค่าทดแทนทั้งหมดหรือเป็นส่วนหนึ่งของค่าทดแทนที่ผู้รับหมั้นพึงได้รับ หรือศาลอาจให้ค่าทดแทนโดยไม่คำนึงถึงของหมั้นที่ตกเป็นสิทธิแก่ผู้รับหมั้นนั้นก็ได้"}},{"id":"TH-H004-A1441","no":1441,"noLabel":{"th":"มาตรา 1441"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๑ ถ้าคู่หมั้นฝ่ายหนึ่งตายก่อนสมรส อีกฝ่ายหนึ่งจะเรียกร้องค่าทดแทนมิได้ ส่วนของหมั้นหรือสินสอดนั้นไม่ว่าผู้หมั้นหรือผู้รับหมั้นตาย ผู้รับหมั้นหรือฝ่ายผู้รับหมั้นไม่ต้องคืนให้แก่ฝ่ายผู้หมั้น"}},{"id":"TH-H004-A1442","no":1442,"noLabel":{"th":"มาตรา 1442"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๒ ในกรณีมีเหตุสำคัญอันเกิดแก่ผู้รับหมั้นทำให้ผู้หมั้นไม่สมควรสมรสกับผู้รับหมั้นนั้น ผู้หมั้นมีสิทธิบอกเลิกสัญญาหมั้นได้และให้ผู้รับหมั้นคืนของหมั้นแก่ผู้หมั้น"}},{"id":"TH-H004-A1443","no":1443,"noLabel":{"th":"มาตรา 1443"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๓ ในกรณีมีเหตุสำคัญอันเกิดแก่ผู้หมั้นทำให้ผู้รับหมั้นไม่สมควรสมรสกับผู้หมั้นนั้น ผู้รับหมั้นมีสิทธิบอกเลิกสัญญาหมั้นได้โดยมิต้องคืนของหมั้นแก่ผู้หมั้น"}},{"id":"TH-H004-A1444","no":1444,"noLabel":{"th":"มาตรา 1444"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๔ ถ้าเหตุอันทำให้คู่หมั้นบอกเลิกสัญญาหมั้นเป็นเพราะการกระทำชั่วอย่างร้ายแรงของคู่หมั้นอีกฝ่ายหนึ่งซึ่งได้กระทำภายหลังการหมั้น คู่หมั้นผู้กระทำชั่วอย่างร้ายแรงนั้นต้องรับผิดใช้ค่าทดแทนแก่คู่หมั้นผู้ใช้สิทธิบอกเลิกสัญญาหมั้นเสมือนเป็นผู้ผิดสัญญาหมั้น"}},{"id":"TH-H004-A1445","no":1445,"noLabel":{"th":"มาตรา 1445"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๕ คู่หมั้นฝ่ายหนึ่งอาจเรียกค่าทดแทนจากผู้ซึ่งได้ร่วมประเวณีกับคู่หมั้นของตน หรือผู้ซึ่งกระทำกับคู่หมั้นของตนเพื่อสนองความใคร่ของผู้นั้นหรือคู่หมั้นของตนโดยรู้หรือควรจะรู้ถึงการหมั้นนั้น เมื่อได้บอกเลิกสัญญาหมั้นแล้วตามมาตรา ๑๔๔๒ หรือมาตรา ๑๔๔๓ แล้วแต่กรณี"}},{"id":"TH-H004-A1446","no":1446,"noLabel":{"th":"มาตรา 1446"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๖ คู่หมั้นฝ่ายหนึ่งอาจเรียกค่าทดแทนจากผู้ซึ่งได้ข่มขืนกระทำชำเราหรือพยายามข่มขืนกระทำชำเราคู่หมั้นของตนโดยรู้หรือควรจะรู้ถึงการหมั้นนั้นได้โดยไม่จำต้องบอกเลิกสัญญาหมั้น"}},{"id":"TH-H004-A1447","no":1447,"noLabel":{"th":"มาตรา 1447"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๗ ค่าทดแทนอันจะพึงชดใช้แก่กันตามหมวดนี้ให้ศาลวินิจฉัยตามควรแก่พฤติการณ์ สิทธิเรียกร้องค่าทดแทนตามหมวดนี้ นอกจากค่าทดแทนตามมาตรา ๑๔๔๐ (๒) ไม่อาจโอนกันได้และไม่ตกทอดไปถึงทายาท เว้นแต่สิทธินั้นจะได้รับสภาพกันไว้เป็นหนังสือหรือผู้เสียหายได้เริ่มฟ้องคดีตามสิทธินั้นแล้ว"}},{"id":"TH-H004-A1447.001","no":1447.001,"noLabel":{"th":"มาตรา 1447/1"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๗/๑ สิทธิเรียกร้องค่าทดแทนตามมาตรา ๑๔๓๙ ให้มีอายุความหกเดือนนับแต่วันที่ผิดสัญญาหมั้น สิทธิเรียกร้องค่าทดแทนตามมาตรา ๑๔๔๔ ให้มีอายุความหกเดือนนับแต่วันรู้หรือควรรู้ถึงการกระทำชั่วอย่างร้ายแรงอันเป็นเหตุให้บอกเลิกสัญญาหมั้น แต่ต้องไม่เกินห้าปีนับแต่วันกระทำการดังกล่าว สิทธิเรียกร้องค่าทดแทนตามมาตรา ๑๔๔๕ และมาตรา ๑๔๔๖ ให้มีอายุความหกเดือนนับแต่วันที่ผู้หมั้นหรือผู้รับหมั้นรู้หรือควรรู้ถึงการกระทำของผู้อื่นอันจะเป็นเหตุให้เรียกค่าทดแทนและรู้ตัวผู้จะพึงใช้ค่าทดแทนนั้น แต่ต้องไม่เกินห้าปีนับแต่วันที่ผู้อื่นนั้นได้กระทำการดังกล่าว"}},{"id":"TH-H004-A1447.002","no":1447.002,"noLabel":{"th":"มาตรา 1447/2"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๔๔๗/๒ สิทธิเรียกคืนของหมั้นตามมาตรา ๑๔๓๙ ให้มีอายุความหกเดือนนับแต่วันที่ผิดสัญญาหมั้น สิทธิเรียกคืนของหมั้นตามมาตรา ๑๔๔๒ ให้มีอายุความหกเดือนนับแต่วันที่ได้บอกเลิกสัญญาหมั้น"}},{"id":"TH-H004-A1448","no":1448,"noLabel":{"th":"มาตรา 1448"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๔๘ การสมรสจะกระทำได้ต่อเมื่อบุคคลทั้งสองฝ่ายมีอายุสิบแปดปีบริบูรณ์แล้ว แต่ในกรณีมีเหตุอันสมควร ศาลอาจอนุญาตให้ทำการสมรสก่อนนั้นได้"}},{"id":"TH-H004-A1449","no":1449,"noLabel":{"th":"มาตรา 1449"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๔๙ การสมรสจะกระทำมิได้ถ้าบุคคลใดบุคคลหนึ่งเป็นบุคคลวิกลจริตหรือเป็นบุคคลซึ่งศาลสั่งให้เป็นคนไร้ความสามารถ"}},{"id":"TH-H004-A1450","no":1450,"noLabel":{"th":"มาตรา 1450"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๐ บุคคลสองคนซึ่งเป็นญาติสืบสายโลหิตโดยตรงขึ้นไปหรือลงมาก็ดี เป็นพี่น้องร่วมบิดามารดาหรือร่วมแต่บิดาหรือมารดาก็ดี จะทำการสมรสกันไม่ได้ ความเป็นญาติดังกล่าวมานี้ให้ถือตามสายโลหิต โดยไม่คำนึงว่าจะเป็นญาติโดยชอบด้วยกฎหมายหรือไม่"}},{"id":"TH-H004-A1451","no":1451,"noLabel":{"th":"มาตรา 1451"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๑ ผู้รับบุตรบุญธรรมและบุตรบุญธรรมจะสมรสกันไม่ได้"}},{"id":"TH-H004-A1452","no":1452,"noLabel":{"th":"มาตรา 1452"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๒ บุคคลจะทำการสมรสในขณะที่ตนมีคู่สมรสอยู่ไม่ได้"}},{"id":"TH-H004-A1453","no":1453,"noLabel":{"th":"มาตรา 1453"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๓ หญิงที่ชายผู้เป็นคู่สมรสตายหรือที่การสมรสสิ้นสุดลงด้วยประการอื่นจะทำการสมรสใหม่กับชายได้ต่อเมื่อการสิ้นสุดแห่งการสมรสได้ผ่านพ้นไปแล้วไม่น้อยกว่าสามร้อยสิบวัน เว้นแต่ (๑) คลอดบุตรแล้วในระหว่างนั้น (๒) สมรสกับคู่สมรสเดิม (๓) มีใบรับรองแพทย์ประกาศนียบัตรหรือปริญญาซึ่งเป็นผู้ประกอบการรักษาโรคในสาขาเวชกรรมได้ตามกฎหมายว่ามิได้มีครรภ์ หรือ (๔) มีคำสั่งของศาลให้สมรสได้"}},{"id":"TH-H004-A1454","no":1454,"noLabel":{"th":"มาตรา 1454"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๔ ผู้เยาว์จะทำการสมรสให้นำความในมาตรา ๑๔๓๖ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1455","no":1455,"noLabel":{"th":"มาตรา 1455"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๕ การให้ความยินยอมให้ทำการสมรสจะกระทำได้แต่โดย (๑) ลงลายมือชื่อในทะเบียนขณะจดทะเบียนสมรส (๒) ทำเป็นหนังสือแสดงความยินยอม โดยระบุชื่อผู้จะสมรสทั้งสองฝ่ายและลงลายมือชื่อของผู้ให้ความยินยอม (๓) ถ้ามีเหตุจำเป็น จะให้ความยินยอมด้วยวาจาต่อหน้าพยานอย่างน้อยสองคนก็ได้ ความยินยอมนั้น เมื่อให้แล้วถอนไม่ได้"}},{"id":"TH-H004-A1456","no":1456,"noLabel":{"th":"มาตรา 1456"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๖ ถ้าไม่มีผู้ที่มีอำนาจให้ความยินยอมตามมาตรา ๑๔๕๔ หรือมีแต่ไม่ให้ความยินยอมหรือไม่อยู่ในสภาพที่อาจให้ความยินยอม หรือโดยพฤติการณ์ผู้เยาว์ไม่อาจขอความยินยอมได้ ผู้เยาว์อาจร้องขอต่อศาลเพื่ออนุญาตให้ทำการสมรส"}},{"id":"TH-H004-A1457","no":1457,"noLabel":{"th":"มาตรา 1457"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๗ การสมรสตามประมวลกฎหมายนี้จะมีได้เฉพาะเมื่อได้จดทะเบียนแล้วเท่านั้น"}},{"id":"TH-H004-A1458","no":1458,"noLabel":{"th":"มาตรา 1458"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๘ การสมรสจะทำได้ต่อเมื่อบุคคลสองคนยินยอมเป็นคู่สมรสกันและต้องแสดงการยินยอมนั้นให้ปรากฏโดยเปิดเผยต่อหน้านายทะเบียนและให้นายทะเบียนบันทึกความยินยอมนั้นไว้ด้วย"}},{"id":"TH-H004-A1459","no":1459,"noLabel":{"th":"มาตรา 1459"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๕๙ การสมรสในต่างประเทศระหว่างคนที่มีสัญชาติไทยด้วยกัน หรือฝ่ายใดฝ่ายหนึ่งมีสัญชาติไทย จะทำตามแบบที่กำหนดไว้ตามกฎหมายไทยหรือกฎหมายแห่งประเทศนั้นก็ได้ ในกรณีที่คู่สมรสประสงค์จะจดทะเบียนตามกฎหมายไทย ให้พนักงานทูตหรือกงสุลไทยเป็นผู้รับจดทะเบียน"}},{"id":"TH-H004-A1460","no":1460,"noLabel":{"th":"มาตรา 1460"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๔๖๐ เมื่อมีพฤติการณ์พิเศษซึ่งไม่อาจทำการจดทะเบียนสมรสต่อนายทะเบียนได้เพราะบุคคลฝ่ายใดฝ่ายหนึ่งหรือทั้งสองฝ่ายตกอยู่ในอันตรายใกล้ความตาย หรืออยู่ในภาวะการรบหรือสงคราม ถ้าบุคคลทั้งสองนั้นได้แสดงเจตนาจะสมรสกันต่อหน้าบุคคลซึ่งบรรลุนิติภาวะที่อยู่ ณ ที่นั้น แล้วให้บุคคลดังกล่าวจดแจ้งการแสดงเจตนาขอทำการสมรสของบุคคลทั้งสองนั้นไว้เป็นหลักฐาน และต่อมาบุคคลทั้งสองได้จดทะเบียนสมรสกันภายในเก้าสิบวันนับแต่วันที่อาจทำการจดทะเบียนต่อนายทะเบียนได้ โดยแสดงหลักฐานต่อนายทะเบียนและให้นายทะเบียนจดแจ้งวัน เดือน ปี สถานที่ที่แสดงเจตนาขอทำการสมรส และพฤติการณ์พิเศษนั้นไว้ในทะเบียนสมรส ให้ถือว่าวันแสดงเจตนาขอทำการสมรสต่อบุคคลดังกล่าวเป็นวันจดทะเบียนสมรสต่อนายทะเบียนแล้ว ความในมาตรานี้มิให้ใช้บังคับถ้าหากจะมีการสมรสในวันแสดงเจตนาขอทำการสมรส การสมรสนั้นจะตกเป็นโมฆะ"}},{"id":"TH-H004-A1461","no":1461,"noLabel":{"th":"มาตรา 1461"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๔๖๑ คู่สมรสต้องอยู่กินด้วยกันฉันคู่สมรส คู่สมรสต้องช่วยเหลืออุปการะเลี้ยงดูกันตามความสามารถและฐานะของตน"}},{"id":"TH-H004-A1462","no":1462,"noLabel":{"th":"มาตรา 1462"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๔๖๒ ในกรณีที่คู่สมรสไม่สามารถที่จะอยู่กินด้วยกันฉันคู่สมรสโดยปกติสุขได้ หรือถ้าการอยู่ร่วมกันจะเป็นอันตรายแก่กายหรือจิตใจหรือทำลายความผาสุกอย่างมาก คู่สมรสฝ่ายใดฝ่ายหนึ่งที่ไม่สามารถที่จะอยู่กินด้วยกันฉันคู่สมรสโดยปกติสุขได้หรือฝ่ายที่จะต้องรับอันตรายหรือถูกทำลายความผาสุก อาจร้องต่อศาลเพื่อให้มีคำสั่งอนุญาตให้ตนอยู่ต่างหากในระหว่างที่เหตุนั้น ๆ ยังมีอยู่ก็ได้ ในกรณีเช่นนี้ศาลจะกำหนดจำนวนค่าอุปการะเลี้ยงดูให้ฝ่ายหนึ่งจ่ายให้แก่อีกฝ่ายหนึ่งตามควรแก่พฤติการณ์ก็ได้"}},{"id":"TH-H004-A1463","no":1463,"noLabel":{"th":"มาตรา 1463"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๔๖๓ ในกรณีที่ศาลสั่งให้คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถ คู่สมรสอีกฝ่ายหนึ่งย่อมเป็นผู้อนุบาลหรือผู้พิทักษ์ แต่เมื่อผู้มีส่วนได้เสียหรืออัยการร้องขอ และถ้ามีเหตุสำคัญ ศาลจะตั้งผู้อื่นเป็นผู้อนุบาลหรือผู้พิทักษ์ก็ได้"}},{"id":"TH-H004-A1464","no":1464,"noLabel":{"th":"มาตรา 1464"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๔๖๔ ในกรณีที่คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นคนวิกลจริต ไม่ว่าศาลจะได้สั่งให้เป็นคนไร้ความสามารถหรือไม่ ถ้าคู่สมรสอีกฝ่ายหนึ่งไม่อุปการะเลี้ยงดูฝ่ายที่วิกลจริตตามมาตรา ๑๔๖๑ วรรคสอง หรือกระทำการหรือไม่กระทำการอย่างใด อันเป็นเหตุให้ฝ่ายที่วิกลจริตตกอยู่ในภาวะอันน่าจะเกิดอันตรายแก่กายหรือจิตใจ หรือตกอยู่ในภาวะอันน่าจะเกิดความเสียหายทางทรัพย์สินถึงขนาด บุคคลตามที่ระบุไว้ในมาตรา ๒๘ หรือผู้อนุบาลอาจฟ้องคู่สมรสอีกฝ่ายหนึ่งเรียกค่าอุปการะเลี้ยงดูให้แก่ฝ่ายที่วิกลจริต หรือขอให้ศาลมีคำสั่งใด ๆ เพื่อคุ้มครองฝ่ายที่วิกลจริตนั้นได้ ในกรณีฟ้องเรียกค่าอุปการะเลี้ยงดูตามวรรคหนึ่งถ้ายังมิได้มีคำสั่งของศาลว่าคู่สมรสซึ่งวิกลจริตเป็นคนไร้ความสามารถ ก็ให้ขอต่อศาลในคดีเดียวกันให้ศาลมีคำสั่งว่าคู่สมรสซึ่งวิกลจริตนั้นเป็นคนไร้ความสามารถ โดยขอให้ตั้งตนเองหรือผู้อื่นที่ศาลเห็นสมควรเป็นผู้อนุบาล หรือถ้าได้มีคำสั่งของศาลแสดงว่าคู่สมรสซึ่งวิกลจริตเป็นคนไร้ความสามารถอยู่แล้ว จะขอให้ถอดถอนผู้อนุบาลคนเดิมและแต่งตั้งผู้อนุบาลคนใหม่ก็ได้ ในการขอให้ศาลมีคำสั่งใด ๆ เพื่อคุ้มครองคู่สมรสฝ่ายที่วิกลจริตโดยมิได้เรียกค่าอุปการะเลี้ยงดูด้วยนั้น จะไม่ขอให้ศาลมีคำสั่งให้คู่สมรสฝ่ายที่วิกลจริตนั้นเป็นคนไร้ความสามารถ หรือจะไม่ขอเปลี่ยนผู้อนุบาลก็ได้ แต่ถ้าศาลเห็นว่าวิธีการคุ้มครองที่ขอนั้นจำต้องมีผู้อนุบาลหรือเปลี่ยนผู้อนุบาล ให้ศาลมีคำสั่งให้จัดการทำนองเดียวกับที่บัญญัติไว้ในวรรคสอง แล้วจึงมีคำสั่งคุ้มครองตามที่เห็นสมควร"}},{"id":"TH-H004-A1464.001","no":1464.001,"noLabel":{"th":"มาตรา 1464/1"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๔๖๔/๑ ในระหว่างการพิจารณาคดีตามมาตรา ๑๔๖๔ ถ้ามีคำขอศาลอาจกำหนดวิธีการชั่วคราวเกี่ยวกับการอุปการะเลี้ยงดูหรือการคุ้มครองคู่สมรสฝ่ายที่วิกลจริตได้ตามที่เห็นสมควร และหากเป็นกรณีฉุกเฉินให้นำบทบัญญัติเรื่องคำขอในเหตุฉุกเฉินตามประมวลกฎหมายวิธีพิจารณาความแพ่งมาใช้บังคับ"}},{"id":"TH-H004-A1465","no":1465,"noLabel":{"th":"มาตรา 1465"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๖๕ ถ้าคู่สมรสมิได้ทำสัญญากันไว้ในเรื่องทรัพย์สินเป็นพิเศษก่อนสมรส ความสัมพันธ์ระหว่างคู่สมรสในเรื่องทรัพย์สินนั้น ให้บังคับตามบทบัญญัติในหมวดนี้ ถ้าข้อความใดในสัญญาก่อนสมรสขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน หรือระบุให้ใช้กฎหมายประเทศอื่นบังคับเรื่องทรัพย์สินนั้น ข้อความนั้น ๆ เป็นโมฆะ"}},{"id":"TH-H004-A1466","no":1466,"noLabel":{"th":"มาตรา 1466"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๖๖ สัญญาก่อนสมรสเป็นโมฆะ ถ้ามิได้จดแจ้งข้อตกลงกันเป็นสัญญาก่อนสมรสนั้นไว้ในทะเบียนสมรสพร้อมกับการจดทะเบียนสมรส หรือมิได้ทำเป็นหนังสือลงลายมือชื่อคู่สมรสและพยานอย่างน้อยสองคนแนบไว้ท้ายทะเบียนสมรส และได้จดไว้ในทะเบียนสมรสพร้อมกับการจดทะเบียนสมรสว่าได้มีสัญญานั้นแนบไว้"}},{"id":"TH-H004-A1467","no":1467,"noLabel":{"th":"มาตรา 1467"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๖๗ เมื่อสมรสแล้วจะเปลี่ยนแปลงเพิกถอนสัญญาก่อนสมรสนั้นไม่ได้ นอกจากจะได้รับอนุญาตจากศาล เมื่อได้มีคำสั่งของศาลถึงที่สุดให้เปลี่ยนแปลงเพิกถอนสัญญาก่อนสมรสแล้ว ให้ศาลแจ้งไปยังนายทะเบียนสมรสเพื่อจดแจ้งไว้ในทะเบียนสมรส"}},{"id":"TH-H004-A1468","no":1468,"noLabel":{"th":"มาตรา 1468"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๖๘ ข้อความในสัญญาก่อนสมรสไม่มีผลกระทบกระเทือนถึงสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริตไม่ว่าจะได้เปลี่ยนแปลงเพิกถอนโดยคำสั่งของศาลหรือไม่ก็ตาม"}},{"id":"TH-H004-A1469","no":1469,"noLabel":{"th":"มาตรา 1469"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๖๙ สัญญาที่เกี่ยวกับทรัพย์สินใดที่คู่สมรสได้ทำไว้ต่อกันในระหว่างเป็นคู่สมรสกันนั้น ฝ่ายใดฝ่ายหนึ่งจะบอกล้างเสียในเวลาใดที่เป็นคู่สมรสกันอยู่หรือภายในกำหนดหนึ่งปีนับแต่วันที่ขาดจากการเป็นคู่สมรสกันก็ได้ แต่ไม่กระทบกระเทือนถึงสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริต"}},{"id":"TH-H004-A1470","no":1470,"noLabel":{"th":"มาตรา 1470"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๐ ทรัพย์สินระหว่างคู่สมรส นอกจากที่ได้แยกไว้เป็นสินส่วนตัวย่อมเป็นสินสมรส"}},{"id":"TH-H004-A1471","no":1471,"noLabel":{"th":"มาตรา 1471"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๑ สินส่วนตัวได้แก่ทรัพย์สิน (๑) ที่ฝ่ายใดฝ่ายหนึ่งมีอยู่ก่อนสมรส (๒) ที่เป็นเครื่องใช้สอยส่วนตัว เครื่องแต่งกาย หรือเครื่องประดับกายตามควรแก่ฐานะ หรือเครื่องมือเครื่องใช้ที่จำเป็นในการประกอบอาชีพหรือวิชาชีพของคู่สมรสฝ่ายใดฝ่ายหนึ่ง (๓) ที่ฝ่ายใดฝ่ายหนึ่งได้มาระหว่างสมรสโดยการรับมรดกหรือโดยการให้โดยเสน่หา (๔) ที่เป็นของหมั้น"}},{"id":"TH-H004-A1472","no":1472,"noLabel":{"th":"มาตรา 1472"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๒ สินส่วนตัวนั้น ถ้าได้แลกเปลี่ยนเป็นทรัพย์สินอื่นก็ดี ซื้อทรัพย์สินอื่นมาก็ดี หรือขายได้เป็นเงินมาก็ดี ทรัพย์สินอื่นหรือเงินที่ได้มานั้นเป็นสินส่วนตัว สินส่วนตัวที่ถูกทำลายไปทั้งหมดหรือแต่บางส่วน แต่ได้ทรัพย์สินอื่นหรือเงินมาทดแทน ทรัพย์สินอื่นหรือเงินที่ได้มานั้นเป็นสินส่วนตัว"}},{"id":"TH-H004-A1473","no":1473,"noLabel":{"th":"มาตรา 1473"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๓ สินส่วนตัวของคู่สมรสฝ่ายใดให้ฝ่ายนั้นเป็นผู้จัดการ"}},{"id":"TH-H004-A1474","no":1474,"noLabel":{"th":"มาตรา 1474"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๔ สินสมรสได้แก่ทรัพย์สิน (๑) ที่คู่สมรสได้มาระหว่างสมรส (๒) ที่ฝ่ายใดฝ่ายหนึ่งได้มาระหว่างสมรสโดยพินัยกรรมหรือโดยการให้เป็นหนังสือเมื่อพินัยกรรมหรือหนังสือยกให้ระบุว่าเป็นสินสมรส (๓) ที่เป็นดอกผลของสินส่วนตัว ถ้ากรณีเป็นที่สงสัยว่าทรัพย์สินอย่างหนึ่งเป็นสินสมรสหรือมิใช่ ให้สันนิษฐานไว้ก่อนว่าเป็นสินสมรส"}},{"id":"TH-H004-A1475","no":1475,"noLabel":{"th":"มาตรา 1475"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๕ ถ้าสินสมรสใดเป็นจำพวกที่ระบุไว้ในมาตรา ๔๕๖ แห่งประมวลกฎหมายนี้ หรือที่มีเอกสารเป็นสำคัญ คู่สมรสฝ่ายใดฝ่ายหนึ่งจะร้องขอให้ลงชื่อตนเป็นเจ้าของรวมกันในเอกสารนั้นก็ได้"}},{"id":"TH-H004-A1476","no":1476,"noLabel":{"th":"มาตรา 1476"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๖ คู่สมรสต้องจัดการสินสมรสร่วมกันหรือได้รับความยินยอมจากอีกฝ่ายหนึ่งในกรณี ดังต่อไปนี้ (๑) ขาย แลกเปลี่ยน ขายฝาก ให้เช่าซื้อ จำนอง ปลดจำนอง หรือโอนสิทธิจำนอง ซึ่งอสังหาริมทรัพย์หรือสังหาริมทรัพย์ที่อาจจำนองได้ (๒) ก่อตั้งหรือกระทำให้สุดสิ้นลงทั้งหมดหรือบางส่วนซึ่งภาระจำยอม สิทธิอาศัย สิทธิเหนือพื้นดิน สิทธิเก็บกิน หรือภาระติดพันในอสังหาริมทรัพย์ (๓) ให้เช่าอสังหาริมทรัพย์เกินสามปี (๔) ให้กู้ยืมเงิน (๕) ให้โดยเสน่หา เว้นแต่การให้ที่พอควรแก่ฐานานุรูปของครอบครัวเพื่อการกุศล เพื่อการสังคม หรือตามหน้าที่ธรรมจรรยา (๖) ประนีประนอมยอมความ (๗) มอบข้อพิพาทให้อนุญาโตตุลาการวินิจฉัย (๘) นำทรัพย์สินไปเป็นประกันหรือหลักประกันต่อเจ้าพนักงานหรือศาล การจัดการสินสมรสนอกจากกรณีที่บัญญัติไว้ในวรรคหนึ่ง คู่สมรสฝ่ายใดฝ่ายหนึ่งจัดการได้โดยมิต้องได้รับความยินยอมจากอีกฝ่ายหนึ่ง"}},{"id":"TH-H004-A1476.001","no":1476.001,"noLabel":{"th":"มาตรา 1476/1"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๖/๑ คู่สมรสจะจัดการสินสมรสให้แตกต่างไปจากที่บัญญัติไว้ในมาตรา ๑๔๗๖ ทั้งหมดหรือบางส่วนได้ก็ต่อเมื่อได้ทำสัญญาก่อนสมรสไว้ตามที่บัญญัติในมาตรา ๑๔๖๕ และมาตรา ๑๔๖๖ ในกรณีดังกล่าวนี้ การจัดการสินสมรสให้เป็นไปตามที่ระบุไว้ในสัญญาก่อนสมรส ในกรณีที่สัญญาก่อนสมรสระบุการจัดการสินสมรสไว้แต่เพียงบางส่วนของมาตรา ๑๔๗๖ การจัดการสินสมรสนอกจากที่ระบุไว้ในสัญญาก่อนสมรสให้เป็นไปตามมาตรา ๑๔๗๖"}},{"id":"TH-H004-A1477","no":1477,"noLabel":{"th":"มาตรา 1477"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๗ คู่สมรสฝ่ายใดฝ่ายหนึ่งมีสิทธิฟ้อง ต่อสู้ หรือดำเนินคดีเกี่ยวกับการสงวนบำรุงรักษาสินสมรส หรือเพื่อประโยชน์แก่สินสมรส หนี้อันเกิดแต่การฟ้อง ต่อสู้ หรือดำเนินคดีดังกล่าว ให้ถือว่าเป็นหนี้ที่คู่สมรสเป็นลูกหนี้ร่วมกัน"}},{"id":"TH-H004-A1478","no":1478,"noLabel":{"th":"มาตรา 1478"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๘ เมื่อฝ่ายใดต้องให้ความยินยอมหรือลงชื่อกับอีกฝ่ายหนึ่งในเรื่องจัดการทรัพย์สินแต่ไม่ให้ความยินยอมหรือไม่ยอมลงชื่อโดยปราศจากเหตุผล หรือไม่อยู่ในสภาพที่อาจให้ความยินยอมได้ อีกฝ่ายหนึ่งอาจร้องขอต่อศาลให้สั่งอนุญาตแทนได้"}},{"id":"TH-H004-A1479","no":1479,"noLabel":{"th":"มาตรา 1479"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๗๙ การใดที่คู่สมรสฝ่ายใดฝ่ายหนึ่งกระทำ ซึ่งต้องรับความยินยอมร่วมกัน และถ้าการนั้นมีกฎหมายบัญญัติให้ทำเป็นหนังสือหรือให้จดทะเบียนต่อพนักงานเจ้าหน้าที่ ความยินยอมนั้นต้องทำเป็นหนังสือ"}},{"id":"TH-H004-A1480","no":1480,"noLabel":{"th":"มาตรา 1480"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๐ การจัดการสินสมรสซึ่งต้องจัดการร่วมกันหรือต้องได้รับความยินยอมจากอีกฝ่ายหนึ่งตามมาตรา ๑๔๗๖ ถ้าคู่สมรสฝ่ายหนึ่งได้ทำนิติกรรมไปแต่เพียงฝ่ายเดียว หรือโดยปราศจากความยินยอมของคู่สมรสอีกฝ่ายหนึ่ง คู่สมรสอีกฝ่ายหนึ่งอาจฟ้องให้ศาลเพิกถอนนิติกรรมนั้นได้ เว้นแต่คู่สมรสอีกฝ่ายหนึ่งได้ให้สัตยาบันแก่นิติกรรมนั้นแล้ว หรือในขณะที่ทำนิติกรรมนั้นบุคคลภายนอกได้กระทำโดยสุจริตและเสียค่าตอบแทน การฟ้องให้ศาลเพิกถอนนิติกรรมตามวรรคหนึ่ง ห้ามมิให้ฟ้องเมื่อพ้นหนึ่งปี นับแต่วันที่ได้รู้เหตุอันเป็นมูลให้เพิกถอนหรือเมื่อพ้นสิบปีนับแต่วันที่ได้ทำนิติกรรมนั้น"}},{"id":"TH-H004-A1481","no":1481,"noLabel":{"th":"มาตรา 1481"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๑ คู่สมรสฝ่ายใดฝ่ายหนึ่งไม่มีอำนาจทำพินัยกรรมยกสินสมรสที่เกินกว่าส่วนของตนให้แก่บุคคลใดได้"}},{"id":"TH-H004-A1482","no":1482,"noLabel":{"th":"มาตรา 1482"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๒ ในกรณีที่คู่สมรสฝ่ายใดฝ่ายหนึ่งมีอำนาจจัดการสินสมรสแต่ฝ่ายเดียว คู่สมรสอีกฝ่ายหนึ่งก็ยังมีอำนาจจัดการบ้านเรือนและจัดหาสิ่งจำเป็นสำหรับครอบครัวตามสมควรแก่อัตภาพได้ ค่าใช้จ่ายในการนี้ย่อมผูกพันสินสมรสและสินส่วนตัวของทั้งสองฝ่าย ถ้าคู่สมรสฝ่ายใดฝ่ายหนึ่งจัดการบ้านเรือนหรือจัดหาสิ่งจำเป็นสำหรับครอบครัวเป็นที่เสียหายถึงขนาด อีกฝ่ายหนึ่งอาจร้องขอให้ศาลสั่งห้ามหรือจำกัดอำนาจนี้เสียได้"}},{"id":"TH-H004-A1483","no":1483,"noLabel":{"th":"มาตรา 1483"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๓ ในกรณีที่คู่สมรสฝ่ายใดฝ่ายหนึ่งมีอำนาจจัดการสินสมรสแต่ฝ่ายเดียว ถ้าคู่สมรสฝ่ายนั้นจะกระทำ หรือกำลังกระทำการอย่างใดอย่างหนึ่งในการจัดการสินสมรสอันพึงเห็นได้ว่าจะเกิดความเสียหายถึงขนาด อีกฝ่ายหนึ่งอาจร้องขอให้ศาลสั่งห้ามมิให้กระทำการนั้นได้"}},{"id":"TH-H004-A1484","no":1484,"noLabel":{"th":"มาตรา 1484"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๔ ถ้าคู่สมรสฝ่ายซึ่งมีอำนาจจัดการสินสมรส (๑) จัดการสินสมรสเป็นที่เสียหายถึงขนาด (๒) ไม่อุปการะเลี้ยงดูอีกฝ่ายหนึ่ง (๓) มีหนี้สินล้นพ้นตัวหรือทำหนี้เกินกึ่งหนึ่งของสินสมรส (๔) ขัดขวางการจัดการสินสมรสของอีกฝ่ายหนึ่งโดยไม่มีเหตุผลอันสมควร (๕) มีพฤติการณ์ปรากฏว่าจะทำความหายนะให้แก่สินสมรส อีกฝ่ายหนึ่งอาจร้องขอให้ศาลสั่งอนุญาตให้ตนเป็นผู้จัดการสินสมรสแต่ผู้เดียวหรือสั่งให้แยกสินสมรสได้ ในกรณีตามวรรคหนึ่ง ถ้ามีคำขอ ศาลอาจกำหนดวิธีคุ้มครองชั่วคราวเพื่อจัดการสินสมรสได้ตามที่เห็นสมควร และหากเป็นกรณีฉุกเฉินให้นำบทบัญญัติเรื่องคำขอในเหตุฉุกเฉินตามประมวลกฎหมายวิธีพิจารณาความแพ่งมาใช้บังคับ"}},{"id":"TH-H004-A1484.001","no":1484.001,"noLabel":{"th":"มาตรา 1484/1"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๔/๑ ในกรณีที่ศาลได้มีคำสั่งห้ามหรือจำกัดอำนาจในการจัดการสินสมรสของคู่สมรสฝ่ายใดฝ่ายหนึ่งตามมาตรา ๑๔๘๒ มาตรา ๑๔๘๓ หรือมาตรา ๑๔๘๔ ถ้าต่อมาเหตุแห่งการนั้นหรือพฤติการณ์ได้เปลี่ยนแปลงไป คู่สมรสฝ่ายใดฝ่ายหนึ่งอาจร้องขอต่อศาลให้ยกเลิกหรือเปลี่ยนแปลงคำสั่งที่ห้ามหรือจำกัดอำนาจจัดการสินสมรสนั้นได้ ในการนี้ศาลจะมีคำสั่งใด ๆ ตามที่เห็นสมควรก็ได้"}},{"id":"TH-H004-A1485","no":1485,"noLabel":{"th":"มาตรา 1485"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๕ คู่สมรสฝ่ายใดฝ่ายหนึ่งอาจร้องขอต่อศาลให้ตนเป็นผู้จัดการสินสมรสโดยเฉพาะอย่างใดอย่างหนึ่งหรือเข้าร่วมจัดการในการนั้นได้ ถ้าการที่จะทำเช่นนั้นจะเป็นประโยชน์ยิ่งกว่า"}},{"id":"TH-H004-A1486","no":1486,"noLabel":{"th":"มาตรา 1486"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๖ เมื่อศาลได้มีคำพิพากษาหรือคำสั่งถึงที่สุดตามความในมาตรา ๑๔๘๒ วรรคสอง มาตรา ๑๔๘๓ มาตรา ๑๔๘๔ มาตรา ๑๔๘๔/๑ หรือมาตรา ๑๔๘๕ อันเป็นคุณแก่ผู้ร้องขอ หรือตามมาตรา ๑๔๙๑ มาตรา ๑๔๙๒/๑ หรือมาตรา ๑๕๙๘/๑๗ หรือเมื่อคู่สมรสฝ่ายใดฝ่ายหนึ่งพ้นจากการเป็นบุคคลล้มละลาย ให้ศาลแจ้งไปยังนายทะเบียนเพื่อจดแจ้งไว้ในทะเบียนสมรส"}},{"id":"TH-H004-A1487","no":1487,"noLabel":{"th":"มาตรา 1487"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๗ ในระหว่างที่เป็นคู่สมรสกัน ฝ่ายใดจะยึดหรืออายัดทรัพย์สินของอีกฝ่ายหนึ่งไม่ได้ เว้นแต่เป็นการยึดหรืออายัดทรัพย์สินในคดีที่ฟ้องร้องเพื่อการปฏิบัติหน้าที่หรือรักษาสิทธิระหว่างคู่สมรสตามที่บัญญัติไว้โดยเฉพาะในประมวลกฎหมายนี้ หรือที่ประมวลกฎหมายนี้บัญญัติไว้โดยเฉพาะให้คู่สมรสฟ้องร้องกันเองได้ หรือเป็นการยึดหรืออายัดทรัพย์สินสำหรับค่าอุปการะเลี้ยงดูและค่าฤชาธรรมเนียมที่ยังมิได้ชำระตามคำพิพากษาของศาล"}},{"id":"TH-H004-A1488","no":1488,"noLabel":{"th":"มาตรา 1488"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๘ ถ้าคู่สมรสฝ่ายใดฝ่ายหนึ่งต้องรับผิดเป็นส่วนตัวเพื่อชำระหนี้ที่ก่อไว้ก่อนหรือระหว่างสมรส ให้ชำระหนี้นั้นด้วยสินส่วนตัวของฝ่ายนั้นก่อน เมื่อไม่พอจึงให้ชำระด้วยสินสมรสที่เป็นส่วนของฝ่ายนั้น"}},{"id":"TH-H004-A1489","no":1489,"noLabel":{"th":"มาตรา 1489"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๘๙ ถ้าคู่สมรสเป็นลูกหนี้ร่วมกัน ให้ชำระหนี้นั้นจากสินสมรสและสินส่วนตัวของทั้งสองฝ่าย"}},{"id":"TH-H004-A1490","no":1490,"noLabel":{"th":"มาตรา 1490"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๙๐ หนี้ที่คู่สมรสเป็นลูกหนี้ร่วมกันนั้นให้รวมถึงหนี้ที่คู่สมรสฝ่ายใดฝ่ายหนึ่งก่อให้เกิดขึ้นในระหว่างสมรส ดังต่อไปนี้ (๑) หนี้เกี่ยวแก่การจัดการบ้านเรือนและจัดหาสิ่งจำเป็นสำหรับครอบครัว การอุปการะเลี้ยงดู ตลอดถึงการรักษาพยาบาลบุคคลในครอบครัวและการศึกษาของบุตรตามสมควรแก่อัตภาพ (๒) หนี้ที่เกี่ยวข้องกับสินสมรส (๓) หนี้ที่เกิดขึ้นเนื่องจากการงานซึ่งคู่สมรสทำด้วยกัน (๔) หนี้ที่คู่สมรสฝ่ายใดฝ่ายหนึ่งก่อขึ้นเพื่อประโยชน์ตนฝ่ายเดียว แต่อีกฝ่ายหนึ่งได้ให้สัตยาบัน"}},{"id":"TH-H004-A1491","no":1491,"noLabel":{"th":"มาตรา 1491"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๙๑ ถ้าคู่สมรสฝ่ายใดฝ่ายหนึ่งต้องคำพิพากษาให้ล้มละลาย สินสมรสย่อมแยกจากกันโดยอำนาจกฎหมายนับแต่วันที่ศาลพิพากษาให้ล้มละลายนั้น"}},{"id":"TH-H004-A1492","no":1492,"noLabel":{"th":"มาตรา 1492"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๙๒ เมื่อได้แยกสินสมรสตามมาตรา ๑๔๘๔ วรรคสอง มาตรา ๑๔๙๑ หรือมาตรา ๑๕๙๘/๑๗ วรรคสองแล้ว ให้ส่วนที่แยกออกตกเป็นสินส่วนตัวของคู่สมรสฝ่ายใดฝ่ายหนึ่ง และบรรดาทรัพย์สินที่ฝ่ายใดได้มาในภายหลังไม่ให้ถือเป็นสินสมรส แต่ให้เป็นสินส่วนตัวของฝ่ายนั้น และสินสมรสที่คู่สมรสได้มาโดยพินัยกรรมหรือโดยการให้เป็นหนังสือตามมาตรา ๑๔๗๔ (๒) ในภายหลัง ให้ตกเป็นสินส่วนตัวของคู่สมรสฝ่ายละครึ่ง ดอกผลของสินส่วนตัวที่ได้มาหลังจากที่ได้แยกสินสมรสแล้วให้เป็นสินส่วนตัว"}},{"id":"TH-H004-A1492.001","no":1492.001,"noLabel":{"th":"มาตรา 1492/1"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๙๒/๑ ในกรณีที่มีการแยกสินสมรสโดยคำสั่งศาล การยกเลิกการแยกสินสมรสให้กระทำได้เมื่อคู่สมรสฝ่ายใดฝ่ายหนึ่งร้องขอต่อศาล และศาลได้มีคำสั่งให้ยกเลิก แต่ถ้าคู่สมรสอีกฝ่ายคัดค้าน ศาลจะสั่งยกเลิกการแยกสินสมรสได้ต่อเมื่อเหตุแห่งการแยกสินสมรสได้สิ้นสุดลงแล้ว เมื่อมีการยกเลิกการแยกสินสมรสตามวรรคหนึ่ง หรือการแยกสินสมรสสิ้นสุดลงเพราะคู่สมรสฝ่ายใดฝ่ายหนึ่งพ้นจากการเป็นบุคคลล้มละลาย ให้ทรัพย์สินที่เป็นสินส่วนตัวอยู่ในวันที่ศาลมีคำสั่งหรือในวันที่พ้นจากการเป็นบุคคลล้มละลาย ยังคงเป็นสินส่วนตัวต่อไปตามเดิม"}},{"id":"TH-H004-A1493","no":1493,"noLabel":{"th":"มาตรา 1493"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๔๙๓ ในกรณีที่ไม่มีสินสมรสแล้ว คู่สมรสต้องช่วยกันออกค่าใช้สอยสำหรับการบ้านเรือนตามส่วนมากและน้อยแห่งสินส่วนตัวของตน"}},{"id":"TH-H004-A1494","no":1494,"noLabel":{"th":"มาตรา 1494"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๔ การสมรสจะเป็นโมฆะก็แต่เฉพาะที่บัญญัติไว้ในหมวดนี้"}},{"id":"TH-H004-A1495","no":1495,"noLabel":{"th":"มาตรา 1495"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๕ การสมรสที่ฝ่าฝืนมาตรา ๑๔๔๙ มาตรา ๑๔๕๐ มาตรา ๑๔๕๒ และมาตรา ๑๔๕๘ เป็นโมฆะ"}},{"id":"TH-H004-A1496","no":1496,"noLabel":{"th":"มาตรา 1496"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๖ คำพิพากษาของศาลเท่านั้นที่จะแสดงว่า การสมรสที่ฝ่าฝืนมาตรา ๑๔๔๙ มาตรา ๑๔๕๐ และมาตรา ๑๔๕๘ เป็นโมฆะ คู่สมรส บิดามารดา หรือผู้สืบสันดานของคู่สมรสอาจร้องขอให้ศาลพิพากษาว่าการสมรสเป็นโมฆะได้ ถ้าไม่มีบุคคลดังกล่าว ผู้มีส่วนได้เสียจะร้องขอให้อัยการเป็นผู้ร้องขอต่อศาลก็ได้"}},{"id":"TH-H004-A1497","no":1497,"noLabel":{"th":"มาตรา 1497"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๗ การสมรสที่เป็นโมฆะ เพราะฝ่าฝืนมาตรา ๑๔๕๒ บุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งจะกล่าวอ้างขึ้น หรือจะร้องขอให้ศาลพิพากษาว่าการสมรสเป็นโมฆะก็ได้"}},{"id":"TH-H004-A1497.001","no":1497.001,"noLabel":{"th":"มาตรา 1497/1"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๗/๑ ในกรณีที่ศาลมีคำพิพากษาถึงที่สุดว่าการสมรสใดเป็นโมฆะให้ศาลแจ้งไปยังนายทะเบียนเพื่อบันทึกความเป็นโมฆะไว้ในทะเบียนสมรส"}},{"id":"TH-H004-A1498","no":1498,"noLabel":{"th":"มาตรา 1498"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๘ การสมรสที่เป็นโมฆะ ไม่ก่อให้เกิดความสัมพันธ์ทางทรัพย์สินระหว่างคู่สมรส ในกรณีที่การสมรสเป็นโมฆะ ทรัพย์สินที่ฝ่ายใดมีหรือได้มาไม่ว่าก่อนหรือหลังการสมรสรวมทั้งดอกผลคงเป็นของฝ่ายนั้น ส่วนบรรดาทรัพย์สินที่ทำมาหาได้ร่วมกันให้แบ่งคนละครึ่ง เว้นแต่ศาลจะเห็นสมควรสั่งเป็นประการอื่น เมื่อได้พิเคราะห์ถึงภาระในครอบครัว ภาระในการหาเลี้ยงชีพ และฐานะของคู่กรณีทั้งสองฝ่าย ตลอดจนพฤติการณ์อื่นทั้งปวงแล้ว"}},{"id":"TH-H004-A1499","no":1499,"noLabel":{"th":"มาตรา 1499"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๙ การสมรสที่เป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๔๙ มาตรา ๑๔๕๐ หรือมาตรา ๑๔๕๘ ไม่ทำให้ผู้สมรสโดยสุจริตเสื่อมสิทธิที่ได้มาเพราะการสมรสก่อนมีคำพิพากษาถึงที่สุดให้เป็นโมฆะ การสมรสที่เป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๕๒ ไม่ทำให้ผู้สมรสโดยสุจริตเสื่อมสิทธิที่ได้มาเพราะการสมรสก่อนที่บุคคลใดบุคคลหนึ่งนั้นรู้ถึงเหตุที่ทำให้การสมรสเป็นโมฆะ แต่การสมรสที่เป็นโมฆะดังกล่าว ไม่ทำให้คู่สมรสเกิดสิทธิรับมรดกในฐานะทายาทโดยธรรมของคู่สมรสอีกฝ่ายหนึ่ง การสมรสที่เป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๔๙ มาตรา ๑๔๕๐ หรือมาตรา ๑๔๕๘ หรือฝ่าฝืนมาตรา ๑๔๕๒ ถ้าคู่สมรสฝ่ายใดได้สมรสโดยสุจริตฝ่ายนั้นมีสิทธิเรียกค่าทดแทนได้ และถ้าการสมรสที่เป็นโมฆะนั้นทำให้ฝ่ายที่ได้สมรสโดยสุจริตต้องยากจนลงเพราะไม่มีรายได้พอจากทรัพย์สิน หรือจากการงานที่เคยทำอยู่ก่อนมีคำพิพากษาถึงที่สุด หรือก่อนที่จะได้รู้ว่าการสมรสของตนเป็นโมฆะ แล้วแต่กรณี ฝ่ายนั้นมีสิทธิเรียกค่าเลี้ยงชีพได้ด้วย สิทธิเรียกค่าเลี้ยงชีพในกรณีนี้ให้นำมาตรา ๑๕๒๖ วรรคหนึ่ง และมาตรา ๑๕๒๘ มาใช้บังคับโดยอนุโลม สิทธิเรียกร้องค่าทดแทน หรือค่าเลี้ยงชีพตามวรรคสาม มีกำหนดอายุความสองปีนับแต่วันที่มีคำพิพากษาถึงที่สุด สำหรับกรณีการสมรสเป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๔๙ มาตรา ๑๔๕๐ หรือมาตรา ๑๔๕๘ หรือนับแต่วันที่รู้ถึงเหตุที่ทำให้การสมรสเป็นโมฆะสำหรับกรณีการสมรสเป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๕๒"}},{"id":"TH-H004-A1499.001","no":1499.001,"noLabel":{"th":"มาตรา 1499/1"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๔๙๙/๑ ในกรณีที่การสมรสเป็นโมฆะข้อตกลงระหว่างคู่สมรสว่าฝ่ายใดจะเป็นผู้ใช้อำนาจปกครองบุตรคนใดหรือฝ่ายใดหรือทั้งสองฝ่ายจะเป็นผู้ออกเงินค่าอุปการะเลี้ยงดูบุตรเป็นจำนวนเท่าใด ให้ทำเป็นหนังสือ หากตกลงกันไม่ได้ให้ศาลเป็นผู้ชี้ขาด ในการพิจารณาชี้ขาดถ้าศาลเห็นว่ามีเหตุที่จะถอนอำนาจปกครองของคู่สมรสนั้นได้ตามมาตรา ๑๕๘๒ ศาลจะถอนอำนาจปกครองของคู่สมรส และสั่งให้บุคคลภายนอกเป็นผู้ปกครองก็ได้ ทั้งนี้ ให้ศาลคำนึงถึงความผาสุกและประโยชน์ของบุตรนั้นเป็นสำคัญ และให้นำความในมาตรา ๑๕๒๑ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1500","no":1500,"noLabel":{"th":"มาตรา 1500"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๕๐๐ การสมรสที่เป็นโมฆะไม่กระทบถึงสิทธิของบุคคลภายนอกผู้กระทำการโดยสุจริตซึ่งได้มาก่อนมีการบันทึกความเป็นโมฆะไว้ในทะเบียนสมรสตามมาตรา ๑๔๙๗/๑"}},{"id":"TH-H004-A1501","no":1501,"noLabel":{"th":"มาตรา 1501"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๑ การสมรสย่อมสิ้นสุดลงด้วยความตาย การหย่าหรือศาลพิพากษาให้เพิกถอน"}},{"id":"TH-H004-A1502","no":1502,"noLabel":{"th":"มาตรา 1502"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๒ การสมรสที่เป็นโมฆียะสิ้นสุดลงเมื่อศาลพิพากษาให้เพิกถอน"}},{"id":"TH-H004-A1503","no":1503,"noLabel":{"th":"มาตรา 1503"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๓ เหตุที่จะขอให้ศาลพิพากษาเพิกถอนการสมรส เพราะเหตุว่าเป็นโมฆียะ มีเฉพาะในกรณีที่คู่สมรสทำการฝ่าฝืนมาตรา ๑๔๔๘ มาตรา ๑๕๐๕ มาตรา ๑๕๐๖ มาตรา ๑๕๐๗ และมาตรา ๑๕๐๙"}},{"id":"TH-H004-A1504","no":1504,"noLabel":{"th":"มาตรา 1504"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๔ การสมรสที่เป็นโมฆียะเพราะฝ่าฝืนมาตรา ๑๔๔๘ ผู้มีส่วนได้เสียขอให้เพิกถอนการสมรสได้ แต่บิดามารดาหรือผู้ปกครองที่ให้ความยินยอมแล้วจะขอให้เพิกถอนการสมรสไม่ได้ ถ้าศาลมิได้สั่งให้เพิกถอนการสมรสจนบุคคลทั้งสองมีอายุครบตามมาตรา ๑๔๔๘ หรือในกรณีการสมรสระหว่างชายหญิง เมื่อหญิงมีครรภ์ก่อนอายุครบตามมาตรา ๑๔๔๘ ให้ถือว่าการสมรสสมบูรณ์มาตั้งแต่เวลาสมรส"}},{"id":"TH-H004-A1505","no":1505,"noLabel":{"th":"มาตรา 1505"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๕ การสมรสที่ได้กระทำไปโดยคู่สมรสฝ่ายหนึ่งสำคัญผิดตัวคู่สมรส การสมรสนั้นเป็นโมฆียะ สิทธิขอเพิกถอนการสมรสเพราะสำคัญผิดตัวคู่สมรสเป็นอันระงับเมื่อเวลาได้ผ่านพ้นไปแล้วเก้าสิบวันนับแต่วันสมรส"}},{"id":"TH-H004-A1506","no":1506,"noLabel":{"th":"มาตรา 1506"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๖ ถ้าคู่สมรสได้ทำการสมรสโดยถูกกลฉ้อฉลอันถึงขนาดซึ่งถ้ามิได้มีกลฉ้อฉลนั้นจะไม่ทำการสมรส การสมรสนั้นเป็นโมฆียะ ความในวรรคหนึ่ง ไม่ใช้บังคับในกรณีที่กลฉ้อฉลนั้นเกิดขึ้นโดยบุคคลที่สามโดยคู่สมรสอีกฝ่ายหนึ่งมิได้รู้เห็นด้วย สิทธิขอเพิกถอนการสมรสเพราะถูกกลฉ้อฉลเป็นอันระงับเมื่อเวลาได้ผ่านพ้นไปแล้วเก้าสิบวันนับแต่วันที่รู้หรือควรได้รู้ถึงกลฉ้อฉล หรือเมื่อเวลาได้ผ่านพ้นไปแล้วหนึ่งปี นับแต่วันสมรส"}},{"id":"TH-H004-A1507","no":1507,"noLabel":{"th":"มาตรา 1507"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๗ ถ้าคู่สมรสได้ทำการสมรสโดยถูกข่มขู่อันถึงขนาดซึ่งถ้ามิได้มีการข่มขู่นั้นจะไม่ทำการสมรส การสมรสนั้นเป็นโมฆียะ สิทธิขอเพิกถอนการสมรสเพราะถูกข่มขู่เป็นอันระงับ เมื่อเวลาได้ผ่านพ้นไปแล้วหนึ่งปีนับแต่วันที่พ้นจากการข่มขู่"}},{"id":"TH-H004-A1508","no":1508,"noLabel":{"th":"มาตรา 1508"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๘ การสมรสที่เป็นโมฆียะเพราะคู่สมรสสำคัญผิดตัวหรือถูกกลฉ้อฉลหรือถูกข่มขู่ เฉพาะแต่คู่สมรสที่สำคัญผิดตัวหรือถูกกลฉ้อฉล หรือถูกข่มขู่เท่านั้นขอเพิกถอนการสมรสได้ ในกรณีที่ผู้มีสิทธิขอเพิกถอนการสมรสเป็นบุคคลที่ถูกศาลสั่งให้เป็นคนไร้ความสามารถ ให้บุคคลซึ่งอาจร้องขอต่อศาลให้สั่งให้บุคคลวิกลจริตเป็นคนไร้ความสามารถตามมาตรา ๒๘ ขอเพิกถอนการสมรสได้ด้วย แต่ถ้าผู้มีสิทธิขอเพิกถอนการสมรสเป็นคนวิกลจริตที่ศาลยังไม่ได้สั่งให้เป็นคนไร้ความสามารถ บุคคลดังกล่าวจะร้องขอเพิกถอนการสมรสก็ได้ แต่ต้องขอให้ศาลสั่งให้คนวิกลจริตเป็นคนไร้ความสามารถพร้อมกันด้วย ในกรณีที่ศาลมีคำสั่งให้ยกคำขอให้ศาลสั่งเป็นคนไร้ความสามารถ ก็ให้ศาลมีคำสั่งยกคำขอเพิกถอนการสมรสของบุคคลดังกล่าวนั้นเสียด้วย คำสั่งศาลให้ยกคำขอเพิกถอนการสมรสของบุคคลตามวรรคสองไม่กระทบกระเทือนสิทธิการขอเพิกถอนการสมรสของคู่สมรส แต่คู่สมรสจะต้องใช้สิทธินั้นภายในกำหนดระยะเวลาที่คู่สมรสมีอยู่ ถ้าระยะเวลาดังกล่าวเหลืออยู่ไม่ถึงหกเดือนนับแต่วันที่ศาลมีคำสั่งให้ยกคำขอเพิกถอนการสมรสของบุคคลดังกล่าวหรือไม่มีเหลืออยู่เลย ก็ให้ขยายระยะเวลานั้นออกไปได้ให้ครบหกเดือนหรืออีกหกเดือนนับแต่วันที่ศาลมีคำสั่งให้ยกคำขอเพิกถอนการสมรสของบุคคลดังกล่าว แล้วแต่กรณี"}},{"id":"TH-H004-A1509","no":1509,"noLabel":{"th":"มาตรา 1509"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๐๙ การสมรสที่มิได้รับความยินยอมของบุคคลดังกล่าวในมาตรา ๑๔๕๔ การสมรสนั้นเป็นโมฆียะ"}},{"id":"TH-H004-A1510","no":1510,"noLabel":{"th":"มาตรา 1510"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๐ การสมรสที่เป็นโมฆียะเพราะมิได้รับความยินยอมของบุคคลดังกล่าวในมาตรา ๑๔๕๔ เฉพาะบุคคลที่อาจให้ความยินยอมตามมาตรา ๑๔๕๔ เท่านั้น ขอให้เพิกถอนการสมรสได้ สิทธิขอเพิกถอนการสมรสตามมาตรานี้เป็นอันระงับเมื่อคู่สมรสนั้นมีอายุครบยี่สิบปีบริบูรณ์หรือในกรณีการสมรสระหว่างชายหญิง เมื่อหญิงมีครรภ์ การฟ้องขอเพิกถอนการสมรสตามมาตรานี้ให้มีอายุความหนึ่งปีนับแต่วันทราบการสมรส"}},{"id":"TH-H004-A1511","no":1511,"noLabel":{"th":"มาตรา 1511"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๑ การสมรสที่ได้มีคำพิพากษาให้เพิกถอนนั้น ให้ถือว่าสิ้นสุดลงในวันที่คำพิพากษาถึงที่สุด แต่จะอ้างเป็นเหตุเสื่อมสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริตไม่ได้ เว้นแต่จะได้จดทะเบียนการเพิกถอนการสมรสนั้นแล้ว"}},{"id":"TH-H004-A1512","no":1512,"noLabel":{"th":"มาตรา 1512"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๒ ให้นำบทบัญญัติว่าด้วยผลของการหย่าโดยคำพิพากษามาใช้บังคับแก่ผลของการเพิกถอนการสมรสโดยอนุโลม"}},{"id":"TH-H004-A1513","no":1513,"noLabel":{"th":"มาตรา 1513"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๓ ถ้าปรากฏว่าคู่สมรสที่ถูกฟ้องเพิกถอนการสมรสได้รู้เห็นเป็นใจในเหตุแห่งโมฆียะกรรม คู่สมรสนั้นจะต้องรับผิดใช้ค่าทดแทนความเสียหายซึ่งคู่สมรสอีกฝ่ายหนึ่งได้รับต่อกาย ชื่อเสียงหรือทรัพย์สิน เนื่องจากการสมรสนั้น และให้นำมาตรา ๑๕๒๕ มาใช้บังคับโดยอนุโลม ถ้าหากการเพิกถอนการสมรสตามวรรคหนึ่งทำให้อีกฝ่ายหนึ่งยากจนลง และไม่มีรายได้พอจากทรัพย์สินหรือจากการงานตามที่เคยทำอยู่ระหว่างสมรส คู่สมรสที่ถูกฟ้องนั้นจะต้องรับผิดในค่าเลี้ยงชีพดังที่บัญญัติไว้ในมาตรา ๑๕๒๖ ด้วย"}},{"id":"TH-H004-A1514","no":1514,"noLabel":{"th":"มาตรา 1514"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๔ การหย่านั้นจะทำได้แต่โดยความยินยอมของทั้งสองฝ่ายหรือโดยคำพิพากษาของศาล การหย่าโดยความยินยอมต้องทำเป็นหนังสือและมีพยานลงลายมือชื่ออย่างน้อยสองคน"}},{"id":"TH-H004-A1515","no":1515,"noLabel":{"th":"มาตรา 1515"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๕ เมื่อได้จดทะเบียนสมรสตามประมวลกฎหมายนี้ การหย่าโดยความยินยอมจะสมบูรณ์ต่อเมื่อคู่สมรสได้จดทะเบียนการหย่านั้นแล้ว"}},{"id":"TH-H004-A1516","no":1516,"noLabel":{"th":"มาตรา 1516"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๖ เหตุฟ้องหย่ามีดังต่อไปนี้ (๑) คู่สมรสฝ่ายใดฝ่ายหนึ่งอุปการะเลี้ยงดูหรือยกย่องผู้อื่นฉันคู่สมรส เป็นชู้หรือมีชู้ ร่วมประเวณีกับผู้อื่นเป็นอาจิณ หรือกระทำกับผู้อื่นหรือยอมรับการกระทำของผู้อื่นเพื่อสนองความใคร่ของตนหรือผู้อื่นเป็นอาจิณ อีกฝ่ายหนึ่งฟ้องหย่าได้ (๒) คู่สมรสฝ่ายใดฝ่ายหนึ่งประพฤติชั่ว ไม่ว่าความประพฤติชั่วนั้นจะเป็นความผิดอาญาหรือไม่ ถ้าเป็นเหตุให้อีกฝ่ายหนึ่ง (ก) ได้รับความอับอายขายหน้าอย่างร้ายแรง (ข) ได้รับความดูถูกเกลียดชังเพราะเหตุที่คงเป็นคู่สมรสของฝ่ายที่ประพฤติชั่วอยู่ต่อไป หรือ (ค) ได้รับความเสียหายหรือเดือดร้อนเกินควร ในเมื่อเอาสภาพ ฐานะและความเป็นอยู่ร่วมกันฉันคู่สมรสมาคำนึงประกอบ อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๓) คู่สมรสฝ่ายใดฝ่ายหนึ่งทำร้าย หรือทรมานร่างกายหรือจิตใจ หรือหมิ่นประมาทหรือเหยียดหยามอีกฝ่ายหนึ่งหรือบุพการีของอีกฝ่ายหนึ่ง ทั้งนี้ ถ้าเป็นการร้ายแรง อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๔) คู่สมรสฝ่ายใดฝ่ายหนึ่งจงใจละทิ้งร้างอีกฝ่ายหนึ่งไปเกินหนึ่งปี อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๔/๑) คู่สมรสฝ่ายใดฝ่ายหนึ่งต้องคำพิพากษาถึงที่สุดให้จำคุก และได้ถูกจำคุกเกินหนึ่งปีในความผิดที่อีกฝ่ายหนึ่งมิได้มีส่วนก่อให้เกิดการกระทำความผิดหรือยินยอมหรือรู้เห็นเป็นใจในการกระทำความผิดนั้นด้วย และการเป็นคู่สมรสกันต่อไปจะเป็นเหตุให้อีกฝ่ายหนึ่งได้รับความเสียหายหรือเดือดร้อนเกินควร อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๔/๒) คู่สมรสสมัครใจแยกกันอยู่เพราะเหตุที่ไม่อาจอยู่ร่วมกันฉันคู่สมรสได้โดยปกติสุขตลอดมาเกินสามปี หรือแยกกันอยู่ตามคำสั่งของศาลเป็นเวลาเกินสามปี ฝ่ายใดฝ่ายหนึ่งฟ้องหย่าได้ (๕) คู่สมรสฝ่ายใดฝ่ายหนึ่งถูกศาลสั่งให้เป็นคนสาบสูญ หรือไปจากภูมิลำเนาหรือถิ่นที่อยู่เป็นเวลาเกินสามปีโดยไม่มีใครทราบแน่ว่าเป็นตายร้ายดีอย่างไร อีกฝ่ายหนึ่งฟ้องหย่าได้ (๖) คู่สมรสฝ่ายใดฝ่ายหนึ่งไม่ให้ความช่วยเหลืออุปการะเลี้ยงดูอีกฝ่ายหนึ่งตามสมควร หรือทำการเป็นปฏิปักษ์ต่อการที่เป็นคู่สมรสอย่างร้ายแรง ทั้งนี้ ถ้าการกระทำนั้นถึงขนาดที่อีกฝ่ายหนึ่งเดือดร้อนเกินควรในเมื่อเอาสภาพ ฐานะและความเป็นอยู่ร่วมกันฉันคู่สมรสมาคำนึงประกอบ อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๗) คู่สมรสฝ่ายใดฝ่ายหนึ่งวิกลจริตตลอดมาเกินสามปี และความวิกลจริตนั้นมีลักษณะยากจะหายได้ กับทั้งความวิกลจริตถึงขนาดที่จะทนอยู่ร่วมกันฉันคู่สมรสต่อไปไม่ได้ อีกฝ่ายหนึ่งฟ้องหย่าได้ (๘) คู่สมรสฝ่ายใดฝ่ายหนึ่งผิดทัณฑ์บนที่ทำให้ไว้เป็นหนังสือในเรื่องความประพฤติ อีกฝ่ายหนึ่งฟ้องหย่าได้ (๙) คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นโรคติดต่ออย่างร้ายแรงอันอาจเป็นภัยแก่อีกฝ่ายหนึ่งและโรคมีลักษณะเรื้อรังไม่มีทางที่จะหายได้ อีกฝ่ายหนึ่งนั้นฟ้องหย่าได้ (๑๐) คู่สมรสฝ่ายใดฝ่ายหนึ่งมีสภาพแห่งกายทำให้ไม่อาจร่วมประเวณี หรือไม่อาจกระทำการหรือยอมรับการกระทำเพื่อสนองความใคร่ของอีกฝ่ายได้ตลอดกาล อีกฝ่ายหนึ่งฟ้องหย่าได้"}},{"id":"TH-H004-A1517","no":1517,"noLabel":{"th":"มาตรา 1517"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๗ เหตุฟ้องหย่าตามมาตรา ๑๕๑๖ (๑) และ (๒) ถ้าคู่สมรสฝ่ายใดฝ่ายหนึ่ง แล้วแต่กรณี ได้ยินยอมหรือรู้เห็นเป็นใจในการกระทำที่เป็นเหตุหย่านั้น ฝ่ายที่ยินยอมหรือรู้เห็นเป็นใจนั้นจะยกเป็นเหตุฟ้องหย่าไม่ได้ เหตุฟ้องหย่าตามมาตรา ๑๕๑๖ (๑๐) ถ้าเกิดเพราะการกระทำของอีกฝ่ายหนึ่ง อีกฝ่ายหนึ่งนั้นจะยกเป็นเหตุฟ้องหย่าไม่ได้ ในกรณีฟ้องหย่าโดยอาศัยเหตุแห่งการผิดทัณฑ์บนตามมาตรา ๑๕๑๖ (๘) นั้น ถ้าศาลเห็นว่าความประพฤติของคู่สมรสอันเป็นเหตุให้ทำทัณฑ์บนเป็นเหตุเล็กน้อยหรือไม่สำคัญเกี่ยวแก่การอยู่ร่วมกันฉันคู่สมรสโดยปกติสุข ศาลจะไม่พิพากษาให้หย่าก็ได้"}},{"id":"TH-H004-A1518","no":1518,"noLabel":{"th":"มาตรา 1518"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๘ สิทธิฟ้องหย่าย่อมหมดไปในเมื่อฝ่ายที่มีสิทธิฟ้องหย่าได้กระทำการอันแสดงให้เห็นว่าได้ให้อภัยในการกระทำของอีกฝ่ายหนึ่งซึ่งเป็นเหตุให้เกิดสิทธิฟ้องหย่านั้นแล้ว"}},{"id":"TH-H004-A1519","no":1519,"noLabel":{"th":"มาตรา 1519"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๑๙ ในกรณีที่คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นคนวิกลจริตและมีเหตุหย่าเกิดขึ้นไม่ว่าเหตุนั้นจะได้เกิดขึ้นก่อนหรือภายหลังการเป็นคนวิกลจริต ให้บุคคลซึ่งอาจร้องขอต่อศาลให้สั่งให้บุคคลวิกลจริตเป็นคนไร้ความสามารถตามมาตรา ๒๘ มีอำนาจฟ้องคู่สมรสอีกฝ่ายหนึ่งขอให้ศาลพิพากษาให้หย่าขาดจากกันและแบ่งทรัพย์สินได้ ในกรณีเช่นว่านี้ ถ้ายังมิได้มีคำสั่งของศาลแสดงว่าคู่สมรสซึ่งวิกลจริตเป็นคนไร้ความสามารถ ก็ให้บุคคลดังกล่าวร้องขอต่อศาลในคดีเดียวกันนั้นให้ศาลมีคำสั่งว่าคู่สมรสซึ่งวิกลจริตนั้นเป็นคนไร้ความสามารถ เมื่อบุคคลดังกล่าวเห็นสมควร จะร้องขอต่อศาลให้มีคำสั่งตามมาตรา ๑๕๒๖ หรือมาตรา ๑๕๓๐ ด้วยก็ได้ ในกรณีที่คู่สมรสซึ่งถูกอ้างว่าเป็นคนวิกลจริตยังไม่ได้ถูกสั่งให้เป็นคนไร้ความสามารถ หากศาลเห็นว่าคู่สมรสนั้นยังไม่เป็นคนที่ควรสั่งให้เป็นคนไร้ความสามารถก็ให้ยกฟ้องคดีนั้นเสีย ถ้าเห็นว่าเป็นบุคคลที่ควรสั่งให้เป็นคนไร้ความสามารถ แต่ยังไม่สมควรจะให้มีการหย่า ก็ให้ศาลสั่งให้คู่สมรสนั้นเป็นคนไร้ความสามารถโดยจะไม่สั่งเรื่องผู้อนุบาลหรือจะตั้งผู้อื่นเป็นผู้อนุบาลตามมาตรา ๑๔๖๓ ก็ได้ คงพิพากษายกแต่เฉพาะข้อหย่า ในกรณีเช่นนี้ศาลจะสั่งกำหนดค่าเลี้ยงชีพด้วยก็ได้ ในกรณีที่ศาลเห็นว่าคู่สมรสนั้นวิกลจริตอันควรสั่งให้เป็นคนไร้ความสามารถและทั้งมีเหตุควรให้หย่าด้วย ก็ให้ศาลสั่งในคำพิพากษาให้คู่สมรสนั้นเป็นคนไร้ความสามารถตั้งผู้อนุบาลและให้หย่า ในกรณีนี้ ถ้าศาลเห็นว่าเหตุหย่าที่ยกขึ้นอ้างในการฟ้องร้องนั้นไม่เหมาะสมแก่สภาพของคู่สมรสซึ่งเป็นคนไร้ความสามารถที่จะหย่าจากคู่สมรสอีกฝ่ายหนึ่งก็ดี ตามพฤติการณ์ไม่สมควรที่จะให้มีการหย่าขาดจากกันก็ดี ศาลจะพิพากษาไม่ให้หย่าก็ได้"}},{"id":"TH-H004-A1520","no":1520,"noLabel":{"th":"มาตรา 1520"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๐ ในกรณีหย่าโดยความยินยอม ให้คู่สมรสทำความตกลงเป็นหนังสือว่าฝ่ายใดจะเป็นผู้ใช้อำนาจปกครองบุตรคนใด ถ้ามิได้ตกลงกันหรือตกลงกันไม่ได้ ให้ศาลเป็นผู้ชี้ขาด ในกรณีหย่าโดยคำพิพากษาของศาล ให้ศาลซึ่งพิจารณาคดีฟ้องหย่านั้นชี้ขาดด้วยว่าฝ่ายใดจะเป็นผู้ใช้อำนาจปกครองบุตรคนใด ในการพิจารณาชี้ขาดถ้าศาลเห็นว่ามีเหตุที่จะถอนอำนาจปกครองของคู่สมรสนั้นได้ตามมาตรา ๑๕๘๒ ศาลจะถอนอำนาจปกครองของคู่สมรสและสั่งให้บุคคลภายนอกเป็นผู้ปกครองก็ได้ ทั้งนี้ ให้ศาลคำนึงถึงความผาสุกและประโยชน์ของบุตรนั้นเป็นสำคัญ"}},{"id":"TH-H004-A1521","no":1521,"noLabel":{"th":"มาตรา 1521"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๑ ถ้าปรากฏว่าผู้ใช้อำนาจปกครองหรือผู้ปกครองตามมาตรา ๑๕๒๐ ประพฤติตนไม่สมควร หรือภายหลังพฤติการณ์ได้เปลี่ยนแปลงไป ศาลมีอำนาจสั่งเปลี่ยนตัวผู้ใช้อำนาจปกครองหรือผู้ปกครองโดยคำนึงถึงความผาสุกและประโยชน์ของบุตรเป็นสำคัญ"}},{"id":"TH-H004-A1522","no":1522,"noLabel":{"th":"มาตรา 1522"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๒ ถ้าคู่สมรสหย่าโดยความยินยอม ให้ทำความตกลงกันไว้ในสัญญาหย่าว่าคู่สมรสทั้งสองฝ่าย หรือคู่สมรสฝ่ายใดฝ่ายหนึ่งจะออกเงินค่าอุปการะเลี้ยงดูบุตรเป็นจำนวนเงินเท่าใด ถ้าหย่าโดยคำพิพากษาของศาลหรือในกรณีที่สัญญาหย่ามิได้กำหนดเรื่องค่าอุปการะเลี้ยงดูบุตรไว้ ให้ศาลเป็นผู้กำหนด"}},{"id":"TH-H004-A1523","no":1523,"noLabel":{"th":"มาตรา 1523"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๓ เมื่อศาลพิพากษาให้หย่ากันเพราะเหตุตามมาตรา ๑๕๑๖ (๑) คู่สมรสฝ่ายใดฝ่ายหนึ่งมีสิทธิได้รับค่าทดแทนจากคู่สมรสอีกฝ่ายหนึ่งและจากผู้ซึ่งได้รับการอุปการะเลี้ยงดูหรือยกย่อง หรือผู้ซึ่งเป็นเหตุแห่งการหย่านั้น คู่สมรสฝ่ายใดฝ่ายหนึ่งจะเรียกค่าทดแทนจากผู้ซึ่งล่วงเกินคู่สมรสอีกฝ่ายหนึ่งไปในทำนองชู้ หรือจากผู้ซึ่งแสดงตนโดยเปิดเผยเพื่อแสดงว่าตนมีความสัมพันธ์กับคู่สมรสอีกฝ่ายหนึ่งในทำนองชู้ก็ได้ ถ้าคู่สมรสฝ่ายใดฝ่ายหนึ่งยินยอมหรือรู้เห็นเป็นใจให้อีกฝ่ายหนึ่งกระทำการตามมาตรา ๑๕๑๖ (๑) หรือให้ผู้อื่นกระทำการตามวรรคสอง คู่สมรสฝ่ายใดฝ่ายหนึ่งนั้นจะเรียกค่าทดแทนไม่ได้"}},{"id":"TH-H004-A1524","no":1524,"noLabel":{"th":"มาตรา 1524"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๔ ถ้าเหตุแห่งการหย่าตามมาตรา ๑๕๑๖ (๓) (๔) หรือ (๖) เกิดขึ้นเพราะฝ่ายผู้ต้องรับผิดชอบก่อให้เกิดขึ้นโดยมุ่งประสงค์ให้อีกฝ่ายหนึ่งไม่อาจทนได้ จึงต้องฟ้องหย่า อีกฝ่ายหนึ่งมีสิทธิได้รับค่าทดแทนจากฝ่ายที่ต้องรับผิด"}},{"id":"TH-H004-A1525","no":1525,"noLabel":{"th":"มาตรา 1525"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๕ ค่าทดแทนตามมาตรา ๑๕๒๓ และมาตรา ๑๕๒๔ นั้น ให้ศาลวินิจฉัยตามควรแก่พฤติการณ์ โดยศาลจะสั่งให้ชำระครั้งเดียวหรือแบ่งชำระเป็นงวด ๆ มีกำหนดเวลาตามที่ศาลจะเห็นสมควรก็ได้ ในกรณีที่ผู้จะต้องชำระค่าทดแทนเป็นคู่สมรสของอีกฝ่ายหนึ่ง ให้ศาลคำนึงถึงจำนวนทรัพย์สินที่คู่สมรสนั้นได้รับไปจากการแบ่งสินสมรสเพราะการหย่านั้นด้วย"}},{"id":"TH-H004-A1526","no":1526,"noLabel":{"th":"มาตรา 1526"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๖ ในคดีหย่า ถ้าเหตุแห่งการหย่าเป็นความผิดของคู่สมรสฝ่ายใดฝ่ายหนึ่งแต่ฝ่ายเดียว และการหย่านั้นจะทำให้อีกฝ่ายหนึ่งยากจนลง เพราะไม่มีรายได้พอจากทรัพย์สินหรือจากการงานตามที่เคยทำอยู่ระหว่างสมรส อีกฝ่ายหนึ่งนั้นจะขอให้ฝ่ายที่ต้องรับผิดจ่ายค่าเลี้ยงชีพให้ได้ ค่าเลี้ยงชีพนี้ศาลอาจให้เพียงใดหรือไม่ให้ก็ได้ โดยคำนึงถึงความสามารถของผู้ให้และฐานะของผู้รับและให้นำบทบัญญัติมาตรา ๑๕๙๘/๓๙ มาตรา ๑๕๙๘/๔๐ และมาตรา ๑๕๙๘/๔๑ มาใช้บังคับโดยอนุโลม สิทธิเรียกร้องค่าเลี้ยงชีพเป็นอันสิ้นสุด ถ้ามิได้ฟ้องหรือฟ้องแย้งในคดีหย่านั้น"}},{"id":"TH-H004-A1527","no":1527,"noLabel":{"th":"มาตรา 1527"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๗ ถ้าหย่าขาดจากกันเพราะเหตุวิกลจริตตามมาตรา ๑๕๑๖ (๗) หรือเพราะเหตุเป็นโรคติดต่ออย่างร้ายแรงตามมาตรา ๑๕๑๖ (๙) คู่สมรสอีกฝ่ายหนึ่งต้องออกค่าเลี้ยงชีพให้แก่ฝ่ายที่วิกลจริตหรือฝ่ายที่เป็นโรคติดต่อนั้นโดยคำนวณค่าเลี้ยงชีพอนุโลมตามมาตรา ๑๕๒๖"}},{"id":"TH-H004-A1528","no":1528,"noLabel":{"th":"มาตรา 1528"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๘ ถ้าฝ่ายที่รับค่าเลี้ยงชีพสมรสใหม่ สิทธิรับค่าเลี้ยงชีพย่อมหมดไป"}},{"id":"TH-H004-A1529","no":1529,"noLabel":{"th":"มาตรา 1529"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๒๙ สิทธิฟ้องร้องโดยอาศัยเหตุในมาตรา ๑๕๑๖ (๑) (๒) (๓) หรือ (๖) หรือมาตรา ๑๕๒๓ ย่อมระงับไปเมื่อพ้นกำหนดหนึ่งปีนับแต่วันผู้กล่าวอ้างรู้หรือควรรู้ความจริงซึ่งตนอาจยกขึ้นกล่าวอ้าง เหตุอันจะยกขึ้นฟ้องหย่าไม่ได้แล้วนั้น อาจนำสืบสนับสนุนคดีฟ้องหย่าซึ่งอาศัยเหตุอย่างอื่น"}},{"id":"TH-H004-A1530","no":1530,"noLabel":{"th":"มาตรา 1530"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๐ ขณะคดีฟ้องหย่าอยู่ในระหว่างพิจารณา ถ้าฝ่ายใดร้องขอศาลอาจสั่งชั่วคราวให้จัดการตามที่เห็นสมควร เช่น ในเรื่องสินสมรส ที่พักอาศัย การอุปการะเลี้ยงดูคู่สมรสและการพิทักษ์อุปการะเลี้ยงดูบุตร"}},{"id":"TH-H004-A1531","no":1531,"noLabel":{"th":"มาตรา 1531"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๑ การสมรสที่จดทะเบียนตามกฎหมายนั้น การหย่าโดยความยินยอมของคู่สมรสทั้งสองฝ่ายมีผลนับแต่เวลาจดทะเบียนการหย่าเป็นต้นไป การหย่าโดยคำพิพากษามีผลแต่เวลาที่คำพิพากษาถึงที่สุด แต่จะอ้างเป็นเหตุเสื่อมสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริตไม่ได้ เว้นแต่จะได้จดทะเบียนการหย่านั้นแล้ว"}},{"id":"TH-H004-A1532","no":1532,"noLabel":{"th":"มาตรา 1532"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๒ เมื่อหย่ากันแล้วให้จัดการแบ่งทรัพย์สินของคู่สมรส แต่ในระหว่างคู่สมรส (ก) ถ้าเป็นการหย่าโดยความยินยอมของทั้งสองฝ่าย ให้จัดการแบ่งทรัพย์สินของคู่สมรสตามที่มีอยู่ในเวลาจดทะเบียนการหย่า (ข) ถ้าเป็นการหย่าโดยคำพิพากษาของศาล คำพิพากษาส่วนที่บังคับทรัพย์สินระหว่างคู่สมรสนั้น มีผลย้อนหลังไปถึงวันฟ้องหย่า"}},{"id":"TH-H004-A1533","no":1533,"noLabel":{"th":"มาตรา 1533"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๓ เมื่อหย่ากันให้แบ่งสินสมรสให้คู่สมรสแต่ละฝ่ายได้ส่วนเท่ากัน"}},{"id":"TH-H004-A1534","no":1534,"noLabel":{"th":"มาตรา 1534"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๔ สินสมรสที่คู่สมรสฝ่ายใดฝ่ายหนึ่งจำหน่ายไปเพื่อประโยชน์ตนฝ่ายเดียวก็ดี จำหน่ายไปโดยเจตนาทำให้คู่สมรสอีกฝ่ายหนึ่งเสียหายก็ดี จำหน่ายไปโดยมิได้รับความยินยอมของคู่สมรสอีกฝ่ายหนึ่งในกรณีที่กฎหมายบังคับว่าการจำหน่ายนั้นจะต้องได้รับความยินยอมของอีกฝ่ายหนึ่งด้วยก็ดี จงใจทำลายให้สูญหายไปก็ดี ให้ถือเสมือนว่าทรัพย์สินนั้นยังคงมีอยู่เพื่อจัดแบ่งสินสมรสตามมาตรา ๑๕๓๓ และถ้าคู่สมรสอีกฝ่ายหนึ่งได้รับส่วนแบ่งสินสมรสไม่ครบตามจำนวนที่ควรจะได้ ให้คู่สมรสฝ่ายที่ได้จำหน่ายหรือจงใจทำลายสินสมรสนั้นชดใช้จากสินสมรสส่วนของตนหรือสินส่วนตัว"}},{"id":"TH-H004-A1535","no":1535,"noLabel":{"th":"มาตรา 1535"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๕๓๕ เมื่อการสมรสสิ้นสุดลง ให้แบ่งความรับผิดในหนี้ที่จะต้องรับผิดด้วยกันตามส่วนเท่ากัน"}},{"id":"TH-H004-A1536","no":1536,"noLabel":{"th":"มาตรา 1536"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๓๖ เด็กเกิดแต่หญิงขณะเป็นคู่สมรสกับชายหรือภายในสามร้อยสิบวันนับแต่วันที่การสมรสสิ้นสุดลง ให้สันนิษฐานไว้ก่อนว่าเป็นบุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรส หรือเคยเป็นคู่สมรส แล้วแต่กรณี ให้นำความในวรรคหนึ่งมาใช้บังคับแก่บุตรที่เกิดจากหญิงก่อนที่ได้มีคำพิพากษาถึงที่สุดของศาลแสดงว่าการสมรสเป็นโมฆะ หรือภายในระยะเวลาสามร้อยสิบวันนับแต่วันนั้น"}},{"id":"TH-H004-A1537","no":1537,"noLabel":{"th":"มาตรา 1537"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๓๗ ในกรณีที่หญิงทำการสมรสใหม่นั้นเป็นการฝ่าฝืนมาตรา ๑๔๕๓ และคลอดบุตรภายในสามร้อยสิบวันนับแต่วันที่การสมรสสิ้นสุดลง ให้สันนิษฐานไว้ก่อนว่าเด็กที่เกิดแต่หญิงนั้นเป็นบุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสคนใหม่ และห้ามมิให้นำข้อสันนิษฐานในมาตรา ๑๕๓๖ ที่ว่าเด็กเป็นบุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสเดิมมาใช้บังคับ ทั้งนี้ เว้นแต่มีคำพิพากษาของศาลแสดงว่าเด็กมิใช่บุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสคนใหม่นั้น"}},{"id":"TH-H004-A1538","no":1538,"noLabel":{"th":"มาตรา 1538"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๓๘ ในกรณีที่บุคคลสมรสฝ่าฝืนมาตรา ๑๔๕๒ เด็กที่เกิดในระหว่างการสมรสที่ฝ่าฝืนนั้น ให้สันนิษฐานไว้ก่อนว่าเป็นบุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสซึ่งได้จดทะเบียนสมรสครั้งหลัง ในกรณีที่หญิงสมรสฝ่าฝืนมาตรา ๑๔๕๒ ถ้ามีคำพิพากษาถึงที่สุดแสดงว่าเด็กมิใช่บุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสซึ่งได้จดทะเบียนสมรสครั้งหลัง ให้นำข้อสันนิษฐานในมาตรา ๑๕๓๖ มาใช้บังคับ ให้นำความในวรรคหนึ่งมาใช้บังคับแก่เด็กที่เกิดภายในสามร้อยสิบวันนับแต่วันที่ศาลมีคำพิพากษาถึงที่สุดให้การสมรสเป็นโมฆะเพราะฝ่าฝืนมาตรา ๑๔๕๒ ด้วย"}},{"id":"TH-H004-A1539","no":1539,"noLabel":{"th":"มาตรา 1539"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๓๙ ในกรณีที่สันนิษฐานว่าเด็กเป็นบุตรชอบด้วยกฎหมายของชายผู้เป็นหรือเคยเป็นคู่สมรสตามมาตรา ๑๕๓๖ มาตรา ๑๕๓๗ หรือมาตรา ๑๕๓๘ ชายผู้เป็นหรือเคยเป็นคู่สมรสจะไม่รับเด็กเป็นบุตรของตนก็ได้ โดยฟ้องเด็กกับมารดาเด็กร่วมกันเป็นจำเลยและพิสูจน์ได้ว่าตนไม่ได้อยู่ร่วมกับมารดาเด็กในระยะเวลาตั้งครรภ์คือระหว่างหนึ่งร้อยแปดสิบวันถึงสามร้อยสิบวันก่อนเด็กเกิด หรือตนไม่สามารถเป็นบิดาของเด็กได้เพราะเหตุอย่างอื่น แต่ถ้าในขณะยื่นฟ้องมารดาเด็กไม่มีชีวิตอยู่ จะฟ้องเด็กแต่ผู้เดียวเป็นจำเลยก็ได้ ถ้าเด็กไม่มีชีวิตอยู่ไม่ว่ามารดาของเด็กจะมีชีวิตอยู่หรือไม่ จะยื่นคำร้องขอให้ศาลแสดงว่าเด็กนั้นไม่เป็นบุตรก็ได้ ในกรณีที่มารดาของเด็กหรือทายาทของเด็กยังมีชีวิตอยู่ ให้ศาลส่งสำเนาคำร้องนี้ไปให้ด้วย และถ้าศาลเห็นสมควร จะส่งสำเนาคำร้องไปให้อัยการพิจารณาเพื่อดำเนินคดีแทนเด็กด้วยก็ได้"}},{"id":"TH-H004-A1540","no":1540,"noLabel":{"th":"มาตรา 1540"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๐ (ยกเลิก)"}},{"id":"TH-H004-A1541","no":1541,"noLabel":{"th":"มาตรา 1541"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๑ ชายผู้เป็นหรือเคยเป็นคู่สมรสจะฟ้องคดีไม่รับเด็กเป็นบุตรตามมาตรา ๑๕๓๙ ไม่ได้ ถ้าปรากฏว่าตนเป็นผู้แจ้งการเกิดของเด็กในทะเบียนคนเกิดเองว่าเป็นบุตรของตน หรือจัดหรือยอมให้มีการแจ้งดังกล่าว"}},{"id":"TH-H004-A1542","no":1542,"noLabel":{"th":"มาตรา 1542"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๒ การฟ้องคดีไม่รับเด็กเป็นบุตร ชายผู้เป็นหรือเคยเป็นคู่สมรสต้องฟ้องภายในหนึ่งปีนับแต่วันรู้ถึงการเกิดของเด็ก แต่ห้ามมิให้ฟ้องเมื่อพ้นสิบปีนับแต่วันเกิดของเด็ก ในกรณีที่มีคำพิพากษาของศาลแสดงว่าเด็กมิใช่บุตรชอบด้วยกฎหมายของชายผู้เป็นคู่สมรสคนใหม่ตามมาตรา ๑๕๓๗ หรือชายผู้เป็นคู่สมรสในการสมรสครั้งหลังตามมาตรา ๑๕๓๘ ถ้าชายผู้เป็นหรือเคยเป็นคู่สมรสซึ่งต้องด้วยบทสันนิษฐานว่าเด็กเป็นบุตรชอบด้วยกฎหมายของตนตามมาตรา ๑๕๓๖ ประสงค์จะฟ้องคดีไม่รับเด็กเป็นบุตร ให้ฟ้องคดีภายในหนึ่งปีนับแต่วันที่รู้ว่ามีคำพิพากษาถึงที่สุด"}},{"id":"TH-H004-A1543","no":1543,"noLabel":{"th":"มาตรา 1543"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๓ ในกรณีที่ชายผู้เป็นหรือเคยเป็นคู่สมรสได้ฟ้องคดีไม่รับเด็กเป็นบุตรแล้ว และตายก่อนคดีนั้นถึงที่สุด ผู้มีสิทธิได้รับมรดกร่วมกับเด็กหรือผู้จะเสียสิทธิรับมรดกเพราะการเกิดของเด็กนั้น จะขอเข้าเป็นคู่ความแทนที่หรืออาจถูกเรียกให้เข้ามาเป็นคู่ความแทนที่ชายผู้เป็นหรือเคยเป็นคู่สมรสก็ได้"}},{"id":"TH-H004-A1544","no":1544,"noLabel":{"th":"มาตรา 1544"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๔ การฟ้องคดีไม่รับเด็กเป็นบุตร ผู้มีสิทธิได้รับมรดกร่วมกับเด็กหรือผู้จะเสียสิทธิรับมรดกเพราะการเกิดของเด็กอาจฟ้องได้ ในกรณีดังต่อไปนี้ (๑) ชายผู้เป็นหรือเคยเป็นคู่สมรสตายก่อนพ้นระยะเวลาที่ชายผู้เป็นหรือเคยเป็นคู่สมรสจะพึงฟ้องได้ (๒) เด็กเกิดภายหลังการตายของชายผู้เป็นหรือเคยเป็นคู่สมรส การฟ้องคดีไม่รับเด็กเป็นบุตรในกรณี (๑) ต้องฟ้องภายในหกเดือนนับแต่วันที่รู้ถึงการตายของชายผู้เป็นหรือเคยเป็นคู่สมรส การฟ้องคดีไม่รับเด็กเป็นบุตรในกรณี (๒) ต้องฟ้องภายในหกเดือนนับแต่วันที่รู้ถึงการเกิดของเด็ก แต่ไม่ว่าเป็นกรณีใด ห้ามมิให้ฟ้องเมื่อพ้นสิบปีนับแต่วันเกิดของเด็ก ให้นำมาตรา ๑๕๓๙ มาใช้บังคับแก่การฟ้องคดีไม่รับเด็กเป็นบุตรตามวรรคหนึ่งโดยอนุโลม"}},{"id":"TH-H004-A1545","no":1545,"noLabel":{"th":"มาตรา 1545"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๕ เมื่อปรากฏข้อเท็จจริงต่อเด็กว่าตนมิได้เป็นบุตรสืบสายโลหิตของชายผู้เป็นคู่สมรสของมารดาตน เด็กจะร้องขอต่ออัยการให้ฟ้องคดีปฏิเสธความเป็นบุตรชอบด้วยกฎหมายของชายนั้นก็ได้ การฟ้องคดีตามวรรคหนึ่ง ถ้าเด็กได้รู้ข้อเท็จจริงก่อนบรรลุนิติภาวะว่าตนมิได้เป็นบุตรของชายผู้เป็นคู่สมรสของมารดา ห้ามอัยการฟ้องคดีเมื่อพ้นหนึ่งปีนับแต่วันที่เด็กบรรลุนิติภาวะ แต่ถ้าเด็กรู้ข้อเท็จจริงดังกล่าวหลังจากบรรลุนิติภาวะแล้ว ห้ามอัยการฟ้องคดีเมื่อพ้นหนึ่งปีนับแต่วันที่เด็กรู้เหตุนั้น ไม่ว่ากรณีใด ๆ ห้ามมิให้ฟ้องคดีปฏิเสธความเป็นบุตรเมื่อพ้นสิบปีนับแต่วันที่เด็กบรรลุนิติภาวะ"}},{"id":"TH-H004-A1546","no":1546,"noLabel":{"th":"มาตรา 1546"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๖ เด็กเกิดจากหญิงที่มิได้มีการสมรสกับชาย ให้ถือว่าเป็นบุตรชอบด้วยกฎหมายของหญิงนั้น เว้นแต่จะมีกฎหมายบัญญัติไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1547","no":1547,"noLabel":{"th":"มาตรา 1547"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๗ เด็กเกิดจากบิดามารดาที่มิได้สมรสกัน จะเป็นบุตรชอบด้วยกฎหมายต่อเมื่อบิดามารดาได้สมรสกันในภายหลังหรือบิดาได้จดทะเบียนว่าเป็นบุตรหรือศาลพิพากษาว่าเป็นบุตร"}},{"id":"TH-H004-A1548","no":1548,"noLabel":{"th":"มาตรา 1548"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๘ บิดาจะจดทะเบียนเด็กเป็นบุตรชอบด้วยกฎหมายได้ต่อเมื่อได้รับความยินยอมของเด็กและมารดาเด็ก ในกรณีที่เด็กและมารดาเด็กไม่ได้มาให้ความยินยอมต่อหน้านายทะเบียนให้นายทะเบียนแจ้งการขอจดทะเบียนของบิดาไปยังเด็กและมารดาเด็ก ถ้าเด็กหรือมารดาเด็กไม่คัดค้านหรือไม่ให้ความยินยอมภายในหกสิบวันนับแต่การแจ้งนั้นถึงเด็กหรือมารดาเด็ก ให้สันนิษฐานว่าเด็กหรือมารดาเด็กไม่ให้ความยินยอม ถ้าเด็กหรือมารดาเด็กอยู่นอกประเทศไทยให้ขยายเวลานั้นเป็นหนึ่งร้อยแปดสิบวัน ในกรณีที่เด็กหรือมารดาเด็กคัดค้านว่าผู้ขอจดทะเบียนไม่ใช่บิดา หรือไม่ให้ความยินยอม หรือไม่อาจให้ความยินยอมได้ การจดทะเบียนเด็กเป็นบุตรต้องมีคำพิพากษาของศาล เมื่อศาลได้พิพากษาให้บิดาจดทะเบียนเด็กเป็นบุตรได้ และบิดาได้นำคำพิพากษาไปขอจดทะเบียนต่อนายทะเบียนให้นายทะเบียนดำเนินการจดทะเบียนให้"}},{"id":"TH-H004-A1549","no":1549,"noLabel":{"th":"มาตรา 1549"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๔๙ เมื่อนายทะเบียนได้แจ้งการขอจดทะเบียนขอรับเด็กเป็นบุตรชอบด้วยกฎหมายไปยังเด็กและมารดาเด็กตามมาตรา ๑๕๔๘ แล้ว ไม่ว่าเด็กหรือมารดาเด็กจะคัดค้านการจดทะเบียนรับเด็กเป็นบุตรตามมาตรา ๑๕๔๘ หรือไม่ ภายในกำหนดเวลาไม่เกินเก้าสิบวันนับแต่วันแจ้งการขอจดทะเบียนถึงเด็กหรือมารดาเด็ก เด็กหรือมารดาเด็กอาจแจ้งให้นายทะเบียนจดบันทึกไว้ได้ว่าผู้ขอจดทะเบียนไม่สมควร เป็นผู้ใช้อำนาจปกครองบางส่วนหรือทั้งหมด เมื่อได้มีคำแจ้งของเด็กหรือมารดาเด็กดังกล่าวในวรรคหนึ่งแล้ว แม้จะได้มีการจดทะเบียนรับเด็กเป็นบุตรตามมาตรา ๑๕๔๘ บิดาของเด็กก็ยังใช้อำนาจปกครองบางส่วนหรือทั้งหมดตามที่เด็กหรือมารดาเด็กแจ้งว่าบิดาไม่สมควรเป็นผู้ใช้อำนาจปกครองนั้นไม่ได้ จนกว่าศาลจะพิพากษาให้บิดาของเด็กใช้อำนาจปกครองบางส่วนหรือทั้งหมด หรือกำหนดเวลาเก้าสิบวันนับแต่วันที่เด็กหรือมารดาเด็กแจ้งต่อนายทะเบียนว่าผู้ขอจดทะเบียนรับเด็กเป็นบุตรไม่สมควรใช้อำนาจปกครองบางส่วนหรือทั้งหมดนั้นได้ล่วงพ้นไปโดยเด็กหรือมารดาเด็กมิได้ร้องขอต่อศาลให้พิพากษาว่าผู้ขอจดทะเบียนรับเด็กเป็นบุตรไม่เป็นผู้สมควรใช้อำนาจปกครองบางส่วนหรือทั้งหมด ในคดีที่ศาลพิพากษาว่าผู้ขอจดทะเบียนรับเด็กเป็นบุตรเป็นผู้ไม่สมควรใช้อำนาจปกครองบางส่วนหรือทั้งหมด ศาลจะพิพากษาในคดีเดียวกันนั้นให้ผู้ใดเป็นผู้ใช้อำนาจปกครองหรือเป็นผู้ปกครองเพื่อการปกครองบางส่วนหรือทั้งหมดก็ได้"}},{"id":"TH-H004-A1550","no":1550,"noLabel":{"th":"มาตรา 1550"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๐ (ยกเลิก)"}},{"id":"TH-H004-A1551","no":1551,"noLabel":{"th":"มาตรา 1551"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๑ ในกรณีที่มีการคัดค้านว่าผู้ซึ่งขอจดทะเบียนรับเด็กเป็นบุตรมิใช่บิดาของเด็ก เมื่อผู้ซึ่งขอจดทะเบียนรับเด็กเป็นบุตรนำคดีไปสู่ศาลขอให้ศาลพิพากษาว่าผู้ขอจดทะเบียนรับเด็กเป็นบุตรเป็นบิดาของเด็ก เด็กหรือมารดาเด็กจะขอให้ศาลพิพากษาในคดีเดียวกันนั้นก็ได้ว่า ผู้ขอจดทะเบียนรับเด็กเป็นบุตรแม้จะเป็นบิดาของเด็ก ก็เป็นผู้ไม่สมควรใช้อำนาจปกครองบางส่วนหรือทั้งหมด ในกรณีเช่นว่านี้ให้นำความในวรรคสามของมาตรา ๑๕๔๙ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1552","no":1552,"noLabel":{"th":"มาตรา 1552"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๒ ในกรณีที่เด็กไม่มีมารดาหรือมีมารดาแต่มารดาถูกถอนอำนาจปกครองบางส่วนหรือทั้งหมดและศาลได้ตั้งผู้อื่นเป็นผู้ปกครองบางส่วนหรือทั้งหมดไว้ก่อนมีการจดทะเบียนรับเด็กเป็นบุตร บิดาซึ่งจดทะเบียนรับเด็กเป็นบุตรชอบด้วยกฎหมายแล้วจะร้องขอต่อศาลให้มีคำสั่งถอนความเป็นผู้ปกครองบางส่วน หรือทั้งหมดของผู้ปกครองและให้บิดาเป็นผู้ใช้อำนาจปกครองก็ได้ ถ้าศาลเห็นว่าบิดาอาจใช้อำนาจปกครองเพื่อความผาสุกและประโยชน์ของเด็กได้ดียิ่งกว่าผู้ปกครอง ศาลจะมีคำสั่งถอนความเป็นผู้ปกครองบางส่วนหรือทั้งหมดของผู้ปกครองและให้บิดาเป็นผู้ใช้อำนาจปกครองก็ได้"}},{"id":"TH-H004-A1553","no":1553,"noLabel":{"th":"มาตรา 1553"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๓ (ยกเลิก)"}},{"id":"TH-H004-A1554","no":1554,"noLabel":{"th":"มาตรา 1554"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๔ ผู้มีส่วนได้เสียจะขอให้ศาลถอนการจดทะเบียนรับเด็กเป็นบุตร เพราะเหตุว่าผู้ขอให้จดทะเบียนนั้นมิใช่บิดาก็ได้ แต่ต้องฟ้องภายในสามเดือนนับแต่วันที่รู้การจดทะเบียนนั้น อนึ่ง ห้ามมิให้ฟ้องเมื่อพ้นสิบปีนับแต่วันจดทะเบียน"}},{"id":"TH-H004-A1555","no":1555,"noLabel":{"th":"มาตรา 1555"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๕ ในคดีฟ้องขอให้รับเด็กเป็นบุตรชอบด้วยกฎหมาย ให้สันนิษฐานไว้ก่อนว่าเด็กเป็นบุตรชอบด้วยกฎหมายของชายเมื่อปรากฏข้อเท็จจริงอย่างหนึ่งอย่างใดดังต่อไปนี้ (๑) เมื่อมีการข่มขืนกระทำชำเรา ฉุดคร่า หรือหน่วงเหนี่ยวกักขังหญิงมารดาโดยมิชอบด้วยกฎหมายในระยะเวลาซึ่งหญิงนั้นอาจตั้งครรภ์ได้ (๒) เมื่อมีการลักพาหญิงมารดาไปในทางชู้สาวหรือมีการล่อลวงร่วมประเวณีกับหญิงมารดาในระยะเวลาซึ่งหญิงนั้นอาจตั้งครรภ์ได้ (๓) เมื่อมีเอกสารของบิดาแสดงว่าเด็กนั้นเป็นบุตรของตน (๔) เมื่อปรากฏในทะเบียนคนเกิดว่าเด็กเป็นบุตรโดยมีหลักฐานว่าบิดาเป็นผู้แจ้งการเกิดหรือรู้เห็นยินยอมในการแจ้งนั้น (๕) เมื่อบิดามารดาได้อยู่กินด้วยกันอย่างเปิดเผยในระยะเวลาซึ่งหญิงมารดาอาจตั้งครรภ์ได้ (๖) เมื่อได้มีการร่วมประเวณีกับหญิงมารดาในระยะเวลาซึ่งหญิงนั้นอาจตั้งครรภ์ได้ และมีเหตุอันควรเชื่อได้ว่าเด็กนั้นมิได้เป็นบุตรของชายอื่น (๗) เมื่อมีพฤติการณ์ที่รู้กันทั่วไปตลอดมาว่าเป็นบุตร พฤติการณ์ที่รู้กันทั่วไปตลอดมาว่าเป็นบุตรนั้น ให้พิจารณาข้อเท็จจริงที่แสดงความเกี่ยวข้องฉันบิดากับบุตรซึ่งปรากฏในระหว่างตัวเด็กกับครอบครัวที่เด็กอ้างว่าตนสังกัดอยู่ เช่น บิดาให้การศึกษา ให้ความอุปการะเลี้ยงดูหรือยอมให้เด็กนั้นใช้ชื่อสกุลของตนหรือโดยเหตุประการอื่น ในกรณีใดกรณีหนึ่งดังกล่าวข้างต้น ถ้าปรากฏว่าชายไม่อาจเป็นบิดาของเด็กนั้นได้ ให้ยกฟ้องเสีย"}},{"id":"TH-H004-A1556","no":1556,"noLabel":{"th":"มาตรา 1556"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๖ การฟ้องคดีขอให้รับเด็กเป็นบุตรในระหว่างที่เด็กเป็นผู้เยาว์ ถ้าเด็กมีอายุยังไม่ครบสิบห้าปีบริบูรณ์ ผู้แทนโดยชอบธรรมของเด็กเป็นผู้ฟ้องแทน ในกรณีที่เด็กไม่มีผู้แทนโดยชอบธรรม หรือมีแต่ผู้แทนโดยชอบธรรมไม่สามารถทำหน้าที่ได้ ญาติสนิทของเด็กหรืออัยการอาจร้องขอต่อศาลให้ตั้งผู้แทนเฉพาะคดีเพื่อทำหน้าที่ฟ้องคดีแทนเด็กก็ได้ เมื่อเด็กมีอายุสิบห้าปีบริบูรณ์ เด็กต้องฟ้องเอง ทั้งนี้ โดยไม่จำต้องได้รับความยินยอมของผู้แทนโดยชอบธรรม ในกรณีที่เด็กบรรลุนิติภาวะแล้ว จะต้องฟ้องคดีภายในหนึ่งปีนับแต่วันบรรลุนิติภาวะ ในกรณีที่เด็กตายในระหว่างที่เด็กนั้นยังมีสิทธิฟ้องคดีขอให้รับเด็กเป็นบุตรอยู่ ผู้สืบสันดานของเด็กจะฟ้องคดีขอให้รับเด็กเป็นบุตรก็ได้ ถ้าผู้สืบสันดานของเด็กได้รู้เหตุที่อาจขอให้รับเด็กเป็นบุตรมาก่อนวันที่เด็กนั้นตาย ผู้สืบสันดานของเด็กจะต้องฟ้องภายในหนึ่งปีนับแต่วันที่เด็กนั้นตาย ถ้าผู้สืบสันดานของเด็กได้รู้เหตุที่อาจขอให้รับเด็กเป็นบุตรภายหลังที่เด็กนั้นตายผู้สืบสันดานของเด็กจะต้องฟ้องภายในหนึ่งปีนับแต่วันที่รู้เหตุดังกล่าว แต่ทั้งนี้ ต้องไม่พ้นสิบปีนับแต่วันที่เด็กนั้นตาย การฟ้องคดีขอให้รับเด็กเป็นบุตรในระหว่างที่ผู้สืบสันดานของเด็กเป็นผู้เยาว์ ให้นำความในวรรคหนึ่งและวรรคสองมาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1557","no":1557,"noLabel":{"th":"มาตรา 1557"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๗ การเป็นบุตรชอบด้วยกฎหมายตามมาตรา ๑๕๔๗ ให้มีผลนับแต่วันที่เด็กเกิด แต่ทั้งนี้จะอ้างเป็นเหตุเสื่อมสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริตในระหว่างเวลาตั้งแต่เด็กเกิดจนถึงเวลาที่บิดามารดาได้สมรสกันหรือบิดาได้จดทะเบียนว่าเป็นบุตรหรือศาลพิพากษาถึงที่สุดว่าเป็นบุตรไม่ได้"}},{"id":"TH-H004-A1558","no":1558,"noLabel":{"th":"มาตรา 1558"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๘ การฟ้องคดีขอให้รับเด็กเป็นบุตรของผู้ตายที่ได้ฟ้องภายในกำหนดอายุความมรดก ถ้าศาลได้พิพากษาว่าเด็กเป็นบุตรชอบด้วยกฎหมายของผู้ตาย เด็กนั้นมีสิทธิรับมรดกในฐานะทายาทโดยธรรม ในกรณีที่ได้มีการแบ่งมรดกไปแล้ว ให้นำบทบัญญัติแห่งประมวลกฎหมายนี้ว่าด้วยเรื่องลาภมิควรได้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1559","no":1559,"noLabel":{"th":"มาตรา 1559"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๕๙ เมื่อได้จดทะเบียนเด็กเป็นบุตรแล้วจะถอนมิได้"}},{"id":"TH-H004-A1560","no":1560,"noLabel":{"th":"มาตรา 1560"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๖๐ บุตรเกิดระหว่างสมรสซึ่งศาลพิพากษาให้เพิกถอนภายหลังนั้นให้ถือว่าเป็นบุตรชอบด้วยกฎหมาย"}},{"id":"TH-H004-A1561","no":1561,"noLabel":{"th":"มาตรา 1561"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๑ บุตรมีสิทธิใช้ชื่อสกุลของบิดา ในกรณีที่บิดาไม่ปรากฏ บุตรมีสิทธิใช้ชื่อสกุลของมารดา"}},{"id":"TH-H004-A1562","no":1562,"noLabel":{"th":"มาตรา 1562"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๒ ผู้ใดจะฟ้องบุพการีของตนเป็นคดีแพ่งหรือคดีอาญามิได้ แต่เมื่อผู้นั้นหรือญาติสนิทของผู้นั้นร้องขอ อัยการจะยกคดีขึ้นว่ากล่าวก็ได้"}},{"id":"TH-H004-A1563","no":1563,"noLabel":{"th":"มาตรา 1563"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๓ บุตรจำต้องอุปการะเลี้ยงดูบิดามารดา"}},{"id":"TH-H004-A1564","no":1564,"noLabel":{"th":"มาตรา 1564"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๔ บิดามารดาจำต้องอุปการะเลี้ยงดูและให้การศึกษาตามสมควรแก่บุตรในระหว่างที่เป็นผู้เยาว์ บิดามารดาจำต้องอุปการะเลี้ยงดูบุตรซึ่งบรรลุนิติภาวะแล้วแต่เฉพาะผู้ทุพพลภาพและหาเลี้ยงตนเองมิได้"}},{"id":"TH-H004-A1565","no":1565,"noLabel":{"th":"มาตรา 1565"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๕ การร้องขอค่าอุปการะเลี้ยงดูบุตรหรือขอให้บุตรได้รับการอุปการะเลี้ยงดูโดยประการอื่น นอกจากอัยการจะยกคดีขึ้นว่ากล่าวตามมาตรา ๑๕๖๒ แล้ว บิดาหรือมารดาจะนำคดีขึ้นว่ากล่าวก็ได้"}},{"id":"TH-H004-A1566","no":1566,"noLabel":{"th":"มาตรา 1566"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๖ บุตรซึ่งยังไม่บรรลุนิติภาวะต้องอยู่ใต้อำนาจปกครองของบิดามารดา อำนาจปกครองอยู่กับบิดาหรือมารดาในกรณีดังต่อไปนี้ (๑) มารดาหรือบิดาตาย (๒) ไม่แน่นอนว่ามารดาหรือบิดามีชีวิตอยู่หรือตาย (๓) มารดาหรือบิดาถูกศาลสั่งให้เป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถ (๔) มารดาหรือบิดาต้องเข้ารักษาตัวในโรงพยาบาลเพราะจิตฟั่นเฟือน (๕) ศาลสั่งให้อำนาจปกครองอยู่กับบิดาหรือมารดา (๖) บิดาและมารดาตกลงกันตามที่มีกฎหมายบัญญัติไว้ให้ตกลงกันได้"}},{"id":"TH-H004-A1567","no":1567,"noLabel":{"th":"มาตรา 1567"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๗ ผู้ใช้อำนาจปกครองมีสิทธิ (๑) กำหนดที่อยู่ของบุตร (๒) ทำโทษบุตรเพื่อว่ากล่าวสั่งสอนหรือปรับพฤติกรรม โดยต้องไม่เป็นการกระทำทารุณกรรมหรือทำร้ายด้วยความรุนแรงต่อร่างกายหรือจิตใจ หรือกระทำโดยมิชอบ (๓) ให้บุตรทำการงานตามสมควรแก่ความสามารถและฐานานุรูป (๔) เรียกบุตรคืนจากบุคคลอื่นซึ่งกักบุตรไว้โดยมิชอบด้วยกฎหมาย"}},{"id":"TH-H004-A1568","no":1568,"noLabel":{"th":"มาตรา 1568"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๘ เมื่อบุคคลใดมีบุตรติดมาได้สมรสกับบุคคลอื่น อำนาจปกครองที่มีต่อบุตรอยู่กับผู้ที่บุตรนั้นติดมา"}},{"id":"TH-H004-A1569","no":1569,"noLabel":{"th":"มาตรา 1569"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๙ ผู้ใช้อำนาจปกครองเป็นผู้แทนโดยชอบธรรมของบุตรในกรณีที่บุตรถูกศาลสั่งให้เป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถ ผู้ใช้อำนาจปกครองย่อมเป็นผู้อนุบาลหรือผู้พิทักษ์ แล้วแต่กรณี"}},{"id":"TH-H004-A1569.001","no":1569.001,"noLabel":{"th":"มาตรา 1569/1"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๖๙/๑ ในกรณีที่ผู้เยาว์ถูกศาลสั่งให้เป็นคนไร้ความสามารถและศาลมีคำสั่งตั้งบุคคลอื่นซึ่งมิใช่ผู้ใช้อำนาจปกครองหรือผู้ปกครองเป็นผู้อนุบาลให้คำสั่งนั้นมีผลเป็นการถอนผู้ใช้อำนาจปกครอง หรือผู้ปกครองที่เป็นอยู่ในขณะนั้น ในกรณีที่บุคคลซึ่งบรรลุนิติภาวะและไม่มีคู่สมรสถูกศาลสั่งให้เป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถ ให้บิดามารดา หรือบิดาหรือมารดาเป็นผู้อนุบาลหรือผู้พิทักษ์ แล้วแต่กรณี เว้นแต่ศาลจะสั่งเป็นอย่างอื่น"}},{"id":"TH-H004-A1570","no":1570,"noLabel":{"th":"มาตรา 1570"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๐ คำบอกกล่าวที่ผู้ใช้อำนาจปกครองตามมาตรา ๑๕๖๖ หรือมาตรา ๑๕๖๘ แจ้งไปหรือรับแจ้งมาให้ถือว่าเป็นคำบอกกล่าวที่บุตรได้แจ้งไปหรือรับแจ้งมา"}},{"id":"TH-H004-A1571","no":1571,"noLabel":{"th":"มาตรา 1571"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๑ อำนาจปกครองนั้น รวมทั้งการจัดการทรัพย์สินของบุตรด้วย และให้จัดการทรัพย์สินนั้นด้วยความระมัดระวังเช่นวิญญูชนจะพึงกระทำ"}},{"id":"TH-H004-A1572","no":1572,"noLabel":{"th":"มาตรา 1572"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๒ ผู้ใช้อำนาจปกครองจะทำหนี้ที่บุตรจะต้องทำเองโดยมิได้รับความยินยอมของบุตรไม่ได้"}},{"id":"TH-H004-A1573","no":1573,"noLabel":{"th":"มาตรา 1573"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๓ ถ้าบุตรมีเงินได้ ให้ใช้เงินนั้นเป็นค่าอุปการะเลี้ยงดูและการศึกษาก่อน ส่วนที่เหลือผู้ใช้อำนาจปกครองต้องเก็บรักษาไว้เพื่อส่งมอบแก่บุตร แต่ถ้าผู้ใช้อำนาจปกครองไม่มีเงินได้เพียงพอแก่การครองชีพตามสมควรแก่ฐานะ ผู้ใช้อำนาจปกครองจะใช้เงินนั้นตามสมควรก็ได้ เว้นแต่จะเป็นเงินได้ที่เกิดจากทรัพย์สินโดยการให้โดยเสน่หาหรือพินัยกรรมซึ่งมีเงื่อนไขว่ามิให้ผู้ใช้อำนาจปกครองได้ประโยชน์จากทรัพย์สินนั้น ๆ"}},{"id":"TH-H004-A1574","no":1574,"noLabel":{"th":"มาตรา 1574"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๔ นิติกรรมใดอันเกี่ยวกับทรัพย์สินของผู้เยาว์ดังต่อไปนี้ ผู้ใช้อำนาจปกครองจะกระทำมิได้ เว้นแต่ศาลจะอนุญาต (๑) ขาย แลกเปลี่ยน ขายฝาก ให้เช่าซื้อ จำนอง ปลดจำนอง หรือโอนสิทธิจำนอง ซึ่งอสังหาริมทรัพย์หรือสังหาริมทรัพย์ที่อาจจำนองได้ (๒) กระทำให้สุดสิ้นลงทั้งหมดหรือบางส่วน ซึ่งทรัพยสิทธิของผู้เยาว์อันเกี่ยวกับอสังหาริมทรัพย์ (๓) ก่อตั้งภาระจำยอม สิทธิอาศัย สิทธิเหนือพื้นดิน สิทธิเก็บกิน ภาระติดพันในอสังหาริมทรัพย์ หรือทรัพยสิทธิอื่นใดในอสังหาริมทรัพย์ (๔) จำหน่ายไปทั้งหมดหรือบางส่วนซึ่งสิทธิเรียกร้องที่จะให้ได้มาซึ่งทรัพยสิทธิในอสังหาริมทรัพย์ หรือสังหาริมทรัพย์ที่อาจจำนองได้ หรือสิทธิเรียกร้องที่จะให้ทรัพย์สินเช่นว่านั้นของผู้เยาว์ปลอดจากทรัพยสิทธิที่มีอยู่เหนือทรัพย์สินนั้น (๕) ให้เช่าอสังหาริมทรัพย์เกินสามปี (๖) ก่อข้อผูกพันใด ๆ ที่มุ่งให้เกิดผลตาม (๑) (๒) หรือ (๓) (๗) ให้กู้ยืมเงิน (๘) ให้โดยเสน่หา เว้นแต่จะเอาเงินได้ของผู้เยาว์ให้แทนผู้เยาว์เพื่อการกุศลสาธารณะ เพื่อการสังคม หรือตามหน้าที่ธรรมจรรยา ทั้งนี้ พอสมควรแก่ฐานานุรูปของผู้เยาว์ (๙) รับการให้โดยเสน่หาที่มีเงื่อนไขหรือค่าภาระติดพัน หรือไม่รับการให้โดยเสน่หา (๑๐) ประกันโดยประการใด ๆ อันอาจมีผลให้ผู้เยาว์ต้องถูกบังคับชำระหนี้หรือทำนิติกรรมอื่นที่มีผลให้ผู้เยาว์ต้องรับเป็นผู้รับชำระหนี้ของบุคคลอื่นหรือแทนบุคคลอื่น (๑๑) นำทรัพย์สินไปแสวงหาผลประโยชน์นอกจากในกรณีที่บัญญัติไว้ในมาตรา ๑๕๙๘/๔ (๑) (๒) หรือ (๓) (๑๒) ประนีประนอมยอมความ (๑๓) มอบข้อพิพาทให้อนุญาโตตุลาการวินิจฉัย"}},{"id":"TH-H004-A1575","no":1575,"noLabel":{"th":"มาตรา 1575"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๕ ถ้าในกิจการใด ประโยชน์ของผู้ใช้อำนาจปกครอง หรือประโยชน์ของคู่สมรสหรือบุตรของผู้ใช้อำนาจปกครองขัดกับประโยชน์ของผู้เยาว์ ผู้ใช้อำนาจปกครองต้องได้รับอนุญาตจากศาลก่อนจึงทำกิจการนั้นได้ มิฉะนั้นเป็นโมฆะ"}},{"id":"TH-H004-A1576","no":1576,"noLabel":{"th":"มาตรา 1576"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๖ ประโยชน์ของผู้ใช้อำนาจปกครอง หรือของคู่สมรสหรือบุตรของผู้ใช้อำนาจปกครองตามมาตรา ๑๕๗๕ ให้หมายความรวมถึงประโยชน์ในกิจการดังต่อไปนี้ด้วย คือ (๑) ประโยชน์ในกิจการที่กระทำกับห้างหุ้นส่วนสามัญที่บุคคลดังกล่าวนั้นเป็นหุ้นส่วน (๒) ประโยชน์ในกิจการที่กระทำกับห้างหุ้นส่วนจำกัดที่บุคคลดังกล่าวนั้นเป็นหุ้นส่วนจำพวกไม่จำกัดความรับผิด"}},{"id":"TH-H004-A1577","no":1577,"noLabel":{"th":"มาตรา 1577"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๗ บุคคลใดจะโอนทรัพย์สินให้ผู้เยาว์โดยพินัยกรรมหรือโดยการให้โดยเสน่หาซึ่งมีเงื่อนไขให้บุคคลอื่นนอกจากผู้ใช้อำนาจปกครองเป็นผู้จัดการจนกว่าผู้เยาว์จะบรรลุนิติภาวะก็ได้ ผู้จัดการนั้นต้องเป็นผู้ซึ่งผู้โอนระบุชื่อไว้ หรือถ้ามิได้ระบุไว้ก็ให้ศาลสั่ง แต่การจัดการทรัพย์สินนั้นต้องอยู่ภายในบังคับมาตรา ๕๖ มาตรา ๕๗ มาตรา ๖๐"}},{"id":"TH-H004-A1578","no":1578,"noLabel":{"th":"มาตรา 1578"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๘ ในกรณีที่อำนาจปกครองสิ้นไปเพราะผู้เยาว์บรรลุนิติภาวะผู้ใช้อำนาจปกครองต้องรีบส่งมอบทรัพย์สินที่จัดการและบัญชีในการนั้นให้ผู้บรรลุนิติภาวะเพื่อรับรอง ถ้ามีเอกสารเกี่ยวกับเรื่องจัดการทรัพย์สินนั้น ก็ให้ส่งมอบพร้อมกับบัญชี ในกรณีที่อำนาจปกครองสิ้นไปเพราะเหตุอื่นนอกจากที่กล่าวในวรรคหนึ่งให้มอบทรัพย์สิน บัญชี และเอกสารที่เกี่ยวกับเรื่องจัดการทรัพย์สินให้แก่ผู้ใช้อำนาจปกครอง ถ้ามี หรือผู้ปกครอง แล้วแต่กรณี เพื่อรับรอง"}},{"id":"TH-H004-A1579","no":1579,"noLabel":{"th":"มาตรา 1579"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๗๙ ในกรณีที่คู่สมรสฝ่ายหนึ่งถึงแก่ความตายและมีบุตรที่เกิดด้วยกันและคู่สมรสอีกฝ่ายหนึ่งจะสมรสใหม่ ถ้าคู่สมรสนั้นได้ครอบครองทรัพย์สินอันเป็นสัดส่วนของบุตรไว้อย่างถูกต้องแล้ว จะส่งมอบทรัพย์สินให้แก่บุตรในเมื่อสามารถจัดการก็ได้ หรือมิฉะนั้นจะเก็บรักษาไว้เพื่อมอบให้บุตรเมื่อถึงเวลาอันสมควรก็ได้ แต่ถ้าทรัพย์สินใดเป็นจำพวกที่ระบุไว้ในมาตรา ๔๕๖ หรือที่มีเอกสารเป็นสำคัญ ให้ลงชื่อบุตรเป็นเจ้าของรวมในเอกสารนั้น ก่อนที่จะจัดการดังกล่าวคู่สมรสนั้นจะทำการสมรสมิได้ ในกรณีที่มีเหตุอันสมควร ศาลจะมีคำสั่งให้คู่สมรสดังกล่าวทำการสมรสไปก่อนก็ได้ คำสั่งศาลเช่นว่านี้ ให้ระบุไว้ด้วยว่าให้คู่สมรสปฏิบัติการแบ่งแยกทรัพย์สินและทำบัญชีทรัพย์สิน ตามความในวรรคหนึ่งภายในกำหนดเวลาเท่าใดภายหลังการสมรสนั้นด้วย ในกรณีที่การสมรสได้กระทำไปโดยมิได้ปฏิบัติตามวรรคหนึ่ง หรือในกรณีที่คู่สมรสไม่ปฏิบัติตามคำสั่งของศาลดังกล่าวในวรรคสอง เมื่อความปรากฏแก่ศาลเอง หรือเมื่อญาติของผู้เยาว์หรืออัยการร้องขอ ศาลมีอำนาจสั่งให้ถอนอำนาจปกครองจากคู่สมรสนั้น หรือจะมอบให้บุคคลหนึ่งบุคคลใดทำบัญชีและลงชื่อบุตรเป็นเจ้าของรวมในเอกสารดังกล่าวแทนโดยให้คู่สมรสเสียค่าใช้จ่ายก็ได้ เพื่อประโยชน์แห่งมาตรานี้ ให้ถือว่าบุตรบุญธรรมของคู่สมรสที่ตายไปและที่มีชีวิตอยู่ทั้งสองฝ่ายเป็นบุตรที่เกิดจากคู่สมรส"}},{"id":"TH-H004-A1580","no":1580,"noLabel":{"th":"มาตรา 1580"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๐ ผู้เยาว์ซึ่งบรรลุนิติภาวะแล้ว ผู้ใช้อำนาจปกครองหรือผู้ปกครองจะให้การรับรองการจัดการทรัพย์สินของผู้เยาว์ได้ต่อเมื่อได้รับมอบทรัพย์สินบัญชีและเอกสารตามมาตรา ๑๕๗๘ แล้ว"}},{"id":"TH-H004-A1581","no":1581,"noLabel":{"th":"มาตรา 1581"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๑ คดีเกี่ยวกับการจัดการทรัพย์สินในระหว่างผู้เยาว์กับผู้ใช้อำนาจปกครองนั้น ห้ามมิให้ฟ้องเมื่อพ้นหนึ่งปีนับแต่เวลาที่อำนาจปกครองสิ้นไป ถ้าอำนาจปกครองสิ้นไปขณะบุตรยังเป็นผู้เยาว์อยู่ ให้เริ่มนับอายุความในวรรคหนึ่งตั้งแต่เวลาที่ผู้เยาว์บรรลุนิติภาวะ หรือเมื่อมีผู้แทนโดยชอบธรรมขึ้นใหม่"}},{"id":"TH-H004-A1582","no":1582,"noLabel":{"th":"มาตรา 1582"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๒ ถ้าผู้ใช้อำนาจปกครองเป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถโดยคำสั่งของศาลก็ดี ใช้อำนาจปกครองเกี่ยวแก่ตัวผู้เยาว์โดยมิชอบก็ดี ประพฤติชั่วร้ายก็ดี ในกรณีเหล่านี้ศาลจะสั่งเอง หรือจะสั่งเมื่อญาติของผู้เยาว์หรืออัยการร้องขอให้ถอนอำนาจปกครองเสียบางส่วนหรือทั้งหมดก็ได้ ถ้าผู้ใช้อำนาจปกครองล้มละลายก็ดี หรือจัดการทรัพย์สินของผู้เยาว์ในทางที่ผิดจนอาจเป็นภัยก็ดี ศาลจะสั่งตามวิธีในวรรคหนึ่งให้ถอนอำนาจจัดการทรัพย์สินเสียก็ได้"}},{"id":"TH-H004-A1583","no":1583,"noLabel":{"th":"มาตรา 1583"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๓ ผู้ถูกถอนอำนาจปกครองบางส่วนหรือทั้งหมดนั้น ถ้าเหตุดังกล่าวไว้ในมาตราก่อนสิ้นไปแล้ว และเมื่อตนเองหรือญาติของผู้เยาว์ร้องขอ ศาลจะสั่งให้มีอำนาจปกครองดังเดิมก็ได้"}},{"id":"TH-H004-A1584","no":1584,"noLabel":{"th":"มาตรา 1584"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๔ การที่ผู้ใช้อำนาจปกครองถูกถอนอำนาจปกครองบางส่วนหรือทั้งหมด ไม่เป็นเหตุให้ผู้นั้นพ้นจากหน้าที่อุปการะเลี้ยงดูผู้เยาว์ตามกฎหมาย"}},{"id":"TH-H004-A1584.001","no":1584.001,"noLabel":{"th":"มาตรา 1584/1"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๕๘๔/๑ บิดาหรือมารดาย่อมมีสิทธิที่จะติดต่อกับบุตรของตนได้ตามควรแก่พฤติการณ์ ไม่ว่าบุคคลใดจะเป็นผู้ใช้อำนาจปกครองหรือผู้ปกครองก็ตาม"}},{"id":"TH-H004-A1585","no":1585,"noLabel":{"th":"มาตรา 1585"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๘๕ บุคคลที่ยังไม่บรรลุนิติภาวะและไม่มีบิดามารดาหรือบิดามารดาถูกถอนอำนาจปกครองเสียแล้วนั้น จะจัดให้มีผู้ปกครองขึ้นในระหว่างที่เป็นผู้เยาว์ก็ได้ ในกรณีที่ผู้ใช้อำนาจปกครองถูกถอนอำนาจปกครองบางส่วนตามมาตรา ๑๕๘๒ วรรคหนึ่ง ศาลจะตั้งผู้ปกครองในส่วนที่ผู้ใช้อำนาจปกครองถูกถอนอำนาจปกครองนั้นก็ได้ หรือในกรณีที่ผู้ใช้อำนาจปกครองถูกถอนอำนาจจัดการทรัพย์สินตามมาตรา ๑๕๘๒ วรรคสอง ศาลจะตั้งผู้ปกครองเพื่อจัดการทรัพย์สินก็ได้"}},{"id":"TH-H004-A1586","no":1586,"noLabel":{"th":"มาตรา 1586"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๘๖ ผู้ปกครองตามมาตรา ๑๕๘๕ นั้นให้ตั้งโดยคำสั่งศาลเมื่อมีการร้องขอของญาติของผู้เยาว์ อัยการ หรือผู้ซึ่งบิดาหรือมารดาที่ตายทีหลังได้ระบุชื่อไว้ในพินัยกรรมให้เป็นผู้ปกครอง ภายใต้บังคับมาตรา ๑๕๙๐ การตั้งผู้ปกครองนั้นถ้ามีข้อกำหนดพินัยกรรมก็ให้ศาลตั้งตามข้อกำหนดพินัยกรรม เว้นแต่พินัยกรรมนั้นไม่มีผลบังคับหรือบุคคลที่ระบุชื่อไว้ในพินัยกรรมนั้นเป็นบุคคลที่ต้องห้ามมิให้เป็นผู้ปกครองตามมาตรา ๑๕๘๗"}},{"id":"TH-H004-A1587","no":1587,"noLabel":{"th":"มาตรา 1587"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๘๗ บุคคลที่บรรลุนิติภาวะแล้วอาจถูกตั้งเป็นผู้ปกครองได้ เว้นแต่ (๑) ผู้ซึ่งศาลสั่งว่าเป็นคนไร้ความสามารถ หรือเสมือนไร้ความสามารถ (๒) ผู้ซึ่งเป็นบุคคลล้มละลาย (๓) ผู้ซึ่งไม่เหมาะสมที่จะปกครองผู้เยาว์หรือทรัพย์สินของผู้เยาว์ (๔) ผู้ซึ่งมีหรือเคยมีคดีในศาลกับผู้เยาว์ ผู้บุพการีหรือพี่น้องร่วมบิดามารดาหรือร่วมแต่บิดาหรือมารดากับผู้เยาว์ (๕) ผู้ซึ่งบิดาหรือมารดาที่ตายได้ทำหนังสือระบุชื่อห้ามไว้มิให้เป็นผู้ปกครอง"}},{"id":"TH-H004-A1588","no":1588,"noLabel":{"th":"มาตรา 1588"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๘๘ หากปรากฏว่าบุคคลที่ศาลตั้งให้เป็นผู้ปกครองเป็นผู้ต้องห้ามมิให้เป็นผู้ปกครองตามมาตรา ๑๕๘๗ อยู่ในขณะที่ศาลตั้งให้เป็นผู้ปกครองโดยปรากฏแก่ศาลเองหรือผู้มีส่วนได้เสียหรืออัยการร้องขอ ให้ศาลสั่งเพิกถอนคำสั่งตั้งผู้ปกครองนั้นเสียและมีคำสั่งเกี่ยวกับผู้ปกครองต่อไปตามที่เห็นสมควร การเพิกถอนคำสั่งตั้งผู้ปกครองตามวรรคหนึ่ง ไม่กระทบกระเทือนสิทธิของบุคคลภายนอกผู้กระทำการโดยสุจริต เว้นแต่ในกรณีการเพิกถอนคำสั่งตั้งผู้ปกครองที่ต้องห้ามตามมาตรา ๑๕๘๗ (๑) หรือ (๒) การกระทำของผู้ปกครองไม่ผูกพันผู้เยาว์ไม่ว่าบุคคลภายนอกจะได้กระทำการโดยสุจริตหรือไม่"}},{"id":"TH-H004-A1589","no":1589,"noLabel":{"th":"มาตรา 1589"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๘๙ (ยกเลิก)"}},{"id":"TH-H004-A1590","no":1590,"noLabel":{"th":"มาตรา 1590"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๐ ผู้ปกครองมีได้คราวหนึ่งเพียงคนเดียว แต่ในกรณีมีข้อกำหนดพินัยกรรมให้ตั้งผู้ปกครองหลายคนหรือเมื่อมีผู้ร้องขอโดยมีเหตุผลอันสมควร ให้ศาลมีอำนาจตั้งผู้ปกครองได้ตามจำนวนที่ศาลเห็นว่าจำเป็น ในกรณีที่ตั้งผู้ปกครองหลายคนศาลจะกำหนดให้ผู้ปกครองเหล่านั้นกระทำการร่วมกันหรือกำหนดอำนาจเฉพาะสำหรับคนหนึ่ง ๆ ก็ได้"}},{"id":"TH-H004-A1591","no":1591,"noLabel":{"th":"มาตรา 1591"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๑ ความเป็นผู้ปกครองนั้นเริ่มแต่วันทราบคำสั่งตั้งของศาล"}},{"id":"TH-H004-A1592","no":1592,"noLabel":{"th":"มาตรา 1592"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๒ ให้ผู้ปกครองรีบทำบัญชีทรัพย์สินของผู้อยู่ในปกครองให้เสร็จภายในสามเดือนนับแต่วันที่ทราบคำสั่งตั้งของศาล แต่ผู้ปกครองจะร้องต่อศาลก่อนสิ้นกำหนดขอให้ยืดเวลาก็ได้ บัญชีนั้นต้องมีพยานรับรองความถูกต้องอย่างน้อยสองคน พยานสองคนนั้นต้องเป็นผู้บรรลุนิติภาวะและเป็นญาติของผู้อยู่ในปกครอง แต่ถ้าหาญาติไม่ได้จะให้ผู้อื่นเป็นพยานก็ได้"}},{"id":"TH-H004-A1593","no":1593,"noLabel":{"th":"มาตรา 1593"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๓ ให้ผู้ปกครองยื่นสำเนาบัญชีทรัพย์สินที่ตนรับรองว่าถูกต้องต่อศาลฉบับหนึ่งภายในสิบวันนับแต่วันที่ได้ทำบัญชีทรัพย์สินแล้ว และศาลจะสั่งให้ผู้ปกครองชี้แจงเพิ่มเติมหรือให้นำเอกสารมาประกอบเพื่อแสดงให้เห็นว่าบัญชีนั้นถูกต้องแล้วก็ได้ ถ้าศาลมิได้มีคำสั่งเป็นอย่างอื่นภายในสิบห้าวันนับแต่วันยื่นบัญชี หรือวันชี้แจงเพิ่มเติม หรือวันนำเอกสารยื่นประกอบ แล้วแต่กรณี ให้ถือว่าศาลยอมรับบัญชีนั้นแล้ว"}},{"id":"TH-H004-A1594","no":1594,"noLabel":{"th":"มาตรา 1594"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๔ ถ้าผู้ปกครองไม่ปฏิบัติเกี่ยวแก่การทำบัญชีทรัพย์สินหรือการยื่นบัญชีทรัพย์สินให้ถูกต้องครบถ้วนตามที่บัญญัติไว้ในมาตรา ๑๕๙๒ หรือมาตรา ๑๕๙๓ หรือไม่ปฏิบัติตามคำสั่งศาลซึ่งสั่งตามมาตรา ๑๕๙๓ หรือศาลไม่พอใจในบัญชีทรัพย์สินเพราะทำขึ้นด้วยความเลินเล่ออย่างร้ายแรงหรือไม่สุจริต หรือเห็นได้ชัดว่าผู้ปกครองหย่อนความสามารถ ศาลจะสั่งถอนผู้ปกครองนั้นเสียก็ได้"}},{"id":"TH-H004-A1595","no":1595,"noLabel":{"th":"มาตรา 1595"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๕ ก่อนที่ศาลยอมรับบัญชีนั้น ห้ามมิให้ผู้ปกครองทำกิจการใด เว้นแต่เป็นการเร่งร้อนและจำเป็น แต่จะยกข้อห้ามดังกล่าวขึ้นเป็นข้อต่อสู้บุคคลภายนอกผู้กระทำการโดยสุจริตและเสียค่าตอบแทนไม่ได้"}},{"id":"TH-H004-A1596","no":1596,"noLabel":{"th":"มาตรา 1596"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๖ ถ้ามีหนี้เป็นคุณแก่ผู้ปกครองแต่เป็นโทษต่อผู้อยู่ในปกครองหรือเป็นคุณแก่ผู้อยู่ในปกครองแต่เป็นโทษต่อผู้ปกครอง ให้ผู้ปกครองแจ้งข้อความเหล่านั้นต่อศาลก่อนลงมือทำบัญชีทรัพย์สิน ถ้าผู้ปกครองรู้ว่ามีหนี้เป็นคุณแก่ตนแต่เป็นโทษต่อผู้อยู่ในปกครอง และมิได้แจ้งข้อความนั้นต่อศาล หนี้ของผู้ปกครองนั้นย่อมสูญไป ถ้าผู้ปกครองรู้ว่ามีหนี้เป็นโทษต่อตน แต่เป็นคุณแก่ผู้อยู่ในปกครอง และมิได้แจ้งข้อความนั้นต่อศาล ศาลจะสั่งถอนผู้ปกครองก็ได้"}},{"id":"TH-H004-A1597","no":1597,"noLabel":{"th":"มาตรา 1597"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๗ เมื่อศาลเห็นสมควรโดยลำพัง หรือเมื่อผู้มีส่วนได้เสียหรืออัยการร้องขอ ศาลอาจสั่งให้ผู้ปกครอง (๑) หาประกันอันสมควรในการจัดการทรัพย์สินของผู้อยู่ในปกครอง ตลอดจนการมอบคืนทรัพย์สินนั้น (๒) แถลงถึงความเป็นอยู่แห่งทรัพย์สินของผู้อยู่ในปกครอง"}},{"id":"TH-H004-A1598","no":1598,"noLabel":{"th":"มาตรา 1598"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘ ในระหว่างปกครอง ถ้าผู้อยู่ในปกครองได้ทรัพย์สินอันมีค่ามาโดยทางมรดกหรือการให้โดยเสน่หา ให้นำมาตรา ๑๕๙๒ ถึงมาตรา ๑๕๙๗ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1598.001","no":1598.001,"noLabel":{"th":"มาตรา 1598/1"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑ ให้ผู้ปกครองทำบัญชีทรัพย์สินส่งต่อศาลปีละครั้งนับแต่วันเป็นผู้ปกครอง แต่เมื่อศาลได้รับบัญชีปีแรกแล้วจะสั่งให้ส่งบัญชีเช่นว่านั้นในระยะเวลาเกินหนึ่งปีก็ได้"}},{"id":"TH-H004-A1598.002","no":1598.002,"noLabel":{"th":"มาตรา 1598/2"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๒ ผู้ปกครองมีสิทธิและหน้าที่เช่นเดียวกับผู้ใช้อำนาจปกครองตามมาตรา ๑๕๖๔ วรรคหนึ่ง และมาตรา ๑๕๖๗"}},{"id":"TH-H004-A1598.003","no":1598.003,"noLabel":{"th":"มาตรา 1598/3"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๓ ผู้ปกครองเป็นผู้แทนโดยชอบธรรมของผู้อยู่ในปกครอง ให้นำมาตรา ๑๕๗๐ มาตรา ๑๕๗๑ มาตรา ๑๕๗๒ มาตรา ๑๕๗๔ มาตรา ๑๕๗๕ มาตรา ๑๕๗๖ และมาตรา ๑๕๗๗ มาใช้บังคับแก่ผู้ปกครองและผู้อยู่ในปกครองโดยอนุโลม"}},{"id":"TH-H004-A1598.004","no":1598.004,"noLabel":{"th":"มาตรา 1598/4"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๔ เงินได้ของผู้อยู่ในปกครองนั้น ผู้ปกครองย่อมใช้ได้ตามสมควรเพื่อการอุปการะเลี้ยงดูและการศึกษาของผู้อยู่ในปกครอง ถ้ามีเหลือให้ใช้เพื่อแสวงหาผลประโยชน์เฉพาะในเรื่องต่อไปนี้ (๑) ซื้อพันธบัตรรัฐบาลไทยหรือพันธบัตรที่รัฐบาลไทยค้ำประกัน (๒) รับขายฝากหรือรับจำนองอสังหาริมทรัพย์ในลำดับแรก แต่จำนวนเงินที่รับขายฝากหรือรับจำนองต้องไม่เกินกึ่งราคาตลาดของอสังหาริมทรัพย์นั้น (๓) ฝากประจำในธนาคารที่ได้ตั้งขึ้นโดยกฎหมายหรือที่ได้รับอนุญาตให้ประกอบกิจการในราชอาณาจักร (๔) ลงทุนอย่างอื่นซึ่งศาลอนุญาตเป็นพิเศษ"}},{"id":"TH-H004-A1598.005","no":1598.005,"noLabel":{"th":"มาตรา 1598/5"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๕ ถ้าผู้อยู่ในปกครองรู้จักผิดชอบและมีอายุไม่ต่ำกว่าสิบห้าปีบริบูรณ์เมื่อผู้ปกครองจะทำกิจการใดที่สำคัญ ให้ปรึกษาหารือผู้อยู่ในปกครองก่อนเท่าที่จะทำได้ การที่ผู้อยู่ในปกครองได้ยินยอมด้วยนั้นหาคุ้มผู้ปกครองให้พ้นจากความรับผิดไม่"}},{"id":"TH-H004-A1598.006","no":1598.006,"noLabel":{"th":"มาตรา 1598/6"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๖ ความปกครองสิ้นสุดลงเมื่อผู้อยู่ในปกครองตายหรือบรรลุนิติภาวะ"}},{"id":"TH-H004-A1598.007","no":1598.007,"noLabel":{"th":"มาตรา 1598/7"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๗ ความเป็นผู้ปกครองสิ้นสุดลงเมื่อผู้ปกครอง (๑) ตาย (๒) ลาออกโดยได้รับอนุญาตจากศาล (๓) เป็นคนไร้ความสามารถหรือเสมือนไร้ความสามารถ (๔) เป็นบุคคลล้มละลาย (๕) ถูกถอนโดยคำสั่งศาล"}},{"id":"TH-H004-A1598.008","no":1598.008,"noLabel":{"th":"มาตรา 1598/8"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๘ ให้ศาลสั่งถอนผู้ปกครองในกรณี ดังต่อไปนี้ (๑) ผู้ปกครองละเลยไม่กระทำการตามหน้าที่ (๒) ผู้ปกครองประมาทเลินเล่ออย่างร้ายแรงในหน้าที่ (๓) ผู้ปกครองใช้อำนาจหน้าที่โดยมิชอบ (๔) ผู้ปกครองประพฤติมิชอบซึ่งไม่สมควรแก่หน้าที่ (๕) ผู้ปกครองหย่อนความสามารถในหน้าที่จนน่าจะเป็นอันตรายแก่ประโยชน์ของผู้อยู่ในปกครอง (๖) มีกรณีดังบัญญัติไว้ในมาตรา ๑๕๘๗ (๓) (๔) หรือ (๕)"}},{"id":"TH-H004-A1598.009","no":1598.009,"noLabel":{"th":"มาตรา 1598/9"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๙ การร้องขอให้ถอนผู้ปกครองตามมาตรา ๑๕๙๘/๘ นั้น ผู้อยู่ในปกครองซึ่งมีอายุไม่ต่ำกว่าสิบห้าปีบริบูรณ์ หรือญาติของผู้อยู่ในปกครองหรืออัยการจะเป็นผู้ร้องขอก็ได้"}},{"id":"TH-H004-A1598.01","no":1598.01,"noLabel":{"th":"มาตรา 1598/10"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๐ ในระหว่างพิจารณาคำร้องขอให้ถอนผู้ปกครอง ศาลจะตั้งผู้จัดการชั่วคราวให้จัดการทรัพย์สินของผู้อยู่ในปกครองแทนผู้ปกครองก็ได้"}},{"id":"TH-H004-A1598.011","no":1598.011,"noLabel":{"th":"มาตรา 1598/11"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๑ ถ้าความปกครองหรือความเป็นผู้ปกครองสิ้นสุดลง ให้ผู้ปกครองหรือทายาทรีบส่งมอบทรัพย์สินที่จัดการแก่ผู้อยู่ในปกครอง หรือทายาทหรือผู้ปกครองคนใหม่ และให้ทำบัญชีในการจัดการทรัพย์สินส่งมอบภายในเวลาหกเดือน และถ้ามีเอกสารเกี่ยวกับเรื่องจัดการทรัพย์สินนั้นก็ให้ส่งมอบพร้อมกับบัญชี แต่เมื่อผู้ปกครองหรือทายาทร้องขอศาลจะสั่งให้ยืดเวลาก็ได้ ให้นำมาตรา ๑๕๘๐ และมาตรา ๑๕๘๑ มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1598.012","no":1598.012,"noLabel":{"th":"มาตรา 1598/12"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๒ นับแต่วันส่งมอบบัญชี ให้เริ่มคิดดอกเบี้ยในจำนวนเงินซึ่งผู้ปกครองหรือผู้อยู่ในปกครองจะต้องคืนให้แก่กัน ถ้าผู้ปกครองใช้เงินของผู้อยู่ในปกครองนอกจากเพื่อประโยชน์ของผู้อยู่ในปกครองแล้ว ให้เสียดอกเบี้ยร้อยละสิบห้าต่อปีในจำนวนเงินนั้นตั้งแต่วันใช้เป็นต้นไป"}},{"id":"TH-H004-A1598.013","no":1598.013,"noLabel":{"th":"มาตรา 1598/13"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๓ ผู้อยู่ในปกครองมีบุริมสิทธิเหนือทรัพย์สินทั้งหมดของผู้ปกครองเพื่อชำระหนี้ซึ่งค้างอยู่แก่ตน บุริมสิทธินี้ให้อยู่ในลำดับที่หกถัดจากบุริมสิทธิสามัญอย่างอื่นตามมาตรา ๒๕๓ แห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A1598.014","no":1598.014,"noLabel":{"th":"มาตรา 1598/14"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๔ ผู้ปกครองไม่มีสิทธิได้รับบำเหน็จ เว้นแต่ในกรณีต่อไปนี้ (๑) มีข้อกำหนดไว้ในพินัยกรรมให้ผู้ปกครองได้รับบำเหน็จ ในกรณีเช่นว่านี้ ให้ผู้ปกครองได้รับบำเหน็จเท่าที่กำหนดในพินัยกรรม (๒) ในกรณีที่พินัยกรรมไม่ได้กำหนดบำเหน็จไว้ แต่ไม่มีข้อกำหนดห้ามผู้ปกครองรับบำเหน็จ ผู้ปกครองจะร้องขอต่อศาลให้กำหนดบำเหน็จในภายหลังก็ได้ ศาลจะกำหนดให้หรือไม่เพียงใดก็ได้ (๓) ในกรณีที่ไม่มีคำสั่งตั้งผู้ปกครองไว้ในพินัยกรรม และไม่มีข้อกำหนดห้ามผู้ปกครองรับบำเหน็จ ศาลจะกำหนดบำเหน็จให้แก่ผู้ปกครองในคำสั่งตั้งผู้ปกครองก็ได้ หรือถ้าศาลมิได้กำหนด ผู้ปกครองจะร้องขอต่อศาลให้กำหนดบำเหน็จในภายหลังก็ได้ ศาลจะกำหนดให้หรือไม่เพียงใดก็ได้ ในการพิจารณากำหนดบำเหน็จ ให้ศาลพิเคราะห์ถึงพฤติการณ์ รายได้และฐานะความเป็นอยู่ของผู้ปกครองและผู้อยู่ในปกครอง ถ้าผู้ปกครองหรือผู้อยู่ในปกครองแสดงได้ว่า พฤติการณ์รายได้หรือฐานะความเป็นอยู่ของผู้ปกครองหรือผู้อยู่ในปกครองได้เปลี่ยนแปลงไปภายหลังที่ได้เข้ารับหน้าที่ผู้ปกครอง ศาลจะสั่งให้บำเหน็จ งด ลด เพิ่ม หรือกลับให้บำเหน็จแก่ผู้ปกครองอีกก็ได้ แล้วแต่กรณี ทั้งนี้ ให้ใช้บังคับแก่กรณีที่มีข้อกำหนดห้ามไว้ในพินัยกรรมมิให้ผู้ปกครองได้รับบำเหน็จด้วย"}},{"id":"TH-H004-A1598.015","no":1598.015,"noLabel":{"th":"มาตรา 1598/15"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๕ ในกรณีที่ศาลสั่งให้คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นคนไร้ความสามารถและคู่สมรสอีกฝ่ายเป็นผู้อนุบาล ให้นำบทบัญญัติว่าด้วยสิทธิและหน้าที่ของผู้ใช้อำนาจปกครองมาใช้บังคับโดยอนุโลม เว้นแต่สิทธิตามมาตรา ๑๕๖๗ (๒) และ (๓)"}},{"id":"TH-H004-A1598.016","no":1598.016,"noLabel":{"th":"มาตรา 1598/16"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๖ คู่สมรสซึ่งเป็นผู้อนุบาลของคู่สมรสที่ถูกศาลสั่งให้เป็นคนไร้ความสามารถมีอำนาจจัดการสินส่วนตัวของคู่สมรสอีกฝ่ายหนึ่งและมีอำนาจจัดการสินสมรสแต่ผู้เดียว แต่การจัดการสินส่วนตัวและสินสมรสตามกรณีที่ระบุไว้ในมาตรา ๑๔๗๖ วรรคหนึ่ง คู่สมรสนั้นจะจัดการไม่ได้ เว้นแต่จะได้รับอนุญาตจากศาล"}},{"id":"TH-H004-A1598.017","no":1598.017,"noLabel":{"th":"มาตรา 1598/17"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๗ ในกรณีที่ศาลสั่งให้คู่สมรสฝ่ายใดฝ่ายหนึ่งเป็นคนไร้ความสามารถและศาลเห็นไม่สมควรให้คู่สมรสอีกฝ่ายเป็นผู้อนุบาล และตั้งบิดาหรือมารดาหรือบุคคลภายนอกเป็นผู้อนุบาล ในกรณีเช่นว่านี้ ให้ผู้อนุบาลเป็นผู้จัดการสินสมรสร่วมกันกับคู่สมรสอีกฝ่ายหนึ่ง เว้นแต่ถ้ามีเหตุสำคัญอันจะเกิดความเสียหายแก่คนไร้ความสามารถ ศาลจะสั่งเป็นอย่างอื่นก็ได้ อย่างไรก็ตาม เมื่อมีกรณีดังกล่าวตามวรรคหนึ่ง คู่สมรสอีกฝ่ายหนึ่งมีสิทธิร้องขอต่อศาลให้สั่งแยกสินสมรสได้"}},{"id":"TH-H004-A1598.018","no":1598.018,"noLabel":{"th":"มาตรา 1598/18"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๕๙๘/๑๘ ในกรณีที่บิดามารดาเป็นผู้อนุบาลบุตร ถ้าบุตรนั้นยังไม่บรรลุนิติภาวะ ให้นำบทบัญญัติว่าด้วยสิทธิและหน้าที่ของผู้ใช้อำนาจปกครองมาใช้บังคับโดยอนุโลม แต่ถ้าบุตรนั้นบรรลุนิติภาวะแล้ว ให้นำบทบัญญัติว่าด้วยสิทธิและหน้าที่ของผู้ปกครองมาใช้บังคับโดยอนุโลม เว้นแต่สิทธิตามมาตรา ๑๕๖๗ (๒) และ (๓) ในกรณีที่บุคคลอื่นซึ่งมิใช่บิดามารดาหรือมิใช่คู่สมรสเป็นผู้อนุบาล ให้นำบทบัญญัติว่าด้วยสิทธิและหน้าที่ของผู้ปกครองมาใช้บังคับโดยอนุโลม แต่ถ้าผู้อยู่ในความอนุบาลบรรลุนิติภาวะแล้วจะใช้สิทธิตามมาตรา ๑๕๖๗ (๒) และ (๓) ไม่ได้"}},{"id":"TH-H004-A1598.019","no":1598.019,"noLabel":{"th":"มาตรา 1598/19"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๑๙ บุคคลที่มีอายุไม่ต่ำกว่ายี่สิบห้าปีจะรับบุคคลอื่นเป็นบุตรบุญธรรมก็ได้ แต่ผู้นั้นต้องมีอายุแก่กว่าผู้ที่จะเป็นบุตรบุญธรรมอย่างน้อยสิบห้าปี"}},{"id":"TH-H004-A1598.02","no":1598.02,"noLabel":{"th":"มาตรา 1598/20"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๐ การรับบุตรบุญธรรม ถ้าผู้ที่จะเป็นบุตรบุญธรรมมีอายุไม่ต่ำกว่าสิบห้าปี ผู้นั้นต้องให้ความยินยอมด้วย"}},{"id":"TH-H004-A1598.021","no":1598.021,"noLabel":{"th":"มาตรา 1598/21"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๑ การรับผู้เยาว์เป็นบุตรบุญธรรมจะกระทำได้ต่อเมื่อได้รับความยินยอมของบิดาและมารดาของผู้จะเป็นบุตรบุญธรรม ในกรณีที่บิดาหรือมารดาคนใดคนหนึ่งตายหรือถูกถอนอำนาจปกครองต้องได้รับความยินยอมของมารดาหรือบิดาซึ่งยังมีอำนาจปกครอง ถ้าไม่มีผู้มีอำนาจให้ความยินยอมดังกล่าวในวรรคหนึ่ง หรือมีแต่บิดาหรือมารดาคนใดคนหนึ่งหรือทั้งสองคนไม่สามารถแสดงเจตนาให้ความยินยอมได้หรือไม่ให้ความยินยอมและการไม่ให้ความยินยอมนั้นปราศจากเหตุผลอันสมควรและเป็นปฏิปักษ์ต่อสุขภาพความเจริญหรือสวัสดิภาพของผู้เยาว์ มารดาหรือบิดาหรือผู้ประสงค์จะขอรับบุตรบุญธรรมหรืออัยการจะร้องขอต่อศาลให้มีคำสั่งอนุญาตแทนการให้ความยินยอมตามวรรคหนึ่งก็ได้"}},{"id":"TH-H004-A1598.022","no":1598.022,"noLabel":{"th":"มาตรา 1598/22"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๒ ในการรับผู้เยาว์เป็นบุตรบุญธรรม ถ้าผู้เยาว์เป็นผู้ถูกทอดทิ้งและอยู่ในความดูแลของสถานสงเคราะห์เด็กตามกฎหมายว่าด้วยการสงเคราะห์และคุ้มครองเด็ก ให้สถานสงเคราะห์เด็กเป็นผู้ให้ความยินยอมแทนบิดาและมารดา ถ้าสถานสงเคราะห์เด็กไม่ให้ความยินยอม ให้นำความในมาตรา ๑๕๙๘/๒๑ วรรคสอง มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1598.023","no":1598.023,"noLabel":{"th":"มาตรา 1598/23"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๓ ในกรณีที่ผู้เยาว์มิได้ถูกทอดทิ้งแต่อยู่ในความอุปการะเลี้ยงดูของสถานสงเคราะห์เด็กตามกฎหมายว่าด้วยการสงเคราะห์และคุ้มครองเด็กบิดาและมารดา หรือบิดาหรือมารดาในกรณีที่มารดาหรือบิดาคนใดคนหนึ่งตายหรือถูกถอนอำนาจปกครอง จะทำหนังสือมอบอำนาจให้สถานสงเคราะห์เด็กดังกล่าวเป็นผู้มีอำนาจให้ความยินยอมในการรับผู้เยาว์เป็นบุตรบุญธรรมแทนตนก็ได้ ในกรณีเช่นนั้นให้นำความในมาตรา ๑๕๙๘/๒๒ มาใช้บังคับโดยอนุโลม หนังสือมอบอำนาจตามวรรคหนึ่งจะถอนเสียมิได้ตราบเท่าที่ผู้เยาว์ยังอยู่ในความอุปการะเลี้ยงดูของสถานสงเคราะห์เด็กนั้น"}},{"id":"TH-H004-A1598.024","no":1598.024,"noLabel":{"th":"มาตรา 1598/24"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๔ ผู้มีอำนาจให้ความยินยอมแทนสถานสงเคราะห์เด็กในการรับบุตรบุญธรรมตามมาตรา ๑๕๙๘/๒๒ หรือมาตรา ๑๕๙๘/๒๓ จะรับผู้เยาว์ซึ่งอยู่ในความดูแลหรืออยู่ในความอุปการะเลี้ยงดูของสถานสงเคราะห์เด็กนั้นเป็นบุตรบุญธรรมของตนเองได้ต่อเมื่อศาลได้มีคำสั่งอนุญาตตามคำขอของผู้นั้นแทนการให้ความยินยอมของสถานสงเคราะห์เด็ก"}},{"id":"TH-H004-A1598.025","no":1598.025,"noLabel":{"th":"มาตรา 1598/25"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๕ ผู้จะรับบุตรบุญธรรมหรือผู้จะเป็นบุตรบุญธรรม ถ้ามีคู่สมรสอยู่ต้องได้รับความยินยอมจากคู่สมรสก่อน ในกรณีที่คู่สมรสไม่อาจให้ความยินยอมได้หรือไปเสียจากภูมิลำเนาหรือถิ่นที่อยู่และหาตัวไม่พบเป็นเวลาไม่น้อยกว่าหนึ่งปี ต้องร้องขอต่อศาลให้มีคำสั่งอนุญาตแทนการให้ความยินยอมของคู่สมรสนั้น"}},{"id":"TH-H004-A1598.026","no":1598.026,"noLabel":{"th":"มาตรา 1598/26"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๖ ผู้เยาว์ที่เป็นบุตรบุญธรรมของบุคคลใดอยู่จะเป็นบุตรบุญธรรมของบุคคลอื่นอีกในขณะเดียวกันไม่ได้ เว้นแต่เป็นบุตรบุญธรรมของคู่สมรสของผู้รับบุตรบุญธรรม ถ้าคู่สมรสฝ่ายหนึ่งจะจดทะเบียนรับผู้เยาว์ซึ่งเป็นบุตรบุญธรรมของคู่สมรสอีกฝ่ายหนึ่งเป็นบุตรบุญธรรมของตนด้วยจะต้องได้รับความยินยอมของคู่สมรสซึ่งเป็นผู้รับบุตรบุญธรรมอยู่แล้ว และมิให้นำมาตรา ๑๕๙๘/๒๑ มาใช้บังคับ"}},{"id":"TH-H004-A1598.027","no":1598.027,"noLabel":{"th":"มาตรา 1598/27"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๗ การรับบุตรบุญธรรมจะสมบูรณ์ต่อเมื่อได้จดทะเบียนตามกฎหมาย แต่ถ้าผู้จะเป็นบุตรบุญธรรมนั้นเป็นผู้เยาว์ต้องปฏิบัติตามกฎหมายว่าด้วยการรับเด็กเป็นบุตรบุญธรรมก่อน"}},{"id":"TH-H004-A1598.028","no":1598.028,"noLabel":{"th":"มาตรา 1598/28"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๘ บุตรบุญธรรมย่อมมีฐานะอย่างเดียวกับบุตรชอบด้วยกฎหมายของผู้รับบุตรบุญธรรมนั้น แต่ไม่สูญสิทธิและหน้าที่ในครอบครัวที่ได้กำเนิดมา ในกรณีเช่นนี้ ให้บิดามารดาโดยกำเนิดหมดอำนาจปกครองนับแต่วันเวลาที่เด็กเป็นบุตรบุญธรรมแล้ว ให้นำบทบัญญัติในลักษณะ ๒ หมวด ๒ แห่งบรรพนี้มาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1598.029","no":1598.029,"noLabel":{"th":"มาตรา 1598/29"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๒๙ การรับบุตรบุญธรรมไม่ก่อให้เกิดสิทธิรับมรดกของบุตรบุญธรรมในฐานะทายาทโดยธรรมเพราะเหตุการรับบุตรบุญธรรมนั้น"}},{"id":"TH-H004-A1598.03","no":1598.03,"noLabel":{"th":"มาตรา 1598/30"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๐ ถ้าบุตรบุญธรรมซึ่งไม่มีคู่สมรสหรือผู้สืบสันดานตายก่อนผู้รับบุตรบุญธรรม ผู้รับบุตรบุญธรรมมีสิทธิเรียกร้องเอาทรัพย์สินที่ตนได้ให้แก่บุตรบุญธรรมคืนจากกองมรดกของบุตรบุญธรรมเพียงเท่าที่ทรัพย์สินนั้นยังคงเหลืออยู่ภายหลังที่ชำระหนี้ของกองมรดกเสร็จสิ้นแล้ว ห้ามมิให้ฟ้องคดีเรียกร้องสิทธิตามวรรคหนึ่ง เมื่อพ้นกำหนดหนึ่งปีนับแต่เวลาที่ผู้รับบุตรบุญธรรมได้รู้หรือควรได้รู้ถึงความตายของบุตรบุญธรรมหรือเมื่อพ้นกำหนดสิบปี นับแต่วันที่บุตรบุญธรรมตาย"}},{"id":"TH-H004-A1598.031","no":1598.031,"noLabel":{"th":"มาตรา 1598/31"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๑ การเลิกรับบุตรบุญธรรม ถ้าบุตรบุญธรรมบรรลุนิติภาวะแล้วจะเลิกโดยความตกลงกันในระหว่างผู้รับบุตรบุญธรรมกับบุตรบุญธรรมเมื่อใดก็ได้ ถ้าบุตรบุญธรรมยังไม่บรรลุนิติภาวะ การเลิกรับบุตรบุญธรรมจะทำได้ต่อเมื่อได้รับความยินยอมของบิดาและมารดา และให้นำมาตรา ๑๕๙๘/๒๐ และมาตรา ๑๕๙๘/๒๑ มาใช้บังคับโดยอนุโลม ในกรณีที่ได้รับผู้เยาว์เป็นบุตรบุญธรรมตามมาตรา ๑๕๙๘/๒๑ วรรคสอง มาตรา ๑๕๙๘/๒๒ มาตรา ๑๕๙๘/๒๓ มาตรา ๑๕๙๘/๒๔ หรือมาตรา ๑๕๙๘/๒๖ วรรคสอง ถ้าบุตรบุญธรรมยังไม่บรรลุนิติภาวะ การเลิกรับบุตรบุญธรรมให้กระทำได้ต่อเมื่อมีคำสั่งศาลโดยคำร้องขอของผู้มีส่วนได้เสียหรืออัยการ การเลิกรับบุตรบุญธรรมจะสมบูรณ์ต่อเมื่อได้จดทะเบียนตามกฎหมาย"}},{"id":"TH-H004-A1598.032","no":1598.032,"noLabel":{"th":"มาตรา 1598/32"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๒ การรับบุตรบุญธรรมย่อมเป็นอันยกเลิก เมื่อมีการสมรสฝ่าฝืนมาตรา ๑๔๕๑"}},{"id":"TH-H004-A1598.033","no":1598.033,"noLabel":{"th":"มาตรา 1598/33"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๓ คดีฟ้องเลิกการรับบุตรบุญธรรมนั้นเมื่อ (๑) ฝ่ายหนึ่งทำการชั่วร้ายไม่ว่าจะเป็นความผิดอาญาหรือไม่ เป็นเหตุให้อีกฝ่ายหนึ่งอับอายขายหน้าอย่างร้ายแรง หรือถูกเกลียดชัง หรือได้รับความเสียหายหรือเดือดร้อนเกินควร อีกฝ่ายหนึ่งฟ้องเลิกได้ (๒) ฝ่ายหนึ่งหมิ่นประมาทหรือเหยียดหยามอีกฝ่ายหนึ่งหรือบุพการีของอีกฝ่ายหนึ่งอันเป็นการร้ายแรง อีกฝ่ายหนึ่งฟ้องเลิกได้ ถ้าบุตรบุญธรรมกระทำการดังกล่าวต่อคู่สมรสของผู้รับบุตรบุญธรรม ให้ผู้รับบุตรบุญธรรมฟ้องเลิกได้ (๓) ฝ่ายหนึ่งกระทำการประทุษร้ายอีกฝ่ายหนึ่งหรือบุพการีหรือคู่สมรสของอีกฝ่ายหนึ่งเป็นเหตุให้เกิดอันตรายแก่กายหรือจิตใจอย่างร้ายแรงและการกระทำนั้นเป็นความผิดที่มีโทษอาญา อีกฝ่ายหนึ่งฟ้องเลิกได้ (๔) ฝ่ายหนึ่งไม่อุปการะเลี้ยงดูอีกฝ่ายหนึ่ง อีกฝ่ายหนึ่งนั้นฟ้องเลิกได้ (๕) ฝ่ายหนึ่งจงใจละทิ้งอีกฝ่ายหนึ่งไปเกินหนึ่งปี อีกฝ่ายหนึ่งนั้นฟ้องเลิกได้ (๖) ฝ่ายหนึ่งต้องคำพิพากษาถึงที่สุดให้จำคุกเกินสามปี เว้นแต่ความผิดที่กระทำโดยประมาท อีกฝ่ายหนึ่งฟ้องเลิกได้ (๗) ผู้รับบุตรบุญธรรมทำผิดหน้าที่บิดามารดา และการกระทำนั้นเป็นการละเมิดหรือไม่ปฏิบัติตามมาตรา ๑๕๖๔ มาตรา ๑๕๗๑ มาตรา ๑๕๗๓ มาตรา ๑๕๗๔ หรือมาตรา ๑๕๗๕ เป็นเหตุให้เกิดหรืออาจเกิดความเสียหายอย่างร้ายแรงต่อบุตรบุญธรรม บุตรบุญธรรมฟ้องเลิกได้ (๘) ผู้รับบุตรบุญธรรมผู้ใดถูกถอนอำนาจปกครองบางส่วนหรือทั้งหมด และเหตุที่ถูกถอนอำนาจปกครองนั้นมีพฤติการณ์แสดงให้เห็นว่า ผู้นั้นไม่สมควรเป็นผู้รับบุตรบุญธรรมต่อไป บุตรบุญธรรมฟ้องเลิกได้ (๙) (ยกเลิก)"}},{"id":"TH-H004-A1598.034","no":1598.034,"noLabel":{"th":"มาตรา 1598/34"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๔ ห้ามมิให้ฟ้องขอเลิกการรับบุตรบุญธรรมเมื่อพ้นกำหนดหนึ่งปีนับแต่วันที่ผู้ขอเลิกการรับบุตรบุญธรรมรู้หรือควรได้รู้ข้อเท็จจริงอันเป็นเหตุให้เลิกการนั้น หรือเมื่อพ้นกำหนดสิบปีนับแต่เหตุนั้นเกิดขึ้น"}},{"id":"TH-H004-A1598.035","no":1598.035,"noLabel":{"th":"มาตรา 1598/35"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๕ การฟ้องเลิกการรับบุตรบุญธรรม ถ้าบุตรบุญธรรมมีอายุไม่ครบสิบห้าปีบริบูรณ์ให้บิดามารดาโดยกำเนิดเป็นผู้มีอำนาจฟ้องแทน แต่ถ้าบุตรบุญธรรมมีอายุสิบห้าปีบริบูรณ์แล้วบุตรบุญธรรมฟ้องได้โดยไม่ต้องได้รับความยินยอมจากผู้ใด ในกรณีตามวรรคหนึ่ง อัยการจะฟ้องคดีแทนบุตรบุญธรรมก็ได้"}},{"id":"TH-H004-A1598.036","no":1598.036,"noLabel":{"th":"มาตรา 1598/36"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๖ การเลิกรับบุตรบุญธรรมโดยคำพิพากษาของศาล ย่อมมีผลแต่เวลาที่คำพิพากษาถึงที่สุด แต่จะอ้างเป็นเหตุเสื่อมสิทธิของบุคคลภายนอกผู้ทำการโดยสุจริตไม่ได้ เว้นแต่ได้จดทะเบียนแล้ว"}},{"id":"TH-H004-A1598.037","no":1598.037,"noLabel":{"th":"มาตรา 1598/37"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๕๙๘/๓๗ เมื่อผู้รับบุตรบุญธรรมตายหรือมีการเลิกรับบุตรบุญธรรม ถ้าบุตรบุญธรรมยังไม่บรรลุนิติภาวะ ให้บิดามารดาโดยกำเนิดกลับมีอำนาจปกครองนับแต่เวลาที่ผู้รับบุตรบุญธรรมตายหรือนับแต่เวลาที่จดทะเบียนเลิกการรับบุตรบุญธรรมตามมาตรา ๑๕๙๘/๓๑ หรือนับแต่เวลาที่ศาลมีคำพิพากษาถึงที่สุดให้เลิกการรับบุตรบุญธรรม เว้นแต่ศาลเห็นสมควรสั่งเป็นประการอื่น ในกรณีที่มีการตั้งผู้ปกครองของผู้เป็นบุตรบุญธรรมไว้ก่อนผู้รับบุตรบุญธรรมตาย หรือก่อนการเลิกรับบุตรบุญธรรม ให้ผู้ปกครองยังคงมีอำนาจหน้าที่เช่นเดิมต่อไป เว้นแต่บิดามารดาโดยกำเนิดจะร้องขอ และศาลมีคำสั่งให้ผู้ร้องขอเป็นผู้มีอำนาจปกครอง การเปลี่ยนผู้ใช้อำนาจปกครองตามวรรคหนึ่งหรือผู้ปกครองตามวรรคสองไม่เป็นเหตุเสื่อมสิทธิที่บุคคลภายนอกได้มาโดยสุจริตก่อนผู้รับบุตรบุญธรรมตายหรือก่อนจดทะเบียนเลิกการรับบุตรบุญธรรม ให้พนักงานอัยการเป็นผู้มีอำนาจร้องขอเพื่อให้ศาลมีคำสั่งเป็นประการอื่นตามวรรคหนึ่ง"}},{"id":"TH-H004-A1598.038","no":1598.038,"noLabel":{"th":"มาตรา 1598/38"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๕๙๘/๓๘ ค่าอุปการะเลี้ยงดูระหว่างคู่สมรส หรือระหว่างบิดามารดากับบุตรนั้น ย่อมเรียกจากกันได้ในเมื่อฝ่ายที่ควรได้รับอุปการะเลี้ยงดูไม่ได้รับการอุปการะเลี้ยงดูหรือได้รับการอุปการะเลี้ยงดูไม่เพียงพอแก่อัตภาพ ค่าอุปการะเลี้ยงดูนี้ศาลอาจให้เพียงใดหรือไม่ให้ก็ได้ โดยคำนึงถึงความสามารถของผู้มีหน้าที่ต้องให้ ฐานะของผู้รับและพฤติการณ์แห่งกรณี"}},{"id":"TH-H004-A1598.039","no":1598.039,"noLabel":{"th":"มาตรา 1598/39"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๕๙๘/๓๙ เมื่อผู้มีส่วนได้เสียแสดงว่าพฤติการณ์รายได้ หรือฐานะของคู่กรณีได้เปลี่ยนแปลงไป ศาลจะสั่งแก้ไขในเรื่องค่าอุปการะเลี้ยงดูโดยให้เพิกถอน ลด เพิ่ม หรือกลับให้ค่าอุปการะเลี้ยงดูอีกก็ได้ ในกรณีที่ศาลไม่พิพากษาให้ค่าอุปการะเลี้ยงดู เพราะเหตุแต่เพียงอีกฝ่ายหนึ่งไม่อยู่ในฐานะที่จะให้ค่าอุปการะเลี้ยงดูได้ในขณะนั้น หากพฤติการณ์ รายได้ หรือฐานะของอีกฝ่ายหนึ่งนั้นได้เปลี่ยนแปลงไป และพฤติการณ์รายได้หรือฐานะของผู้เรียกร้องอยู่ในสภาพที่ควรได้รับค่าอุปการะเลี้ยงดู ผู้เรียกร้องอาจร้องขอให้ศาลเปลี่ยนแปลงคำสั่งในคดีนั้นใหม่ได้"}},{"id":"TH-H004-A1598.04","no":1598.04,"noLabel":{"th":"มาตรา 1598/40"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๕๙๘/๔๐ ค่าอุปการะเลี้ยงดูนั้นให้ชำระเป็นเงิน โดยวิธีชำระเป็นครั้งคราวตามกำหนด เว้นแต่คู่กรณีจะตกลงกันให้ชำระเป็นอย่างอื่นหรือโดยวิธีอื่น ถ้าไม่มีการตกลงกันและมีเหตุพิเศษ เมื่อฝ่ายใดฝ่ายหนึ่งร้องขอและศาลเห็นสมควร จะกำหนดให้ค่าอุปการะเลี้ยงดูเป็นอย่างอื่นหรือโดยวิธีอื่น โดยจะให้ชำระเป็นเงินด้วยหรือไม่ก็ได้ ในกรณีขอค่าอุปการะเลี้ยงดูบุตร เมื่อมีเหตุพิเศษและศาลเห็นเป็นการสมควรเพื่อประโยชน์แก่บุตร จะกำหนดให้บุตรได้รับการอุปการะเลี้ยงดูโดยประการใด ๆ นอกจากที่คู่กรณีตกลงกัน หรือนอกจากที่ฝ่ายใดฝ่ายหนึ่งร้องขอก็ได้ เช่นให้ไปอยู่ในสถานการศึกษาหรือวิชาชีพ โดยให้ผู้ที่มีหน้าที่ต้องชำระค่าอุปการะเลี้ยงดูออกค่าใช้จ่ายในการนี้"}},{"id":"TH-H004-A1598.041","no":1598.041,"noLabel":{"th":"มาตรา 1598/41"},"chapter":{"th":"ลักษณะ 3"},"text":{"th":"มาตรา ๑๕๙๘/๔๑ สิทธิที่จะได้ค่าอุปการะเลี้ยงดูนั้น จะสละหรือโอนมิได้และไม่อยู่ในข่ายแห่งการบังคับคดี"}},{"id":"TH-H004-A1599","no":1599,"noLabel":{"th":"มาตรา 1599"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๕๙๙ เมื่อบุคคลใดตาย มรดกของบุคคลนั้นตกทอดแก่ทายาท ทายาทอาจเสียไปซึ่งสิทธิในมรดกได้แต่โดยบทบัญญัติแห่งประมวลกฎหมายนี้หรือกฎหมายอื่น"}},{"id":"TH-H004-A1600","no":1600,"noLabel":{"th":"มาตรา 1600"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๐๐ ภายใต้บังคับของบทบัญญัติแห่งประมวลกฎหมายนี้ กองมรดกของผู้ตายได้แก่ทรัพย์สินทุกชนิดของผู้ตาย ตลอดทั้งสิทธิหน้าที่และความรับผิดต่าง ๆ เว้นแต่ตามกฎหมายหรือว่าโดยสภาพแล้ว เป็นการเฉพาะตัวของผู้ตายโดยแท้"}},{"id":"TH-H004-A1601","no":1601,"noLabel":{"th":"มาตรา 1601"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๐๑ ทายาทไม่จำต้องรับผิดเกินกว่าทรัพย์มรดกที่ตกทอดได้แก่ตน"}},{"id":"TH-H004-A1602","no":1602,"noLabel":{"th":"มาตรา 1602"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๐๒ เมื่อบุคคลใดต้องถือว่าถึงแก่ความตายตามความในมาตรา ๖๒ แห่งประมวลกฎหมายนี้ มรดกของบุคคลนั้นตกทอดแก่ทายาท ถ้าพิสูจน์ได้ว่าบุคคลนั้นยังคงมีชีวิตอยู่ หรือตายในเวลาอื่นผิดไปจากเวลาดังระบุไว้ในคำสั่งที่สั่งให้เป็นคนสาบสูญ ให้ใช้บทบัญญัติมาตรา ๖๓ แห่งประมวลกฎหมายนี้บังคับแก่ทายาทของบุคคลนั้น"}},{"id":"TH-H004-A1603","no":1603,"noLabel":{"th":"มาตรา 1603"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๐๓ กองมรดกย่อมตกทอดแก่ทายาทโดยสิทธิตามกฎหมายหรือโดยพินัยกรรม ทายาทที่มีสิทธิตามกฎหมาย เรียกว่า “ทายาทโดยธรรม” ทายาทที่มีสิทธิตามพินัยกรรม เรียกว่า “ผู้รับพินัยกรรม”"}},{"id":"TH-H004-A1604","no":1604,"noLabel":{"th":"มาตรา 1604"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๐๔ บุคคลธรรมดาจะเป็นทายาทได้ก็ต่อเมื่อมีสภาพบุคคลหรือสามารถมีสิทธิได้ตามมาตรา ๑๕ แห่งประมวลกฎหมายนี้ ในเวลาที่เจ้ามรดกถึงแก่ความตาย เพื่อประโยชน์แห่งมาตรานี้ ให้ถือว่าเด็กที่เกิดมารอดอยู่ภายในสามร้อยสิบวันนับแต่เวลาที่เจ้ามรดกถึงแก่ความตายนั้น เป็นทารกในครรภ์มารดาอยู่ในเวลาที่เจ้ามรดกถึงแก่ความตาย"}},{"id":"TH-H004-A1605","no":1605,"noLabel":{"th":"มาตรา 1605"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๐๕ ทายาทคนใดยักย้าย หรือปิดบังทรัพย์มรดกเท่าส่วนที่ตนจะได้หรือมากกว่านั้นโดยฉ้อฉลหรือรู้อยู่ว่า ตนทำให้เสื่อมประโยชน์ของทายาทคนอื่น ทายาทคนนั้นต้องถูกกำจัดมิให้ได้มรดกเลย แต่ถ้าได้ยักย้ายหรือปิดบังทรัพย์มรดกน้อยกว่าส่วนที่ตนจะได้ ทายาทคนนั้นต้องถูกกำจัดมิให้ได้มรดกเฉพาะส่วนที่ได้ยักย้ายหรือปิดบังไว้นั้น มาตรานี้มิให้ใช้บังคับแก่ผู้รับพินัยกรรม ซึ่งผู้ตายได้ทำพินัยกรรมยกทรัพย์สินให้เฉพาะสิ่งเฉพาะอย่าง ในอันที่จะได้รับทรัพย์สินนั้น"}},{"id":"TH-H004-A1606","no":1606,"noLabel":{"th":"มาตรา 1606"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๐๖ บุคคลดังต่อไปนี้ต้องถูกกำจัดมิให้รับมรดกฐานเป็นผู้ไม่สมควร คือ (๑) ผู้ที่ต้องคำพิพากษาถึงที่สุดว่าได้เจตนากระทำ หรือพยายามกระทำให้เจ้ามรดกหรือผู้มีสิทธิได้รับมรดกก่อนตนถึงแก่ความตายโดยมิชอบด้วยกฎหมาย (๒) ผู้ที่ได้ฟ้องเจ้ามรดกหาว่าทำความผิดโทษประหารชีวิตและตนเองกลับต้องคำพิพากษาถึงที่สุดว่า มีความผิดฐานฟ้องเท็จหรือทำพยานเท็จ (๓) ผู้ที่รู้แล้วว่า เจ้ามรดกถูกฆ่าโดยเจตนา แต่มิได้นำข้อความนั้นขึ้นร้องเรียนเพื่อเป็นทางที่จะเอาตัวผู้กระทำผิดมาลงโทษ แต่ข้อนี้มิให้ใช้บังคับถ้าบุคคลนั้นมีอายุยังไม่ครบสิบหกปีบริบูรณ์ หรือเป็นคนวิกลจริตไม่สามารถรู้ผิดชอบ หรือถ้าผู้ที่ฆ่านั้นเป็นคู่สมรสหรือผู้บุพการีหรือผู้สืบสันดานของตนโดยตรง (๔) ผู้ที่ฉ้อฉลหรือข่มขู่ให้เจ้ามรดกทำ หรือเพิกถอนหรือเปลี่ยนแปลงพินัยกรรมแต่บางส่วนหรือทั้งหมดซึ่งเกี่ยวกับทรัพย์มรดก หรือไม่ให้กระทำการดังกล่าวนั้น (๕) ผู้ที่ปลอม ทำลาย หรือปิดบังพินัยกรรมแต่บางส่วนหรือทั้งหมด เจ้ามรดกอาจถอนข้อกำจัดฐานเป็นผู้ไม่สมควรเสียก็ได้โดยให้อภัยไว้เป็นลายลักษณ์อักษร"}},{"id":"TH-H004-A1607","no":1607,"noLabel":{"th":"มาตรา 1607"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๐๗ การถูกกำจัดมิให้รับมรดกนั้นเป็นการเฉพาะตัว ผู้สืบสันดานของทายาทที่ถูกกำจัดสืบมรดกต่อไปเหมือนหนึ่งว่าทายาทนั้นตายแล้ว แต่ในส่วนทรัพย์สินซึ่งผู้สืบสันดานได้รับมรดกมาเช่นนี้ ทายาทที่ว่านั้นไม่มีสิทธิที่จะจัดการและใช้ดังที่ระบุไว้ในบรรพ ๕ ลักษณะ ๒ หมวด ๓ แห่งประมวลกฎหมายนี้ ในกรณีเช่นนั้นให้ใช้มาตรา ๑๕๔๘ บังคับโดยอนุโลม"}},{"id":"TH-H004-A1608","no":1608,"noLabel":{"th":"มาตรา 1608"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๐๘ เจ้ามรดกจะตัดทายาทโดยธรรมของตนคนใดมิให้รับมรดกก็ได้แต่ด้วยแสดงเจตนาชัดแจ้ง (๑) โดยพินัยกรรม (๒) โดยทำเป็นหนังสือมอบไว้แก่พนักงานเจ้าหน้าที่ ตัวทายาทผู้ถูกตัดมิให้รับมรดกนั้นต้องระบุไว้ให้ชัดเจน แต่เมื่อบุคคลใดได้ทำพินัยกรรมจำหน่ายทรัพย์มรดกเสียทั้งหมดแล้ว ให้ถือว่าบรรดาทายาทโดยธรรมผู้ที่มิได้รับประโยชน์จากพินัยกรรม เป็นผู้ถูกตัดมิให้รับมรดก"}},{"id":"TH-H004-A1609","no":1609,"noLabel":{"th":"มาตรา 1609"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๐๙ การแสดงเจตนาตัดมิให้รับมรดกนั้นจะถอนเสียก็ได้ ถ้าการตัดมิให้รับมรดกนั้นได้ทำโดยพินัยกรรม จะถอนเสียได้ก็แต่โดยพินัยกรรมเท่านั้น แต่ถ้าการตัดมิให้รับมรดกได้ทำเป็นหนังสือมอบไว้แก่พนักงานเจ้าหน้าที่ การถอนจะทำตามแบบใดแบบหนึ่งดังบัญญัติไว้ในมาตรา ๑๖๐๘ (๑) หรือ (๒) ก็ได้"}},{"id":"TH-H004-A1610","no":1610,"noLabel":{"th":"มาตรา 1610"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๐ ถ้ามรดกตกทอดแก่ผู้เยาว์ หรือบุคคลวิกลจริต หรือบุคคลผู้ไม่สามารถจะจัดทำการงานของตนเองได้ตามความหมายแห่งมาตรา ๓๒ แห่งประมวลกฎหมายนี้ และบุคคลนั้นยังไม่มีผู้แทนโดยชอบธรรม หรือผู้อนุบาล หรือผู้พิทักษ์ เมื่อผู้มีส่วนได้เสีย หรือพนักงานอัยการร้องขอ ก็ให้ศาลตั้งผู้ปกครอง ผู้อนุบาล หรือผู้พิทักษ์ แล้วแต่กรณี"}},{"id":"TH-H004-A1611","no":1611,"noLabel":{"th":"มาตรา 1611"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๑ ทายาทซึ่งเป็นผู้เยาว์ บุคคลวิกลจริตหรือบุคคลผู้ไม่สามารถจะจัดทำการงานของตนเองได้ตามความหมายแห่งมาตรา ๓๒ แห่งประมวลกฎหมายนี้ จะทำการดังต่อไปนี้ไม่ได้ เว้นแต่จะได้รับความยินยอมของบิดามารดา ผู้ปกครอง ผู้อนุบาล หรือผู้พิทักษ์ แล้วแต่กรณี และได้รับอนุมัติจากศาลแล้วคือ (๑) สละมรดก (๒) รับมรดกอันมีค่าภาระติดพันหรือเงื่อนไข"}},{"id":"TH-H004-A1612","no":1612,"noLabel":{"th":"มาตรา 1612"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๒ การสละมรดกนั้น ต้องแสดงเจตนาชัดแจ้งเป็นหนังสือมอบไว้แก่พนักงานเจ้าหน้าที่ หรือทำเป็นสัญญาประนีประนอมยอมความ"}},{"id":"TH-H004-A1613","no":1613,"noLabel":{"th":"มาตรา 1613"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๓ การสละมรดกนั้น จะทำแต่เพียงบางส่วน หรือทำโดยมีเงื่อนไข หรือเงื่อนเวลาไม่ได้ การสละมรดกนั้น จะถอนเสียมิได้"}},{"id":"TH-H004-A1614","no":1614,"noLabel":{"th":"มาตรา 1614"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๔ ถ้าทายาทสละมรดกด้วยวิธีใดโดยที่รู้อยู่ว่าการที่ทำเช่นนั้นจะทำให้เจ้าหนี้ของตนเสียเปรียบ เจ้าหนี้มีสิทธิที่จะร้องขอให้เพิกถอนการสละมรดกนั้นเสียได้ แต่ความข้อนี้มิให้ใช้บังคับ ถ้าปรากฏว่าในขณะที่สละมรดกนั้น บุคคลซึ่งเป็นผู้ได้ลาภงอกแต่การนั้นมิได้รู้เท่าถึงข้อความจริงอันเป็นทางให้เจ้าหนี้ต้องเสียเปรียบนั้นด้วย แต่หากกรณีเป็นการสละมรดกโดยเสน่หา เพียงแต่ทายาทผู้สละมรดกเป็นผู้รู้ฝ่ายเดียวเท่านั้นก็พอแล้ว ที่จะขอเพิกถอนได้ เมื่อได้เพิกถอนการสละมรดกแล้ว เจ้าหนี้จะร้องขอให้ศาลสั่ง เพื่อให้ตนรับมรดกแทนที่ทายาทและในสิทธิของทายาทนั้นก็ได้ ในกรณีเช่นนี้ เมื่อได้ชำระหนี้ของทายาทนั้นให้แก่เจ้าหนี้แล้ว ถ้าส่วนของทายาทนั้นยังมีเหลืออยู่อีก ก็ให้ได้แก่ผู้สืบสันดานของทายาทนั้น หรือทายาทอื่นของเจ้ามรดก แล้วแต่กรณี"}},{"id":"TH-H004-A1615","no":1615,"noLabel":{"th":"มาตรา 1615"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๕ การที่ทายาทสละมรดกนั้น มีผลย้อนหลังไปถึงเวลาที่เจ้ามรดกตาย เมื่อทายาทโดยธรรมคนใดสละมรดก ผู้สืบสันดานของทายาทคนนั้นสืบมรดกได้ตามสิทธิของตน และชอบที่จะได้รับส่วนแบ่งเท่ากับส่วนแบ่งที่ผู้สละมรดกนั้นจะได้รับ แต่ผู้สืบสันดานนั้นต้องไม่ใช่ผู้ที่บิดามารดา ผู้ปกครอง หรือผู้อนุบาล แล้วแต่กรณี ได้บอกสละมรดกโดยสมบูรณ์ในนามของผู้สืบสันดานนั้น"}},{"id":"TH-H004-A1616","no":1616,"noLabel":{"th":"มาตรา 1616"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๖ ถ้าผู้สืบสันดานของผู้สละมรดกได้มรดกมาดังกล่าวไว้ในมาตรา ๑๖๑๕ แล้ว ผู้ที่ได้สละมรดกนั้นไม่มีสิทธิในส่วนทรัพย์สินอันผู้สืบสันดานของตนได้รับมรดกมา ในอันที่จะจัดการและใช้ดังที่ระบุไว้ในบรรพ ๕ ลักษณะ ๒ หมวด ๓ แห่งประมวลกฎหมายนี้ และให้ใช้มาตรา ๑๕๔๘ บังคับโดยอนุโลม"}},{"id":"TH-H004-A1617","no":1617,"noLabel":{"th":"มาตรา 1617"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๗ ผู้รับพินัยกรรมคนใดสละมรดก ผู้นั้นรวมตลอดทั้งผู้สืบสันดานไม่มีสิทธิจะรับมรดกที่ได้สละแล้วนั้น"}},{"id":"TH-H004-A1618","no":1618,"noLabel":{"th":"มาตรา 1618"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๘ ถ้าทายาทโดยธรรมผู้ที่ได้สละมรดกไม่มีผู้สืบสันดานที่จะรับมรดกได้ หรือผู้รับพินัยกรรมได้สละมรดก ให้ปันส่วนแบ่งของผู้ที่ได้สละมรดกนั้น ๆ แก่ทายาทอื่นของเจ้ามรดกต่อไป"}},{"id":"TH-H004-A1619","no":1619,"noLabel":{"th":"มาตรา 1619"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๑๙ ผู้ใดจะสละหรือจำหน่ายจ่ายโอนโดยประการใด ซึ่งสิทธิอันหากจะมีในภายหน้าในการสืบมรดกผู้ที่ยังมีชีวิตอยู่นั้นไม่ได้"}},{"id":"TH-H004-A1620","no":1620,"noLabel":{"th":"มาตรา 1620"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๐ ถ้าผู้ใดตายโดยไม่ได้ทำพินัยกรรมไว้หรือทำพินัยกรรมไว้แต่ไม่มีผลบังคับได้ ให้ปันทรัพย์มรดกทั้งหมดแก่ทายาทโดยธรรมของผู้ตายนั้นตามกฎหมาย ถ้าผู้ใดตายโดยได้ทำพินัยกรรมไว้ แต่พินัยกรรมนั้นจำหน่ายทรัพย์หรือมีผลบังคับได้แต่เพียงบางส่วนแห่งทรัพย์มรดก ให้ปันส่วนที่มิได้จำหน่ายโดยพินัยกรรม หรือส่วนที่พินัยกรรมไม่มีผลบังคับให้แก่ทายาทโดยธรรมตามกฎหมาย"}},{"id":"TH-H004-A1621","no":1621,"noLabel":{"th":"มาตรา 1621"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๑ เว้นแต่ผู้ทำพินัยกรรมจะได้แสดงเจตนากำหนดไว้ในพินัยกรรมเป็นอย่างอื่น แม้ทายาทโดยธรรมคนใดจะได้รับทรัพย์สินอย่างหนึ่งอย่างใดตามพินัยกรรม ทายาทคนนั้นก็ยังมีสิทธิที่จะเรียกเอาส่วนโดยธรรมของตนจากทรัพย์มรดกส่วนที่ยังไม่ได้จำหน่ายโดยพินัยกรรมจนเต็มอีกก็ได้"}},{"id":"TH-H004-A1622","no":1622,"noLabel":{"th":"มาตรา 1622"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๒ พระภิกษุนั้น จะเรียกร้องเอาทรัพย์มรดกในฐานะที่เป็นทายาทโดยธรรมไม่ได้ เว้นแต่จะได้สึกจากสมณเพศมาเรียกร้องภายในกำหนดอายุความตามมาตรา ๑๗๕๔ แต่พระภิกษุนั้น อาจเป็นผู้รับพินัยกรรมได้"}},{"id":"TH-H004-A1623","no":1623,"noLabel":{"th":"มาตรา 1623"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๓ ทรัพย์สินของพระภิกษุที่ได้มาในระหว่างเวลาที่อยู่ในสมณเพศนั้น เมื่อพระภิกษุนั้นถึงแก่มรณภาพให้ตกเป็นสมบัติของวัดที่เป็นภูมิลำเนาของพระภิกษุนั้น เว้นไว้แต่พระภิกษุนั้นจะได้จำหน่ายไปในระหว่างชีวิตหรือโดยพินัยกรรม"}},{"id":"TH-H004-A1624","no":1624,"noLabel":{"th":"มาตรา 1624"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๔ ทรัพย์สินใดเป็นของบุคคลก่อนอุปสมบทเป็นพระภิกษุ ทรัพย์สินนั้นหาตกเป็นสมบัติของวัดไม่ และให้เป็นมรดกตกทอดแก่ทายาทโดยธรรมของบุคคลนั้นหรือบุคคลนั้นจะจำหน่ายโดยประการใดตามกฎหมายก็ได้"}},{"id":"TH-H004-A1625","no":1625,"noLabel":{"th":"มาตรา 1625"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๕ ถ้าผู้ตายเป็นผู้สมรสแล้ว การคิดส่วนแบ่งและการปันทรัพย์สินระหว่างผู้ตายกับคู่สมรสที่ยังมีชีวิตอยู่นั้นให้เป็นไปดังนี้ (๑) ในเรื่องส่วนแบ่งในทรัพย์สินระหว่างคู่สมรสให้อยู่ในบังคับของบทบัญญัติแห่งประมวลกฎหมายนี้ว่าด้วยการหย่าโดยยินยอมทั้งสองฝ่าย อันมีบทบัญญัติเพิ่มเติมให้บริบูรณ์ในมาตรา ๑๖๓๗ และมาตรา ๑๖๓๘ และโดยเฉพาะต้องอยู่ในบังคับแห่งมาตรา ๑๕๑๓ ถึงมาตรา ๑๕๑๗ แห่งประมวลกฎหมายนี้ แต่การคิดส่วนแบ่งนั้นมีผลตั้งแต่วันที่การสมรสได้สิ้นไปด้วยเหตุความตายนั้น (๒) ในเรื่องส่วนแบ่งในทรัพย์มรดกของผู้ตาย ให้อยู่ในบังคับของบทบัญญัติแห่งบรรพนี้ นอกจากมาตรา ๑๖๓๗ และมาตรา ๑๖๓๘"}},{"id":"TH-H004-A1626","no":1626,"noLabel":{"th":"มาตรา 1626"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๖ เมื่อได้ปฏิบัติตามมาตรา ๑๖๒๕ (๑) แล้ว ให้คิดส่วนแบ่งทรัพย์มรดกระหว่างทายาทโดยธรรม ดังต่อไปนี้ (๑) ทรัพย์มรดกนั้นให้แบ่งแก่ทายาทตามลำดับและชั้นต่าง ๆ ดังที่บัญญัติไว้ในหมวด ๒ แห่งลักษณะนี้ (๒) ส่วนแบ่งอันจะได้แก่ทายาทในลำดับและชั้นต่าง ๆ นั้น ให้แบ่งในระหว่างบรรดาทายาทในลำดับและชั้นนั้น ๆ ดังที่บัญญัติไว้ในหมวด ๓ แห่งลักษณะนี้"}},{"id":"TH-H004-A1627","no":1627,"noLabel":{"th":"มาตรา 1627"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๗ บุตรนอกกฎหมายที่บิดาได้รับรองแล้วและบุตรบุญธรรมนั้น ให้ถือว่าเป็นผู้สืบสันดาน เหมือนกับบุตรที่ชอบด้วยกฎหมาย ตามความหมายแห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A1628","no":1628,"noLabel":{"th":"มาตรา 1628"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๒๘ คู่สมรสที่ร้างกันหรือแยกกันอยู่โดยยังมิได้หย่าขาดจากกันตามกฎหมาย มิได้สิ้นไปซึ่งสิทธิโดยธรรมในการสืบมรดกซึ่งกันและกัน"}},{"id":"TH-H004-A1629","no":1629,"noLabel":{"th":"มาตรา 1629"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๒๙ ทายาทโดยธรรมมีหกลำดับเท่านั้น และภายใต้บังคับแห่งมาตรา ๑๖๓๐ วรรคสอง แต่ละลำดับมีสิทธิได้รับมรดกก่อนหลังดังต่อไปนี้ คือ (๑) ผู้สืบสันดาน (๒) บิดามารดา (๓) พี่น้องร่วมบิดามารดาเดียวกัน (๔) พี่น้องร่วมบิดาหรือร่วมมารดาเดียวกัน (๕) ปู่ ย่า ตา ยาย (๖) ลุง ป้า น้า อา คู่สมรสที่ยังมีชีวิตอยู่นั้นก็เป็นทายาทโดยธรรม ภายใต้บังคับของบทบัญญัติพิเศษแห่งมาตรา ๑๖๓๕"}},{"id":"TH-H004-A1630","no":1630,"noLabel":{"th":"มาตรา 1630"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๓๐ ตราบใดที่มีทายาทซึ่งยังมีชีวิตอยู่ หรือมีผู้รับมรดกแทนที่ยังไม่ขาดสาย แล้วแต่กรณี ในลำดับหนึ่ง ๆ ที่ระบุไว้ในมาตรา ๑๖๒๙ ทายาทผู้ที่อยู่ในลำดับถัดลงไปไม่มีสิทธิในทรัพย์มรดกของผู้ตายเลย แต่ความในวรรคก่อนนี้มิให้ใช้บังคับในกรณีเฉพาะที่มีผู้สืบสันดานคนใดยังมีชีวิตอยู่หรือมีผู้รับมรดกแทนที่กัน แล้วแต่กรณี และมีบิดามารดายังมีชีวิตอยู่ ในกรณีเช่นนั้นให้บิดามารดาได้ส่วนแบ่งเสมือนหนึ่งว่าเป็นทายาทชั้นบุตร"}},{"id":"TH-H004-A1631","no":1631,"noLabel":{"th":"มาตรา 1631"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๓๑ ในระหว่างผู้สืบสันดานต่างชั้นกันนั้น บุตรของเจ้ามรดกอันอยู่ในชั้นสนิทที่สุดเท่านั้นมีสิทธิรับมรดก ผู้สืบสันดานที่อยู่ในชั้นถัดลงไปจะรับมรดกได้ก็แต่โดยอาศัยสิทธิในการรับมรดกแทนที่"}},{"id":"TH-H004-A1632","no":1632,"noLabel":{"th":"มาตรา 1632"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๖๓๒ ภายใต้บังคับแห่งมาตรา ๑๖๒๙ วรรคสุดท้าย การแบ่งส่วนมรดกของทายาทโดยธรรมในลำดับญาติให้เป็นไปตามบทบัญญัติในส่วนที่ ๑ แห่งหมวดนี้"}},{"id":"TH-H004-A1633","no":1633,"noLabel":{"th":"มาตรา 1633"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๖๓๓ ทายาทโดยธรรมในลำดับเดียวกัน ในลำดับหนึ่ง ๆ ที่ระบุไว้ในมาตรา ๑๖๒๙ นั้น ชอบที่จะได้รับส่วนแบ่งเท่ากัน ถ้าในลำดับหนึ่งมีทายาทโดยธรรมคนเดียว ทายาทโดยธรรมคนนั้นมีสิทธิได้รับส่วนแบ่งทั้งหมด"}},{"id":"TH-H004-A1634","no":1634,"noLabel":{"th":"มาตรา 1634"},"chapter":{"th":"ส่วน 1"},"text":{"th":"มาตรา ๑๖๓๔ ระหว่างผู้สืบสันดานที่รับมรดกแทนที่กันในส่วนแบ่งของสายหนึ่ง ๆ ตามบทบัญญัติในลักษณะ ๒ หมวด ๔ นั้น ให้ได้รับส่วนแบ่งมรดกดังนี้ (๑) ถ้ามีผู้สืบสันดานต่างชั้นกัน บุตรของผู้ตายซึ่งอยู่ในชั้นสนิทที่สุดเท่านั้นมีสิทธิรับมรดก ผู้สืบสันดานในชั้นถัดลงไปจะรับมรดกได้ก็แต่โดยอาศัยสิทธิในการรับมรดกแทนที่ (๒) ผู้สืบสันดานในชั้นเดียวกันได้รับส่วนแบ่งเท่ากัน (๓) ถ้าในชั้นหนึ่งมีผู้สืบสันดานคนเดียว ผู้สืบสันดานคนนั้นมีสิทธิได้รับส่วนแบ่งทั้งหมด"}},{"id":"TH-H004-A1635","no":1635,"noLabel":{"th":"มาตรา 1635"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๖๓๕ ลำดับและส่วนแบ่งของคู่สมรสที่ยังมีชีวิตอยู่ในการรับมรดกของผู้ตายนั้น ให้เป็นไปดังต่อไปนี้ (๑) ถ้ามีทายาทตามมาตรา ๑๖๒๙ (๑) ซึ่งยังมีชีวิตอยู่หรือมีผู้รับมรดกแทนที่ แล้วแต่กรณี คู่สมรสที่ยังมีชีวิตอยู่นั้น มีสิทธิได้ส่วนแบ่งเสมือนหนึ่งว่าตนเป็นทายาทชั้นบุตร (๒) ถ้ามีทายาทตามมาตรา ๑๖๒๙ (๓) และทายาทนั้นยังมีชีวิตอยู่หรือมีผู้รับมรดกแทนที่ หรือถ้าไม่มีทายาทตามมาตรา ๑๖๒๙ (๑) แต่มีทายาทตามมาตรา ๑๖๒๙ (๒) แล้วแต่กรณี คู่สมรสที่ยังมีชีวิตอยู่นั้นมีสิทธิได้รับมรดกกึ่งหนึ่ง (๓) ถ้ามีทายาทตามมาตรา ๑๖๒๙ (๔) หรือ (๖) และทายาทนั้นยังมีชีวิตอยู่ หรือมีผู้รับมรดกแทนที่ หรือมีทายาทตามมาตรา ๑๖๒๙ (๕) แล้วแต่กรณี คู่สมรสที่ยังมีชีวิตอยู่ มีสิทธิได้มรดกสองส่วนในสาม (๔) ถ้าไม่มีทายาทดังที่ระบุไว้ในมาตรา ๑๖๒๙ คู่สมรสที่ยังมีชีวิตอยู่นั้นมีสิทธิได้รับมรดกทั้งหมด"}},{"id":"TH-H004-A1636","no":1636,"noLabel":{"th":"มาตรา 1636"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๖๓๖ ถ้าเจ้ามรดกมีภริยาที่ชอบด้วยกฎหมายก่อนใช้ประมวลกฎหมายแพ่งและพาณิชย์บรรพ ๕ หลายคนยังมีชีวิตอยู่ ภริยาเหล่านั้นทั้งหมดรวมกันมีสิทธิได้รับมรดกตามลำดับชั้นและส่วนแบ่งดังระบุไว้ในมาตรา ๑๖๓๕ แต่ในระหว่างกันเองให้ภริยาน้อยแต่ละคนมีสิทธิได้รับมรดกกึ่งส่วนที่ภริยาหลวงจะพึงได้รับ"}},{"id":"TH-H004-A1637","no":1637,"noLabel":{"th":"มาตรา 1637"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๖๓๗ ถ้าคู่สมรสฝ่ายใดที่ยังมีชีวิตอยู่เป็นผู้รับประโยชน์ตามสัญญาประกันชีวิต คู่สมรสฝ่ายนั้นมีสิทธิรับจำนวนเงินทั้งหมดที่ได้ตกลงไว้กับผู้รับประกันภัย แต่จำต้องเอาจำนวนเบี้ยประกันภัย เพียงเท่าที่พิสูจน์ได้ว่าสูงกว่าจำนวนเงินที่ผู้ตายจะพึงส่งใช้เป็นเบี้ยประกันภัยได้ตามรายได้หรือฐานะของตนโดยปกติไปชดใช้สินเดิมของคู่สมรสอีกฝ่ายหนึ่ง หรือสินสมรส แล้วแต่กรณี ถึงอย่างไรก็ดี จำนวนเงินเบี้ยประกันภัยซึ่งจะพึงส่งคืนตามบทบัญญัติข้างต้นนั้น รวมทั้งสิ้นต้องไม่เกินจำนวนเงินที่ผู้รับประกันภัยได้ชำระให้"}},{"id":"TH-H004-A1638","no":1638,"noLabel":{"th":"มาตรา 1638"},"chapter":{"th":"ส่วน 2"},"text":{"th":"มาตรา ๑๖๓๘ เมื่อคู่สมรสทั้งสองฝ่ายได้ลงทุนออกเงินในการทำสัญญา และตามสัญญานั้นทั้งสองฝ่ายจะต้องได้รับเงินปีในขณะที่ยังมีชีวิตอยู่ร่วมกัน และเมื่อฝ่ายหนึ่งฝ่ายใดตาย ฝ่ายที่ยังมีชีวิตอยู่ยังจะต้องได้รับเงินปีต่อไปตลอดอายุ ฝ่ายที่ยังมีชีวิตอยู่ จำต้องชดใช้สินเดิมของอีกฝ่ายหนึ่ง หรือสินสมรส แล้วแต่กรณี สุดแต่ว่าได้เอาเงินสินเดิม หรือสินสมรสไปใช้ในการลงทุนนั้น เงินที่จะต้องชดใช้สินเดิมหรือสินสมรสดังว่านี้ ให้ชดใช้เท่าจำนวนเงินซึ่งผู้จ่ายเงินรายปีจะเรียกให้ใช้เพิ่มขึ้นเป็นพิเศษ เพื่อผู้จ่ายจะได้จ่ายเงินรายปีให้แก่คู่สมรสฝ่ายที่ยังมีชีวิตอยู่นั้นต่อไป"}},{"id":"TH-H004-A1639","no":1639,"noLabel":{"th":"มาตรา 1639"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๓๙ ถ้าบุคคลใดซึ่งจะเป็นทายาทตามมาตรา ๑๖๒๙ (๑) (๓) (๔) หรือ (๖) ถึงแก่ความตาย หรือถูกกำจัดมิให้รับมรดกก่อนเจ้ามรดกตาย ถ้าบุคคลนั้นมีผู้สืบสันดานก็ให้ผู้สืบสันดานรับมรดกแทนที่ ถ้าผู้สืบสันดานคนใดของบุคคลนั้นถึงแก่ความตายหรือถูกกำจัดมิให้รับมรดกเช่นเดียวกัน ก็ให้ผู้สืบสันดานของผู้สืบสันดานนั้นรับมรดกแทนที่ และให้มีการรับมรดกแทนที่กันเฉพาะส่วนแบ่งของบุคคลเป็นราย ๆ สืบต่อกันเช่นนี้ไปจนหมดสาย"}},{"id":"TH-H004-A1640","no":1640,"noLabel":{"th":"มาตรา 1640"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๐ เมื่อบุคคลใดต้องถือว่าถึงแก่ความตายตามความในมาตรา ๖๕ แห่งประมวลกฎหมายนี้ ให้มีการรับมรดกแทนที่กันได้"}},{"id":"TH-H004-A1641","no":1641,"noLabel":{"th":"มาตรา 1641"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๑ ถ้าบุคคลใดซึ่งจะเป็นทายาทตามมาตรา ๑๖๒๙ (๒) หรือ (๕) ถึงแก่ความตาย หรือถูกกำจัดมิให้รับมรดกก่อนเจ้ามรดกตาย ถ้ามีทายาทในลำดับเดียวกันยังมีชีวิตอยู่ ก็ให้ส่วนแบ่งทั้งหมดตกได้แก่ทายาทนั้นเท่านั้น ห้ามมิให้มีการรับมรดกแทนที่กันต่อไป"}},{"id":"TH-H004-A1642","no":1642,"noLabel":{"th":"มาตรา 1642"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๒ การรับมรดกแทนที่กันนั้น ให้ใช้บังคับแต่ในระหว่างทายาทโดยธรรม"}},{"id":"TH-H004-A1643","no":1643,"noLabel":{"th":"มาตรา 1643"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๓ สิทธิที่จะรับมรดกแทนที่กันนั้นได้เฉพาะผู้สืบสันดานโดยตรง ผู้บุพการีหามีสิทธิดังนั้นไม่"}},{"id":"TH-H004-A1644","no":1644,"noLabel":{"th":"มาตรา 1644"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๔ ผู้สืบสันดานจะรับมรดกแทนที่ได้ต่อเมื่อมีสิทธิบริบูรณ์ในการรับมรดก"}},{"id":"TH-H004-A1645","no":1645,"noLabel":{"th":"มาตรา 1645"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๔๕ การที่บุคคลใดสละมรดกของบุคคลอีกคนหนึ่งนั้น ไม่ตัดสิทธิของผู้สละที่จะรับมรดกแทนที่บุคคลอีกคนหนึ่งนั้นในการสืบมรดกบุคคลอื่น"}},{"id":"TH-H004-A1646","no":1646,"noLabel":{"th":"มาตรา 1646"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๔๖ บุคคลใดจะแสดงเจตนาโดยพินัยกรรม กำหนดการเผื่อตายในเรื่องทรัพย์สินของตนเอง หรือในการต่าง ๆ อันจะให้เกิดเป็นผลบังคับได้ตามกฎหมายเมื่อตนตายก็ได้"}},{"id":"TH-H004-A1647","no":1647,"noLabel":{"th":"มาตรา 1647"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๔๗ การแสดงเจตนากำหนดการเผื่อตายนั้นย่อมทำได้ด้วยคำสั่งสุดท้ายกำหนดไว้ในพินัยกรรม"}},{"id":"TH-H004-A1648","no":1648,"noLabel":{"th":"มาตรา 1648"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๔๘ พินัยกรรมนั้นต้องทำตามแบบซึ่งระบุไว้ในหมวด ๒ แห่งลักษณะนี้"}},{"id":"TH-H004-A1649","no":1649,"noLabel":{"th":"มาตรา 1649"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๔๙ ผู้จัดการมรดกซึ่งผู้ตายตั้งไว้ย่อมมีอำนาจและหน้าที่ในอันที่จะจัดการทำศพของผู้ตาย เว้นแต่ผู้ตายจะได้ตั้งบุคคลอื่นไว้โดยเฉพาะให้จัดการดังว่านั้น ถ้าผู้ตายมิได้ตั้งผู้จัดการมรดกหรือบุคคลใดไว้ให้เป็นผู้จัดการทำศพ หรือทายาทมิได้มอบหมายตั้งให้บุคคลใดเป็นผู้จัดการทำศพ บุคคลผู้ได้รับทรัพย์มรดกโดยพินัยกรรมหรือโดยสิทธิโดยธรรมเป็นจำนวนมากที่สุด เป็นผู้มีอำนาจและตกอยู่ในหน้าที่ต้องจัดการทำศพ เว้นแต่ศาลจะเห็นเป็นการสมควรตั้งบุคคลอื่นให้จัดการเช่นนั้น ในเมื่อบุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งร้องขอขึ้น"}},{"id":"TH-H004-A1650","no":1650,"noLabel":{"th":"มาตรา 1650"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๕๐ ค่าใช้จ่ายเกิดมีหนี้เป็นคุณแก่บุคคลใดในการจัดการทำศพนั้น ให้เรียกเอาได้ตามบุริมสิทธิที่ระบุไว้ในมาตรา ๒๕๓ (๒) แห่งประมวลกฎหมายนี้ ถ้าการจัดการทำศพ ต้องชักช้าไปด้วยประการใด ๆ ให้บุคคลผู้มีอำนาจตามความในมาตราก่อนกันเงินเป็นจำนวนอันสมควรจากสินทรัพย์แห่งกองมรดกเพื่อใช้ในการนี้ โดยให้บุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งร้องต่อศาลได้ในกรณีที่ไม่ตกลงหรือคัดค้านการกันเงินจำนวนนั้น กรณีจะเป็นอย่างไรก็ตาม เงินค่าใช้จ่าย หรือเงินที่กันไว้อันเกี่ยวกับการจัดการทำศพนั้น ให้กันไว้ได้แต่เพียงจำนวนตามสมควรแก่ฐานะในสมาคมของผู้ตาย แต่จะต้องไม่เป็นการเสื่อมเสียต่อสิทธิของเจ้าหนี้ของผู้ตาย"}},{"id":"TH-H004-A1651","no":1651,"noLabel":{"th":"มาตรา 1651"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๕๑ ภายใต้บังคับบทบัญญัติลักษณะ ๔ (๑) เมื่อตามข้อกำหนดพินัยกรรม บุคคลใดมีสิทธิที่จะได้รับทรัพย์มรดกทั้งหมดของเจ้ามรดก หรือตามเศษส่วน หรือตามส่วนที่เหลือแห่งทรัพย์มรดก ซึ่งมิได้แยกไว้ต่างหากเป็นพิเศษจากกองมรดก บุคคลนั้นเรียกว่าผู้รับพินัยกรรมลักษณะทั่วไป และมีสิทธิและความรับผิดเช่นเดียวกับทายาทโดยธรรม (๒) เมื่อตามข้อกำหนดพินัยกรรมบุคคลใดมีสิทธิที่จะได้รับทรัพย์สินเฉพาะสิ่งเฉพาะอย่าง ซึ่งเจาะจงไว้โดยเฉพาะ หรือแยกไว้ต่างหากเป็นพิเศษจากกองมรดก บุคคลนั้นเรียกว่า ผู้รับพินัยกรรมลักษณะเฉพาะ และมีสิทธิและความรับผิดที่เกี่ยวกับทรัพย์สินเท่านั้น ในกรณีที่มีข้อสงสัย ให้สันนิษฐานไว้ก่อนว่า ผู้รับพินัยกรรมเป็นผู้รับพินัยกรรมลักษณะเฉพาะ"}},{"id":"TH-H004-A1652","no":1652,"noLabel":{"th":"มาตรา 1652"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๕๒ บุคคลผู้อยู่ในความปกครองนั้น จะทำพินัยกรรมยกทรัพย์มรดกของตนให้แก่ผู้ปกครองหรือคู่สมรส บุพการี หรือผู้สืบสันดาน หรือพี่น้องของผู้ปกครองไม่ได้จนกว่าผู้ปกครองจะได้ทำคำแถลงการณ์ปกครองตามที่บัญญัติไว้ในมาตรา ๑๕๗๗ และมาตราต่อ ๆ ไปแห่งประมวลกฎหมายนี้เสร็จสิ้นแล้ว"}},{"id":"TH-H004-A1653","no":1653,"noLabel":{"th":"มาตรา 1653"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๕๓ ผู้เขียน หรือพยานในพินัยกรรมจะเป็นผู้รับทรัพย์ตามพินัยกรรมนั้นไม่ได้ ให้ใช้บทบัญญัติในวรรคก่อนบังคับแก่คู่สมรสของผู้เขียนหรือพยานในพินัยกรรมด้วย พนักงานเจ้าหน้าที่ซึ่งได้จดข้อความแห่งพินัยกรรมที่พยานนำมาแจ้งตามมาตรา ๑๖๖๓ ให้ถือว่าเป็นผู้เขียนพินัยกรรมตามความหมายแห่งมาตรานี้"}},{"id":"TH-H004-A1654","no":1654,"noLabel":{"th":"มาตรา 1654"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๖๕๔ ความสามารถของผู้ทำพินัยกรรมนั้น ให้พิจารณาแต่ในเวลาที่ทำพินัยกรรมเท่านั้น ความสามารถของผู้รับพินัยกรรมนั้น ให้พิจารณาแต่ในเวลาที่ผู้ทำพินัยกรรมตายเท่านั้น"}},{"id":"TH-H004-A1655","no":1655,"noLabel":{"th":"มาตรา 1655"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕๕ พินัยกรรมนั้น จะทำได้ก็แต่ตามแบบใดแบบหนึ่งดังที่บัญญัติไว้ในหมวดนี้"}},{"id":"TH-H004-A1656","no":1656,"noLabel":{"th":"มาตรา 1656"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕๖ พินัยกรรมนั้น จะทำตามแบบดังนี้ก็ได้ กล่าวคือต้องทำเป็นหนังสือลงวัน เดือน ปี ในขณะที่ทำขึ้น และผู้ทำพินัยกรรมต้องลงลายมือชื่อไว้ต่อหน้าพยานอย่างน้อยสองคนพร้อมกัน ซึ่งพยานสองคนนั้นต้องลงลายมือชื่อรับรองลายมือชื่อของผู้ทำพินัยกรรมไว้ในขณะนั้น การขูดลบ ตก เติม หรือการแก้ไขเปลี่ยนแปลงอย่างอื่นซึ่งพินัยกรรมนั้นย่อมไม่สมบูรณ์ เว้นแต่จะได้ปฏิบัติตามแบบอย่างเดียวกับการทำพินัยกรรมตามมาตรานี้"}},{"id":"TH-H004-A1657","no":1657,"noLabel":{"th":"มาตรา 1657"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕๗ พินัยกรรมนั้น จะทำเป็นเอกสารเขียนเองทั้งฉบับก็ได้ กล่าวคือผู้ทำพินัยกรรมต้องเขียนด้วยมือตนเองซึ่งข้อความทั้งหมด วัน เดือน ปี และลายมือชื่อของตน การขูดลบ ตก เติม หรือการแก้ไขเปลี่ยนแปลงอย่างอื่นซึ่งพินัยกรรมนั้นย่อมไม่สมบูรณ์ เว้นแต่ผู้ทำพินัยกรรมจะได้ทำด้วยมือตนเอง และลงลายมือชื่อกำกับไว้ บทบัญญัติมาตรา ๙ แห่งประมวลกฎหมายนี้ มิให้ใช้บังคับแก่พินัยกรรมที่ทำขึ้นตามมาตรานี้"}},{"id":"TH-H004-A1658","no":1658,"noLabel":{"th":"มาตรา 1658"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕๘ พินัยกรรมนั้น จะทำเป็นเอกสารฝ่ายเมืองก็ได้ กล่าวคือ (๑) ผู้ทำพินัยกรรมต้องไปแจ้งข้อความที่ตนประสงค์จะให้ใส่ไว้ในพินัยกรรมของตนแก่กรมการอำเภอต่อหน้าพยานอีกอย่างน้อยสองคนพร้อมกัน (๒) กรมการอำเภอต้องจดข้อความที่ผู้ทำพินัยกรรมแจ้งให้ทราบนั้นลงไว้ และอ่านข้อความนั้นให้ผู้ทำพินัยกรรมและพยานฟัง (๓) เมื่อผู้ทำพินัยกรรมและพยานทราบแน่ชัดว่าข้อความที่กรมการอำเภอจดนั้นเป็นการถูกต้องตรงกันกับที่ผู้ทำพินัยกรรมแจ้งไว้แล้ว ให้ผู้ทำพินัยกรรมและพยานลงลายมือชื่อไว้เป็นสำคัญ (๔) ข้อความที่กรมการอำเภอจดไว้นั้น ให้กรมการอำเภอลงลายมือชื่อและลงวัน เดือน ปี ทั้งจดลงไว้ด้วยตนเองเป็นสำคัญว่า พินัยกรรมนั้นได้ทำขึ้นถูกต้องตามบทบัญญัติ (๑) ถึง (๓) ข้างต้น แล้วประทับตราตำแหน่งไว้เป็นสำคัญ การขูดลบ ตก เติม หรือการแก้ไขเปลี่ยนแปลงอย่างอื่นซึ่งพินัยกรรมนั้นย่อมไม่สมบูรณ์ เว้นแต่ผู้ทำพินัยกรรม พยาน และกรมการอำเภอจะได้ลงลายมือชื่อกำกับไว้"}},{"id":"TH-H004-A1659","no":1659,"noLabel":{"th":"มาตรา 1659"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๕๙ การทำพินัยกรรมแบบเอกสารฝ่ายเมืองนั้น จะทำนอกที่ว่าการอำเภอก็ได้ เมื่อมีการร้องขอเช่นนั้น"}},{"id":"TH-H004-A1660","no":1660,"noLabel":{"th":"มาตรา 1660"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๐ พินัยกรรมนั้น จะทำเป็นเอกสารลับก็ได้ กล่าวคือ (๑) ผู้ทำพินัยกรรมต้องลงลายมือชื่อในพินัยกรรม (๒) ผู้ทำพินัยกรรมต้องผนึกพินัยกรรมนั้น แล้วลงลายมือชื่อคาบรอยผนึกนั้น (๓) ผู้ทำพินัยกรรมต้องนำพินัยกรรมที่ผนึกนั้นไปแสดงต่อกรมการอำเภอ และพยานอีกอย่างน้อยสองคน และให้ถ้อยคำต่อบุคคลทั้งหมดเหล่านั้นว่าเป็นพินัยกรรมของตน ถ้าพินัยกรรมนั้นผู้ทำพินัยกรรมมิได้เป็นผู้เขียนเองโดยตลอด ผู้ทำพินัยกรรมจะต้องแจ้งนามและภูมิลำเนาของผู้เขียนให้ทราบด้วย (๔) เมื่อกรมการอำเภอจดถ้อยคำของผู้ทำพินัยกรรมและวัน เดือน ปี ที่นำพินัยกรรมมาแสดงไว้บนซองนั้นและประทับตราตำแหน่งแล้ว ให้กรมการอำเภอผู้ทำพินัยกรรมและพยานลงลายมือชื่อบนซองนั้น การขูดลบ ตก เติม หรือการแก้ไขเปลี่ยนแปลงอย่างอื่นซึ่งพินัยกรรมนั้นย่อมไม่สมบูรณ์ เว้นแต่ผู้ทำพินัยกรรมจะได้ลงลายมือชื่อกำกับไว้"}},{"id":"TH-H004-A1661","no":1661,"noLabel":{"th":"มาตรา 1661"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๑ ถ้าบุคคลผู้เป็นทั้งใบ้และหูหนวกหรือผู้ที่พูดไม่ได้ มีความประสงค์จะทำพินัยกรรมเป็นแบบเอกสารลับ ให้ผู้นั้นเขียนด้วยตนเองบนซองพินัยกรรมต่อหน้ากรมการอำเภอและพยานซึ่งข้อความว่าพินัยกรรมที่ผนึกนั้นเป็นของตนแทนการให้ถ้อยคำดังที่กำหนดไว้ในมาตรา ๑๖๖๐ (๓) และถ้าหากมีผู้เขียนก็ให้เขียนชื่อกับภูมิลำเนาของผู้เขียนพินัยกรรมนั้นไว้ด้วย ให้กรมการอำเภอจดลงไว้บนซองเป็นสำคัญว่า ผู้ทำพินัยกรรมได้ปฏิบัติตามข้อความในวรรคก่อนแล้ว แทนการจดถ้อยคำของผู้ทำพินัยกรรม"}},{"id":"TH-H004-A1662","no":1662,"noLabel":{"th":"มาตรา 1662"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๒ พินัยกรรมซึ่งได้ทำเป็นแบบเอกสารฝ่ายเมืองหรือเอกสารลับนั้น กรมการอำเภอจะเปิดเผยแก่บุคคลอื่นใดไม่ได้ในระหว่างที่ผู้ทำพินัยกรรมยังมีชีวิตอยู่ และผู้ทำพินัยกรรมจะเรียกให้กรมการอำเภอส่งมอบพินัยกรรมนั้นแก่ตนในเวลาใด ๆ กรมการอำเภอจำต้องส่งมอบให้ ถ้าพินัยกรรมนั้นทำเป็นแบบเอกสารฝ่ายเมือง ก่อนส่งมอบพินัยกรรมให้กรมการอำเภอคัดสำเนาพินัยกรรมไว้ แล้วลงลายมือชื่อประทับตราตำแหน่งเป็นสำคัญ สำเนาพินัยกรรมนั้นจะเปิดเผยแก่บุคคลอื่นใดไม่ได้ในระหว่างที่ผู้ทำพินัยกรรมยังมีชีวิตอยู่"}},{"id":"TH-H004-A1663","no":1663,"noLabel":{"th":"มาตรา 1663"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๓ เมื่อมีพฤติการณ์พิเศษซึ่งบุคคลใดไม่สามารถจะทำพินัยกรรมตามแบบอื่นที่กำหนดไว้ได้ เช่น ตกอยู่ในอันตรายใกล้ความตาย หรือเวลามีโรคระบาด หรือสงคราม บุคคลนั้นจะทำพินัยกรรมด้วยวาจาก็ได้ เพื่อการนี้ ผู้ทำพินัยกรรมต้องแสดงเจตนากำหนดข้อพินัยกรรมต่อหน้าพยานอย่างน้อยสองคนซึ่งอยู่พร้อมกัน ณ ที่นั้น พยานสองคนนั้นต้องไปแสดงตนต่อกรมการอำเภอโดยมิชักช้าและแจ้งข้อความที่ผู้ทำพินัยกรรมได้สั่งไว้ด้วยวาจานั้น ทั้งต้องแจ้งวัน เดือน ปี สถานที่ที่ทำพินัยกรรมและพฤติการณ์พิเศษนั้นไว้ด้วย ให้กรมการอำเภอจดข้อความที่พยานแจ้งนั้นไว้ และพยานสองคนนั้นต้องลงลายมือชื่อไว้ หรือมิฉะนั้น จะให้เสมอกับการลงลายมือชื่อได้ก็แต่ด้วยลงลายพิมพ์นิ้วมือ โดยมีพยานลงลายมือชื่อรับรองสองคน"}},{"id":"TH-H004-A1664","no":1664,"noLabel":{"th":"มาตรา 1664"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๔ ความสมบูรณ์แห่งพินัยกรรมซึ่งทำขึ้นตามมาตราก่อนนั้นย่อมสิ้นไปเมื่อพ้นกำหนดหนึ่งเดือนนับแต่เวลาผู้ทำพินัยกรรมกลับมาสู่ฐานะที่จะทำพินัยกรรมตามแบบอื่นที่กำหนดไว้ได้"}},{"id":"TH-H004-A1665","no":1665,"noLabel":{"th":"มาตรา 1665"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๕ เมื่อผู้ทำพินัยกรรมจะต้องลงลายมือชื่อตามมาตรา ๑๖๕๖ มาตรา ๑๖๕๘ มาตรา ๑๖๖๐ จะให้เสมอกับลงลายมือชื่อได้ ก็แต่ด้วยลงลายพิมพ์นิ้วมือโดยมีพยานลงลายมือชื่อรับรองไว้ด้วยสองคนในขณะนั้น"}},{"id":"TH-H004-A1666","no":1666,"noLabel":{"th":"มาตรา 1666"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๖ บทบัญญัติมาตรา ๙ วรรคสอง แห่งประมวลกฎหมายนี้ มิให้ใช้บังคับแก่พยานผู้ที่จะต้องลงลายมือชื่อตามมาตรา ๑๖๕๖ มาตรา ๑๖๕๘ มาตรา ๑๖๖๐"}},{"id":"TH-H004-A1667","no":1667,"noLabel":{"th":"มาตรา 1667"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๗ เมื่อคนในบังคับสยามจะทำพินัยกรรมในต่างประเทศ พินัยกรรมนั้นอาจทำตามแบบซึ่งกฎหมายของประเทศที่ทำพินัยกรรมบัญญัติไว้ หรือตามแบบที่กฎหมายสยามบัญญัติไว้ก็ได้ เมื่อทำพินัยกรรมตามแบบที่กฎหมายสยามบัญญัติไว้ อำนาจและหน้าที่ของกรมการอำเภอตามมาตรา ๑๖๕๘ มาตรา ๑๖๖๐ มาตรา ๑๖๖๑ มาตรา ๑๖๖๒ มาตรา ๑๖๖๓ ให้ตกแก่บุคคลดังต่อไปนี้ คือ (๑) พนักงานทูต หรือกงสุลฝ่ายสยาม กระทำการตามขอบอำนาจของตน หรือ (๒) พนักงานใด ๆ ซึ่งมีอำนาจตามกฎหมายของต่างประเทศนั้น ๆ ที่จะรับบันทึกข้อแจ้งความไว้เป็นหลักฐานได้"}},{"id":"TH-H004-A1668","no":1668,"noLabel":{"th":"มาตรา 1668"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๘ ผู้ทำพินัยกรรมไม่จำเป็นต้องเปิดเผยข้อความในพินัยกรรมนั้นให้พยานทราบ เว้นแต่กฎหมายจะได้ระบุไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1669","no":1669,"noLabel":{"th":"มาตรา 1669"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๖๙ ในระหว่างเวลาที่ประเทศตกอยู่ในภาวะการรบหรือการสงคราม บุคคลที่รับราชการทหารหรือทำการเกี่ยวข้องอยู่กับราชการทหาร จะทำพินัยกรรมตามแบบที่บัญญัติไว้ในมาตรา ๑๖๕๘ มาตรา ๑๖๖๐ หรือมาตรา ๑๖๖๓ ก็ได้ ในกรณีเช่นว่านั้น ให้นายทหารหรือข้าราชการฝ่ายทหารชั้นสัญญาบัตรมีอำนาจและหน้าที่เช่นเดียวกับกรมการอำเภอ บทบัญญัติวรรคก่อนให้นำมาใช้บังคับแก่กรณีที่บุคคลที่รับราชการทหารหรือทำการเกี่ยวข้องอยู่กับราชการทหารทำพินัยกรรมในต่างประเทศในระหว่างที่ปฏิบัติการเพื่อประเทศในภาวะการรบหรือการสงครามในต่างประเทศโดยอนุโลม และในกรณีเช่นว่านี้ ให้นายทหารหรือข้าราชการฝ่ายทหารชั้นสัญญาบัตรมีอำนาจและหน้าที่เช่นเดียวกับพนักงานทูตหรือกงสุลฝ่ายไทย ถ้าผู้ทำพินัยกรรมตามความในสองวรรคก่อนนั้นป่วยเจ็บหรือต้องบาดเจ็บ และอยู่ในโรงพยาบาล ให้แพทย์แห่งโรงพยาบาลนั้นมีอำนาจและหน้าที่เช่นเดียวกับกรมการอำเภอหรือพนักงานทูต หรือกงสุลฝ่ายไทย แล้วแต่กรณีด้วย"}},{"id":"TH-H004-A1670","no":1670,"noLabel":{"th":"มาตรา 1670"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๗๐ บุคคลต่อไปนี้จะเป็นพยานในการทำพินัยกรรมไม่ได้ (๑) ผู้ซึ่งยังไม่บรรลุนิติภาวะ (๒) บุคคลวิกลจริตหรือบุคคลซึ่งศาลสั่งให้เป็นผู้เสมือนไร้ความสามารถ (๓) บุคคลที่หูหนวก เป็นใบ้ หรือจักษุบอดทั้งสองข้าง"}},{"id":"TH-H004-A1671","no":1671,"noLabel":{"th":"มาตรา 1671"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๗๑ เมื่อบุคคลใดนอกจากผู้ทำพินัยกรรมเป็นผู้เขียนข้อความแห่งพินัยกรรม บุคคลนั้นต้องลงลายมือชื่อของตนทั้งระบุว่าเป็นผู้เขียน ถ้าบุคคลนั้นเป็นพยานด้วย ให้เขียนข้อความระบุว่าตนเป็นพยานไว้ต่อท้ายลายมือชื่อของตนเช่นเดียวกับพยานอื่น ๆ"}},{"id":"TH-H004-A1672","no":1672,"noLabel":{"th":"มาตรา 1672"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๖๗๒ ให้รัฐมนตรีว่าการกระทรวงมหาดไทย กลาโหม และต่างประเทศ มีอำนาจและหน้าที่เท่าที่เกี่ยวกับกระทรวงนั้น ๆ ที่จะออกกฎกระทรวง เพื่อให้การเป็นไปตามประมวลกฎหมายบรรพนี้ รวมทั้งกำหนดอัตราค่าฤชาธรรมเนียมอันเกี่ยวกับการนั้น"}},{"id":"TH-H004-A1673","no":1673,"noLabel":{"th":"มาตรา 1673"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๓ สิทธิและหน้าที่ใด ๆ อันเกิดขึ้นตามพินัยกรรม ให้มีผลบังคับเรียกร้องกันได้ตั้งแต่ผู้ทำพินัยกรรมตายเป็นต้นไป เว้นแต่ผู้ทำพินัยกรรมจะได้กำหนดเงื่อนไขหรือเงื่อนเวลาให้มีผลบังคับเรียกร้องกันได้ภายหลัง"}},{"id":"TH-H004-A1674","no":1674,"noLabel":{"th":"มาตรา 1674"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๔ ถ้าข้อกำหนดพินัยกรรมมีเงื่อนไข และเงื่อนไขนั้นสำเร็จเสียก่อนเวลาที่ผู้ทำพินัยกรรมตาย หากว่าเป็นเงื่อนไขบังคับก่อน ข้อกำหนดพินัยกรรมนั้นมีผลเมื่อผู้ทำพินัยกรรมตาย หากว่าเป็นเงื่อนไขบังคับหลัง ข้อกำหนดพินัยกรรมนั้นเป็นอันไร้ผล ถ้าเงื่อนไขบังคับก่อนสำเร็จภายหลังที่ผู้ทำพินัยกรรมตาย ข้อกำหนดพินัยกรรมมีผลตั้งแต่เวลาเงื่อนไขสำเร็จ ถ้าเงื่อนไขบังคับหลังสำเร็จภายหลังที่ผู้ทำพินัยกรรมตาย ข้อกำหนดพินัยกรรมมีผลตั้งแต่เวลาที่ผู้ทำพินัยกรรมตาย แต่ตกเป็นอันไร้ผลในเมื่อเงื่อนไขนั้นสำเร็จ แต่ถ้าผู้ทำพินัยกรรมได้กำหนดไว้ในพินัยกรรมว่า ในกรณีที่กล่าวมาในสองวรรคก่อนนั้น ให้ความสำเร็จแห่งเงื่อนไขมีผลย้อนหลังไปถึงเวลาที่ผู้ทำพินัยกรรมตาย ก็ให้เป็นไปตามเจตนาของผู้ทำพินัยกรรมนั้น"}},{"id":"TH-H004-A1675","no":1675,"noLabel":{"th":"มาตรา 1675"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๕ เมื่อพินัยกรรมมีเงื่อนไขบังคับก่อน ผู้รับประโยชน์ตามข้อความแห่งพินัยกรรมนั้นจะร้องต่อศาลขอให้ตั้งผู้จัดการทรัพย์สินที่ยกให้โดยพินัยกรรมนั้นจนกว่าจะถึงเวลาที่เงื่อนไขสำเร็จ หรือจนกว่าความสำเร็จแห่งเงื่อนไขตกเป็นอันพ้นวิสัยก็ได้ ถ้าศาลเห็นเป็นการสมควร จะตั้งผู้ร้องนั้นเป็นผู้จัดการทรัพย์สินเสียเอง และเรียกให้ผู้ร้องนั้นวางประกันตามที่สมควรก็ได้"}},{"id":"TH-H004-A1676","no":1676,"noLabel":{"th":"มาตรา 1676"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๖ พินัยกรรมจะทำขึ้นโดยให้บุคคลใดตกอยู่ในภาระติดพันที่จะต้องก่อตั้งมูลนิธิ หรือจะสั่งจัดสรรทรัพย์สินไว้โดยตรง เพื่อประโยชน์อย่างใดอย่างหนึ่งตามบทบัญญัติมาตรา ๑๑๐ แห่งประมวลกฎหมายนี้ก็ได้"}},{"id":"TH-H004-A1677","no":1677,"noLabel":{"th":"มาตรา 1677"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๗ เมื่อมีพินัยกรรมก่อตั้งมูลนิธิขึ้นตามมาตราก่อน ให้เป็นหน้าที่ของทายาทหรือผู้จัดการมรดก แล้วแต่กรณี ที่จะต้องร้องขอให้รัฐบาลให้อำนาจจัดตั้งขึ้นเป็นนิติบุคคลตามมาตรา ๑๑๔ แห่งประมวลกฎหมายนี้ เว้นแต่จะได้มีข้อกำหนดไว้ในพินัยกรรมเป็นอย่างอื่น ถ้าบุคคลดังกล่าวแล้วมิได้ร้องขอให้รัฐบาลให้อำนาจ บุคคลผู้มีส่วนได้เสียคนหนึ่งคนใดหรือพนักงานอัยการจะเป็นผู้ร้องขอก็ได้"}},{"id":"TH-H004-A1678","no":1678,"noLabel":{"th":"มาตรา 1678"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๘ เมื่อมูลนิธิใดซึ่งก่อตั้งขึ้นโดยพินัยกรรมได้ตั้งขึ้นเป็นนิติบุคคลแล้ว ให้ถือว่าทรัพย์สินซึ่งผู้ทำพินัยกรรมจัดสรรไว้เพื่อการนั้น ตกเป็นของนิติบุคคลนั้นตั้งแต่เวลาซึ่งพินัยกรรมมีผล เว้นแต่จะมีข้อกำหนดไว้ในพินัยกรรมเป็นอย่างอื่น"}},{"id":"TH-H004-A1679","no":1679,"noLabel":{"th":"มาตรา 1679"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๗๙ ถ้าจัดตั้งมูลนิธิขึ้นไม่ได้ตามวัตถุที่ประสงค์ ให้ทรัพย์สินตกทอดไปตามที่ระบุไว้ในพินัยกรรม ถ้าพินัยกรรมไม่ได้ระบุไว้ เมื่อทายาทหรือผู้จัดการมรดก หรือพนักงานอัยการ หรือบุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งร้องขอ ให้ศาลจัดสรรทรัพย์สินนั้นให้แก่นิติบุคคลอื่น ซึ่งปรากฏว่ามีวัตถุที่ประสงค์ใกล้ชิดที่สุดกับความประสงค์ของผู้ทำพินัยกรรม ถ้าหากว่าจัดสรรทรัพย์สินอย่างนี้ไม่ได้ก็ดี หรือว่ามูลนิธินั้นตั้งขึ้นไม่ได้ เพราะเป็นการขัดต่อกฎหมาย หรือขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชนก็ดี ข้อกำหนดพินัยกรรมในการจัดตั้งมูลนิธินั้นเป็นอันไร้ผล"}},{"id":"TH-H004-A1680","no":1680,"noLabel":{"th":"มาตรา 1680"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๐ เจ้าหนี้ของผู้ทำพินัยกรรมมีสิทธิที่จะร้องขอให้เพิกถอนข้อกำหนดพินัยกรรมซึ่งก่อตั้งมูลนิธินั้นได้เพียงเท่าที่ตนต้องเสียประโยชน์เนื่องแต่การนั้น"}},{"id":"TH-H004-A1681","no":1681,"noLabel":{"th":"มาตรา 1681"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๑ ถ้าทรัพย์สินซึ่งเป็นวัตถุแห่งพินัยกรรมนั้น ได้สูญหาย ทำลาย หรือบุบสลายไป และพฤติการณ์ ทั้งนี้ เป็นผลให้ได้ทรัพย์สินอื่นมาแทน หรือได้สิทธิเรียกร้องเอาค่าสินไหมทดแทนทรัพย์สินนั้น ผู้รับพินัยกรรมจะเรียกให้ส่งมอบของแทนซึ่งได้รับมานั้น หรือจะเรียกร้องเอาค่าสินไหมทดแทนเสียเองก็ได้ แล้วแต่กรณี"}},{"id":"TH-H004-A1682","no":1682,"noLabel":{"th":"มาตรา 1682"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๒ เมื่อพินัยกรรมทำขึ้นเป็นการปลดหนี้หรือโอนสิทธิเรียกร้อง พินัยกรรมนั้นมีผลเพียงจำนวนซึ่งคงค้างชำระอยู่ในเวลาที่ผู้ทำพินัยกรรมตาย เว้นแต่ผู้ทำพินัยกรรมจะได้กำหนดไว้เป็นอย่างอื่น ถ้ามีเอกสารอันเป็นหลักฐานแห่งหนี้ที่ปลดให้หรือสิทธิเรียกร้องที่โอนไปนั้น ก็ให้ส่งมอบแก่ผู้รับพินัยกรรมและให้ใช้มาตรา ๓๐๓ ถึงมาตรา ๓๑๓ มาตรา ๓๔๐ แห่งประมวลกฎหมายนี้บังคับโดยอนุโลม แต่ถ้าผู้ทำพินัยกรรมจะต้องกระทำการหรือดำเนินการอย่างใดอย่างหนึ่งตามมาตรานั้น ๆ แล้ว บุคคลผู้ต้องจัดการตามพินัยกรรมหรือผู้รับพินัยกรรมจะกระทำการหรือดำเนินการนั้น ๆ แทนผู้ทำพินัยกรรมก็ได้"}},{"id":"TH-H004-A1683","no":1683,"noLabel":{"th":"มาตรา 1683"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๓ พินัยกรรมที่บุคคลทำให้แก่เจ้าหนี้คนใดของตนนั้น ให้สันนิษฐานไว้ก่อนว่า มิได้ทำขึ้นเพื่อชำระหนี้อันค้างชำระแก่เจ้าหนี้คนนั้น"}},{"id":"TH-H004-A1684","no":1684,"noLabel":{"th":"มาตรา 1684"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๔ เมื่อความข้อใดข้อหนึ่งในพินัยกรรมอาจตีความได้เป็นหลายนัย ให้ถือเอาตามนัยที่จะสำเร็จผลตามความประสงค์ของผู้ทำพินัยกรรมนั้นได้ดีที่สุด"}},{"id":"TH-H004-A1685","no":1685,"noLabel":{"th":"มาตรา 1685"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๖๘๕ ในกรณีที่ผู้ทำพินัยกรรมได้กำหนดผู้รับพินัยกรรมไว้โดยคุณสมบัติที่ทราบตัวแน่นอนได้ ถ้ามีบุคคลหลายคนทรงไว้ซึ่งคุณสมบัติที่จะเป็นผู้รับพินัยกรรมตามที่ผู้ทำพินัยกรรมกำหนดไว้ดังนั้นได้ ในกรณีที่มีข้อสงสัยให้ถือว่าทุกคนมีสิทธิที่จะได้รับส่วนปันเท่า ๆ กัน"}},{"id":"TH-H004-A1686","no":1686,"noLabel":{"th":"มาตรา 1686"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๘๖ อันว่าทรัสต์นั้น จะก่อตั้งขึ้นโดยตรงหรือโดยทางอ้อมด้วยพินัยกรรมหรือด้วยนิติกรรมใด ๆ ที่มีผลในระหว่างชีวิตก็ดีหรือเมื่อตายแล้วก็ดี หามีผลไม่ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายเพื่อการก่อตั้งทรัสต์เท่านั้น"}},{"id":"TH-H004-A1687","no":1687,"noLabel":{"th":"มาตรา 1687"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๘๗ ถ้าผู้ทำพินัยกรรมประสงค์จะยกทรัพย์สินให้แก่ผู้เยาว์ หรือผู้ซึ่งศาลได้สั่งให้เป็นคนไร้ความสามารถ หรือเสมือนไร้ความสามารถ หรือแก่ผู้ซึ่งต้องรักษาตัวอยู่ในโรงพยาบาลเพราะเหตุวิกลจริต แต่ต้องการมอบการเก็บรักษาและจัดการทรัพย์สินนั้นแก่บุคคลอื่น นอกจากบิดามารดา ผู้ปกครอง ผู้อนุบาล หรือผู้พิทักษ์ของบุคคลเช่นนั้น ผู้ทำพินัยกรรมต้องตั้งผู้ปกครองทรัพย์ขึ้น การตั้งผู้ปกครองทรัพย์นี้ ห้ามมิให้ตั้งขึ้นเป็นเวลาเกินกว่ากำหนดแห่งการเป็นผู้เยาว์ หรือกำหนดที่ศาลได้สั่งให้เป็นคนไร้ความสามารถ หรือเสมือนไร้ความสามารถ หรือกำหนดที่ต้องรักษาตัวอยู่ในโรงพยาบาล แล้วแต่กรณี"}},{"id":"TH-H004-A1688","no":1688,"noLabel":{"th":"มาตรา 1688"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๘๘ การตั้งผู้ปกครองทรัพย์นั้น ในส่วนที่เกี่ยวด้วยอสังหาริมทรัพย์หรือทรัพยสิทธิใด ๆ อันเกี่ยวกับอสังหาริมทรัพย์ ย่อมไม่บริบูรณ์ เว้นแต่จะได้จดทะเบียนต่อพนักงานเจ้าหน้าที่ บทบัญญัติที่กล่าวมาในวรรคก่อนนี้ ให้ใช้บังคับแก่เรือมีระวางตั้งแต่ห้าตันขึ้นไป ทั้งแพและสัตว์พาหนะด้วย"}},{"id":"TH-H004-A1689","no":1689,"noLabel":{"th":"มาตรา 1689"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๘๙ นอกจากบุคคลที่ระบุไว้ในมาตรา ๑๕๕๗ แห่งประมวลกฎหมายนี้ นิติบุคคล หรือบุคคลธรรมดาที่มีความสามารถบริบูรณ์ จะรับตั้งเป็นผู้ปกครองทรัพย์ก็ได้"}},{"id":"TH-H004-A1690","no":1690,"noLabel":{"th":"มาตรา 1690"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๙๐ ผู้ปกครองทรัพย์นั้น ย่อมตั้งขึ้นได้โดย (๑) ผู้ทำพินัยกรรม (๒) บุคคลซึ่งระบุไว้ในพินัยกรรมให้เป็นผู้ตั้ง"}},{"id":"TH-H004-A1691","no":1691,"noLabel":{"th":"มาตรา 1691"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๙๑ เว้นแต่ผู้ทำพินัยกรรมจะได้กำหนดไว้เป็นอย่างอื่นในพินัยกรรม ผู้ปกครองทรัพย์จะทำพินัยกรรมตั้งบุคคลอื่นให้ทำการสืบแทนตนก็ได้"}},{"id":"TH-H004-A1692","no":1692,"noLabel":{"th":"มาตรา 1692"},"chapter":{"th":"หมวด / หมวดที่ 4"},"text":{"th":"มาตรา ๑๖๙๒ เว้นแต่ผู้ทำพินัยกรรมจะได้กำหนดไว้ในพินัยกรรมเป็นอย่างอื่น ในส่วนที่เกี่ยวด้วยทรัพย์สินที่ได้รับมอบไว้ ผู้ปกครองทรัพย์มีสิทธิและหน้าที่เช่นเดียวกับผู้ปกครองตามความหมายในบรรพ ๕ แห่งประมวลกฎหมายนี้"}},{"id":"TH-H004-A1693","no":1693,"noLabel":{"th":"มาตรา 1693"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๓ ผู้ทำพินัยกรรมจะเพิกถอนพินัยกรรมของตนเสียทั้งหมด หรือแต่บางส่วนในเวลาใดก็ได้"}},{"id":"TH-H004-A1694","no":1694,"noLabel":{"th":"มาตรา 1694"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๔ ถ้าจะเพิกถอนพินัยกรรมฉบับก่อนเสียทั้งหมด หรือแต่บางส่วนด้วยพินัยกรรมฉบับหลัง การเพิกถอนจะสมบูรณ์ต่อเมื่อพินัยกรรมฉบับหลังนั้นได้ทำตามแบบใดแบบหนึ่งที่กฎหมายบัญญัติไว้"}},{"id":"TH-H004-A1695","no":1695,"noLabel":{"th":"มาตรา 1695"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๕ ถ้าพินัยกรรมได้ทำเป็นต้นฉบับแต่ฉบับเดียว ผู้ทำพินัยกรรมอาจเพิกถอนพินัยกรรมนั้นทั้งหมดหรือบางส่วนได้ โดยทำลายหรือขีดฆ่าเสียด้วยความตั้งใจ ถ้าพินัยกรรมได้ทำเป็นต้นฉบับหลายฉบับ การเพิกถอนนั้นไม่บริบูรณ์ เว้นแต่จะได้กระทำแก่ต้นฉบับเหล่านั้นทุกฉบับ"}},{"id":"TH-H004-A1696","no":1696,"noLabel":{"th":"มาตรา 1696"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๖ ถ้าผู้ทำพินัยกรรมได้โอนไปโดยสมบูรณ์ซึ่งทรัพย์สินอันเป็นวัตถุแห่งข้อกำหนดพินัยกรรมใดด้วยความตั้งใจ ข้อกำหนดพินัยกรรมนั้นเป็นอันเพิกถอนไป วิธีเดียวกันนี้ให้ใช้บังคับ เมื่อผู้ทำพินัยกรรมได้ทำลายทรัพย์สินนั้นด้วยความตั้งใจ"}},{"id":"TH-H004-A1697","no":1697,"noLabel":{"th":"มาตรา 1697"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๗ ถ้าผู้ทำพินัยกรรมมิได้แสดงเจตนาไว้ในพินัยกรรมเป็นอย่างอื่น และปรากฏว่าพินัยกรรมฉบับก่อนกับฉบับหลังขัดกัน ให้ถือว่าพินัยกรรมฉบับก่อนเป็นอันเพิกถอนโดยพินัยกรรมฉบับหลัง เฉพาะในส่วนที่มีข้อความขัดกันนั้นเท่านั้น"}},{"id":"TH-H004-A1698","no":1698,"noLabel":{"th":"มาตรา 1698"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๘ ข้อกำหนดพินัยกรรมนั้น ย่อมตกไป (๑) เมื่อผู้รับพินัยกรรมตายก่อนผู้ทำพินัยกรรม (๒) เมื่อข้อกำหนดพินัยกรรมเป็นผลใช้ได้ต่อเมื่อเงื่อนไขอย่างใดอย่างหนึ่งสำเร็จลง และผู้รับพินัยกรรมตายเสียก่อนเงื่อนไขสำเร็จ หรือปรากฏเป็นที่แน่นอนอยู่แล้วว่าเงื่อนไขนั้นไม่อาจจะสำเร็จได้ (๓) เมื่อผู้รับพินัยกรรมบอกสละพินัยกรรม (๔) เมื่อทรัพย์สินทั้งหมดที่ยกให้สูญหาย หรือถูกทำลายโดยผู้ทำพินัยกรรมมิได้ตั้งใจในระหว่างที่ผู้ทำพินัยกรรมยังมีชีวิตอยู่ และผู้ทำพินัยกรรมมิได้ได้มาซึ่งของแทน หรือซึ่งสิทธิที่จะเรียกค่าทดแทนในการที่ทรัพย์สินนั้นสูญหายไป"}},{"id":"TH-H004-A1699","no":1699,"noLabel":{"th":"มาตรา 1699"},"chapter":{"th":"หมวด / หมวดที่ 5"},"text":{"th":"มาตรา ๑๖๙๙ ถ้าพินัยกรรม หรือข้อกำหนดในพินัยกรรม เกี่ยวกับทรัพย์สินรายใดเป็นอันไร้ผลด้วยประการใด ๆ ทรัพย์สินรายนั้นตกทอดแก่ทายาทโดยธรรมหรือได้แก่แผ่นดิน แล้วแต่กรณี"}},{"id":"TH-H004-A1700","no":1700,"noLabel":{"th":"มาตรา 1700"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๐ ภายใต้บังคับแห่งบทบัญญัติในหมวดนี้ บุคคลจะจำหน่ายทรัพย์สินใด ๆ โดยนิติกรรมที่มีผลในระหว่างชีวิต หรือเมื่อตายแล้ว โดยมีข้อกำหนดห้ามมิให้ผู้รับประโยชน์โอนทรัพย์สินนั้นก็ได้ แต่ต้องมีบุคคลใดบุคคลหนึ่งนอกจากผู้รับประโยชน์กำหนดไว้ สำหรับเป็นผู้จะได้รับทรัพย์สินนั้นเป็นสิทธิเด็ดขาด ในเมื่อมีการละเมิดข้อกำหนดห้ามโอน ผู้ซึ่งกำหนดขึ้นดังกล่าวนั้นต้องเป็นผู้สามารถจะมีสิทธิต่าง ๆ ได้อยู่ในขณะที่การจำหน่ายทรัพย์สินนั้นมีผลบังคับ ถ้ามิได้กำหนดบุคคลที่จะเป็นผู้รับทรัพย์สินในเมื่อมีการละเมิดข้อกำหนดห้ามโอนไว้ ให้ถือว่าข้อกำหนดห้ามโอนนั้นเป็นอันไม่มีเลย"}},{"id":"TH-H004-A1701","no":1701,"noLabel":{"th":"มาตรา 1701"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๑ ข้อกำหนดห้ามโอนตามมาตราก่อนนั้น จะให้มีกำหนดเวลาหรือตลอดชีวิตของผู้รับประโยชน์ก็ได้ ถ้าไม่มีกำหนดเวลาห้ามโอนไว้ ในกรณีที่ผู้รับประโยชน์เป็นบุคคลธรรมดา ให้ถือว่าข้อกำหนดห้ามโอนมีระยะเวลาอยู่ตลอดชีวิตของผู้รับประโยชน์ แต่ในกรณีที่ผู้รับประโยชน์เป็นนิติบุคคล ให้มีระยะเวลาเพียงสามสิบปี ถ้าได้กำหนดเวลาห้ามโอนไว้ กำหนดนั้นมิให้เกินสามสิบปี ถ้ากำหนดไว้นานกว่านั้น ก็ให้ลดลงมาเป็นสามสิบปี"}},{"id":"TH-H004-A1702","no":1702,"noLabel":{"th":"มาตรา 1702"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๒ ข้อกำหนดห้ามโอนอันเกี่ยวกับสังหาริมทรัพย์ซึ่งไม่อาจจดทะเบียนกรรมสิทธิ์ได้นั้น ให้ถือว่าเป็นอันไม่มีเลย ข้อกำหนดห้ามโอนอันเกี่ยวกับอสังหาริมทรัพย์หรือทรัพยสิทธิอันเกี่ยวกับอสังหาริมทรัพย์นั้น ไม่บริบูรณ์ เว้นแต่จะได้ทำเป็นหนังสือและจดทะเบียนการห้ามโอนต่อพนักงานเจ้าหน้าที่ บทบัญญัติในวรรคก่อนนี้ ให้ใช้บังคับแก่เรือมีระวางตั้งแต่ห้าตันขึ้นไป ทั้งแพและสัตว์พาหนะด้วย"}},{"id":"TH-H004-A1703","no":1703,"noLabel":{"th":"มาตรา 1703"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๓ พินัยกรรมซึ่งบุคคลที่มีอายุยังไม่ครบสิบห้าปีบริบูรณ์ทำขึ้นนั้น เป็นโมฆะ"}},{"id":"TH-H004-A1704","no":1704,"noLabel":{"th":"มาตรา 1704"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๔ พินัยกรรมซึ่งบุคคลผู้ถูกศาลสั่งให้เป็นคนไร้ความสามารถทำขึ้นนั้น เป็นโมฆะ พินัยกรรมซึ่งบุคคลผู้ถูกอ้างว่าเป็นคนวิกลจริต แต่ศาลยังไม่ได้สั่งให้เป็นคนไร้ความสามารถทำขึ้นนั้น จะเป็นอันเสียเปล่าก็แต่เมื่อพิสูจน์ได้ว่าในเวลาที่ทำพินัยกรรมนั้นผู้ทำจริตวิกลอยู่"}},{"id":"TH-H004-A1705","no":1705,"noLabel":{"th":"มาตรา 1705"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๕ พินัยกรรมหรือข้อกำหนดพินัยกรรมนั้น ถ้าได้ทำขึ้นขัดต่อบทบัญญัติแห่งมาตรา ๑๖๕๒ มาตรา ๑๖๕๓ มาตรา ๑๖๕๖ มาตรา ๑๖๕๗ มาตรา ๑๖๕๘ มาตรา ๑๖๖๐ มาตรา ๑๖๖๑ หรือมาตรา ๑๖๖๓ ย่อมเป็นโมฆะ"}},{"id":"TH-H004-A1706","no":1706,"noLabel":{"th":"มาตรา 1706"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๖ ข้อกำหนดพินัยกรรมเป็นโมฆะ (๑) ถ้าตั้งผู้รับพินัยกรรมไว้โดยมีเงื่อนไขว่า ให้ผู้รับพินัยกรรมจำหน่ายทรัพย์สินของเขาเองโดยพินัยกรรมให้แก่ผู้ทำพินัยกรรม หรือแก่บุคคลภายนอก (๒) ถ้ากำหนดบุคคลซึ่งไม่อาจที่จะทราบตัวแน่นอนได้เป็นผู้รับพินัยกรรม แต่ผู้รับพินัยกรรมตามพินัยกรรมลักษณะเฉพาะนั้น อาจกำหนดโดยให้บุคคลใดคนหนึ่งเป็นผู้ระบุเลือกเอาจากบุคคลอื่นหลายคน หรือจากบุคคลอื่นหมู่ใดหมู่หนึ่ง ซึ่งผู้ทำพินัยกรรมระบุไว้ก็ได้ (๓) ถ้าทรัพย์สินที่ยกให้โดยพินัยกรรมระบุไว้ไม่ชัดแจ้งจนไม่อาจที่จะทราบแน่นอนได้ หรือถ้าให้บุคคลใดคนหนึ่งกำหนดให้มากน้อยเท่าใดตามแต่ใจ"}},{"id":"TH-H004-A1707","no":1707,"noLabel":{"th":"มาตรา 1707"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๗ ถ้าข้อกำหนดพินัยกรรมตั้งผู้รับพินัยกรรมโดยมีเงื่อนไขว่าให้ผู้รับพินัยกรรมจำหน่ายทรัพย์สินที่ยกให้โดยพินัยกรรมนั้นแก่บุคคลอื่น ให้ถือว่าเงื่อนไขนั้นเป็นอันไม่มีเลย"}},{"id":"TH-H004-A1708","no":1708,"noLabel":{"th":"มาตรา 1708"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๘ เมื่อผู้ทำพินัยกรรมตายแล้ว บุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งจะร้องขอให้ศาลสั่งเพิกถอนพินัยกรรมซึ่งได้ทำขึ้นเพราะเหตุข่มขู่ก็ได้ แต่หากผู้ทำพินัยกรรมยังมีชีวิตอยู่ต่อมาเกินหนึ่งปีนับแต่ผู้ทำพินัยกรรมพ้นจากการข่มขู่แล้ว จะมีการร้องขอเช่นว่านั้นไม่ได้"}},{"id":"TH-H004-A1709","no":1709,"noLabel":{"th":"มาตรา 1709"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๐๙ เมื่อผู้ทำพินัยกรรมตายแล้ว บุคคลผู้มีส่วนได้เสียคนใดคนหนึ่งจะร้องขอให้ศาลสั่งเพิกถอนพินัยกรรมซึ่งได้ทำขึ้นเพราะสำคัญผิดหรือกลฉ้อฉลได้ก็ต่อเมื่อความสำคัญผิดหรือกลฉ้อฉลนั้นถึงขนาด ซึ่งถ้ามิได้มีความสำคัญผิดหรือกลฉ้อฉลเช่นนั้น พินัยกรรมนั้นก็จะมิได้ทำขึ้น ความในวรรคก่อนนี้ ให้ใช้บังคับ แม้ถึงว่ากลฉ้อฉลนั้น บุคคลซึ่งมิใช่เป็นผู้รับประโยชน์ตามพินัยกรรมได้ก่อขึ้น แต่พินัยกรรมซึ่งได้ทำขึ้นโดยสำคัญผิดหรือกลฉ้อฉลย่อมมีผลบังคับได้ เมื่อผู้ทำพินัยกรรมมิได้เพิกถอนพินัยกรรมนั้นภายในหนึ่งปีนับแต่ที่ได้รู้ถึงการสำคัญผิดหรือกลฉ้อฉลนั้น"}},{"id":"TH-H004-A1710","no":1710,"noLabel":{"th":"มาตรา 1710"},"chapter":{"th":"หมวด / หมวดที่ 6"},"text":{"th":"มาตรา ๑๗๑๐ คดีฟ้องขอให้เพิกถอนข้อกำหนดพินัยกรรมนั้น มิให้ฟ้องเมื่อพ้นกำหนดดังนี้ (๑) สามเดือนภายหลังที่ผู้ทำพินัยกรรมตาย ในกรณีที่โจทก์รู้เหตุแห่งการที่จะขอให้เพิกถอนได้ ในระหว่างที่ผู้ทำพินัยกรรมยังมีชีวิตอยู่ หรือ (๒) สามเดือนภายหลังที่โจทก์ได้รู้เหตุเช่นนั้นในกรณีอื่นใด แต่ถ้าโจทก์ไม่รู้ว่ามีข้อกำหนดพินัยกรรมอันกระทบกระทั่งถึงส่วนได้เสียของตน แม้ว่าโจทก์จะได้รู้เหตุแห่งการที่จะขอให้เพิกถอนได้ก็ดี อายุความสามเดือนให้เริ่มนับแต่ขณะที่โจทก์รู้หรือควรจะได้รู้ว่ามีข้อกำหนดพินัยกรรมนั้น แต่อย่างไรก็ดี ห้ามมิให้ฟ้องคดีเช่นนี้เมื่อพ้นสิบปีนับแต่ผู้ทำพินัยกรรมตาย"}},{"id":"TH-H004-A1711","no":1711,"noLabel":{"th":"มาตรา 1711"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๑ ผู้จัดการมรดกนั้นรวมตลอดทั้งบุคคลที่ตั้งขึ้นโดยพินัยกรรมหรือโดยคำสั่งศาล"}},{"id":"TH-H004-A1712","no":1712,"noLabel":{"th":"มาตรา 1712"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๒ ผู้จัดการมรดกโดยพินัยกรรมอาจตั้งขึ้นได้ (๑) โดยผู้ทำพินัยกรรมเอง (๒) โดยบุคคลซึ่งระบุไว้ในพินัยกรรม ให้เป็นผู้ตั้ง"}},{"id":"TH-H004-A1713","no":1713,"noLabel":{"th":"มาตรา 1713"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๓ ทายาทหรือผู้มีส่วนได้เสียหรือพนักงานอัยการจะร้องต่อศาลขอให้ตั้งผู้จัดการมรดกก็ได้ ในกรณีดังต่อไปนี้ (๑) เมื่อเจ้ามรดกตาย ทายาทโดยธรรมหรือผู้รับพินัยกรรมได้สูญหายไป หรืออยู่นอกราชอาณาเขต หรือเป็นผู้เยาว์ (๒) เมื่อผู้จัดการมรดกหรือทายาทไม่สามารถ หรือไม่เต็มใจที่จะจัดการ หรือมีเหตุขัดข้องในการจัดการ หรือในการแบ่งปันมรดก (๓) เมื่อข้อกำหนดพินัยกรรมซึ่งตั้งผู้จัดการมรดกไว้ไม่มีผลบังคับได้ด้วยประการใด ๆ การตั้งผู้จัดการมรดกนั้น ถ้ามีข้อกำหนดพินัยกรรมก็ให้ศาลตั้งตามข้อกำหนดพินัยกรรม และถ้าไม่มีข้อกำหนดพินัยกรรม ก็ให้ศาลตั้งเพื่อประโยชน์แก่กองมรดกตามพฤติการณ์ และโดยคำนึงถึงเจตนาของเจ้ามรดก แล้วแต่ศาลจะเห็นสมควร"}},{"id":"TH-H004-A1714","no":1714,"noLabel":{"th":"มาตรา 1714"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๔ เมื่อศาลตั้งให้ผู้ใดเป็นผู้จัดการมรดกเพื่อการใดโดยเฉพาะ ผู้นั้นไม่จำต้องทำบัญชีทรัพย์มรดก เว้นแต่จะจำเป็นเพื่อการนั้น หรือศาลสั่งให้ทำ"}},{"id":"TH-H004-A1715","no":1715,"noLabel":{"th":"มาตรา 1715"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๕ ผู้ทำพินัยกรรมจะตั้งบุคคลคนเดียวหรือหลายคนให้เป็นผู้จัดการมรดกก็ได้ เว้นแต่จะมีข้อกำหนดไว้ในพินัยกรรมเป็นอย่างอื่น ถ้ามีผู้จัดการมรดกหลายคน แต่ผู้จัดการเหล่านั้นบางคนไม่สามารถ หรือไม่เต็มใจที่จะจัดการ และยังมีผู้จัดการมรดกเหลืออยู่แต่คนเดียว ผู้นั้นมีสิทธิที่จะจัดการมรดกได้โดยลำพัง แต่ถ้ามีผู้จัดการมรดกเหลืออยู่หลายคน ให้สันนิษฐานไว้ก่อนว่า ผู้จัดการเหล่านั้นแต่ละคนจะจัดการโดยลำพังไม่ได้"}},{"id":"TH-H004-A1716","no":1716,"noLabel":{"th":"มาตรา 1716"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๖ หน้าที่ผู้จัดการมรดกที่ศาลตั้ง ให้เริ่มนับแต่วันที่ได้ฟังหรือถือว่าได้ฟังคำสั่งศาลแล้ว"}},{"id":"TH-H004-A1717","no":1717,"noLabel":{"th":"มาตรา 1717"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๗ ในเวลาใด ๆ ภายในหนึ่งปีนับแต่วันที่เจ้ามรดกตาย แต่ต้องเป็นเวลาภายหลังที่เจ้ามรดกตายแล้วสิบห้าวัน ทายาทหรือผู้มีส่วนได้เสียคนใดคนหนึ่ง จะแจ้งความถามไปยังผู้ที่ถูกตั้งเป็นผู้จัดการมรดกโดยพินัยกรรมว่าจะรับเป็นผู้จัดการมรดกหรือไม่ก็ได้ ถ้าผู้ที่ได้รับแจ้งความมิได้ตอบรับเป็นผู้จัดการมรดกภายในหนึ่งเดือนนับแต่วันรับแจ้งความนั้น ให้ถือว่าผู้นั้นปฏิเสธ แต่การรับเป็นผู้จัดการมรดกนั้น จะทำภายหลังหนึ่งปีนับแต่วันที่เจ้ามรดกตายไม่ได้ เว้นแต่ศาลจะอนุญาต"}},{"id":"TH-H004-A1718","no":1718,"noLabel":{"th":"มาตรา 1718"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๘ บุคคลต่อไปนี้จะเป็นผู้จัดการมรดกไม่ได้ (๑) ผู้ซึ่งยังไม่บรรลุนิติภาวะ (๒) บุคคลวิกลจริต หรือบุคคลซึ่งศาลสั่งให้เป็นผู้เสมือนไร้ความสามารถ (๓) บุคคลซึ่งศาลสั่งให้เป็นคนล้มละลาย"}},{"id":"TH-H004-A1719","no":1719,"noLabel":{"th":"มาตรา 1719"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๑๙ ผู้จัดการมรดกมีสิทธิและหน้าที่ที่จะทำการอันจำเป็น เพื่อให้การเป็นไปตามคำสั่งแจ้งชัดหรือโดยปริยายแห่งพินัยกรรม และเพื่อจัดการมรดกโดยทั่วไปหรือเพื่อแบ่งปันทรัพย์มรดก"}},{"id":"TH-H004-A1720","no":1720,"noLabel":{"th":"มาตรา 1720"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๐ ผู้จัดการมรดกต้องรับผิดต่อทายาทตามที่บัญญัติไว้ในมาตรา ๘๐๙ ถึงมาตรา ๘๑๒ มาตรา ๘๑๙ มาตรา ๘๒๓ แห่งประมวลกฎหมายนี้โดยอนุโลม และเมื่อเกี่ยวกับบุคคลภายนอก ให้ใช้มาตรา ๘๓๑ บังคับโดยอนุโลม"}},{"id":"TH-H004-A1721","no":1721,"noLabel":{"th":"มาตรา 1721"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๑ ผู้จัดการมรดกไม่มีสิทธิที่จะได้รับบำเหน็จจากกองมรดก เว้นแต่พินัยกรรม หรือทายาทโดยจำนวนข้างมากจะได้กำหนดให้ไว้"}},{"id":"TH-H004-A1722","no":1722,"noLabel":{"th":"มาตรา 1722"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๒ ผู้จัดการมรดกจะทำนิติกรรมใด ๆ ซึ่งตนมีส่วนได้เสียเป็นปฏิปักษ์ต่อกองมรดกหาได้ไม่ เว้นแต่พินัยกรรมจะได้อนุญาตไว้ หรือได้รับอนุญาตจากศาล"}},{"id":"TH-H004-A1723","no":1723,"noLabel":{"th":"มาตรา 1723"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๓ ผู้จัดการมรดกต้องจัดการโดยตนเอง เว้นแต่จะทำการโดยตัวแทนได้ตามอำนาจที่ให้ไว้ชัดแจ้งหรือโดยปริยายในพินัยกรรม หรือโดยคำสั่งศาล หรือในพฤติการณ์เพื่อประโยชน์แก่กองมรดก"}},{"id":"TH-H004-A1724","no":1724,"noLabel":{"th":"มาตรา 1724"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๔ ทายาทย่อมมีความผูกพันต่อบุคคลภายนอกในกิจการทั้งหลายอันผู้จัดการมรดกได้ทำไปภายในขอบอำนาจในฐานะที่เป็นผู้จัดการมรดก ถ้าผู้จัดการมรดกเข้าทำนิติกรรมกับบุคคลภายนอก โดยเห็นแก่ทรัพย์สินอย่างใด ๆ หรือประโยชน์อย่างอื่นใด อันบุคคลภายนอกได้ให้ หรือได้ให้คำมั่นว่าจะให้เป็นลาภส่วนตัว ทายาทหาต้องผูกพันไม่ เว้นแต่ทายาทจะได้ยินยอมด้วย"}},{"id":"TH-H004-A1725","no":1725,"noLabel":{"th":"มาตรา 1725"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๕ ผู้จัดการมรดกต้องสืบหาโดยสมควรซึ่งตัวผู้มีส่วนได้เสียและแจ้งไปให้ทราบถึงข้อกำหนดพินัยกรรมที่เกี่ยวกับผู้มีส่วนได้เสียนั้นภายในเวลาอันสมควร"}},{"id":"TH-H004-A1726","no":1726,"noLabel":{"th":"มาตรา 1726"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๖ ถ้าผู้จัดการมรดกมีหลายคน การทำการตามหน้าที่ของผู้จัดการมรดกนั้นต้องถือเอาเสียงข้างมาก เว้นแต่จะมีข้อกำหนดพินัยกรรมเป็นอย่างอื่น ถ้าเสียงเท่ากัน เมื่อผู้มีส่วนได้เสียร้องขอ ก็ให้ศาลเป็นผู้ชี้ขาด"}},{"id":"TH-H004-A1727","no":1727,"noLabel":{"th":"มาตรา 1727"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๗ ผู้มีส่วนได้เสียคนหนึ่งคนใดจะร้องขอให้ศาลสั่งถอนผู้จัดการมรดก เพราะเหตุผู้จัดการมรดกละเลยไม่ทำการตามหน้าที่ หรือเพราะเหตุอย่างอื่นที่สมควรก็ได้ แต่ต้องร้องขอเสียก่อนที่การปันมรดกเสร็จสิ้นลง แม้ถึงว่าจะได้เข้ารับตำแหน่งแล้วก็ดี ผู้จัดการมรดกจะลาออกจากตำแหน่งโดยมีเหตุอันสมควรก็ได้ แต่ต้องได้รับอนุญาตจากศาล"}},{"id":"TH-H004-A1728","no":1728,"noLabel":{"th":"มาตรา 1728"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๘ ผู้จัดการมรดกต้องลงมือจัดทำบัญชีทรัพย์มรดกภายในสิบห้าวัน (๑) นับแต่เจ้ามรดกตาย ถ้าในขณะนั้นผู้จัดการมรดกได้รู้ถึงการตั้งแต่งตามพินัยกรรมที่มอบหมายไว้แก่ตน หรือ (๒) นับแต่วันที่เริ่มหน้าที่ผู้จัดการมรดกตามมาตรา ๑๗๑๖ ในกรณีที่ศาลตั้งเป็นผู้จัดการมรดก หรือ (๓) นับแต่วันที่ผู้จัดการมรดกรับเป็นผู้จัดการมรดกในกรณีอื่น"}},{"id":"TH-H004-A1729","no":1729,"noLabel":{"th":"มาตรา 1729"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๒๙ ผู้จัดการมรดกต้องจัดทำบัญชีทรัพย์มรดกให้แล้วเสร็จภายในหนึ่งเดือนนับแต่เวลาที่ระบุไว้ในมาตรา ๑๗๒๘ แต่กำหนดเวลานี้ เมื่อผู้จัดการมรดกร้องขอก่อนสิ้นกำหนดเวลาหนึ่งเดือน ศาลจะอนุญาตให้ขยายต่อไปอีกก็ได้ บัญชีนั้นต้องทำต่อหน้าพยานอย่างน้อยสองคน ซึ่งต้องเป็นผู้มีส่วนได้เสียในกองมรดกนั้นด้วย บุคคลซึ่งจะเป็นพยานในการทำพินัยกรรมไม่ได้ตามมาตรา ๑๖๗๐ จะเป็นพยานในการทำบัญชีใด ๆ ที่ต้องทำขึ้นตามบทบัญญัติแห่งประมวลกฎหมายนี้ไม่ได้"}},{"id":"TH-H004-A1730","no":1730,"noLabel":{"th":"มาตรา 1730"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๓๐ ให้นำมาตรา ๑๕๖๓ มาตรา ๑๕๖๔ วรรคหนึ่ง และวรรคสอง และมาตรา ๑๕๖๕ แห่งประมวลกฎหมายนี้มาใช้บังคับโดยอนุโลม ในระหว่างทายาทกับผู้จัดการมรดกโดยพินัยกรรมและในระหว่างศาลกับผู้จัดการมรดกที่ศาลตั้ง"}},{"id":"TH-H004-A1731","no":1731,"noLabel":{"th":"มาตรา 1731"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๓๑ ถ้าผู้จัดการมรดกมิได้จัดทำบัญชีภายในเวลาและตามแบบที่กำหนดไว้ หรือถ้าบัญชีนั้นไม่เป็นที่พอใจแก่ศาล เพราะความประมาทเลินเล่ออย่างร้ายแรงหรือการทุจริต หรือความไม่สามารถอันเห็นประจักษ์ของผู้จัดการมรดก ศาลจะถอนผู้จัดการมรดกเสียก็ได้"}},{"id":"TH-H004-A1732","no":1732,"noLabel":{"th":"มาตรา 1732"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๓๒ ผู้จัดการมรดกต้องจัดการตามหน้าที่และทำรายงานแสดงบัญชีการจัดการและแบ่งปันมรดกให้เสร็จภายในหนึ่งปีนับแต่วันที่ระบุไว้ในมาตรา ๑๗๒๘ เว้นแต่ผู้ทำพินัยกรรม ทายาทโดยจำนวนข้างมาก หรือศาลจะได้กำหนดเวลาให้ไว้เป็นอย่างอื่น"}},{"id":"TH-H004-A1733","no":1733,"noLabel":{"th":"มาตรา 1733"},"chapter":{"th":"หมวด / หมวดที่ 1"},"text":{"th":"มาตรา ๑๗๓๓ การให้อนุมัติ การปลดเปลื้องความรับผิด หรือข้อตกลงอื่น ๆ อันเกี่ยวกับรายงานแสดงบัญชีการจัดการมรดกดังที่บัญญัติไว้ในมาตรา ๑๗๓๒ นั้น จะสมบูรณ์ต่อเมื่อรายงานแสดงบัญชีนั้นได้ส่งมอบล่วงหน้าแก่ทายาทพร้อมด้วยเอกสารอันเกี่ยวกับการนั้นไม่น้อยกว่าสิบวันก่อนแล้ว คดีเกี่ยวกับการจัดการมรดกนั้น มิให้ทายาทฟ้องเกินกว่าห้าปีนับแต่การจัดการมรดกสิ้นสุดลง"}},{"id":"TH-H004-A1734","no":1734,"noLabel":{"th":"มาตรา 1734"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๔ เจ้าหนี้กองมรดกชอบแต่จะได้รับการชำระหนี้จากทรัพย์สินในกองมรดกเท่านั้น"}},{"id":"TH-H004-A1735","no":1735,"noLabel":{"th":"มาตรา 1735"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๕ ทายาทจำต้องบอกทรัพย์มรดกและหนี้สินของผู้ตายตามที่ตนรู้ทั้งหมดแก่ผู้จัดการมรดก"}},{"id":"TH-H004-A1736","no":1736,"noLabel":{"th":"มาตรา 1736"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๖ ตราบใดที่เจ้าหนี้กองมรดก หรือผู้รับพินัยกรรมที่ปรากฏตัว ยังไม่ได้รับชำระหนี้ หรือส่วนได้ตามพินัยกรรมแล้วทุกคน ให้ถือว่าทรัพย์มรดกยังคงอยู่ในระหว่างจัดการ ในระหว่างเวลาเช่นว่านั้น ผู้จัดการมรดกชอบที่จะทำการใด ๆ ในทางจัดการตามที่จำเป็นได้ เช่นฟ้องคดีหรือแก้ฟ้องในศาลและอื่น ๆ อนึ่ง ผู้จัดการมรดกต้องทำการทุกอย่างตามที่จำเป็น เพื่อเรียกเก็บหนี้สินซึ่งค้างชำระอยู่แก่กองมรดกภายในเวลาอันเร็วที่สุดที่จะทำได้ และเมื่อเจ้าหนี้กองมรดกได้รับชำระหนี้แล้ว ผู้จัดการมรดกต้องทำการแบ่งปันมรดก"}},{"id":"TH-H004-A1737","no":1737,"noLabel":{"th":"มาตรา 1737"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๗ เจ้าหนี้กองมรดกจะบังคับสิทธิเรียกร้องต่อทายาทคนใดก็ได้ แต่ถ้ามีผู้จัดการมรดก ให้เจ้าหนี้เรียกเข้ามาในคดีด้วย"}},{"id":"TH-H004-A1738","no":1738,"noLabel":{"th":"มาตรา 1738"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๘ ก่อนแบ่งมรดก เจ้าหนี้กองมรดกจะบังคับชำระหนี้เต็มจำนวนจากกองมรดกก็ได้ ในกรณีเช่นนี้ทายาทคนหนึ่ง ๆ อาจเรียกให้ชำระหนี้จากทรัพย์มรดกของเจ้ามรดก หรือให้เอาเป็นประกันก็ได้จนถึงเวลาแบ่งมรดก เมื่อแบ่งมรดกแล้ว เจ้าหนี้อาจเรียกให้ทายาทคนใดคนหนึ่งชำระหนี้ได้เพียงไม่เกินทรัพย์มรดกที่ทายาทคนนั้นได้รับไป ในกรณีเช่นนี้ ทายาทคนใดซึ่งได้ชำระหนี้แก่เจ้าหนี้กองมรดกเกินกว่าส่วนที่ตนจะต้องเฉลี่ยใช้หนี้ ทายาทคนนั้นมีสิทธิไล่เบี้ยจากทายาทคนอื่นได้"}},{"id":"TH-H004-A1739","no":1739,"noLabel":{"th":"มาตรา 1739"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๓๙ ให้ชำระหนี้ที่กองมรดกค้างชำระตามลำดับต่อไปนี้ และตามบทบัญญัติแห่งประมวลกฎหมายนี้ว่าด้วยบุริมสิทธิ โดยต้องไม่เป็นที่เสื่อมเสียแก่บรรดาเจ้าหนี้ผู้มีบุริมสิทธิพิเศษตามประมวลกฎหมายนี้หรือกฎหมายอื่น และบรรดาเจ้าหนี้ที่มีประกันโดยการจำนำหรือการจำนอง (๑) ค่าใช้จ่ายเพื่อประโยชน์อันร่วมกันของกองมรดก (๒) ค่าใช้จ่ายในการทำศพเจ้ามรดก (๓) ค่าภาษีอากรซึ่งกองมรดกค้างชำระอยู่ (๔) ค่าจ้างซึ่งเจ้ามรดกค้างชำระแก่เสมียน คนใช้และคนงาน (๕) ค่าเครื่องอุปโภคบริโภคอันจำเป็นประจำวันซึ่งส่งให้แก่เจ้ามรดก (๖) หนี้สินสามัญของเจ้ามรดก (๗) บำเหน็จของผู้จัดการมรดก"}},{"id":"TH-H004-A1740","no":1740,"noLabel":{"th":"มาตรา 1740"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๔๐ เว้นแต่เจ้ามรดกหรือกฎหมายจะได้กำหนดไว้เป็นอย่างอื่น ให้จัดสรรทรัพย์สินของเจ้ามรดกเพื่อชำระหนี้ตามลำดับต่อไปนี้ (๑) ทรัพย์สินนอกจากอสังหาริมทรัพย์ (๒) อสังหาริมทรัพย์ซึ่งจัดสรรไว้ชัดแจ้งในพินัยกรรมว่าสำหรับชำระหนี้ถ้าหากว่ามีทรัพย์สินเช่นนั้น (๓) อสังหาริมทรัพย์ซึ่งทายาทโดยธรรมชอบที่จะได้รับในฐานะเช่นนั้น (๔) อสังหาริมทรัพย์ซึ่งเจ้ามรดกทำพินัยกรรมให้แก่ผู้ใดผู้หนึ่งโดยมีเงื่อนไขว่า ผู้นั้นต้องชำระหนี้ของเจ้ามรดก (๕) อสังหาริมทรัพย์ซึ่งเจ้ามรดกทำพินัยกรรมให้โดยลักษณะทั่วไปดังบัญญัติไว้ในมาตรา ๑๖๕๑ (๖) ทรัพย์สินเฉพาะอย่างซึ่งเจ้ามรดกทำพินัยกรรมให้โดยลักษณะเฉพาะดังบัญญัติไว้ในมาตรา ๑๖๕๑ ทรัพย์สินอย่างใดอย่างหนึ่งซึ่งได้จัดสรรไว้ตามความที่กล่าวมาแล้วข้างต้นนั้น ให้เอาออกขายทอดตลาด แต่ทายาทคนใดคนหนึ่งอาจมิให้มีการขายเช่นว่านั้นได้ โดยชำระราคาทรัพย์สินนั้นทั้งหมด หรือแต่บางส่วนตามที่ผู้ตีราคาซึ่งศาลตั้งขึ้นได้กำหนดให้ จนพอแก่จำนวนที่จะชำระหนี้ให้แก่เจ้าหนี้"}},{"id":"TH-H004-A1741","no":1741,"noLabel":{"th":"มาตรา 1741"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๔๑ เจ้าหนี้กองมรดกคนใดคนหนึ่ง จะคัดค้านการขายทอดตลาดหรือการตีราคาทรัพย์สินดังระบุไว้ในมาตราก่อน โดยเสียค่าใช้จ่ายของตนเองก็ได้ ถ้าเจ้าหนี้ได้ร้องคัดค้านแล้ว ยังได้กระทำการขายทอดตลาด หรือตีราคาไป จะยกการขายทอดตลาดหรือตีราคานั้นขึ้นยันต่อเจ้าหนี้ผู้ร้องคัดค้านแล้วนั้นหาได้ไม่"}},{"id":"TH-H004-A1742","no":1742,"noLabel":{"th":"มาตรา 1742"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๔๒ ถ้าในการชำระหนี้ซึ่งค้างชำระอยู่แก่ตน เจ้าหนี้คนใดคนหนึ่งได้รับตั้งในระหว่างที่ผู้ตายมีชีวิตอยู่ ให้เป็นผู้รับประโยชน์ในการประกันชีวิต เจ้าหนี้คนนั้นชอบที่จะได้รับเงินทั้งหมด ซึ่งได้ตกลงไว้กับผู้รับประกัน อนึ่ง เจ้าหนี้เช่นว่านั้น จำต้องส่งเบี้ยประกันภัยคืนเข้ากองมรดกก็ต่อเมื่อเจ้าหนี้คนอื่น ๆ พิสูจน์ได้ว่า (๑) การที่ผู้ตายชำระหนี้ให้แก่เจ้าหนี้โดยวิธีดังกล่าวมานั้นเป็นการขัดต่อบทบัญญัติมาตรา ๒๓๗ แห่งประมวลกฎหมายนี้ และ (๒) เบี้ยประกันภัยเช่นว่านั้น เป็นจำนวนสูงเกินส่วนเมื่อเทียบกับรายได้หรือฐานะของผู้ตาย ถึงอย่างไรก็ดี เบี้ยประกันภัยซึ่งจะพึงส่งคืนเข้ากองมรดกนั้นต้องไม่เกินกว่าจำนวนเงินที่ผู้รับประกันชำระให้"}},{"id":"TH-H004-A1743","no":1743,"noLabel":{"th":"มาตรา 1743"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๔๓ ทายาทโดยธรรม หรือผู้รับพินัยกรรมโดยลักษณะทั่วไปไม่จำต้องปฏิบัติตามข้อกำหนดในพินัยกรรม ลักษณะเฉพาะเกินกว่าจำนวนทรัพย์มรดกที่ตนได้รับ"}},{"id":"TH-H004-A1744","no":1744,"noLabel":{"th":"มาตรา 1744"},"chapter":{"th":"หมวด / หมวดที่ 2"},"text":{"th":"มาตรา ๑๗๔๔ ผู้จัดการมรดกไม่ต้องส่งมอบทรัพย์มรดกหรือส่วนใดส่วนหนึ่งแห่งทรัพย์มรดกให้แก่ทายาทก่อนปีหนึ่งนับแต่วันที่เจ้ามรดกถึงแก่ความตาย เว้นแต่เจ้าหนี้กองมรดกและผู้รับพินัยกรรมที่ปรากฏตัวได้รับชำระหนี้และส่วนได้ตามพินัยกรรมแล้วทุกคน"}},{"id":"TH-H004-A1745","no":1745,"noLabel":{"th":"มาตรา 1745"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔๕ ถ้ามีทายาทหลายคน ทายาทเหล่านั้นมีสิทธิและหน้าที่เกี่ยวกับทรัพย์มรดกร่วมกันจนกว่าจะได้แบ่งมรดกกันเสร็จแล้ว และให้ใช้มาตรา ๑๓๕๖ ถึงมาตรา ๑๓๖๖ แห่งประมวลกฎหมายนี้บังคับ เพียงเท่าที่ไม่ขัดกับบทบัญญัติแห่งบรรพนี้"}},{"id":"TH-H004-A1746","no":1746,"noLabel":{"th":"มาตรา 1746"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔๖ ภายใต้บังคับแห่งกฎหมาย หรือข้อความในพินัยกรรมถ้าหากมี ให้สันนิษฐานไว้ก่อนว่า ผู้เป็นทายาทด้วยกันมีส่วนเท่ากันในกองมรดกที่ยังไม่ได้แบ่ง"}},{"id":"TH-H004-A1747","no":1747,"noLabel":{"th":"มาตรา 1747"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔๗ การที่ทายาทคนใดได้รับทรัพย์สินอย่างหนึ่งอย่างใด หรือประโยชน์อย่างอื่นใดจากเจ้ามรดกโดยการให้ หรือโดยการอย่างอื่นใด ซึ่งทำให้โดยเสน่หาในระหว่างเวลาที่เจ้ามรดกยังมีชีวิตอยู่นั้น หาทำให้สิทธิในการแบ่งปันทรัพย์มรดกของทายาทคนนั้น ต้องเสื่อมเสียไปแต่โดยประการใดไม่"}},{"id":"TH-H004-A1748","no":1748,"noLabel":{"th":"มาตรา 1748"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔๘ ทายาทคนใดครอบครองทรัพย์มรดกซึ่งยังมิได้แบ่งกัน ทายาทคนนั้นมีสิทธิที่จะเรียกร้องให้แบ่งทรัพย์มรดกนั้นได้ แม้ว่าจะล่วงพ้นกำหนดอายุความตามมาตรา ๑๗๕๔ แล้วก็ดี สิทธิที่จะเรียกให้แบ่งทรัพย์มรดกตามวรรคก่อน จะตัดโดยนิติกรรมเกินคราวละสิบปีไม่ได้"}},{"id":"TH-H004-A1749","no":1749,"noLabel":{"th":"มาตรา 1749"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๔๙ ถ้ามีคดีฟ้องเรียกทรัพย์มรดก ผู้ซึ่งอ้างว่าตนเป็นทายาทมีสิทธิในทรัพย์มรดกนั้น จะร้องสอดเข้ามาในคดีก็ได้ แต่ศาลจะเรียกทายาทอื่น นอกจากคู่ความ หรือผู้ร้องสอด ให้เข้ามารับส่วนแบ่ง หรือกันส่วนแห่งทรัพย์มรดกไว้เพื่อทายาทอื่นนั้นไม่ได้"}},{"id":"TH-H004-A1750","no":1750,"noLabel":{"th":"มาตรา 1750"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๕๐ การแบ่งปันทรัพย์มรดกนั้น อาจทำได้โดยทายาทต่างเข้าครอบครองทรัพย์สินเป็นส่วนสัด หรือโดยการขายทรัพย์มรดกแล้วเอาเงินที่ขายได้มาแบ่งปันกันระหว่างทายาท ถ้าการแบ่งปันมิได้เป็นไปตามวรรคก่อน แต่ได้ทำโดยสัญญา จะฟ้องร้องให้บังคับคดีหาได้ไม่ เว้นแต่จะมีหลักฐานเป็นหนังสืออย่างหนึ่งอย่างใด ลงลายมือชื่อฝ่ายที่รับผิดหรือตัวแทนของฝ่ายนั้นเป็นสำคัญ ในกรณีเช่นนี้ให้นำมาตรา ๘๕๐ มาตรา ๘๕๒ แห่งประมวลกฎหมายนี้ว่าด้วยประนีประนอมยอมความมาใช้บังคับโดยอนุโลม"}},{"id":"TH-H004-A1751","no":1751,"noLabel":{"th":"มาตรา 1751"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๕๑ ภายหลังที่ได้แบ่งมรดกกันแล้ว ถ้าทรัพย์สินทั้งหมดหรือบางส่วน ซึ่งทายาทคนใดคนหนึ่งได้รับตามส่วนแบ่งปันนั้น หลุดมือไปจากทายาทคนนั้นเนื่องจากการรอนสิทธิ ทายาทคนอื่น ๆ จำต้องใช้ค่าทดแทน หนี้เช่นว่านั้น เป็นอันระงับเมื่อมีการตกลงกันไว้เป็นอย่างอื่น หรือการรอนสิทธิเป็นผลเนื่องมาจากความผิดของทายาทผู้ถูกรอนสิทธิ หรือเนื่องมาจากเหตุซึ่งเกิดขึ้นภายหลังการแบ่งปัน ทายาทคนอื่น ๆ ต้องใช้ค่าทดแทนให้แก่ทายาทผู้ถูกรอนสิทธิตามส่วนแห่งส่วนแบ่งของตน แต่ให้หักจำนวนที่เป็นส่วนเฉลี่ย ซึ่งทายาทผู้ถูกรอนสิทธิจะต้องออกกับเขาด้วยนั้นออกเสีย แต่ถ้าทายาทคนใดคนหนึ่งเป็นคนหนี้สินล้นพ้นตัว ทายาทคนอื่น ๆ ต้องรับผิดในส่วนของทายาทคนนั้นตามส่วนเฉลี่ยเช่นเดียวกัน แต่ให้หักจำนวนที่เป็นส่วนเฉลี่ยซึ่งทายาทผู้ที่จะได้รับค่าทดแทนจะต้องออกแทนทายาทผู้ที่มีหนี้สินล้นพ้นตัวนั้นออกเสีย บทบัญญัติในวรรคก่อน ๆ มิให้ใช้บังคับแก่ผู้รับพินัยกรรมลักษณะเฉพาะ"}},{"id":"TH-H004-A1752","no":1752,"noLabel":{"th":"มาตรา 1752"},"chapter":{"th":"หมวด / หมวดที่ 3"},"text":{"th":"มาตรา ๑๗๕๒ คดีฟ้องให้รับผิดเนื่องจากการรอนสิทธิตามมาตรา ๑๗๕๑ นั้น มิให้ฟ้องเมื่อพ้นกำหนดสามเดือนนับแต่เมื่อถูกรอนสิทธิ"}},{"id":"TH-H004-A1753","no":1753,"noLabel":{"th":"มาตรา 1753"},"chapter":{"th":"ลักษณะ 5"},"text":{"th":"มาตรา ๑๗๕๓ ภายใต้บังคับแห่งสิทธิของเจ้าหนี้กองมรดก เมื่อบุคคลใดถึงแก่ความตายโดยไม่มีทายาทโดยธรรมหรือผู้รับพินัยกรรม หรือการตั้งมูลนิธิตามพินัยกรรมมรดกของบุคคลนั้นตกทอดแก่แผ่นดิน"}},{"id":"TH-H004-A1754","no":1754,"noLabel":{"th":"มาตรา 1754"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๗๕๔ ห้ามมิให้ฟ้องคดีมรดกเมื่อพ้นกำหนดหนึ่งปี นับแต่เมื่อเจ้ามรดกตาย หรือนับแต่เมื่อทายาทโดยธรรมได้รู้ หรือควรได้รู้ถึงความตายของเจ้ามรดก คดีฟ้องเรียกตามข้อกำหนดพินัยกรรม มิให้ฟ้องเมื่อพ้นกำหนดหนึ่งปีนับแต่เมื่อผู้รับพินัยกรรมได้รู้หรือควรได้รู้ถึงสิทธิซึ่งตนมีอยู่ตามพินัยกรรม ภายใต้บังคับแห่งมาตรา ๑๙๓/๒๗ แห่งประมวลกฎหมายนี้ ถ้าสิทธิเรียกร้องของเจ้าหนี้อันมีต่อเจ้ามรดกมีกำหนดอายุความยาวกว่าหนึ่งปี มิให้เจ้าหนี้นั้นฟ้องร้องเมื่อพ้นกำหนดหนึ่งปีนับแต่เมื่อเจ้าหนี้ได้รู้ หรือควรได้รู้ถึงความตายของเจ้ามรดก ถึงอย่างไรก็ดี สิทธิเรียกร้องตามที่ว่ามาในวรรคก่อน ๆ นั้น มิให้ฟ้องร้องเมื่อพ้นกำหนดสิบปีนับแต่เมื่อเจ้ามรดกตาย"}},{"id":"TH-H004-A1755","no":1755,"noLabel":{"th":"มาตรา 1755"},"chapter":{"th":"ลักษณะ 6"},"text":{"th":"มาตรา ๑๗๕๕ อายุความหนึ่งปีนั้น จะยกขึ้นต่อสู้ได้ก็แต่โดยบุคคลซึ่งเป็นทายาท หรือบุคคลซึ่งชอบที่จะใช้สิทธิของทายาท หรือโดยผู้จัดการมรดก"}}],"pack":"th-p01"};
  FT["TH-H008"] = {"id":"TH-H008","coverage":"full","language":"en","sourceName":"泰国官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":72,"structureMode":"ARTICLE","title":{"zh":"争议调解法","en":"DISPUTE MEDIATION ACT, B.E. 2562 (2019)","orig":null},"level":"law","status":"active","issuingBody":"泰国官方发布渠道","promulgatedDate":"2019","completenessNote":"自 2026-10-06 全库备份回流（_work/_backup_20261006/data/TH-H008.json）；条文逐字取自该备份，未改写、未补全；原始来源见 source 字段。","country":"TH","countryName":"泰国","layer":"intl","articles":[{"id":"TH-H008-A1","no":1,"noLabel":{"en":"Article 1"},"text":{"en":"This Act is called the “Dispute Medication Act, B.E. 2562 (2019)”."}},{"id":"TH-H008-A2","no":2,"noLabel":{"en":"Article 2"},"text":{"en":"1  This Act shall come into force as from the day following the date of \nits publication in the Government Gazette except that the provisions of Chapter II, Civil Dispute \nMediation, Chapter III, Criminal Dispute Mediation, Chapter IV, Criminal Dispute Mediation at the \nInquiry Stage, and Chapter V, Public Sector Dispute Mediation, shall come into force after one \nhundred eighty days as from the date of its publication in the Government Gazette."}},{"id":"TH-H008-A3","no":3,"noLabel":{"en":"Article 3"},"heading":{"en":"In this Act:"},"text":{"en":"“dispute mediation” means the operation intended to provide parties with an \nopportunity to agree to resolve civil and criminal disputes by a peaceful means and without \nadjudication of the disputes, excluding the mediation of disputes conducted at the court stage \nand at the execution stage; \n  “mediator” means a person registered and appointed for performing duties in \nthe dispute mediation; \n  “setlement agreement” means an agreement agreed by the parties to be legally \nbinding for resolving any dispute or claim of each party and to give each party rights, duties or \nliabilities only to the extent provided therein;  \n  “agency conducting the dispute mediation” means a State agency carrying out \nthe dispute resolution by dispute mediation; \n  “State agency” means the central administration, the provincial administration, \nthe Office of the Judiciary, the Office of the Attorney-General or any other agency of the State \nas prescribed by the Minister of Justice in the Ministerial Regulation; \n  “Registrar” means the head of the State agency conducting the dispute \nmediation."}},{"id":"TH-H008-A4","no":4,"noLabel":{"en":"Article 4"},"text":{"en":"This Act has no prejudice to the dispute mediation by State agencies \ncarried out in accordance with their duties and powers. \n                                                        \n  1 Published in Government Gazette, Vol. 136, Part 67a, dated 22 nd  May 2019. \n3 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  State agencies under paragraph one may conduct the dispute mediation in \naccordance with this Act."}},{"id":"TH-H008-A5","no":5,"noLabel":{"en":"Article 5"},"text":{"en":"A State agency which intends to conduct the dispute mediation \nunder this Act shall also notify it to the Ministry of Justice."}},{"id":"TH-H008-A6","no":6,"noLabel":{"en":"Article 6"},"heading":{"en":"In the case where the dispute mediation terminates without"},"text":{"en":"achieving a successful result, if it appears that a period of prescription has expired during the \ndispute mediation or is due to expire within sixty days as from the date on which the dispute \nmediation terminates, the period of prescription shall be extended for another sixty days as \nfrom the date on which the dispute mediation terminates. \n  In the case where the Court gives an order refusing to enforce the settlement \nagreement under section 33, the provisions of paragraph one shall apply mutatis mutandis . For \nthis purpose, the sixty-day period shall be counted as from the date on which the order of the \nCourt becomes final."}},{"id":"TH-H008-A7","no":7,"noLabel":{"en":"Article 7"},"text":{"en":"The President of the Supreme Court, the Prime Minister, the Minister \nof Defence, the Minister of Interior, the Minister of Justice and the Attorney-General shall have \ncharge and control of the execution of this Act in respect of the matters that are concerned \nwith their duties and powers. \n  The President of the Supreme Court shall have the power to issue Rules of Court \nand the Prime Minister, the Minister of Defence, the Minister of Interior and the Minister of \nJustice shall have the power to issue Ministerial Regulations and Rules while the Attorney-\nGeneral shall have the power to issue Regulations, in the execution of this Act. \n  Such Rules of Court, Ministerial Regulations, Rules and Regulations shall come \ninto force upon their publication in the Government Gazette."}},{"id":"TH-H008-A8","no":8,"noLabel":{"en":"Article 8"},"text":{"en":"This Act shall not apply to criminal cases falling under the jurisdiction \nof the Juvenile and Family Courts under the law on Juvenile and Family Courts and juvenile \nand family procedures. \n \n \n4 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nCHAPTER I \nMEDIATORS  \n_______________"}},{"id":"TH-H008-A9","no":9,"noLabel":{"en":"Article 9"},"text":{"en":"A person intending to be registered as a mediator shall submit an \napplication to the Registrar. \n  The Registrar shall also have the power to select persons suitable for being \nregistered as mediators, provided that consent shall be obtained from such persons. \n  The submission of applications for registration, the issuance of certificates of \nregistration, the renewal of certificates of registration, the issuance of substitutes for certificates \nof registration, the declaration of particulars in the submission of applications for registration \nand the forms of identification cards for mediators shall be in accordance with the rules, \nprocedures and conditions prescribed in the Notification of the Registrar. \n  The removal of mediators, termination of the status of mediators and revocation \nof the status of mediators shall be in accordance with the rules, procedures and conditions \nprescribed by the Minister of Justice in the Ministerial Regulation."}},{"id":"TH-H008-A10","no":10,"noLabel":{"en":"Article 10"},"text":{"en":"A person registered as a mediator must have the qualifications and \nmust not be under the prohibitions as follows: \n  a. Qualifications: \n   (1) having successfully completed the dispute mediation training under \nthe programme accredited by the Commission on National Development of Justice \nAdministration under the law on national development of justice administration; \n   (2) being a person possessing experience in areas beneficial to the dispute \nmediation; \n  b. Prohibitions: \n   (1) having been sentenced to imprisonment by a final judgment, except \nfor an offence committed through negligence or a petty offence; \n5 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n   (2) being an incompetent person, a quasi -incompetent person or a person \nof unsound mind or mental infirmity; \n   (3) having had the status of a mediator revoked under this Act, where a \nperiod of five years has not yet elapsed up to the date of submission of the application for a \ncertificate of registration as a mediator."}},{"id":"TH-H008-A11","no":11,"noLabel":{"en":"Article 11"},"heading":{"en":"A mediator has the duties and powers as follows:"},"text":{"en":"(1) to lay down directions for and hold dispute mediation; \n  (2) to assist, facilitate and make suggestions to parties with respect to ways for \nending disputes; \n  (3) to conduct mediation on the basis of impartiality; \n  (4) to prepare a settlement agreement in accordance with the results of the \ndispute mediation. \n  In the case where a mediator carries out an act in discharge of duties in good \nfaith, the mediator shall be afforded protection and shall not be liable both in civil matters and \nin criminal matters."}},{"id":"TH-H008-A12","no":12,"noLabel":{"en":"Article 12"},"heading":{"en":"A mediator shall observe ethics as follows:"},"text":{"en":"(1) performing duties on the basis of impartiality, independence, justice and non-\ndiscrimination; \n  (2) attending the dispute mediation on every occasion and, in the case of \ninability to attend the dispute mediation, giving prior notification of reasons and necessity \ntherefor to the agency conducting the dispute mediation for information; \n  (3) performing duties expeditiously without causing unreasonable delay in the \ndispute mediation; \n  (4) upholding integrity and honesty and refraining from demanding or taking \nproperty or any other benefit from parties or other persons involved in the dispute; \n  (5) performing the dispute mediation duties politely; \n  (6) keeping confidentiality of matters relating to the dispute mediation; \n6 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  (7) refraining from an act in a manner adjudicating the dispute or forcing any \nparty to sign a settlement agreement; \n  (8) other cases prescribed by the Minister of Justice in the Ministerial Regulation."}},{"id":"TH-H008-A13","no":13,"noLabel":{"en":"Article 13"},"text":{"en":"A mediator shall disclose to the parties facts likely to give rise to \njustifiable doubts as to the mediator’s impartiality and independence in the performance of \nduties as the mediator, in particular, the facts as to the relationship with any party in the \nfollowing matters: \n  (1) being the fiancé or the spouse;  \n  (2) being an ascendant or a descendant in any degree or being a brother or sister \nor a cousin within only three degrees or being a relative by marriage within only two degrees; \n  (3) being or having previously been a legal representative or a curator or a \nrepresentative or an agent; \n  (4) being a creditor or a debtor or being an employer or an employee."}},{"id":"TH-H008-A14","no":14,"noLabel":{"en":"Article 14"},"heading":{"en":"A mediator may be addressed by a party a challenge of such a"},"text":{"en":"serious nature as to be likely to give rise to the impartial or independent performance of duties. \nIn the case of such circumstance, the mediator may be removed under section 15 (4). \n  In the case where any party consists of several persons, the addressing of a \nchallenge under paragraph one shall be made upon consent of all persons forming such party."}},{"id":"TH-H008-A15","no":15,"noLabel":{"en":"Article 15"},"heading":{"en":"A mediator may be removed by any party or both parties or an"},"text":{"en":"agency conducting the dispute mediation on the following grounds: \n  (1) exerting fraud or duress on a party or other persons involved in the dispute; \n  (2) failing to perform the duty as a mediator on more than two occasions without \nany reasonable cause; \n  (3) ethical deficiency under section 12; \n  (4) being addressed a challenge under section 14."}},{"id":"TH-H008-A16","no":16,"noLabel":{"en":"Article 16"},"text":{"en":"In the dispute medication, a mediator shall not carry out any act, or \ncause it to be carried out, in a manner of exerting coercion, a threat or a deceit or carry out an \n7 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nillegitimate act in any manner whatsoever in order to induce parties to conclude a settlement \nagreement."}},{"id":"TH-H008-A17","no":17,"noLabel":{"en":"Article 17"},"heading":{"en":"The status as a mediator terminates upon:"},"text":{"en":"(1) death; \n  (2) resignation; \n  (3) termination of the status of a mediator or revocation of the status of a \nmediator; \n  (4) being disqualified or being under prohibitions under section 10."}},{"id":"TH-H008-A18","no":18,"noLabel":{"en":"Article 18"},"text":{"en":"In the case where a mediator is removed or the status of a mediator \nterminates when the dispute mediation is in progress, the parties may appoint a new mediator \nfor further performing the duty of mediating such dispute and, for this purpose, documents in \nthe dispute mediation proceedings previously conducted may be relied on as the parties and \nthe new mediator deem appropriate."}},{"id":"TH-H008-A19","no":19,"noLabel":{"en":"Article 19"},"text":{"en":"In the performance of duties of a mediator in an agency conducting \nthe dispute mediation, the mediator shall receive remuneration and other allowances necessary \nfor the conduct of the dispute mediation, in accordance with the Rule prescribed by the \nMinister of Justice with the approval of the Ministry of Finance. \nCHAPTER II \nCIVIL DISPUTE MEDIATION  \n_______________ \nPART I \nCIVIL DISPUTE MEDIATION PROCEEDINGS  \n_______________"}},{"id":"TH-H008-A20","no":20,"noLabel":{"en":"Article 20"},"text":{"en":"Civil dispute mediation under this Act is not permissible if it relates \nto a right as regards personality, a family right or ownership in immovable property. \n  Civil dispute mediation is permissible in the following cases: \n8 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  (1) a dispute which is concerned with land other than disputes relating to \nownership; \n  (2) a dispute between heirs which is concerned with property to be obtained by \nway of succession; \n  (3) other disputes as prescribed in the Royal Decree; \n  (4) a dispute, other than those in (1), (2) and (3), of which the amount of claim \ndoes not exceed five million Baht or does not exceed such amount as prescribed in the Royal \nDecree."}},{"id":"TH-H008-A21","no":21,"noLabel":{"en":"Article 21"},"text":{"en":"If any party intends to have the dispute mediation, the party shall \nsubmit an application to an agency conducting the dispute mediation. \n  The agency conducting the dispute mediation shall seek the other party’s \nwillingness to engage in the dispute mediation. \n  If the other party is not willing to engage in the dispute mediation proceedings, \nthe agency conducting the dispute mediation shall dismiss the application for the mediation of \nsuch dispute and notify it to the party submitting the application therefor. \n  In the case where there are more than two parties and any party is not willing to \nengage in the dispute mediation, the dispute mediation may be conducted amongst the parties \nwilling to engage therein. \n  The submission of an application for the dispute mediation, details of the \napplication and a period of time for the consideration of an application for the dispute \nmediation shall be in accordance with the rules, procedures and conditions prescribed in the \nNotification of the agency conducting the mediation."}},{"id":"TH-H008-A22","no":22,"noLabel":{"en":"Article 22"},"text":{"en":"The parties shall agree to appoint one or more mediators from a list \nof mediators prepared by the agency conducting the mediation. If the parties fail to agree on \nthe appointment of mediators, the parties may request the agency conducting the mediation to \nappoint mediators from such list, in accordance with the Rule prescribed by the agency \nconducting the mediation. \n  The appointment of mediators under paragraph one shall be made upon \nconsent of persons to be appointed. The agency conducting the mediation shall give the parties \n9 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nexplanations on proceedings and legal consequences in relation to the dispute mediation and \nthe right to terminate the dispute mediation."}},{"id":"TH-H008-A23","no":23,"noLabel":{"en":"Article 23"},"text":{"en":"When there exists a fact likely to give rise to justifiable doubts as to \nthe mediator’s impartiality or independence in the performance of duties as a mediator under \nsection 13 and any party makes a challenge thereto or the mediator himself considers that he is \nin such circumstance, the mediator shall cease the dispute mediation for the time being and \nnotify it to the agency conducting the mediation in order for orders to be further issued by the \nhead of the agency conducting the mediation. \n  The submission of a challenge, the consideration of a challenge and the \nreplacement of the challenged mediator by another mediator shall be in accordance with the \nrules, procedures and condition prescribed by the Minister of Justice in the Ministerial \nRegulation."}},{"id":"TH-H008-A24","no":24,"noLabel":{"en":"Article 24"},"heading":{"en":"Subject to section 33, when a memorandum of settlement"},"text":{"en":"agreement is made under section 30, if it thereafter appears that the mediator has failed to \ndisclose a fact likely to give rise to justifiable doubts as to the mediator’s impartiality or \nindependence under section 13 or that the appointment of the mediator is unlawful, such \nmemorandum of agreement is not prejudiced but this shall not preclude the right of the party \nto prove in order for the Court to issue an order refusing to enforce such agreement."}},{"id":"TH-H008-A25","no":25,"noLabel":{"en":"Article 25"},"text":{"en":"Dispute mediation shall be conducted continuously and completed \nexpeditiously. In this regard, the mediator may also agree with the parties on the timeframe and \nplans for the conduct of the dispute mediation. \n  In the dispute mediation, when the mediator has asked facts concerning the \ndispute, intentions of the parties to resolve the dispute and other facts relating to the dispute \nmediation, the mediator shall give explanations to the parties with a view to their understanding \neach other or mutual leniency conducive to their successful resolution of the dispute."}},{"id":"TH-H008-A26","no":26,"noLabel":{"en":"Article 26"},"text":{"en":"The mediator shall conduct the dispute mediation in the presence \nof all parties except that, for the purpose of the dispute mediation in certain situations, the \nmediator may conduct the dispute mediation without the presence of a party, provided that \nthe mediator shall also notify the conduct of such dispute mediation to the party not present. \n10 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  The mediator may also permit a party’s lawyers or counsellors or any person to \nattend the dispute mediation."}},{"id":"TH-H008-A27","no":27,"noLabel":{"en":"Article 27"},"text":{"en":"While the dispute mediation is in progress, any party has the right to \nwithdraw from the dispute mediation by giving written notification thereof to the mediator."}},{"id":"TH-H008-A28","no":28,"noLabel":{"en":"Article 28"},"text":{"en":"In the dispute mediation, the parties have the right to enter into \nnegotiations with a view to reaching mutual agreement freely, provided that such agreement \nshall not be expressly prohibited by law, impossible or contrary to public order or good morals."}},{"id":"TH-H008-A29","no":29,"noLabel":{"en":"Article 29"},"text":{"en":"The following facts arising from the dispute mediation proceedings \nshall not be admissible into evidence in the conduct of judicial proceedings, arbitral \nproceedings or any other proceedings except for the purpose of the enforcement of a \nsettlement agreement: \n  (1) the parties’ intention or willingness to engage in the dispute mediation;  \n  (2) views or suggestions on ways or means for mediating the dispute of the parties; \n  (3) admissions or statements made by the parties in the course of the dispute \nmediation; \n  (4) any proposals made by the mediator; \n  (5) facts indicating the willingness to accept a proposal in the dispute mediation; \n  (6) documents which are prepared solely for the purposes of use, or which are \nsolely used, in the dispute mediation. \n  Any existing evidence or fact which is otherwise admissible into evidence in \njudicial proceedings, arbitral proceedings or any other proceedings does not become \ninadmissible under paragraph one as a consequence of its use by any party in the dispute \nmediation."}},{"id":"TH-H008-A30","no":30,"noLabel":{"en":"Article 30"},"heading":{"en":"When parties have reached any agreement, the mediator shall"},"text":{"en":"prepare a memorandum of agreement for the dispute mediation or cause a memorandum of \nsettlement agreement to be prepared in writing. For this purpose, the parties and the mediator \nshall enter signatures thereon. \n11 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  The memorandum of agreement under paragraph one shall at least contain \ndetails as follows: \n  (1) names and addresses of the parties; \n  (2) the dispute under the law; \n  (3) willingness to engage in the dispute mediation; \n  (4) the fundamental substance of the agreement in consequence of the dispute \nmediation, such as compensation for damage, conditions requiring the parties’ compliance or \nforbearance, a period of time for taking action or the agreement to waive compensation for \ndamage."}},{"id":"TH-H008-A31","no":31,"noLabel":{"en":"Article 31"},"text":{"en":"Dispute mediation proceedings terminate in the cases as follows: \n  (1) the parties have concluded a settlement agreement; \n  (2) a party withdraws from the dispute mediation under section 27;  \n  (3) the mediator considers that further conduct of the dispute mediation is not \nuseful and directs termination of the dispute mediation. \nPART II \nENFORCEMENT OF A DISPUTE RESOLUTION AGREEMENT \n_______________"}},{"id":"TH-H008-A32","no":32,"noLabel":{"en":"Article 32"},"heading":{"en":"When a party has demanded the other party to perform the"},"text":{"en":"settlement agreement but the party against whom the demand is made fails to perform the \nsettlement agreement, the party making the demand may file with the Court a request for the \nenforcement of the settlement agreement. \n  A request under paragraph one shall be made within three years as from the \ndate on which a settlement agreement is enforceable. If a request is not made within such time \nlimit, the obligation forming the basis of such settlement agreement shall be extinguished. \n  A request under paragraph one shall be filed with the Court of Justice in whose \njurisdiction the settlement agreement is concluded or the Court of Justice in whose jurisdiction \nany party has a domicile or the Court of Justice which has jurisdiction to try and adjudicate the \n12 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \ndispute to which the mediation relates and shall be subject to payment of the Court fee under \nthe Civil Procedure Code at the same rate as that applicable to a request to the Court for the \nenforcement of a domestic arbitral award."}},{"id":"TH-H008-A33","no":33,"noLabel":{"en":"Article 33"},"text":{"en":"The Court shall issue an order for the enforcement of a settlement \nagreement unless it is apparent to the Court, or the party against whom the agreement is \nintended to be enforced proves, that: \n  (1) either party has deficiency as regards the capacity to conclude the settlement \nagreement; \n  (2)  a ground of the dispute or the settlement agreement is, in essence, expressly \nprohibited by law, impossible or contrary to public order or good morals; \n  (3) the settlement agreement has been procured by fraud, coercion, a threat or \nan otherwise unlawful act;    \n  (4) there exists an incidence as regards the appointment of the mediator under \nsection 24 which materially affects the preparation of the memorandum of agreement. \n  An order of the Court under paragraph one shall not be appealed against unless: \n  (1) the Court issues an order refusing to enforce the settlement agreement; \n  (2) the Court issues an order in derogation from the settlement agreement; \n  (3) the Court issues an order enforcing the settlement agreement in violation of \nparagraph one. \n  A decision or an order of the Court at the appellate stage shall be final."}},{"id":"TH-H008-A34","no":34,"noLabel":{"en":"Article 34"},"text":{"en":"The President of the Supreme Court, with the approval of a general \nassembly of the Supreme Court, has the power to issue Rules of Court concerning the filing of a \nrequest and the enforcement of a settlement agreement under section 32 and the issuance of \nan order under section 33. In this regard, the provisions of the Civil Procedure Code shall apply \nmutatis mutandis  to matters other than those provided in this Act. \n \n \n13 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nCHAPTER III \nCRIMINAL DISPUTE MEDIATION \n_______________"}},{"id":"TH-H008-A35","no":35,"noLabel":{"en":"Article 35"},"text":{"en":"Criminal dispute mediation is permissible in the following cases: \n  (1) compoundable offences; \n  (2) petty offences under section 390, section 391, section 392, section 393, \nsection 394, section 395 and section 397 of the Penal Code and other petty offences not \naffecting the public as prescribed in the Royal Decree.   \n  In the dispute mediation under paragraph one, when the parties have concluded \na criminal settlement agreement, it shall be deemed that the right to institute a criminal action \nis extinguished only in respect of the parties that have concluded such agreement."}},{"id":"TH-H008-A36","no":36,"noLabel":{"en":"Article 36"},"text":{"en":"In the conduct of the criminal dispute mediation, if the case is being \npursued at the stage of inquiries or legal proceedings by the inquiry official, the Public \nProsecutor or the Court, an agency conducting the dispute mediation or the Rights and Liberties \nProtection Department which has the duties and powers to exercise superintendence of the \ndispute mediation by a public-sector dispute mediation centre shall notify it to the inquiry \nofficial, the Public Prosecutor or the Court, as the case may be. The inquiry official, the Public \nProsecutor or the Court may stay the inquiry, the delivery of orders for the case or the trial or \nadjudication of the case, as the case may be, for the time being until the result of the dispute \nmediation is known. \n  When the criminal dispute mediation ends, the agency conducting the dispute \nmediation or the Rights and Liberties Protection Department shall notify the result of the \ndispute mediation to the inquiry official, the Public Prosecutor or the Court. In the case where \nthe parties have successfully reached a criminal settlement agreement, a copy of a \nmemorandum of such agreement shall also be furnished. \n  In the case where the criminal dispute mediation is unsuccessful, the inquiry \nofficial, the Public Prosecutor or the Court shall further proceed with the inquiries, the delivery \nof orders for the case or the trial and adjudication of the case. \n14 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H008-A37","no":37,"noLabel":{"en":"Article 37"},"text":{"en":"If the parties have concluded an agreement for settlement of a \ncriminal dispute in respect of which any party may have the right to institute a civil action \nconnected with a criminal action under the Criminal Procedure Code, the right to institute a \ncriminal action shall be extinguished when the parties have already performed the settlement \nagreement in respect of the civil matters. In the case where any party fails to perform the \nsettlement agreement in respect of the civil matters, the other party may take action in making \na request for the enforcement of the settlement agreement under section 32. \n  In the case under paragraph one where a settlement agreement allows any party \nto have the benefit of the time for the performance of the agreement, the provisions of section \n6 shall apply in the case where such party fails to perform the agreement."}},{"id":"TH-H008-A38","no":38,"noLabel":{"en":"Article 38"},"text":{"en":"In the case where the provisions of this Chapter do not provide any \nparticular proceeding in a criminal dispute mediation, the provisions of Chapter II, Civil Dispute \nMediation, shall apply to the criminal dispute mediation mutatis mutandis . \nCHAPTER IV \nCRIMINAL DISPUTE MEDIATION AT THE INQUIRY STAGE \n_______________ \nPART I \nGENERAL PROVISIONS \n_______________"}},{"id":"TH-H008-A39","no":39,"noLabel":{"en":"Article 39"},"heading":{"en":"In this Chapter:"},"text":{"en":"“criminal dispute mediation” means the criminal dispute mediation at the \ninquiry stage, whereby the inquiry official provides the parties to a criminal case with \nopportunities to negotiate, reach agreement or provide remedies for damage, with a view to \nextinguishing the criminal case; \n  “parties” means the alleged offender and the injured person in a criminal case, \nexcluding a criminal case in respect of which the State or a State agency is the injured person. \n15 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H008-A40","no":40,"noLabel":{"en":"Article 40"},"text":{"en":"When the inquiry official who is competent to issue orders has \nissued an order for the criminal dispute mediation under section 44, a period of prescription for \ntaking criminal proceedings shall cease to run and when the inquiry official who is competent to \nissue orders has issued an order for further pursuing legal proceedings under section 61, the \nperiod of prescription for taking legal proceedings shall rerun as from such time. \n  Inquiry officials who are competent to issue orders for criminal dispute mediation \nshall be in accordance with the Rule prescribed by the Commissioner-General of the Royal Thai \nPolice, Permanent Secretary for Defence, Permanent Secretary for Interior or Permanent \nSecretary for Justice or the Regulation prescribed by the Attorney-General, as the case may be. \n  For the purpose of criminal dispute mediation, if there is no circumstantial risk of \nan escape by the alleged offender, the provisions on prosecution and postponement of \nprosecution under the law on the establishment of Khwaeng  Courts and Criminal Procedures in \nKhwaeng  Courts and the custody as well as detention under the Criminal Procedure Code shall \nnot apply until the inquiry official who is competent to issue orders issues an order for taking \nfurther legal proceedings and the period of time for prosecution, postponement of prosecution, \ncustody and detention shall commence as from such time. \n  In the case under paragraph three, if the alleged offender is granted a provisional \nrelease at the inquiry stage, the provisions on the period of time under section 113 of the \nCriminal Procedure Code shall not apply."}},{"id":"TH-H008-A41","no":41,"noLabel":{"en":"Article 41"},"text":{"en":"Criminal dispute mediation at the inquiry stage is permissible in \ncases involving offences as follows: \n  (1) cases involving compoundable offences; \n  (2) cases involving petty offences under section 390, section 391, section 392, \nsection 393, section 394, section 395 and section 397 of the Penal Code and other petty \noffences not affecting the public as prescribed in the Royal Decree; \n  (3) offences punishable with maximum imprisonment term not exceeding three \nyears as specified in the Schedule annexed to this Act. \n \n16 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H008-A42","no":42,"noLabel":{"en":"Article 42"},"text":{"en":"Cases involving offences under section 41 (3) must be cases in \nwhich: \n  (1) the alleged offender has never undergone criminal dispute medication under \nthis Act except for cases involving offences committed through negligence or petty offences, \nwhere a period exceeding three years has elapsed as from the order for discontinuance of the \nproceedings; and \n  (2) the alleged offender is not serving a sentence for imprisonment by a final \njudgment or has been released from the punishment for a period exceeding five years, except \nfor cases involving offences committed through negligence, cases involving petty offences or \ncases involving offences committed at the time when the offender is below eighteen years of \nage."}},{"id":"TH-H008-A43","no":43,"noLabel":{"en":"Article 43"},"text":{"en":"In a case capable of criminal dispute mediation, the inquiry official \nshall, at the earliest opportunity, inform the parties of their right to request for criminal dispute \nmediation."}},{"id":"TH-H008-A44","no":44,"noLabel":{"en":"Article 44"},"text":{"en":"When both parties are willing and intend to engage in criminal \ndispute mediation and the case concerned is not pending trial of the Court, the parties shall \nsubmit a request for criminal dispute mediation to the inquiry official. The inquiry official shall \nissue an opinion thereon. If the inquiry official who is competent to issue orders is of the \nopinion that the circumstances of the commission of the offence are not serious and do not \nhave severe impacts on the society as a whole, an order shall be issued for criminal dispute \nmediation. \n  The submission of a request for criminal dispute mediation, the consideration \nand a period of time for decision upon the request and proceedings for criminal dispute \nmediation under the provisions of this Chapter shall be in accordance with the rules, \nprocedures and conditions in the Rule prescribed by the Commissioner-General of the Royal \nThai Police, Permanent Secretary for Defence, Permanent Secretary for Interior or Permanent \nSecretary for Justice or the Regulation prescribed by the Attorney-General, as the case may be."}},{"id":"TH-H008-A45","no":45,"noLabel":{"en":"Article 45"},"text":{"en":"In the case where there are several injured persons, the injured \npersons engaging in criminal dispute mediation must be willing and intend to engage in criminal \ndispute mediation. \n17 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  In the case where there are more than two parties and any party is not willing to \nengage in the dispute mediation, the dispute mediation may be conducted amongst parties that \nare willing to engage therein."}},{"id":"TH-H008-A46","no":46,"noLabel":{"en":"Article 46"},"heading":{"en":"The person with the power to manage affairs on behalf of the"},"text":{"en":"injured person under the Criminal Procedure Code shall have the power to manage affairs on \nbehalf of the injured person in relation to criminal dispute mediation under this Act, provided \nthat it shall not be contrary to or against the intention of the injured person."}},{"id":"TH-H008-A47","no":47,"noLabel":{"en":"Article 47"},"text":{"en":"In the case where the provisions of this Chapter do not provide any \nparticular proceeding in a criminal dispute mediation at the inquiry stage, the provisions of \nChapter II, Civil Dispute Mediation, and Chapter III, Criminal Dispute Mediation, shall apply to the \ncriminal dispute mediation at the inquiry stage mutatis mutandis . \nPART II \nMEDIATORS \n_______________"}},{"id":"TH-H008-A48","no":48,"noLabel":{"en":"Article 48"},"text":{"en":"A person who intends to be registered as a mediator in accordance \nwith the provisions of this Chapter shall submit an application to the Commissioner-General of \nthe Royal Thai Police, Permanent Secretary for Defence, Permanent Secretary for Interior, \nPermanent Secretary for Justice or the Attorney-General, as the case may be, as the Registrar, \nand the provisions of section 9 shall apply mutatis mutandis . \n  A mediator under paragraph one shall possess the qualifications and shall not be \nunder prohibitions under section 10."}},{"id":"TH-H008-A49","no":49,"noLabel":{"en":"Article 49"},"text":{"en":"The inquiry official shall cause to be held a meeting between \nparties for the selection and appointment of a mediator within seven days as from the date on \nwhich the inquiry official who is competent to issue orders issues an order for criminal dispute \nmediation. If the parties fail to agree on the selection of a mediator, the inquiry official shall \nselect and appoint a mediator and notify it to the mediator and the parties. \n  The selection and appointment of a mediator under paragraph one shall be in \naccordance with the rules, procedures and conditions in the Rule prescribed by the \n18 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nCommissioner-General of the Royal Thai Police, Permanent Secretary for Defence, Permanent \nSecretary for Interior or Permanent Secretary for Justice or the Regulation prescribed by the \nAttorney-General, as the case may be. \nPART III \nPROCEEDINGS FOR CRIMINAL DISPUTE MEDIATION AT THE INQUIRY STAGE \n_______________"}},{"id":"TH-H008-A50","no":50,"noLabel":{"en":"Article 50"},"text":{"en":"The inquiry official shall make the first appointment for criminal \ndispute mediation within seven days as from the date of the appointment of the mediator and \nnotify it to the mediator and the parties. \n  In the case of a cause of necessity preventing the action from being taken within \nthe period of time under paragraph one, the inquiry official may address to the inquiry official \nwho is competent to issue orders a request for an extension of the period of time for not more \nthan seven days."}},{"id":"TH-H008-A51","no":51,"noLabel":{"en":"Article 51"},"text":{"en":"The parties shall attend criminal dispute mediation in person and \nhave the right to allow not more than two trusted persons. \n  If the party who is the alleged offender is a minor, parents, a guardian, a \npsychologist or a social worker shall also attend criminal dispute mediation. \n  Criminal dispute mediation under this Chapter shall be conducted in camera."}},{"id":"TH-H008-A52","no":52,"noLabel":{"en":"Article 52"},"text":{"en":"In criminal dispute mediation, if an interpreter is necessary, the \ninquiry official shall provide an interpreter."}},{"id":"TH-H008-A53","no":53,"noLabel":{"en":"Article 53"},"text":{"en":"Before commencing criminal dispute mediation, the mediator shall \nexplain to the parties circumstances of the acts committed by the party who is the alleged \noffender as revealed in the complaint, other facts relating to the case, proceedings and legal \nconsequences of the criminal dispute mediation and the right to terminate the criminal dispute \nmediation. \n  For the purpose of criminal dispute mediation, the inquiry official shall give co-\noperation to the mediator in the interest of gaining knowledge of circumstances and other facts \nunder paragraph one. \n19 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H008-A54","no":54,"noLabel":{"en":"Article 54"},"text":{"en":"The mediator shall perform duties on the basis of integrity and \nimpartiality and shall assist and support the parties in conducting negotiations with a view to \nthe voluntary settlement of the case."}},{"id":"TH-H008-A55","no":55,"noLabel":{"en":"Article 55"},"text":{"en":"Criminal dispute mediation shall be completed within thirty days as \nfrom the date of the first appointment for the criminal dispute mediation except that, where \nthere exists a cause of necessity or it is the case in which there is a reasonable cause to believe \nthat the parties may reach agreement, the mediator may proceed with it for a further period \nnot exceeding thirty days, provided that such cause shall be noted down. \n  In the case where the mediator may be removed under section 15 or in the case \nwhere the status as a mediator terminates under section 17, the period of time under paragraph \none shall begin to run as from the date of the first appointment for criminal dispute mediation \nfollowing the appointment of a new mediator."}},{"id":"TH-H008-A56","no":56,"noLabel":{"en":"Article 56"},"text":{"en":"In the criminal dispute mediation, the parties have the right to enter \ninto negotiations with a view to reaching mutual agreement freely, provided that such \nagreement shall not be contrary to the law, impossible or contrary to public order or good \nmorals. \n  In the case where the injured person is a minor, the agreement under paragraph \none shall not be contrary to or against the intention of the minor as well."}},{"id":"TH-H008-A57","no":57,"noLabel":{"en":"Article 57"},"text":{"en":"When the parties have reached their agreement, the mediator shall \nprepare a memorandum of agreement or cause a memorandum of agreement to be prepared \nin writing, and the parties as well as the mediator shall sign it. Thereafter, the mediator shall \nfurnish the memorandum of agreement to the inquiry official. \n  The memorandum of agreement under paragraph one shall at least contain the \ndetails as follows: \n  (1) names and addresses of the parties; \n  (2) the alleged circumstances; \n  (3) the alleged offence and rate of penalty under the law;  \n  (4) willingness to engage in the criminal dispute mediation; \n20 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  (5) the fundamental substance of the agreement in consequence of the criminal \ndispute mediation, such as compensation of damage, conditions requiring the parties’ \ncompliance or forbearance and the period of time therefor or the agreement to waive \ncompensation for damage. \nPART IV \nTERMINATION OF CRIMINAL DISPUTE MEDIATION AT THE INQUIRY STAGE \n_______________"}},{"id":"TH-H008-A58","no":58,"noLabel":{"en":"Article 58"},"text":{"en":"Any party may, at any time, declare withdrawal in order that the \ncriminal dispute mediation shall terminate. \n  In the case where any party consists of several persons, the declaration of \nwithdrawal by any particular person or persons for terminating the criminal dispute mediation \nshall not prejudice the criminal dispute mediation of the remaining persons in both parties."}},{"id":"TH-H008-A59","no":59,"noLabel":{"en":"Article 59"},"text":{"en":"The mediator may terminate the criminal dispute mediation upon \nthe occurrence of any of the following facts: \n  (1) any party or both parties fail to attend the criminal dispute mediation without \ngiving notification or without any reasonable cause or, in the circumstances, fail to give co-\noperation in the criminal dispute mediation; \n  (2) there is a reasonable cause to believe that the agreement in question fails to \nbe concluded voluntarily; \n  (3) the criminal dispute mediation is certainly unable to achieve successful \nresults;  \n  (4) it is clear that further conduct of the criminal dispute mediation will be \ncontrary to the interest of the party who is a minor; \n  (5) the parties are unable to negotiate for reaching an agreement towards the \nresolution of the conflict or are unable to remedy the ensuing damage."}},{"id":"TH-H008-A60","no":60,"noLabel":{"en":"Article 60"},"text":{"en":"When it is apparent to the mediator that the injured person has \nfiled a criminal action before the Court, whether before the inquiry or during the inquiry, the \ncriminal dispute mediation shall terminate. \n21 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H008-A61","no":61,"noLabel":{"en":"Article 61"},"text":{"en":"The mediator shall report to the inquiry official the termination of \nthe criminal dispute mediation under section 58, section 59 and section 60 within seven days as \nfrom the date of the termination thereof. \n  Upon receipt of the report on the termination of the criminal dispute mediation, \nthe inquiry official who is competent to issue orders shall issue an order for taking further legal \nproceedings."}},{"id":"TH-H008-A62","no":62,"noLabel":{"en":"Article 62"},"text":{"en":"In the criminal dispute mediation under this Chapter, if it appears to \nthe mediator that the right to institute a criminal action is extinguished under the Criminal \nProcedure Code, the mediator shall terminate the criminal dispute mediation and report it to \nthe inquiry official for taking further action. \n  In the case of several offenders, if the right to institute a criminal action is \nextinguished only in respect of some offenders, the mediator shall proceed with the criminal \ndispute mediation in respect of remaining offenders."}},{"id":"TH-H008-A63","no":63,"noLabel":{"en":"Article 63"},"text":{"en":"In a case involving the commission of a single act violating several \nprovisions of law, if the offence under the provision of law carrying the heaviest punishment has \nreached a successful result of the criminal dispute medication under this Act, it shall be \ndeemed that the right to institute a criminal action in respect of other offences is also \nextinguished, but if the offence which has reached a successful result of the criminal dispute \nmedication is an offence carrying less or the least heavy punishment, it shall not have the \neffect of extinguishing the right to institute a criminal action in respect of offences carrying \nheavier or the heaviest punishment. \nPART V \nRESULTS OF CRIMINAL DISPUTE MEDIATION AT THE INQUIRY STAGE \n_______________"}},{"id":"TH-H008-A64","no":64,"noLabel":{"en":"Article 64"},"text":{"en":"When the party has undertaken the performance as required by the \nmemorandum of agreement under section 57, the party shall notify it to the inquiry official for \npreparing a memorandum of the agreed performance to be referred to the Public Prosecutor \ntogether with the briefs of the inquiry and relevant documents for considering the issuance of \nan order that the case be discontinued. \n22 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  In the case where the performance as required by the memorandum of \nagreement has been incompletely undertaken, the party shall notify it to the inquiry official for \nreferring the matter to the inquiry official who is competent to issue orders for considering the \nissuance of an order that legal proceedings be further continued except that, where the injured \nparty is satisfied with the performance previously undertaken as required by the agreement, the \nparty shall notify it to the inquiry official for taking action under paragraph one."}},{"id":"TH-H008-A65","no":65,"noLabel":{"en":"Article 65"},"text":{"en":"If it appears to the inquiry official that the party that is the alleged \noffender intentionally fails to perform the agreement without any reasonable cause, the inquiry \nofficial who is competent to issue orders shall issue an order that legal proceedings be further \ncontinued."}},{"id":"TH-H008-A66","no":66,"noLabel":{"en":"Article 66"},"heading":{"en":"When the Public Prosecutor issues an order that the case be"},"text":{"en":"discontinued, the right to institute a criminal action shall be extinguished. \n  In the case of several injured persons, if any injured person is unable to conclude \nan agreement with the alleged offender, such injured person’s right to institute a criminal action \nshall not be extinguished."}},{"id":"TH-H008-A67","no":67,"noLabel":{"en":"Article 67"},"text":{"en":"Criminal dispute mediation does not preclude the inquiry official’s \npower to conduct further inquiries. \nCHAPTER V \nPUBLIC SECTOR DISPUTE MEDIATION \n_______________"}},{"id":"TH-H008-A68","no":68,"noLabel":{"en":"Article 68"},"text":{"en":"The Rights and Liberties Protection Department of the Ministry of \nJustice shall promote and encourage public congregation into a public-sector dispute mediation \ncentre for carrying out affairs in connection with public sector dispute mediation. \n  A mediator of a public-sector dispute mediation centre shall possess the \nqualifications and shall not be under the prohibitions under section 10. \n  The Director-General of the Rights and Liberties Protection Department shall be \nthe Registrar of public-sector dispute mediation centres. \n23 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \n  The Rights and Liberties Protection Department shall have the duty and power \nto superintend dispute mediation of a public-sector dispute mediation centre to ensure \ncompliance with this Act."}},{"id":"TH-H008-A69","no":69,"noLabel":{"en":"Article 69"},"text":{"en":"Subject to section 20, dispute mediation by a public-sector dispute \nmediation centre is permissible in the following cases: \n  (1) a civil dispute of which the amount of claim does not exceed five hundred \nthousand Baht or does not exceed such amount as prescribed in the Royal Decree; \n  (2) such other civil disputes other than those in (1) as prescribed in the Royal Decree; \n  (3) criminal disputes under section 35. \n  In the case where the Rights and Liberties Protection Department considers that \nthe dispute mediation by a public-sector dispute mediation centre on any matter has been \nconducted in accordance with this Act and has issued a certificate to such effect, the dispute \nsettlement agreement in question shall be enforceable or the right to institute a criminal action \nshall be extinguished under this Act."}},{"id":"TH-H008-A70","no":70,"noLabel":{"en":"Article 70"},"text":{"en":"The Rights and Liberties Protection Department shall grant financial \nsupport for funding operational costs of public-sector dispute mediation centres in accordance \nwith the Rule prescribed by the Director-General of the Rights and Liberties Protection \nDepartment with the approval of the Ministry of Finance. \nCHAPTER VI \nPENALTIES \n_______________"}},{"id":"TH-H008-A71","no":71,"noLabel":{"en":"Article 71"},"heading":{"en":"Any mediator who unduly demands, accepts or agrees to accept"},"text":{"en":"property or any other benefit for himself or another person for the purpose of performing or \nrefraining from performing any act in the course of duty, whether such act is contrary to the \nperformance of the duty or not, shall be liable to imprisonment for a term not exceeding five \nyears or to a fine not exceeding one hundred thousand Baht or to both."}},{"id":"TH-H008-A72","no":72,"noLabel":{"en":"Article 72"},"text":{"en":"Any person who gives, offers to give or agrees to give property or \nany other benefit to a mediator for inducing the performance of any act or the omission or a \n24 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \ndelay in the performance of any act, which is contrary to the performance of the duty, shall be \nliable to imprisonment for a term not exceeding five years or to a fine not exceeding one \nhundred thousand Baht or to both. \n \n  Countersigned by: \n    General Prayut Chan-o-cha  \n Prime Minister \n25 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN TH E SOLE AUTHORITY HAVING LEGAL FORCE. \nSCHEDULE ANNEXED TO THE DISPUTE MEDIATION ACT, B.E. 2562 (2019) \n_______________ \n \n  Offences under the Penal Code as follows: \n  (1) an offence of participating in a chaotic affray causing death therefrom under \nsection 294 paragraph one; \n  (2) an offence of causing bodily harm under section 295; \n  (3) an offence of causing bodily harm with an aggravated factor under section \n296; \n  (4) an offence of participating in a chaotic affray causing a person to suffer serious \ninjury therefrom under section 299 paragraph one; \n  (5) an offence of negligently causing another person to suffer serious injury under \nsection 300; \n  (6) an offence of theft under section 334."}}],"pack":"th-p01"};
  FT["TH-H011"] = {"id":"TH-H011","coverage":"full","language":"en","sourceName":"泰国官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"LABOUR PROTECTION IN FISHING WORK ACT，B.E. 2562 (2019)","en":"LABOUR PROTECTION IN FISHING WORK ACT, B.E. 2562 (2019)","orig":null},"level":"law","status":"active","issuingBody":"泰国官方发布渠道","promulgatedDate":"2019","completenessNote":"自 2026-10-06 全库备份回流（_work/_backup_20261006/data/TH-H011.json）；条文逐字取自该备份，未改写、未补全；原始来源见 source 字段。","country":"TH","countryName":"泰国","layer":"intl","articles":[{"id":"TH-H011-A1","no":1,"noLabel":{"en":"Article 1"},"text":{"en":"This Act is called the “Labour Protection in Fishing Work Act, B.E. \n2562 (2019)”. \n                                                        \n  * Translated by Associate Professor Dr. Pinai Nanakorn under contract for the Office of the \nCouncil of State of Thailand's Law for ASEAN project. – Tentative Version – subject to final authorisation by \nthe Office of the Council of State.  \n2 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H011-A2","no":2,"noLabel":{"en":"Article 2"},"text":{"en":"1  This Act shall come into force after one hundred eighty days as from \nthe date of its publication in the Government Gazette."}},{"id":"TH-H011-A3","no":3,"noLabel":{"en":"Article 3"},"heading":{"en":"In this Act:"},"text":{"en":"“vessel owner” means an owner of a fishing vessel and shall also include a \nlessee of a fishing vessel but shall exclude an owner of a fishing vessel leased to another \nperson or used for engaging in a fishing business without the owner’s involvement; \n  “fishing labourer” means a fishing vessel skipper and a vessel worker under the \nlaw on fisheries but shall exclude an observer under the law on fisheries; \n  “fishing vessel” means a water vehicle of every size that is used or intended to \nbe used for the purpose of commercial fishing; \n  “engage in fishing” mean engaging in fishing under the law on fisheries; \n  “subsistence fishing” means the engaging in fishing with a view to using aquatic \nanimals for household consumption or for the direct supply to the community; \n  “fresh water fishing” means fresh water fishing under the law on fisheries; \n  “recreational fishing” means the engaging in fishing for recreation, a sportive \ncompetition or any other act as prescribed in the Notification of the Minister of the Agriculture \nand Co-operatives; \n  “outside Thai waters” means the high seas which are outside the exclusive \neconomic zone under the Notification of the Exclusive Economic Zone of the Kingdom of \nThailand or which are beyond continental shelves falling under sovereign rights of the Kingdom \nof Thailand under international law, whichever is further, and shall also include the seas which \nare in the zone of a Coastal State other than Thailand; \n  “contract of employment” means a contract of employment under the law on \nlabour protection; \n  “centre for controlling notification of vessel arrival and departure” means a \ncentre for controlling notification of vessel arrival and departure under the law on fisheries; \n                                                        \n  1 Published in Government Gazette, Vol. 136, Part 67a, dated 22 nd  May 2019. \n3 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  “competent official” means a person appointed by the Minister for performing \nactivities under this Act; \n  “Minister” means the Minister having charge and control of the execution of this \nAct."}},{"id":"TH-H011-A4","no":4,"noLabel":{"en":"Article 4"},"text":{"en":"The Minister of Agriculture and Co-operatives, Minister of Transport \nand Minister of Labour shall have charge and control of the execution of this Act and each \nMinister shall have the power to appoint competent officials for performing activities under this \nAct in respect of the official service of such Ministry. \nCHAPTER I \nGENERAL PROVISIONS  \n_______________"}},{"id":"TH-H011-A5","no":5,"noLabel":{"en":"Article 5"},"text":{"en":"This Act shall not apply to the engaging in fishing in the following cases: \n  (1) subsistence fishing; \n  (2) fresh water fishing; \n  (3) recreational fishing; \n  (4) the engaging in fishing involving such size of the vessel or such number of \nfishing labourers as prescribed in the Notification of the Minister of Agriculture and Co-\noperatives."}},{"id":"TH-H011-A6","no":6,"noLabel":{"en":"Article 6"},"text":{"en":"In addition to compliance with the rules provided in this Act, vessel \nowners and fishing labourers shall comply with minimum requirements as regards work, the \nperformance of duties, accommodation, food, the protection of safety and hygiene while at \nwork on board a fishing vessel and the provision of welfare at work as provided in the law on \nlabour protection, the law on job procurement and protection of job seekers, the law on \nnavigation in Thai waters, the law on foreigners’ working management, the law on fisheries, the \nlaw on compensation and the law on labour relations, unless specifically or otherwise provided \nby this Act. \n4 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  There shall be included in a contract of employment terms and conditions or \nother arrangements in relation to fishing labourers’ living and working conditions both on board \na vessel and on a quay. \n  For the purpose of the execution of the law under paragraph one, it shall be \ndeemed that a vessel owner is the employer and a fishing labourer is the employee. \n  An agency which is responsible for the law under paragraph one shall prepare a \nreport on the amount of cases and operation results to be submitted to the Ministry of Labour \nand the Ministry of Labour shall gather information and prepare a report on situations, the \namount of cases, operations of agencies concerned and directions for future operation in \nrelation to the protection of labour in fishing work in line with international standards for \nsubmission to the Council of Ministers, in accordance with periods of time prescribed by the \nMinister of Labour."}},{"id":"TH-H011-A7","no":7,"noLabel":{"en":"Article 7"},"text":{"en":"All cases which arise from disputes between vessel owners and fishing \nlabourers or heirs or between such persons and officials or State agencies and which are \nconcerned with rights or duties under this Act shall be under jurisdiction of the Labour Court. \nCHAPTER II \nFISHING LABOURERS PROTECTION  \n_______________"}},{"id":"TH-H011-A8","no":8,"noLabel":{"en":"Article 8"},"text":{"en":"Permission under the law on navigation in Thai waters, the law on \nforeigners’ working management and the law on fisheries, in respect of the working of fishing \nlabourers, may be granted only in the case where the applicant for permission has a medical \ncertificate indicating readiness, as regards health, for working on board a fishing vessel, including \nhearing and visual health as well."}},{"id":"TH-H011-A9","no":9,"noLabel":{"en":"Article 9"},"text":{"en":"On the occurrence of the following incidences outside Thai waters or \noverseas, a fishing labourer has the right to request for a return to the place where the vessel owner \nhas taken the fishing labourer into employment or the place agreed upon in the contract of \nemployment: \n5 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  (1) the duration of the contract of employment expires while the fishing labourer \nis working at a place other than the place for which the vessel owner has taken the fishing labourer \ninto employment and no agreement is made for extension of the contract of employment; \n  (2) the vessel owner or fishing labourer terminates the contract of employment \nbefore the expiration of the duration of the contract of employment or the vessel owner alters \nterms and conditions of the contract of employment without consent of the fishing labourer; \n  (3) the fishing labourer is so sick as to be unable to perform duties; \n  (4) the fishing labourer is taken into residence overseas on account of any cause \nwithout the fishing labourer’s fault. \n  Upon receipt of the request from the fishing labourer under paragraph one, the \nvessel owner shall expeditiously take action in repatriation of such fishing labourer to the place for \nwhich the vessel owner has taken the fishing labourer into employment or the place agreed upon \nin the contract of employment. During the time in which the repatriation is unable to be carried out \non account of any cause not attributable to the vessel owner, the vessel owner shall provide the \nfishing labourer with accommodation on board the vessel or suitable accommodation as well as \nsufficient food for the living, provided that the vessel owner shall bear all costs. \n  In the case where the fishing labourer makes a request for the exercise of the right \nunder (2), if the incidence in question results from the fishing labourer’s fault or the fishing labourer \nterminates the contract of employment without reasonable cause, the fishing labourer shall bear \ncosts incurred in the repatriation."}},{"id":"TH-H011-A10","no":10,"noLabel":{"en":"Article 10"},"text":{"en":"In the case where the vessel owner fails to comply with section 9, the \ncompetent official shall have the power to take action to effectuate the fishing labourer’s return to \nthe place under section 9 and the vessel owner shall reimburse the costs incurred therein to the \ncompetent official together with interest at the rate of fifteen percent per year as from the date of \npayment of the costs by the competent official up to the date of full reimbursement. \n  The issuance of a fishing licence under the law on fisheries or the granting of \nrenewal of a licence for the use of a vessel under the law on navigation in Thai waters, as the case \nmay be, shall be permissible only in the case where the vessel owner has made payment of costs \ntogether with interest under paragraph one. \n6 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H011-A11","no":11,"noLabel":{"en":"Article 11"},"text":{"en":"In the case where service fees and costs are chargeable in the \nprocurement of jobs for fishing labourers, the job procurer shall demand payment from the vessel \nowner and the vessel owner has the duty to pay such service fees and costs."}},{"id":"TH-H011-A12","no":12,"noLabel":{"en":"Article 12"},"text":{"en":"The vessel owner shall provide fishing labourers with such rights and \nbenefits as regards health and welfare as prescribed in the Notification of the Minister of Labour. In \nthis regard, this may be carried into effect through providing an insurance covering health and such \nwelfare or any other method prescribed in the Notification of the Minister of Labour."}},{"id":"TH-H011-A13","no":13,"noLabel":{"en":"Article 13"},"text":{"en":"A decked fishing vessel of three hundred gross tonnage upwards shall \nprovide accommodation on board the fishing vessel in accordance with the rules prescribed in the \nlaw on navigation in Thai waters."}},{"id":"TH-H011-A14","no":14,"noLabel":{"en":"Article 14"},"text":{"en":"The following fishing vessels shall have a certificate attesting the passing \nof the inspection of the living as well as working conditions in accordance with the rules prescribed \nin the Notification of the Director-General of the Marine Department: \n  (1) fishing vessels remaining at sea for more than three days and having the length \noverall of twenty-six point five metres upwards, taken as the distance in a straight line parallel \nto the designed waterline between the foremost point of the bow and the aftermost point of \nthe stern; or \n  (2) fishing vessels remaining at sea for more than three days and navigating \noutside Thai waters. \n  The rules under paragraph one shall at least prescribe a period of time not \nexceeding ten working days for the issuance of a certificate and a certificate’s period of validity not \nexceeding five years and may designate the Fisheries Department, the Department of Labour \nProtection and Welfare or a vessel inspecting institute prescribed in the Notification of the Minister \nof Transport under the law on navigation in Thai waters as the issuer of a certificate on behalf of the \nDirector-General. \n  In giving notification of a departure for fishing operations, the vessel owner shall, on \nevery occasion, notify the reference number of the certificate under paragraph one, and a centre \nfor controlling notification of vessel arrival and departure may grant permission to the vessel for \na departure for fishing operations when the certificate does not expire. \n7 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE."}},{"id":"TH-H011-A15","no":15,"noLabel":{"en":"Article 15"},"text":{"en":"In the case where a fishing labourer makes a complaint that the vessel \nowner fails to give the fishing labourer proper treatment under this Act, the vessel owner may not \nterminate the contract of employment or carry out any act giving rise to the fishing labourer’s \ninability to tolerate the continuance of work on account of such complaint or on account of giving \ntestimonies as a witness for the matter to which the complaint relates. \n \nCHAPTER III \nCOMPETENT OFFICIALS  \n_______________"}},{"id":"TH-H011-A16","no":16,"noLabel":{"en":"Article 16"},"text":{"en":"In the performance of duties under this Act, the competent official \nshall have the powers as follows: \n  (1) to get on board the fishing vessel or enter into the vessel owner’s place of \nbusiness for inspecting working conditions, employment conditions and living conditions, making \nfactual enquiries and gathering evidence beneficial to the examination or proof of facts, in the \ninterest of carrying out activities in the execution of this Act; \n  (2) to address written enquiries to the vessel owner, fishing labourers or persons \nconcerned or demand them to give explanation of facts or furnish documents or relevant evidence \nto assist the consideration of action to be pursued under this Act; \n  (3) to issue a written order demanding the vessel owner or fishing labourers to \nperform actions correctly in accordance with this Act; \n  (4) to issue a written order prohibiting the use of the vessel for fishing operations in \nthe case where the vessel is in the condition of unsafety or the vessel owner fails to comply with \nminimum requirements as regards work, the performance of duties, accommodation, food, the \nprotection of safety and health while at work on board the fishing vessel, or the provision of \nwelfare at work does not comply with this Act, until rectification is carried out to secure \ncompliance with this Act, provided that reasons shall clearly be indicated in the prohibition \norder.   \n  In the exercise of the power under (1), the competent official shall produce an \nidentification card to the vessel owner or persons concerned and the vessel owner or persons \n8 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \nconcerned shall not carry out any act or pursue omission which causes the competent official to be \nunable to perform duties. \n  Identification cards of competent officials shall be in accordance with the form \nprescribed in the Notification of the Minister of Labour. \n  The performance of activities under (1) and (4) shall be in accordance with the rules \nprescribed in the Notification of the Minister of Labour, which shall require integration of operations \nwith a view to reducing duplication of the exercise of powers of competent officials."}},{"id":"TH-H011-A17","no":17,"noLabel":{"en":"Article 17"},"text":{"en":"Upon receipt of a request or a complaint or upon the occurrence of \nconvincing evidence that a non-Thai fishing vessel has conditions on board the vessel which are \nseriously harmful to life, safety or health, the competent official shall have the power to get on \nboard the vessel and inspect such fishing vessel which enters the Kingdom and, in the case of \ninevitable necessity, the competent official may order the arrest of the vessel until rectification of \nsuch incidences is carried out. \nCHAPTER IV \nPENALTIES  \n_______________"}},{"id":"TH-H011-A18","no":18,"noLabel":{"en":"Article 18"},"text":{"en":"Any person who obstructs or fails to comply with an order of the \ncompetent official under section 16 paragraph one or fails to comply with or violates section 16 \nparagraph two shall be liable to imprisonment for a term not exceeding one year or to a fine of \ntwenty thousand to fifty thousand Baht or to both."}},{"id":"TH-H011-A19","no":19,"noLabel":{"en":"Article 19"},"text":{"en":"For offences under this Act, the Settlement Committee, if it considers \nthat the alleged offender should not be inflicted with imprisonment or should not be prosecuted, \nshall have the power to carry out the settlement in accordance with the rules prescribed in the \nNotification of the Minister of Labour. \n  The Settlement Committee under paragraph one shall consist of a representative of \nthe Office of the Attorney-General as Chairperson, a representative of the Royal Thai Police, as a \nmember and a representative of the Department of Labour Protection and Welfare, as a member \nand secretary. There may be Settlement Committees both in the area of Bangkok and in provincial \nareas as appropriately prescribed by the Minister of Labour. \n9 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  Upon payment by the alleged offender of a fine in the amount required by the \nsettlement within thirty days as from the date of the settlement, it shall be deemed that the case is \nextinguished under the Criminal Procedure Code."}},{"id":"TH-H011-A20","no":20,"noLabel":{"en":"Article 20"},"text":{"en":"In the case where the offender is a juristic person, if the commission \nof the offence by such juristic person has resulted from the instruction or an action of a director \nor a manager or any person responsible for the operation of such juristic person or in the case \nwhere such person has the duty to give instructions or take action and refrains from giving \ninstructions or taking action, thereby leading to the commission of the offence by such juristic \nperson, such person shall also be liable to the penalty as provided for such offence. \nTRANSITORY PROVISIONS \n_______________"}},{"id":"TH-H011-A21","no":21,"noLabel":{"en":"Article 21"},"text":{"en":"A medicate certificate issued to a fishing labourer prior to the date on \nwhich this Act comes into force may be held in lieu of a medical certificate under section 8 until \nthe expiry of such medicate certificate."}},{"id":"TH-H011-A22","no":22,"noLabel":{"en":"Article 22"},"text":{"en":"The provision of accommodation on board the fishing vessel under \nsection 13 shall not apply to a decked fishing vessel of three hundred gross tonnage upwards in \nexistence on the day prior to the date on which this Act comes into force unless there exists \nexpansion of the size of the vessel or accommodation or the tonnage for the carriage of aquatic \nanimals or aquatic animal products which is regarded as substantial modification of the vessel in \naccordance with the rules prescribed in the law on navigation in Thai waters subsequent to the date \non which this Act comes into force. \n  The provisions of paragraph one shall not apply to a non-Thai fishing vessel in \nrespect of which application has been made for registration as a Thai vessel under the law on Thai \nvessels subsequent to the date on which this Act comes into force except that it is a fishing vessel \npreviously registered as a Thai vessel and application has been made for cancellation of the \nregistration as a Thai vessel for the purpose of registration as a vessel of another Coastal State in \naccordance with the conditions for fishing operations as approved by such Coastal State. \n \n \n10 \n \n \nDISCLAIMER : THIS TEXT HAS BEEN PROVIDED FOR EDUCATIONAL/ COMPREHENSION PURPOSES AND CONTAINS \nNO LEGAL AUTHORITY. THE OFFICE OF THE COUNCIL OF STATE SHALL ASSUME NO RESPONSIBILITY FOR ANY \nLIABILITIES ARISING FROM THE USE AND/OR REFERENCE OF THIS TEXT. THE ORIGINAL THAI TEXT AS FORMALLY \nADOPTED AND PUBLISHED SHALL IN ALL EVENTS REMAIN THE SOLE AUTHORITY HAVING LEGAL FORCE. \n  Countersigned by: \n    General Prayut Chan-o-cha  \n       Prime Minister"}}],"pack":"th-p01"};
})(typeof window !== 'undefined' ? window : globalThis);
